        cin >> array[i];
    }

    for (int i = 0; i < SIZE - 1; i++) {
        for (int j = 0; j < SIZE - 1 - i; j++) {
            if (array[j] > array[j + 1]) {
                int temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }

    cout << "Sorted array: ";

    for (int i = 0; i < SIZE; i++) {
        cout << array[i] << " ";
    }

    return 0;
}

#include <iostream>

using namespace std;

bool isSorted(int *arr/*or arr[0] both are OK */, int n){

    //base case
    if(n==0 || n==1){
        return true;
    }
    else if(arr[0]>arr[1]){
        return false;
    }
    else{
        bool remainingPart=isSorted(arr+1,n-1);
        return remainingPart;
    }

}

int main()
{
    int arr[5]={2,4,6,8,9};
    bool ans=isSorted(arr,5);
    if(ans){
        cout<<"array is sorted"<<endl;
    }
    else
        cout<<"array is not sorted"<<endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int SIZE = 5;
    int array[SIZE];

    cout << "Enter 5 numbers: ";

    for (int i = 0; i < SIZE; i++) {
        cin >> array[i];
    }

    for (int i = 1; i < SIZE; i++) {
        int key = array[i];
        int j = i - 1;

        while (j >= 0 && array[j] > key) {
            array[j + 1] = array[j];
            j--;
        }

        array[j + 1] = key;
    }

    cout << "Sorted array: ";

    for (int i = 0; i < SIZE; i++) {
        cout << array[i] << " ";
    }

    return 0;
}

#include <iostream>

using namespace std;

void sort(int *arr,int n){

    int i =0;
    while(i<n){
        int correct = arr[i]-1;
        if(arr[i] != arr[correct])
            swap(arr[i],arr[correct]);
        else
            i++;
    }

}

int main()
{
    int arr[5] = {3,5,2,1,4};
    sort(arr,5);

    for(int i=0;i<5;i++){
        cout<<arr[i]<<" ";
    }cout<<endl;
    return 0;
}

