void printArray(int arr[],int n){

        for(int i=0;i<n;i++){
            cout<<arr[i]<<" ";
        }
        cout<<endl;

}

int findUnique(int arr[], int size){

        int ans=0;
        for(int i=0;i<size;i++){
            ans=ans^arr[i];
        }
        return ans;

}

