#include <iostream>
#include <bits/stdc++.h>

using namespace std;

class graph{

public:
    unordered_map<int, list<int>> adj;

    void addEdge(int u, int v, bool direction){
        //direction = 0 -> undirected;
        //direction = 1 -> directed Graph;

        //create ans edge from u and v
        adj[u].push_back(v);

        if(direction == 0){
            adj[v].push_back(u);
        }
    }

    void printAdjList(){
        for(auto i:adj){
            cout<<i.first<<"->";
            for(auto j:i.second){
                cout<<j<<",";
            }
            cout<<endl;
        }
    }

};

int main()
{
    int n;
    cout<<"Enter the Number of Nodes "<<endl;
    cin>>n;

    int m;
    cout<<"Enter the Number of Edges"<<endl;
    cin>>m;

    graph g;

    for(int i=0;i<m;i++){
        int u,v;
        cin>>u>>v;
        //creating undirected graph
        g.addEdge(u,v,0);
    }
    //printing graph
    g.printAdjList();

    return 0;
}

