    }


    return 0;
}

#include <iostream>
using namespace std;

class MaxHeap {
private:
    int heap[100];
    int size;

public:
    MaxHeap() {
        size = 0;
    }

    void insert(int value) {
        heap[size] = value;
        int index = size;
        size++;

        while (index > 0) {
            int parent = (index - 1) / 2;

            if (heap[parent] < heap[index]) {
                int temp = heap[parent];
                heap[parent] = heap[index];
                heap[index] = temp;
                index = parent;
            } else {
                break;
            }
        }
    }

    void removeRoot() {
        if (size == 0)
            return;

        heap[0] = heap[size - 1];
        size--;

        int index = 0;

        while (true) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int largest = index;

            if (left < size && heap[left] > heap[largest])
                largest = left;

            if (right < size && heap[right] > heap[largest])
                largest = right;

            if (largest != index) {
                int temp = heap[index];
                heap[index] = heap[largest];
                heap[largest] = temp;
                index = largest;
            } else {
                break;
            }
        }
    }

    void printHeap() {
        for (int i = 0; i < size; i++) {
            cout << heap[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    MaxHeap h;

    h.insert(50);
    h.insert(30);
    h.insert(40);
    h.insert(10);
    h.insert(60);

    cout << "Heap: ";
    h.printHeap();

    h.removeRoot();

    cout << "After delete root: ";
    h.printHeap();

    return 0;
}

