    cout << "Sorted array: ";

    for (int i = 0; i < SIZE; i++) {
        cout << array[i] << " ";
    }

    return 0;
}

#include <iostream>

using namespace std;

void merge(int arr1[],int n,int arr2[],int m,int arr3[]){

        int i=0,j=0,k=0;
        while(i<n && j<m){
            if(arr1[i]<arr2[j]){
                arr3[k]=arr1[i];
                k++;
                i++;
            }
            else{
                arr3[k]=arr2[j];
                k++;
                j++;
            }
        }

        //copy first array k element
        while(i<n){
            arr3[k]=arr1[i];
            k++;
            i++;
        }

        //copy 2nd array k element
        while(j<m){
            arr3[k]=arr2[j];
            k++;
            j++;
        }
}

