#include <iostream>

using namespace std;

int partition(int arr[], int s, int e){

    int pivot=arr[s];
    int cnt=0;

    for(int i=s+1;i<=e;i++){
        if(arr[i]<=pivot){
            cnt++;
        }
    }
    //place pivot at right position
    int pivotIndex=s+cnt;
    swap(arr[pivotIndex], arr[s]);

    //left and right wala part sambhal lete hai
    int i=s,j=e;
    while(i<pivotIndex && j>pivotIndex){
        while(arr[i]<pivot){
            i++;
        }
        while(arr[j]>pivot){
            j--;
        }
        if(i<pivotIndex && j>pivotIndex){
            swap(arr[i++],arr[j--]);
        }
    }
    return pivotIndex;


}

void quickSort(int arr[], int s, int e){

    //base caase
    if(s>=e)
        return;

    //partition of an array
    int p=partition(arr,s,e);

    //recursion
    quickSort(arr,s,p-1);
    quickSort(arr,p+1,e);

}

int main()
{
    int arr[5]={2,4,1,6,9};
    int n=5;

    quickSort(arr,0,n-1);

    for(int i=0;i<n;i++){
        cout<<arr[i]<<" ";
    }cout<<endl;
    return 0;
}

#include <iostream>
using namespace std;

void quickSort(int array[], int left, int right) {
    int i = left;
    int j = right;
    int pivot = array[(left + right) / 2];

    while (i <= j) {
        while (array[i] < pivot)
            i++;

        while (array[j] > pivot)
            j--;

        if (i <= j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
            i++;
            j--;
        }
    }

    if (left < j)
        quickSort(array, left, j);

    if (i < right)
        quickSort(array, i, right);
}

int main() {
    const int SIZE = 6;
    int array[SIZE];

    cout << "Enter 6 numbers: ";

    for (int i = 0; i < SIZE; i++) {
        cin >> array[i];
    }

    quickSort(array, 0, SIZE - 1);

    cout << "Sorted array: ";

    for (int i = 0; i < SIZE; i++) {
        cout << array[i] << " ";
    }

    return 0;
}

#include <iostream>

using namespace std;


void reverse(int arr[],int n){

    int start=0;
    int end=n-1;
    while(start<=end){
        swap(arr[start],arr[end]);
        start++;
        end--;
    }

}


void printArray(int arr[],int n){

    for(int i=0;i<n;i++){
        cout<<arr[i]<<" ";
    }
    cout<<endl;
}


int main()
{
    int arr[6]={2,4,5,9,7,3};
    int brr[5]={4,2,9,5,7};

    reverse(arr,6);
    reverse(brr,5);

    printArray(arr,6);
    printArray(brr,5);

    return 0;
}

