#include <iostream>

using namespace std;

class TrieNode{

public:
    char data;
    TrieNode* children[26];
    bool isTerminal;

    TrieNode(char ch){
        data = ch;
        for(int i=0;i<26;i++){
            children[i] = NULL;
        }
        isTerminal = false;
    }
};

class Trie{

public:
    TrieNode* root;

    Trie(){
        root = new TrieNode('\0');
    }

    void insertUtil(TrieNode* root, string word){
        // base case
        if(word.length() == 0){
            root->isTerminal = true;
            return;
        }

        //assumption: word will be in CAPS;
        int index = word[0] - 'A';
        TrieNode* child;

        //present
        if(root->children[index] != NULL){
            child = root->children[index];
        }
        else{
            //absent
            child  = new TrieNode(word[0]);
            root->children[index] = child;
        }

        //Recursion
        insertUtil(child, word.substr(1));

    }

    void InsertWord(string word){
        insertUtil(root,word);
    }

    bool searchUtil(TrieNode* root, string word){
        //base case
        if(word.length() == 0){
            return root->isTerminal;
        }

        int index = word[0] - 'A';
        TrieNode* child;

        //present
        if(root->children[index] != NULL){
            child = root->children[index];
        }
        else{
            //absent
            return false;
        }

        return searchUtil(child, word.substr(1));

    }

    bool searchWord(string word){
        return searchUtil(root, word);
    }

};

int main()
{
    Trie* t = new Trie();

    t->InsertWord("abcd");

    cout<<"word present or not: "<<t->searchWord("abcd")<<endl;

    return 0;
}

#include <iostream>
using namespace std;

struct TrieNode {
    TrieNode* children[26];
    bool isEnd;

    TrieNode() {
        isEnd = false;
        for (int i = 0; i < 26; i++) {
            children[i] = NULL;
        }
    }
};

void insert(TrieNode* root, string word) {
    TrieNode* current = root;

    for (int i = 0; i < word.length(); i++) {
        int index = word[i] - 'a';

        if (current->children[index] == NULL) {
            current->children[index] = new TrieNode();
        }

        current = current->children[index];
    }

    current->isEnd = true;
}

bool search(TrieNode* root, string word) {
    TrieNode* current = root;

    for (int i = 0; i < word.length(); i++) {
        int index = word[i] - 'a';

        if (current->children[index] == NULL) {
            return false;
        }

        current = current->children[index];
    }

    return current->isEnd;
}

int main() {
    TrieNode* root = new TrieNode();

    insert(root, "cat");
    insert(root, "car");
    insert(root, "dog");

    cout << search(root, "car") << endl;
    cout << search(root, "cow") << endl;

    return 0;
}

#include <iostream>

using namespace std;

bool binarySearch(int *arr, int s, int e, int k){
    if(s>e)
        return false;
    int mid=s+(e-s)/2;
    if(arr[mid] == k)
        return true;
    if(arr[mid]<k)
        return binarySearch(arr,mid+1,e,k);
    else
        return binarySearch(arr,s,mid-1,k);
}

int main()
{
    int arr[5]={2,4,6,8,10};
    bool ans=binarySearch(arr,0,4,8);
    if(ans)
        cout<<"Element found: "<<endl;
    else
        cout<<"Element not found: "<<endl;
    return 0;
}

#include <iostream>
using namespace std;

int binarySearch(int array[], int left, int right, int target) {
    if (left > right)
        return -1;

    int mid = (left + right) / 2;

    if (array[mid] == target)
        return mid;

    if (target < array[mid])
        return binarySearch(array, left, mid - 1, target);

    return binarySearch(array, mid + 1, right, target);
}

int main() {
    const int SIZE = 6;
    int array[SIZE] = {2, 4, 6, 8, 10, 12};

    int target;
    cout << "Enter number to search: ";
    cin >> target;

    int result = binarySearch(array, 0, SIZE - 1, target);

    if (result != -1)
        cout << "Found at index: " << result;
    else
        cout << "Not found";

    return 0;
}

#include <iostream>

using namespace std;

int binarySearch(int arr[],int n,int key){

    int start=0;
    int end=n-1;
    int mid=start+(end-start)/2;                    //int mid=(start+end)/2;
    while(start<=end){
        if(arr[mid]==key){
            return mid;
        }
        if(key>arr[mid]){
            start=mid+1;
        }
        else{
            end=mid-1;
        }
        mid=start+(end-start)/2;
    }
    return -1;
}

int main()
{
    int arr[7]={2,4,7,9,13,15,19};
    for(int i=0;i<7;i++){
        cout<<arr[i]<<" ";
    }cout<<endl;
    int key;
    cout<<"Enter the value to find in array: "<<endl;
    cin>>key;
    int index=binarySearch(arr,7,key);

    if(index==-1){
        cout<<"Element not found in given array"<<endl;
    }
    else{
        cout<<"Element found at index: "<<index<<endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

bool isPossible(int pages[], int size, int students, int limit) {
    int count = 1;
    int sum = 0;

    for (int i = 0; i < size; i++) {
        if (pages[i] > limit)
            return false;

        if (sum + pages[i] <= limit) {
            sum += pages[i];
        } else {
            count++;
            sum = pages[i];

            if (count > students)
                return false;
        }
    }

    return true;
}

int main() {
    int pages[4] = {10, 20, 30, 40};
    int size = 4;
    int students = 2;

    int start = 0;
    int end = 100;
    int answer = -1;

    while (start <= end) {
        int mid = (start + end) / 2;

        if (isPossible(pages, size, students, mid)) {
            answer = mid;
            end = mid - 1;
        } else {
            start = mid + 1;
        }
    }

    cout << "Minimum pages: " << answer;

    return 0;
}

