int main() {
    const int SIZE = 5;
    int array[SIZE];

    cout << "Enter 5 numbers: ";

    for (int i = 0; i < SIZE; i++) {
        cin >> array[i];
    }

    for (int i = 1; i < SIZE; i++) {
        int key = array[i];
        int j = i - 1;

        while (j >= 0 && array[j] > key) {
            array[j + 1] = array[j];
            j--;
        }

        array[j + 1] = key;
    }

    cout << "Sorted array: ";

    for (int i = 0; i < SIZE; i++) {
        cout << array[i] << " ";
    }

    return 0;
}

