int getMin(int num[], int n){

        int min=INT_MAX;
        for(int i=0;i<n;i++){
            //mini=min(mini,num[i}) also possible
            if(num[i]<min){
                min=num[i];
            }
        }
        //returning the value of min
        return min;
}

int getMax(int num[], int n){

        int max=INT_MIN;

        for(int i=0;i<n;i++){
            //maxi=max(maxi,num[i}) also possible
            if(num[i]>max){
                max=num[i];
            }
        }
        //returning the value of max
        return max;
}


