    cout << "Результат: ";
    for (int num : nums) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>

using namespace std;

int factorial(int n){

    int fact=1;
    for(int i=1;i<=n;i++){
        fact=fact*i;
    }
    return fact;
}

int nCr(int n, int r){

    int numerator = factorial(n);
    int denominator = factorial(r)*factorial(n-r);
    return numerator/denominator;

}


int main()
{
    int n,r;
    cout<<"enter any two number: "<<endl;
    cin>>n>>r;
    int answer=nCr(n,r);
    cout<<"your answer for nCr is: "<<answer<<endl;
    return 0;
}

#include <iostream>
using namespace std;

long long binomialCoefficient(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;

    // Используем симметрию C(n, k) = C(n, n-k)
    if (k > n - k) k = n - k;

    long long result = 1;
    for (int i = 1; i <= k; i++) {
        result = result * (n - k + i) / i;
    }

    return result;
}

#include <vector>

long long binomialDP(int n, int k) {
    if (k < 0 || k > n) return 0;

    vector<vector<long long>> C(n + 1, vector<long long>(k + 1, 0));

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= min(i, k); j++) {
            if (j == 0 || j == i) {
                C[i][j] = 1;
            } else {
                C[i][j] = C[i-1][j-1] + C[i-1][j];
            }
        }
    }

    return C[n][k];
}

#include <iostream>
#include <vector>
#include <iomanip>

using namespace std;

// Основная функция (оптимальная)
long long C(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;

    if (k > n - k) k = n - k;

    long long result = 1;
    for (int i = 1; i <= k; i++) {
        result = result * (n - k + i) / i;
    }

    return result;
}

// Функция для вывода треугольника Паскаля
void printPascalTriangle(int rows) {
    cout << "Треугольник Паскаля (первые " << rows << " строк):\n";
    for (int n = 0; n < rows; n++) {
        cout << string((rows - n) * 2, ' ');
        for (int k = 0; k <= n; k++) {
            cout << setw(4) << C(n, k) << " ";
        }
        cout << endl;
    }
}

int main() {
    // Примеры вычислений
    cout << "Биномиальные коэффициенты:\n";
    cout << "C(5, 2) = " << C(5, 2) << " (ожидается 10)\n";
    cout << "C(10, 3) = " << C(10, 3) << " (ожидается 120)\n";
    cout << "C(7, 0) = " << C(7, 0) << " (ожидается 1)\n";
    cout << "C(7, 7) = " << C(7, 7) << " (ожидается 1)\n";
    cout << "C(10, 5) = " << C(10, 5) << " (ожидается 252)\n\n";

    // Проверка симметрии
    cout << "Проверка симметрии C(10, 3) = C(10, 7): ";
    cout << C(10, 3) << " = " << C(10, 7) << endl << endl;

    // Треугольник Паскаля
    printPascalTriangle(8);

    // Формула бинома Ньютона
    cout << "\nФормула бинома Ньютона (a+b)^4:\n";
    cout << "a^4 + ";
    for (int k = 1; k < 4; k++) {
        cout << C(4, k) << "a^" << (4-k) << "b^" << k << " + ";
    }
    cout << "b^4" << endl;

    return 0;
}

