#include <iostream>

using namespace std;

int pivotElement(int arr[],int n){

    int s=0;
    int e=n-1;

    int mid=s+(e-s)/2;

    while(s<e){
        if(arr[mid]>=arr[0]){
            s=mid+1;
        }
        else{
            e=mid;
        }mid=s+(e-s)/2;
    }return e;

}


int main()
{
    int arr[5]={7,9,1,2,3};
    int ans=pivotElement(arr,5);
    cout<<"pivot element is at index: "<<ans<<endl;


    return 0;
}

#include <iostream>
using namespace std;

int pivotIndex(int arr[], int n) {
    int total = 0;

    for (int i = 0; i < n; i++) {
        total += arr[i];
    }

    int leftSum = 0;

    for (int i = 0; i < n; i++) {
        int rightSum = total - leftSum - arr[i];

        if (leftSum == rightSum) {
            return i;
        }

        leftSum += arr[i];
    }

    return -1;
}

int main() {
    int arr[] = {1, 7, 3, 6, 5, 6};
    int n = 6;

    cout << "Pivot index: " << pivotIndex(arr, n) << endl;

    return 0;
}

