#include <iostream>
using namespace std;

#define SIZE 5

class Queue {
private:
    int arr[SIZE];
    int front;
    int rear;

public:
    Queue() {
        front = -1;
        rear = -1;
    }

    void enqueue(int value) {
        if (rear == SIZE - 1) {
            cout << "Очередь переполнена\n";
            return;
        }

        if (front == -1)
            front = 0;

        arr[++rear] = value;
    }

    void dequeue() {
        if (front == -1 || front > rear) {
            cout << "Очередь пуста\n";
            return;
        }

        cout << "Удалено: " << arr[front] << endl;
        front++;
    }

    void display() {
        if (front == -1 || front > rear) {
            cout << "Очередь пуста\n";
            return;
        }

        for (int i = front; i <= rear; i++) {
            cout << arr[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    Queue q;

    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);

    q.display();

    q.dequeue();
    q.display();

    return 0;
}

#include <iostream>
#include <stack>
