    for (char c : str) {
        s.push(c);
    }

    // достаём обратно (в обратном порядке)
    string reversed = "";
    while (!s.empty()) {
        reversed += s.top();
        s.pop();
    }

    cout << "Reversed: " << reversed << endl;

    return 0;
}

