#include <iostream>

using namespace std;

int sqrt(int n){

    int s=0;
    int e=n;
    int mid=s+(e-s)/2;
    int ans=0;
    while(s<=e){
        int square=mid*mid;
        if(square==mid){
            return mid;
        }
        else if(square<=n){
            ans=mid;
            s=mid+1;
        }
        else{
            e=mid-1;
        }
        mid=s+(e-s)/2;

    }return ans;
}


int main()
{
    cout<<sqrt(16)<<endl;;
    return 0;
}

#include <iostream>
using namespace std;

int search(int arr[], int n, int target) {
    int left = 0, right = n - 1;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (arr[mid] == target)
            return mid;

        // левая часть отсортирована
        if (arr[left] <= arr[mid]) {
            if (target >= arr[left] && target < arr[mid])
                right = mid - 1;
            else
                left = mid + 1;
        }
        // правая часть отсортирована
        else {
            if (target > arr[mid] && target <= arr[right])
                left = mid + 1;
            else
                right = mid - 1;
        }
    }

    return -1; // не найден
}

int main() {
    int arr[] = {4, 5, 6, 7, 0, 1, 2};
    int n = 7;
    int target = 0;

    cout << "Index: " << search(arr, n, target) << endl;

    return 0;
}

