    assert(bit_manipulation::count_bits_flip::countBitsFlip(11, 8) == 2);
    assert(bit_manipulation::count_bits_flip::countBitsFlip(21, 22) == 2);
    assert(bit_manipulation::count_bits_flip::countBitsFlip(7, 786) == 5);
