#include <bitset>
#include <cassert>
#include <iostream>
#include <vector>

using namespace std;

namespace bit_manipulation {
namespace gray_code {

vector<bitset<32>> gray_code_generation(int n) {
    vector<bitset<32>> gray_code = {};

    if (n <= 0) {
        return gray_code;
    }

    int total_codes = 1 << n;

    for (int i = 0; i < total_codes; i++) {
        int gray_num = i ^ (i >> 1);
        gray_code.push_back(bitset<32>(gray_num));
    }

    return gray_code;
}
}
}

static void test() { 
    vector<bitset<32>> gray_code_negative_1 = {};

    vector<bitset<32>> gray_code_0 = {};

    vector<bitset<32>> gray_code_1 = {
        bitset<32>(0), bitset<32>(1)
    };

    vector<bitset<32>> gray_code_2 = {
        bitset<32>(0), bitset<32>(1), bitset<32>(3), bitset<32>(2)
    };

    vector<bitset<32>> gray_code_3 = {
        bitset<32>(0), bitset<32>(1), bitset<32>(3), bitset<32>(2),
        bitset<32>(6), bitset<32>(7), bitset<32>(5), bitset<32>(4)
    };

    vector<bitset<32>> gray_code_4 = {
        bitset<32>(0), bitset<32>(1), bitset<32>(3), bitset<32>(2),
        bitset<32>(6), bitset<32>(7), bitset<32>(5), bitset<32>(4),
        bitset<32>(12), bitset<32>(13), bitset<32>(15), bitset<32>(14),
        bitset<32>(10), bitset<32>(11), bitset<32>(9), bitset<32>(8)
    };

    vector<bitset<32>> gray_code_5 = {
        bitset<32>(0), bitset<32>(1), bitset<32>(3), bitset<32>(2),
        bitset<32>(6), bitset<32>(7), bitset<32>(5), bitset<32>(4),
        bitset<32>(12), bitset<32>(13), bitset<32>(15), bitset<32>(14),
        bitset<32>(10), bitset<32>(11), bitset<32>(9), bitset<32>(8),
        bitset<32>(24), bitset<32>(25), bitset<32>(27), bitset<32>(26),
        bitset<32>(30), bitset<32>(31), bitset<32>(29), bitset<32>(28),
        bitset<32>(20), bitset<32>(21), bitset<32>(23), bitset<32>(22),
        bitset<32>(18), bitset<32>(19), bitset<32>(17), bitset<32>(16)
    };

    assert(bit_manipulation::gray_code::gray_code_generation(-1) == gray_code_negative_1);
    assert(bit_manipulation::gray_code::gray_code_generation(0) == gray_code_0);
    assert(bit_manipulation::gray_code::gray_code_generation(1) == gray_code_1);
    assert(bit_manipulation::gray_code::gray_code_generation(2) == gray_code_2);
    assert(bit_manipulation::gray_code::gray_code_generation(3) == gray_code_3);
    assert(bit_manipulation::gray_code::gray_code_generation(4) == gray_code_4);
    assert(bit_manipulation::gray_code::gray_code_generation(5) == gray_code_5);
}

int main() {
    test();
    return 0;
}

