#include <iostream>
#include <vector>
using namespace std;

vector<string> grayCode(int n) {
    if (n == 1)
        return {"0", "1"};

    vector<string> prev = grayCode(n - 1);
    vector<string> result;

    // добавляем 0
    for (string s : prev)
        result.push_back("0" + s);

    // добавляем 1 в обратном порядке
    for (int i = prev.size() - 1; i >= 0; i--)
        result.push_back("1" + prev[i]);

    return result;
}

int main() {
    vector<string> res = grayCode(3);

    for (string s : res)
        cout << s << endl;
}

#include <cassert>
#include <cstdint>
#include <iostream>

using namespace std;

namespace bit_manipulation {
namespace hamming_distance {

uint64_t bitCount(uint64_t value) {
    uint64_t count = 0;
    while (value) {
        if (value & 1) {
            count++;
        }
        value >>= 1;
    }
    return count;
}

uint64_t hamming_distance(uint64_t a, uint64_t b) {
    return bitCount(a ^ b);
}

uint64_t hamming_distance(const string& a, const string& b) {
    assert(a.size() == b.size());
    size_t n = a.size();
    uint64_t count = 0;
    for (size_t i = 0; i < n; i++) {
        count += (b[i] != a[i]);
    }
    return count;
}
}
}

static void test() {
    assert(bit_manipulation::hamming_distance::hamming_distance(11, 2) == 2);
    assert(bit_manipulation::hamming_distance::hamming_distance(2, 0) == 1);
    assert(bit_manipulation::hamming_distance::hamming_distance(11, 0) == 3);

    assert(bit_manipulation::hamming_distance::hamming_distance("1101", "1111") == 1);
    assert(bit_manipulation::hamming_distance::hamming_distance("1111", "1111") == 0);
    assert(bit_manipulation::hamming_distance::hamming_distance("0000", "1111") == 4);

    assert(bit_manipulation::hamming_distance::hamming_distance("alpha", "alphb") == 1);
    assert(bit_manipulation::hamming_distance::hamming_distance("abcd", "abcd") == 0);
    assert(bit_manipulation::hamming_distance::hamming_distance("dcba", "abcd") == 4);
}

int main() {
    test();
    uint64_t a = 11;
    uint64_t b = 2;

    cout << "Hamming distance between " << a << " and " << b << " is "
         << bit_manipulation::hamming_distance::hamming_distance(a, b)
         << endl;
}

#include <iostream>
using namespace std;

int hammingDistance(int x, int y) {
    int xorVal = x ^ y;
    int count = 0;

    while (xorVal) {
        xorVal = xorVal & (xorVal - 1); // удаляем 1 бит
        count++;
    }

    return count;
}

int main() {
    int x = 1, y = 4;
    cout << hammingDistance(x, y) << endl;
}

int hammingDistance(int x, int y) {
    int xorVal = x ^ y;
    int count = 0;

    while (xorVal > 0) {
        if (xorVal & 1)
            count++;
        xorVal >>= 1;
    }

    return count;
}

#include <cassert>
#include <cstdint>
#include <iostream>

using namespace std;

namespace bit_manipulation {

uint64_t next_higher_number(uint64_t x) {
    uint64_t rightOne = 0;
    uint64_t nextHigherOneBit = 0;
    uint64_t rightOnesPattern = 0;
    uint64_t next = 0;

    if (x) {
        rightOne = x & -static_cast<signed>(x);
        nextHigherOneBit = x + rightOne;
        rightOnesPattern = x ^ nextHigherOneBit;
        rightOnesPattern = (rightOnesPattern) / rightOne;
        rightOnesPattern >>= 2;
        next = nextHigherOneBit | rightOnesPattern;
    }

    return next;
}

}

static void test() {
    assert(bit_manipulation::next_higher_number(4) == 8);
    assert(bit_manipulation::next_higher_number(6) == 9);
    assert(bit_manipulation::next_higher_number(13) == 14);
    assert(bit_manipulation::next_higher_number(64) == 128);
    assert(bit_manipulation::next_higher_number(15) == 23);
    assert(bit_manipulation::next_higher_number(32) == 64);
    assert(bit_manipulation::next_higher_number(97) == 98);
    assert(bit_manipulation::next_higher_number(1024) == 2048);

    cout << "All test cases have successfully passed!" << endl;
}

int main() {
    test();
    return 0;
}

#include <iostream>
using namespace std;

int nextHigher(int n) {
    int c = n;
    int c0 = 0, c1 = 0;

    // считаем нули справа
    while (((c & 1) == 0) && (c != 0)) {
        c0++;
        c >>= 1;
    }

    // считаем единицы после них
    while ((c & 1) == 1) {
        c1++;
        c >>= 1;
    }

    // если невозможно
    if (c0 + c1 == 31 || c0 + c1 == 0)
        return -1;

    int p = c0 + c1; // позиция

    // ставим 1
    n |= (1 << p);

    // обнуляем справа
    n &= ~((1 << p) - 1);

    // добавляем (c1-1) единиц справа
    n |= (1 << (c1 - 1)) - 1;

    return n;
}

int main() {
    int n = 6;
    cout << nextHigher(n) << endl;
}

