#include <algorithm>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <limits>
#include <vector>

using namespace std;

namespace bit_manipulation {
namespace travelling_salesman_using_bit_manipulation {

uint64_t travelling_salesman_using_bit_manipulation(
    vector<vector<uint32_t>> dist,
    uint64_t setOfCities,
    uint64_t city,
    uint64_t n,
    vector<vector<uint32_t>> &dp)
{
    if (setOfCities == (1 << n) - 1) {
        return dist[city][0];
    }

    if (dp[setOfCities][city] != -1) {
        return dp[setOfCities][city];
    }

    uint64_t ans = 2147483647;
    for (int choice = 0; choice < n; choice++) {
        if ((setOfCities & (1 << choice)) == 0) {
            uint64_t subProb =
                dist[city][choice] +
                travelling_salesman_using_bit_manipulation(
                    dist, setOfCities | (1 << choice), choice, n, dp);
            ans = min(ans, subProb);
        }
    }
    dp[setOfCities][city] = ans;
    return ans;
}
}
}

static void test() {
    vector<vector<uint32_t>> dist = {
        {0, 20, 42, 35}, {20, 0, 30, 34}, {42, 30, 0, 12}, {35, 34, 12, 0}};
    uint32_t V = dist.size();
    vector<vector<uint32_t>> dp(1 << V, vector<uint32_t>(V, -1));
    assert(bit_manipulation::travelling_salesman_using_bit_manipulation::
               travelling_salesman_using_bit_manipulation(dist, 1, 0, V, dp) ==
           97);
    cout << "1st test-case: passed!" << "\n";

    dist = {{0, 5, 10, 15}, {5, 0, 20, 30}, {10, 20, 0, 35}, {15, 30, 35, 0}};
    V = dist.size();
    vector<vector<uint32_t>> dp1(1 << V, vector<uint32_t>(V, -1));
    assert(bit_manipulation::travelling_salesman_using_bit_manipulation::
               travelling_salesman_using_bit_manipulation(dist, 1, 0, V, dp1) ==
           75);
    cout << "2nd test-case: passed!" << "\n";

    dist = {{0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
    V = dist.size();
    vector<vector<uint32_t>> dp2(1 << V, vector<uint32_t>(V, -1));
    assert(bit_manipulation::travelling_salesman_using_bit_manipulation::
               travelling_salesman_using_bit_manipulation(dist, 1, 0, V, dp2) ==
           80);

    cout << "3rd test-case: passed!" << "\n";
}

int main() {
    test();
    return 0;
}

#include <iostream>
#include <vector>
#include <climits>
using namespace std;

int n = 4;

int dist[4][4] = {
    {0, 10, 15, 20},
    {10, 0, 35, 25},
    {15, 35, 0, 30},
    {20, 25, 30, 0}
};

int dp[1 << 4][4];

// TSP с битмаской
int tsp(int mask, int pos) {

    // если все города посещены → возвращаемся в старт
    if (mask == (1 << n) - 1)
        return dist[pos][0];

    // если уже считали
    if (dp[mask][pos] != -1)
        return dp[mask][pos];

    int ans = INT_MAX;

    // пробуем идти в следующий город
    for (int city = 0; city < n; city++) {

        // если не посещён
        if ((mask & (1 << city)) == 0) {

            int newAns = dist[pos][city] +
                         tsp(mask | (1 << city), city);

            ans = min(ans, newAns);
        }
    }

    return dp[mask][pos] = ans;
}

int main() {
    // инициализация dp
    for (int i = 0; i < (1 << n); i++)
        for (int j = 0; j < n; j++)
            dp[i][j] = -1;

    cout << "Минимальная стоимость: "
         << tsp(1, 0) << endl;

    return 0;
}

