string atbash(string text) {
    for (int i = 0; i < text.length(); i++) {
        char c = text[i];

        if (isupper(c)) {
            text[i] = 'Z' - (c - 'A');
        }
        else if (islower(c)) {
            text[i] = 'z' - (c - 'a');
        }
    }

    return text;
}

