    cout << atbash(s) << endl; // SVOOL
}

#include <iostream>
using namespace std;

string base64_chars =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    "abcdefghijklmnopqrstuvwxyz"
    "0123456789+/";

string base64_encode(string input) {
    string output;
    int val = 0, valb = -6;

    for (unsigned char c : input) {
        val = (val << 8) + c;
        valb += 8;

        while (valb >= 0) {
            output.push_back(base64_chars[(val >> valb) & 0x3F]);
            valb -= 6;
        }
    }

    if (valb > -6)
        output.push_back(base64_chars[((val << 8) >> (valb + 8)) & 0x3F]);

    while (output.size() % 4)
        output.push_back('=');

    return output;
}

int main() {
    string text = "Man";
    cout << base64_encode(text) << endl; // TWFu
}

#include <cassert>
#include <cstdint>
#include <iostream>

using namespace std;

namespace ciphers {
namespace base64_encoding {

const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

string base64_encode(const string &input) {
    string base64_string;
    for (uint32_t i = 0; i < input.size(); i += 3) {
        char first_byte = input[i];
        base64_string.push_back(chars[first_byte >> 2]);

        if (i + 1 < input.size()) {
            char second_byte = input[i + 1];
            base64_string.push_back(
                chars[(((first_byte & 3) << 4) | ((second_byte & 0xF0) >> 4))]);

            if (i + 2 < input.size()) {
                char third_byte = input[i + 2];
                base64_string.push_back(chars[((third_byte & 0xC0) >> 6) |
                                              ((second_byte & 0x0F) << 2)]);
                base64_string.push_back(chars[(third_byte & 0x3F)]);
            } else {
                base64_string.push_back(chars[((second_byte & 0x0F) << 2)]);
                base64_string.push_back('=');
            }
        } else {
            base64_string.push_back(chars[((first_byte & 3) << 4)]);
            base64_string.push_back('=');
            base64_string.push_back('=');
        }
    }
    return base64_string;
}

uint8_t find_idx(const char c) {
    if (c >= 'A' && c <= 'Z') {
        return c - 'A';
    } else if (c >= 'a' && c <= 'z') {
        return c - 'a' + 26;
    } else if (c >= '0' && c <= '9') {
        return c - '0' + 52;
    } else if (c == '+') {
        return 62;
    } else if (c == '/') {
        return 63;
    }
    return -1;
}

string base64_decode(const string &base64_str) {
    string base64_decoded;
    for (uint32_t i = 0; i < base64_str.size(); i += 4) {
        char first_byte = base64_str[i];
        char second_byte = base64_str[i + 1];
        char first_actual_byte = static_cast<char>(
            (find_idx(first_byte) << 2) | ((find_idx(second_byte)) >> 4));
        base64_decoded.push_back(first_actual_byte);
        if (i + 2 < base64_str.size() && base64_str[i + 2] != '=') {
            char third_byte = base64_str[i + 2];
            char second_actual_byte =
                static_cast<char>(((find_idx(second_byte) & 0x0F) << 4) |
                                  (find_idx(third_byte) >> 2));
            base64_decoded.push_back(second_actual_byte);

            if (i + 3 < base64_str.size() && base64_str[i + 3] != '=') {
                char fourth_byte = base64_str[i + 3];
                char third_actual_byte =
                    static_cast<char>(((find_idx(third_byte) & 0x03) << 6) |
                                      find_idx(fourth_byte));
                base64_decoded.push_back(third_actual_byte);
            }
        }
    }
    return base64_decoded;
}
}
}

static void test() {
    string str = "To err is human, but to really foul things up you need a computer.";
    string base64_str = ciphers::base64_encoding::base64_encode(str);
    string verify = "VG8gZXJyIGlzIGh1bWFuLCBidXQgdG8gcmVhbGx5IGZvdWwgdGhpbmdzIHVwIHlvdSBuZW"
                    "VkIGEgY29tcHV0ZXIu";
    assert(base64_str == verify);
    string original_str = ciphers::base64_encoding::base64_decode(base64_str);
    assert(original_str == str);

    str = "Man is distinguished, not only by his reason, but by this singular "
          "passion from other animals, which is a lust of the mind, that by a "
          "perseverance of delight in the continued and indefatigable generation "
          "of knowledge, exceeds the short vehemence of any carnal pleasure.";

    base64_str = ciphers::base64_encoding::base64_encode(str);
    verify = "TWFuIGlzIGRpc3Rpbmd1aXNoZWQsIG5vdCBvbmx5IGJ5IGhpcyByZWFzb24sIGJ1dCBieS"
             "B0aGlzIHNpbmd1bGFyIHBhc3Npb24gZnJvbSBvdGhlciBhbmltYWxzLCB3aGljaCBpcyBh"
             "IGx1c3Qgb2YgdGhlIG1pbmQsIHRoYXQgYnkgYSBwZXJzZXZlcmFuY2Ugb2YgZGVsaWdodC"
             "BpbiB0aGUgY29udGludWVkIGFuZCBpbmRlZmF0aWdhYmxlIGdlbmVyYXRpb24gb2Yga25v"
             "d2xlZGdlLCBleGNlZWRzIHRoZSBzaG9ydCB2ZWhlbWVuY2Ugb2YgYW55IGNhcm5hbCBwbG"
             "Vhc3VyZS4=";
    assert(base64_str == verify);
    original_str = ciphers::base64_encoding::base64_decode(base64_str);
    assert(original_str == str);
}

int main() {
    test();
    return 0;
}

#include <iostream>
#include <string>
#include <cassert>

using namespace std;

namespace ciphers {
    namespace caesar {
        namespace {
            inline char get_char(const int x) {
                return char(x + 65);
            }
            inline int get_value(const char c) {
                return int(c - 65);
            }
        }
        string encrypt(const string &text, const int &shift) {
            string encrypted_text = "";
            for (char c : text) {
                int place_value = get_value(c);
                place_value = (place_value + shift) % 26;
                char new_char = get_char(place_value);
                encrypted_text += new_char;
            }
            return encrypted_text;
        }
        string decrypt(const string &text, const int &shift) {
            string decrypted_text = "";
            for (char c : text) {
                int place_value = get_value(c);
                place_value = (place_value - shift) % 26;
                if(place_value < 0) {
                    place_value = place_value + 26;
                }
                char new_char = get_char(place_value);
                decrypted_text += new_char;
            }
            return decrypted_text;
        }
    }
}

void test() {
    string text1 = "ALANTURING";
    string encrypted1 = ciphers::caesar::encrypt(text1, 17);
    string decrypted1 = ciphers::caesar::decrypt(encrypted1, 17);
    assert(text1 == decrypted1);
    cout << "Original text : " << text1;
    cout << " , Encrypted text (with shift = 21) : " << encrypted1;
    cout << " , Decrypted text : "<< decrypted1 << endl;

    string text2 = "HELLOWORLD";
    string encrypted2 = ciphers::caesar::encrypt(text2, 1729);
    string decrypted2 = ciphers::caesar::decrypt(encrypted2, 1729);
    assert(text2 == decrypted2);
    cout << "Original text : " << text2;
    cout << " , Encrypted text (with shift = 1729) : " << encrypted2;
    cout << " , Decrypted text : "<< decrypted2 << endl;
}

int main() {
    test();
    return 0;
}

#include <iostream>
using namespace std;

string encrypt(string text, int k) {
    string result = "";

    for (char c : text) {

        if (isupper(c)) {
            result += char((c - 'A' + k) % 26 + 'A');
        }
        else if (islower(c)) {
            result += char((c - 'a' + k) % 26 + 'a');
        }
        else {
            result += c; // символы не меняем
        }
    }

    return result;
}

int main() {
    string s = "HELLO";
    int k = 3;

    cout << encrypt(s, k) << endl; // KHOOR
}

#include <cassert>
#include <iostream>

#include "uint256_t.hpp"

using namespace std;

namespace ciphers {
namespace elliptic_curve_key_exchange {

typedef struct Point {
    uint256_t x, y;

    inline bool operator==(const Point &p) { return x == p.x && y == p.y; }

    friend ostream &operator<<(ostream &op, const Point &p) {
        op << p.x << " " << p.y;
        return op;
    }
} Point;

uint256_t exp(uint256_t number, uint256_t power, const uint256_t &mod) {
    if (!power) {
        return uint256_t(1);
    }
    uint256_t ans(1);
    number = number % mod;
    while (power) {
        if ((power & 1)) {
            ans = (ans * number) % mod;
        }
        power >>= 1;
        if (power) {
            number = (number * number) % mod;
        }
    }
    return ans;
}

Point addition(Point a, Point b, const uint256_t &curve_a_coeff,
               uint256_t mod) {
    uint256_t lambda(0);
    uint256_t zero(0);
    lambda = zero = 0;
    uint256_t inf = ~zero;
    if (a.x != b.x || a.y != b.y) {
        if (b.x == a.x) {
            return {inf, inf};
        }
        uint256_t num = (b.y - a.y + mod), den = (b.x - a.x + mod);
        lambda = (num * (exp(den, mod - 2, mod))) % mod;
    } else {
        if (!a.y) {
            return {inf, inf};
        }
        uint256_t axsq = ((a.x * a.x)) % mod;
        axsq += (axsq << 1);
        axsq %= mod;
        uint256_t a_2 = (a.y << 1);
        lambda =
            (((axsq + curve_a_coeff) % mod) * exp(a_2, mod - 2, mod)) % mod;
    }
    Point c;
    c.x = ((lambda * lambda) % mod + (mod << 1) - a.x - b.x) % mod;
    c.y = (((lambda * (a.x + mod - c.x)) % mod) + mod - a.y) % mod;
    return c;
}

Point multiply(const Point &a, const uint256_t &curve_a_coeff, uint256_t p,
               const uint256_t &mod) {
    Point N = a;
    N.x %= mod;
    N.y %= mod;
    uint256_t inf{};
    inf = ~uint256_t(0);
    Point Q = {inf, inf};
    while (p) {
        if ((p & 1)) {
            if (Q.x == inf && Q.y == inf) {
                Q.x = N.x;
                Q.y = N.y;
            } else {
                Q = addition(Q, N, curve_a_coeff, mod);
            }
        }
        p >>= 1;
        if (p) {
            N = addition(N, N, curve_a_coeff, mod);
        }
    }
    return Q;
}
}
}

static void uint128_t_tests() {
