#include <iostream>
using namespace std;

// простая структура точки
struct Point {
    int x, y;
};

// параметры кривой: y^2 = x^3 + ax + b (mod p)
const int a = 2;
const int b = 3;
const int p = 97;

// модульная инверсия (очень упрощённо)
int modInv(int n) {
    for (int i = 1; i < p; i++) {
        if ((n * i) % p == 1)
            return i;
    }
    return 1;
}

// сложение точек
Point add(Point P, Point Q) {
    int lambda;

    if (P.x == Q.x && P.y == Q.y) {
        // удвоение
        int num = (3 * P.x * P.x + a) % p;
        int den = modInv(2 * P.y % p);
        lambda = (num * den) % p;
    } else {
        int num = (Q.y - P.y + p) % p;
        int den = modInv((Q.x - P.x + p) % p);
        lambda = (num * den) % p;
    }

    Point R;
    R.x = (lambda * lambda - P.x - Q.x + p) % p;
    R.y = (lambda * (P.x - R.x) - P.y + p) % p;

    return R;
}

// умножение точки на число (kG)
Point multiply(Point P, int k) {
    Point result = P;
    for (int i = 1; i < k; i++) {
        result = add(result, P);
    }
    return result;
}

int main() {
    Point G = {3, 6}; // базовая точка

    int a_secret = 5;
    int b_secret = 7;

    Point A = multiply(G, a_secret);
    Point B = multiply(G, b_secret);

    Point secretA = multiply(B, a_secret);
    Point secretB = multiply(A, b_secret);

    cout << "Shared Secret (Alice): " << secretA.x << ", " << secretA.y << endl;
    cout << "Shared Secret (Bob):   " << secretB.x << ", " << secretB.y << endl;

    return 0;
}

#include <iostream>
using namespace std;

// функция для шифрования
void encrypt(string text, int key[2][2]) {

    for (int i = 0; i < text.length(); i += 2) {

        int p1 = text[i] - 'A';
        int p2 = text[i+1] - 'A';

        int c1 = (key[0][0]*p1 + key[0][1]*p2) % 26;
        int c2 = (key[1][0]*p1 + key[1][1]*p2) % 26;

        cout << char(c1 + 'A') << char(c2 + 'A') << " ";
    }
}

int main() {
    string text = "HELLO";

    // если нечётная длина → добавляем X
    if (text.length() % 2 != 0)
        text += 'X';

    int key[2][2] = {
        {3, 3},
        {2, 5}
    };

    encrypt(text, key);
}

