#include <iostream>
using namespace std;

string encrypt(string text, string key) {
    string result = "";
    int j = 0;

    for (int i = 0; i < text.length(); i++) {

        char c = text[i];

        if (isalpha(c)) {
            char k = toupper(key[j % key.length()]);

            result += char((toupper(c) - 'A' + (k - 'A')) % 26 + 'A');
            j++;
        } else {
            result += c;
        }
    }

    return result;
}

int main() {
    string text = "HELLO";
    string key = "KEY";

    cout << encrypt(text, key) << endl; // RIJVS
}

#include <iostream>
using namespace std;

string decrypt(string text, string key) {
    string result = "";
    int j = 0;

    for (int i = 0; i < text.length(); i++) {

        char c = text[i];

        if (isalpha(c)) {
            char k = toupper(key[j % key.length()]);

            result += char((toupper(c) - 'A' - (k - 'A') + 26) % 26 + 'A');
            j++;
        } else {
            result += c;
        }
    }

    return result;
}

#include <iostream>
#include <string>
#include <cassert>

using namespace std;

namespace ciphers {
    namespace XOR {   
        string encrypt (const string &text, const int &key) {
            string encrypted_text = "";
            for (auto &c: text) {
                char encrypted_char = char(c ^ key);
                encrypted_text += encrypted_char;
            }
            return encrypted_text;
        }

        string decrypt (const string &text, const int &key) {
            string decrypted_text = "";
            for (auto &c : text) {
                char decrypted_char = char(c ^ key);
                decrypted_text += decrypted_char;
            }
            return decrypted_text;
        }
    }
}

void test() {
    string text1 = "Whipalsh! : Do watch this movie...";
    string encrypted1 = ciphers::XOR::encrypt(text1, 17);
    string decrypted1 = ciphers::XOR::decrypt(encrypted1, 17);
    assert(text1 == decrypted1);
    cout << "Original text : " << text1;
    cout << " , Encrypted text (with key = 17) : " << encrypted1;
    cout << " , Decrypted text : "<< decrypted1 << endl;

    string text2 = "->Valar M0rghulis<-";
    string encrypted2 = ciphers::XOR::encrypt(text2, 29);
    string decrypted2 = ciphers::XOR::decrypt(encrypted2, 29);
    assert(text2 == decrypted2);
    cout << "Original text : " << text2;
    cout << " , Encrypted text (with key = 29) : " << encrypted2;
    cout << " , Decrypted text : "<< decrypted2 << endl;
}

int main() {
    test();
    return 0;
}

