#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdlib>
#include <ctime>
#include <iomanip>
#include <iostream>
#include <queue>
#include <unordered_set>
#include <vector>

using namespace std;

template <typename S, typename T, typename E>
bool sortcol(tuple<S, T, E>& t1, tuple<S, T, E>& t2) {
    if (get<1>(t1) < get<1>(t2)) {
        return true;
    } else if (get<1>(t1) == get<1>(t2) && get<0>(t1) < get<0>(t2)) {
        return true;
    }
    return false;
}

template <typename S, typename T, typename E>
class Compare {
 public:
    bool operator()(tuple<S, T, E, double, double, double>& t1,
                    tuple<S, T, E, double, double, double>& t2) {
        if (get<1>(t2) < get<1>(t1)) {
            return true;
        } else if (get<1>(t2) == get<1>(t1)) {
            return get<0>(t2) < get<0>(t1);
        }
        return false;
    }
};

template <typename S, typename T, typename E>
class FCFS {
    priority_queue<tuple<S, T, E, double, double, double>,
                   vector<tuple<S, T, E, double, double, double>>,
                   Compare<S, T, E>> schedule;

    vector<tuple<S, T, E, double, double, double>> result;
    unordered_set<S> idList;

 public:
    void addProcess(S id, T arrival, E burst) {
        if (idList.find(id) == idList.end()) {
            tuple<S, T, E, double, double, double> t =
                make_tuple(id, arrival, burst, 0, 0, 0);
            schedule.push(t);
            idList.insert(id);
        }
    }

    vector<tuple<S, T, E, double, double, double>> scheduleForFcfs() {
        double timeElapsed = 0;

        while (!schedule.empty()) {
            tuple<S, T, E, double, double, double> cur = schedule.top();

            if (get<1>(cur) > timeElapsed) {
                timeElapsed += get<1>(cur) - timeElapsed;
            }

            timeElapsed += get<2>(cur);
            get<3>(cur) = timeElapsed;
            get<4>(cur) = get<3>(cur) - get<1>(cur);
            get<5>(cur) = get<4>(cur) - get<2>(cur);

            result.push_back(cur);
            schedule.pop();
        }
        return result;
    }

    void printResult() {
        cout << "Status of all the proceses post completion is as follows:" << endl;

        cout << setw(17) << left << "Process ID"
             << setw(17) << left << "Arrival Time"
             << setw(17) << left << "Burst Time"
             << setw(17) << left << "Completion Time"
             << setw(17) << left << "Turnaround Time"
             << setw(17) << left << "Waiting Time" << endl;

        for (size_t i{}; i < result.size(); i++) {
            cout << setprecision(2) << fixed
                 << setw(17) << left << get<0>(result[i])
                 << setw(17) << left << get<1>(result[i])
                 << setw(17) << left << get<2>(result[i])
                 << setw(17) << left << get<3>(result[i])
                 << setw(17) << left << get<4>(result[i])
                 << setw(17) << left << get<5>(result[i]) << endl;
        }
    }
};

template <typename S, typename T, typename E>
vector<tuple<S, T, E, double, double, double>> get_final_status(
    vector<tuple<uint32_t, uint32_t, uint32_t>> input) {

    sort(input.begin(), input.end(), sortcol<S, T, E>);
    vector<tuple<S, T, E, double, double, double>> result(input.size());

    double timeElapsed = 0;

    for (size_t i{}; i < input.size(); i++) {
        T arrival = get<1>(input[i]);
        E burst = get<2>(input[i]);

        if (arrival > timeElapsed) {
            timeElapsed += arrival - timeElapsed;
        }

        timeElapsed += burst;

        double completion = timeElapsed;
        double turnaround = completion - arrival;
        double waiting = turnaround - burst;

        get<0>(result[i]) = get<0>(input[i]);
        get<1>(result[i]) = arrival;
        get<2>(result[i]) = burst;
        get<3>(result[i]) = completion;
        get<4>(result[i]) = turnaround;
        get<5>(result[i]) = waiting;
    }

    return result;
}

static void test() {
    for (int i{}; i < 1000; i++) {
        srand(time(nullptr));
        uint32_t n = 1 + rand() % 1000;

        FCFS<uint32_t, uint32_t, uint32_t> readyQueue;
        vector<tuple<uint32_t, uint32_t, uint32_t>> input(n);

        for (uint32_t i{}; i < n; i++) {
            get<0>(input[i]) = i;
            srand(time(nullptr));
            get<1>(input[i]) = 1 + rand() % 10000;
            srand(time(nullptr));
            get<2>(input[i]) = 1 + rand() % 10000;
        }

        for (uint32_t i{}; i < n; i++) {
            readyQueue.addProcess(get<0>(input[i]),
                                  get<1>(input[i]),
                                  get<2>(input[i]));
        }

        vector<tuple<uint32_t, uint32_t, uint32_t, double, double, double>> res =
            get_final_status<uint32_t, uint32_t, uint32_t>(input);

        assert(res == readyQueue.scheduleForFcfs());
    }

    cout << "All the tests have successfully passed!" << endl;
}

int main() {
    test();
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n = 3;

    int AT[] = {0, 1, 2};
    int BT[] = {5, 3, 8};

    int CT[3], TAT[3], WT[3];

    // первый процесс
    CT[0] = AT[0] + BT[0];

    // остальные
    for (int i = 1; i < n; i++) {
        CT[i] = max(CT[i - 1], AT[i]) + BT[i];
    }

    // считаем TAT и WT
    for (int i = 0; i < n; i++) {
        TAT[i] = CT[i] - AT[i];
        WT[i] = TAT[i] - BT[i];
    }

    cout << "P\tAT\tBT\tCT\tTAT\tWT\n";

    for (int i = 0; i < n; i++) {
        cout << i + 1 << "\t" << AT[i] << "\t" << BT[i] << "\t"
             << CT[i] << "\t" << TAT[i] << "\t" << WT[i] << endl;
    }

    return 0;
}

#include <algorithm>
#include <cassert>
#include <iomanip>
#include <iostream>
#include <queue>
#include <random>
#include <unordered_set>
#include <vector>

using namespace std;

template <typename S, typename T, typename E>
bool sortcol(tuple<S, T, E>& t1, tuple<S, T, E>& t2) {
    if (get<1>(t1) < get<1>(t2) ||
        (get<1>(t1) == get<1>(t2) && get<0>(t1) < get<0>(t2))) {
        return true;
    }
    return false;
}

template <typename S, typename T, typename E>
class Compare {
 public:
    bool operator()(tuple<S, T, E, double, double, double>& t1,
                    tuple<S, T, E, double, double, double>& t2) {
        if (get<2>(t2) < get<2>(t1)) {
            return true;
        } else if (get<2>(t2) == get<2>(t1)) {
            return get<1>(t2) < get<1>(t1);
        }
        return false;
    }
};

template <typename S, typename T, typename E>
class SJF {
    priority_queue<tuple<S, T, E, double, double, double>,
                   vector<tuple<S, T, E, double, double, double>>,
                   Compare<S, T, E>> schedule;

    vector<tuple<S, T, E, double, double, double>> result;
    unordered_set<S> idList;

 public:
    void addProcess(S id, T arrival, E burst) {
        if (idList.find(id) == idList.end()) {
            tuple<S, T, E, double, double, double> t =
                make_tuple(id, arrival, burst, 0, 0, 0);
            schedule.push(t);
            idList.insert(id);
        }
    }

    vector<tuple<S, T, E, double, double, double>> scheduleForSJF() {
        double timeElapsed = 0;

        while (!schedule.empty()) {
            tuple<S, T, E, double, double, double> cur = schedule.top();

            if (get<1>(cur) > timeElapsed) {
                timeElapsed += get<1>(cur) - timeElapsed;
            }

            timeElapsed += get<2>(cur);
            get<3>(cur) = timeElapsed;
            get<4>(cur) = get<3>(cur) - get<1>(cur);
            get<5>(cur) = get<4>(cur) - get<2>(cur);

            assert(get<4>(cur) >= get<2>(cur));
            assert(get<5>(cur) >= 0);

            result.push_back(cur);
            schedule.pop();
        }
        return result;
    }

    void printResult(
        const vector<tuple<S, T, E, double, double, double>>& processes) {

        cout << setw(17) << left << "Process ID"
             << setw(17) << left << "Arrival Time"
             << setw(17) << left << "Burst Time"
             << setw(17) << left << "Completion Time"
             << setw(17) << left << "Turnaround Time"
             << setw(17) << left << "Waiting Time" << endl;

        for (const auto& process : processes) {
            cout << setprecision(2) << fixed
                 << setw(17) << left << get<0>(process)
                 << setw(17) << left << get<1>(process)
                 << setw(17) << left << get<2>(process)
                 << setw(17) << left << get<3>(process)
                 << setw(17) << left << get<4>(process)
                 << setw(17) << left << get<5>(process)
                 << endl;
        }
    }
};

template <typename S, typename T, typename E>
vector<tuple<S, T, E, double, double, double>> get_final_status(
    vector<tuple<S, T, E>> input) {

    sort(input.begin(), input.end(), sortcol<S, T, E>);
    vector<tuple<S, T, E, double, double, double>> result(input.size());

    double timeElapsed = 0;

    for (size_t i = 0; i < input.size(); i++) {
        T arrival = get<1>(input[i]);
        E burst = get<2>(input[i]);

        if (arrival > timeElapsed) {
            timeElapsed = arrival;
        }

        timeElapsed += burst;

        double completion = timeElapsed;
        double turnaround = completion - arrival;
        double waiting = turnaround - burst;

        result[i] = make_tuple(get<0>(input[i]), arrival, burst,
                               completion, turnaround, waiting);
    }

    return result;
}

static void test() {
    for (int i{}; i < 10; i++) {
        random_device rd;
        mt19937 eng(rd());
        uniform_int_distribution<> distr(1, 10);

        uint32_t n = distr(eng);
        SJF<uint32_t, uint32_t, uint32_t> readyQueue;

        vector<tuple<uint32_t, uint32_t, uint32_t, double, double, double>> input(n);

        for (uint32_t i{}; i < n; i++) {
            get<0>(input[i]) = i;
            get<1>(input[i]) = distr(eng);
            get<2>(input[i]) = distr(eng);
        }

        cout << "Processes before SJF scheduling:" << endl;
        readyQueue.printResult(input);

        for (uint32_t i{}; i < n; i++) {
            readyQueue.addProcess(get<0>(input[i]),
                                  get<1>(input[i]),
                                  get<2>(input[i]));
        }

        auto finalResult = readyQueue.scheduleForSJF();

        cout << "\nProcesses after SJF scheduling:" << endl;
        readyQueue.printResult(finalResult);
    }

    cout << "All the tests have successfully passed!" << endl;
}

int main() {
    test();
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n = 4;

    int pid[10] = {1, 2, 3, 4};
    int AT[10]  = {0, 1, 2, 3};
    int BT[10]  = {7, 4, 1, 4};

    int CT[10], TAT[10], WT[10];
    bool completed[10] = {false};

    int current_time = 0;
    int completed_count = 0;

    while (completed_count < n) {

        int idx = -1;
        int minBT = 1e9;

        // ищем процесс с минимальным BT среди доступных
        for (int i = 0; i < n; i++) {
            if (AT[i] <= current_time && !completed[i]) {
                if (BT[i] < minBT) {
                    minBT = BT[i];
                    idx = i;
                }
                // tie-breaker: раньше пришёл
                else if (BT[i] == minBT) {
                    if (AT[i] < AT[idx]) {
                        idx = i;
                    }
                }
            }
        }

        // если нет доступных процессов → сдвигаем время
        if (idx == -1) {
            current_time++;
        }
        else {
            // выполняем процесс полностью
            CT[idx] = current_time + BT[idx];
            current_time = CT[idx];

            TAT[idx] = CT[idx] - AT[idx];
            WT[idx]  = TAT[idx] - BT[idx];

            completed[idx] = true;
            completed_count++;
        }
    }

    // вывод
    cout << "P\tAT\tBT\tCT\tTAT\tWT\n";

    for (int i = 0; i < n; i++) {
        cout << pid[i] << "\t"
             << AT[i] << "\t"
             << BT[i] << "\t"
             << CT[i] << "\t"
             << TAT[i] << "\t"
             << WT[i] << endl;
    }

    return 0;
}

#include <algorithm>
#include <iostream>
#include <queue>

using namespace std;

using node = struct node {
    int data;
    int height;
    struct node *left;
    struct node *right;
};

node *createNode(int data) {
    node *nn = new node();
    nn->data = data;
    nn->height = 0;
    nn->left = nullptr;
    nn->right = nullptr;
    return nn;
}

int height(node *root) {
    if (root == nullptr) {
        return 0;
    }
    return 1 + max(height(root->left), height(root->right));
}

int getBalance(node *root) {
    return height(root->left) - height(root->right);
}

node *rightRotate(node *root) {
    node *t = root->left;
    node *u = t->right;
    t->right = root;
    root->left = u;
    return t;
}

node *leftRotate(node *root) {
    node *t = root->right;
    node *u = t->left;
    t->left = root;
    root->right = u;
    return t;
}

node *minValue(node *root) {
    if (root->left == nullptr) {
        return root;
    }
    return minValue(root->left);
}

node *insert(node *root, int item) {
    if (root == nullptr) {
        return createNode(item);
    }
    if (item < root->data) {
        root->left = insert(root->left, item);
    } else {
        root->right = insert(root->right, item);
    }

    int b = getBalance(root);

    if (b > 1) {
        if (getBalance(root->left) < 0) {
            root->left = leftRotate(root->left);
        }
        return rightRotate(root);
    } else if (b < -1) {
        if (getBalance(root->right) > 0) {
            root->right = rightRotate(root->right);
        }
        return leftRotate(root);
    }

    return root;
}

node *deleteNode(node *root, int element) {
    if (root == nullptr) {
        return root;
    }

    if (element < root->data) {
        root->left = deleteNode(root->left, element);
    } else if (element > root->data) {
        root->right = deleteNode(root->right, element);
    } else {
        if (!root->right || !root->left) {
            node *temp = !root->right ? root->left : root->right;
            delete root;
            return temp;
        }

        node *temp = minValue(root->right);
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data);
    }

    return root;
}

void deleteAllNodes(const node *const root) {
    if (root) {
        deleteAllNodes(root->left);
        deleteAllNodes(root->right);
        delete root;
    }
}

void levelOrder(node *root) {
    queue<node *> q;
    q.push(root);

    while (!q.empty()) {
        root = q.front();
        cout << root->data << " ";
        q.pop();

        if (root->left) {
            q.push(root->left);
        }
        if (root->right) {
            q.push(root->right);
        }
    }
}

int main() {
    node *root = nullptr;

    for (int i = 1; i <= 7; i++) {
        root = insert(root, i);
    }

    cout << "LevelOrder: ";
    levelOrder(root);

    root = deleteNode(root, 1);
    cout << "\nLevelOrder: ";
    levelOrder(root);

    root = deleteNode(root, 4);
    cout << "\nLevelOrder: ";
    levelOrder(root);

    deleteAllNodes(root);
    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int key;
    Node* left;
    Node* right;
    int height;
};

// высота
int height(Node* n) {
    return n ? n->height : 0;
}

// максимум
int getMax(int a, int b) {
    return (a > b) ? a : b;
}

// создание узла
Node* newNode(int key) {
    Node* node = new Node();
    node->key = key;
    node->left = node->right = NULL;
    node->height = 1;
    return node;
}

// правый поворот
Node* rightRotate(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = getMax(height(y->left), height(y->right)) + 1;
    x->height = getMax(height(x->left), height(x->right)) + 1;

    return x;
}

// левый поворот
Node* leftRotate(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = getMax(height(x->left), height(x->right)) + 1;
    y->height = getMax(height(y->left), height(y->right)) + 1;

    return y;
}

// баланс
int getBalance(Node* n) {
    return n ? height(n->left) - height(n->right) : 0;
}

// вставка
Node* insert(Node* node, int key) {
    if (!node)
        return newNode(key);

    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);
    else
        return node;

    // обновляем высоту
    node->height = 1 + getMax(height(node->left), height(node->right));

    int balance = getBalance(node);

    // LL
    if (balance > 1 && key < node->left->key)
        return rightRotate(node);

    // RR
    if (balance < -1 && key > node->right->key)
        return leftRotate(node);

    // LR
    if (balance > 1 && key > node->left->key) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    // RL
    if (balance < -1 && key < node->right->key) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

// inorder (проверка)
void inorder(Node* root) {
    if (root) {
        inorder(root->left);
        cout << root->key << " ";
        inorder(root->right);
    }
}

int main() {
    Node* root = NULL;

    root = insert(root, 10);
    root = insert(root, 20);
    root = insert(root, 30);
    root = insert(root, 40);
    root = insert(root, 50);
    root = insert(root, 25);

    cout << "Inorder traversal: ";
    inorder(root);

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
};

// создание узла
Node* createNode(int val) {
    Node* newNode = new Node();
    newNode->data = val;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// вставка
Node* insert(Node* root, int val) {
    if (root == NULL)
        return createNode(val);

    if (val < root->data)
        root->left = insert(root->left, val);
    else
        root->right = insert(root->right, val);

    return root;
}

// поиск
bool search(Node* root, int key) {
    if (root == NULL)
        return false;

    if (root->data == key)
        return true;

    if (key < root->data)
        return search(root->left, key);
    else
        return search(root->right, key);
}

// inorder (sorted output)
void inorder(Node* root) {
    if (root != NULL) {
        inorder(root->left);
        cout << root->data << " ";
        inorder(root->right);
    }
}

// минимальный элемент
Node* findMin(Node* root) {
    while (root->left != NULL)
        root = root->left;
    return root;
}

// удаление
Node* deleteNode(Node* root, int key) {
    if (root == NULL)
        return root;

    if (key < root->data)
        root->left = deleteNode(root->left, key);
    else if (key > root->data)
        root->right = deleteNode(root->right, key);
    else {
        // 0 или 1 ребёнок
        if (root->left == NULL) {
            Node* temp = root->right;
            delete root;
            return temp;
        }
        else if (root->right == NULL) {
            Node* temp = root->left;
            delete root;
            return temp;
        }

        // 2 ребёнка
        Node* temp = findMin(root->right);
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data);
    }

    return root;
}

int main() {
    Node* root = NULL;

    root = insert(root, 50);
    insert(root, 30);
    insert(root, 70);
    insert(root, 20);
    insert(root, 40);
    insert(root, 60);
    insert(root, 80);

    cout << "Inorder: ";
    inorder(root);

    cout << "\nSearch 40: " << (search(root, 40) ? "Found" : "Not Found");

    root = deleteNode(root, 20);

    cout << "\nAfter deletion: ";
    inorder(root);

    return 0;
}

#include <iostream>

using namespace std;

struct node {
    int val;
    node *left;
    node *right;
};

struct Queue {
    node *t[100];
    int front;
    int rear;
};

Queue queue;

void enqueue(node *n) {
    queue.t[queue.rear++] = n;
}

node *dequeue() {
    return queue.t[queue.front++];
}

void Insert(node *n, int x) {
    if (x < n->val) {
        if (n->left == NULL) {
            node *temp = new node;
            temp->val = x;
            temp->left = NULL;
            temp->right = NULL;
            n->left = temp;
        } else {
            Insert(n->left, x);
        }
    } else {
        if (n->right == NULL) {
            node *temp = new node;
            temp->val = x;
            temp->left = NULL;
            temp->right = NULL;
            n->right = temp;
        } else {
            Insert(n->right, x);
        }
    }
}

int findMaxInLeftST(node *n) {
    while (n->right != NULL) {
        n = n->right;
    }
    return n->val;
}

void Remove(node *p, node *n, int x) {
    if (n->val == x) {
        if (n->right == NULL && n->left == NULL) {
            if (x < p->val) {
                p->right = NULL;
            } else {
                p->left = NULL;
            }
        } else if (n->right == NULL) {
            if (x < p->val) {
                p->right = n->left;
            } else {
                p->left = n->left;
            }
        } else if (n->left == NULL) {
            if (x < p->val) {
                p->right = n->right;
            } else {
                p->left = n->right;
            }
        } else {
            int y = findMaxInLeftST(n->left);
            n->val = y;
            Remove(n, n->right, y);
        }
    } else if (x < n->val) {
        Remove(n, n->left, x);
    } else {
        Remove(n, n->right, x);
    }
}

void BFT(node *n) {
    if (n != NULL) {
        cout << n->val << "  ";
        enqueue(n->left);
        enqueue(n->right);
        BFT(dequeue());
    }
}

void Pre(node *n) {
    if (n != NULL) {
        cout << n->val << "  ";
        Pre(n->left);
        Pre(n->right);
    }
}

void In(node *n) {
    if (n != NULL) {
        In(n->left);
        cout << n->val << "  ";
        In(n->right);
    }
}

void Post(node *n) {
    if (n != NULL) {
        Post(n->left);
        Post(n->right);
        cout << n->val << "  ";
    }
}

int main() {
    queue.front = 0;
    queue.rear = 0;

    int value, ch;
    node *root = new node;

    cout << "\nEnter the value of root node :";
    cin >> value;

    root->val = value;
    root->left = NULL;
    root->right = NULL;

    do {
        cout << "\n1. Insert"
             << "\n2. Delete"
             << "\n3. Breadth First"
             << "\n4. Preorder Depth First"
             << "\n5. Inorder Depth First"
             << "\n6. Postorder Depth First";

        cout << "\nEnter Your Choice : ";
        cin >> ch;

        int x;

        switch (ch) {
        case 1:
            cout << "\nEnter the value to be Inserted : ";
            cin >> x;
            Insert(root, x);
            break;
        case 2:
            cout << "\nEnter the value to be Deleted : ";
            cin >> x;
            Remove(root, root, x);
            break;
        case 3:
            BFT(root);
            break;
        case 4:
            Pre(root);
            break;
        case 5:
            In(root);
            break;
        case 6:
            Post(root);
            break;
        }
    } while (ch != 0);

    return 0;
}

#include <iostream>
using namespace std;

class MinHeap {
    int* arr;
    int size;
    int capacity;

public:
    MinHeap(int cap) {
        capacity = cap;
        size = 0;
        arr = new int[cap];
    }

    int parent(int i) { return (i - 1) / 2; }
    int left(int i)   { return 2 * i + 1; }
    int right(int i)  { return 2 * i + 2; }

    // вставка
    void insert(int key) {
        if (size == capacity) {
            cout << "Overflow\n";
            return;
        }

        int i = size;
        arr[size++] = key;

        // heapify вверх
        while (i != 0 && arr[parent(i)] > arr[i]) {
            swap(arr[i], arr[parent(i)]);
            i = parent(i);
        }
    }

    // heapify вниз
    void heapify(int i) {
        int l = left(i);
        int r = right(i);
        int smallest = i;

        if (l < size && arr[l] < arr[smallest])
            smallest = l;

        if (r < size && arr[r] < arr[smallest])
            smallest = r;

        if (smallest != i) {
            swap(arr[i], arr[smallest]);
            heapify(smallest);
        }
    }

    // извлечь минимум
    int extractMin() {
        if (size <= 0) return -1;

        if (size == 1)
            return arr[--size];

        int root = arr[0];
        arr[0] = arr[size - 1];
        size--;

        heapify(0);

        return root;
    }

    // вывести
    void print() {
        for (int i = 0; i < size; i++)
            cout << arr[i] << " ";
        cout << endl;
    }
};

int main() {
    MinHeap h(10);

    h.insert(10);
    h.insert(4);
    h.insert(15);
    h.insert(20);
    h.insert(0);

    h.print();

    cout << "Min: " << h.extractMin() << endl;

    h.print();

    return 0;
}

#include <climits>
#include <iostream>
#include <utility>

using namespace std;

class MinHeap {
    int *harr;
    int capacity;
    int heap_size;

 public:
    explicit MinHeap(int cap) {
        heap_size = 0;
        capacity = cap;
        harr = new int[cap];
    }

    void MinHeapify(int);

    int parent(int i) { return (i - 1) / 2; }

    int left(int i) { return (2 * i + 1); }

    int right(int i) { return (2 * i + 2); }

    int extractMin();

    void decreaseKey(int i, int new_val);

    int getMin() { return harr[0]; }

    void deleteKey(int i);

    void insertKey(int k);

    ~MinHeap() { delete[] harr; }
};

void MinHeap::insertKey(int k) {
    if (heap_size == capacity) {
        cout << "\nOverflow: Could not insertKey\n";
        return;
    }

    heap_size++;
    int i = heap_size - 1;
    harr[i] = k;

    while (i != 0 && harr[parent(i)] > harr[i]) {
        swap(harr[i], harr[parent(i)]);
        i = parent(i);
    }
}

void MinHeap::decreaseKey(int i, int new_val) {
    harr[i] = new_val;
    while (i != 0 && harr[parent(i)] > harr[i]) {
        swap(harr[i], harr[parent(i)]);
        i = parent(i);
    }
}

int MinHeap::extractMin() {
    if (heap_size <= 0)
        return INT_MAX;

    if (heap_size == 1) {
        heap_size--;
        return harr[0];
    }

    int root = harr[0];
    harr[0] = harr[heap_size - 1];
    heap_size--;
    MinHeapify(0);

    return root;
}

void MinHeap::deleteKey(int i) {
    decreaseKey(i, INT_MIN);
    extractMin();
}

void MinHeap::MinHeapify(int i) {
    int l = left(i);
    int r = right(i);
    int smallest = i;

    if (l < heap_size && harr[l] < harr[i])
        smallest = l;

    if (r < heap_size && harr[r] < harr[smallest])
        smallest = r;

    if (smallest != i) {
        swap(harr[i], harr[smallest]);
        MinHeapify(smallest);
    }
}

int main() {
    MinHeap h(11);

    h.insertKey(3);
    h.insertKey(2);
    h.deleteKey(1);
    h.insertKey(15);
    h.insertKey(5);
    h.insertKey(4);
    h.insertKey(45);

    cout << h.extractMin() << " ";
    cout << h.getMin() << " ";

    h.decreaseKey(2, 1);

    cout << h.getMin();

    return 0;
}

