#include <cassert>
#include <functional>
#include <initializer_list>
#include <string>
#include <vector>
#include <iostream>

using namespace std;

namespace data_structures {

class Bitset {
 private:
    vector<size_t> data;
    static const size_t blockSize = sizeof(size_t);

 public:
    explicit Bitset(size_t);
    size_t size();
    void add(size_t);
    bool contains(size_t);
};

size_t Bitset::size() { return data.size(); }

Bitset::Bitset(size_t initSize) : data(initSize) {}

void Bitset::add(size_t x) {
    size_t blockIndex = x / blockSize;
    if (blockIndex >= data.size()) {
        data.resize(blockIndex + 1);
    }
    data[blockIndex] |= 1 << (x % blockSize);
}

bool Bitset::contains(size_t x) {
    size_t blockIndex = x / blockSize;
    if (blockIndex >= data.size()) {
        return false;
    }
    return data[blockIndex] & (1 << (x % blockSize));
}

template <typename T>
class BloomFilter {
 private:
    Bitset set;
    vector<function<size_t(T)>> hashFunks;

 public:
    BloomFilter(size_t,
                initializer_list<function<size_t(T)>>);
    void add(T);
    bool contains(T);
};

template <typename T>
BloomFilter<T>::BloomFilter(
    size_t size,
    initializer_list<function<size_t(T)>> funks)
    : set(size), hashFunks(funks) {}

template <typename T>
void BloomFilter<T>::add(T x) {
    for (size_t i = 0; i < hashFunks.size(); i++) {
        set.add(hashFunks[i](x) % (sizeof(size_t) * set.size()));
    }
}

template <typename T>
bool BloomFilter<T>::contains(T x) {
    for (size_t i = 0; i < hashFunks.size(); i++) {
        if (set.contains(hashFunks[i](x) %
                         (sizeof(size_t) * set.size())) == false) {
            return false;
        }
    }
    return true;
}

static size_t hashDJB2(string const& s) {
    size_t hash = 5381;
    for (char c : s) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

static size_t hashStr(string const& s) {
    size_t hash = 37;
    size_t primeNum1 = 54059;
    size_t primeNum2 = 76963;
    for (char c : s) {
        hash = (hash * primeNum1) ^ (c * primeNum2);
    }
    return hash;
}

size_t hashInt_1(int x) {
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = (x >> 16) ^ x;
    return x;
}

size_t hashInt_2(int x) {
    auto y = static_cast<size_t>(x);
    y = (y ^ (y >> 30)) * static_cast<size_t>(0xbf58476d1ce4e5b9);
    y = (y ^ (y >> 27)) * static_cast<size_t>(0x94d049bb133111eb);
    y = y ^ (y >> 31);
    return y;
}

} 

static void test_bloom_filter_string() {
    data_structures::BloomFilter<string> filter(
        10, {data_structures::hashDJB2, data_structures::hashStr});

    vector<string> toCheck{"hello", "world", "!"};
    vector<string> toFalse{"false", "world2", "!!!"};

    for (const auto& x : toCheck) {
        filter.add(x);
    }

    for (const auto& x : toFalse) {
        assert(filter.contains(x) == false);
    }

    for (const auto& x : toCheck) {
        assert(filter.contains(x));
    }
}

static void test_bloom_filter_int() {
    data_structures::BloomFilter<int> filter(
        20, {data_structures::hashInt_1, data_structures::hashInt_2});

    vector<int> toCheck{100, 200, 300, 50};
    vector<int> toFalse{1, 2, 3, 4, 5, 6, 7, 8};

    for (int x : toCheck) {
        filter.add(x);
    }

    for (int x : toFalse) {
        assert(filter.contains(x) == false);
    }

    for (int x : toCheck) {
        assert(filter.contains(x));
    }
}

static void test_bitset() {
    data_structures::Bitset set(2);

    vector<size_t> toCheck{0, 1, 5, 8, 63, 64, 67, 127};

    for (auto x : toCheck) {
        set.add(x);
        assert(set.contains(x));
    }

    assert(set.contains(128) == false);
    assert(set.contains(256) == false);
}

int main() {
    test_bitset();
    test_bloom_filter_string();
    test_bloom_filter_int();

    cout << "All tests have successfully passed!\n";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

class BloomFilter {
    vector<bool> bitArray;
    int size;

public:
    BloomFilter(int s) {
        size = s;
        bitArray.resize(size, false);
    }

    // простые hash функции
    int hash1(int x) { return x % size; }
    int hash2(int x) { return (x / size) % size; }
    int hash3(int x) { return (x * 7) % size; }

    // вставка
    void insert(int x) {
        bitArray[hash1(x)] = true;
        bitArray[hash2(x)] = true;
        bitArray[hash3(x)] = true;
    }

    // проверка
    bool contains(int x) {
        if (!bitArray[hash1(x)]) return false;
        if (!bitArray[hash2(x)]) return false;
        if (!bitArray[hash3(x)]) return false;
        return true;
    }

    void print() {
        for (bool b : bitArray)
            cout << b;
        cout << endl;
    }
};

int main() {
    BloomFilter bf(10);

    bf.insert(5);
    bf.insert(15);

    cout << bf.contains(5) << endl;   // возможно 1
    cout << bf.contains(20) << endl;  // точно 0

    bf.print();

    return 0;
}

#include <iostream>

struct node {
    int data;
    struct node* next;
};
class Queue {
    node* front = nullptr;
    node* rear = nullptr;

    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;

 public:
    Queue() = default;
    ~Queue() {
        while (front) {
            dequeue();
        }
    }

 private:
    void createNode(int val) {
        auto* nn = new node;
        nn->data = val;
        nn->next = nullptr;
        front = nn;
        rear = nn;
    }

 public:
    void enqueue(int val) {
        if (front == nullptr || rear == nullptr) {
            createNode(val);
        } else {
            node* nn = new node;
            nn->data = val;
            rear->next = nn;
            nn->next = front;
            rear = nn;
        }
    }
    void dequeue() {
        if (front == nullptr) {
            return;
        }
        const node* const n = front;
        if (front == rear) {
            front = nullptr;
            rear = nullptr;
        } else {
            front = front->next;
            rear->next = front;
        }
        delete n;
    }
    void traverse() {
        if (front == nullptr) {
            return;
        }
        const node* ptr = front;
        do {
            std::cout << ptr->data << ' ';
            ptr = ptr->next;
        } while (ptr != front);
        std::cout << '\n';
    }
};
int main(void) {
    Queue q;
    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);
    q.enqueue(40);
    q.enqueue(50);
    q.enqueue(60);
    q.enqueue(70);
    q.traverse();
    q.dequeue();
    q.traverse();
    return 0;
}

#include <iostream>
using namespace std;

class DSU {
    int parent[100];
    int rank[100];

public:
    DSU(int n) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    // find с path compression
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);

        return parent[x];
    }

    // union по рангу
    void unite(int x, int y) {
        int px = find(x);
        int py = find(y);

        if (px == py) return;

        if (rank[px] < rank[py]) {
            parent[px] = py;
        }
        else if (rank[px] > rank[py]) {
            parent[py] = px;
        }
        else {
            parent[py] = px;
            rank[px]++;
        }
    }
};

int main() {
    DSU dsu(5);

    dsu.unite(0, 1);
    dsu.unite(1, 2);

    cout << dsu.find(2) << endl; // тот же представитель

    return 0;
