#include <iostream>
#include <vector>

using namespace std;

vector<int> root, rank;

void CreateSet(int n) {
    root = vector<int>(n + 1);
    rank = vector<int>(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        root[i] = i;
    }
}

int Find(int x) {
    if (root[x] == x) {
        return x;
    }
    return root[x] = Find(root[x]);
}

bool InSameUnion(int x, int y) {
    return Find(x) == Find(y);
}

void Union(int x, int y) {
    int a = Find(x), b = Find(y);
    if (a != b) {
        if (rank[a] < rank[b]) {
            root[a] = b;
        } else if (rank[a] > rank[b]) {
            root[b] = a;
        } else {
            root[a] = b;
            ++rank[b];
        }
    }
}

int main() {
    int n = 100;
    CreateSet(n);

    for (int i = 1; i <= 100; ++i) {
        if (root[i] != i) {
            cout << "Fail" << endl;
            break;
        }
    }

    cout << "1 and 2 are initially not in the same subset" << endl;
    if (InSameUnion(1, 2)) {
        cout << "Fail" << endl;
    }

    Union(1, 2);

    cout << "1 and 2 are now in the same subset" << endl;
    if (!InSameUnion(1, 2)) {
        cout << "Fail" << endl;
    }

    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <iostream>

using namespace std;

struct node {
    int val;
    node *prev;
    node *next;
} *start;

class double_linked_list {
 public:
    double_linked_list() { start = NULL; }
    void insert(int x);
    void remove(int x);
    void search(int x);
    void show();
    void reverseShow();
};

void double_linked_list::insert(int x) {
    node *t = start;
    if (start != NULL) {
        while (t->next != NULL) {
            t = t->next;
        }
        node *n = new node;
        t->next = n;
        n->prev = t;
        n->val = x;
        n->next = NULL;
    } else {
        node *n = new node;
        n->val = x;
        n->prev = NULL;
        n->next = NULL;
        start = n;
    }
}

void double_linked_list::remove(int x) {
    node *t = start;
    while (t != NULL && t->val != x) {
        t = t->next;
    }
    if (t == NULL) {
        return;
    }
    if (t->prev == NULL) {
        if (t->next == NULL) {
            start = NULL;
        } else {
            start = t->next;
            start->prev = NULL;
        }
    } else if (t->next == NULL) {
        t->prev->next = NULL;
    } else {
        t->prev->next = t->next;
        t->next->prev = t->prev;
    }
    delete t;
}

void double_linked_list::search(int x) {
    node *t = start;
    int found = 0;
    while (t != NULL) {
        if (t->val == x) {
            cout << "\nFound";
            found = 1;
            break;
        }
        t = t->next;
    }
    if (found == 0) {
        cout << "\nNot Found";
    }
}

void double_linked_list::show() {
    node *t = start;
    while (t != NULL) {
        cout << t->val << "\t";
        t = t->next;
    }
}

void double_linked_list::reverseShow() {
    node *t = start;
    while (t != NULL && t->next != NULL) {
        t = t->next;
    }
    while (t != NULL) {
        cout << t->val << "\t";
        t = t->prev;
    }
}

int main() {
    int choice, x;
    double_linked_list ob;

    do {
        cout << "\n1. Insert";
        cout << "\n2. Delete";
        cout << "\n3. Search";
        cout << "\n4. Forward print";
        cout << "\n5. Reverse print";
        cout << "\n\nEnter you choice : ";
        cin >> choice;

        switch (choice) {
        case 1:
            cout << "\nEnter the element to be inserted : ";
            cin >> x;
            ob.insert(x);
            break;
        case 2:
            cout << "\nEnter the element to be removed : ";
            cin >> x;
            ob.remove(x);
            break;
        case 3:
            cout << "\nEnter the element to be searched : ";
            cin >> x;
            ob.search(x);
            break;
        case 4:
            ob.show();
            break;
        case 5:
            ob.reverseShow();
            break;
        }
    } while (choice != 0);

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
    Node* head;

public:
    DoublyLinkedList() {
        head = NULL;
    }

    // вставка в начало
    void insertFront(int val) {
        Node* newNode = new Node();
        newNode->data = val;
        newNode->prev = NULL;
        newNode->next = head;

        if (head != NULL)
            head->prev = newNode;

        head = newNode;
    }

    // вставка в конец
    void insertEnd(int val) {
        Node* newNode = new Node();
        newNode->data = val;
        newNode->next = NULL;

        if (head == NULL) {
            newNode->prev = NULL;
            head = newNode;
            return;
        }

        Node* temp = head;
        while (temp->next != NULL)
            temp = temp->next;

        temp->next = newNode;
        newNode->prev = temp;
    }

    // удаление
    void deleteNode(int key) {
        Node* temp = head;

        while (temp != NULL && temp->data != key)
            temp = temp->next;

        if (temp == NULL) return;

        if (temp->prev != NULL)
            temp->prev->next = temp->next;
        else
            head = temp->next;

        if (temp->next != NULL)
            temp->next->prev = temp->prev;

        delete temp;
    }

    // вывод вперёд
    void display() {
        Node* temp = head;
        while (temp != NULL) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }

    // вывод назад
    void displayReverse() {
        Node* temp = head;

        while (temp && temp->next != NULL)
            temp = temp->next;

        while (temp != NULL) {
            cout << temp->data << " ";
            temp = temp->prev;
        }
        cout << endl;
    }
};

int main() {
    DoublyLinkedList dll;

    dll.insertFront(10);
    dll.insertFront(5);
    dll.insertEnd(20);
    dll.insertEnd(30);

    dll.display();

    dll.deleteNode(20);

    dll.display();
    dll.displayReverse();

    return 0;
}

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class dsu {
 private:
    vector<uint64_t> p;
    vector<uint64_t> depth;
    vector<uint64_t> setSize;
    vector<uint64_t> maxElement;
    vector<uint64_t> minElement;

 public:
    explicit dsu(uint64_t n) {
        p.assign(n, 0);
        for (uint64_t i = 0; i < n; i++) {
            p[i] = i;
        }

        depth.assign(n, 0);
        maxElement.assign(n, 0);
        minElement.assign(n, 0);

        for (uint64_t i = 0; i < n; i++) {
            depth[i] = 0;
            maxElement[i] = i;
            minElement[i] = i;
        }

        setSize.assign(n, 0);
        for (uint64_t i = 0; i < n; i++) {
            setSize[i] = 1;
        }
    }

    uint64_t findSet(uint64_t i) {
        if (p[i] == i) {
            return i;
        }
        return (p[i] = findSet(p[i]));
    }

    void UnionSet(uint64_t i, uint64_t j) {
        if (isSame(i, j)) {
            return;
        }

        uint64_t x = findSet(i);
        uint64_t y = findSet(j);

        if (depth[x] > depth[y]) {
            swap(x, y);
        }

        p[x] = y;

        if (depth[x] == depth[y]) {
            depth[y]++;
        }

        setSize[y] += setSize[x];
        maxElement[y] = max(maxElement[x], maxElement[y]);
        minElement[y] = min(minElement[x], minElement[y]);
    }

    bool isSame(uint64_t i, uint64_t j) {
        return findSet(i) == findSet(j);
    }

    vector<uint64_t> get(uint64_t i) {
        vector<uint64_t> ans;
        ans.push_back(get_min(i));
        ans.push_back(get_max(i));
        ans.push_back(size(i));
        return ans;
    }

    uint64_t size(uint64_t i) {
        return setSize[findSet(i)];
    }

    uint64_t get_max(uint64_t i) {
        return maxElement[findSet(i)];
    }

    uint64_t get_min(uint64_t i) {
        return minElement[findSet(i)];
    }
};

static void test1() {
    uint64_t n = 10;
    dsu d(n + 1);

    d.UnionSet(1, 2);
    d.UnionSet(1, 4);

    vector<uint64_t> ans = {1, 4, 3};

    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.get(4).at(i) == ans[i]);
    }

    cout << "1st test passed!" << endl;
}

static void test2() {
    uint64_t n = 10;
    dsu d(n + 1);

    d.UnionSet(3, 5);
    d.UnionSet(5, 6);
    d.UnionSet(5, 7);

    vector<uint64_t> ans = {3, 7, 4};

    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.get(3).at(i) == ans[i]);
    }

    cout << "2nd test passed!" << endl;
}

int main() {
    uint64_t n = 10;
    dsu d(n + 1);

    test1();
    test2();

    return 0;
}

#include <iostream>
using namespace std;

class DSU {
    int parent[100];

public:
    DSU(int n) {
        for (int i = 0; i < n; i++)
            parent[i] = i;
    }

    // find с path compression
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]); // ключевая строка

        return parent[x];
    }

    // union (без ранга — чисто для демонстрации)
    void unite(int x, int y) {
        int px = find(x);
        int py = find(y);

        if (px != py)
            parent[px] = py;
    }

    void print(int n) {
        for (int i = 0; i < n; i++)
            cout << parent[i] << " ";
        cout << endl;
    }
};

int main() {
    DSU dsu(5);

    dsu.unite(0, 1);
    dsu.unite(1, 2);
    dsu.unite(2, 3);

    cout << "Before compression: ";
    dsu.print(5);

    // вызов find → происходит сжатие
    dsu.find(3);

    cout << "After compression: ";
    dsu.print(5);

    return 0;
}

