        p.assign(n, 0);
        depth.assign(n, 0);
        setSize.assign(n, 0);

        for (uint64_t i = 0; i < n; i++) {
            p[i] = i;
            depth[i] = 0;
            setSize[i] = 1;
        }
    }

    uint64_t findSet(uint64_t i) {
        while (i != p[i]) {
            i = p[i];
        }
        return i;
    }

