#include <iostream>
using namespace std;

class DSU {
    int parent[100];
    int rank[100];

public:
    DSU(int n) {
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    // find с path compression
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);

        return parent[x];
    }

    // union by rank
    void unite(int x, int y) {
        int px = find(x);
        int py = find(y);

        if (px == py) return;

        if (rank[px] < rank[py]) {
            parent[px] = py;
        }
        else if (rank[px] > rank[py]) {
            parent[py] = px;
        }
        else {
            parent[py] = px;
            rank[px]++;
        }
    }

    void print(int n) {
        for (int i = 0; i < n; i++)
            cout << parent[i] << " ";
        cout << endl;
    }
};

int main() {
    DSU dsu(6);

    dsu.unite(0, 1);
    dsu.unite(2, 3);
    dsu.unite(4, 5);

    dsu.unite(1, 3);
    dsu.unite(3, 5);

    dsu.print(6);

    return 0;
}

