#include <iostream>
#include <memory>
#include <string>
#include <cctype>

using namespace std;

namespace data_structures {
namespace linked_list {

bool isDigit(const string& s) {
    for (char i : s) {
        if (!isdigit(i)) {
            return false;
        }
    }
    return true;
}

class link {
 private:
    int pvalue;
    shared_ptr<link> psucc;

 public:
    int val() { return pvalue; }

    shared_ptr<link>& succ() { return psucc; }

    explicit link(int value = 0) : pvalue(value), psucc(nullptr) {}
};

class list {
 private:
    shared_ptr<link> first;
    shared_ptr<link> last;

 public:
    list() {
        first = make_shared<link>();
        last = nullptr;
    }

    bool isEmpty();
    void push_back(int new_elem);
    void push_front(int new_elem);
    void erase(int old_elem);
    void display();
    shared_ptr<link> search(int find_elem);
};

bool list::isEmpty() {
    return last == nullptr;
}

void list::push_back(int new_elem) {
    if (isEmpty()) {
        first->succ() = make_shared<link>(new_elem);
        last = first->succ();
    } else {
        last->succ() = make_shared<link>(new_elem);
        last = last->succ();
    }
}

void list::push_front(int new_elem) {
    if (isEmpty()) {
        first->succ() = make_shared<link>(new_elem);
        last = first->succ();
    } else {
        shared_ptr<link> t = make_shared<link>(new_elem);
        t->succ() = first->succ();
        first->succ() = t;
    }
}

void list::erase(int old_elem) {
    if (isEmpty()) {
        cout << "List is Empty!";
        return;
    }

    shared_ptr<link> t = first;
    shared_ptr<link> to_be_removed = nullptr;

    while (t != last && t->succ()->val() != old_elem) {
        t = t->succ();
    }

    if (t == last) {
        cout << "Element not found\n";
        return;
    }

    to_be_removed = t->succ();
    t->succ() = t->succ()->succ();
    to_be_removed.reset();

    if (t->succ() == nullptr) {
        last = t;
    }

    if (first == last) {
        last = nullptr;
    }
}

void list::display() {
    if (isEmpty()) {
        cout << "List is Empty!";
        return;
    }

    shared_ptr<link> t = first;

    while (t->succ() != nullptr) {
        cout << t->succ()->val() << "\t";
        t = t->succ();
    }
}

shared_ptr<link> list::search(int find_elem) {
    if (isEmpty()) {
        cout << "List is Empty!";
        return nullptr;
    }

    shared_ptr<link> t = first;

    while (t != last && t->succ()->val() != find_elem) {
        t = t->succ();
    }

    if (t == last) {
        cout << "Element not found\n";
        return nullptr;
    }

    cout << "Element was found\n";
    return t->succ();
}

}  
}

int main() {
    data_structures::linked_list::list l;

    int choice = 0;
    int x = 0;
    string s;

    do {
        cout << "\n1. Insert";
        cout << "\n2. Delete";
        cout << "\n3. Search";
        cout << "\n4. Print";
        cout << "\n0. Exit";
        cout << "\n\nEnter you choice : ";
        cin >> choice;

        switch (choice) {
            case 0:
                cout << "\nQuitting the program...\n";
                break;

            case 1:
                cout << "\nEnter the element to be inserted : ";
                cin >> s;

                if (data_structures::linked_list::isDigit(s)) {
                    x = stoi(s);
                    l.push_back(x);
                } else {
                    cout << "Wrong Input!\n";
                }
                break;

            case 2:
                cout << "\nEnter the element to be removed : ";
                cin >> s;

                if (data_structures::linked_list::isDigit(s)) {
                    x = stoi(s);
                    l.erase(x);
                } else {
                    cout << "Wrong Input!\n";
                }
                break;

            case 3:
                cout << "\nEnter the element to be searched : ";
                cin >> s;

                if (data_structures::linked_list::isDigit(s)) {
                    x = stoi(s);
                    auto found = l.search(x);
                } else {
                    cout << "Wrong Input!\n";
                }
                break;

            case 4:
                l.display();
                cout << "\n";
                break;

            default:
                cout << "Invalid Input\n";
                break;
        }

    } while (choice != 0);

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class LinkedList {
    Node* head;

public:
    LinkedList() {
        head = NULL;
    }

    // вставка в начало
    void insertFront(int val) {
        Node* newNode = new Node();
        newNode->data = val;
        newNode->next = head;
        head = newNode;
    }

    // вставка в конец
    void insertEnd(int val) {
        Node* newNode = new Node();
        newNode->data = val;
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            return;
        }

        Node* temp = head;
        while (temp->next != NULL)
            temp = temp->next;

        temp->next = newNode;
    }

    // удаление
    void deleteNode(int key) {
        Node* temp = head;
        Node* prev = NULL;

        if (temp != NULL && temp->data == key) {
            head = temp->next;
            delete temp;
            return;
        }

        while (temp != NULL && temp->data != key) {
            prev = temp;
            temp = temp->next;
        }

        if (temp == NULL) return;

        prev->next = temp->next;
        delete temp;
    }

    // поиск
    bool search(int key) {
        Node* temp = head;

        while (temp != NULL) {
            if (temp->data == key)
                return true;
            temp = temp->next;
        }

        return false;
    }

    // вывод
    void display() {
        Node* temp = head;

        while (temp != NULL) {
            cout << temp->data << " → ";
            temp = temp->next;
        }

        cout << "NULL\n";
    }
};

int main() {
    LinkedList list;

    list.insertFront(10);
    list.insertFront(5);
    list.insertEnd(20);
    list.insertEnd(30);

    list.display();

    list.deleteNode(20);
    list.display();

    cout << "Search 30: "
         << (list.search(30) ? "Found" : "Not Found");

