#include <iostream>

using namespace std;

struct Node {
    int data;
    int next;
};

Node AvailArray[100];

int head = -1;
int avail = 0;

void initialise_list() {
    for (int i = 0; i <= 98; i++) {
        AvailArray[i].next = i + 1;
    }
    AvailArray[99].next = -1;
}

int getnode() {
    int NodeIndexToBeReturned = avail;
    avail = AvailArray[avail].next;
    return NodeIndexToBeReturned;
}

void freeNode(int nodeToBeDeleted) {
    AvailArray[nodeToBeDeleted].next = avail;
    avail = nodeToBeDeleted;
}

void insertAtTheBeginning(int data) {
    int newNode = getnode();
    AvailArray[newNode].data = data;
    AvailArray[newNode].next = head;
    head = newNode;
}

void insertAtTheEnd(int data) {
    int newNode = getnode();

    if (head == -1) {
        AvailArray[newNode].data = data;
        AvailArray[newNode].next = -1;
        head = newNode;
        return;
    }

    int temp = head;
    while (AvailArray[temp].next != -1) {
        temp = AvailArray[temp].next;
    }

    AvailArray[newNode].data = data;
    AvailArray[newNode].next = -1;
    AvailArray[temp].next = newNode;
}

void display() {
    int temp = head;
    while (temp != -1) {
        cout << AvailArray[temp].data << "->";
        temp = AvailArray[temp].next;
    }
    cout << "-1" << endl;
}

int main() {
    initialise_list();

    int x, y, z;

    while (true) {
        cout << "1. Insert At The Beginning" << endl;
        cout << "2. Insert At The End" << endl;
        cout << "3. Display" << endl;
        cout << "4.Exit" << endl;
        cout << "Enter Your choice" << endl;

        cin >> z;

        switch (z) {
        case 1:
            cout << "Enter the number you want to enter" << endl;
            cin >> x;
            insertAtTheBeginning(x);
            break;

        case 2:
            cout << "Enter the number you want to enter" << endl;
            cin >> y;
            insertAtTheEnd(y);
            break;

        case 3:
            cout << "The linked list contains the following element in order" << endl;
            display();
            break;

        case 4:
            return 0;

        default:
            cout << "The entered choice is not correct" << endl;
        }
    }

    return 0;
}

#include <iostream>
using namespace std;

#define SIZE 10

class ArrayLinkedList {
    int data[SIZE];
    int next[SIZE];

    int head;
    int freeIndex;

public:
    ArrayLinkedList() {
        head = -1;
        freeIndex = 0;

        // создаём свободный список
        for (int i = 0; i < SIZE - 1; i++)
            next[i] = i + 1;

        next[SIZE - 1] = -1;
    }

    // получить свободный индекс
    int getFree() {
        if (freeIndex == -1) return -1;

        int i = freeIndex;
        freeIndex = next[i];
        return i;
    }

    // освободить индекс
    void freeNode(int i) {
        next[i] = freeIndex;
        freeIndex = i;
    }

    // вставка в начало
    void insertFront(int val) {
        int i = getFree();
        if (i == -1) {
            cout << "No space\n";
            return;
        }

        data[i] = val;
        next[i] = head;
        head = i;
    }

    // удаление из начала
    void deleteFront() {
        if (head == -1) return;

        int temp = head;
        head = next[head];

        freeNode(temp);
    }

    // вывод
    void display() {
        int i = head;

        while (i != -1) {
            cout << data[i] << " → ";
            i = next[i];
        }

        cout << "NULL\n";
    }
};

int main() {
    ArrayLinkedList list;

    list.insertFront(10);
    list.insertFront(20);
    list.insertFront(30);

    list.display();

    list.deleteFront();

    list.display();

    return 0;
}

#include <array>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <algorithm>

using namespace std;

namespace data_structures {
namespace list_array {

template <uint64_t N>
struct list {
    array<uint64_t, N> data{};
    uint64_t top = 0;
    bool isSorted = false;

    uint64_t BinarySearch(const array<uint64_t, N> &dataArr,
                          const uint64_t &first,
                          const uint64_t &last,
                          const uint64_t &val) {
        if (last < first) {
            return -1;
        }

        uint64_t mid = (first + last) / 2;

        if (dataArr[mid] == val)
            return mid;
        else if (val < dataArr[mid])
            return BinarySearch(dataArr, first, mid - 1, val);
        else
            return BinarySearch(dataArr, mid + 1, last, val);
    }

    uint64_t LinearSearch(const array<uint64_t, N> &dataArr,
                          const uint64_t &val) const {
        for (uint64_t i = 0; i < top; i++) {
            if (dataArr[i] == val) {
                return i;
            }
        }
        return -1;
    }

    uint64_t search(const uint64_t &val) {
        uint64_t pos;

        if (isSorted) {
            pos = BinarySearch(data, 0, top - 1, val);
        } else {
            pos = LinearSearch(data, val);
        }

        if (pos != -1) {
            cout << "\nElement found at position : " << pos;
        } else {
            cout << "\nElement not found";
        }

        return pos;
    }

    void sort() {
        for (uint64_t i = 0; i < top; i++) {
            uint64_t min_idx = i;
            for (uint64_t j = i + 1; j < top; j++) {
                if (data[j] < data[min_idx]) {
                    min_idx = j;
                }
            }
            swap(data[min_idx], data[i]);
        }
        isSorted = true;
    }

    void insert(const uint64_t &val) {
        if (top == N) {
            cout << "\nOverflow";
            return;
        }

        if (!isSorted) {
            data[top++] = val;
        } else {
            uint64_t pos = 0;

            for (uint64_t i = 0; i < top - 1; i++) {
                if (data[i] <= val && val <= data[i + 1]) {
                    pos = i + 1;
                    break;
                }
            }

            if (pos == 0) {
                pos = top - 1;
            }

            for (uint64_t i = top; i > pos; i--) {
                data[i] = data[i - 1];
            }

            data[pos] = val;
            top++;
        }
    }

    void remove(const uint64_t &val) {
        uint64_t pos = search(val);

        if (pos == -1) {
            cout << "\n Element does not present in the list ";
            return;
        }

        cout << "\n" << data[pos] << " deleted";

        for (uint64_t i = pos; i < top - 1; i++) {
            data[i] = data[i + 1];
        }

        top--;
    }

    void show() {
        cout << '\n';
        for (uint64_t i = 0; i < top; i++) {
            cout << data[i] << " ";
        }
    }
};

}  
}

static void test() {
    data_structures::list_array::list<50> L;

    L.insert(11);
    L.insert(12);
    assert(L.top == 2);

    L.insert(15);
    L.insert(10);
    L.insert(12);
    L.insert(20);
    L.insert(18);
    assert(L.top == 7);

    L.show();

    L.remove(12);
    L.remove(15);
    assert(L.top == 5);

    L.remove(50);
    assert(L.top == 5);

    assert(L.search(11) == 0);
    assert(L.search(12) == 2);
    assert(L.search(50) == -1);

    L.sort();
    assert(L.isSorted == true);

    L.show();

    assert(L.search(11) == 1);
    assert(L.search(12) == 2);
    assert(L.search(50) == -1);
}

int main() {
    test();
    return 0;
}

#include <iostream>
using namespace std;

class ArrayList {
    int* arr;
    int size;
    int capacity;

public:
    ArrayList() {
        capacity = 2;
        size = 0;
        arr = new int[capacity];
    }

    // увеличить размер массива
    void resize() {
        capacity *= 2;
        int* newArr = new int[capacity];

        for (int i = 0; i < size; i++)
            newArr[i] = arr[i];

        delete[] arr;
        arr = newArr;
    }

    // добавить в конец
    void push_back(int val) {
        if (size == capacity)
            resize();

        arr[size++] = val;
    }

    // удалить последний
    void pop_back() {
        if (size > 0)
            size--;
    }

    // доступ по индексу
    int get(int index) {
        if (index >= 0 && index < size)
            return arr[index];

        return -1;
    }

    // вставка по позиции
    void insert(int index, int val) {
        if (index < 0 || index > size) return;

        if (size == capacity)
            resize();

        for (int i = size; i > index; i--)
            arr[i] = arr[i - 1];

        arr[index] = val;
        size++;
    }

    // удаление по позиции
    void erase(int index) {
        if (index < 0 || index >= size) return;

        for (int i = index; i < size - 1; i++)
            arr[i] = arr[i + 1];

        size--;
    }

    // вывод
    void print() {
        for (int i = 0; i < size; i++)
            cout << arr[i] << " ";
        cout << endl;
    }
};

int main() {
    ArrayList list;

    list.push_back(10);
    list.push_back(20);
    list.push_back(30);

    list.print();

    list.insert(1, 15);
    list.print();

    list.erase(2);
    list.print();

    return 0;
}

#include <iostream>
#include <queue>

using namespace std;

struct Btree {
    int data;
    Btree *left;
    Btree *right;
};

void insert(Btree **root, int d) {
    Btree *nn = new Btree();
    nn->data = d;
    nn->left = NULL;
    nn->right = NULL;

    if (*root == NULL) {
        *root = nn;
        return;
    }

    queue<Btree *> q;
    q.push(*root);

    while (!q.empty()) {
        Btree *node = q.front();
        q.pop();

        if (node->left)
            q.push(node->left);
        else {
            node->left = nn;
            return;
        }

        if (node->right)
            q.push(node->right);
        else {
            node->right = nn;
            return;
        }
    }
}

void morrisInorder(Btree *root) {
    Btree *curr = root;
    Btree *temp;

    while (curr) {
        if (curr->left == NULL) {
            cout << curr->data << " ";
            curr = curr->right;
        } else {
            temp = curr->left;

            while (temp->right && temp->right != curr)
                temp = temp->right;

            if (temp->right == NULL) {
                temp->right = curr;
                curr = curr->left;
            } else {
                cout << curr->data << " ";
                temp->right = NULL;
                curr = curr->right;
            }
        }
    }
}

void deleteAll(const Btree *const root) {
    if (root) {
        deleteAll(root->left);
        deleteAll(root->right);
        delete root;
    }
}

int main() {
    Btree *root = NULL;

    for (int i = 1; i <= 7; i++)
        insert(&root, i);

    cout << "Morris Inorder: ";
    morrisInorder(root);

    deleteAll(root);
    return 0;
}

