void morrisInorder(Node* root) {
    Node* current = root;

    while (current != NULL) {
        if (current->left == NULL) {
            cout << current->data << " ";
            current = current->right;
        } else {
            Node* pred = current->left;

            while (pred->right != NULL && pred->right != current) {
                pred = pred->right;
            }

            if (pred->right == NULL) {
                pred->right = current;
                current = current->left;
            } else {
                pred->right = NULL;
                cout << current->data << " ";
                current = current->right;
            }
        }
    }
}

