#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class LinkedList {
private:
    Node* head;

public:
    LinkedList() {
        head = nullptr;
    }

    // Добавление в начало
    void insertFront(int value) {
        Node* newNode = new Node;
        newNode->data = value;
        newNode->next = head;
        head = newNode;
    }

    // Добавление в конец
    void insertEnd(int value) {
        Node* newNode = new Node;
        newNode->data = value;
        newNode->next = nullptr;

        if (head == nullptr) {
            head = newNode;
            return;
        }

        Node* temp = head;
        while (temp->next != nullptr) {
            temp = temp->next;
        }

        temp->next = newNode;
    }

    // Удаление элемента
    void deleteValue(int value) {
        if (head == nullptr) {
            cout << "List is empty\n";
            return;
        }

        if (head->data == value) {
            Node* temp = head;
            head = head->next;
            delete temp;
            return;
        }

        Node* temp = head;

        while (temp->next != nullptr && temp->next->data != value) {
            temp = temp->next;
        }

        if (temp->next == nullptr) {
            cout << "Element not found\n";
            return;
        }

        Node* del = temp->next;
        temp->next = temp->next->next;
        delete del;
    }

    // Поиск
    void search(int value) {
        Node* temp = head;
        int pos = 0;

        while (temp != nullptr) {
            if (temp->data == value) {
                cout << "Found at position: " << pos << endl;
                return;
            }
            temp = temp->next;
            pos++;
        }

        cout << "Not found\n";
    }

    // Вывод списка
    void display() {
        Node* temp = head;

        while (temp != nullptr) {
            cout << temp->data << " -> ";
            temp = temp->next;
        }

        cout << "NULL\n";
    }

    // Деструктор (очистка памяти)
    ~LinkedList() {
        Node* temp;
        while (head != nullptr) {
            temp = head;
            head = head->next;
            delete temp;
        }
    }
};

int main() {
    LinkedList list;

    list.insertFront(10);
    list.insertFront(5);
    list.insertEnd(20);
    list.insertEnd(30);

    cout << "List: ";
    list.display();

    list.search(20);

    list.deleteValue(10);
    cout << "After deletion: ";
    list.display();

    return 0;
}

#ifndef DATA_STRUCTURES_QUEUE_HPP_
#define DATA_STRUCTURES_QUEUE_HPP_

#include <iostream>
#include <vector>
#include <memory>
#include <stdexcept>

using namespace std;

template <class ValueType>
struct Node {
    ValueType data;
    shared_ptr<Node<ValueType>> next;
};

template <class ValueType>
class queue {
    using node_type = Node<ValueType>;

 public:
    using value_type = ValueType;

    void display() const {
        cout << "Front --> ";
        auto temp = queueFront;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << '\n';
        cout << "Size of queue: " << size << '\n';
    }

    vector<value_type> toVector() const {
        vector<value_type> result;
        auto temp = queueFront;
        while (temp != nullptr) {
            result.push_back(temp->data);
            temp = temp->next;
        }
        return result;
    }

 private:
    void ensureNotEmpty() const {
        if (isEmptyQueue()) {
            throw invalid_argument("Queue is empty.");
        }
    }

 public:
    bool isEmptyQueue() const {
        return (queueFront == nullptr);
    }

    void enQueue(const value_type& item) {
        auto newNode = make_shared<node_type>();
        newNode->data = item;
        newNode->next = nullptr;

        if (isEmptyQueue()) {
            queueFront = newNode;
            queueRear = newNode;
        } else {
            queueRear->next = newNode;
            queueRear = queueRear->next;
        }
        ++size;
    }

    value_type front() const {
        ensureNotEmpty();
        return queueFront->data;
    }

    void deQueue() {
        ensureNotEmpty();
        queueFront = queueFront->next;
        --size;
    }

    void clear() {
        queueFront = nullptr;
        queueRear = nullptr;
        size = 0;
    }

 private:
    shared_ptr<node_type> queueFront = {};
    shared_ptr<node_type> queueRear = {};
    size_t size = 0;
};

#endif

#include <iostream>
using namespace std;

class Queue {
private:
    int arr[100];
    int front, rear;

public:
    Queue() {
        front = 0;
        rear = -1;
    }

    bool isEmpty() {
        return front > rear;
    }

    void enqueue(int x) {
        if (rear == 99) {
            cout << "Queue Overflow\n";
            return;
        }
        arr[++rear] = x;
    }

    void dequeue() {
        if (isEmpty()) {
            cout << "Queue Underflow\n";
            return;
        }
        front++;
    }

    int peek() {
        if (isEmpty()) return -1;
        return arr[front];
    }

    void display() {
        for (int i = front; i <= rear; i++) {
            cout << arr[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    Queue q;

    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);

    q.display();

    q.dequeue();
    q.display();

    cout << "Front: " << q.peek() << endl;

    return 0;
}

#include <array>
#include <cstdint>
#include <iostream>
#include <cstdlib>

using namespace std;

constexpr uint16_t max_size{10};

namespace data_structures {
namespace queue_using_array {

class Queue_Array {
 public:
    void enqueue(const int16_t&);
    int dequeue();
    void display() const;

 private:
    int8_t front{-1};
    int8_t rear{-1};
    array<int16_t, max_size> arr{};
};

void Queue_Array::enqueue(const int16_t& ele) {
    if (rear == arr.size() - 1) {
        cout << "\nQueue is full";
    } else if (front == -1 && rear == -1) {
        front = rear = 0;
        arr[rear] = ele;
    } else {
        arr[++rear] = ele;
    }
}

int Queue_Array::dequeue() {
    int16_t d{0};

    if (front == -1) {
        cout << "\nQueue is empty ";
        return 0;
    } else if (front == rear) {
        d = arr.at(front);
        front = rear = -1;
    } else {
        d = arr.at(front++);
    }

    return d;
}

void Queue_Array::display() const {
    if (front == -1) {
        cout << "\nQueue is empty";
    } else {
        for (int16_t i = front; i <= rear; ++i) {
            cout << arr.at(i) << " ";
        }
    }
}

}  
}

int main() {
    int op{0}, data{0};
    data_structures::queue_using_array::Queue_Array ob;

    cout << "\n1. enqueue(Insertion)";
    cout << "\n2. dequeue(Deletion)";
    cout << "\n3. Display";
    cout << "\n4. Exit";

    while (true) {
        cout << "\nEnter your choice ";
        cin >> op;

        if (op == 1) {
            cout << "Enter data ";
            cin >> data;
            ob.enqueue(data);
        } else if (op == 2) {
            data = ob.dequeue();
            cout << "\ndequeue element is:\t" << data;
        } else if (op == 3) {
            ob.display();
        } else if (op == 4) {
            exit(0);
        } else {
            cout << "\nWrong choice ";
        }
    }

    return 0;
}

