struct node {
    int val;
    node *next;
};

node *top_var = nullptr;

void push(int x) {
    node *n = new node;
    n->val = x;
    n->next = top_var;
    top_var = n;
}

void pop() {
    if (top_var == nullptr) {
        cout << "\nUnderflow";
    } else {
        node *t = top_var;
        cout << "\n" << t->val << " deleted";
        top_var = top_var->next;
        delete t;
    }
}

