        t = t->next;
    }
}

int main() {
    int ch = 0, x = 0;

    do {
        cout << "\n0. Exit";
        cout << "\n1. Push";
        cout << "\n2. Pop";
        cout << "\n3. Print";
        cout << "\nEnter Your Choice: ";
        cin >> ch;

        switch (ch) {
            case 1:
                cout << "\nInsert : ";
                cin >> x;
                push(x);
                break;

            case 2:
                pop();
                break;

            case 3:
                show();
                break;

            case 0:
                break;

            default:
                cout << "Invalid option!\n";
                break;
        }

    } while (ch != 0);

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class Stack {
private:
    Node* top;

public:
    Stack() {
        top = nullptr;
    }

    bool isEmpty() {
        return top == nullptr;
    }

    // PUSH
    void push(int x) {
        Node* temp = new Node;
        temp->data = x;
        temp->next = top;
        top = temp;
    }

    // POP
    void pop() {
        if (isEmpty()) {
            cout << "Stack Underflow\n";
            return;
        }

        Node* temp = top;
        top = top->next;
        delete temp;
    }

    // PEEK
    int peek() {
        if (isEmpty()) {
            cout << "Stack is empty\n";
            return -1;
        }
        return top->data;
    }

    // DISPLAY
    void display() {
        Node* temp = top;

        while (temp != nullptr) {
            cout << temp->data << " -> ";
            temp = temp->next;
        }

        cout << "NULL\n";
    }

    // Destructor (очистка памяти)
    ~Stack() {
        while (!isEmpty()) {
            pop();
        }
    }
};

int main() {
    Stack s;

    s.push(10);
    s.push(20);
    s.push(30);

    cout << "Stack: ";
    s.display();

    cout << "Top: " << s.peek() << endl;

    s.pop();
    cout << "After pop: ";
    s.display();

    return 0;
}

#include <cassert>
#include <cstdint>
#include <iostream>
#include <queue>

using namespace std;

namespace data_structures {
namespace stack_using_queue {

struct Stack {
    queue<int64_t> main_q;
    queue<int64_t> auxiliary_q;
    uint32_t current_size = 0;

    int top() {
        return main_q.front();
    }

    void push(int val) {
        auxiliary_q.push(val);

        while (!main_q.empty()) {
            auxiliary_q.push(main_q.front());
            main_q.pop();
        }

        swap(main_q, auxiliary_q);
        current_size++;
    }

    void pop() {
        if (main_q.empty()) {
            return;
        }

        main_q.pop();
        current_size--;
    }

    int size() {
        return current_size;
    }
};

}
}

static void test() {
    data_structures::stack_using_queue::Stack s;

    s.push(1);
    s.push(2);
    s.push(3);

    assert(s.size() == 3);
    assert(s.top() == 3);

    s.pop();
    assert(s.top() == 2);

    s.pop();
    assert(s.top() == 1);

    s.push(5);
    assert(s.top() == 5);

    s.pop();
    assert(s.top() == 1);

    assert(s.size() == 1);
}

int main() {
    test();
    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

class Stack {
private:
    queue<int> q;

public:
    // PUSH
    void push(int x) {
        int size = q.size();
        q.push(x);

        // вращаем очередь
        for (int i = 0; i < size; i++) {
            q.push(q.front());
            q.pop();
        }
    }

    // POP
    void pop() {
        if (q.empty()) {
            cout << "Stack is empty\n";
            return;
        }
        q.pop();
    }

    // PEEK
    int top() {
        if (q.empty()) return -1;
        return q.front();
    }

    bool isEmpty() {
        return q.empty();
    }
};

int main() {
    Stack s;

    s.push(10);
    s.push(20);
    s.push(30);

    cout << "Top: " << s.top() << endl; // 30

    s.pop();
    cout << "Top after pop: " << s.top() << endl; // 20

    return 0;
}

#include <cassert>
#include <iostream>
#include <vector>
#include <stdexcept>

#include "./queue.hpp"

using namespace std;

template <typename T>
void testConstructedQueueIsEmpty() {
    const queue<T> curQueue;
    assert(curQueue.isEmptyQueue());
}

void testEnQueue() {
    queue<int> curQueue;

    curQueue.enQueue(10);
    assert(curQueue.toVector() == vector<int>({10}));

    curQueue.enQueue(20);
    assert(curQueue.toVector() == vector<int>({10, 20}));

    curQueue.enQueue(30);
    curQueue.enQueue(40);
    assert(curQueue.toVector() == vector<int>({10, 20, 30, 40}));
}

void testDeQueue() {
    queue<int> curQueue;

    curQueue.enQueue(10);
    curQueue.enQueue(20);
    curQueue.enQueue(30);

    curQueue.deQueue();
    assert(curQueue.toVector() == vector<int>({20, 30}));

    curQueue.deQueue();
    assert(curQueue.toVector() == vector<int>({30}));

    curQueue.deQueue();
    assert(curQueue.isEmptyQueue());
}

void testFront() {
    queue<int> curQueue;

    curQueue.enQueue(10);
    assert(curQueue.front() == 10);

    curQueue.enQueue(20);
    assert(curQueue.front() == 10);
}

void testQueueAfterClearIsEmpty() {
    queue<int> curQueue;

    curQueue.enQueue(10);
    curQueue.enQueue(20);
    curQueue.enQueue(30);

    curQueue.clear();
    assert(curQueue.isEmptyQueue());
}

void testFrontThrowsAnInvalidArgumentWhenQueueEmpty() {
    const queue<int> curQueue;
    bool wasException = false;

    try {
        curQueue.front();
    } catch (const invalid_argument&) {
        wasException = true;
    }

    assert(wasException);
}

void testDeQueueThrowsAnInvalidArgumentWhenQueueEmpty() {
    queue<int> curQueue;
    bool wasException = false;

    try {
        curQueue.deQueue();
    } catch (const invalid_argument&) {
        wasException = true;
    }

    assert(wasException);
}

int main() {
    testConstructedQueueIsEmpty<int>();
    testConstructedQueueIsEmpty<double>();
    testConstructedQueueIsEmpty<vector<long double>>();

    testEnQueue();
    testDeQueue();
    testQueueAfterClearIsEmpty();
    testFrontThrowsAnInvalidArgumentWhenQueueEmpty();
    testDeQueueThrowsAnInvalidArgumentWhenQueueEmpty();

    cout << "All tests pass!\n";
    return 0;
}

#include <iostream>
using namespace std;

class Queue {
private:
    int arr[100];
    int front, rear;

public:
    Queue() {
        front = 0;
        rear = -1;
    }

    bool isEmpty() {
        return front > rear;
    }

    bool isFull() {
        return rear == 99;
    }

    void enqueue(int x) {
        if (isFull()) {
            cout << "Queue Overflow\n";
            return;
        }
        arr[++rear] = x;
        cout << "Inserted: " << x << endl;
    }

    void dequeue() {
        if (isEmpty()) {
            cout << "Queue Underflow\n";
            return;
        }
        cout << "Removed: " << arr[front++] << endl;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return -1;
        }
        return arr[front];
    }

    void display() {
        if (isEmpty()) {
            cout << "Queue is empty\n";
            return;
        }
        cout << "Queue: ";
        for (int i = front; i <= rear; i++) {
            cout << arr[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    Queue q;
    int choice, x;

    do {
        cout << "\n1. Enqueue";
        cout << "\n2. Dequeue";
        cout << "\n3. Peek";
        cout << "\n4. Display";
        cout << "\n0. Exit";
        cout << "\nEnter choice: ";
        cin >> choice;

        switch (choice) {
        case 1:
            cout << "Enter value: ";
            cin >> x;
            q.enqueue(x);
            break;

        case 2:
            q.dequeue();
            break;

        case 3:
            cout << "Front element: " << q.peek() << endl;
            break;

        case 4:
            q.display();
            break;

        case 0:
            cout << "Exiting...\n";
            break;

        default:
            cout << "Invalid choice\n";
        }

    } while (choice != 0);

    return 0;
}

#include <cassert>
#include <iostream>
#include <stdexcept>
#include <vector>

#include "./stack.hpp"

using namespace std;

template <typename T>
void testConstructedStackIsEmpty() {
    const stack<T> curStack;
    assert(curStack.isEmptyStack());
}

void testPush() {
    using valueType = int;
    stack<valueType> curStack;

    curStack.push(10);
    curStack.push(20);
    curStack.push(30);
    curStack.push(40);

    const auto expectedData = vector<valueType>({40, 30, 20, 10});
    assert(curStack.toVector() == expectedData);
}

void testTop() {
    using valueType = unsigned;
    stack<valueType> curStack;

    curStack.push(1);
    curStack.push(2);
    curStack.push(3);
    curStack.push(4);

    assert(curStack.top() == static_cast<valueType>(4));
}

void testPop() {
    using valueType = int;
    stack<valueType> curStack;

    curStack.push(100);
    curStack.push(200);
    curStack.push(300);

    assert(curStack.top() == 300);
    curStack.pop();
    assert(curStack.top() == 200);
    curStack.pop();
    assert(curStack.top() == 100);
    curStack.pop();
    assert(curStack.isEmptyStack());
}

void testClear() {
    stack<int> curStack;

    curStack.push(1000);
    curStack.push(2000);

    curStack.clear();
    assert(curStack.isEmptyStack());
}

void testCopyOfStackHasSameData() {
    stack<int> stackA;

    stackA.push(10);
    stackA.push(200);
    stackA.push(3000);

    const auto stackB(stackA);

    assert(stackA.toVector() == stackB.toVector());
}

void testPushingToCopyDoesNotChangeOriginal() {
    stack<int> stackA;

    stackA.push(10);
    stackA.push(20);
    stackA.push(30);

    auto stackB(stackA);
    stackB.push(40);

    assert(stackA.toVector() == vector<int>({30, 20, 10}));
    assert(stackB.toVector() == vector<int>({40, 30, 20, 10}));
}

void testPoppingFromCopyDoesNotChangeOriginal() {
    stack<int> stackA;

    stackA.push(10);
    stackA.push(20);
    stackA.push(30);

    auto stackB(stackA);
    stackB.pop();

    assert(stackA.toVector() == vector<int>({30, 20, 10}));
    assert(stackB.toVector() == vector<int>({20, 10}));
}

void testPushingToOrginalDoesNotChangeCopy() {
    stack<int> stackA;

    stackA.push(10);
    stackA.push(20);
    stackA.push(30);

    const auto stackB(stackA);
    stackA.push(40);

    assert(stackA.toVector() == vector<int>({40, 30, 20, 10}));
    assert(stackB.toVector() == vector<int>({30, 20, 10}));
}

void testPoppingFromOrginalDoesNotChangeCopy() {
    stack<int> stackA;

    stackA.push(10);
    stackA.push(20);
    stackA.push(30);

    const auto stackB(stackA);
    stackA.pop();

    assert(stackA.toVector() == vector<int>({20, 10}));
    assert(stackB.toVector() == vector<int>({30, 20, 10}));
}

void testAssign() {
    stack<int> stackA;

    stackA.push(10);
    stackA.push(20);
    stackA.push(30);

    stack<int> stackB = stackA;

    stackA.pop();
    stackB.push(40);

    assert(stackA.toVector() == vector<int>({20, 10}));
    assert(stackB.toVector() == vector<int>({40, 30, 20, 10}));

    stackB = stackA;

    stackA.pop();
    stackB.push(5);
    stackB.push(6);

    assert(stackA.toVector() == vector<int>({10}));
    assert(stackB.toVector() == vector<int>({6, 5, 20, 10}));
}

void testTopThrowsAnInvalidArgumentWhenStackEmpty() {
    const stack<long double> curStack;

    bool wasException = false;

    try {
        curStack.top();
    } catch (const invalid_argument&) {
        wasException = true;
    }

    assert(wasException);
}

void testPopThrowsAnInvalidArgumentWhenStackEmpty() {
    stack<bool> curStack;

    bool wasException = false;

    try {
        curStack.pop();
    } catch (const invalid_argument&) {
        wasException = true;
    }

    assert(wasException);
}

int main() {
    testConstructedStackIsEmpty<int>();
    testConstructedStackIsEmpty<char>();

    testPush();
    testPop();
    testClear();

    testCopyOfStackHasSameData();
    testPushingToCopyDoesNotChangeOriginal();
    testPoppingFromCopyDoesNotChangeOriginal();
    testPushingToOrginalDoesNotChangeCopy();
    testPoppingFromOrginalDoesNotChangeCopy();

    testAssign();

    testTopThrowsAnInvalidArgumentWhenStackEmpty();
    testPopThrowsAnInvalidArgumentWhenStackEmpty();

    cout << "All tests pass!\n";
    return 0;
}

