    Node* root = nullptr;

    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 70);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 60);
    root = insert(root, 80);

    inorder(root);
    cout << endl;

    preorder(root);
    cout << endl;

    postorder(root);
    cout << endl;

    cout << search(root, 60) << endl;

    root = deleteNode(root, 50);

    inorder(root);
    cout << endl;

    return 0;
}

#include <iostream>
using namespace std;

struct Node {
    int keys[3];
    Node* child[4];
    int n;
    bool leaf;

    Node(bool leaf) {
        this->leaf = leaf;
        n = 0;
        for (int i = 0; i < 4; i++) child[i] = nullptr;
    }
};

class Tree234 {
private:
    Node* root;

    void splitChild(Node* parent, int i, Node* y) {
        Node* z = new Node(y->leaf);
        z->n = 1;
        z->keys[0] = y->keys[2];

        if (!y->leaf) {
            z->child[0] = y->child[2];
            z->child[1] = y->child[3];
        }

        y->n = 1;

        for (int j = parent->n; j > i; j--) {
            parent->child[j + 1] = parent->child[j];
        }
        parent->child[i + 1] = z;

        for (int j = parent->n - 1; j >= i; j--) {
            parent->keys[j + 1] = parent->keys[j];
        }

        parent->keys[i] = y->keys[1];
        parent->n++;
    }

    void insertNonFull(Node* x, int k) {
        int i = x->n - 1;

        if (x->leaf) {
            while (i >= 0 && k < x->keys[i]) {
                x->keys[i + 1] = x->keys[i];
                i--;
            }
            x->keys[i + 1] = k;
            x->n++;
        } else {
            while (i >= 0 && k < x->keys[i]) i--;
            i++;

            if (x->child[i]->n == 3) {
                splitChild(x, i, x->child[i]);
                if (k > x->keys[i]) i++;
            }
            insertNonFull(x->child[i], k);
        }
    }

    void inorder(Node* x) {
        if (!x) return;

        for (int i = 0; i < x->n; i++) {
            inorder(x->child[i]);
            cout << x->keys[i] << " ";
        }
        inorder(x->child[x->n]);
    }

    bool search(Node* x, int k) {
        int i = 0;
        while (i < x->n && k > x->keys[i]) i++;

        if (i < x->n && k == x->keys[i]) return true;
        if (x->leaf) return false;

        return search(x->child[i], k);
    }

public:
    Tree234() {
        root = new Node(true);
    }

    void insert(int k) {
        if (root->n == 3) {
            Node* s = new Node(false);
            s->child[0] = root;
            splitChild(s, 0, root);
            root = s;
        }
        insertNonFull(root, k);
    }

    void inorder() {
        inorder(root);
        cout << endl;
    }

    bool search(int k) {
        return search(root, k);
    }
};

int main() {
    Tree234 t;

    t.insert(10);
    t.insert(20);
    t.insert(5);
    t.insert(6);
    t.insert(12);
    t.insert(30);
    t.insert(7);
    t.insert(17);

    t.inorder();

    cout << t.search(6) << endl;
    cout << t.search(15) << endl;

    return 0;
}

#include <array>
#include <cassert>
#include <fstream>
#include <iostream>
#include <memory>
#include <queue>
#include <string>

namespace data_structures {
namespace tree_234 {

class Node {
 public:
    explicit Node(int64_t item)
        : items({{item, 0, 0}}),
          children({{nullptr, nullptr, nullptr, nullptr}}),
          count(1) {}

    int8_t GetCount() { return count; }
    void SetCount(int8_t c) { count = c; }
    bool IsLeaf() { return children[0] == nullptr; }
    bool IsFull() { return count == 3; }
    bool Is2Node() { return count == 1; }
    bool Is34Node() { return count == 2 || count == 3; }

    bool Contains(int64_t item) {
        for (int8_t i = 0; i < count; i++) {
            if (item == items[i]) return true;
        }
        return false;
    }

    int8_t GetItemIndex(int64_t item) {
        for (int8_t i = 0; i < count; i++) {
            if (items[i] == item) return i;
        }
        return -1;
    }

    int64_t GetMaxItem() { return items[count - 1]; }
    int64_t GetMinItem() { return items[0]; }
    int64_t GetItem(int8_t index) { return items[index]; }

    void SetItem(int8_t index, int64_t new_item) {
        assert(index >= 0 && index <= 2);
        items[index] = new_item;
    }

    int InsertItem(int item) {
        assert(!IsFull());
        if (Contains(item)) return -1;

        int8_t i = 0;
        for (i = 0; i < count; i++) {
            if (items[i] > item) break;
        }

        InsertItemByIndex(i, item, nullptr, true);
        return i;
    }

    void InsertItemByIndex(int8_t index, int64_t item, Node* with_child,
                           bool to_left = true) {
        assert(count < 3 && index >= 0 && index < 3);

        for (int8_t i = count - 1; i >= index; i--) {
            items[i + 1] = items[i];
        }
        items[index] = item;

        int8_t start_index = to_left ? index : index + 1;
        for (int8_t i = count; i >= start_index; i--) {
            children[i + 1] = children[i];
        }
        children[start_index] = with_child;
        count++;
    }

    Node* RemoveItemByIndex(int8_t index, bool keep_left) {
        assert(index >= 0 && index < count);
        Node* removed_child = keep_left ? children[index + 1] : children[index];

        for (int8_t i = index; i < count - 1; i++) {
            items[i] = items[i + 1];
        }
        for (int8_t i = keep_left ? index + 1 : index; i < count; i++) {
            children[i] = children[i + 1];
        }
        count--;
        return removed_child;
    }

    int8_t GetChildIndex(Node* child) {
        for (int8_t i = 0; i < count + 1; i++) {
            if (children[i] == child) return i;
        }
        return -1;
    }

    Node* GetChild(int8_t index) { return children[index]; }
    void SetChild(int8_t index, Node* child) { children[index] = child; }
    Node* GetRightmostChild() { return children[count]; }
    Node* GetLeftmostChild() { return children[0]; }

    Node* GetItemLeftChild(int8_t item_index) {
        if (item_index < 0 || item_index > count - 1) return nullptr;
        return children[item_index];
    }

    Node* GetItemRightChild(int8_t item_index) {
        if (item_index < 0 || item_index > count - 1) return nullptr;
        return children[item_index + 1];
    }

    Node* GetNextPossibleChild(int64_t item) {
        int i = 0;
        for (i = 0; i < count; i++) {
            if (items[i] > item) break;
        }
        return children[i];
    }

 private:
    std::array<int64_t, 3> items;
    std::array<Node*, 4> children;
    int8_t count = 0;
};

class Tree234 {
 public:
    Tree234() = default;
    Tree234(const Tree234&) = delete;
    Tree234(const Tree234&&) = delete;
    Tree234& operator=(const Tree234&) = delete;
    Tree234& operator=(const Tree234&&) = delete;
    ~Tree234() { DeleteNode(root_); }

    void Insert(int64_t item) { InsertPreSplit(item); }
    bool Remove(int64_t item) { return RemovePreMerge(root_, item); }

    void Traverse() {
        Traverse(root_);
        std::cout << std::endl;
    }

    void Print(const char* file_name = nullptr) {
        if (!file_name) file_name = "out.dot";

        std::ofstream ofs(file_name);
        if (!ofs) {
            std::cout << "create tree dot file failed, " << file_name << std::endl;
            return;
        }

        ofs << "digraph G {\n";
        ofs << "node [shape=record]\n";

        int64_t index = 0;

        struct NodeInfo {
            Node* node;
            int64_t index;
        };

        std::queue<NodeInfo> q;

        if (root_) {
            PrintNode(ofs, root_, -1, index, 0);
            q.push({root_, index});

            while (!q.empty()) {
                NodeInfo node_info = q.front();
                q.pop();

                if (!node_info.node->IsLeaf()) {
                    if (node_info.node->GetCount() > 0) {
                        PrintNode(ofs, node_info.node->GetChild(0), node_info.index, ++index, 0);
                        q.push({node_info.node->GetChild(0), index});
                        PrintNode(ofs, node_info.node->GetChild(1), node_info.index, ++index, 1);
                        q.push({node_info.node->GetChild(1), index});
                    }
                    if (node_info.node->GetCount() > 1) {
                        PrintNode(ofs, node_info.node->GetChild(2), node_info.index, ++index, 2);
                        q.push({node_info.node->GetChild(2), index});
                    }
                    if (node_info.node->GetCount() > 2) {
                        PrintNode(ofs, node_info.node->GetChild(3), node_info.index, ++index, 3);
                        q.push({node_info.node->GetChild(3), index});
                    }
                }
            }
        }

        ofs << "}\n";
    }

 private:
    void InsertPreSplit(int64_t item) {
        if (!root_) {
            root_ = new Node(item);
            return;
        }

        Node* parent = nullptr;
        Node* node = root_;

        while (true) {
            if (!node) {
                std::unique_ptr<Node> tmp(new Node(item));
                MergeNodeNotFull(parent, tmp.get());
                return;
            }

            if (node->Contains(item)) return;

            if (node->IsFull()) {
                node = SplitNode(node);

                Node* cur_node = (item < node->GetItem(0))
                    ? node->GetChild(0)
                    : node->GetChild(1);

                if (!parent) {
                    root_ = node;
                } else {
                    MergeNodeNotFull(parent, node);
                }
                node = cur_node;
            }

            parent = node;
            node = parent->GetNextPossibleChild(item);
        }
    }

    Node* Insert(Node* tree, int64_t item) {
        assert(tree != nullptr);

        std::unique_ptr<Node> split_node;

        if (tree->Contains(item)) return nullptr;

        Node* next_node = tree->GetNextPossibleChild(item);
        if (next_node) {
            split_node.reset(Insert(next_node, item));
        } else {
            split_node.reset(new Node(item));
        }

        if (split_node) return MergeNode(tree, split_node.get());

        return nullptr;
    }

    Node* MergeNode(Node* dst_node, Node* node) {
        assert(dst_node && node);

        if (!dst_node->IsFull()) {
            MergeNodeNotFull(dst_node, node);
            return nullptr;
        }

        dst_node = SplitNode(dst_node);

        if (node->GetItem(0) < dst_node->GetItem(0)) {
            MergeNodeNotFull(dst_node->GetChild(0), node);
        } else {
            MergeNodeNotFull(dst_node->GetChild(1), node);
        }

        return dst_node;
    }

    void MergeNodeNotFull(Node* dst_node, Node* node) {
        assert(dst_node && node && !dst_node->IsFull() && node->Is2Node());

        int8_t i = dst_node->InsertItem(node->GetItem(0));
        dst_node->SetChild(i, node->GetChild(0));
        dst_node->SetChild(i + 1, node->GetChild(1));
    }

    Node* SplitNode(Node* node) {
        assert(node->GetCount() == 3);

        Node* left = node;
        Node* right = new Node(node->GetItem(2));
        right->SetChild(0, node->GetChild(2));
        right->SetChild(1, node->GetChild(3));

        Node* parent = new Node(node->GetItem(1));
        parent->SetChild(0, left);
        parent->SetChild(1, right);
        left->SetCount(1);

        return parent;
    }

    bool TryLeftRotate(Node* parent, Node* to_child) {
        int to_child_index = parent->GetChildIndex(to_child);
        if (to_child_index >= parent->GetCount()) return false;

        Node* right_sibling = parent->GetChild(to_child_index + 1);
        if (right_sibling->Is2Node()) return false;

        LeftRotate(parent, to_child_index);
        return true;
    }

    bool TryRightRotate(Node* parent, Node* to_child) {
        int8_t to_child_index = parent->GetChildIndex(to_child);
        if (to_child_index <= 0) return false;

        Node* left_sibling = parent->GetChild(to_child_index - 1);
        if (left_sibling->Is2Node()) return false;

        RightRotate(parent, to_child_index - 1);
        return true;
    }

    void RightRotate(Node* parent, int8_t index) {
        Node* left = parent->GetItemLeftChild(index);
        Node* right = parent->GetItemRightChild(index);

        assert(left && left->Is34Node());
        assert(right && right->Is2Node());

        right->InsertItemByIndex(0, parent->GetItem(index),
                                 left->GetRightmostChild(), true);
        parent->SetItem(index, left->GetMaxItem());
        left->RemoveItemByIndex(left->GetCount() - 1, true);
    }

    void LeftRotate(Node* parent, int8_t index) {
        Node* left = parent->GetItemLeftChild(index);
        Node* right = parent->GetItemRightChild(index);

        assert(right && right->Is34Node());
        assert(left && left->Is2Node());

        left->InsertItemByIndex(left->GetCount(), parent->GetItem(index),
                                right->GetLeftmostChild(), false);
        parent->SetItem(index, right->GetMinItem());
        right->RemoveItemByIndex(0, false);
    }

    Node* Merge(Node* parent, int8_t index) {
        assert(parent);

        Node* left_child = parent->GetItemLeftChild(index);
        Node* right_child = parent->GetItemRightChild(index);
        assert(left_child->Is2Node() && right_child->Is2Node());

        int64_t item = parent->GetItem(index);

        left_child->SetItem(1, item);
        left_child->SetItem(2, right_child->GetItem(0));
        left_child->SetChild(2, right_child->GetChild(0));
        left_child->SetChild(3, right_child->GetChild(1));
        left_child->SetCount(3);

        parent->RemoveItemByIndex(index, true);
        delete right_child;

        return left_child;
    }

    bool RemovePreMerge(Node* node, int64_t item) {
        while (node) {
            if (node->IsLeaf()) {
                if (node->Contains(item)) {
                    if (node->Is2Node()) {
                        delete node;
                        root_ = nullptr;
                    } else {
                        node->RemoveItemByIndex(node->GetItemIndex(item), true);
                    }
                    return true;
                }
                return false;
            }

            if (node->Contains(item)) {
                int8_t index = node->GetItemIndex(item);
                Node* left_child = node->GetItemLeftChild(index);
                Node* right_child = node->GetItemRightChild(index);
                assert(left_child && right_child);

                if (left_child->Is2Node() && right_child->Is2Node()) {
                    if (node->Is2Node()) {
                        Node* new_root = Merge(node, index);
                        delete root_;
                        root_ = new_root;
                        node = root_;
                        continue;
                    }

                    do {
                        if (index > 0) {
                            Node* left_sibling = node->GetItemLeftChild(index - 1);
                            if (left_sibling->Is34Node()) {
                                RightRotate(node, index - 1);
                                break;
                            }
                        }
                        if (index < node->GetCount() - 1) {
                            Node* right_sibling = node->GetItemRightChild(index + 1);
                            if (right_sibling->Is34Node()) {
                                LeftRotate(node, index + 1);
                                break;
                            }
                        }
                        if (index > 0) {
                            Merge(node, index - 1);
                            break;
                        }
                        Merge(node, index + 1);
                    } while (false);
                }

                left_child = node->GetItemLeftChild(index);
                right_child = node->GetItemRightChild(index);

                if (left_child->Is34Node()) {
                    int64_t predecessor = GetTreeMaxItem(left_child);
                    node->SetItem(node->GetItemIndex(item), predecessor);
                    node = left_child;
                    item = predecessor;
                    continue;
                }

                if (right_child->Is34Node()) {
                    int64_t successor = GetTreeMinItem(right_child);
                    node->SetItem(node->GetItemIndex(item), successor);
                    node = right_child;
                    item = successor;
                    continue;
                }
            }

            Node* next_node = node->GetNextPossibleChild(item);

            if (next_node->Is34Node()) {
                node = next_node;
                continue;
            }
            if (TryRightRotate(node, next_node)) {
                node = next_node;
                continue;
            }
            if (TryLeftRotate(node, next_node)) {
                node = next_node;
                continue;
            }

            int8_t child_index = node->GetChildIndex(next_node);
            node = (child_index > 0) ? Merge(node, child_index - 1)
                                     : Merge(node, child_index);
        }

        return false;
    }

    int64_t GetTreeMaxItem(Node* tree) {
        assert(tree);
        int64_t max = 0;
        while (tree) {
            max = tree->GetMaxItem();
            tree = tree->GetRightmostChild();
        }
        return max;
    }

    int64_t GetTreeMinItem(Node* tree) {
        assert(tree);
        int64_t min = 0;
        while (tree) {
            min = tree->GetMinItem();
            tree = tree->GetLeftmostChild();
        }
        return min;
    }

    void DeleteNode(Node* tree) {
        if (!tree) return;
        for (int8_t i = 0; i <= tree->GetCount(); i++) {
            DeleteNode(tree->GetChild(i));
        }
        delete tree;
    }

    void Traverse(Node* node) {
        if (!node) return;
        int8_t i = 0;
        for (i = 0; i < node->GetCount(); i++) {
            Traverse(node->GetChild(i));
            std::cout << node->GetItem(i) << ", ";
        }
        Traverse(node->GetChild(i));
    }

    void PrintNode(std::ofstream& ofs, Node* node, int64_t parent_index,
                   int64_t index, int8_t parent_child_index) {
        assert(node);

        switch (node->GetCount()) {
            case 1:
                ofs << "node_" << index << " [label=\"<f0> " << node->GetItem(0) << "\"]\n";
                break;
            case 2:
                ofs << "node_" << index << " [label=\"<f0> " << node->GetItem(0)
                    << " | <f1> " << node->GetItem(1) << "\"]\n";
                break;
            case 3:
                ofs << "node_" << index << " [label=\"<f0> " << node->GetItem(0)
                    << " | <f1> " << node->GetItem(1)
                    << "| <f2> " << node->GetItem(2) << "\"]\n";
                break;
            default:
                break;
        }

        if (parent_index >= 0) {
            ofs << "node_" << parent_index << ":f"
                << (parent_child_index == 0 ? 0 : parent_child_index - 1) << ":"
                << (parent_child_index == 0 ? "sw" : "se")
                << " -> node_" << index << "\n";
        }
    }

    Node* root_{nullptr};
};

}  // namespace tree_234
}  // namespace data_structures


static void test1() {
    std::array<int16_t, 13> arr = {3, 1, 5, 4, 2, 9, 10, 8, 7, 6, 16, 13, 14};
    data_structures::tree_234::Tree234 tree;

    for (auto i : arr) tree.Insert(i);

    tree.Remove(5);
    tree.Print();
}

static void test2(int64_t n) {
    data_structures::tree_234::Tree234 tree;

    for (int64_t i = 0; i < n; i++) tree.Insert(i);

    tree.Traverse();
    tree.Print((std::to_string(n) + ".dot").c_str());
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        test1();
    } else {
        test2(std::stoi(argv[1]));
    }

    return 0;
}

#include <iostream>
#include <memory>
#include <string>

using namespace std;

class Trie {
 private:
    static constexpr size_t ALPHABETS = 26;

    struct TrieNode {
        shared_ptr<TrieNode> character[ALPHABETS]{nullptr};
        bool isEndOfWord{false};
    };

    shared_ptr<TrieNode> m_root;

    static bool hasChildren(shared_ptr<TrieNode> node) {
        for (size_t i = 0; i < ALPHABETS; i++) {
            if (node->character[i]) return true;
        }
        return false;
    }

    shared_ptr<TrieNode> removeWordHelper(const string& word,
                                          shared_ptr<TrieNode> curr,
                                          size_t index) {
        if (word.size() == index) {
            if (curr->isEndOfWord) curr->isEndOfWord = false;
            if (hasChildren(curr)) return curr;
            return nullptr;
        }

        size_t idx = word[index] - 'a';

        if (!curr->character[idx]) {
            throw runtime_error("Word not found.");
        }

        curr->character[idx] =
            removeWordHelper(word, curr->character[idx], index + 1);

        if (curr->character[idx] || hasChildren(curr)) {
            return curr;
        }
        return nullptr;
    }

 public:
    Trie() : m_root(make_shared<TrieNode>()) {}

    void insert(const string& word) {
        auto curr = m_root;
        for (char ch : word) {
            size_t index = ch - 'a';
            if (!curr->character[index]) {
                curr->character[index] = make_shared<TrieNode>();
            }
            curr = curr->character[index];
        }
        curr->isEndOfWord = true;
    }

    bool search(const string& word) {
        auto curr = m_root;
        for (char ch : word) {
            size_t index = ch - 'a';
            if (!curr->character[index]) return false;
            curr = curr->character[index];
        }
        return curr->isEndOfWord;
    }

    void removeWord(const string& word) {
        m_root = removeWordHelper(word, m_root, 0);
    }
};

int main() {
    Trie trie;
    trie.insert("hel");
    trie.insert("hello");
    trie.removeWord("hel");
    cout << trie.search("hello") << '\n';
    return 0;
}

#include <iostream>
#include <memory>
#include <unordered_map>
#include <string>
using namespace std;

class Trie {
private:
    struct Node {
        unordered_map<char, unique_ptr<Node>> next;
        bool end = false;
    };

    unique_ptr<Node> root;

public:
    Trie() {
        root = make_unique<Node>();
    }

    void insert(const string& word) {
        Node* cur = root.get();
        for (char c : word) {
            if (!cur->next[c]) {
                cur->next[c] = make_unique<Node>();
            }
            cur = cur->next[c].get();
        }
        cur->end = true;
    }

    bool search(const string& word) {
        Node* cur = root.get();
        for (char c : word) {
            if (!cur->next.count(c)) return false;
            cur = cur->next[c].get();
        }
        return cur->end;
    }

    bool startsWith(const string& prefix) {
        Node* cur = root.get();
        for (char c : prefix) {
            if (!cur->next.count(c)) return false;
            cur = cur->next[c].get();
        }
        return true;
    }
};

int main() {
    Trie t;

    t.insert("apple");
    t.insert("app");
    t.insert("bat");

    cout << t.search("app") << endl;
    cout << t.search("apple") << endl;
    cout << t.search("appl") << endl;

    cout << t.startsWith("ap") << endl;
    cout << t.startsWith("ba") << endl;
    cout << t.startsWith("ca") << endl;

    return 0;
}

#include <array>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <memory>
#include <string>

using namespace std;

namespace data_structures {

class trie {
 private:
    static constexpr uint8_t NUM_CHARS = 26;
    array<shared_ptr<trie>, NUM_CHARS << 1> arr{};
    bool isEndofWord = false;

    uint8_t char_to_int(const char& ch) const {
        if (ch >= 'A' && ch <= 'Z') {
            return ch - 'A';
        } else if (ch >= 'a' && ch <= 'z') {
            return ch - 'a' + NUM_CHARS;
        }
        cerr << "Invalid character present. Exiting...";
        exit(EXIT_FAILURE);
        return 0;
    }

    bool search(const shared_ptr<trie>& root, const string& str, int index) {
        if (index == str.length()) {
            return root->isEndofWord;
        }
        int j = char_to_int(str[index]);
        if (!root->arr[j]) return false;
        return search(root->arr[j], str, index + 1);
    }

 public:
    trie() = default;

    void insert(const string& str) {
        shared_ptr<trie> root(nullptr);

        for (const char& ch : str) {
            int j = char_to_int(ch);
            if (root) {
                if (root->arr[j]) {
                    root = root->arr[j];
                } else {
                    auto temp = make_shared<trie>();
                    root->arr[j] = temp;
                    root = temp;
                }
            } else if (arr[j]) {
                root = arr[j];
            } else {
                auto temp = make_shared<trie>();
                arr[j] = temp;
                root = temp;
            }
        }
        root->isEndofWord = true;
    }

    bool search(const string& str, int index) {
        if (index == str.length()) {
            return isEndofWord;
        }
        int j = char_to_int(str[index]);
        if (!arr[j]) return false;
        return search(arr[j], str, index + 1);
    }

    bool deleteString(const string& str, int index) {
        if (index == str.length()) {
            if (!isEndofWord) return false;
            isEndofWord = false;
            return true;
        }
        int j = char_to_int(str[index]);
        if (!arr[j]) return false;

        bool var = deleteString(str, index + 1);
        if (var) {
            arr[j].reset();
            if (isEndofWord) {
                return false;
            } else {
                for (int i = 0; i < NUM_CHARS; i++) {
                    if (arr[i]) return false;
                }
                return true;
            }
        }

        cout << __func__ << ":" << __LINE__ << "Should not reach this line\n";
        return false;
    }
};

}  

static void test() {
    data_structures::trie root;
    root.insert("Hello");
    root.insert("World");

    assert(!root.search("hello", 0));
    cout << "hello - " << root.search("hello", 0) << "\n";

    assert(root.search("Hello", 0));
    cout << "Hello - " << root.search("Hello", 0) << "\n";

    assert(!root.search("Word", 0));
    cout << "Word - " << root.search("Word", 0) << "\n";

    assert(root.search("World", 0));
    cout << "World - " << root.search("World", 0) << "\n";
}

int main() {
    test();
    return 0;
}

