using namespace std;

namespace data_structures {

class trie {
 private:
    static constexpr uint8_t NUM_CHARS = 26;
    array<shared_ptr<trie>, NUM_CHARS << 1> arr{};
    bool isEndofWord = false;

    uint8_t char_to_int(const char& ch) const {
        if (ch >= 'A' && ch <= 'Z') return ch - 'A';
        else if (ch >= 'a' && ch <= 'z') return ch - 'a' + NUM_CHARS;

        cerr << "Invalid character present. Exiting...";
        exit(EXIT_FAILURE);
        return 0;
    }

    bool search(const shared_ptr<trie>& root, const string& str, int index) {
        if (index == str.length()) {
            return root->isEndofWord;
        }
        int j = char_to_int(str[index]);
        if (!root->arr[j]) return false;
        return search(root->arr[j], str, index + 1);
    }

 public:
    trie() = default;

    void insert(const string& str) {
        shared_ptr<trie> root(nullptr);

        for (const char& ch : str) {
            int j = char_to_int(ch);
            if (root) {
                if (root->arr[j]) {
                    root = root->arr[j];
                } else {
                    auto temp = make_shared<trie>();
                    root->arr[j] = temp;
                    root = temp;
                }
            } else if (arr[j]) {
                root = arr[j];
            } else {
                auto temp = make_shared<trie>();
                arr[j] = temp;
                root = temp;
            }
        }
        root->isEndofWord = true;
    }

    bool search(const string& str, int index) {
        if (index == str.length()) {
            return isEndofWord;
        }
        int j = char_to_int(str[index]);
        if (!arr[j]) return false;
        return search(arr[j], str, index + 1);
    }

    bool deleteString(const string& str, int index) {
        if (index == str.length()) {
            if (!isEndofWord) return false;
            isEndofWord = false;
            return true;
        }

        int j = char_to_int(str[index]);
        if (!arr[j]) return false;

        bool var = deleteString(str, index + 1);

        if (var) {
            arr[j].reset();

            if (isEndofWord) return false;

            for (int i = 0; i < NUM_CHARS; i++) {
                if (arr[i]) return false;
            }
            return true;
        }

        cout << __func__ << ":" << __LINE__ << "Should not reach this line\n";
        return false;
    }
};

}

