#include <iostream>
#include <string>
using namespace std;

struct Node {
    Node* child[26];
    bool end;

    Node() {
        end = false;
        for (int i = 0; i < 26; i++) child[i] = nullptr;
    }
};

class Trie {
private:
    Node* root;

public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        Node* cur = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!cur->child[idx]) {
                cur->child[idx] = new Node();
            }
            cur = cur->child[idx];
        }
        cur->end = true;
    }

    bool search(string word) {
        Node* cur = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!cur->child[idx]) return false;
            cur = cur->child[idx];
        }
        return cur->end;
    }

    bool startsWith(string prefix) {
        Node* cur = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!cur->child[idx]) return false;
            cur = cur->child[idx];
        }
        return true;
    }

    void remove(string word) {
        removeHelper(root, word, 0);
    }

private:
    bool removeHelper(Node* node, string& word, int depth) {
        if (!node) return false;

        if (depth == word.size()) {
            if (!node->end) return false;
            node->end = false;

            for (int i = 0; i < 26; i++)
                if (node->child[i]) return false;

            return true;
        }

        int idx = word[depth] - 'a';

        if (removeHelper(node->child[idx], word, depth + 1)) {
            delete node->child[idx];
            node->child[idx] = nullptr;

            if (!node->end) {
                for (int i = 0; i < 26; i++)
                    if (node->child[i]) return false;
                return true;
            }
        }

        return false;
    }
};

int main() {
    Trie t;

    t.insert("apple");
    t.insert("app");
    t.insert("bat");

    cout << t.search("app") << endl;
    cout << t.search("apple") << endl;

    t.remove("app");

    cout << t.search("app") << endl;
    cout << t.search("apple") << endl;

    cout << t.startsWith("ap") << endl;
    cout << t.startsWith("ba") << endl;

    return 0;
}

#include <cassert>
#include <iostream>
#include <memory>
#include <stack>
#include <unordered_map>
#include <vector>

using namespace std;

namespace data_structures {
namespace trie_using_hashmap {

class Trie {
 private:
    struct Node {
        unordered_map<char16_t, shared_ptr<Node>> children;
        bool word_end = false;
    };

    shared_ptr<Node> root_node = make_shared<Node>();

 public:
    Trie() = default;

    void insert(const string& word) {
        shared_ptr<Node> curr = root_node;
        for (char ch : word) {
            if (curr->children.find(ch) == curr->children.end()) {
                curr->children[ch] = make_shared<Node>();
            }
            curr = curr->children[ch];
        }
        if (!curr->word_end && curr != root_node) {
            curr->word_end = true;
        }
    }

    bool search(const string& word) {
        shared_ptr<Node> curr = root_node;
        for (char ch : word) {
            if (curr->children.find(ch) == curr->children.end()) {
                return false;
            }
            curr = curr->children[ch];
            if (!curr) return false;
        }
        return curr->word_end;
    }

    bool startwith(const string& prefix) {
        shared_ptr<Node> curr = root_node;
        for (char ch : prefix) {
            if (curr->children.find(ch) == curr->children.end()) {
                return false;
            }
            curr = curr->children[ch];
        }
        return true;
    }

    void delete_word(string word) {
        shared_ptr<Node> curr = root_node;
        stack<shared_ptr<Node>> nodes;

        for (char ch : word) {
            if (curr->children.find(ch) == curr->children.end()) return;
            nodes.push(curr->children[ch]);
            curr = curr->children[ch];
        }

        if (nodes.top()->word_end) {
            nodes.top()->word_end = false;
        }

        while (!nodes.empty() &&
               !nodes.top()->word_end &&
               nodes.top()->children.empty()) {

            nodes.pop();
            if (!nodes.empty()) {
                nodes.top()->children.erase(word.back());
                word.pop_back();
            }
        }
    }

    vector<string> get_all_words(vector<string> results,
                                const shared_ptr<Node>& element,
                                string prefix) {
        if (element->word_end) results.push_back(prefix);

        for (auto const& x : element->children) {
            prefix.push_back(static_cast<char>(x.first));
            results = get_all_words(results, x.second, prefix);
            prefix.pop_back();
        }

        return results;
    }

    vector<string> predict_words(const string& prefix) {
        vector<string> result;
        shared_ptr<Node> curr = root_node;

        for (char ch : prefix) {
            if (curr->children.find(ch) == curr->children.end()) {
                return result;
            }
            curr = curr->children[ch];
        }

        if (curr->word_end && curr->children.empty()) {
            result.push_back(prefix);
            return result;
        }

        return get_all_words(result, curr, prefix);
    }
};

}  
}

static void test() {
    data_structures::trie_using_hashmap::Trie obj;

    obj.insert("app");
    obj.insert("abscond");
    obj.insert("about");
    obj.insert("apps");
    obj.insert("apen");
    obj.insert("apples");
    obj.insert("apple");
    obj.insert("approach");
    obj.insert("bus");
    obj.insert("buses");
    obj.insert("Apple");
    obj.insert("Bounce");

    assert(!obj.search("appy"));
    cout << "appy is not a word in trie\n";

    assert(!obj.search("car"));
    cout << "car is not a word in trie\n";

    assert(obj.search("app"));
    assert(obj.search("apple"));

    cout << "All words exist\n";

    vector<string> pred = obj.predict_words("app");

    for (auto& s : pred) {
        cout << s << endl;
    }

    obj.delete_word("app");
    assert(!obj.search("app"));

    cout << "delete works\n";
}

int main() {
    test();
    return 0;
}

#include <iostream>
#include <unordered_map>
#include <string>
using namespace std;

struct Node {
    unordered_map<char, Node*> next;
    bool end;
    Node() {
        end = false;
    }
};

class Trie {
private:
    Node* root;

public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        Node* cur = root;
        for (char c : word) {
            if (!cur->next[c]) {
                cur->next[c] = new Node();
            }
            cur = cur->next[c];
        }
        cur->end = true;
    }

    bool search(string word) {
        Node* cur = root;
        for (char c : word) {
            if (!cur->next.count(c)) return false;
            cur = cur->next[c];
        }
        return cur->end;
    }

    bool startsWith(string prefix) {
        Node* cur = root;
        for (char c : prefix) {
            if (!cur->next.count(c)) return false;
            cur = cur->next[c];
        }
        return true;
    }

    void remove(string word) {
        removeHelper(root, word, 0);
    }

private:
    bool removeHelper(Node* node, string& word, int depth) {
        if (!node) return false;

        if (depth == word.size()) {
            if (!node->end) return false;
            node->end = false;
            return node->next.empty();
        }

        char c = word[depth];

        if (!node->next.count(c)) return false;

        if (removeHelper(node->next[c], word, depth + 1)) {
            delete node->next[c];
            node->next.erase(c);
            return !node->end && node->next.empty();
        }

        return false;
    }
};

int main() {
    Trie t;

    t.insert("hello");
    t.insert("hell");
    t.insert("heaven");
    t.insert("good");

    cout << t.search("hell") << endl;
    cout << t.search("hello") << endl;
    cout << t.search("he") << endl;

    cout << t.startsWith("he") << endl;
    cout << t.startsWith("goo") << endl;

    t.remove("hell");

    cout << t.search("hell") << endl;
    cout << t.search("hello") << endl;

    return 0;
}

/**
 * @file
 * @brief Well-formed [Generated
 * Parentheses](https://leetcode.com/explore/interview/card/top-interview-questions-medium/109/backtracking/794/) with all combinations.
 *
 * @details a sequence of parentheses is well-formed if each opening parentheses
 * has a corresponding closing parenthesis
 * and the closing parentheses are correctly ordered
 *
 * @author [Giuseppe Coco](https://github.com/WoWS17)

 */

#include <cassert>   /// for assert
#include <iostream>  /// for I/O operation
#include <vector>    /// for vector container

/**
 * @brief Backtracking algorithms
 * @namespace backtracking
 */
namespace backtracking {
/**
 * @brief generate_parentheses class
 */
class generate_parentheses {
 private:
    std::vector<std::string> res;  ///< Contains all possible valid patterns

    void makeStrings(std::string str, int n, int closed, int open);

 public:
    std::vector<std::string> generate(int n);
};

/**
 * @brief function that adds parenthesis to the string.
 *
 * @param str string build during backtracking
 * @param n number of pairs of parentheses
 * @param closed number of closed parentheses
 * @param open number of open parentheses
 */

void generate_parentheses::makeStrings(std::string str, int n,
                                                     int closed, int open) {
    if (closed > open)  // We can never have more closed than open
        return;

    if ((str.length() == 2 * n) &&
        (closed != open)) {  // closed and open must be the same
        return;
    }

    if (str.length() == 2 * n) {
        res.push_back(str);
        return;
    }

    makeStrings(str + ')', n, closed + 1, open);
    makeStrings(str + '(', n, closed, open + 1);
}

/**
 * @brief wrapper interface
 *
 * @param n number of pairs of parentheses
 * @return all well-formed pattern of parentheses
 */
std::vector<std::string> generate_parentheses::generate(int n) {
    backtracking::generate_parentheses::res.clear();
    std::string str = "(";
    generate_parentheses::makeStrings(str, n, 0, 1);
    return res;
}
}  // namespace backtracking

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    int n = 0;
    std::vector<std::string> patterns;
    backtracking::generate_parentheses p;

    n = 1;
    patterns = {{"()"}};
    assert(p.generate(n) == patterns);

    n = 3;
    patterns = {{"()()()"}, {"()(())"}, {"(())()"}, {"(()())"}, {"((()))"}};

    assert(p.generate(n) == patterns);

    n = 4;
    patterns = {{"()()()()"}, {"()()(())"}, {"()(())()"}, {"()(()())"},
                {"()((()))"}, {"(())()()"}, {"(())(())"}, {"(()())()"},
                {"(()()())"}, {"(()(()))"}, {"((()))()"}, {"((())())"},
                {"((()()))"}, {"(((())))"}};
    assert(p.generate(n) == patterns);

    std::cout << "All tests passed\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Builds every balanced parenthesis combination for a given pair
 * count, following the classic backtracking recursion tree.
 *
 * @details A parenthesis string is balanced when every '(' has a matching
 * ')' later in the string and, at any prefix, the count of ')' never
 * exceeds the count of '('.
 */

#include <cassert>   /// for assert()
#include <iostream>  /// for std::cout
#include <string>    /// for std::string
#include <vector>    /// for std::vector

namespace backtracking {
namespace paren_builder {

/**
 * @brief Encapsulates the recursive search for balanced parenthesis
 * combinations of a fixed pair count.
 */
class BalancedParenGenerator {
 public:
    std::vector<std::string> build(int pairCount);

 private:
    std::vector<std::string> collected;  ///< accumulated balanced strings

    void expand(const std::string &partial, int pairCount, int closedCount,
                int openCount);
};

/**
 * @brief Recursively appends '(' or ')' to a partial candidate and prunes
 * branches that can never yield a balanced result.
 * @param partial string assembled so far along this branch
 * @param pairCount target number of parenthesis pairs
 * @param closedCount how many ')' appear in partial
 * @param openCount how many '(' appear in partial
 */
void BalancedParenGenerator::expand(const std::string &partial, int pairCount,
                                     int closedCount, int openCount) {
    if (closedCount > openCount) {
        // A closing bracket without a matching opener - dead branch.
        return;
    }

    const std::size_t target = static_cast<std::size_t>(2 * pairCount);

    if (partial.length() == target) {
        if (closedCount == openCount) {
            collected.push_back(partial);
        }
        return;
    }

    expand(partial + ')', pairCount, closedCount + 1, openCount);
    expand(partial + '(', pairCount, closedCount, openCount + 1);
}

/**
 * @brief Public entry point that kicks off the recursive search.
 * @param pairCount number of parenthesis pairs requested
 * @return every balanced combination for that pair count
 */
std::vector<std::string> BalancedParenGenerator::build(int pairCount) {
    collected.clear();
    expand("(", pairCount, 0, 1);
    return collected;
}

}  // namespace paren_builder
}  // namespace backtracking

/**
 * @brief Runs a handful of known-good cases against the generator.
 */
static void runSelfChecks() {
    backtracking::paren_builder::BalancedParenGenerator generator;
    std::vector<std::string> expected;

    expected = {"()"};
    assert(generator.build(1) == expected);

    expected = {"()()()", "()(())", "(())()", "(()())", "((()))"};
    assert(generator.build(3) == expected);

    expected = {"()()()()", "()()(())", "()(())()", "()(()())",
                "()((()))", "(())()()", "(())(())", "(()())()",
                "(()()())", "(()(()))", "((()))()", "((())())",
                "((()()))", "(((())))"};
    assert(generator.build(4) == expected);

    std::cout << "generate_parentheses: all self checks passed\n";
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief prints the assigned colors
 * using [Graph Coloring](https://en.wikipedia.org/wiki/Graph_coloring)
 * algorithm
 *
 * @details
 * In graph theory, graph coloring is a special case of graph labeling;
 * it is an assignment of labels traditionally called "colors" to elements of a
 * graph subject to certain constraints. In its simplest form, it is a way of
 * coloring the vertices of a graph such that no two adjacent vertices are of
 * the same color; this is called a vertex coloring. Similarly, an edge coloring
 * assigns a color to each edge so that no two adjacent edges are of the same
 * color, and a face coloring of a planar graph assigns a color to each face or
 * region so that no two faces that share a boundary have the same color.
 *
 * @author [Anup Kumar Panwar](https://github.com/AnupKumarPanwar)
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <array>     /// for std::array
#include <iostream>  /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace graph_coloring
 * @brief Functions for the [Graph
 * Coloring](https://en.wikipedia.org/wiki/Graph_coloring) algorithm,
 */
namespace graph_coloring {
/**
 * @brief A utility function to print the solution
 * @tparam V number of vertices in the graph
 * @param color array of colors assigned to the nodes
 */
template <size_t V>
void printSolution(const std::array<int, V>& color) {
    std::cout << "Following are the assigned colors\n";
    for (auto& col : color) {
        std::cout << col;
    }
    std::cout << "\n";
}

/**
 * @brief Utility function to check if the current color assignment is safe for
 * vertex v
 * @tparam V number of vertices in the graph
 * @param v index of graph vertex to check
 * @param graph matrix of graph nonnectivity
 * @param color vector of colors assigned to the graph nodes/vertices
 * @param c color value to check for the node `v`
 * @returns `true` if the color is safe to be assigned to the node
 * @returns `false` if the color is not safe to be assigned to the node
 */
template <size_t V>
bool isSafe(int v, const std::array<std::array<int, V>, V>& graph,
            const std::array<int, V>& color, int c) {
    for (int i = 0; i < V; i++) {
        if (graph[v][i] && c == color[i]) {
            return false;
        }
    }
    return true;
}

/**
 * @brief Recursive utility function to solve m coloring problem
 * @tparam V number of vertices in the graph
 * @param graph matrix of graph nonnectivity
 * @param m number of colors
 * @param [in,out] color description // used in,out to notify in documentation
 * that this parameter gets modified by the function
 * @param v index of graph vertex to check
 */
template <size_t V>
void graphColoring(const std::array<std::array<int, V>, V>& graph, int m,
                   std::array<int, V> color, int v) {
    // base case:
    // If all vertices are assigned a color then return true
    if (v == V) {
        printSolution<V>(color);
        return;
    }

    // Consider this vertex v and try different colors
    for (int c = 1; c <= m; c++) {
        // Check if assignment of color c to v is fine
        if (isSafe<V>(v, graph, color, c)) {
            color[v] = c;

            // recur to assign colors to rest of the vertices
            graphColoring<V>(graph, m, color, v + 1);

            // If assigning color c doesn't lead to a solution then remove it
            color[v] = 0;
        }
    }
}
}  // namespace graph_coloring
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Create following graph and test whether it is 3 colorable
    // (3)---(2)
    // |   / |
    // |  /  |
    // | /   |
    // (0)---(1)

    const int V = 4;  // number of vertices in the graph
    std::array<std::array<int, V>, V> graph = {
        std::array<int, V>({0, 1, 1, 1}), std::array<int, V>({1, 0, 1, 0}),
        std::array<int, V>({1, 1, 0, 1}), std::array<int, V>({1, 0, 1, 0})};

    int m = 3;  // Number of colors
    std::array<int, V> color{};

    backtracking::graph_coloring::graphColoring<V>(graph, m, color, 0);
    return 0;
}

/**
 * @file
 * @brief Assigns colors to graph vertices such that no edge connects two
 * same-colored vertices, using exhaustive backtracking (m-coloring
 * problem).
 *
 * @details Vertex coloring labels each node so that adjacent nodes never
 * share a label. This file walks every vertex in order and tries each
 * available color, backing off whenever a conflict with an already-colored
 * neighbor is found.
 */

#include <array>     /// for std::array
#include <iostream>  /// for std::cout

namespace backtracking {
namespace vertex_coloring {

/**
 * @brief Dumps the final color assigned to each vertex.
 * @tparam N number of vertices
 * @param labels color chosen per vertex
 */
template <size_t N>
void showAssignment(const std::array<int, N> &labels) {
    std::cout << "Vertex color assignment:\n";
    for (auto label : labels) {
        std::cout << label;
    }
    std::cout << "\n";
}

/**
 * @brief Determines whether coloring vertex `vertex` with `candidateColor`
 * conflicts with any already-colored neighbor.
 * @tparam N number of vertices
 * @param vertex vertex under consideration
 * @param adjacency adjacency matrix of the graph
 * @param labels colors assigned so far
 * @param candidateColor color being tested
 * @returns true when no adjacent vertex already uses candidateColor
 */
template <size_t N>
bool noConflict(int vertex, const std::array<std::array<int, N>, N> &adjacency,
                 const std::array<int, N> &labels, int candidateColor) {
    int neighbor = 0;
    while (neighbor < static_cast<int>(N)) {
        if (adjacency[vertex][neighbor] && labels[neighbor] == candidateColor) {
            return false;
        }
        ++neighbor;
    }
    return true;
}

/**
 * @brief Recursively tries to extend a partial coloring to cover the
 * remaining vertices.
 * @tparam N number of vertices
 * @param adjacency adjacency matrix of the graph
 * @param colorBudget how many distinct colors may be used
 * @param labels colors assigned so far (passed by value for easy undo)
 * @param vertex next vertex to color
 */
template <size_t N>
void colorFrom(const std::array<std::array<int, N>, N> &adjacency,
               int colorBudget, std::array<int, N> labels, int vertex) {
    if (vertex == static_cast<int>(N)) {
        // Every vertex received a color without conflict - report it.
        showAssignment<N>(labels);
        return;
    }

    for (int candidate = 1; candidate <= colorBudget; ++candidate) {
        if (noConflict<N>(vertex, adjacency, labels, candidate)) {
            labels[vertex] = candidate;
            colorFrom<N>(adjacency, colorBudget, labels, vertex + 1);
            labels[vertex] = 0;  // undo before trying next candidate color
        }
    }
}

}  // namespace vertex_coloring
}  // namespace backtracking

int main() {
    // Graph layout under test:
    // (3)---(2)
    // |   / |
    // |  /  |
    // | /   |
    // (0)---(1)
    constexpr int totalVertices = 4;
    std::array<std::array<int, totalVertices>, totalVertices> adjacency = {
        std::array<int, totalVertices>({0, 1, 1, 1}),
        std::array<int, totalVertices>({1, 0, 1, 0}),
        std::array<int, totalVertices>({1, 1, 0, 1}),
        std::array<int, totalVertices>({1, 0, 1, 0})};

    const int availableColors = 3;
    std::array<int, totalVertices> labels{};

    backtracking::vertex_coloring::colorFrom<totalVertices>(
        adjacency, availableColors, labels, 0);
    return 0;
}

/**
 * @file
 * @brief [Knight's tour](https://en.wikipedia.org/wiki/Knight%27s_tour)
 * algorithm
 *
 * @details
 * A knight's tour is a sequence of moves of a knight on a chessboard
 * such that the knight visits every square only once. If the knight
 * ends on a square that is one knight's move from the beginning
 * square (so that it could tour the board again immediately, following
 * the same path, the tour is closed; otherwise, it is open.
 *
 * @author [Nikhil Arora](https://github.com/nikhilarora068)
 * @author [David Leal](https://github.com/Panquesito7)
 */
#include <array>     /// for std::array
#include <iostream>  /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace knight_tour
 * @brief Functions for the [Knight's
 * tour](https://en.wikipedia.org/wiki/Knight%27s_tour) algorithm
 */
namespace knight_tour {
/**
 * A utility function to check if i,j are valid indexes for N*N chessboard
 * @tparam V number of vertices in array
 * @param x current index in rows
 * @param y current index in columns
 * @param sol matrix where numbers are saved
 * @returns `true` if ....
 * @returns `false` if ....
 */
template <size_t V>
bool issafe(int x, int y, const std::array<std::array<int, V>, V> &sol) {
    return (x < V && x >= 0 && y < V && y >= 0 && sol[x][y] == -1);
}

/**
 * Knight's tour algorithm
 * @tparam V number of vertices in array
 * @param x current index in rows
 * @param y current index in columns
 * @param mov movement to be done
 * @param sol matrix where numbers are saved
 * @param xmov next move of knight (x coordinate)
 * @param ymov next move of knight (y coordinate)
 * @returns `true` if solution exists
 * @returns `false` if solution does not exist
 */
template <size_t V>
bool solve(int x, int y, int mov, std::array<std::array<int, V>, V> &sol,
           const std::array<int, V> &xmov, std::array<int, V> &ymov) {
    int k = 0, xnext = 0, ynext = 0;

    if (mov == V * V) {
        return true;
    }

    for (k = 0; k < V; k++) {
        xnext = x + xmov[k];
        ynext = y + ymov[k];

        if (issafe<V>(xnext, ynext, sol)) {
            sol[xnext][ynext] = mov;

            if (solve<V>(xnext, ynext, mov + 1, sol, xmov, ymov) == true) {
                return true;
            } else {
                sol[xnext][ynext] = -1;
            }
        }
    }
    return false;
}
}  // namespace knight_tour
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    const int n = 8;
    std::array<std::array<int, n>, n> sol = {0};

    int i = 0, j = 0;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            sol[i][j] = -1;
        }
    }

    std::array<int, n> xmov = {2, 1, -1, -2, -2, -1, 1, 2};
    std::array<int, n> ymov = {1, 2, 2, 1, -1, -2, -2, -1};

    sol[0][0] = 0;

    bool flag = backtracking::knight_tour::solve<n>(0, 0, 1, sol, xmov, ymov);
    if (flag == false) {
        std::cout << "Error: Solution does not exist\n";
    } else {
        for (i = 0; i < n; i++) {
            for (j = 0; j < n; j++) {
                std::cout << sol[i][j] << "  ";
            }
            std::cout << "\n";
        }
    }
    return 0;
}

/**
 * @file
 * @brief Finds a closed/open [Knight's
 * tour](https://en.wikipedia.org/wiki/Knight%27s_tour) across an N by N
 * chessboard via depth-first backtracking.
 *
 * @details Starting from a fixed square, the knight repeatedly attempts
 * each of its eight legal jump offsets, marking the destination square
 * with a move index and recursing. When a branch runs out of legal moves
 * before every square is visited, the last move is undone and the next
 * offset is tried.
 */
#include <array>     /// for std::array
#include <iostream>  /// for std::cout

namespace backtracking {
namespace knight_journey {

/**
 * @brief Tells whether (row, col) lies on the board and is still
 * unvisited.
 * @tparam Side board dimension
 * @param row candidate row
 * @param col candidate column
 * @param visited board where each cell holds its visit order, or -1
 * @returns true when the square is on-board and unvisited
 */
template <size_t Side>
bool isFreeSquare(int row, int col,
                   const std::array<std::array<int, Side>, Side> &visited) {
    return row >= 0 && row < static_cast<int>(Side) && col >= 0 &&
           col < static_cast<int>(Side) && visited[row][col] == -1;
}

/**
 * @brief Attempts to complete a full knight's tour from (row, col) having
 * already made `stepNumber` moves.
 * @tparam Side board dimension
 * @param row current row of the knight
 * @param col current column of the knight
 * @param stepNumber number of squares visited so far
 * @param visited board recording visit order per square
 * @param rowOffsets the 8 possible row deltas for a knight jump
 * @param colOffsets the 8 possible column deltas for a knight jump
 * @returns true once every square has been visited
 */
template <size_t Side>
bool tourFrom(int row, int col, int stepNumber,
              std::array<std::array<int, Side>, Side> &visited,
              const std::array<int, Side> &rowOffsets,
              std::array<int, Side> &colOffsets) {
    if (stepNumber == static_cast<int>(Side * Side)) {
        return true;
    }

    int candidateIndex = 0;
    while (candidateIndex < static_cast<int>(Side)) {
        int nextRow = row + rowOffsets[candidateIndex];
        int nextCol = col + colOffsets[candidateIndex];

        if (isFreeSquare<Side>(nextRow, nextCol, visited)) {
            visited[nextRow][nextCol] = stepNumber;

            if (tourFrom<Side>(nextRow, nextCol, stepNumber + 1, visited,
                                rowOffsets, colOffsets)) {
                return true;
            }
            // Dead end further down this path - undo and try another jump.
            visited[nextRow][nextCol] = -1;
        }
        ++candidateIndex;
    }
    return false;
}

}  // namespace knight_journey
}  // namespace backtracking

int main() {
    const int boardSide = 8;
    std::array<std::array<int, boardSide>, boardSide> visited{};

    for (int r = 0; r < boardSide; ++r) {
        for (int c = 0; c < boardSide; ++c) {
            visited[r][c] = -1;
        }
    }

    std::array<int, boardSide> rowOffsets = {2, 1, -1, -2, -2, -1, 1, 2};
    std::array<int, boardSide> colOffsets = {1, 2, 2, 1, -1, -2, -2, -1};

    visited[0][0] = 0;

    bool found = backtracking::knight_journey::tourFrom<boardSide>(
        0, 0, 1, visited, rowOffsets, colOffsets);

    if (!found) {
        std::cout << "Error: no knight's tour exists from this start\n";
    } else {
        for (int r = 0; r < boardSide; ++r) {
            for (int c = 0; c < boardSide; ++c) {
                std::cout << visited[r][c] << "  ";
            }
            std::cout << "\n";
        }
    }
    return 0;
}

/*
 * @brief [Magic sequence](https://www.csplib.org/Problems/prob019/)
 * implementation
 *
 * @details Solve the magic sequence problem with backtracking
 *
 * "A magic sequence of length $n$ is a sequence of integers $x_0
 * \ldots x_{n-1}$ between $0$ and $n-1$, such that for all $i$
 * in $0$ to $n-1$, the number $i$ occurs exactly $x_i$ times in
 * the sequence. For instance, $6,2,1,0,0,0,1,0,0,0$ is a magic
 * sequence since $0$ occurs $6$ times in it, $1$ occurs twice, etc."
 * Quote taken from the [CSPLib](https://www.csplib.org/Problems/prob019/)
 * website
 *
 * @author [Jxtopher](https://github.com/Jxtopher)
 */

#include <algorithm>  /// for std::count
#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <list>       /// for std::list
#include <numeric>    /// for std::accumulate
#include <vector>     /// for std::vector

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace magic_sequence
 * @brief Functions for the [Magic
 * sequence](https://www.csplib.org/Problems/prob019/) implementation
 */
namespace magic_sequence {
using sequence_t =
    std::vector<unsigned int>;  ///< Definition of the sequence type
/**
 * @brief Print the magic sequence
 * @param s working memory for the sequence
 */
void print(const sequence_t& s) {
    for (const auto& item : s) std::cout << item << " ";
    std::cout << std::endl;
}

/**
 * @brief Check if the sequence is magic
 * @param s working memory for the sequence
 * @returns true if it's a magic sequence
 * @returns false if it's NOT a magic sequence
 */
bool is_magic(const sequence_t& s) {
    for (unsigned int i = 0; i < s.size(); i++) {
        if (std::count(s.cbegin(), s.cend(), i) != s[i]) {
            return false;
        }
    }
    return true;
}

/**
 * @brief Sub-solutions filtering
 * @param s working memory for the sequence
 * @param depth current depth in tree
 * @returns true if the sub-solution is valid
 * @returns false if the sub-solution is NOT valid
 */
bool filtering(const sequence_t& s, unsigned int depth) {
    return std::accumulate(s.cbegin(), s.cbegin() + depth,
                           static_cast<unsigned int>(0)) <= s.size();
}

/**
 * @brief Solve the Magic Sequence problem
 * @param s working memory for the sequence
 * @param ret list of the valid magic sequences
 * @param depth current depth in the tree
 */
void solve(sequence_t* s, std::list<sequence_t>* ret, unsigned int depth = 0) {
    if (depth == s->size()) {
        if (is_magic(*s)) {
            ret->push_back(*s);
        }
    } else {
        for (unsigned int i = 0; i < s->size(); i++) {
            (*s)[depth] = i;
            if (filtering(*s, depth + 1)) {
                solve(s, ret, depth + 1);
            }
        }
    }
}

}  // namespace magic_sequence
}  // namespace backtracking

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // test a valid magic sequence
    backtracking::magic_sequence::sequence_t s_magic = {6, 2, 1, 0, 0,
                                                        0, 1, 0, 0, 0};
    assert(backtracking::magic_sequence::is_magic(s_magic));

    // test a non-valid magic sequence
    backtracking::magic_sequence::sequence_t s_not_magic = {5, 2, 1, 0, 0,
                                                            0, 1, 0, 0, 0};
    assert(!backtracking::magic_sequence::is_magic(s_not_magic));
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations

    // solve magic sequences of size 2 to 11 and print the solutions
    for (unsigned int i = 2; i < 12; i++) {
        std::cout << "Solution for n = " << i << std::endl;
        // valid magic sequence list
        std::list<backtracking::magic_sequence::sequence_t> list_of_solutions;
        // initialization of a sequence
        backtracking::magic_sequence::sequence_t s1(i, i);
        // launch of solving the problem
        backtracking::magic_sequence::solve(&s1, &list_of_solutions);
        // print solutions
        for (const auto& item : list_of_solutions) {
            backtracking::magic_sequence::print(item);
        }
    }
    return 0;
}

/*
 * @brief Backtracking solver for the [magic
 * sequence](https://www.csplib.org/Problems/prob019/) constraint problem.
 *
 * @details A magic sequence of length n is a list of n integers, each
 * between 0 and n-1, where value i appears in the sequence exactly as
 * many times as the number stored at position i. Example: for
 * 6,2,1,0,0,0,1,0,0,0 the value 0 shows up six times, 1 shows up twice,
 * and so on, matching each position's own entry.
 */

#include <algorithm>  /// for std::count
#include <cassert>    /// for assert
#include <iostream>   /// for std::cout
#include <list>       /// for std::list
#include <numeric>    /// for std::accumulate
#include <vector>     /// for std::vector

namespace backtracking {
namespace magic_seq_solver {

using Digits = std::vector<unsigned int>;  ///< alias for a candidate sequence

/**
 * @brief Writes a sequence to standard output, space separated.
 * @param seq sequence to display
 */
void display(const Digits &seq) {
    for (const auto &value : seq) {
        std::cout << value << " ";
    }
    std::cout << std::endl;
}

/**
 * @brief Verifies the magic property holds across the whole sequence:
 * value i must occur exactly seq[i] times.
 * @param seq candidate sequence
 * @returns true if seq satisfies the magic sequence property
 */
bool satisfiesMagicProperty(const Digits &seq) {
    unsigned int probe = 0;
    while (probe < seq.size()) {
        if (std::count(seq.cbegin(), seq.cend(), probe) != seq[probe]) {
            return false;
        }
        ++probe;
    }
    return true;
}

/**
 * @brief Cheap early-exit pruning check: the sum of values fixed so far
 * can never legitimately exceed the sequence length.
 * @param seq partially filled sequence
 * @param filledUpTo how many leading positions have been assigned
 * @returns true if the partial assignment could still lead to a solution
 */
bool withinBudget(const Digits &seq, unsigned int filledUpTo) {
    unsigned int runningTotal = std::accumulate(
        seq.cbegin(), seq.cbegin() + filledUpTo, static_cast<unsigned int>(0));
    return runningTotal <= seq.size();
}

/**
 * @brief Recursively assigns a value to each position of the sequence,
 * pruning branches that can no longer satisfy the magic property.
 * @param seq working buffer being filled in place
 * @param solutions accumulator for every valid magic sequence found
 * @param position index currently being assigned
 */
void search(Digits *seq, std::list<Digits> *solutions,
            unsigned int position = 0) {
    if (position == seq->size()) {
        if (satisfiesMagicProperty(*seq)) {
            solutions->push_back(*seq);
        }
        return;
    }

    unsigned int candidate = 0;
    while (candidate < seq->size()) {
        (*seq)[position] = candidate;
        if (withinBudget(*seq, position + 1)) {
            search(seq, solutions, position + 1);
        }
        ++candidate;
    }
}

}  // namespace magic_seq_solver
}  // namespace backtracking

/**
 * @brief Sanity-checks the magic property predicate against a known-good
 * and a known-bad sequence.
 */
static void runSelfChecks() {
    backtracking::magic_seq_solver::Digits validSeq = {6, 2, 1, 0, 0,
                                                        0, 1, 0, 0, 0};
    assert(backtracking::magic_seq_solver::satisfiesMagicProperty(validSeq));

    backtracking::magic_seq_solver::Digits brokenSeq = {5, 2, 1, 0, 0,
                                                         0, 1, 0, 0, 0};
    assert(!backtracking::magic_seq_solver::satisfiesMagicProperty(brokenSeq));
}

int main() {
    runSelfChecks();

    for (unsigned int length = 2; length < 12; ++length) {
        std::cout << "Solution for n = " << length << std::endl;

        std::list<backtracking::magic_seq_solver::Digits> foundSolutions;
        backtracking::magic_seq_solver::Digits seed(length, length);

        backtracking::magic_seq_solver::search(&seed, &foundSolutions);

        for (const auto &solution : foundSolutions) {
            backtracking::magic_seq_solver::display(solution);
        }
    }
    return 0;
}

/**
 * @file
 * @brief returns which is the longest/shortest number
 * using [minimax](https://en.wikipedia.org/wiki/Minimax) algorithm
 *
 * @details
 * Minimax (sometimes MinMax, MM or saddle point) is a decision rule used in
 * artificial intelligence, decision theory, game theory, statistics,
 * and philosophy for minimizing the possible loss for a worst case (maximum
 * loss) scenario. When dealing with gains, it is referred to as "maximin"—to
 * maximize the minimum gain. Originally formulated for two-player zero-sum game
 * theory, covering both the cases where players take alternate moves and those
 * where they make simultaneous moves, it has also been extended to more complex
 * games and to general decision-making in the presence of uncertainty.
 *
 * @author [Gleison Batista](https://github.com/gleisonbs)
 * @author [David Leal](https://github.com/Panquesito7)
 */
#include <algorithm>  /// for std::max, std::min
#include <array>      /// for std::array
#include <cmath>      /// for log2
#include <iostream>   /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @brief Check which is the maximum/minimum number in the array
 * @param depth current depth in game tree
 * @param node_index current index in array
 * @param is_max if current index is the longest number
 * @param scores saved numbers in array
 * @param height maximum height for game tree
 * @returns the maximum or minimum number
 */
template <size_t T>
int minimax(int depth, int node_index, bool is_max,
            const std::array<int, T> &scores, double height) {
    if (depth == height) {
        return scores[node_index];
    }

    int v1 = minimax(depth + 1, node_index * 2, !is_max, scores, height);
    int v2 = minimax(depth + 1, node_index * 2 + 1, !is_max, scores, height);

    return is_max ? std::max(v1, v2) : std::min(v1, v2);
}
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    std::array<int, 8> scores = {90, 23, 6, 33, 21, 65, 123, 34423};
    double height = log2(scores.size());

    std::cout << "Optimal value: "
              << backtracking::minimax(0, 0, true, scores, height) << std::endl;
    return 0;
}

/**
 * @file
 * @brief Picks the optimal leaf value from a game tree using the
 * [minimax](https://en.wikipedia.org/wiki/Minimax) decision rule.
 *
 * @details Minimax alternates between a maximizing player and a
 * minimizing player as it descends a game tree, ultimately propagating
 * back the best achievable outcome assuming perfect play from both
 * sides. This implementation walks a complete binary tree stored as a
 * flat array of leaf scores.
 */
#include <algorithm>  /// for std::max, std::min
#include <array>      /// for std::array
#include <cmath>      /// for std::log2
#include <iostream>   /// for std::cout

namespace backtracking {

/**
 * @brief Recursively evaluates the game tree, alternating between
 * maximizing and minimizing at each level, until the leaf level is
 * reached.
 * @tparam LeafCount number of leaf scores in the array
 * @param level current depth in the tree, 0 at the root
 * @param leafIndex index into the conceptual leaf array for this branch
 * @param maximizing true when this level picks the larger child value
 * @param leafScores flat array holding every leaf's score
 * @param treeHeight depth at which leaves are found
 * @returns the backed-up optimal value for this branch
 */
template <size_t LeafCount>
int evaluate(int level, int leafIndex, bool maximizing,
             const std::array<int, LeafCount> &leafScores, double treeHeight) {
    if (level == treeHeight) {
        return leafScores[leafIndex];
    }

    int leftBranch =
        evaluate(level + 1, leafIndex * 2, !maximizing, leafScores, treeHeight);
    int rightBranch = evaluate(level + 1, leafIndex * 2 + 1, !maximizing,
                                leafScores, treeHeight);

    return maximizing ? std::max(leftBranch, rightBranch)
                       : std::min(leftBranch, rightBranch);
}

}  // namespace backtracking

int main() {
    std::array<int, 8> leafScores = {90, 23, 6, 33, 21, 65, 123, 34423};
    double treeHeight = std::log2(leafScores.size());

    std::cout << "Optimal value: "
              << backtracking::evaluate(0, 0, true, leafScores, treeHeight)
              << std::endl;
    return 0;
}

/**
 * @file
 * @brief [Eight Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle)
 * puzzle
 *
 * @details
 * The **eight queens puzzle** is the problem of placing eight chess queens on
 * an 8×8 chessboard so that no two queens threaten each other; thus, a solution
 * requires that no two queens share the same row, column, or diagonal. The
 * eight queens puzzle is an example of the more general **n queens problem** of
 * placing n non-attacking queens on an n×n chessboard, for which solutions
 * exist for all natural numbers n with the exception of n = 2 and n = 3.
 *
 * @author Unknown author
 * @author [David Leal](https://github.com/Panquesito7)
 *
 */
#include <array>
#include <iostream>

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace n_queens
 * @brief Functions for [Eight
 * Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle) puzzle.
 */
namespace n_queens {
/**
 * Utility function to print matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 */
template <size_t n>
void printSolution(const std::array<std::array<int, n>, n> &board) {
    std::cout << "\n";
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << "" << board[i][j] << " ";
        }
        std::cout << "\n";
    }
}

/**
 * Check if a queen can be placed on matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param row current index in rows
 * @param col current index in columns
 * @returns `true` if queen can be placed on matrix
 * @returns `false` if queen can't be placed on matrix
 */
template <size_t n>
bool isSafe(const std::array<std::array<int, n>, n> &board, const int &row,
            const int &col) {
    int i = 0, j = 0;

    // Check this row on left side
    for (i = 0; i < col; i++) {
        if (board[row][i]) {
            return false;
        }
    }

    // Check upper diagonal on left side
    for (i = row, j = col; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j]) {
            return false;
        }
    }
    // Check lower diagonal on left side
    for (i = row, j = col; j >= 0 && i < n; i++, j--) {
        if (board[i][j]) {
            return false;
        }
    }
    return true;
}

/**
 * Solve n queens problem
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param col current index in columns
 */
template <size_t n>
void solveNQ(std::array<std::array<int, n>, n> board, const int &col) {
    if (col >= n) {
        printSolution<n>(board);
        return;
    }

    // Consider this column and try placing
    // this queen in all rows one by one
    for (int i = 0; i < n; i++) {
        // Check if queen can be placed
        // on board[i][col]
        if (isSafe<n>(board, i, col)) {
            // Place this queen in matrix
            board[i][col] = 1;

            // Recursive to place rest of the queens
            solveNQ<n>(board, col + 1);

            board[i][col] = 0;  // backtrack
        }
    }
}
}  // namespace n_queens
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    const int n = 4;
    std::array<std::array<int, n>, n> board = {
        std::array<int, n>({0, 0, 0, 0}), std::array<int, n>({0, 0, 0, 0}),
        std::array<int, n>({0, 0, 0, 0}), std::array<int, n>({0, 0, 0, 0})};

    backtracking::n_queens::solveNQ<n>(board, 0);
    return 0;
}

/**
 * @file
 * @brief Solves the [N
 * Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle) puzzle by
 * placing queens column by column and backtracking on attacks.
 *
 * @details Queens must be placed so that none shares a row, column, or
 * diagonal with another. This version fills the board one column at a
 * time, testing every row in that column before moving to the next
 * column, undoing a placement whenever the remaining columns cannot be
 * completed.
 */
#include <array>
#include <iostream>

namespace backtracking {
namespace queens_puzzle {

/**
 * @brief Prints the current board layout, one row per line.
 * @tparam Size board dimension
 * @param board occupancy grid, 1 where a queen sits
 */
template <size_t Size>
void dumpBoard(const std::array<std::array<int, Size>, Size> &board) {
    std::cout << "\n";
    for (size_t row = 0; row < Size; ++row) {
        for (size_t col = 0; col < Size; ++col) {
            std::cout << "" << board[row][col] << " ";
        }
        std::cout << "\n";
    }
}

/**
 * @brief Checks whether a queen may be dropped at (targetRow, targetCol)
 * without being attacked by any queen already placed in earlier columns.
 * @tparam Size board dimension
 * @param board occupancy grid so far
 * @param targetRow row being considered
 * @param targetCol column being considered
 * @returns true if the square is free of attacks
 */
template <size_t Size>
bool isAttackFree(const std::array<std::array<int, Size>, Size> &board,
                   const int &targetRow, const int &targetCol) {
    // Scan leftwards along the same row.
    for (int col = 0; col < targetCol; ++col) {
        if (board[targetRow][col]) {
            return false;
        }
    }

    // Scan the upper-left diagonal.
    int r = targetRow, c = targetCol;
    while (r >= 0 && c >= 0) {
        if (board[r][c]) {
            return false;
        }
        --r;
        --c;
    }

    // Scan the lower-left diagonal.
    r = targetRow;
    c = targetCol;
    while (c >= 0 && r < static_cast<int>(Size)) {
        if (board[r][c]) {
            return false;
        }
        ++r;
        --c;
    }

    return true;
}

/**
 * @brief Recursively places one queen per column, backtracking whenever
 * a placement leads to a dead end.
 * @tparam Size board dimension
 * @param board occupancy grid, passed by value so backtracking is free
 * @param col column currently being filled
 */
template <size_t Size>
void placeQueensFrom(std::array<std::array<int, Size>, Size> board,
                      const int &col) {
    if (col >= static_cast<int>(Size)) {
        dumpBoard<Size>(board);
        return;
    }

    for (int row = 0; row < static_cast<int>(Size); ++row) {
        if (isAttackFree<Size>(board, row, col)) {
            board[row][col] = 1;

            placeQueensFrom<Size>(board, col + 1);

            board[row][col] = 0;  // backtrack: undo before trying next row
        }
    }
}

}  // namespace queens_puzzle
}  // namespace backtracking

int main() {
    const int boardSize = 4;
    std::array<std::array<int, boardSize>, boardSize> board = {
        std::array<int, boardSize>({0, 0, 0, 0}),
        std::array<int, boardSize>({0, 0, 0, 0}),
        std::array<int, boardSize>({0, 0, 0, 0}),
        std::array<int, boardSize>({0, 0, 0, 0})};

    backtracking::queens_puzzle::placeQueensFrom<boardSize>(board, 0);
    return 0;
}

/**
 * @file
 * @brief [N queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle) all
 * optimized
 *
 * @author [Sombit Bose](https://github.com/deadshotsb)
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <array>
#include <iostream>

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace n_queens_optimized
 * @brief Functions for [Eight
 * Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle) puzzle optimized.
 */
namespace n_queens_optimized {
/**
 * Utility function to print matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 */
template <size_t n>
void PrintSol(const std::array<std::array<int, n>, n> &board) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << board[i][j] << " ";
        }
        std::cout << std::endl;
    }
    std::cout << std::endl;
    if (n % 2 == 0 || (n % 2 == 1 && board[n / 2 + 1][0] != 1)) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                std::cout << board[j][i] << " ";
            }
            std::cout << std::endl;
        }
        std::cout << std::endl;
    }
}

/**
 * Check if a queen can be placed on matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param row current index in rows
 * @param col current index in columns
 * @returns `true` if queen can be placed on matrix
 * @returns `false` if queen can't be placed on matrix
 */
template <size_t n>
bool CanIMove(const std::array<std::array<int, n>, n> &board, int row,
              int col) {
    /// check in the row
    for (int i = 0; i <= col; i++) {
        if (board[row][i] == 1) {
            return false;
        }
    }
    /// check the first diagonal
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }
    /// check the second diagonal
    for (int i = row, j = col; i <= n - 1 && j >= 0; i++, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }
    return true;
}

/**
 * Solve n queens problem
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param col current index in columns
 */
template <size_t n>
void NQueenSol(std::array<std::array<int, n>, n> board, int col) {
    if (col >= n) {
        PrintSol<n>(board);
        return;
    }
    for (int i = 0; i < n; i++) {
        if (CanIMove<n>(board, i, col)) {
            board[i][col] = 1;
            NQueenSol<n>(board, col + 1);
            board[i][col] = 0;
        }
    }
}
}  // namespace n_queens_optimized
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    const int n = 4;
    std::array<std::array<int, n>, n> board{};

    if (n % 2 == 0) {
        for (int i = 0; i <= n / 2 - 1; i++) {
            if (backtracking::n_queens_optimized::CanIMove(board, i, 0)) {
                board[i][0] = 1;
                backtracking::n_queens_optimized::NQueenSol(board, 1);
                board[i][0] = 0;
            }
        }
    } else {
        for (int i = 0; i <= n / 2; i++) {
            if (backtracking::n_queens_optimized::CanIMove(board, i, 0)) {
                board[i][0] = 1;
                backtracking::n_queens_optimized::NQueenSol(board, 1);
                board[i][0] = 0;
            }
        }
    }
    return 0;
}

/**
 * Alternate write-up of the classic Eight Queens puzzle, optimized variant.
 *
 * Because a chessboard is symmetric top-to-bottom, we only need to seed the
 * very first column with placements in roughly the upper half of the board;
 * every solution found from those seeds already covers its mirror image, so
 * we print both the board and its transpose when the mirrored board hasn't
 * already been produced.
 */

#include <array>
#include <iostream>

namespace backtracking {
namespace queens_fast {

// Dumps the board followed (when relevant) by its transposed twin.
template <size_t dim>
void showBoard(const std::array<std::array<int, dim>, dim> &grid) {
    for (size_t r = 0; r < dim; ++r) {
        for (size_t c = 0; c < dim; ++c) {
            std::cout << grid[r][c] << ' ';
        }
        std::cout << '\n';
    }
    std::cout << '\n';

    bool needMirror = (dim % 2 == 0) || (grid[dim / 2 + 1][0] != 1);
    if (needMirror) {
        for (size_t r = 0; r < dim; ++r) {
            for (size_t c = 0; c < dim; ++c) {
                std::cout << grid[c][r] << ' ';
            }
            std::cout << '\n';
        }
        std::cout << '\n';
    }
}

// Tests whether a queen dropped at (targetRow, targetCol) survives attacks
// from anything already committed on the board.
template <size_t dim>
bool isSafeSpot(const std::array<std::array<int, dim>, dim> &grid,
                int targetRow, int targetCol) {
    int idx = 0;
    while (idx <= targetCol) {
        if (grid[targetRow][idx] == 1) return false;
        ++idx;
    }

    int r = targetRow, c = targetCol;
    while (r >= 0 && c >= 0) {
        if (grid[r][c] == 1) return false;
        --r;
        --c;
    }

    r = targetRow;
    c = targetCol;
    while (r <= static_cast<int>(dim) - 1 && c >= 0) {
        if (grid[r][c] == 1) return false;
        ++r;
        --c;
    }

    return true;
}

// Recursively assigns a queen per column, backtracking whenever a column
// runs out of safe rows.
template <size_t dim>
void expandColumn(std::array<std::array<int, dim>, dim> grid, int column) {
    if (column >= static_cast<int>(dim)) {
        showBoard<dim>(grid);
        return;
    }

    for (size_t candidateRow = 0; candidateRow < dim; ++candidateRow) {
        if (isSafeSpot<dim>(grid, static_cast<int>(candidateRow), column)) {
            grid[candidateRow][column] = 1;
            expandColumn<dim>(grid, column + 1);
            grid[candidateRow][column] = 0;
        }
    }
}

}  // namespace queens_fast
}  // namespace backtracking

int main() {
    constexpr int boardSize = 4;
    std::array<std::array<int, boardSize>, boardSize> grid{};

    int halfLimit = (boardSize % 2 == 0) ? (boardSize / 2 - 1) : (boardSize / 2);

    for (int seedRow = 0; seedRow <= halfLimit; ++seedRow) {
        if (backtracking::queens_fast::isSafeSpot(grid, seedRow, 0)) {
            grid[seedRow][0] = 1;
            backtracking::queens_fast::expandColumn(grid, 1);
            grid[seedRow][0] = 0;
        }
    }

    return 0;
}

/**
 * @file
 * @brief [Eight Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle)
 * puzzle, printing all solutions
 *
 * @author [Himani Negi](https://github.com/Himani2000)
 * @author [David Leal](https://github.com/Panquesito7)
 *
 */
#include <array>     /// for std::array
#include <iostream>  /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace n_queens_all_solutions
 * @brief Functions for the [Eight
 * Queens](https://en.wikipedia.org/wiki/Eight_queens_puzzle) puzzle with all
 * solutions.
 */
namespace n_queens_all_solutions {
/**
 * @brief Utility function to print matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 */
template <size_t n>
void PrintSol(const std::array<std::array<int, n>, n>& board) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << board[i][j] << " ";
        }
        std::cout << std::endl;
    }
    std::cout << std::endl;
}

/**
 * @brief Check if a queen can be placed on the matrix
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param row current index in rows
 * @param col current index in columns
 * @returns `true` if queen can be placed on matrix
 * @returns `false` if queen can't be placed on matrix
 */
template <size_t n>
bool CanIMove(const std::array<std::array<int, n>, n>& board, int row,
              int col) {
    /// check in the row
    for (int i = 0; i < col; i++) {
        if (board[row][i] == 1) {
            return false;
        }
    }
    /// check the first diagonal
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }
    /// check the second diagonal
    for (int i = row, j = col; i <= n - 1 && j >= 0; i++, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }
    return true;
}

/**
 * @brief Main function to solve the N Queens problem
 * @tparam n number of matrix size
 * @param board matrix where numbers are saved
 * @param col current index in columns
 */
template <size_t n>
void NQueenSol(std::array<std::array<int, n>, n> board, int col) {
    if (col >= n) {
        PrintSol(board);
        return;
    }
    for (int i = 0; i < n; i++) {
        if (CanIMove(board, i, col)) {
            board[i][col] = 1;
            NQueenSol(board, col + 1);
            board[i][col] = 0;
        }
    }
}
}  // namespace n_queens_all_solutions
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    const int n = 4;
    std::array<std::array<int, n>, n> board{0};

    backtracking::n_queens_all_solutions::NQueenSol(board, 0);
}

/**
 * Enumerates and prints every distinct arrangement of N non-attacking queens
 * on an N x N board, using plain (unoptimized) column-by-column backtracking.
 */

#include <array>
#include <iostream>

namespace backtracking {
namespace queens_enum {

// Prints the full board, one row per line.
template <size_t dim>
void dumpBoard(const std::array<std::array<int, dim>, dim> &grid) {
    for (size_t row = 0; row < dim; ++row) {
        for (size_t col = 0; col < dim; ++col) {
            std::cout << grid[row][col] << ' ';
        }
        std::cout << '\n';
    }
    std::cout << '\n';
}

// Verifies no existing queen threatens the (row, col) cell via row,
// or either diagonal.
template <size_t dim>
bool placementAllowed(const std::array<std::array<int, dim>, dim> &grid,
                      int row, int col) {
    for (int c = 0; c < col; ++c) {
        if (grid[row][c] == 1) return false;
    }

    int r = row, c = col;
    while (r >= 0 && c >= 0) {
        if (grid[r][c] == 1) return false;
        --r;
        --c;
    }

    r = row;
    c = col;
    while (r <= static_cast<int>(dim) - 1 && c >= 0) {
        if (grid[r][c] == 1) return false;
        ++r;
        --c;
    }

    return true;
}

// Backtracking driver: try every row for the current column, recurse, undo.
template <size_t dim>
void fillColumn(std::array<std::array<int, dim>, dim> grid, int col) {
    if (col >= static_cast<int>(dim)) {
        dumpBoard(grid);
        return;
    }

    for (size_t row = 0; row < dim; ++row) {
        if (placementAllowed(grid, static_cast<int>(row), col)) {
            grid[row][col] = 1;
            fillColumn(grid, col + 1);
            grid[row][col] = 0;
        }
    }
}

}  // namespace queens_enum
}  // namespace backtracking

int main() {
    constexpr int boardSize = 4;
    std::array<std::array<int, boardSize>, boardSize> grid{};
    for (auto &row : grid) row.fill(0);

    backtracking::queens_enum::fillColumn(grid, 0);
    return 0;
}

/**
 * @file
 * @brief Implements [Rat in a
 * Maze](https://www.codesdope.com/blog/article/backtracking-to-
 * solve-a-rat-in-a-maze-c-java-pytho/) algorithm
 *
 * @details
 * A Maze is given as N*N binary matrix of blocks where source block is the
 * upper left most block i.e., maze[0][0] and destination block is lower
 * rightmost block i.e., maze[N-1][N-1]. A rat starts from source and has to
 * reach destination. The rat can move only in two directions: forward and down.
 * In the maze matrix, 0 means the block is dead end and 1 means the block can
 * be used in the path from source to destination.
 *
 * @author [Vaibhav Thakkar](https://github.com/vaithak)
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <array>     /// for std::array
#include <cassert>   /// for assert
#include <iostream>  /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace rat_maze
 * @brief Functions for [Rat in a
 * Maze](https://www.codesdope.com/blog/article/backtracking-to-
 * solve-a-rat-in-a-maze-c-java-pytho/) algorithm
 */
namespace rat_maze {
/**
 * @brief Solve rat maze problem
 * @tparam size number of matrix size
 * @param currposrow current position in rows
 * @param currposcol current position in columns
 * @param maze matrix where numbers are saved
 * @param soln matrix to problem solution
 * @returns `true` if there exists a solution to move one step ahead in a column
 * or in a row
 * @returns `false` for the backtracking part
 */
template <size_t size>
bool solveMaze(int currposrow, int currposcol,
               const std::array<std::array<int, size>, size> &maze,
               std::array<std::array<int, size>, size> soln) {
    if ((currposrow == size - 1) && (currposcol == size - 1)) {
        soln[currposrow][currposcol] = 1;
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                std::cout << soln[i][j] << " ";
            }
            std::cout << std::endl;
        }
        return true;
    } else {
        soln[currposrow][currposcol] = 1;

        // if there exist a solution by moving one step ahead in a column
        if ((currposcol < size - 1) && maze[currposrow][currposcol + 1] == 1 &&
            solveMaze(currposrow, currposcol + 1, maze, soln)) {
            return true;
        }

        // if there exists a solution by moving one step ahead in a row
        if ((currposrow < size - 1) && maze[currposrow + 1][currposcol] == 1 &&
            solveMaze(currposrow + 1, currposcol, maze, soln)) {
            return true;
        }

        // the backtracking part
        soln[currposrow][currposcol] = 0;
        return false;
    }
}
}  // namespace rat_maze
}  // namespace backtracking

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    const int size = 4;
    std::array<std::array<int, size>, size> maze = {
        std::array<int, size>{1, 0, 1, 0}, std::array<int, size>{1, 0, 1, 1},
        std::array<int, size>{1, 0, 0, 1}, std::array<int, size>{1, 1, 1, 1}};

    std::array<std::array<int, size>, size> soln{};

    // Backtracking: setup matrix solution to zero
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            soln[i][j] = 0;
        }
    }

    int currposrow = 0;  // Current position in the rows
    int currposcol = 0;  // Current position in the columns

    assert(backtracking::rat_maze::solveMaze<size>(currposrow, currposcol, maze,
                                                   soln) == 1);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * Rat-in-a-Maze path finder.
 *
 * A binary grid represents open cells (1) and walls (0). Starting at the
 * top-left cell, the goal is to reach the bottom-right cell moving only
 * rightward or downward. We explore greedily and unwind (backtrack) any
 * cell that leads to a dead end.
 */

#include <array>
#include <cassert>
#include <iostream>

namespace backtracking {
namespace maze_walker {

// Attempts to walk from (row, col) to the bottom-right corner, marking
// visited cells in `path`. Returns whether a full route was found.
template <size_t dim>
bool findRoute(int row, int col,
               const std::array<std::array<int, dim>, dim> &grid,
               std::array<std::array<int, dim>, dim> path) {
    const int last = static_cast<int>(dim) - 1;

    if (row == last && col == last) {
        path[row][col] = 1;
        for (int r = 0; r < static_cast<int>(dim); ++r) {
            for (int c = 0; c < static_cast<int>(dim); ++c) {
                std::cout << path[r][c] << ' ';
            }
            std::cout << '\n';
        }
        return true;
    }

    path[row][col] = 1;

    bool canGoRight = col < last && grid[row][col + 1] == 1;
    if (canGoRight && findRoute(row, col + 1, grid, path)) {
        return true;
    }

    bool canGoDown = row < last && grid[row + 1][col] == 1;
    if (canGoDown && findRoute(row + 1, col, grid, path)) {
        return true;
    }

    // Neither direction panned out from here: undo the mark and retreat.
    path[row][col] = 0;
    return false;
}

}  // namespace maze_walker
}  // namespace backtracking

static void runSelfCheck() {
    constexpr int dim = 4;
    std::array<std::array<int, dim>, dim> grid = {
        std::array<int, dim>{1, 0, 1, 0}, std::array<int, dim>{1, 0, 1, 1},
        std::array<int, dim>{1, 0, 0, 1}, std::array<int, dim>{1, 1, 1, 1}};

    std::array<std::array<int, dim>, dim> path{};
    for (auto &row : path) row.fill(0);

    int startRow = 0;
    int startCol = 0;

    bool solved =
        backtracking::maze_walker::findRoute<dim>(startRow, startCol, grid, path);
    assert(solved);
}

int main() {
    runSelfCheck();
    return 0;
}

/**
 * @file
 * @brief [Subset-sum](https://en.wikipedia.org/wiki/Subset_sum_problem) (only
 * continuous subsets) problem
 * @details We are given an array and a sum value. The algorithms find all
 * the subarrays of that array with sum equal to the given sum and return such
 * subarrays count. This approach will have \f$O(n)\f$ time complexity and
 * \f$O(n)\f$ space complexity. NOTE: In this problem, we are only referring to
 * the continuous subsets as subarrays everywhere. Subarrays can be created
 * using deletion operation at the end of the front of an array only. The parent
 * array is also counted in subarrays having 0 number of deletion operations.
 *
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>        /// for assert
#include <cstdint>
#include <iostream>       /// for IO operations
#include <unordered_map>  /// for unordered_map
#include <vector>         /// for std::vector

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace subarray_sum
 * @brief Functions for the [Subset
 * sum](https://en.wikipedia.org/wiki/Subset_sum_problem) implementation
 */
namespace subarray_sum {
/**
 * @brief The main function that implements the count of the subarrays
 * @param sum is the required sum of any subarrays
 * @param in_arr is the input array
 * @returns count of the number of subsets with required sum
 */
uint64_t subarray_sum(int64_t sum, const std::vector<int64_t> &in_arr) {
    int64_t nelement = in_arr.size();
    int64_t count_of_subset = 0;
    int64_t current_sum = 0;
    std::unordered_map<int64_t, int64_t>
        sumarray;  // to store the subarrays count
                   // frequency having some sum value

    for (int64_t i = 0; i < nelement; i++) {
        current_sum += in_arr[i];

        if (current_sum == sum) {
            count_of_subset++;
        }
        // If in case current_sum is greater than the required sum
        if (sumarray.find(current_sum - sum) != sumarray.end()) {
            count_of_subset += (sumarray[current_sum - sum]);
        }
        sumarray[current_sum]++;
    }
    return count_of_subset;
}
}  // namespace subarray_sum
}  // namespace backtracking

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::cout << "1st test ";
    std::vector<int64_t> array1 = {-7, -3, -2, 5, 8};  // input array
    assert(
        backtracking::subarray_sum::subarray_sum(0, array1) ==
        1);  // first argument in subarray_sum function is the required sum and
             // second is the input array, answer is the subarray {(-3,-2,5)}
    std::cout << "passed" << std::endl;

    // 2nd test
    std::cout << "2nd test ";
    std::vector<int64_t> array2 = {1, 2, 3, 3};
    assert(backtracking::subarray_sum::subarray_sum(6, array2) ==
           2);  // here we are expecting 2 subsets which sum up to 6 i.e.
                // {(1,2,3),(3,3)}
    std::cout << "passed" << std::endl;

    // 3rd test
    std::cout << "3rd test ";
    std::vector<int64_t> array3 = {1, 1, 1, 1};
    assert(backtracking::subarray_sum::subarray_sum(1, array3) ==
           4);  // here we are expecting 4 subsets which sum up to 1 i.e.
                // {(1),(1),(1),(1)}
    std::cout << "passed" << std::endl;

    // 4rd test
    std::cout << "4th test ";
    std::vector<int64_t> array4 = {3, 3, 3, 3};
    assert(backtracking::subarray_sum::subarray_sum(6, array4) ==
           3);  // here we are expecting 3 subsets which sum up to 6 i.e.
                // {(3,3),(3,3),(3,3)}
    std::cout << "passed" << std::endl;

    // 5th test
    std::cout << "5th test ";
    std::vector<int64_t> array5 = {};
    assert(backtracking::subarray_sum::subarray_sum(6, array5) ==
           0);  // here we are expecting 0 subsets which sum up to 6 i.e. we
                // cannot select anything from an empty array
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * Counts contiguous slices (subarrays) of an integer array whose elements
 * add up to a target value, in linear time using a running-sum frequency
 * map (a prefix-sum / hash-map technique rather than brute force).
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <unordered_map>
#include <vector>

namespace backtracking {
namespace contiguous_sum {

// Walks the array once, tracking how many times each prefix sum has been
// seen so far, to count how many contiguous ranges hit `target`.
uint64_t countRanges(int64_t target, const std::vector<int64_t> &values) {
    int64_t size = static_cast<int64_t>(values.size());
    int64_t matches = 0;
    int64_t runningTotal = 0;

    std::unordered_map<int64_t, int64_t> seenTotals;

    int64_t idx = 0;
    while (idx < size) {
        runningTotal += values[idx];

        if (runningTotal == target) {
            ++matches;
        }

        auto it = seenTotals.find(runningTotal - target);
        if (it != seenTotals.end()) {
            matches += it->second;
        }

        seenTotals[runningTotal]++;
        ++idx;
    }

    return static_cast<uint64_t>(matches);
}

}  // namespace contiguous_sum
}  // namespace backtracking

static void runSelfCheck() {
    std::cout << "case A ";
    std::vector<int64_t> dataA = {-7, -3, -2, 5, 8};
    assert(backtracking::contiguous_sum::countRanges(0, dataA) == 1);
    std::cout << "ok" << std::endl;

    std::cout << "case B ";
    std::vector<int64_t> dataB = {1, 2, 3, 3};
    assert(backtracking::contiguous_sum::countRanges(6, dataB) == 2);
    std::cout << "ok" << std::endl;

    std::cout << "case C ";
    std::vector<int64_t> dataC = {1, 1, 1, 1};
    assert(backtracking::contiguous_sum::countRanges(1, dataC) == 4);
    std::cout << "ok" << std::endl;

    std::cout << "case D ";
    std::vector<int64_t> dataD = {3, 3, 3, 3};
    assert(backtracking::contiguous_sum::countRanges(6, dataD) == 3);
    std::cout << "ok" << std::endl;

    std::cout << "case E ";
    std::vector<int64_t> dataE = {};
    assert(backtracking::contiguous_sum::countRanges(6, dataE) == 0);
    std::cout << "ok" << std::endl;
}

int main() {
    runSelfCheck();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Subset
 * Sum](https://en.wikipedia.org/wiki/Subset_sum_problem) problem.
 * @details
 * We are given an array and a sum value. The algorithm finds all
 * the subsets of that array with sum equal to the given sum and return such
 * subsets count. This approach will have exponential time complexity.
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace Subsets
 * @brief Functions for the [Subset
 * Sum](https://en.wikipedia.org/wiki/Subset_sum_problem) problem.
 */
namespace subset_sum {
/**
 * @brief The main function implements count of subsets
 * @param sum is the required sum of any subset
 * @param in_arr is the input array
 * @returns count of the number of subsets with required sum
 */
uint64_t number_of_subsets(int32_t sum, const std::vector<int32_t> &in_arr) {
    int32_t nelement = in_arr.size();
    uint64_t count_of_subset = 0;

    for (int32_t i = 0; i < (1 << (nelement)); i++) {
        int32_t check = 0;
        for (int32_t j = 0; j < nelement; j++) {
            if (i & (1 << j)) {
                check += (in_arr[j]);
            }
        }
        if (check == sum) {
            count_of_subset++;
        }
    }
    return count_of_subset;
}
}  // namespace subset_sum
}  // namespace backtracking

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::cout << "1st test ";
    std::vector<int32_t> array1 = {-7, -3, -2, 5, 8};  // input array
    assert(backtracking::subset_sum::number_of_subsets(0, array1) ==
           2);  // first argument in subset_sum function is the required sum and
                // second is the input array
    std::cout << "passed" << std::endl;

    // 2nd test
    std::cout << "2nd test ";
    std::vector<int32_t> array2 = {1, 2, 3, 3};
    assert(backtracking::subset_sum::number_of_subsets(6, array2) ==
           3);  // here we are expecting 3 subsets which sum up to 6 i.e.
                // {(1,2,3),(1,2,3),(3,3)}
    std::cout << "passed" << std::endl;

    // 3rd test
    std::cout << "3rd test ";
    std::vector<int32_t> array3 = {1, 1, 1, 1};
    assert(backtracking::subset_sum::number_of_subsets(1, array3) ==
           4);  // here we are expecting 4 subsets which sum up to 1 i.e.
                // {(1),(1),(1),(1)}
    std::cout << "passed" << std::endl;

    // 4th test
    std::cout << "4th test ";
    std::vector<int32_t> array4 = {3, 3, 3, 3};
    assert(backtracking::subset_sum::number_of_subsets(6, array4) ==
           6);  // here we are expecting 6 subsets which sum up to 6 i.e.
                // {(3,3),(3,3),(3,3),(3,3),(3,3),(3,3)}
    std::cout << "passed" << std::endl;

    // Test 5
    std::cout << "5th test ";
    std::vector<int32_t> array5 = {};
    assert(backtracking::subset_sum::number_of_subsets(6, array5) ==
           0);  // here we are expecting 0 subsets which sum up to 6 i.e. we
                // cannot select anything from an empty array
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * Brute-force Subset Sum counter: enumerates every possible inclusion mask
 * over the input array (2^n possibilities) and tallies how many masks
 * produce a subset whose elements sum to the target value.
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

namespace backtracking {
namespace mask_subsets {

// Iterates all bitmasks from 0 to 2^n - 1, treating each set bit as
// "include this element," and counts masks whose sum equals `target`.
uint64_t tallyMatchingSubsets(int32_t target, const std::vector<int32_t> &items) {
    int32_t count = items.size();
    uint64_t hits = 0;

    int32_t mask = 0;
    while (mask < (1 << count)) {
        int32_t accumulated = 0;
        for (int32_t bit = 0; bit < count; ++bit) {
            if (mask & (1 << bit)) {
                accumulated += items[bit];
            }
        }
        if (accumulated == target) {
            ++hits;
        }
        ++mask;
    }

    return hits;
}

}  // namespace mask_subsets
}  // namespace backtracking

static void runSelfCheck() {
    std::cout << "case A ";
    std::vector<int32_t> setA = {-7, -3, -2, 5, 8};
    assert(backtracking::mask_subsets::tallyMatchingSubsets(0, setA) == 2);
    std::cout << "ok" << std::endl;

    std::cout << "case B ";
    std::vector<int32_t> setB = {1, 2, 3, 3};
    assert(backtracking::mask_subsets::tallyMatchingSubsets(6, setB) == 3);
    std::cout << "ok" << std::endl;

    std::cout << "case C ";
    std::vector<int32_t> setC = {1, 1, 1, 1};
    assert(backtracking::mask_subsets::tallyMatchingSubsets(1, setC) == 4);
    std::cout << "ok" << std::endl;

    std::cout << "case D ";
    std::vector<int32_t> setD = {3, 3, 3, 3};
    assert(backtracking::mask_subsets::tallyMatchingSubsets(6, setD) == 6);
    std::cout << "ok" << std::endl;

    std::cout << "case E ";
    std::vector<int32_t> setE = {};
    assert(backtracking::mask_subsets::tallyMatchingSubsets(6, setE) == 0);
    std::cout << "ok" << std::endl;
}

int main() {
    runSelfCheck();
    return 0;
}

/**
 * @file
 * @brief [Sudoku Solver](https://en.wikipedia.org/wiki/Sudoku) algorithm.
 *
 * @details
 * Sudoku (数独, sūdoku, digit-single) (/suːˈdoʊkuː/, /-ˈdɒk-/, /sə-/,
 * originally called Number Place) is a logic-based, combinatorial
 * number-placement puzzle. In classic sudoku, the objective is to fill a 9×9
 * grid with digits so that each column, each row, and each of the nine 3×3
 * subgrids that compose the grid (also called "boxes", "blocks", or "regions")
 * contain all of the digits from 1 to 9. The puzzle setter provides a
 * partially completed grid, which for a well-posed puzzle has a single
 * solution.
 *
 * @author [DarthCoder3200](https://github.com/DarthCoder3200)
 * @author [David Leal](https://github.com/Panquesito7)
 */
#include <array>     /// for assert
#include <iostream>  /// for IO operations

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace sudoku_solver
 * @brief Functions for the [Sudoku
 * Solver](https://en.wikipedia.org/wiki/Sudoku) implementation
 */
namespace sudoku_solver {
/**
 * @brief Check if it's possible to place a number (`no` parameter)
 * @tparam V number of vertices in the array
 * @param mat matrix where numbers are saved
 * @param i current index in rows
 * @param j current index in columns
 * @param no number to be added in matrix
 * @param n number of times loop will run
 * @returns `true` if 'mat' is different from 'no'
 * @returns `false` if 'mat' equals to 'no'
 */
template <size_t V>
bool isPossible(const std::array<std::array<int, V>, V> &mat, int i, int j,
                int no, int n) {
    /// `no` shouldn't be present in either row i or column j
    for (int x = 0; x < n; x++) {
        if (mat[x][j] == no || mat[i][x] == no) {
            return false;
        }
    }

    /// `no` shouldn't be present in the 3*3 subgrid
    int sx = (i / 3) * 3;
    int sy = (j / 3) * 3;

    for (int x = sx; x < sx + 3; x++) {
        for (int y = sy; y < sy + 3; y++) {
            if (mat[x][y] == no) {
                return false;
            }
        }
    }

    return true;
}
/**
 * @brief Utility function to print the matrix
 * @tparam V number of vertices in array
 * @param mat matrix where numbers are saved
 * @param starting_mat copy of mat, required by printMat for highlighting the
 * differences
 * @param n number of times loop will run
 * @return void
 */
template <size_t V>
void printMat(const std::array<std::array<int, V>, V> &mat,
              const std::array<std::array<int, V>, V> &starting_mat, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (starting_mat[i][j] != mat[i][j]) {
                std::cout << "\033[93m" << mat[i][j] << "\033[0m"
                          << " ";
            } else {
                std::cout << mat[i][j] << " ";
            }
            if ((j + 1) % 3 == 0) {
                std::cout << '\t';
            }
        }
        if ((i + 1) % 3 == 0) {
            std::cout << std::endl;
        }
        std::cout << std::endl;
    }
}

/**
 * @brief Main function to implement the Sudoku algorithm
 * @tparam V number of vertices in array
 * @param mat matrix where numbers are saved
 * @param starting_mat copy of mat, required by printMat for highlighting the
 * differences
 * @param i current index in rows
 * @param j current index in columns
 * @returns `true` if 'no' was placed
 * @returns `false` if 'no' was not placed
 */
template <size_t V>
bool solveSudoku(std::array<std::array<int, V>, V> &mat,
                 const std::array<std::array<int, V>, V> &starting_mat, int i,
                 int j) {
    /// Base Case
    if (i == 9) {
        /// Solved for 9 rows already
        printMat<V>(mat, starting_mat, 9);
        return true;
    }

    /// Crossed the last  Cell in the row
    if (j == 9) {
        return solveSudoku<V>(mat, starting_mat, i + 1, 0);
    }

    /// Blue Cell - Skip
    if (mat[i][j] != 0) {
        return solveSudoku<V>(mat, starting_mat, i, j + 1);
    }
    /// White Cell
    /// Try to place every possible no
    for (int no = 1; no <= 9; no++) {
        if (isPossible<V>(mat, i, j, no, 9)) {
            /// Place the 'no' - assuming a solution will exist
            mat[i][j] = no;
            bool solution_found = solveSudoku<V>(mat, starting_mat, i, j + 1);
            if (solution_found) {
                return true;
            }
            /// Couldn't find a solution
            /// loop will place the next `no`.
        }
    }
    /// Solution couldn't be found for any of the numbers provided
    mat[i][j] = 0;
    return false;
}
}  // namespace sudoku_solver
}  // namespace backtracking

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    const int V = 9;
    std::array<std::array<int, V>, V> mat = {
        std::array<int, V>{5, 3, 0, 0, 7, 0, 0, 0, 0},
        std::array<int, V>{6, 0, 0, 1, 9, 5, 0, 0, 0},
        std::array<int, V>{0, 9, 8, 0, 0, 0, 0, 6, 0},
        std::array<int, V>{8, 0, 0, 0, 6, 0, 0, 0, 3},
        std::array<int, V>{4, 0, 0, 8, 0, 3, 0, 0, 1},
        std::array<int, V>{7, 0, 0, 0, 2, 0, 0, 0, 6},
        std::array<int, V>{0, 6, 0, 0, 0, 0, 2, 8, 0},
        std::array<int, V>{0, 0, 0, 4, 1, 9, 0, 0, 5},
        std::array<int, V>{0, 0, 0, 0, 8, 0, 0, 7, 9}};

    backtracking::sudoku_solver::printMat<V>(mat, mat, 9);
    std::cout << "Solution " << std::endl;
    std::array<std::array<int, V>, V> starting_mat = mat;
    backtracking::sudoku_solver::solveSudoku<V>(mat, starting_mat, 0, 0);

    return 0;
}

/**
 * Backtracking Sudoku solver for a standard 9x9 grid: fills empty (zero)
 * cells one at a time, trying digits 1-9 while respecting row, column, and
 * 3x3-box constraints, undoing choices that lead nowhere.
 */

#include <array>
#include <iostream>

namespace backtracking {
namespace sudoku_engine {

// Returns false if `candidate` already appears in the target row, column,
// or containing 3x3 box.
template <size_t dim>
bool candidateFits(const std::array<std::array<int, dim>, dim> &board, int row,
                   int col, int candidate, int limit) {
    for (int k = 0; k < limit; ++k) {
        if (board[k][col] == candidate || board[row][k] == candidate) {
            return false;
        }
    }

    int boxRow = (row / 3) * 3;
    int boxCol = (col / 3) * 3;

    for (int r = boxRow; r < boxRow + 3; ++r) {
        for (int c = boxCol; c < boxCol + 3; ++c) {
            if (board[r][c] == candidate) {
                return false;
            }
        }
    }

    return true;
}

// Renders the grid, highlighting cells that changed relative to the puzzle
// as originally given.
template <size_t dim>
void renderGrid(const std::array<std::array<int, dim>, dim> &board,
                const std::array<std::array<int, dim>, dim> &original,
                int limit) {
    for (int r = 0; r < limit; ++r) {
        for (int c = 0; c < limit; ++c) {
            if (original[r][c] != board[r][c]) {
                std::cout << "\033[93m" << board[r][c] << "\033[0m" << ' ';
            } else {
                std::cout << board[r][c] << ' ';
            }
            if ((c + 1) % 3 == 0) {
                std::cout << '\t';
            }
        }
        if ((r + 1) % 3 == 0) {
            std::cout << '\n';
        }
        std::cout << '\n';
    }
}

// Recursively fills cell (row, col), advancing across rows and down columns;
// backtracks by resetting a cell to 0 whenever no digit works.
template <size_t dim>
bool fillGrid(std::array<std::array<int, dim>, dim> &board,
              const std::array<std::array<int, dim>, dim> &original, int row,
              int col) {
    if (row == 9) {
        renderGrid<dim>(board, original, 9);
        return true;
    }

    if (col == 9) {
        return fillGrid<dim>(board, original, row + 1, 0);
    }

    if (board[row][col] != 0) {
        return fillGrid<dim>(board, original, row, col + 1);
    }

    for (int candidate = 1; candidate <= 9; ++candidate) {
        if (candidateFits<dim>(board, row, col, candidate, 9)) {
            board[row][col] = candidate;
            if (fillGrid<dim>(board, original, row, col + 1)) {
                return true;
            }
        }
    }

    board[row][col] = 0;
    return false;
}

}  // namespace sudoku_engine
}  // namespace backtracking

int main() {
    constexpr int dim = 9;
    std::array<std::array<int, dim>, dim> board = {
        std::array<int, dim>{5, 3, 0, 0, 7, 0, 0, 0, 0},
        std::array<int, dim>{6, 0, 0, 1, 9, 5, 0, 0, 0},
        std::array<int, dim>{0, 9, 8, 0, 0, 0, 0, 6, 0},
        std::array<int, dim>{8, 0, 0, 0, 6, 0, 0, 0, 3},
        std::array<int, dim>{4, 0, 0, 8, 0, 3, 0, 0, 1},
        std::array<int, dim>{7, 0, 0, 0, 2, 0, 0, 0, 6},
        std::array<int, dim>{0, 6, 0, 0, 0, 0, 2, 8, 0},
        std::array<int, dim>{0, 0, 0, 4, 1, 9, 0, 0, 5},
        std::array<int, dim>{0, 0, 0, 0, 8, 0, 0, 7, 9}};

    backtracking::sudoku_engine::renderGrid<dim>(board, board, 9);
    std::cout << "Solution" << std::endl;

    std::array<std::array<int, dim>, dim> original = board;
    backtracking::sudoku_engine::fillGrid<dim>(board, original, 0, 0);

    return 0;
}

/**
 * @file
 * @brief Implementation of the [Wildcard
 * Matching](https://www.geeksforgeeks.org/wildcard-pattern-matching/) problem.
 * @details
 * Given a matching string and a pattern, implement wildcard pattern
 * matching with support for `?` and `*`. `?` matches any single character.
 * `*` matches any sequence of characters (including the empty sequence).
 * The matching should cover the entire matching string (not partial). The task
 * is to determine if the pattern matches with the matching string
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace backtracking
 * @brief Backtracking algorithms
 */
namespace backtracking {
/**
 * @namespace wildcard_matching
 * @brief Functions for the [Wildcard
 * Matching](https://www.geeksforgeeks.org/wildcard-pattern-matching/) problem.
 */
namespace wildcard_matching {
/**
 * @brief The main function implements if pattern can be matched with given
 * string
 * @param s is the given matching string
 * @param p is the given pattern
 * @param pos1 is the starting index
 * @param pos2 is the last index
 * @returns 1 if pattern matches with matching string otherwise 0
 */
std::vector<std::vector<int64_t>> dpTable(1000, std::vector<int64_t>(1000, -1));
bool wildcard_matching(std::string s, std::string p, uint32_t pos1,
                       uint32_t pos2) {
    uint32_t n = s.length();
    uint32_t m = p.length();
    // matching is successfull if both strings are done
    if (pos1 == n && pos2 == m) {
        return true;
    }

    // matching is unsuccessfull if pattern is not finished but matching string
    // is
    if (pos1 != n && pos2 == m) {
        return false;
    }

    // all the remaining characters of patterns must be * inorder to match with
    // finished string
    if (pos1 == n && pos2 != m) {
        while (pos2 < m && p[pos2] == '*') {
            pos2++;
        }

        return pos2 == m;
    }

    // if already calculted for these positions
    if (dpTable[pos1][pos2] != -1) {
        return dpTable[pos1][pos2];
    }

    // if the characters are same just go ahead in both the string
    if (s[pos1] == p[pos2]) {
        return dpTable[pos1][pos2] =
                   wildcard_matching(s, p, pos1 + 1, pos2 + 1);
    }

    else {
        // can only single character
        if (p[pos2] == '?') {
            return dpTable[pos1][pos2] =
                       wildcard_matching(s, p, pos1 + 1, pos2 + 1);
        }
        // have choice either to match one or more charcters
        else if (p[pos2] == '*') {
            return dpTable[pos1][pos2] =
                       wildcard_matching(s, p, pos1, pos2 + 1) ||
                       wildcard_matching(s, p, pos1 + 1, pos2);
        }
        // not possible to match
        else {
            return dpTable[pos1][pos2] = 0;
        }
    }
}

}  // namespace wildcard_matching
}  // namespace backtracking

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::cout << "1st test ";
    std::string matching1 = "baaabab";
    std::string pattern1 = "*****ba*****ab";
    assert(backtracking::wildcard_matching::wildcard_matching(matching1,
                                                              pattern1, 0, 0) ==
           1);  // here the pattern matches with given string
    std::cout << "passed" << std::endl;

    // 2nd test
    std::cout << "2nd test ";
    std::string matching2 = "baaabab";
    std::string pattern2 = "ba*****ab";
    assert(backtracking::wildcard_matching::wildcard_matching(matching2,
                                                              pattern2, 0, 0) ==
           1);  // here the pattern matches with given string
    std::cout << "passed" << std::endl;

    // 3rd test
    std::cout << "3rd test ";
    std::string matching3 = "baaabab";
    std::string pattern3 = "ba*ab";
    assert(backtracking::wildcard_matching::wildcard_matching(matching3,
                                                              pattern3, 0, 0) ==
           1);  // here the pattern matches with given string
    std::cout << "passed" << std::endl;

    // 4th test
    std::cout << "4th test ";
    std::string matching4 = "baaabab";
    std::string pattern4 = "a*ab";
    assert(backtracking::wildcard_matching::wildcard_matching(matching4,
                                                              pattern4, 0, 0) ==
           1);  // here the pattern matches with given string
    std::cout << "passed" << std::endl;

    // 5th test
    std::cout << "5th test ";
    std::string matching5 = "baaabab";
    std::string pattern5 = "aa?ab";
    assert(backtracking::wildcard_matching::wildcard_matching(matching5,
                                                              pattern5, 0, 0) ==
           1);  // here the pattern matches with given string
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * Wildcard pattern matcher supporting `?` (any single character) and `*`
 * (any run of characters, including none). Implemented as memoized
 * recursion (top-down DP) over the pair of string positions so repeated
 * subproblems are only solved once.
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

namespace backtracking {
namespace glob_match {

// Memo table: memo[i][j] caches whether text[i:] matches pattern[j:].
// -1 means "not yet computed."
std::vector<std::vector<int64_t>> memo(1000, std::vector<int64_t>(1000, -1));

// Recursively checks whether pattern[patIdx:] can match text[txtIdx:].
bool matches(const std::string &text, const std::string &pattern,
             uint32_t txtIdx, uint32_t patIdx) {
    uint32_t textLen = text.length();
    uint32_t patLen = pattern.length();

    // Both exhausted together: a full match.
    if (txtIdx == textLen && patIdx == patLen) {
        return true;
    }

    // Text exhausted but pattern still has non-star work left: no match.
    if (txtIdx != textLen && patIdx == patLen) {
        return false;
    }

    // Text is exhausted; only trailing stars in the pattern can still match.
    if (txtIdx == textLen && patIdx != patLen) {
        uint32_t cursor = patIdx;
        while (cursor < patLen && pattern[cursor] == '*') {
            ++cursor;
        }
        return cursor == patLen;
    }

    if (memo[txtIdx][patIdx] != -1) {
        return memo[txtIdx][patIdx];
    }

    if (text[txtIdx] == pattern[patIdx]) {
        return memo[txtIdx][patIdx] = matches(text, pattern, txtIdx + 1, patIdx + 1);
    }

    if (pattern[patIdx] == '?') {
        // '?' consumes exactly one character from the text.
        return memo[txtIdx][patIdx] = matches(text, pattern, txtIdx + 1, patIdx + 1);
    }

    if (pattern[patIdx] == '*') {
        // '*' either grows to swallow one more character, or steps past
        // itself in the pattern while leaving the text untouched.
        bool skipStarInPattern = matches(text, pattern, txtIdx, patIdx + 1);
        bool consumeOneChar = matches(text, pattern, txtIdx + 1, patIdx);
        return memo[txtIdx][patIdx] = (skipStarInPattern || consumeOneChar);
    }

    return memo[txtIdx][patIdx] = 0;
}

}  // namespace glob_match
}  // namespace backtracking

static void runSelfCheck() {
    std::cout << "check 1 ";
    std::string textA = "baaabab";
    std::string patA = "*****ba*****ab";
    assert(backtracking::glob_match::matches(textA, patA, 0, 0) == 1);
    std::cout << "ok" << std::endl;

    std::cout << "check 2 ";
    std::string textB = "baaabab";
    std::string patB = "ba*****ab";
    assert(backtracking::glob_match::matches(textB, patB, 0, 0) == 1);
    std::cout << "ok" << std::endl;

    std::cout << "check 3 ";
    std::string textC = "baaabab";
    std::string patC = "ba*ab";
    assert(backtracking::glob_match::matches(textC, patC, 0, 0) == 1);
    std::cout << "ok" << std::endl;

    std::cout << "check 4 ";
    std::string textD = "baaabab";
    std::string patD = "a*ab";
    assert(backtracking::glob_match::matches(textD, patD, 0, 0) == 1);
    std::cout << "ok" << std::endl;

    std::cout << "check 5 ";
    std::string textE = "baaabab";
    std::string patE = "aa?ab";
    assert(backtracking::glob_match::matches(textE, patE, 0, 0) == 1);
    std::cout << "ok" << std::endl;
}

int main() {
    runSelfCheck();
    return 0;
}

/**
 * @file
 * @brief Implementation to [Check if a number is Even or Odd using Bitwise Operator]
 * (https://www.log2base2.com/c-examples/bitwise/odd-or-even-program-in-c-using-bitwise-operator.html)
 *
 * @details
 * Given an integer N, determine whether it is even or odd using bitwise manipulation.
 * The least significant bit (LSB) of a binary number determines its parity:
 * - If the LSB is 0, the number is even.
 * - If the LSB is 1, the number is odd.
 *
 * This can be checked efficiently using the bitwise AND operator (&) with 1.
 * - If (N & 1) == 0, N is even.
 * - If (N & 1) == 1, N is odd.
 *
 * Example:
 * Consider 8-bit binary representations of two numbers:
 *     Number: 10 (decimal) -> 00001010 (binary)
 *       LSB = 0 -> Even number
 * 
 *     Number: 13 (decimal) -> 00001101 (binary)
 *       LSB = 1 -> Odd number
 *
 * In both cases, evaluating (N & 1) isolates the LSB:
 * - For 10: 00001010 & 00000001 = 0  (Even)
 * - For 13: 00001101 & 00000001 = 1  (Odd)
 *
 * Worst Case Time Complexity: O(1)
 * Space Complexity: O(1)
 *
 * @author [Vedant Mukhedkar](https://github.com/git5v)
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for uint32_t
#include <iostream>  /// for IO operations
#include <string>    /// for std::string

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace even_odd
 * @brief Functions for checking if a number is even or odd using bitwise operations
 */
namespace even_odd {

/**
 * @brief Checks if a number is even or odd using bitwise AND.
 * @param N The number to check.
 * @returns "Even" if N is even, "Odd" if N is odd.
     */
        bool is_even(std::int64_t N) {
            return (N & 1) == 0 ? true : false;
        }

    }  // namespace even_odd
}  // namespace bit_manipulation

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    using bit_manipulation::even_odd::is_even;

    // Test Even numbers
    assert(is_even(0) == true);
    assert(is_even(2) == true);
    assert(is_even(100) == true);
    assert(is_even(-4) == true);
    assert(is_even(-1000) == true);

    // Test Odd numbers
    assert(is_even(1) == false);
    assert(is_even(3) == false);
    assert(is_even(101) == false);
    assert(is_even(-5) == false);
    assert(is_even(-999) == false);

    std::cout << "All test cases successfully passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Determine whether an integer is even or odd purely through bitwise
 * inspection of its least significant bit.
 *
 * @details
 * Every binary integer ends in either a 0 or a 1. That trailing digit alone
 * tells us the parity of the value:
 *   - trailing digit 0 -> the value is even
 *   - trailing digit 1 -> the value is odd
 *
 * Masking the value against 1 with the bitwise AND operator isolates that
 * final digit without needing a modulo operation.
 *
 * Walkthrough:
 *   14 -> 0b1110, mask with 1 -> 0, so 14 is even
 *   11 -> 0b1011, mask with 1 -> 1, so 11 is odd
 *
 * Time complexity: O(1)
 * Space complexity: O(1)
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for fixed width integer types
#include <iostream>  /// for std::cout

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace parity_check
 * @brief Routines that classify integers as even or odd via bit masking
 */
namespace parity_check {

/**
 * @brief Determines parity of a value by masking its lowest order bit.
 * @param value the signed integer to classify
 * @return true when value is even, false when it is odd
 */
bool has_even_parity(std::int64_t value) {
    bool lowest_bit_clear = ((value & 1) == 0);
    return lowest_bit_clear;
}

}  // namespace parity_check
}  // namespace bit_manipulation

/**
 * @brief Runs a battery of sanity checks against has_even_parity.
 * @returns void
 */
static void run_self_tests() {
    using bit_manipulation::parity_check::has_even_parity;

    // Values expected to be classified as even
    assert(has_even_parity(0));
    assert(has_even_parity(2));
    assert(has_even_parity(100));
    assert(has_even_parity(-4));
    assert(has_even_parity(-1000));

    // Values expected to be classified as odd
    assert(!has_even_parity(1));
    assert(!has_even_parity(3));
    assert(!has_even_parity(101));
    assert(!has_even_parity(-5));
    assert(!has_even_parity(-999));

    std::cout << "check_even_odd: every case matched the expected parity!"
               << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on successful exit
 */
int main() {
    run_self_tests();
    return 0;
}

/**
 * @file
 * @brief Implementation to
 * [Count number of bits to be flipped to convert A to B]
 * (https://www.geeksforgeeks.org/count-number-of-bits-to-be-flipped-to-convert-a-to-b/)
 * in an integer.
 *
 * @details
 * We are given two numbers A and B. Our task is to count the number of bits
 * needed to be flipped to convert A to B.
 *
 * Explanation:
 *
 * A  = 01010 B  = 10100
 * As we can see, the bits of A that need to be flipped are 01010.
 * If we flipthese bits, we get 10100, which is B.
 *
 * Worst Case Time Complexity: O(log n)
 * Space complexity: O(1)
 * @author [Yash Raj Singh](https://github.com/yashrajyash)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace count_bits_flip
 * @brief Functions for the [count bits
 * flip](https://www.geeksforgeeks.org/count-set-bits-in-an-integer/)
 * implementation
 */
namespace count_bits_flip {
/**
 * @brief The main function implements count of bits flip required
 * @param A is the given number whose bits will be flipped to get number B
 * @param B is the given target number
 * @returns total number of bits needed to be flipped to convert A to B
 */
std::uint64_t countBitsFlip(
    std::int64_t A,
    std::int64_t B) {  // int64_t is preferred over int so that
                       // no Overflow can be there.

    int count =
        0;  // "count" variable is used to count number of bits flip of the
            // number A to form B in binary representation of number 'n'
    A = A ^ B;
    while (A) {
        A = A & (A - 1);
        count++;
    }
    return count;
}
}  // namespace count_bits_flip
}  // namespace bit_manipulation

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // A = 10, B = 20 return 4
    assert(bit_manipulation::count_bits_flip::countBitsFlip(10, 20) == 4);
    // A = 20, B = 25 return 3
    assert(bit_manipulation::count_bits_flip::countBitsFlip(20, 25) == 3);
    // A = 7, B = 10 return 3
    assert(bit_manipulation::count_bits_flip::countBitsFlip(7, 10) == 3);
    // A = 17, B = 25 return 1
    assert(bit_manipulation::count_bits_flip::countBitsFlip(17, 25) == 1);
    // A = 11, B = 8 return 2
    assert(bit_manipulation::count_bits_flip::countBitsFlip(11, 8) == 2);
    // A = 21, B = 22 return 2
    assert(bit_manipulation::count_bits_flip::countBitsFlip(21, 22) == 2);
    // A = 7, B = 786 return 5
    assert(bit_manipulation::count_bits_flip::countBitsFlip(7, 786) == 5);
    std::cout << "All test cases successfully passed!" << std::endl;
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Determine how many individual bit flips are required to turn one
 * integer into another.
 *
 * @details
 * Given two integers `source` and `target`, we want the minimum count of bit
 * positions that differ between them.
 *
 * Approach:
 *   1. XOR the two numbers together. Every bit that differs between them
 *      becomes a 1 in the result; every bit that matches becomes 0.
 *   2. Count the 1 bits in that XOR result using Brian Kernighan's trick,
 *      which repeatedly clears the lowest set bit until nothing remains.
 *
 * Example:
 *   source = 0b01010, target = 0b10100
 *   XOR    = 0b11110 -> 4 bits differ, so 4 flips are needed.
 *
 * Time complexity: O(log n)
 * Space complexity: O(1)
 */
#include <cassert>   /// for assert
#include <cstdint>   /// for fixed width integer types
#include <iostream>  /// for std::cout

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace flip_distance
 * @brief Functions that compute the Hamming-style flip distance between
 * two integers
 */
namespace flip_distance {

/**
 * @brief Counts the bit flips necessary to convert one integer into another.
 * @param source the starting value
 * @param target the value we want to reach
 * @return number of bit positions that must be toggled
 */
std::uint64_t bits_to_flip(std::int64_t source, std::int64_t target) {
    std::int64_t differing_bits = source ^ target;

    std::uint64_t flips_needed = 0;
    while (differing_bits != 0) {
        differing_bits &= (differing_bits - 1);  // drop the lowest set bit
        ++flips_needed;
    }

    return flips_needed;
}

}  // namespace flip_distance
}  // namespace bit_manipulation

/**
 * @brief Exercises bits_to_flip against known input/output pairs.
 * @returns void
 */
static void run_self_tests() {
    using bit_manipulation::flip_distance::bits_to_flip;

    assert(bits_to_flip(10, 20) == 4);
    assert(bits_to_flip(20, 25) == 3);
    assert(bits_to_flip(7, 10) == 3);
    assert(bits_to_flip(17, 25) == 1);
    assert(bits_to_flip(11, 8) == 2);
    assert(bits_to_flip(21, 22) == 2);
    assert(bits_to_flip(7, 786) == 5);

    std::cout << "count_bits_flip: all expected flip counts matched!"
               << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on successful exit
 */
int main() {
    run_self_tests();
    return 0;
}

/**
 * @file
 * @brief Implementation to [count number of set bits of a number]
 * (https://www.geeksforgeeks.org/count-set-bits-in-an-integer/) in an
 * integer.
 *
 * @details
 * We are given an integer number. We need to calculate the number of set bits
 * in it.
 *
 * A binary number consists of two digits. They are 0 & 1. Digit 1 is known as
 * set bit in computer terms.
 * Worst Case Time Complexity: O(log n)
 * Space complexity: O(1)
 * @author [Swastika Gupta](https://github.com/Swastyy)
 * @author [Prashant Thakur](https://github.com/prashant-th18)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace count_of_set_bits
 * @brief Functions for the [count sets
 * bits](https://www.geeksforgeeks.org/count-set-bits-in-an-integer/)
 * implementation
 */
namespace count_of_set_bits {
/**
 * @brief The main function implements set bit count
 * @param n is the number whose set bit will be counted
 * @returns total number of set-bits in the binary representation of number `n`
 */
std::uint64_t countSetBits(
    std ::uint64_t n) {  // uint64_t is preferred over int so that
                        // no Overflow can be there.
                        //It's preferred over int64_t because it Guarantees that inputs are always non-negative, 
                        //which matches the algorithmic problem statement.
                        //set bit counting is conceptually defined only for non-negative numbers.
                        //Provides a type Safety: Using an unsigned type helps prevent accidental negative values,

    std::uint64_t count = 0;  // "count" variable is used to count number of set-bits('1')
                            // in binary representation of number 'n'
                            //Count is uint64_t because it Prevents theoretical overflow if someone passes very large integers.
                            //  Behavior stays the same for all normal inputs.
                            // Safer for edge cases.

    while (n != 0) {
        ++count;
        n = (n & (n - 1));
    }
    return count;
    // Why this algorithm is better than the standard one?
    // Because this algorithm runs the same number of times as the number of
    // set-bits in it. Means if my number is having "3" set bits, then this
    // while loop will run only "3" times!!
}
}  // namespace count_of_set_bits
}  // namespace bit_manipulation

static void test() {
    // n = 4 return 1
    assert(bit_manipulation::count_of_set_bits::countSetBits(4) == 1);
    // n = 6 return 2
    assert(bit_manipulation::count_of_set_bits::countSetBits(6) == 2);
    // n = 13 return 3
    assert(bit_manipulation::count_of_set_bits::countSetBits(13) == 3);
    // n = 9 return 2
    assert(bit_manipulation::count_of_set_bits::countSetBits(9) == 2);
    // n = 15 return 4
    assert(bit_manipulation::count_of_set_bits::countSetBits(15) == 4);
    // n = 25 return 3
    assert(bit_manipulation::count_of_set_bits::countSetBits(25) == 3);
    // n = 97 return 3
    assert(bit_manipulation::count_of_set_bits::countSetBits(97) == 3);
    // n = 31 return 5
    assert(bit_manipulation::count_of_set_bits::countSetBits(31) == 5);
    std::cout << "All test cases successfully passed!" << std::endl;
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Tally the number of set (1) bits inside an unsigned integer's
 * binary representation.
 *
 * @details
 * Binary digits are either 0 or 1; a digit equal to 1 is commonly called a
 * "set bit". This file counts how many set bits appear in a given value.
 *
 * Rather than shifting through every bit position and testing each one
 * individually, we repeatedly apply `n & (n - 1)`, an operation that clears
 * the least significant set bit on each pass. The loop therefore executes
 * exactly as many times as there are set bits, which is faster than a fixed
 * 32/64 iteration scan whenever the number of set bits is small.
 *
 * Time complexity: O(log n)
 * Space complexity: O(1)
 */
#include <cassert>   /// for assert
#include <cstdint>   /// for fixed width integer types
#include <iostream>  /// for std::cout

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace population_count
 * @brief Functions that tally the set bits within an integer
 */
namespace population_count {

/**
 * @brief Counts how many bits are set to 1 in the given value.
 * @param value the unsigned integer whose set bits should be counted
 * @return the number of 1 bits present in value's binary form
 */
std::uint64_t tally_set_bits(std::uint64_t value) {
    // uint64_t avoids sign related surprises since bit counting only makes
    // sense for non-negative quantities, and it comfortably avoids overflow
    // even for very large inputs.
    std::uint64_t set_bit_total = 0;

    while (value != 0) {
        value = value & (value - 1);  // clear the lowest set bit
        ++set_bit_total;
    }

    return set_bit_total;
    // This runs proportionally to the number of set bits rather than the
    // total bit width, so sparse numbers finish very quickly.
}

}  // namespace population_count
}  // namespace bit_manipulation

/**
 * @brief Validates tally_set_bits against known values.
 * @returns void
 */
static void run_self_tests() {
    using bit_manipulation::population_count::tally_set_bits;

    assert(tally_set_bits(4) == 1);
    assert(tally_set_bits(6) == 2);
    assert(tally_set_bits(13) == 3);
    assert(tally_set_bits(9) == 2);
    assert(tally_set_bits(15) == 4);
    assert(tally_set_bits(25) == 3);
    assert(tally_set_bits(97) == 3);
    assert(tally_set_bits(31) == 5);

    std::cout << "count_of_set_bits: every population count was correct!"
               << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on successful exit
 */
int main() {
    run_self_tests();
    return 0;
}

/**
 * @file
 * @brief [Count the number of
 * ciphers](https://www.tutorialspoint.com/count-trailing-zeros-in-factorial-of-a-number-in-cplusplus) in `n!` implementation
 * @details
 * Given an integer number as input. The goal is to find the number of trailing
 zeroes in the factorial calculated for
 * that number. A factorial of a number N is a product of all numbers in the
 range [1, N].

 * We know that we get a trailing zero only if the number is multiple of 10 or
 has a factor pair (2,5). In all factorials of
 * any number greater than 5, we have many 2s more than 5s in the prime
 factorization of that number. Dividing a
 * number by powers of 5 will give us the count of 5s in its factors. So, the
 number of 5s will tell us the number of trailing zeroes.
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace count_of_trailing_ciphers_in_factorial_n
 * @brief Functions for the [Count the number of
 * ciphers](https://www.tutorialspoint.com/count-trailing-zeros-in-factorial-of-a-number-in-cplusplus)
 * in `n!` implementation
 */
namespace count_of_trailing_ciphers_in_factorial_n {
/**
 * @brief Function to count the number of the trailing ciphers
 * @param n number for which `n!` ciphers are returned
 * @return count, Number of ciphers in `n!`.
 */
uint64_t numberOfCiphersInFactorialN(uint64_t n) {
    // count is to store the number of 5's in factorial(n)
    uint64_t count = 0;

    // Keep dividing n by powers of
    // 5 and update count
    for (uint64_t i = 5; n / i >= 1; i *= 5) {
        count += static_cast<uint64_t>(n) / i;
    }

    return count;
}
}  // namespace count_of_trailing_ciphers_in_factorial_n
}  // namespace bit_manipulation

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::cout << "1st test ";
    assert(bit_manipulation::count_of_trailing_ciphers_in_factorial_n::
               numberOfCiphersInFactorialN(395) == 97);
    std::cout << "passed" << std::endl;

    // 2nd test
    std::cout << "2nd test ";
    assert(bit_manipulation::count_of_trailing_ciphers_in_factorial_n::
               numberOfCiphersInFactorialN(977) == 242);
    std::cout << "passed" << std::endl;

    // 3rd test
    std::cout << "3rd test ";
    assert(bit_manipulation::count_of_trailing_ciphers_in_factorial_n::
               numberOfCiphersInFactorialN(871) == 215);
    std::cout << "passed" << std::endl;

    // 4th test
    std::cout << "4th test ";
    assert(bit_manipulation::count_of_trailing_ciphers_in_factorial_n::
               numberOfCiphersInFactorialN(239) == 57);
    std::cout << "passed" << std::endl;

    // 5th test
    std::cout << "5th test ";
    assert(bit_manipulation::count_of_trailing_ciphers_in_factorial_n::
               numberOfCiphersInFactorialN(0) == 0);
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Compute how many trailing zero digits appear in `n!` (n factorial).
 *
 * @details
 * A trailing zero in a factorial arises from a factor pair of 2 and 5 in its
 * prime factorization. Because factorials always contain far more factors of
 * 2 than factors of 5, the count of trailing zeroes is limited entirely by
 * how many times 5 divides into the product 1 * 2 * ... * n.
 *
 * We obtain that count by summing floor(n / 5) + floor(n / 25) +
 * floor(n / 125) + ... until the divisor exceeds n.
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for fixed width integer types
#include <iostream>  /// for std::cout

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace factorial_trailing_zero_count
 * @brief Functions for counting trailing zero digits of n!
 */
namespace factorial_trailing_zero_count {

/**
 * @brief Counts the trailing zero digits present in n factorial.
 * @param n the number whose factorial's trailing zeroes we want
 * @return the number of trailing zero digits in n!
 */
uint64_t trailing_zero_count(uint64_t n) {
    uint64_t five_power = 5;
    uint64_t zero_count = 0;

    // Each successive power of five contributes its own share of factors
    // of 5 found among 1..n; sum them all up.
    while (n / five_power >= 1) {
        zero_count += n / five_power;
        five_power *= 5;
    }

    return zero_count;
}

}  // namespace factorial_trailing_zero_count
}  // namespace bit_manipulation

/**
 * @brief Runs a series of checks against trailing_zero_count.
 * @returns void
 */
static void run_self_tests() {
    using bit_manipulation::factorial_trailing_zero_count::trailing_zero_count;

    std::cout << "case 1: ";
    assert(trailing_zero_count(395) == 97);
    std::cout << "ok" << std::endl;

    std::cout << "case 2: ";
    assert(trailing_zero_count(977) == 242);
    std::cout << "ok" << std::endl;

    std::cout << "case 3: ";
    assert(trailing_zero_count(871) == 215);
    std::cout << "ok" << std::endl;

    std::cout << "case 4: ";
    assert(trailing_zero_count(239) == 57);
    std::cout << "ok" << std::endl;

    std::cout << "case 5: ";
    assert(trailing_zero_count(0) == 0);
    std::cout << "ok" << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on successful exit
 */
int main() {
    run_self_tests();
    return 0;
}

/**
 * @file
 * @brief Implementation to find the non repeating integer
 * in an array of repeating integers. [Single
 * Number](https://leetcode.com/problems/single-number/)
 *
 * @details
 * Given an array of integers in which all of the numbers occur exactly
 * twice except one integer which occurs only once. Find the non-repeating
 * integer.
 *
 * Worst Case Time Complexity: O(n)
 * Space complexity: O(1)

 * @author [Ravidev Pandey](https://github.com/literalEval)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// storing the numbers

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace find_non_repeating_integer
 * @brief Functions to find the non repeating integer
 * in an array of repeating integers. [Single
 * Number](https://leetcode.com/problems/single-number/)
 */
namespace find_non_repeating_integer {
/**
 * @brief The main function implements find single number
 * @param nums vector of integers
 * @returns returns the integer that occurs only once
 */
int64_t find_non_repeating_integer(const std::vector<int>& nums) {
    // The idea is based on the property of XOR.
    // We know that 'a' XOR 'a' is '0' and '0' XOR 'b'
    // is b.
    // Using this, if we XOR all the elements of the array,
    // the repeating elements will give '0' and this '0'
    // with the single number will give the number itself.

    int _xor = 0;

    for (const int& num: nums) {
        _xor ^= num;
    }

    return _xor;
}
}  // namespace find_non_repeating_integer
}  // namespace bit_manipulation

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // n = 10,2 return 14

    std::vector<int> nums_one{1, 1, 2, 2, 4, 5, 5};
    std::vector<int> nums_two{203, 3434, 4545, 3434, 4545};
    std::vector<int> nums_three{90, 1, 3, 90, 3};

    assert(bit_manipulation::find_non_repeating_integer::
               find_non_repeating_integer(nums_one) ==
           4);  // 4 is non repeating
    assert(bit_manipulation::find_non_repeating_integer::
               find_non_repeating_integer(nums_two) ==
           203);  // 203 is non repeating
    assert(bit_manipulation::find_non_repeating_integer::
               find_non_repeating_integer(nums_three) ==
           1);  // 1 is non repeating

    std::cout << "All test cases successfully passed!" << std::endl;
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Locate the single unpaired integer inside a collection where every
 * other value appears exactly twice. See the classic ["Single
 * Number"](https://leetcode.com/problems/single-number/) problem.
 *
 * @details
 * Given a list of integers where each value shows up exactly two times
 * except for one lone outlier, identify that outlier.
 *
 * The XOR operator cancels identical values (a ^ a == 0) and leaves any
 * value XORed with zero unchanged (0 ^ b == b). Folding XOR across the
 * entire list therefore cancels out every paired value, leaving only the
 * unpaired one behind.
 *
 * Time complexity: O(n)
 * Space complexity: O(1)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout
#include <vector>    /// for std::vector

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace lone_value_finder
 * @brief Functions to locate the unpaired integer in a mostly-paired
 * collection
 */
namespace lone_value_finder {

/**
 * @brief Finds the single value that doesn't have a matching duplicate.
 * @param values collection of integers, all but one appearing twice
 * @return the integer that occurs exactly once
 */
int64_t locate_unpaired_value(const std::vector<int>& values) {
    // Folding every element together with XOR cancels the duplicated
    // entries pairwise and leaves the lone survivor.
    int accumulator = 0;

    for (std::size_t idx = 0; idx < values.size(); ++idx) {
        accumulator ^= values[idx];
    }

    return accumulator;
}

}  // namespace lone_value_finder
}  // namespace bit_manipulation

/**
 * @brief Runs sample cases through locate_unpaired_value.
 * @returns void
 */
static void run_self_tests() {
    using bit_manipulation::lone_value_finder::locate_unpaired_value;

    std::vector<int> sample_a{1, 1, 2, 2, 4, 5, 5};
    std::vector<int> sample_b{203, 3434, 4545, 3434, 4545};
    std::vector<int> sample_c{90, 1, 3, 90, 3};

    assert(locate_unpaired_value(sample_a) == 4);    // 4 has no pair
    assert(locate_unpaired_value(sample_b) == 203);  // 203 has no pair
    assert(locate_unpaired_value(sample_c) == 1);    // 1 has no pair

    std::cout << "find_non_repeating_number: located the lone value in "
                 "every sample!"
              << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on successful exit
 */
int main() {
    run_self_tests();
    return 0;
}

/**
 * @brief Program to generate n-bit [Gray 
 * code](https://en.wikipedia.org/wiki/Gray_code)
 * 
 * @details
 * Gray code is a binary numeral system
 * where consecutive values differ in exactly 1 bit.
 * The following code offers one of many possible Gray codes 
 * given some pre-determined number of bits.
 */

#include <bitset>  /// for gray code representation
#include <cassert>  /// for assert
#include <iostream>  /// for IO operations
#include <vector>  /// for vector data structure

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace gray_code
 * @brief Generate n-bit Gray code
 */
namespace gray_code {
/**
 * @brief The main function to generate n-bit Gray code
 *
 * @param n Number of bits
 * @return A vector that stores the n-bit Gray code
 */
std::vector<std::bitset<32>> gray_code_generation(int n) {
    std::vector<std::bitset<32>> gray_code = {};  // Initialise empty vector

    // No Gray codes for non-positive values of n
    if (n <= 0) {
        return gray_code;
    }

    int total_codes = 1 << n;  // Number of n-bit gray codes

    for (int i = 0; i < total_codes; i++) {
        int gray_num = i ^ (i >> 1);  // Gray code formula
        gray_code.push_back(std::bitset<32>(gray_num));  // Store the value
    }

    return gray_code;
} 
}  // namespace gray_code
}  // namespace bit_manipulation

/**
 * @brief Self-test implementation
 *
 * @returns void
 */
