/**
 * @brief Build the sequence of n-bit [Gray
 * codes](https://en.wikipedia.org/wiki/Gray_code).
 *
 * @details
 * A Gray code ordering is a sequence of binary values in which each
 * consecutive pair differs in exactly one bit position. This file produces
 * one valid ordering for a requested bit width.
 *
 * The classic construction converts an ordinary binary counter value `i`
 * into its corresponding Gray code word via `i ^ (i >> 1)`.
 */

#include <bitset>    /// for representing each code as bits
#include <cassert>   /// for assert
#include <iostream>  /// for std::cout
#include <vector>    /// for std::vector

/**
 * @namespace bit_manipulation
 * @brief Bit manipulation algorithms
 */
namespace bit_manipulation {
/**
 * @namespace gray_sequence
 * @brief Builds n-bit Gray code sequences
 */
namespace gray_sequence {

/**
 * @brief Produces the full n-bit Gray code sequence.
 *
 * @param bit_width how many bits each code word should contain
 * @return a vector holding every code word in Gray code order
 */
std::vector<std::bitset<32>> build_gray_sequence(int bit_width) {
    std::vector<std::bitset<32>> sequence;  // starts empty

    // Non-positive widths have no meaningful Gray sequence.
    if (bit_width <= 0) {
        return sequence;
    }

    int word_count = 1 << bit_width;  // total codes for this bit width

    for (int counter = 0; counter < word_count; ++counter) {
        int gray_word = counter ^ (counter >> 1);  // standard Gray formula
        sequence.emplace_back(std::bitset<32>(gray_word));
    }

    return sequence;
}

}  // namespace gray_sequence
}  // namespace bit_manipulation

/**
 * @brief Confirms build_gray_sequence matches known reference sequences.
 *
 * @returns void
 */
static void run_self_tests() {
    using bit_manipulation::gray_sequence::build_gray_sequence;

    std::vector<std::bitset<32>> expected_for_negative = {};

    std::vector<std::bitset<32>> expected_for_zero = {};

