}

/** Main function */
int main() {
    std::srand(std::time(nullptr));
    std::cout << "Key dictionary: (" << std::strlen(ciphers::STRKEY) << ")\n\t"
              << ciphers::STRKEY << "\n";

    std::string text = "This is a simple text with numb3r5 and exclamat!0n.";

    test1(text);
    test2(text);

    return 0;
}

/**
 * @file hill_cipher.cpp
 * @brief Alternate implementation of the Hill cipher
 * (https://en.wikipedia.org/wiki/Hill_cipher) block cipher algorithm.
 *
 * The Hill cipher encrypts fixed-size blocks of text by treating each block
 * as a vector and multiplying it by a square key matrix modulo the size of
 * the character alphabet. Decryption uses the modular inverse of that
 * matrix. For the matrix to be usable it must be invertible modulo the
 * alphabet size, i.e. its determinant must be coprime with that size.
 *
 * This variant restructures the original HillCipher class into a set of
 * free functions grouped in a namespace, but preserves the same overall
 * algorithm: random key generation, modular matrix inversion via
 * Gauss-Jordan elimination, and block encode/decode.
 *
 * \note Relies on determinant_lu from lu_decomposition.h, same as original.
 */

#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>
#ifdef _OPENMP
#include <omp.h>
#endif

#include "../numerical_methods/lu_decomposition.h"

/// Pretty-prints a matrix for debugging/output purposes.
template <typename T>
static std::ostream &operator<<(std::ostream &out, matrix<T> const &m) {
    constexpr int kColumnWidth = 15;
    constexpr char kFill = ' ';
    for (size_t r = 0; r < m.size(); r++) {
        for (size_t c = 0; c < m[r].size(); c++) {
            out << std::left << std::setw(kColumnWidth) << std::setfill(kFill)
                << m[r][c];
        }
        out << std::endl;
    }
    return out;
}

namespace ciphers {

/// The alphabet of characters the cipher can encode/decode.
static const char *kAlphabet =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789~!@#$%^&"
    "*()_+`-=[]{}|;':\",./<>?\\\r\n \0";

namespace hill_detail {

/// Generates a uniform random value scaled into [lo, hi).
template <typename TIn, typename TOut>
TOut uniform_random(TIn lo, TIn hi) {
    long double unit = static_cast<long double>(std::rand()) / RAND_MAX;
    return static_cast<TOut>(unit * (hi - lo) + lo);
}

/// Fills a matrix with random integers in [lo, hi) and returns its
/// determinant.
template <typename TIn, typename TVal>
double fill_random_matrix(matrix<TVal> *target, TIn lo, TIn hi) {
    for (size_t r = 0; r < target->size(); r++) {
        for (size_t c = 0; c < target[0][0].size(); c++) {
            target[0][r][c] = uniform_random<TIn, TVal>(lo, hi);
        }
    }
    return determinant_lu(*target);
}

/// Euclidean algorithm for greatest common divisor.
template <typename T>
T gcd_of(T x, T y) {
    if (y > x) std::swap(x, y);
    while (y != 0) {
        T rem = x % y;
        x = y;
        y = rem;
    }
    return x;
}

/// Applies the key matrix to a block vector, reducing modulo the alphabet
/// size.
std::valarray<uint8_t> apply_matrix(const std::valarray<uint8_t> &block,
                                    const matrix<int> &key) {
    std::valarray<uint8_t> transformed(block);
    size_t alphabet_len = std::strlen(kAlphabet);

    for (size_t row = 0; row < key.size(); row++) {
        int acc = 0;
        for (size_t col = 0; col < block.size(); col++) {
            acc += key[row][col] * block[col];
        }
        transformed[row] = static_cast<uint8_t>(acc % alphabet_len);
    }
    return transformed;
}

/// Looks up the character stored at a given alphabet index.
inline char char_at(uint8_t index) { return kAlphabet[index]; }

/// Finds the alphabet index of a character (linear scan).
inline uint8_t index_of_char(char ch) {
    size_t alphabet_len = std::strlen(kAlphabet);
    for (size_t i = 0; i <= alphabet_len; i++) {
        if (kAlphabet[i] == ch) return static_cast<uint8_t>(i);
    }
    std::cerr << __func__ << ":" << __LINE__ << ": (" << ch
              << ") Should not reach here!\n";
    return 0;
}

/// Shared routine for block-based encode/decode: chunks `text` into blocks
/// matching the key's dimension and multiplies each block by `key`.
std::string apply_block_cipher(const std::string &text, const matrix<int> &key) {
    size_t text_len = text.length();
    size_t block_size = key.size();

    size_t padded_len = (text_len % block_size == 0)
                            ? text_len
                            : text_len + block_size - (text_len % block_size);
    std::string out(padded_len, '\0');

    int i;
#ifdef _OPENMP
#pragma parallel omp for private(i)
#endif
    for (i = 0; i < static_cast<int>(padded_len) - static_cast<int>(block_size) + 1;
         i += static_cast<int>(block_size)) {
        std::valarray<uint8_t> block(block_size);
        for (size_t j = 0; j < block_size; j++) {
            block[j] = index_of_char(text[i + j]);
        }

        block = apply_matrix(block, key);

        for (size_t j = 0; j < block_size; j++) {
            out[i + j] = kAlphabet[block[j]];
        }
    }

    return out;
}

/// Computes the matrix inverse via Gauss-Jordan row reduction (no modular
/// arithmetic here -- that's applied afterwards).
template <typename T>
matrix<double> gauss_jordan_inverse(matrix<T> const &input) {
    size_t n = input.size();

    matrix<double> inverse(n, std::valarray<double>(n));
    for (size_t r = 0; r < n; r++) {
        for (size_t c = 0; c < n; c++) {
            inverse[r][c] = (r == c) ? 1.0 : 0.0;
        }
    }

    if (input.size() != input[0].size()) {
        std::cerr << "Input must be a square matrix!" << std::endl;
        return inverse;
    }

    matrix<double> work(n, std::valarray<double>(n));
    for (size_t r = 0; r < n; r++) {
        for (size_t c = 0; c < n; c++) {
            work[r][c] = static_cast<double>(input[r][c]);
        }
    }

    for (size_t pivot_row = 0; pivot_row < n; pivot_row++) {
        for (size_t alt_row = pivot_row; alt_row < n && work[pivot_row][pivot_row] == 0;
             alt_row++) {
            work[pivot_row] = work[pivot_row] + work[alt_row];
            inverse[pivot_row] = inverse[pivot_row] + inverse[alt_row];
        }

        for (size_t alt_col = pivot_row;
             alt_col < n && work[pivot_row][pivot_row] == 0; alt_col++) {
            for (size_t r2 = 0; r2 < n; r2++) {
                work[r2][pivot_row] = work[r2][pivot_row] + work[r2][alt_col];
                inverse[r2][pivot_row] =
                    inverse[r2][pivot_row] + inverse[r2][alt_col];
            }
        }

        if (work[pivot_row][pivot_row] == 0) {
            std::cerr << "Low-rank matrix, no inverse!" << std::endl;
            return inverse;
        }

        double pivot_value = work[pivot_row][pivot_row];
        work[pivot_row] = work[pivot_row] / pivot_value;
        inverse[pivot_row] = inverse[pivot_row] / pivot_value;

        for (size_t r2 = 0; r2 < n; r2++) {
            if (r2 == pivot_row) continue;
            double factor = work[r2][pivot_row];
            work[r2] = work[r2] - factor * work[pivot_row];
            inverse[r2] = inverse[r2] - factor * inverse[pivot_row];
        }
    }

    return inverse;
}

/// Modulo that always returns a non-negative remainder.
inline int positive_mod(int a, int m) {
    int r = a % m;
    return r < 0 ? r + m : r;
}

}  // namespace hill_detail

/**
 * @brief Random key generation, modular inversion, and block
 * encode/decode for the Hill cipher.
 */
namespace hill_cipher {

/**
 * @brief Generates a random square encryption key matrix that is invertible
 * modulo the alphabet length.
 */
matrix<int> make_encryption_key(size_t dimension, int lo = 0, int hi = 10) {
    matrix<int> key(dimension, std::valarray<int>(dimension));
    int alphabet_len = static_cast<int>(std::strlen(kAlphabet));

    double det;
    int det_int;
    do {
        det = hill_detail::fill_random_matrix(&key, lo, hi);
        det_int = static_cast<int>(det);
        if (det_int < 0) det_int %= alphabet_len;
    } while (std::abs(det) > 1e3 || det < 0.1 || !std::isfinite(det) ||
             hill_detail::gcd_of(det_int, alphabet_len) != 1);

    return key;
}

/**
 * @brief Derives the decryption key (modular inverse of the encryption key)
 * from a given encryption key.
 */
matrix<int> make_decryption_key(matrix<int> const &encryption_key) {
    size_t dimension = encryption_key.size();
    int alphabet_len = static_cast<int>(std::strlen(kAlphabet));

    matrix<int> decryption_key(dimension, std::valarray<int>(dimension));
    int det = static_cast<int>(determinant_lu(encryption_key));
    int det_mod = det < 0 ? det % alphabet_len : det;

    matrix<double> raw_inverse = hill_detail::gauss_jordan_inverse(encryption_key);

    int det_inverse = -1;
    for (int candidate = 0; candidate < alphabet_len; candidate++) {
        if (hill_detail::positive_mod(det_mod * candidate, alphabet_len) == 1) {
            det_inverse = candidate;
            break;
        }
    }

    if (det_inverse == -1) {
        std::cerr << "Could not find a co-prime for inversion\n";
        std::exit(EXIT_FAILURE);
    }

    int scale = det_inverse * det;

    int i;
#ifdef _OPENMP
#pragma parallel omp for private(i)
#endif
    for (i = 0; i < static_cast<int>(dimension); i++) {
        for (int j = 0; j < static_cast<int>(dimension); j++) {
            int rounded = static_cast<int>(std::round(raw_inverse[i][j] * scale));
            decryption_key[i][j] = hill_detail::positive_mod(rounded, alphabet_len);
        }
    }
    return decryption_key;
}

/**
 * @brief Generates a matching encryption/decryption key pair, retrying
 * generation until the decryption key is also well conditioned.
 */
std::pair<matrix<int>, matrix<int>> make_key_pair(size_t dimension, int lo = 0,
                                                  int hi = 10) {
    matrix<int> enc_key = make_encryption_key(dimension);
    matrix<int> dec_key = make_decryption_key(enc_key);
    double dec_det = determinant_lu(dec_key);

    while (std::abs(dec_det) < 0.1 || std::abs(dec_det) > 1e3) {
        enc_key = make_encryption_key(dimension, lo, hi);
        dec_key = make_decryption_key(enc_key);
        dec_det = determinant_lu(dec_key);
    }
    return std::make_pair(enc_key, dec_key);
}

/// Encrypts `plaintext` using `key`.
std::string encrypt(const std::string &plaintext, const matrix<int> &key) {
    return hill_detail::apply_block_cipher(plaintext, key);
}

/// Decrypts `ciphertext` using `key`.
std::string decrypt(const std::string &ciphertext, const matrix<int> &key) {
    return hill_detail::apply_block_cipher(ciphertext, key);
}

}  // namespace hill_cipher
}  // namespace ciphers

namespace {

/// Demo run using a randomly generated 3x3 key.
void demo_small_key(const std::string &text) {
    std::cout << "=== Demo: 3x3 key ===\nplaintext:\n\t" << text << std::endl;

    auto keys = ciphers::hill_cipher::make_key_pair(3, 0, 100);
    matrix<int> enc_key = keys.first;
    matrix<int> dec_key = keys.second;

    std::string ciphertext = ciphers::hill_cipher::encrypt(text, enc_key);
    std::cout << "ciphertext:\n\t" << ciphertext << std::endl;

    std::string roundtrip = ciphers::hill_cipher::decrypt(ciphertext, dec_key);
    std::cout << "roundtrip:\n\t" << roundtrip << std::endl;

    std::ofstream log_file("hill_cipher_test1.txt");
    log_file << "Block size: " << enc_key.size() << "\n";
    log_file << "Encryption Key:\n" << enc_key;
    log_file << "\nDecryption Key:\n" << dec_key;
    log_file.close();

    assert(roundtrip == text);
    std::cout << "3x3 demo: OK\n";
}

/// Demo run using a randomly generated 8x8 key.
void demo_large_key(const std::string &text) {
    std::cout << "=== Demo: 8x8 key ===\nplaintext:\n\t" << text << std::endl;

    auto keys = ciphers::hill_cipher::make_key_pair(8, 0, 3);
    matrix<int> enc_key = keys.first;
    matrix<int> dec_key = keys.second;

    std::string ciphertext = ciphers::hill_cipher::encrypt(text, enc_key);
    std::cout << "ciphertext:\n\t" << ciphertext << std::endl;

    std::string roundtrip = ciphers::hill_cipher::decrypt(ciphertext, dec_key);
    std::cout << "roundtrip:\n\t" << roundtrip << std::endl;

    std::ofstream log_file("hill_cipher_test2.txt");
    log_file << "Block size: " << enc_key.size() << "\n";
    log_file << "Encryption Key:\n" << enc_key;
    log_file << "\nDecryption Key:\n" << dec_key;
    log_file.close();

    assert(roundtrip.compare(0, text.size(), text) == 0);
    std::cout << "8x8 demo: OK\n";
}

}  // namespace

int main() {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));
    std::cout << "Alphabet size: (" << std::strlen(ciphers::kAlphabet) << ")\n\t"
              << ciphers::kAlphabet << "\n";

    std::string sample_text = "This is a simple text with numb3r5 and exclamat!0n.";

    demo_small_key(sample_text);
    demo_large_key(sample_text);

    return 0;
}

/**
 * @file
 * @author [Deep Raval](https://github.com/imdeep2905)
 *
 * @brief Implementation of [Morse Code]
 * (https://en.wikipedia.org/wiki/Morse_code).
 *
 * @details
 * Morse code is a method used in telecommunication to encode text characters
 * as standardized sequences of two different signal durations, called dots
 * and dashes or dits and dahs. Morse code is named after Samuel Morse, an
 * inventor of the telegraph.
 */
#include <cassert>
#include <iostream>
#include <string>
#include <vector>

/** \namespace ciphers
 * \brief Algorithms for encryption and decryption
 */
namespace ciphers {
/** \namespace morse
 * \brief Functions for [Morse Code]
 * (https://en.wikipedia.org/wiki/Morse_code).
 */
namespace morse {
/**
 * Get the morse representation for given character.
 * @param c Character
 * @returns morse representation string of character
 */
std::string char_to_morse(const char &c) {
    // return corresponding morse code
    switch (c) {
        case 'a':
            return ".-";
        case 'b':
            return "-...";
        case 'c':
            return "-.-.";
        case 'd':
            return "-..";
        case 'e':
            return ".";
        case 'f':
            return "..-.";
        case 'g':
            return "--.";
        case 'h':
            return "....";
        case 'i':
            return "..";
        case 'j':
            return ".---";
        case 'k':
            return "-.-";
        case 'l':
            return ".-..";
        case 'm':
            return "--";
        case 'n':
            return "-.";
        case 'o':
            return "---";
        case 'p':
            return ".--.";
        case 'q':
            return "--.-";
        case 'r':
            return ".-.";
        case 's':
            return "...";
        case 't':
            return "-";
        case 'u':
            return "..-";
        case 'v':
            return "...-";
        case 'w':
            return ".--";
        case 'x':
            return "-..-";
        case 'y':
            return "-.--";
        case 'z':
            return "--..";
        case '1':
            return ".----";
        case '2':
            return "..---";
        case '3':
            return "...--";
        case '4':
            return "....-";
        case '5':
            return ".....";
        case '6':
            return "-....";
        case '7':
            return "--...";
        case '8':
            return "---..";
        case '9':
            return "----.";
        case '0':
            return "-----";
        default:
            std::cerr << "Found invalid character: " << c << ' ' << std::endl;
            std::exit(0);
    }
}
/**
 * Get character from the morse representation.
 * @param s Morse representation
 * @returns corresponding character
 */
char morse_to_char(const std::string &s) {
    // return corresponding character
    if (s == ".-") {
        return 'a';
    } else if (s == "-...") {
        return 'b';
    } else if (s == "-.-.") {
        return 'c';
    } else if (s == "-..") {
        return 'd';
    } else if (s == ".") {
        return 'e';
    } else if (s == "..-.") {
        return 'f';
    } else if (s == "--.") {
        return 'g';
    } else if (s == "....") {
        return 'h';
    } else if (s == "..") {
        return 'i';
    } else if (s == ".---") {
        return 'j';
    } else if (s == "-.-") {
        return 'k';
    } else if (s == ".-..") {
        return 'l';
    } else if (s == "--") {
        return 'm';
    } else if (s == "-.") {
        return 'n';
    } else if (s == "---") {
        return 'o';
    } else if (s == ".--.") {
        return 'p';
    } else if (s == "--.-") {
        return 'q';
    } else if (s == ".-.") {
        return 'r';
    } else if (s == "...") {
        return 's';
    } else if (s == "-") {
        return 't';
    } else if (s == "..-") {
        return 'u';
    } else if (s == "...-") {
        return 'v';
    } else if (s == ".--") {
        return 'w';
    } else if (s == "-..-") {
        return 'x';
    } else if (s == "-.--") {
        return 'y';
    } else if (s == "--..") {
        return 'z';
    } else if (s == ".----") {
        return '1';
    } else if (s == "..---") {
        return '2';
    } else if (s == "...--") {
        return '3';
    } else if (s == "....-") {
        return '4';
    } else if (s == ".....") {
        return '5';
    } else if (s == "-....") {
        return '6';
    } else if (s == "--...") {
        return '7';
    } else if (s == "---..") {
        return '8';
    } else if (s == "----.") {
        return '9';
    } else if (s == "-----") {
        return '0';
    } else {
        std::cerr << "Found invalid Morse code: " << s << ' ' << std::endl;
        std::exit(0);
    }
}
/**
 * Encrypt given text using morse code.
 * @param text text to be encrypted
 * @returns new encrypted text
 */
std::string encrypt(const std::string &text) {
    std::string encrypted_text = "";  // Empty string to store encrypted text
    // Going through each character of text and converting it
    // to morse representation
    for (const char &c : text) {
        encrypted_text += ciphers::morse::char_to_morse(c) + " ";
    }
    return encrypted_text;  // Returning encrypted text
}
/**
 * Decrypt given morse coded text.
 * @param text text to be decrypted
 * @returns new decrypted text
 */
std::string decrypt(const std::string &text) {
    // Going through each character of text and converting it
    // back to normal representation.
    std::string decrypted_text = "";  // Empty string to store decrypted text
    // Spliting string (with delimiter = " ") and storing it
    // in vector
    std::size_t pos_start = 0, pos_end = 0, delim_len = 1;
    std::vector<std::string> splits;
    while ((pos_end = text.find(' ', pos_start)) != std::string::npos) {
        std::string token = text.substr(pos_start, pos_end - pos_start);
        pos_start = pos_end + delim_len;
        splits.push_back(token);
    }

    // Traversing through each morse code string
    for (const std::string &s : splits) {
        // Add corresponding character
        decrypted_text += ciphers::morse::morse_to_char(s);
    }

    return decrypted_text;  // Returning decrypted text
}
}  // namespace morse
}  // namespace ciphers

/**
 * @brief Function to test above algorithm
 * @returns void
 */
static void test() {
    // Test 1
    std::string text1 = "01234567890";
    std::string encrypted1 = ciphers::morse::encrypt(text1);
    std::string decrypted1 = ciphers::morse::decrypt(encrypted1);
    assert(text1 == decrypted1);
    std::cout << "Original text : " << text1 << std::endl;
    std::cout << "Encrypted text : " << encrypted1 << std::endl;
    std::cout << "Decrypted text : " << decrypted1 << std::endl;
    // Test 2
    std::string text2 = "abcdefghijklmnopqrstuvwxyz";
    std::string encrypted2 = ciphers::morse::encrypt(text2);
    std::string decrypted2 = ciphers::morse::decrypt(encrypted2);
    assert(text2 == decrypted2);
    std::cout << "Original text : " << text2 << std::endl;
    std::cout << "Encrypted text : " << encrypted2 << std::endl;
    std::cout << "Decrypted text : " << decrypted2 << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Testing
    test();
    return 0;
}

/**
 * @brief Encoder/decoder for International Morse Code.
 *
 * @details
 * Morse code represents letters and digits as sequences of short and long
 * signals (dots and dashes). This file maps single characters to their
 * Morse representation and back.
 */
#include <cassert>
#include <iostream>
#include <string>
#include <vector>

namespace ciphers {
namespace morse_code {

/// Maps a single lowercase letter or digit to its Morse pattern.
std::string letter_to_pattern(const char &letter) {
    switch (letter) {
        case 'a': return ".-";
        case 'b': return "-...";
        case 'c': return "-.-.";
        case 'd': return "-..";
        case 'e': return ".";
        case 'f': return "..-.";
        case 'g': return "--.";
        case 'h': return "....";
        case 'i': return "..";
        case 'j': return ".---";
        case 'k': return "-.-";
        case 'l': return ".-..";
        case 'm': return "--";
        case 'n': return "-.";
        case 'o': return "---";
        case 'p': return ".--.";
        case 'q': return "--.-";
        case 'r': return ".-.";
        case 's': return "...";
        case 't': return "-";
        case 'u': return "..-";
        case 'v': return "...-";
        case 'w': return ".--";
        case 'x': return "-..-";
        case 'y': return "-.--";
        case 'z': return "--..";
        case '1': return ".----";
        case '2': return "..---";
        case '3': return "...--";
        case '4': return "....-";
        case '5': return ".....";
        case '6': return "-....";
        case '7': return "--...";
        case '8': return "---..";
        case '9': return "----.";
        case '0': return "-----";
        default:
            std::cerr << "Unsupported character: " << letter << std::endl;
            std::exit(0);
    }
}

/// Maps a Morse pattern back to the letter or digit it represents.
char pattern_to_letter(const std::string &pattern) {
    if (pattern == ".-") return 'a';
    if (pattern == "-...") return 'b';
    if (pattern == "-.-.") return 'c';
    if (pattern == "-..") return 'd';
    if (pattern == ".") return 'e';
    if (pattern == "..-.") return 'f';
    if (pattern == "--.") return 'g';
    if (pattern == "....") return 'h';
    if (pattern == "..") return 'i';
    if (pattern == ".---") return 'j';
    if (pattern == "-.-") return 'k';
    if (pattern == ".-..") return 'l';
    if (pattern == "--") return 'm';
    if (pattern == "-.") return 'n';
    if (pattern == "---") return 'o';
    if (pattern == ".--.") return 'p';
    if (pattern == "--.-") return 'q';
    if (pattern == ".-.") return 'r';
    if (pattern == "...") return 's';
    if (pattern == "-") return 't';
    if (pattern == "..-") return 'u';
    if (pattern == "...-") return 'v';
    if (pattern == ".--") return 'w';
    if (pattern == "-..-") return 'x';
    if (pattern == "-.--") return 'y';
    if (pattern == "--..") return 'z';
    if (pattern == ".----") return '1';
    if (pattern == "..---") return '2';
    if (pattern == "...--") return '3';
    if (pattern == "....-") return '4';
    if (pattern == ".....") return '5';
    if (pattern == "-....") return '6';
    if (pattern == "--...") return '7';
    if (pattern == "---..") return '8';
    if (pattern == "----.") return '9';
    if (pattern == "-----") return '0';
    std::cerr << "Unsupported Morse pattern: " << pattern << std::endl;
    std::exit(0);
}

/// Converts a plain string into space-separated Morse patterns.
std::string encode(const std::string &message) {
    std::string result;
    for (const char &letter : message) {
        result += letter_to_pattern(letter) + " ";
    }
    return result;
}

/// Converts space-separated Morse patterns back into plain text.
std::string decode(const std::string &morse) {
    std::vector<std::string> tokens;
    std::size_t start = 0;
    std::size_t gap;
    while ((gap = morse.find(' ', start)) != std::string::npos) {
        tokens.push_back(morse.substr(start, gap - start));
        start = gap + 1;
    }

    std::string result;
    for (const std::string &token : tokens) {
        result += pattern_to_letter(token);
    }
    return result;
}

}  // namespace morse_code
}  // namespace ciphers

static void run_self_checks() {
    std::string digits = "01234567890";
    std::string digitsEncoded = ciphers::morse_code::encode(digits);
    std::string digitsDecoded = ciphers::morse_code::decode(digitsEncoded);
    assert(digits == digitsDecoded);
    std::cout << "Original text : " << digits << std::endl;
    std::cout << "Encrypted text : " << digitsEncoded << std::endl;
    std::cout << "Decrypted text : " << digitsDecoded << std::endl;

    std::string alphabet = "abcdefghijklmnopqrstuvwxyz";
    std::string alphabetEncoded = ciphers::morse_code::encode(alphabet);
    std::string alphabetDecoded = ciphers::morse_code::decode(alphabetEncoded);
    assert(alphabet == alphabetDecoded);
    std::cout << "Original text : " << alphabet << std::endl;
    std::cout << "Encrypted text : " << alphabetEncoded << std::endl;
    std::cout << "Decrypted text : " << alphabetDecoded << std::endl;
}

int main() {
    run_self_checks();
    return 0;
}

/**
 * @file vigenere_cipher.cpp
 * @brief Implementation of [Vigenère cipher](https://en.wikipedia.org/wiki/Vigen%C3%A8re_cipher) algorithm.
 *
 * @details
 * The Vigenère cipher is a method of encrypting alphabetic text by using a series of interwoven vigenere 
 * ciphers, based on the letters of a keyword. It employs a form of polyalphabetic substitution. 
 *
 * ### Algorithm
 * The encryption can also be represented using modular arithmetic by first transforming 
 * the letters into numbers, according to the scheme, A → 0, B → 1, ..., Z → 25.
 * Encryption of \f$i^{th}\f$ character in Message M by key K can be described mathematically as,
 * 
 * \f[ E_{K}(M_{i}) = (M_{i} + K_{i})\;\mbox{mod}\; 26\f]
 * 
 * while decryption of \f$i^{th}\f$ character in Cipher C by key K can be described mathematically as,
 *
 * \f[ D_{k}(C_{i}) = (C_{i} - K_{i} + 26)\;\mbox{mod}\; 26\f]
 * 
 * Where \f$K_{i}\f$ denotes corresponding character in key. If \f$|key| < |text|\f$ than
 * same key is repeated untill their lengths are equal.
 * 
 * For Example,
 * If M = "ATTACKATDAWN" and K = "LEMON" than K becomes "LEMONLEMONLE".
 * 
 * \note Rather than creating new key of equal length this program does this by using modular index for key
 * (i.e. \f$(j + 1) \;\mbox{mod}\; |\mbox{key}|\f$)
 * 
 * \note This program implements Vigenère cipher for only uppercase English alphabet characters (i.e. A-Z). 
 * 
 * @author [Deep Raval](https://github.com/imdeep2905)
 */
#include <iostream>
#include <string>
#include <cassert>

/** \namespace ciphers
 * \brief Algorithms for encryption and decryption
 */
namespace ciphers {
    /** \namespace vigenere
     * \brief Functions for [vigenère cipher](https://en.wikipedia.org/wiki/Vigen%C3%A8re_cipher) algorithm.
     */
    namespace vigenere {   
        namespace {
            /**
             * This function finds character for given value (i.e.A-Z)
             * @param x value for which we want character 
             * @return  corresponding character for perticular value
             */        
            inline char get_char(const int x) {
                // By adding 65 we are scaling 0-25 to 65-90. 
                // Which are in fact ASCII values of A-Z. 
                return char(x + 65); 
            }
            /**
             * This function finds value for given character (i.e.0-25)
             * @param c character for which we want value
             * @return returns corresponding value for perticular character
             */  
            inline int get_value(const char c) {
                // A-Z have ASCII values in range 65-90.
                // Hence subtracting 65 will scale them to 0-25.
                return int(c - 65);
            }
        } // Unnamed namespace
        /**
         * Encrypt given text using vigenere cipher.
         * @param text text to be encrypted
         * @param key to be used for encryption
         * @return new encrypted text
         */
        std::string encrypt (const std::string &text, const std::string &key) {
            std::string encrypted_text = ""; // Empty string to store encrypted text
            // Going through each character of text and key
            // Note that key is visited in circular way hence  j = (j + 1) % |key|
            for(size_t i = 0, j = 0; i < text.length(); i++, j = (j + 1) % key.length()) {
                int place_value_text = get_value(text[i]); // Getting value of character in text
                int place_value_key = get_value(key[j]); // Getting value of character in key
                place_value_text = (place_value_text + place_value_key) % 26; // Applying encryption
                char encrypted_char = get_char(place_value_text); // Getting new character from encrypted value
                encrypted_text += encrypted_char; // Appending encrypted character
            }
            return encrypted_text; // Returning encrypted text
        }
        /**
         * Decrypt given text using vigenere cipher.
         * @param text text to be decrypted
         * @param key key to be used for decryption
         * @return new decrypted text
         */        
        std::string decrypt (const std::string &text, const std::string &key) {
            // Going through each character of text and key
            // Note that key is visited in circular way hence  j = (j + 1) % |key|
            std::string decrypted_text = ""; // Empty string to store decrypted text
            for(size_t i = 0, j = 0; i < text.length(); i++, j = (j + 1) % key.length()) {
                int place_value_text = get_value(text[i]); // Getting value of character in text
                int place_value_key = get_value(key[j]); // Getting value of character in key
                place_value_text = (place_value_text - place_value_key + 26) % 26; // Applying decryption
                char decrypted_char = get_char(place_value_text); // Getting new character from decrypted value
                decrypted_text += decrypted_char; // Appending decrypted character
            }        
            return decrypted_text; // Returning decrypted text
        }
    } // namespace vigenere
} // namespace ciphers

/**
 * Function to test above algorithm
 */
void test() {
    // Test 1
    std::string text1 = "NIKOLATESLA";
    std::string encrypted1 = ciphers::vigenere::encrypt(text1, "TESLA");
    std::string decrypted1 = ciphers::vigenere::decrypt(encrypted1, "TESLA");
    assert(text1 == decrypted1);
    std::cout << "Original text : " << text1;
    std::cout << " , Encrypted text (with key = TESLA) : " << encrypted1;
    std::cout << " , Decrypted text : "<< decrypted1 << std::endl;
    // Test 2
    std::string text2 = "GOOGLEIT";
    std::string encrypted2 = ciphers::vigenere::encrypt(text2, "REALLY");
    std::string decrypted2 = ciphers::vigenere::decrypt(encrypted2, "REALLY");
    assert(text2 == decrypted2);
    std::cout << "Original text : " << text2;
    std::cout << " , Encrypted text (with key = REALLY) : " << encrypted2;
    std::cout << " , Decrypted text : "<< decrypted2 << std::endl;
}

/** Driver Code */
int main() {
    // Testing
    test();
    return 0;
}

/**
 * @brief Implementation of the Vigenère polyalphabetic substitution cipher.
 *
 * @details
 * Each letter of the plaintext is shifted by an amount determined by the
 * corresponding letter of a repeating keyword, using modular arithmetic
 * over the 26 letters of the alphabet. Only uppercase A-Z is supported.
 */
#include <cassert>
#include <iostream>
#include <string>

namespace ciphers {
namespace vigenere {

namespace {
/// Converts a 0-25 value back into an uppercase letter.
inline char value_to_letter(const int value) { return static_cast<char>(value + 65); }

/// Converts an uppercase letter into its 0-25 value.
inline int letter_to_value(const char letter) { return static_cast<int>(letter - 65); }
}  // namespace

/// Shifts each character of text forward by the matching keyword letter.
std::string encrypt(const std::string &text, const std::string &keyword) {
    std::string cipher;
    for (std::size_t i = 0, k = 0; i < text.length(); ++i, k = (k + 1) % keyword.length()) {
        int shifted = (letter_to_value(text[i]) + letter_to_value(keyword[k])) % 26;
        cipher += value_to_letter(shifted);
    }
    return cipher;
}

/// Shifts each character of the cipher text backward by the keyword letter.
std::string decrypt(const std::string &cipher, const std::string &keyword) {
    std::string plain;
    for (std::size_t i = 0, k = 0; i < cipher.length(); ++i, k = (k + 1) % keyword.length()) {
        int shifted = (letter_to_value(cipher[i]) - letter_to_value(keyword[k]) + 26) % 26;
        plain += value_to_letter(shifted);
    }
    return plain;
}

}  // namespace vigenere
}  // namespace ciphers

void run_self_checks() {
    std::string first = "NIKOLATESLA";
    std::string firstCipher = ciphers::vigenere::encrypt(first, "TESLA");
    std::string firstPlain = ciphers::vigenere::decrypt(firstCipher, "TESLA");
    assert(first == firstPlain);
    std::cout << "Original text : " << first;
    std::cout << " , Encrypted text (with key = TESLA) : " << firstCipher;
    std::cout << " , Decrypted text : " << firstPlain << std::endl;

    std::string second = "GOOGLEIT";
    std::string secondCipher = ciphers::vigenere::encrypt(second, "REALLY");
    std::string secondPlain = ciphers::vigenere::decrypt(secondCipher, "REALLY");
    assert(second == secondPlain);
    std::cout << "Original text : " << second;
    std::cout << " , Encrypted text (with key = REALLY) : " << secondCipher;
    std::cout << " , Decrypted text : " << secondPlain << std::endl;
}

int main() {
    run_self_checks();
    return 0;
}

/**
 * @file xor_cipher.cpp
 * @brief Implementation of [XOR cipher](https://en.wikipedia.org/wiki/XOR_cipher) algorithm.
 *
 * @details
 * In cryptography, the simple XOR cipher is a type of additive cipher, an encryption 
 * algorithm that operates according to the principles: 
 *
 * * \f$A {\oplus} 0 = A\f$
 * * \f$A {\oplus} A = 0\f$
 * * \f$ (A {\oplus} B) {\oplus} C = A {\oplus} (B {\oplus} C)\f$
 * * \f$ (B {\oplus} A) {\oplus} B = B {\oplus} 0 = B \f$
 * 
 * 
 * where \f$\oplus\f$ symbol denotes the exclusive disjunction (XOR) operation.
 * This operation is sometimes called modulus 2 addition (or subtraction, which is identical).
 * With this logic, a string of text can be encrypted by applying the bitwise XOR operator to
 * every character using a given key. To decrypt the output, merely reapplying the XOR function 
 * with the key will remove the cipher.
 * 
 * ### Algorithm
 * Choose the key for encryption and apply XOR operation to each character of a string. 
 * Reapplying XOR operation to each character of encrypted string will give original string back.
 * 
 * \note This program implements XOR Cipher for string with ASCII characters. 
 * 
 * @author [Deep Raval](https://github.com/imdeep2905)
 */
#include <iostream>
#include <string>
#include <cassert>

/** \namespace ciphers
 * \brief Algorithms for encryption and decryption
 */
namespace ciphers {
    /** \namespace XOR
     * \brief Functions for [XOR cipher](https://en.wikipedia.org/wiki/XOR_cipher) algorithm.
     */
    namespace XOR {   
        /**
         * Encrypt given text using XOR cipher.
         * @param text text to be encrypted
         * @param key to be used for encyption
         * @return new encrypted text
         */
        std::string encrypt (const std::string &text, const int &key) {
            std::string encrypted_text = ""; // Empty string to store encrypted text
            for (auto &c: text) { // Going through each character
                char encrypted_char = char(c ^ key); // Applying encyption
                encrypted_text += encrypted_char; // Appending encrypted character
            }
            return encrypted_text; // Returning encrypted text
        }
        /**
         * Decrypt given text using XOR cipher.
         * @param text text to be encrypted
         * @param key to be used for decryption
         * @return new decrypted text
         */        
        std::string decrypt (const std::string &text, const int &key) {
            std::string decrypted_text = ""; // Empty string to store decrypted text
            for (auto &c : text) { // Going through each character
                char decrypted_char = char(c ^ key); // Applying decryption
                decrypted_text += decrypted_char; // Appending decrypted character
            }
            return decrypted_text; // Returning decrypted text
        }
    } // namespace XOR
} // namespace ciphers

/**
 * Function to test above algorithm
 */
void test() {
    // Test 1
    std::string text1 = "Whipalsh! : Do watch this movie...";
    std::string encrypted1 = ciphers::XOR::encrypt(text1, 17);
    std::string decrypted1 = ciphers::XOR::decrypt(encrypted1, 17);
    assert(text1 == decrypted1);
