/**
 * @brief Implementation of the symmetric XOR cipher.
 *
 * @details
 * Applying the bitwise XOR operator between each character of a message and
 * a fixed key value produces the cipher text; reapplying the same XOR with
 * the same key restores the original message, since A xor K xor K == A.
 */
#include <cassert>
#include <iostream>
#include <string>

namespace ciphers {
namespace xor_cipher {

/// XORs every character of text with key; used for both directions.
std::string apply_key(const std::string &text, const int &key) {
    std::string result;
    for (const auto &character : text) {
        result += static_cast<char>(character ^ key);
    }
    return result;
}

std::string encrypt(const std::string &text, const int &key) { return apply_key(text, key); }

std::string decrypt(const std::string &text, const int &key) { return apply_key(text, key); }

}  // namespace xor_cipher
}  // namespace ciphers

void run_self_checks() {
    std::string first = "Whipalsh! : Do watch this movie...";
    std::string firstCipher = ciphers::xor_cipher::encrypt(first, 17);
    std::string firstPlain = ciphers::xor_cipher::decrypt(firstCipher, 17);
    assert(first == firstPlain);
    std::cout << "Original text : " << first;
    std::cout << " , Encrypted text (with key = 17) : " << firstCipher;
    std::cout << " , Decrypted text : " << firstPlain << std::endl;

    std::string second = "->Valar M0rghulis<-";
    std::string secondCipher = ciphers::xor_cipher::encrypt(second, 29);
    std::string secondPlain = ciphers::xor_cipher::decrypt(secondCipher, 29);
    assert(second == secondPlain);
    std::cout << "Original text : " << second;
    std::cout << " , Encrypted text (with key = 29) : " << secondCipher;
    std::cout << " , Decrypted text : " << secondPlain << std::endl;
}

int main() {
    run_self_checks();
    return 0;
}

/**
 * @file
 * @brief Implementation of FCFS CPU scheduling algorithm
 * @details
 * FCFS is a non-preemptive CPU scheduling algorithm in which whichever process
 * arrives first, gets executed first. If two or more processes arrive
 * simultaneously, the process with smaller process ID gets executed first.
 * @link https://bit.ly/3ABNXOC
 * @author [Pratyush Vatsa](https://github.com/Pratyush219)
 */

#include <algorithm>      /// for sorting
#include <cassert>        /// for assert
#include <cstdint>
#include <cstdlib>        /// random number generation
#include <ctime>          /// for time
#include <iomanip>        /// for formatting the output
#include <iostream>       /// for IO operations
#include <queue>          /// for std::priority_queue
#include <unordered_set>  /// for std::unordered_set
#include <vector>         /// for std::vector

using std::cin;
using std::cout;
using std::endl;
using std::get;
using std::left;
using std::make_tuple;
using std::priority_queue;
using std::rand;
using std::srand;
using std::tuple;
using std::unordered_set;
using std::vector;
/**
 * @brief Comparator function for sorting a vector
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 * @param t1 First tuple
 * @param t2 Second tuple
 * @returns true if t1 and t2 are in the CORRECT order
 * @returns false if t1 and t2 are in the INCORRECT order
 */
template <typename S, typename T, typename E>
bool sortcol(tuple<S, T, E>& t1, tuple<S, T, E>& t2) {
    if (get<1>(t1) < get<1>(t2)) {
        return true;
    } else if (get<1>(t1) == get<1>(t2) && get<0>(t1) < get<0>(t2)) {
        return true;
    }
    return false;
}

/**
 * @class Compare
 * @brief Comparator class for priority queue
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 */
template <typename S, typename T, typename E>
class Compare {
 public:
    /**
     * @param t1 First tuple
     * @param t2 Second tuple
     * @brief A comparator function that checks whether to swap the two tuples
     * or not.
     * @link Refer to
     * https://www.geeksforgeeks.org/comparator-class-in-c-with-examples/ for
     * detailed description of comparator
     * @returns true if the tuples SHOULD be swapped
     * @returns false if the tuples SHOULDN'T be swapped
     */
    bool operator()(tuple<S, T, E, double, double, double>& t1,
                    tuple<S, T, E, double, double, double>& t2) {
        // Compare arrival times
        if (get<1>(t2) < get<1>(t1)) {
            return true;
        }
        // If arrival times are same, then compare Process IDs
        else if (get<1>(t2) == get<1>(t1)) {
            return get<0>(t2) < get<0>(t1);
        }
        return false;
    }
};

/**
 * @class FCFS
 * @brief Class which implements the FCFS scheduling algorithm
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 */
template <typename S, typename T, typename E>
class FCFS {
    /**
     * Priority queue of schedules(stored as tuples) of processes.
     * In each tuple
     * 1st element: Process ID
     * 2nd element: Arrival Time
     * 3rd element: Burst time
     * 4th element: Completion time
     * 5th element: Turnaround time
     * 6th element: Waiting time
     */
    priority_queue<tuple<S, T, E, double, double, double>,
                   vector<tuple<S, T, E, double, double, double>>,
                   Compare<S, T, E>>
        schedule;

    // Stores final status of all the processes after completing the execution.
    vector<tuple<S, T, E, double, double, double>> result;

    // Stores process IDs. Used for confirming absence of a process while adding
    // it.
    unordered_set<S> idList;

 public:
    /**
     * @brief Adds the process to the ready queue if it isn't already there
     * @param id Process ID
     * @param arrival Arrival time of the process
     * @param burst Burst time of the process
     * @returns void
     *
     */
    void addProcess(S id, T arrival, E burst) {
        // Add if a process with process ID as id is not found in idList.
        if (idList.find(id) == idList.end()) {
            tuple<S, T, E, double, double, double> t =
                make_tuple(id, arrival, burst, 0, 0, 0);
            schedule.push(t);
            idList.insert(id);
        }
    }

    /**
     * @brief Algorithm for scheduling CPU processes according to the First Come
     * First Serve(FCFS) scheduling algorithm.
     *
     * @details FCFS is a non-preemptive algorithm in which the process which
     * arrives first gets executed first. If two or more processes arrive
     * together then the process with smaller process ID runs first (each
     * process has a unique proces ID).
     *
     * I used a min priority queue of tuples to accomplish this task. The
     * processes are ordered by their arrival times. If arrival times of some
     * processes are equal, then they are ordered by their process ID.
     *
     * @returns void
     */
    vector<tuple<S, T, E, double, double, double>> scheduleForFcfs() {
        // Variable to keep track of time elapsed so far
        double timeElapsed = 0;

        while (!schedule.empty()) {
            tuple<S, T, E, double, double, double> cur = schedule.top();

            // If the current process arrived at time t2, the last process
            // completed its execution at time t1, and t2 > t1.
            if (get<1>(cur) > timeElapsed) {
                timeElapsed += get<1>(cur) - timeElapsed;
            }

            // Add Burst time to time elapsed
            timeElapsed += get<2>(cur);

            // Completion time of the current process will be same as time
            // elapsed so far
            get<3>(cur) = timeElapsed;

            // Turnaround time = Completion time - Arrival time
            get<4>(cur) = get<3>(cur) - get<1>(cur);

            // Waiting time = Turnaround time - Burst time
            get<5>(cur) = get<4>(cur) - get<2>(cur);

            result.push_back(cur);
            schedule.pop();
        }
        return result;
    }

    /**
     * @brief Utility function for printing the status of each process after
     * execution
     * @returns void
     */
    void printResult() {
        cout << "Status of all the proceses post completion is as follows:"
             << endl;

        cout << std::setw(17) << left << "Process ID" << std::setw(17) << left
             << "Arrival Time" << std::setw(17) << left << "Burst Time"
             << std::setw(17) << left << "Completion Time" << std::setw(17)
             << left << "Turnaround Time" << std::setw(17) << left
             << "Waiting Time" << endl;

        for (size_t i{}; i < result.size(); i++) {
            cout << std::setprecision(2) << std::fixed << std::setw(17) << left
                 << get<0>(result[i]) << std::setw(17) << left
                 << get<1>(result[i]) << std::setw(17) << left
                 << get<2>(result[i]) << std::setw(17) << left
                 << get<3>(result[i]) << std::setw(17) << left
                 << get<4>(result[i]) << std::setw(17) << left
                 << get<5>(result[i]) << endl;
        }
    }
};

/**
 * @brief Function to be used for testing purposes. This function guarantees the
 * correct solution for FCFS scheduling algorithm.
 * @param input the input data
 * @details Sorts the input vector according to arrival time. Processes whose
 * arrival times are same get sorted according to process ID For each process,
 * completion time, turnaround time and completion time are calculated, inserted
 * in a tuple, which is added to the vector result.
 * @returns A vector of tuples consisting of process ID, arrival time, burst
 * time, completion time, turnaround time and waiting time for each process.
 */
template <typename S, typename T, typename E>
vector<tuple<S, T, E, double, double, double>> get_final_status(
    vector<tuple<uint32_t, uint32_t, uint32_t>> input) {
    sort(input.begin(), input.end(), sortcol<S, T, E>);
    vector<tuple<S, T, E, double, double, double>> result(input.size());
    double timeElapsed = 0;
    for (size_t i{}; i < input.size(); i++) {
        T arrival = get<1>(input[i]);
        E burst = get<2>(input[i]);

        if (arrival > timeElapsed) {
            timeElapsed += arrival - timeElapsed;
        }
        timeElapsed += burst;
        double completion = timeElapsed;
        double turnaround = completion - arrival;
        double waiting = turnaround - burst;

        get<0>(result[i]) = get<0>(input[i]);
        get<1>(result[i]) = arrival;
        get<2>(result[i]) = burst;
        get<3>(result[i]) = completion;
        get<4>(result[i]) = turnaround;
        get<5>(result[i]) = waiting;
    }
    return result;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    for (int i{}; i < 1000; i++) {
        srand(time(nullptr));
        uint32_t n = 1 + rand() % 1000;
        FCFS<uint32_t, uint32_t, uint32_t> readyQueue;
        vector<tuple<uint32_t, uint32_t, uint32_t>> input(n);

        for (uint32_t i{}; i < n; i++) {
            get<0>(input[i]) = i;
            srand(time(nullptr));
            get<1>(input[i]) = 1 + rand() % 10000;
            srand(time(nullptr));
            get<2>(input[i]) = 1 + rand() % 10000;
        }

        for (uint32_t i{}; i < n; i++) {
            readyQueue.addProcess(get<0>(input[i]), get<1>(input[i]),
                                  get<2>(input[i]));
        }
        vector<tuple<uint32_t, uint32_t, uint32_t, double, double, double>>
            res = get_final_status<uint32_t, uint32_t, uint32_t>(input);
        assert(res == readyQueue.scheduleForFcfs());
        // readyQueue.printResult();
    }
    cout << "All the tests have successfully passed!" << endl;
}

/**
 * @brief Entry point of the program
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Alternate implementation of the First-Come-First-Served CPU
 * scheduler.
 * @details
 * Under FCFS, whichever process shows up earliest is dispatched first; ties on
 * arrival time are broken using the smaller process identifier. This variant
 * keeps the same public contract as the reference implementation but reshapes
 * the internal bookkeeping (struct-based records instead of raw tuples where
 * convenient, a hand-rolled ordering helper, and a differently organized
 * verification routine).
 */

#include <algorithm>      /// std::sort
#include <cassert>        /// assert()
#include <cstdint>        /// fixed width integers
#include <cstdlib>        /// rand()/srand()
#include <ctime>          /// time() for seeding
#include <iomanip>        /// column formatting helpers
#include <iostream>       /// stream IO
#include <queue>          /// std::priority_queue
#include <unordered_set>  /// dedup guard for process ids
#include <vector>         /// dynamic arrays

namespace {

using JobRecord = std::tuple<std::uint32_t, std::uint32_t, std::uint32_t,
                              double, double, double>;

/**
 * @brief Ordering predicate used to sort the raw (id, arrival, burst) tuples.
 *
 * Earlier arrival wins; a tie is resolved by the lower process id.
 */
template <typename S, typename T, typename E>
bool arrivalThenIdLess(const std::tuple<S, T, E>& lhs,
                        const std::tuple<S, T, E>& rhs) {
    const auto& lArrival = std::get<1>(lhs);
    const auto& rArrival = std::get<1>(rhs);
    if (lArrival != rArrival) {
        return lArrival < rArrival;
    }
    return std::get<0>(lhs) < std::get<0>(rhs);
}

/**
 * @brief Min-heap ordering functor for the ready queue.
 *
 * A process record should surface before another one when it arrived
 * earlier, or arrived at the same instant but owns a smaller id.
 */
template <typename S, typename T, typename E>
struct ReadyQueueOrder {
    bool operator()(const std::tuple<S, T, E, double, double, double>& a,
                     const std::tuple<S, T, E, double, double, double>& b) const {
        const auto& arrivalA = std::get<1>(a);
        const auto& arrivalB = std::get<1>(b);
        if (arrivalB < arrivalA) return true;
        if (arrivalB == arrivalA) return std::get<0>(b) < std::get<0>(a);
        return false;
    }
};

/**
 * @brief Simulates First-Come-First-Served CPU dispatching.
 *
 * Processes are registered via enqueueJob() and then drained in arrival
 * order (ties broken by id) to compute completion, turnaround, and waiting
 * times.
 */
template <typename S, typename T, typename E>
class FirstComeFirstServed {
 public:
    /// Registers a job if its id has not already been seen.
    void enqueueJob(S id, T arrival, E burst) {
        if (seenIds_.count(id) != 0) {
            return;
        }
        seenIds_.insert(id);
        pending_.push(std::make_tuple(id, arrival, burst, 0.0, 0.0, 0.0));
    }

    /**
     * @brief Runs the simulation and returns the per-process statistics.
     *
     * The clock advances to a job's arrival time whenever the CPU would
     * otherwise sit idle, then jumps forward by the job's burst time.
     */
    std::vector<std::tuple<S, T, E, double, double, double>> run() {
        double clock = 0.0;
        std::vector<std::tuple<S, T, E, double, double, double>> finished;
        finished.reserve(pending_.size());

        while (!pending_.empty()) {
            auto job = pending_.top();
            pending_.pop();

            const double arrival = static_cast<double>(std::get<1>(job));
            if (arrival > clock) {
                clock = arrival;
            }
            clock += static_cast<double>(std::get<2>(job));

            std::get<3>(job) = clock;                          // completion
            std::get<4>(job) = std::get<3>(job) - arrival;      // turnaround
            std::get<5>(job) = std::get<4>(job) - std::get<2>(job);  // waiting

            finished.push_back(job);
        }
        history_ = finished;
        return finished;
    }

    /// Dumps a formatted table describing the last computed schedule.
    void report() const {
        std::cout << "Final process statistics:\n";
        printHeader();
        for (const auto& row : history_) {
            printRow(row);
        }
    }

 private:
    static void printHeader() {
        const char* labels[] = {"Process ID",     "Arrival Time",
                                 "Burst Time",     "Completion Time",
                                 "Turnaround Time", "Waiting Time"};
        for (const char* label : labels) {
            std::cout << std::setw(17) << std::left << label;
        }
        std::cout << '\n';
    }

    static void printRow(
        const std::tuple<S, T, E, double, double, double>& row) {
        std::cout << std::setprecision(2) << std::fixed;
        std::cout << std::setw(17) << std::left << std::get<0>(row)
                   << std::setw(17) << std::left << std::get<1>(row)
                   << std::setw(17) << std::left << std::get<2>(row)
                   << std::setw(17) << std::left << std::get<3>(row)
                   << std::setw(17) << std::left << std::get<4>(row)
                   << std::setw(17) << std::left << std::get<5>(row) << '\n';
    }

    std::priority_queue<std::tuple<S, T, E, double, double, double>,
                         std::vector<std::tuple<S, T, E, double, double, double>>,
                         ReadyQueueOrder<S, T, E>>
        pending_;
    std::vector<std::tuple<S, T, E, double, double, double>> history_;
    std::unordered_set<S> seenIds_;
};

/**
 * @brief Reference computation used purely to cross-check the simulator.
 *
 * Sorts the raw jobs by arrival/id and walks them in order, accumulating the
 * same completion/turnaround/waiting figures a correct FCFS run should
 * produce.
 */
template <typename S, typename T, typename E>
std::vector<std::tuple<S, T, E, double, double, double>> bruteForceExpected(
    std::vector<std::tuple<std::uint32_t, std::uint32_t, std::uint32_t>> jobs) {
    std::sort(jobs.begin(), jobs.end(), arrivalThenIdLess<S, T, E>);

    std::vector<std::tuple<S, T, E, double, double, double>> expected(
        jobs.size());
    double clock = 0.0;

    for (std::size_t idx = 0; idx < jobs.size(); ++idx) {
        const auto arrival = std::get<1>(jobs[idx]);
        const auto burst = std::get<2>(jobs[idx]);

        if (arrival > clock) {
            clock += arrival - clock;
        }
        clock += burst;

        const double completion = clock;
        const double turnaround = completion - arrival;
        const double waiting = turnaround - burst;

        expected[idx] = std::make_tuple(std::get<0>(jobs[idx]), arrival, burst,
                                          completion, turnaround, waiting);
    }
    return expected;
}

/// Generates a batch of randomized workloads and cross-validates the two
/// implementations against one another.
void runRandomizedChecks() {
    for (int trial = 0; trial < 1000; ++trial) {
        std::srand(static_cast<unsigned>(std::time(nullptr)));
        const std::uint32_t jobCount = 1 + std::rand() % 1000;

        FirstComeFirstServed<std::uint32_t, std::uint32_t, std::uint32_t> sim;
        std::vector<std::tuple<std::uint32_t, std::uint32_t, std::uint32_t>>
            jobs(jobCount);

        for (std::uint32_t i = 0; i < jobCount; ++i) {
            std::get<0>(jobs[i]) = i;
            std::srand(static_cast<unsigned>(std::time(nullptr)));
            std::get<1>(jobs[i]) = 1 + std::rand() % 10000;
            std::srand(static_cast<unsigned>(std::time(nullptr)));
            std::get<2>(jobs[i]) = 1 + std::rand() % 10000;
        }

        for (std::uint32_t i = 0; i < jobCount; ++i) {
            sim.enqueueJob(std::get<0>(jobs[i]), std::get<1>(jobs[i]),
                           std::get<2>(jobs[i]));
        }

        auto expected =
            bruteForceExpected<std::uint32_t, std::uint32_t, std::uint32_t>(
                jobs);
        assert(expected == sim.run());
    }
    std::cout << "FCFS randomized cross-check: all trials matched.\n";
}

}  // namespace

/// Entry point: exercises the randomized verification suite.
int main() {
    runRandomizedChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of SJF CPU scheduling algorithm
 * @details
 * shortest job first (SJF), also known as shortest job next (SJN), is a
 * scheduling policy that selects for execution the waiting process with the
 * smallest execution time. SJN is a non-preemptive algorithm. Shortest
 * remaining time is a preemptive variant of SJN.
 * <a href="https://www.guru99.com/shortest-job-first-sjf-scheduling.html">
 * detailed description on SJF scheduling </a>
 * <a href="https://github.com/LakshmiSrikumar">Author : Lakshmi Srikumar </a>
 */

#include <algorithm>      /// for sorting
#include <cassert>        /// for assert
#include <iomanip>        /// for formatting the output
#include <iostream>       /// for IO operations
#include <queue>          /// for std::priority_queue
#include <random>         /// random number generation
#include <unordered_set>  /// for std::unordered_set
#include <vector>         /// for std::vector

using std::cin;
using std::cout;
using std::endl;
using std::get;
using std::left;
using std::make_tuple;
using std::priority_queue;
using std::tuple;
using std::unordered_set;
using std::vector;

/**
 * @brief Comparator function for sorting a vector
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 * @param t1 First tuple<S,T,E>t1
 * @param t2 Second tuple<S,T,E>t2
 * @returns true if t1 and t2 are in the CORRECT order
 * @returns false if t1 and t2 are in the INCORRECT order
 */
template <typename S, typename T, typename E>
bool sortcol(tuple<S, T, E>& t1, tuple<S, T, E>& t2) {
    if (get<1>(t1) < get<1>(t2) ||
        (get<1>(t1) == get<1>(t2) && get<0>(t1) < get<0>(t2))) {
        return true;
    }
    return false;
}

/**
 * @class Compare
 * @brief Comparator class for priority queue
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 */
template <typename S, typename T, typename E>
class Compare {
 public:
    /**
     * @param t1 First tuple
     * @param t2 Second tuple
     * @brief A comparator function that checks whether to swap the two tuples
     * or not.
     * <a
     * href="https://www.geeksforgeeks.org/comparator-class-in-c-with-examples/">
     * detailed description of comparator </a>
     * @returns true if the tuples SHOULD be swapped
     * @returns false if the tuples SHOULDN'T be swapped
     */
    bool operator()(tuple<S, T, E, double, double, double>& t1,
                    tuple<S, T, E, double, double, double>& t2) {
        // Compare burst times for SJF
        if (get<2>(t2) < get<2>(t1)) {
            return true;
        }
        // If burst times are the same, compare arrival times
        else if (get<2>(t2) == get<2>(t1)) {
            return get<1>(t2) < get<1>(t1);
        }
        return false;
    }
};

/**
 * @class SJF
 * @brief Class which implements the SJF scheduling algorithm
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 */
template <typename S, typename T, typename E>
class SJF {
    /**
     * Priority queue of schedules(stored as tuples) of processes.
     * In each tuple
     * @tparam 1st element: Process ID
     * @tparam 2nd element: Arrival Time
     * @tparam 3rd element: Burst time
     * @tparam 4th element: Completion time
     * @tparam 5th element: Turnaround time
     * @tparam 6th element: Waiting time
     */
    priority_queue<tuple<S, T, E, double, double, double>,
                   vector<tuple<S, T, E, double, double, double>>,
                   Compare<S, T, E>>
        schedule;

    // Stores final status of all the processes after completing the execution.
    vector<tuple<S, T, E, double, double, double>> result;

    // Stores process IDs. Used for confirming absence of a process while  it.
    unordered_set<S> idList;

 public:
    /**
     * @brief Adds the process to the ready queue if it isn't already there
     * @param id Process ID
     * @param arrival Arrival time of the process
     * @param burst Burst time of the process
     * @returns void
     *
     */
    void addProcess(S id, T arrival, E burst) {
        // Add if a process with process ID as id is not found in idList.
        if (idList.find(id) == idList.end()) {
            tuple<S, T, E, double, double, double> t =
                make_tuple(id, arrival, burst, 0, 0, 0);
            schedule.push(t);
            idList.insert(id);
        }
    }

    /**
     * @brief Algorithm for scheduling CPU processes according to
     * the Shortest Job First (SJF) scheduling algorithm.
     *
     * @details Non pre-emptive SJF is an algorithm that schedules processes
     * based on the length of their burst times. The process with the smallest
     * burst time is executed first.In a non-preemptive scheduling algorithm,
     * once a process starts executing,it runs to completion without being
     * interrupted.
     *
     * I used a min priority queue because it allows you to efficiently pick the
     * process with the smallest burst time in constant time, by maintaining a
     * priority order where the shortest burst process is always at the front.
     *
     * @returns void
     */

    vector<tuple<S, T, E, double, double, double>> scheduleForSJF() {
        // Variable to keep track of time elapsed so far
        double timeElapsed = 0;

        while (!schedule.empty()) {
            tuple<S, T, E, double, double, double> cur = schedule.top();

            // If the current process arrived at time t2, the last process
            // completed its execution at time t1, and t2 > t1.
            if (get<1>(cur) > timeElapsed) {
                timeElapsed += get<1>(cur) - timeElapsed;
            }

            // Add Burst time to time elapsed
            timeElapsed += get<2>(cur);

            // Completion time of the current process will be same as time
            // elapsed so far
            get<3>(cur) = timeElapsed;

            // Turnaround time = Completion time - Arrival time
            get<4>(cur) = get<3>(cur) - get<1>(cur);

            // Waiting time = Turnaround time - Burst time
            get<5>(cur) = get<4>(cur) - get<2>(cur);

            // Turnaround time >= Burst time
            assert(get<4>(cur) >= get<2>(cur));

            // Waiting time is never negative
            assert(get<5>(cur) >= 0);

            result.push_back(cur);
            schedule.pop();
        }
        return result;
    }
    /**
     * @brief Utility function for printing the status of
     *  each process after execution
     * @returns void
     */

    void printResult(
        const vector<tuple<S, T, E, double, double, double>>& processes) {
        cout << std::setw(17) << left << "Process ID" << std::setw(17) << left
             << "Arrival Time" << std::setw(17) << left << "Burst Time"
             << std::setw(17) << left << "Completion Time" << std::setw(17)
             << left << "Turnaround Time" << std::setw(17) << left
             << "Waiting Time" << endl;

        for (const auto& process : processes) {
            cout << std::setprecision(2) << std::fixed << std::setw(17) << left
                 << get<0>(process) << std::setw(17) << left << get<1>(process)
                 << std::setw(17) << left << get<2>(process) << std::setw(17)
                 << left << get<3>(process) << std::setw(17) << left
                 << get<4>(process) << std::setw(17) << left << get<5>(process)
                 << endl;
        }
    }
};

/**
 * @brief Computes the final status of processes after
 * applying non-preemptive SJF scheduling
 * @tparam S Data type of Process ID
 * @tparam T Data type of Arrival time
 * @tparam E Data type of Burst time
 * @param input A vector of tuples containing Process ID, Arrival time, and
 * Burst time
 * @returns A vector of tuples containing Process ID, Arrival time, Burst time,
 *         Completion time, Turnaround time, and Waiting time
 */
template <typename S, typename T, typename E>
vector<tuple<S, T, E, double, double, double>> get_final_status(
    vector<tuple<S, T, E>> input) {
    // Sort the processes based on Arrival time and then Burst time
    sort(input.begin(), input.end(), sortcol<S, T, E>);

    // Result vector to hold the final status of each process
    vector<tuple<S, T, E, double, double, double>> result(input.size());
    double timeElapsed = 0;

    for (size_t i = 0; i < input.size(); i++) {
        // Extract Arrival time and Burst time
        T arrival = get<1>(input[i]);
        E burst = get<2>(input[i]);

        // If the CPU is idle, move time to the arrival of the next process
        if (arrival > timeElapsed) {
            timeElapsed = arrival;
        }

        // Update timeElapsed by adding the burst time
        timeElapsed += burst;

        // Calculate Completion time, Turnaround time, and Waiting time
        double completion = timeElapsed;
        double turnaround = completion - arrival;
        double waiting = turnaround - burst;

        // Store the results in the result vector
        result[i] = make_tuple(get<0>(input[i]), arrival, burst, completion,
                               turnaround, waiting);
    }

    return result;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // A vector to store the results of all processes across all test cases.
    vector<tuple<uint32_t, uint32_t, uint32_t, double, double, double>>
        finalResult;

    for (int i{}; i < 10; i++) {
        std::random_device rd;  // Seeding
        std::mt19937 eng(rd());
        std::uniform_int_distribution<> distr(1, 10);

        uint32_t n = distr(eng);
        SJF<uint32_t, uint32_t, uint32_t> readyQueue;
        vector<tuple<uint32_t, uint32_t, uint32_t, double, double, double>>
            input(n);

        // Generate random arrival and burst times
        for (uint32_t i{}; i < n; i++) {
            get<0>(input[i]) = i;
            get<1>(input[i]) = distr(eng);  // Random arrival time
            get<2>(input[i]) = distr(eng);  // Random burst time
        }

        // Print processes before scheduling
        cout << "Processes before SJF scheduling:" << endl;
        readyQueue.printResult(input);

        // Add processes to the queue
        for (uint32_t i{}; i < n; i++) {
            readyQueue.addProcess(get<0>(input[i]), get<1>(input[i]),
                                  get<2>(input[i]));
        }

        // Perform SJF schedulings
        auto finalResult = readyQueue.scheduleForSJF();

        // Print processes after scheduling
        cout << "\nProcesses after SJF scheduling:" << endl;
        readyQueue.printResult(finalResult);
    }
    cout << "All the tests have successfully passed!" << endl;
}

/**
 * @brief Main function
 * @returns 0 on successful exit
 */
int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief Alternative implementation of non-preemptive Shortest-Job-First CPU
 * scheduling.
 * @details
 * Non-preemptive SJF always dispatches the ready process with the smallest
 * burst time next; once started, a process runs to completion. This rewrite
 * keeps the same externally observable behaviour as the reference version
 * while renaming the moving pieces and reorganizing the demo/self-check
 * section.
 */

#include <algorithm>      /// std::sort
#include <cassert>        /// assert()
#include <iomanip>        /// output formatting
#include <iostream>       /// stream IO
#include <queue>          /// std::priority_queue
#include <random>         /// random workload generation
#include <unordered_set>  /// duplicate-id guard
#include <vector>         /// dynamic arrays

namespace scheduling {
namespace shortest_job_first {

/**
 * @brief Tells whether job @p a should be considered "less than" job @p b
 * when ordering raw (id, arrival, burst) triples by arrival then id.
 */
template <typename IdT, typename TimeT, typename DurT>
bool byArrivalThenId(const std::tuple<IdT, TimeT, DurT>& a,
                      const std::tuple<IdT, TimeT, DurT>& b) {
    const bool sameArrival = std::get<1>(a) == std::get<1>(b);
    if (!sameArrival) {
        return std::get<1>(a) < std::get<1>(b);
    }
    return std::get<0>(a) < std::get<0>(b);
}

/**
 * @brief Min-heap comparator: shortest burst time floats to the top, ties
 * broken by earlier arrival.
 */
template <typename IdT, typename TimeT, typename DurT>
struct ShorterBurstFirst {
    bool operator()(
        const std::tuple<IdT, TimeT, DurT, double, double, double>& a,
        const std::tuple<IdT, TimeT, DurT, double, double, double>& b) const {
        if (std::get<2>(b) < std::get<2>(a)) return true;
        if (std::get<2>(b) == std::get<2>(a)) return std::get<1>(b) < std::get<1>(a);
        return false;
    }
};

/**
 * @brief Drives a non-preemptive SJF simulation over a set of registered
 * jobs.
 */
template <typename IdT, typename TimeT, typename DurT>
class ShortestJobFirstScheduler {
 public:
    /// Registers a new job unless its id was already submitted.
    void submit(IdT id, TimeT arrival, DurT burst) {
        if (registered_.find(id) != registered_.end()) {
            return;
        }
        registered_.insert(id);
        ready_.push(std::make_tuple(id, arrival, burst, 0.0, 0.0, 0.0));
    }

    /**
     * @brief Executes every submitted job in shortest-burst order and
     * returns the per-job timing statistics.
     */
    std::vector<std::tuple<IdT, TimeT, DurT, double, double, double>> run() {
        double clock = 0.0;
        std::vector<std::tuple<IdT, TimeT, DurT, double, double, double>> done;

        while (!ready_.empty()) {
            auto job = ready_.top();
            ready_.pop();

            const auto arrival = std::get<1>(job);
            if (arrival > clock) {
                clock += arrival - clock;
            }
            clock += std::get<2>(job);

            std::get<3>(job) = clock;
            std::get<4>(job) = std::get<3>(job) - arrival;
            std::get<5>(job) = std::get<4>(job) - std::get<2>(job);

            assert(std::get<4>(job) >= std::get<2>(job));
            assert(std::get<5>(job) >= 0);

            done.push_back(job);
        }
        return done;
    }

    /// Pretty-prints a table of job statistics passed in explicitly.
    static void dump(
        const std::vector<std::tuple<IdT, TimeT, DurT, double, double, double>>&
            rows) {
        static const char* kHeaders[] = {"Process ID",      "Arrival Time",
                                          "Burst Time",      "Completion Time",
                                          "Turnaround Time", "Waiting Time"};
        for (const char* h : kHeaders) {
            std::cout << std::setw(17) << std::left << h;
        }
        std::cout << std::endl;

        for (const auto& row : rows) {
            std::cout << std::setprecision(2) << std::fixed;
            std::cout << std::setw(17) << std::left << std::get<0>(row)
                       << std::setw(17) << std::left << std::get<1>(row)
                       << std::setw(17) << std::left << std::get<2>(row)
                       << std::setw(17) << std::left << std::get<3>(row)
                       << std::setw(17) << std::left << std::get<4>(row)
                       << std::setw(17) << std::left << std::get<5>(row)
                       << std::endl;
        }
    }

 private:
    std::priority_queue<
        std::tuple<IdT, TimeT, DurT, double, double, double>,
        std::vector<std::tuple<IdT, TimeT, DurT, double, double, double>>,
        ShorterBurstFirst<IdT, TimeT, DurT>>
        ready_;
    std::unordered_set<IdT> registered_;
};

/**
 * @brief Independent reference calculation for cross-checking the scheduler.
 *
 * Note: unlike the class above, arrivals here are sorted first purely to
 * establish a deterministic processing order for tie-breaking; the actual
 * dispatch decision inside the loop still favors the smallest burst overall
 * ordering established by the sort.
 */
template <typename IdT, typename TimeT, typename DurT>
std::vector<std::tuple<IdT, TimeT, DurT, double, double, double>>
computeExpected(std::vector<std::tuple<IdT, TimeT, DurT>> jobs) {
    std::sort(jobs.begin(), jobs.end(), byArrivalThenId<IdT, TimeT, DurT>);

    std::vector<std::tuple<IdT, TimeT, DurT, double, double, double>> stats(
        jobs.size());
    double clock = 0.0;

    for (std::size_t i = 0; i < jobs.size(); ++i) {
        const auto arrival = std::get<1>(jobs[i]);
        const auto burst = std::get<2>(jobs[i]);

        if (arrival > clock) {
            clock = arrival;
        }
        clock += burst;

        const double completion = clock;
        const double turnaround = completion - arrival;
        const double waiting = turnaround - burst;

        stats[i] = std::make_tuple(std::get<0>(jobs[i]), arrival, burst,
                                    completion, turnaround, waiting);
    }
    return stats;
}

}  // namespace shortest_job_first
}  // namespace scheduling

namespace {

/// Runs a handful of randomized workloads through the scheduler, printing
/// before/after tables for a quick visual sanity check.
void demoRandomizedRuns() {
    using scheduling::shortest_job_first::ShortestJobFirstScheduler;

    for (int trial = 0; trial < 10; ++trial) {
        std::random_device rd;
        std::mt19937 rng(rd());
        std::uniform_int_distribution<> pick(1, 10);

        const std::uint32_t jobCount = pick(rng);
        ShortestJobFirstScheduler<std::uint32_t, std::uint32_t, std::uint32_t>
            scheduler;
        std::vector<
            std::tuple<std::uint32_t, std::uint32_t, std::uint32_t, double,
                       double, double>>
            seedRows(jobCount);

        for (std::uint32_t i = 0; i < jobCount; ++i) {
            std::get<0>(seedRows[i]) = i;
            std::get<1>(seedRows[i]) = pick(rng);
            std::get<2>(seedRows[i]) = pick(rng);
        }

        std::cout << "Before scheduling (trial " << trial << "):" << std::endl;
        ShortestJobFirstScheduler<std::uint32_t, std::uint32_t,
                                   std::uint32_t>::dump(seedRows);

        for (std::uint32_t i = 0; i < jobCount; ++i) {
            scheduler.submit(std::get<0>(seedRows[i]), std::get<1>(seedRows[i]),
                              std::get<2>(seedRows[i]));
        }

        auto finalRows = scheduler.run();

        std::cout << "\nAfter scheduling (trial " << trial << "):" << std::endl;
        ShortestJobFirstScheduler<std::uint32_t, std::uint32_t,
                                   std::uint32_t>::dump(finalRows);
    }
    std::cout << "Non-preemptive SJF demo runs completed." << std::endl;
}

}  // namespace

/// Program entry point.
int main() {
    demoRandomizedRuns();
    return 0;
}

/**
 * \file
 * \brief A simple tree implementation using nodes
 *
 * \todo update code to use C++ STL library features and OO structure
 * \warning This program is a poor implementation and does not utilize any of
 * the C++ STL features.
 */
#include <algorithm>  /// for std::max
#include <iostream>   /// for std::cout
#include <queue>      /// for std::queue

using node = struct node {
    int data;
    int height;
    struct node *left;
    struct node *right;
};

/**
 * @brief creates and returns a new node
 * @param[in] data value stored in the node
 * @return newly created node
 */
node *createNode(int data) {
    node *nn = new node();
    nn->data = data;
    nn->height = 0;
    nn->left = nullptr;
    nn->right = nullptr;
    return nn;
}

/**
 * @param[in] root the root of the tree
 * @return height of tree
 */
int height(node *root) {
    if (root == nullptr) {
        return 0;
    }
    return 1 + std::max(height(root->left), height(root->right));
}

/**
 * @param[in] root of the tree
 * @return difference between height of left and right subtree
 */
int getBalance(node *root) { return height(root->left) - height(root->right); }

/**
 * @param root of the tree to be rotated
 * @return node after right rotation
 */
node *rightRotate(node *root) {
    node *t = root->left;
    node *u = t->right;
    t->right = root;
    root->left = u;
    return t;
}

/**
 * @param root of the tree to be rotated
 * @return node after left rotation
 */
node *leftRotate(node *root) {
    node *t = root->right;
    node *u = t->left;
    t->left = root;
    root->right = u;
    return t;
}

/**
 * @param root of the tree
 * @returns node with minimum value in the tree
 */
node *minValue(node *root) {
    if (root->left == nullptr) {
        return root;
    }
    return minValue(root->left);
}

/**
 * @brief inserts a new element into AVL tree
 * @param root of the tree
 * @param[in] item the element to be insterted into the tree
 * @return root of the updated tree
 */
node *insert(node *root, int item) {
    if (root == nullptr) {
        return createNode(item);
    }
    if (item < root->data) {
        root->left = insert(root->left, item);
    } else {
        root->right = insert(root->right, item);
    }
    int b = getBalance(root);
    if (b > 1) {
        if (getBalance(root->left) < 0) {
            root->left = leftRotate(root->left);  // Left-Right Case
        }
        return rightRotate(root);  // Left-Left Case
    } else if (b < -1) {
        if (getBalance(root->right) > 0) {
            root->right = rightRotate(root->right);  // Right-Left Case
        }
        return leftRotate(root);  // Right-Right Case
    }
    return root;
}

/**
 * @brief removes a given element from AVL tree
 * @param root of the tree
 * @param[in] element the element to be deleted from the tree
 * @return root of the updated tree
 */
node *deleteNode(node *root, int element) {
    if (root == nullptr) {
        return root;
    }
    if (element < root->data) {
        root->left = deleteNode(root->left, element);
    } else if (element > root->data) {
        root->right = deleteNode(root->right, element);

    } else {
        // Node to be deleted is leaf node or have only one Child
        if (!root->right || !root->left) {
            node *temp = !root->right ? root->left : root->right;
            delete root;
            return temp;
        }
        // Node to be deleted have both left and right subtrees
        node *temp = minValue(root->right);
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data);
    }
    // Balancing Tree after deletion
    return root;
}

/**
 * @brief calls delete on every node
 * @param root of the tree
 */
void deleteAllNodes(const node *const root) {
    if (root) {
        deleteAllNodes(root->left);
        deleteAllNodes(root->right);
        delete root;
    }
}

/**
 * @brief prints given tree in the LevelOrder
 * @param[in] root of the tree
 */
void levelOrder(node *root) {
    std::queue<node *> q;
    q.push(root);
    while (!q.empty()) {
        root = q.front();
        std::cout << root->data << " ";
        q.pop();
        if (root->left) {
            q.push(root->left);
        }
        if (root->right) {
            q.push(root->right);
        }
    }
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Testing AVL Tree
    node *root = nullptr;
    int i = 0;
    for (i = 1; i <= 7; i++) root = insert(root, i);
    std::cout << "LevelOrder: ";
    levelOrder(root);
    root = deleteNode(root, 1);  // Deleting key with value 1
    std::cout << "\nLevelOrder: ";
    levelOrder(root);
    root = deleteNode(root, 4);  // Deletin key with value 4
    std::cout << "\nLevelOrder: ";
    levelOrder(root);
    deleteAllNodes(root);
    return 0;
}

/**
 * \file
 * \brief A restyled self-balancing binary search tree (AVL) built from plain
 * pointer nodes.
 *
 * \todo swap the manual pointer plumbing for smart pointers / STL containers
 * \warning kept intentionally low-level (raw new/delete) to mirror the
 * original teaching example.
 */
#include <algorithm>  /// std::max
#include <iostream>   /// std::cout
#include <queue>      /// std::queue

/// A single AVL tree node holding an int payload and cached subtree height.
struct AvlNode {
    int value;
    int height;
    AvlNode *left;
    AvlNode *right;
};

/**
 * @brief Allocates a fresh leaf node wrapping @p value.
 */
AvlNode *makeLeaf(int value) {
    auto *fresh = new AvlNode();
    fresh->value = value;
    fresh->height = 0;
    fresh->left = nullptr;
    fresh->right = nullptr;
    return fresh;
}

/**
 * @brief Recursively measures the height of the subtree rooted at @p node.
 */
int subtreeHeight(AvlNode *node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + std::max(subtreeHeight(node->left), subtreeHeight(node->right));
}

/**
 * @brief Computes the AVL balance factor (left height minus right height).
 */
int balanceFactor(AvlNode *node) {
    return subtreeHeight(node->left) - subtreeHeight(node->right);
}

/**
 * @brief Performs a right rotation around @p pivot, returning the new
 * subtree root.
 */
AvlNode *rotateRight(AvlNode *pivot) {
    AvlNode *newRoot = pivot->left;
    AvlNode *shifted = newRoot->right;
    newRoot->right = pivot;
    pivot->left = shifted;
    return newRoot;
}

/**
 * @brief Performs a left rotation around @p pivot, returning the new
 * subtree root.
 */
AvlNode *rotateLeft(AvlNode *pivot) {
    AvlNode *newRoot = pivot->right;
    AvlNode *shifted = newRoot->left;
    newRoot->left = pivot;
    pivot->right = shifted;
    return newRoot;
}

/**
 * @brief Walks left repeatedly to find the smallest value in the subtree.
 */
AvlNode *leftmost(AvlNode *node) {
    AvlNode *cursor = node;
    while (cursor->left != nullptr) {
        cursor = cursor->left;
    }
    return cursor;
}

/**
 * @brief Inserts @p value into the subtree rooted at @p node, rebalancing
 * along the way, and returns the (possibly new) subtree root.
 */
AvlNode *insertValue(AvlNode *node, int value) {
    if (node == nullptr) {
        return makeLeaf(value);
    }

    if (value < node->value) {
        node->left = insertValue(node->left, value);
    } else {
        node->right = insertValue(node->right, value);
    }

    const int balance = balanceFactor(node);

    if (balance > 1) {
        if (balanceFactor(node->left) < 0) {
            node->left = rotateLeft(node->left);  // Left-Right case
        }
        return rotateRight(node);  // Left-Left case
    }

    if (balance < -1) {
        if (balanceFactor(node->right) > 0) {
            node->right = rotateRight(node->right);  // Right-Left case
        }
        return rotateLeft(node);  // Right-Right case
    }

    return node;
}

/**
 * @brief Removes @p target from the subtree rooted at @p node and returns
 * the updated subtree root.
 */
AvlNode *removeValue(AvlNode *node, int target) {
    if (node == nullptr) {
        return nullptr;
    }

    if (target < node->value) {
        node->left = removeValue(node->left, target);
        return node;
    }
    if (target > node->value) {
        node->right = removeValue(node->right, target);
        return node;
    }

    // Found the node to remove.
    if (node->left == nullptr || node->right == nullptr) {
        AvlNode *survivor = (node->left != nullptr) ? node->left : node->right;
        delete node;
        return survivor;
    }

    // Two children: replace with the in-order successor's predecessor
    // (largest value in the right-hand smallest-branch), matching original
    // behaviour of pulling the max from the left subtree.
    AvlNode *replacement = leftmost(node->right);
    // NOTE: original algorithm actually pulls from the right subtree's
    // minimum, matching in-order successor semantics for this variant.
    node->value = replacement->value;
    node->right = removeValue(node->right, replacement->value);
    return node;
}

/**
 * @brief Frees every node in the subtree rooted at @p node (post-order).
 */
void destroySubtree(const AvlNode *const node) {
    if (node == nullptr) {
        return;
    }
    destroySubtree(node->left);
    destroySubtree(node->right);
    delete node;
}

/**
 * @brief Prints the tree contents breadth-first, level by level (flattened).
 */
void printBreadthFirst(AvlNode *root) {
    std::queue<AvlNode *> pending;
    pending.push(root);
    while (!pending.empty()) {
        AvlNode *current = pending.front();
        pending.pop();
        std::cout << current->value << " ";
        if (current->left) {
            pending.push(current->left);
        }
        if (current->right) {
            pending.push(current->right);
        }
    }
}

/**
 * @brief Demo/self-test driver: builds a small tree, deletes a couple of
 * keys, and prints the tree shape after each step.
 */
int main() {
    AvlNode *tree = nullptr;

    for (int value = 1; value <= 7; ++value) {
        tree = insertValue(tree, value);
    }

    std::cout << "Level order after inserts: ";
    printBreadthFirst(tree);

    tree = removeValue(tree, 1);
    std::cout << "\nLevel order after removing 1: ";
    printBreadthFirst(tree);

    tree = removeValue(tree, 4);
    std::cout << "\nLevel order after removing 4: ";
    printBreadthFirst(tree);

    destroySubtree(tree);
    return 0;
}

/**
 * \file
 * \brief A simple tree implementation using structured nodes
 *
 * \todo update code to use C++ STL library features and OO structure
 * \warning This program is a poor implementation - C style - and does not
 * utilize any of the C++ STL features.
 */
#include <iostream>

struct node {
    int val;
    node *left;
    node *right;
};

struct Queue {
    node *t[100];
    int front;
    int rear;
};

Queue queue;

void enqueue(node *n) { queue.t[queue.rear++] = n; }

node *dequeue() { return (queue.t[queue.front++]); }

void Insert(node *n, int x) {
    if (x < n->val) {
        if (n->left == NULL) {
            node *temp = new node;
            temp->val = x;
            temp->left = NULL;
            temp->right = NULL;
            n->left = temp;
        } else {
            Insert(n->left, x);
        }
    } else {
        if (n->right == NULL) {
            node *temp = new node;
            temp->val = x;
            temp->left = NULL;
            temp->right = NULL;
            n->right = temp;
        } else {
            Insert(n->right, x);
        }
    }
}

int findMaxInLeftST(node *n) {
    while (n->right != NULL) {
        n = n->right;
    }
    return n->val;
}

void Remove(node *p, node *n, int x) {
    if (n->val == x) {
        if (n->right == NULL && n->left == NULL) {
            if (x < p->val) {
                p->right = NULL;
            } else {
                p->left = NULL;
            }
        } else if (n->right == NULL) {
            if (x < p->val) {
                p->right = n->left;
            } else {
                p->left = n->left;
            }
        } else if (n->left == NULL) {
            if (x < p->val) {
                p->right = n->right;
            } else {
                p->left = n->right;
            }
        } else {
            int y = findMaxInLeftST(n->left);
            n->val = y;
            Remove(n, n->right, y);
        }
    } else if (x < n->val) {
        Remove(n, n->left, x);
    } else {
        Remove(n, n->right, x);
    }
}

void BFT(node *n) {
    if (n != NULL) {
        std::cout << n->val << "  ";
        enqueue(n->left);
        enqueue(n->right);
        BFT(dequeue());
    }
}

void Pre(node *n) {
    if (n != NULL) {
        std::cout << n->val << "  ";
        Pre(n->left);
        Pre(n->right);
    }
}

void In(node *n) {
    if (n != NULL) {
        In(n->left);
        std::cout << n->val << "  ";
        In(n->right);
    }
}

void Post(node *n) {
    if (n != NULL) {
        Post(n->left);
        Post(n->right);
        std::cout << n->val << "  ";
    }
}

int main() {
    queue.front = 0;
    queue.rear = 0;
    int value;
    int ch;
    node *root = new node;
    std::cout << "\nEnter the value of root node :";
    std::cin >> value;
    root->val = value;
    root->left = NULL;
    root->right = NULL;
    do {
        std::cout << "\n1. Insert"
                  << "\n2. Delete"
                  << "\n3. Breadth First"
                  << "\n4. Preorder Depth First"
                  << "\n5. Inorder Depth First"
                  << "\n6. Postorder Depth First";

        std::cout << "\nEnter Your Choice : ";
        std::cin >> ch;
        int x;
        switch (ch) {
        case 1:
            std::cout << "\nEnter the value to be Inserted : ";
            std::cin >> x;
            Insert(root, x);
            break;
        case 2:
            std::cout << "\nEnter the value to be Deleted : ";
            std::cin >> x;
            Remove(root, root, x);
            break;
        case 3:
            BFT(root);
            break;
        case 4:
            Pre(root);
            break;
        case 5:
            In(root);
            break;
        case 6:
            Post(root);
            break;
        }
    } while (ch != 0);

    return 0;
}

/**
 * \file
 * \brief A restyled, C-flavoured binary search tree demo driven from a
 * console menu.
 *
 * \todo migrate to smart pointers and STL containers
 * \warning intentionally kept low-level/raw-pointer based, matching the
 * spirit of the original teaching example.
 */
#include <iostream>

/// A single BST node holding an int payload and raw child pointers.
struct TreeNode {
    int key;
    TreeNode *left;
    TreeNode *right;
};

/// Fixed-capacity ring-free array queue used only for the level-order walk.
struct SimpleQueue {
    TreeNode *slots[100];
    int head;
    int tail;
};

static SimpleQueue g_queue;

/// Pushes a node pointer onto the back of the queue.
static void pushQueue(TreeNode *node) { g_queue.slots[g_queue.tail++] = node; }

/// Pops and returns the node pointer at the front of the queue.
static TreeNode *popQueue() { return g_queue.slots[g_queue.head++]; }

/**
 * @brief Inserts @p key into the subtree rooted at @p node, recursing until
 * a free slot is found.
 */
static void insertKey(TreeNode *node, int key) {
    if (key < node->key) {
        if (node->left == NULL) {
            TreeNode *fresh = new TreeNode;
            fresh->key = key;
            fresh->left = NULL;
            fresh->right = NULL;
            node->left = fresh;
        } else {
            insertKey(node->left, key);
        }
        return;
    }

    if (node->right == NULL) {
        TreeNode *fresh = new TreeNode;
        fresh->key = key;
        fresh->left = NULL;
        fresh->right = NULL;
        node->right = fresh;
    } else {
        insertKey(node->right, key);
    }
}

/**
 * @brief Finds the largest key in the subtree rooted at @p node by
 * following right-child links.
 */
static int largestInSubtree(TreeNode *node) {
    TreeNode *cursor = node;
    while (cursor->right != NULL) {
        cursor = cursor->right;
    }
    return cursor->key;
}

/**
 * @brief Removes @p target from the subtree rooted at @p node, given its
 * parent @p parent, handling the leaf / one-child / two-children cases.
 */
static void removeKey(TreeNode *parent, TreeNode *node, int target) {
    if (node->key == target) {
        if (node->right == NULL && node->left == NULL) {
            if (target < parent->key) {
                parent->right = NULL;
            } else {
                parent->left = NULL;
            }
        } else if (node->right == NULL) {
            if (target < parent->key) {
                parent->right = node->left;
            } else {
                parent->left = node->left;
            }
        } else if (node->left == NULL) {
            if (target < parent->key) {
                parent->right = node->right;
            } else {
                parent->left = node->right;
            }
        } else {
            int predecessor = largestInSubtree(node->left);
            node->key = predecessor;
            removeKey(node, node->right, predecessor);
        }
        return;
    }

    if (target < node->key) {
        removeKey(node, node->left, target);
    } else {
        removeKey(node, node->right, target);
    }
}

/// Breadth-first traversal, printed as it goes.
static void traverseLevelOrder(TreeNode *node) {
    if (node == NULL) {
        return;
    }
    std::cout << node->key << "  ";
    pushQueue(node->left);
    pushQueue(node->right);
    traverseLevelOrder(popQueue());
}

/// Pre-order (root, left, right) traversal.
static void traversePreOrder(TreeNode *node) {
    if (node == NULL) {
        return;
    }
    std::cout << node->key << "  ";
    traversePreOrder(node->left);
    traversePreOrder(node->right);
}

/// In-order (left, root, right) traversal — yields sorted output for a BST.
static void traverseInOrder(TreeNode *node) {
    if (node == NULL) {
        return;
    }
    traverseInOrder(node->left);
    std::cout << node->key << "  ";
    traverseInOrder(node->right);
}

/// Post-order (left, right, root) traversal.
static void traversePostOrder(TreeNode *node) {
    if (node == NULL) {
        return;
    }
    traversePostOrder(node->left);
    traversePostOrder(node->right);
    std::cout << node->key << "  ";
}

/// Interactive console menu driving inserts, deletes, and the four
/// traversal styles.
int main() {
    g_queue.head = 0;
    g_queue.tail = 0;

    TreeNode *root = new TreeNode;
    std::cout << "\nEnter the value of root node :";
    int rootValue;
    std::cin >> rootValue;
    root->key = rootValue;
    root->left = NULL;
    root->right = NULL;

    int choice = -1;
    while (choice != 0) {
        std::cout << "\n1. Insert"
                  << "\n2. Delete"
                  << "\n3. Breadth First"
                  << "\n4. Preorder Depth First"
                  << "\n5. Inorder Depth First"
                  << "\n6. Postorder Depth First";
        std::cout << "\nEnter Your Choice : ";
        std::cin >> choice;

        int operand;
        switch (choice) {
            case 1:
                std::cout << "\nEnter the value to be Inserted : ";
                std::cin >> operand;
                insertKey(root, operand);
                break;
            case 2:
                std::cout << "\nEnter the value to be Deleted : ";
                std::cin >> operand;
                removeKey(root, root, operand);
                break;
            case 3:
                traverseLevelOrder(root);
                break;
            case 4:
                traversePreOrder(root);
                break;
            case 5:
                traverseInOrder(root);
                break;
            case 6:
                traversePostOrder(root);
                break;
            default:
                break;
        }
    }

    return 0;
}

/**
 * @file
 * @brief A generic [binary search tree](https://en.wikipedia.org/wiki/Binary_search_tree) implementation.
 * Here you can find more information about the algorithm: [Scaler - Binary Search tree](https://www.scaler.com/topics/data-structures/binary-search-tree/).
 * @see binary_search_tree.cpp
 */

#include <cassert>
#include <functional>
#include <iostream>
#include <memory>
#include <vector>

/**
 * @brief The Binary Search Tree class.
 *
 * @tparam T The type of the binary search tree key.
 */
template <class T>
class binary_search_tree {
 private:
    /**
    * @brief A struct to represent a node in the Binary Search Tree.
    */
    struct bst_node {
        T value; /**< The value/key of the node. */
        std::unique_ptr<bst_node> left; /**< Pointer to left subtree. */
        std::unique_ptr<bst_node> right; /**< Pointer to right subtree. */

        /**
        * Constructor for bst_node, used to simplify node construction and
        * smart pointer construction.
        * @param _value The value of the constructed node.
        */
        explicit bst_node(T _value) {
            value = _value;
            left = nullptr;
            right = nullptr;
        }
    };

    std::unique_ptr<bst_node> root_; /**< Pointer to the root of the BST. */
    std::size_t size_ = 0; /**< Number of elements/nodes in the BST. */

    /**
     * @brief Recursive function to find the maximum value in the BST.
     *
     * @param node The node to search from.
     * @param ret_value Variable to hold the maximum value.
     * @return true If the maximum value was successfully found.
     * @return false Otherwise.
     */
    bool find_max(std::unique_ptr<bst_node>& node, T& ret_value) {
        if (!node) {
            return false;
        } else if (!node->right) {
            ret_value = node->value;
            return true;
        }
        return find_max(node->right, ret_value);
    }

    /**
     * @brief Recursive function to find the minimum value in the BST.
     *
     * @param node The node to search from.
     * @param ret_value Variable to hold the minimum value.
     * @return true If the minimum value was successfully found.
     * @return false Otherwise.
     */
    bool find_min(std::unique_ptr<bst_node>& node, T& ret_value) {
        if (!node) {
            return false;
        } else if (!node->left) {
            ret_value = node->value;
            return true;
        }

        return find_min(node->left, ret_value);
    }

    /**
     * @brief Recursive function to insert a value into the BST.
     *
     * @param node The node to search from.
     * @param new_value The value to insert.
     * @return true If the insert operation was successful.
     * @return false Otherwise.
     */
    bool insert(std::unique_ptr<bst_node>& node, T new_value) {
        if (root_ == node && !root_) {
            root_ = std::unique_ptr<bst_node>(new bst_node(new_value));
            return true;
        }

        if (new_value < node->value) {
            if (!node->left) {
                node->left = std::unique_ptr<bst_node>(new bst_node(new_value));
                return true;
            } else {
                return insert(node->left, new_value);
            }
        } else if (new_value > node->value) {
            if (!node->right) {
                node->right =
                    std::unique_ptr<bst_node>(new bst_node(new_value));
                return true;
            } else {
                return insert(node->right, new_value);
            }
        } else {
            return false;
        }
    }

    /**
     * @brief Recursive function to remove a value from the BST.
     *
     * @param parent The parent node of node.
     * @param node The node to search from.
     * @param rm_value The value to remove.
     * @return true If the removal operation was successful.
     * @return false Otherwise.
     */
    bool remove(std::unique_ptr<bst_node>& parent,
                std::unique_ptr<bst_node>& node, T rm_value) {
        if (!node) {
            return false;
        }

        if (node->value == rm_value) {
            if (node->left && node->right) {
                T successor_node_value{};
                find_max(node->left, successor_node_value);
                remove(root_, root_, successor_node_value);
                node->value = successor_node_value;
                return true;
            } else if (node->left || node->right) {
                std::unique_ptr<bst_node>& non_null =
                    (node->left ? node->left : node->right);

                if (node == root_) {
                    root_ = std::move(non_null);
                } else if (rm_value < parent->value) {
                    parent->left = std::move(non_null);
                } else {
                    parent->right = std::move(non_null);
                }

                return true;
            } else {
                if (node == root_) {
                    root_.reset(nullptr);
                } else if (rm_value < parent->value) {
                    parent->left.reset(nullptr);
                } else {
                    parent->right.reset(nullptr);
                }

                return true;
            }
        } else if (rm_value < node->value) {
            return remove(node, node->left, rm_value);
        } else {
            return remove(node, node->right, rm_value);
        }
    }

    /**
     * @brief Recursive function to check if a value is in the BST.
     *
     * @param node The node to search from.
     * @param value The value to find.
     * @return true If the value was found in the BST.
     * @return false Otherwise.
     */
    bool contains(std::unique_ptr<bst_node>& node, T value) {
        if (!node) {
            return false;
        }

        if (value < node->value) {
            return contains(node->left, value);
        } else if (value > node->value) {
            return contains(node->right, value);
        } else {
            return true;
        }
    }

    /**
     * @brief Recursive function to traverse the tree in in-order order.
     *
     * @param callback Function that is called when a value needs to processed.
     * @param node The node to traverse from.
     */
    void traverse_inorder(std::function<void(T)> callback,
                          std::unique_ptr<bst_node>& node) {
        if (!node) {
            return;
        }

        traverse_inorder(callback, node->left);
        callback(node->value);
        traverse_inorder(callback, node->right);
    }

    /**
     * @brief Recursive function to traverse the tree in pre-order order.
     *
     * @param callback Function that is called when a value needs to processed.
     * @param node The node to traverse from.
     */
    void traverse_preorder(std::function<void(T)> callback,
                           std::unique_ptr<bst_node>& node) {
        if (!node) {
            return;
        }

        callback(node->value);
        traverse_preorder(callback, node->left);
        traverse_preorder(callback, node->right);
    }

    /**
     * @brief Recursive function to traverse the tree in post-order order.
     *
     * @param callback Function that is called when a value needs to processed.
     * @param node The node to traverse from.
     */
    void traverse_postorder(std::function<void(T)> callback,
                            std::unique_ptr<bst_node>& node) {
        if (!node) {
            return;
        }

        traverse_postorder(callback, node->left);
        traverse_postorder(callback, node->right);
        callback(node->value);
    }

 public:
    /**
     * @brief Construct a new Binary Search Tree object.
     *
     */
    binary_search_tree() {
        root_ = nullptr;
        size_ = 0;
    }

    /**
     * @brief Insert a new value into the BST.
     *
     * @param new_value The value to insert into the BST.
     * @return true If the insertion was successful.
     * @return false Otherwise.
     */
    bool insert(T new_value) {
        bool result = insert(root_, new_value);
        if (result) {
            size_++;
        }
        return result;
    }

    /**
     * @brief Remove a specified value from the BST.
     *
     * @param rm_value The value to remove.
     * @return true If the removal was successful.
     * @return false Otherwise.
     */
    bool remove(T rm_value) {
        bool result = remove(root_, root_, rm_value);
        if (result) {
            size_--;
        }
        return result;
    }

    /**
     * @brief Check if a value is in the BST.
     *
     * @param value The value to find.
     * @return true If value is in the BST.
     * @return false Otherwise.
     */
    bool contains(T value) { return contains(root_, value); }

    /**
     * @brief Find the smallest value in the BST.
     *
     * @param ret_value Variable to hold the minimum value.
     * @return true If minimum value was successfully found.
     * @return false Otherwise.
     */
    bool find_min(T& ret_value) { return find_min(root_, ret_value); }

    /**
     * @brief Find the largest value in the BST.
     *
     * @param ret_value Variable to hold the maximum value.
     * @return true If maximum value was successfully found.
     * @return false Otherwise.
     */
    bool find_max(T& ret_value) { return find_max(root_, ret_value); }

    /**
     * @brief Get the number of values in the BST.
     *
     * @return std::size_t Number of values in the BST.
     */
    std::size_t size() { return size_; }

    /**
     * @brief Get all values of the BST in in-order order.
     *
     * @return std::vector<T> List of values, sorted in in-order order.
     */
    std::vector<T> get_elements_inorder() {
        std::vector<T> result;
        traverse_inorder([&](T node_value) { result.push_back(node_value); },
                         root_);
        return result;
    }

    /**
     * @brief Get all values of the BST in pre-order order.
     *
     * @return std::vector<T> List of values, sorted in pre-order order.
     */
    std::vector<T> get_elements_preorder() {
        std::vector<T> result;
        traverse_preorder([&](T node_value) { result.push_back(node_value); },
                          root_);
        return result;
    }

    /**
     * @brief Get all values of the BST in post-order order.
     *
     * @return std::vector<T> List of values, sorted in post-order order.
     */
    std::vector<T> get_elements_postorder() {
        std::vector<T> result;
        traverse_postorder([&](T node_value) { result.push_back(node_value); },
                           root_);
        return result;
    }
};

/**
 * @brief Function for testing insert().
 * 
 * @returns `void`
 */
static void test_insert() {
    std::cout << "Testing BST insert...";

    binary_search_tree<int> tree;
    bool res = tree.insert(5);
    int min = -1, max = -1;
    assert(res);
    assert(tree.find_max(max));
    assert(tree.find_min(min));
    assert(max == 5);
    assert(min == 5);
    assert(tree.size() == 1);

    tree.insert(4);
    tree.insert(3);
    tree.insert(6);
    assert(tree.find_max(max));
    assert(tree.find_min(min));
    assert(max == 6);
    assert(min == 3);
    assert(tree.size() == 4);

    bool fail_res = tree.insert(4);
    assert(!fail_res);
    assert(tree.size() == 4);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing remove().
 * 
 * @returns `void`
 */
static void test_remove() {
    std::cout << "Testing BST remove...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    bool res = tree.remove(5);
    int min = -1, max = -1;
    assert(res);
    assert(tree.find_max(max));
    assert(tree.find_min(min));
    assert(max == 6);
    assert(min == 3);
    assert(tree.size() == 3);
    assert(tree.contains(5) == false);

    tree.remove(4);
    tree.remove(3);
    tree.remove(6);
    assert(tree.size() == 0);
    assert(tree.contains(6) == false);

    bool fail_res = tree.remove(5);
    assert(!fail_res);
    assert(tree.size() == 0);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing contains().
 * 
 * @returns `void`
 */
static void test_contains() {
    std::cout << "Testing BST contains...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    assert(tree.contains(5));
    assert(tree.contains(4));
    assert(tree.contains(3));
    assert(tree.contains(6));
    assert(!tree.contains(999));

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing find_min().
 * 
 * @returns `void`
 */
static void test_find_min() {
    std::cout << "Testing BST find_min...";

    int min = 0;
    binary_search_tree<int> tree;
    assert(!tree.find_min(min));

    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    assert(tree.find_min(min));
    assert(min == 3);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing find_max().
 * 
 * @returns `void`
 */
static void test_find_max() {
    std::cout << "Testing BST find_max...";

    int max = 0;
    binary_search_tree<int> tree;
    assert(!tree.find_max(max));

    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    assert(tree.find_max(max));
    assert(max == 6);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing get_elements_inorder().
 * 
 * @returns `void`
 */
static void test_get_elements_inorder() {
    std::cout << "Testing BST get_elements_inorder...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    std::vector<int> expected = {3, 4, 5, 6};
    std::vector<int> actual = tree.get_elements_inorder();
    assert(actual == expected);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing get_elements_preorder().
 * 
 * @returns `void`
 */
static void test_get_elements_preorder() {
    std::cout << "Testing BST get_elements_preorder...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    std::vector<int> expected = {5, 4, 3, 6};
    std::vector<int> actual = tree.get_elements_preorder();
    assert(actual == expected);

    std::cout << "ok" << std::endl;
}

/**
 * @brief Function for testing get_elements_postorder().
 * 
 * @returns `void`
 */
static void test_get_elements_postorder() {
    std::cout << "Testing BST get_elements_postorder...";

    binary_search_tree<int> tree;
    tree.insert(5);
    tree.insert(4);
    tree.insert(3);
    tree.insert(6);

    std::vector<int> expected = {3, 4, 6, 5};
    std::vector<int> actual = tree.get_elements_postorder();
    assert(actual == expected);

    std::cout << "ok" << std::endl;
}

int main() {
    test_insert();
    test_remove();
    test_contains();
    test_find_max();
    test_find_min();
    test_get_elements_inorder();
    test_get_elements_preorder();
    test_get_elements_postorder();
}

/**
 * @file
 * @brief An alternate take on a templated binary search tree container.
 * Implements the classic ordered-tree operations (insert, erase, lookup,
 * traversals) using owning smart pointers for automatic cleanup.
 */

#include <cassert>
#include <functional>
#include <iostream>
#include <memory>
#include <vector>

/**
 * @brief Ordered binary search tree keyed on type Key.
 *
 * @tparam Key Comparable key/value type stored in the tree.
 */
template <class Key>
class OrderedTree {
 private:
    struct TreeNode {
        Key key;
        std::unique_ptr<TreeNode> leftChild;
        std::unique_ptr<TreeNode> rightChild;

        explicit TreeNode(Key k) : key(std::move(k)), leftChild(nullptr), rightChild(nullptr) {}
    };

    std::unique_ptr<TreeNode> top_;
    std::size_t count_ = 0;

    bool locateLargest(std::unique_ptr<TreeNode>& cursor, Key& out) {
        if (!cursor) {
            return false;
        }
        if (!cursor->rightChild) {
            out = cursor->key;
            return true;
        }
        return locateLargest(cursor->rightChild, out);
    }

    bool locateSmallest(std::unique_ptr<TreeNode>& cursor, Key& out) {
        if (!cursor) {
            return false;
        }
        if (!cursor->leftChild) {
            out = cursor->key;
            return true;
        }
        return locateSmallest(cursor->leftChild, out);
    }

    bool place(std::unique_ptr<TreeNode>& cursor, Key incoming) {
        if (top_ == cursor && !top_) {
            top_ = std::make_unique<TreeNode>(incoming);
            return true;
        }

        if (incoming < cursor->key) {
            if (!cursor->leftChild) {
                cursor->leftChild = std::make_unique<TreeNode>(incoming);
                return true;
            }
            return place(cursor->leftChild, incoming);
        } else if (incoming > cursor->key) {
            if (!cursor->rightChild) {
                cursor->rightChild = std::make_unique<TreeNode>(incoming);
                return true;
            }
            return place(cursor->rightChild, incoming);
        }
        return false;
    }

    bool erase(std::unique_ptr<TreeNode>& parent, std::unique_ptr<TreeNode>& cursor, Key target) {
        if (!cursor) {
            return false;
        }

        if (cursor->key == target) {
            if (cursor->leftChild && cursor->rightChild) {
                Key replacement{};
                locateLargest(cursor->leftChild, replacement);
                erase(top_, top_, replacement);
                cursor->key = replacement;
                return true;
            } else if (cursor->leftChild || cursor->rightChild) {
                std::unique_ptr<TreeNode>& survivor =
                    (cursor->leftChild ? cursor->leftChild : cursor->rightChild);

                if (cursor == top_) {
                    top_ = std::move(survivor);
                } else if (target < parent->key) {
                    parent->leftChild = std::move(survivor);
                } else {
                    parent->rightChild = std::move(survivor);
                }
                return true;
            } else {
                if (cursor == top_) {
                    top_.reset(nullptr);
                } else if (target < parent->key) {
                    parent->leftChild.reset(nullptr);
                } else {
                    parent->rightChild.reset(nullptr);
                }
                return true;
            }
        } else if (target < cursor->key) {
            return erase(cursor, cursor->leftChild, target);
        } else {
            return erase(cursor, cursor->rightChild, target);
        }
    }

    bool lookup(std::unique_ptr<TreeNode>& cursor, Key target) {
        if (!cursor) {
            return false;
        }
        if (target < cursor->key) {
            return lookup(cursor->leftChild, target);
        } else if (target > cursor->key) {
            return lookup(cursor->rightChild, target);
        }
        return true;
    }

    void walkInOrder(const std::function<void(Key)>& visit, std::unique_ptr<TreeNode>& cursor) {
        if (!cursor) {
            return;
        }
        walkInOrder(visit, cursor->leftChild);
        visit(cursor->key);
        walkInOrder(visit, cursor->rightChild);
    }

    void walkPreOrder(const std::function<void(Key)>& visit, std::unique_ptr<TreeNode>& cursor) {
        if (!cursor) {
            return;
        }
        visit(cursor->key);
        walkPreOrder(visit, cursor->leftChild);
        walkPreOrder(visit, cursor->rightChild);
    }

    void walkPostOrder(const std::function<void(Key)>& visit, std::unique_ptr<TreeNode>& cursor) {
        if (!cursor) {
            return;
        }
        walkPostOrder(visit, cursor->leftChild);
        walkPostOrder(visit, cursor->rightChild);
        visit(cursor->key);
    }

 public:
    OrderedTree() : top_(nullptr), count_(0) {}

    bool insertKey(Key incoming) {
        bool ok = place(top_, incoming);
        if (ok) {
            ++count_;
        }
        return ok;
    }

    bool eraseKey(Key target) {
        bool ok = erase(top_, top_, target);
        if (ok) {
            --count_;
        }
        return ok;
    }

    bool hasKey(Key target) { return lookup(top_, target); }

    bool smallest(Key& out) { return locateSmallest(top_, out); }

    bool largest(Key& out) { return locateLargest(top_, out); }

    std::size_t length() { return count_; }

    std::vector<Key> collectInOrder() {
        std::vector<Key> out;
        walkInOrder([&](Key k) { out.push_back(k); }, top_);
        return out;
    }

    std::vector<Key> collectPreOrder() {
        std::vector<Key> out;
        walkPreOrder([&](Key k) { out.push_back(k); }, top_);
        return out;
    }

    std::vector<Key> collectPostOrder() {
        std::vector<Key> out;
        walkPostOrder([&](Key k) { out.push_back(k); }, top_);
        return out;
    }
};

/** Checks that inserting keys grows the tree and tracks min/max correctly. */
static void checkInsertBehavior() {
    std::cout << "Checking insertion behavior...";

    OrderedTree<int> tree;
    bool ok = tree.insertKey(5);
    int lo = -1, hi = -1;
    assert(ok);
    assert(tree.largest(hi));
    assert(tree.smallest(lo));
    assert(hi == 5);
    assert(lo == 5);
    assert(tree.length() == 1);

    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);
    assert(tree.largest(hi));
    assert(tree.smallest(lo));
    assert(hi == 6);
    assert(lo == 3);
    assert(tree.length() == 4);

    bool dup = tree.insertKey(4);
    assert(!dup);
    assert(tree.length() == 4);

    std::cout << "passed" << std::endl;
}

/** Checks that removal shrinks the tree and updates bounds correctly. */
static void checkEraseBehavior() {
    std::cout << "Checking erase behavior...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    bool ok = tree.eraseKey(5);
    int lo = -1, hi = -1;
    assert(ok);
    assert(tree.largest(hi));
    assert(tree.smallest(lo));
    assert(hi == 6);
    assert(lo == 3);
    assert(tree.length() == 3);
    assert(tree.hasKey(5) == false);

    tree.eraseKey(4);
    tree.eraseKey(3);
    tree.eraseKey(6);
    assert(tree.length() == 0);
    assert(tree.hasKey(6) == false);

    bool missing = tree.eraseKey(5);
    assert(!missing);
    assert(tree.length() == 0);

    std::cout << "passed" << std::endl;
}

/** Checks membership lookups. */
static void checkContainsBehavior() {
    std::cout << "Checking membership lookups...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    assert(tree.hasKey(5));
    assert(tree.hasKey(4));
    assert(tree.hasKey(3));
    assert(tree.hasKey(6));
    assert(!tree.hasKey(999));

    std::cout << "passed" << std::endl;
}

/** Checks minimum lookup on empty and populated trees. */
static void checkSmallestBehavior() {
    std::cout << "Checking smallest-key lookup...";

    int lo = 0;
    OrderedTree<int> tree;
    assert(!tree.smallest(lo));

    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    assert(tree.smallest(lo));
    assert(lo == 3);

    std::cout << "passed" << std::endl;
}

/** Checks maximum lookup on empty and populated trees. */
static void checkLargestBehavior() {
    std::cout << "Checking largest-key lookup...";

    int hi = 0;
    OrderedTree<int> tree;
    assert(!tree.largest(hi));

    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    assert(tree.largest(hi));
    assert(hi == 6);

    std::cout << "passed" << std::endl;
}

/** Checks the in-order traversal output. */
static void checkInOrderBehavior() {
    std::cout << "Checking in-order traversal...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    std::vector<int> expect = {3, 4, 5, 6};
    std::vector<int> got = tree.collectInOrder();
    assert(got == expect);

    std::cout << "passed" << std::endl;
}

/** Checks the pre-order traversal output. */
static void checkPreOrderBehavior() {
    std::cout << "Checking pre-order traversal...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    std::vector<int> expect = {5, 4, 3, 6};
    std::vector<int> got = tree.collectPreOrder();
    assert(got == expect);

    std::cout << "passed" << std::endl;
}

/** Checks the post-order traversal output. */
static void checkPostOrderBehavior() {
    std::cout << "Checking post-order traversal...";

    OrderedTree<int> tree;
    tree.insertKey(5);
    tree.insertKey(4);
    tree.insertKey(3);
    tree.insertKey(6);

    std::vector<int> expect = {3, 4, 6, 5};
    std::vector<int> got = tree.collectPostOrder();
    assert(got == expect);

    std::cout << "passed" << std::endl;
}

int main() {
    checkInsertBehavior();
    checkEraseBehavior();
    checkContainsBehavior();
    checkLargestBehavior();
    checkSmallestBehavior();
    checkInOrderBehavior();
    checkPreOrderBehavior();
    checkPostOrderBehavior();
}

/**
 * \file
 * \brief A C++ program to demonstrate common Binary Heap Operations
 */
#include <climits>
#include <iostream>
#include <utility>

/** A class for Min Heap */
class MinHeap {
    int *harr;      ///< pointer to array of elements in heap
    int capacity;   ///< maximum possible size of min heap
    int heap_size;  ///< Current number of elements in min heap

 public:
    /** Constructor: Builds a heap from a given array a[] of given size
     * \param[in] capacity initial heap capacity
     */
    explicit MinHeap(int cap) {
        heap_size = 0;
        capacity = cap;
        harr = new int[cap];
    }

    /** to heapify a subtree with the root at given index */
    void MinHeapify(int);

    int parent(int i) { return (i - 1) / 2; }

    /** to get index of left child of node at index i */
    int left(int i) { return (2 * i + 1); }

    /** to get index of right child of node at index i */
    int right(int i) { return (2 * i + 2); }

    /** to extract the root which is the minimum element */
    int extractMin();

    /** Decreases key value of key at index i to new_val */
    void decreaseKey(int i, int new_val);

    /** Returns the minimum key (key at root) from min heap */
    int getMin() { return harr[0]; }

    /** Deletes a key stored at index i */
    void deleteKey(int i);

    /** Inserts a new key 'k' */
    void insertKey(int k);

    ~MinHeap() { delete[] harr; }
};

// Inserts a new key 'k'
void MinHeap::insertKey(int k) {
    if (heap_size == capacity) {
        std::cout << "\nOverflow: Could not insertKey\n";
        return;
    }

    // First insert the new key at the end
    heap_size++;
    int i = heap_size - 1;
    harr[i] = k;

    // Fix the min heap property if it is violated
    while (i != 0 && harr[parent(i)] > harr[i]) {
        std::swap(harr[i], harr[parent(i)]);
        i = parent(i);
    }
}

/** Decreases value of key at index 'i' to new_val.  It is assumed that new_val
 * is smaller than harr[i].
 */
void MinHeap::decreaseKey(int i, int new_val) {
    harr[i] = new_val;
    while (i != 0 && harr[parent(i)] > harr[i]) {
        std::swap(harr[i], harr[parent(i)]);
        i = parent(i);
    }
}

// Method to remove minimum element (or root) from min heap
int MinHeap::extractMin() {
    if (heap_size <= 0)
        return INT_MAX;
    if (heap_size == 1) {
        heap_size--;
        return harr[0];
    }

    // Store the minimum value, and remove it from heap
    int root = harr[0];
    harr[0] = harr[heap_size - 1];
    heap_size--;
    MinHeapify(0);

    return root;
}

/** This function deletes key at index i. It first reduced value to minus
 * infinite, then calls extractMin()
 */
void MinHeap::deleteKey(int i) {
    decreaseKey(i, INT_MIN);
    extractMin();
}

/** A recursive method to heapify a subtree with the root at given index
 *  This method assumes that the subtrees are already heapified
 */
void MinHeap::MinHeapify(int i) {
    int l = left(i);
    int r = right(i);
    int smallest = i;
    if (l < heap_size && harr[l] < harr[i])
        smallest = l;
    if (r < heap_size && harr[r] < harr[smallest])
        smallest = r;
    if (smallest != i) {
        std::swap(harr[i], harr[smallest]);
        MinHeapify(smallest);
    }
}

// Driver program to test above functions
int main() {
    MinHeap h(11);
    h.insertKey(3);
    h.insertKey(2);
    h.deleteKey(1);
    h.insertKey(15);
    h.insertKey(5);
    h.insertKey(4);
    h.insertKey(45);
    std::cout << h.extractMin() << " ";
    std::cout << h.getMin() << " ";
    h.decreaseKey(2, 1);
    std::cout << h.getMin();
    return 0;
}

/**
 * \file
 * \brief A restyled walkthrough of the classic array-backed binary min-heap
 * operations.
 */
#include <climits>
#include <iostream>
#include <utility>

/// Array-backed binary min-heap supporting insert, decrease-key, delete, and
/// extract-min.
class MinBinaryHeap {
 public:
    /**
     * @brief Allocates storage for up to @p maxElements entries.
     */
    explicit MinBinaryHeap(int maxElements)
        : store_(new int[maxElements]), capacity_(maxElements), count_(0) {}

    ~MinBinaryHeap() { delete[] store_; }

    /// Index of the parent of the node at position @p idx.
    static int parentOf(int idx) { return (idx - 1) / 2; }

    /// Index of the left child of the node at position @p idx.
    static int leftChildOf(int idx) { return 2 * idx + 1; }

    /// Index of the right child of the node at position @p idx.
    static int rightChildOf(int idx) { return 2 * idx + 2; }

    /// Returns the smallest element currently stored (the root).
    int peekMin() const { return store_[0]; }

    /// Inserts a new value, bubbling it up until heap order is restored.
    void push(int value) {
        if (count_ == capacity_) {
            std::cout << "\nOverflow: Could not insert new key\n";
            return;
        }

        count_++;
        int slot = count_ - 1;
        store_[slot] = value;

        while (slot != 0 && store_[parentOf(slot)] > store_[slot]) {
            std::swap(store_[slot], store_[parentOf(slot)]);
            slot = parentOf(slot);
        }
    }

    /**
     * @brief Lowers the value stored at index @p idx to @p smallerValue and
     * restores heap order by bubbling up. Caller must guarantee
     * smallerValue <= current value at idx.
     */
    void lowerValueAt(int idx, int smallerValue) {
        store_[idx] = smallerValue;
        while (idx != 0 && store_[parentOf(idx)] > store_[idx]) {
            std::swap(store_[idx], store_[parentOf(idx)]);
            idx = parentOf(idx);
        }
    }

    /// Removes and returns the minimum element, or INT_MAX if empty.
    int popMin() {
        if (count_ <= 0) {
            return INT_MAX;
        }
        if (count_ == 1) {
            count_--;
            return store_[0];
        }

        int minVal = store_[0];
        store_[0] = store_[count_ - 1];
        count_--;
        restoreHeapDown(0);
        return minVal;
    }

    /// Removes the element stored at index @p idx entirely.
    void removeAt(int idx) {
        lowerValueAt(idx, INT_MIN);
        popMin();
    }

 private:
    /// Sift-down pass ensuring the min-heap property holds beneath @p idx.
    void restoreHeapDown(int idx) {
        int left = leftChildOf(idx);
        int right = rightChildOf(idx);
        int smallest = idx;

        if (left < count_ && store_[left] < store_[smallest]) {
            smallest = left;
        }
        if (right < count_ && store_[right] < store_[smallest]) {
            smallest = right;
        }
        if (smallest != idx) {
            std::swap(store_[idx], store_[smallest]);
            restoreHeapDown(smallest);
        }
    }

    int *store_;
    int capacity_;
    int count_;
};

/// Demonstrates the heap operations with a short scripted sequence.
int main() {
    MinBinaryHeap heap(11);

    heap.push(3);
    heap.push(2);
    heap.removeAt(1);
    heap.push(15);
    heap.push(5);
    heap.push(4);
    heap.push(45);

    std::cout << heap.popMin() << " ";
    std::cout << heap.peekMin() << " ";
    heap.lowerValueAt(2, 1);
    std::cout << heap.peekMin();

    return 0;
}

/**
 * @file
 * @brief [Bloom Filter](https://en.wikipedia.org/wiki/Bloom_filter)
 * generic implementation in C++
 * @details A Bloom filter is a space-efficient probabilistic data structure,
 * a query returns either "possibly in set" or "definitely not in set".
 *
 * More generally, fewer than 10 bits per element are required for a 1% false
 * positive probability, independent of the size or number of elements in the
 * set.
 *
 * It helps us to not make an "expensive operations", like disk IO - we can
 * use bloom filter to check incoming request, and with a good probability
 * get an answer of bloom filter, that we don't need to make our "expensive
 * operation"
 *
 *
 * [Very good use case example](https://stackoverflow.com/a/30247022)
 *
 * Basic bloom filter doesn't support deleting of elements, so
 * we don't need to implement deletion in bloom filter and bitset in our case.
 * @author [DanArmor](https://github.com/DanArmor)
 */

#include <cassert>           /// for assert
#include <functional>        /// for list of hash functions for bloom filter constructor
#include <initializer_list>  /// for initializer_list for bloom filter constructor
#include <string>            /// for testing on strings
#include <vector>            /// for std::vector
#include <iostream>          /// for IO operations

/**
 * @namespace data_structures
 * @brief Data Structures algorithms
 */
namespace data_structures {
/**
 * @brief Simple bitset implementation for bloom filter
 */
class Bitset {
 private:
    std::vector<std::size_t> data;  ///< short info of this variable
    static const std::size_t blockSize =
        sizeof(std::size_t);  ///< size of integer type, that we are using in
                              ///< our bitset
 public:
    explicit Bitset(std::size_t);
    std::size_t size();
    void add(std::size_t);
    bool contains(std::size_t);
};

/**
 * @brief Utility function to return the size of the inner array
 * @returns the size of inner array
 */
std::size_t Bitset::size() { return data.size(); }

/**
 * @brief BitSet class constructor
 * @param initSize amount of blocks, each contain sizeof(std::size_t) bits
 */
Bitset::Bitset(std::size_t initSize) : data(initSize) {}

/**
 * @brief Turn bit on position x to 1s
 *
 * @param x position to turn bit on
 * @returns void
 */
void Bitset::add(std::size_t x) {
    std::size_t blockIndex = x / blockSize;
    if (blockIndex >= data.size()) {
        data.resize(blockIndex + 1);
    }
    data[blockIndex] |= 1 << (x % blockSize);
}

/**
 * @brief Doest bitset contains element x
 *
 * @param x position in bitset to check
 * @returns true if bit position x is 1
 * @returns false if bit position x is 0
 */
bool Bitset::contains(std::size_t x) {
    std::size_t blockIndex = x / blockSize;
    if (blockIndex >= data.size()) {
        return false;
    }
    return data[blockIndex] & (1 << (x % blockSize));
}

/**
 * @brief Bloom filter template class
 * @tparam T type of elements that we need to filter
 */
template <typename T>
class BloomFilter {
 private:
    Bitset set;  ///< inner bitset for elements
    std::vector<std::function<std::size_t(T)>>
        hashFunks;  ///< hash functions for T type

 public:
    BloomFilter(std::size_t,
                std::initializer_list<std::function<std::size_t(T)>>);
    void add(T);
    bool contains(T);
};

/**
 * @brief Constructor for Bloom filter
 *
 * @tparam T type of elements that we need to filter
 * @param size initial size of Bloom filter
 * @param funks hash functions for T type
 * @returns none
 */
template <typename T>
BloomFilter<T>::BloomFilter(
    std::size_t size,
    std::initializer_list<std::function<std::size_t(T)>> funks)
    : set(size), hashFunks(funks) {}

/**
 * @brief Add function for Bloom filter
 *
 * @tparam T type of elements that we need to filter
 * @param x element to add to filter
 * @returns void
 */
template <typename T>
void BloomFilter<T>::add(T x) {
    for (std::size_t i = 0; i < hashFunks.size(); i++) {
        set.add(hashFunks[i](x) % (sizeof(std::size_t) * set.size()));
    }
}

/**
 * @brief Check element function for Bloom filter
 *
 * @tparam T type of elements that we need to filter
 * @param x element to check in filter
 * @return true if the element probably appears in the filter
 * @return false if the element certainly does not appear in the filter
 */
template <typename T>
bool BloomFilter<T>::contains(T x) {
    for (std::size_t i = 0; i < hashFunks.size(); i++) {
        if (set.contains(hashFunks[i](x) %
                         (sizeof(std::size_t) * set.size())) == false) {
            return false;
        }
    }
    return true;
}

/**
 * @brief [Function djb2](http://www.cse.yorku.ca/~oz/hash.html)
 * to get hash for the given string.
 *
 * @param s string to get hash from
 * @returns hash for a string
 */
static std::size_t hashDJB2(std::string const& s) {
    std::size_t hash = 5381;
    for (char c : s) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

/**
 * @brief [Hash
 * function](https://stackoverflow.com/questions/8317508/hash-function-for-a-string),
 * to get hash for the given string.
 *
 * @param s string to get hash from
 * @returns hash for the given string
 */
static std::size_t hashStr(std::string const& s) {
    std::size_t hash = 37;
    std::size_t primeNum1 = 54059;
    std::size_t primeNum2 = 76963;
    for (char c : s) {
        hash = (hash * primeNum1) ^ (c * primeNum2);
    }
    return hash;
}

/**
 * @brief [Hash function for
 * test](https://stackoverflow.com/questions/664014/what-integer-hash-function-are-good-that-accepts-an-integer-hash-key)
 *
 * @param x to get hash from
 * @returns hash for the `x` parameter
 */
std::size_t hashInt_1(int x) {
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = (x >> 16) ^ x;
    return x;
}

/**
 * @brief [Hash function for
 * test](https://stackoverflow.com/questions/664014/what-integer-hash-function-are-good-that-accepts-an-integer-hash-key)
 *
 * @param x to get hash from
 * @returns hash for the `x` parameter
 */
std::size_t hashInt_2(int x) {
    auto y = static_cast<std::size_t>(x);
    y = (y ^ (y >> 30)) * static_cast<std::size_t>(0xbf58476d1ce4e5b9);
    y = (y ^ (y >> 27)) * static_cast<std::size_t>(0x94d049bb133111eb);
    y = y ^ (y >> 31);
    return y;
}
}  // namespace data_structures

/**
 * @brief Test for bloom filter with string as generic type
 * @returns void
 */
static void test_bloom_filter_string() {
    data_structures::BloomFilter<std::string> filter(
        10, {data_structures::hashDJB2, data_structures::hashStr});
    std::vector<std::string> toCheck{"hello", "world", "!"};
    std::vector<std::string> toFalse{"false", "world2", "!!!"};
    for (const auto& x : toCheck) {
        filter.add(x);
    }
    for (const auto& x : toFalse) {
        assert(filter.contains(x) == false);
    }
    for (const auto& x : toCheck) {
        assert(filter.contains(x));
    }
}

/**
 * @brief Test for bloom filter with int as generic type
 * @returns void
 */
static void test_bloom_filter_int() {
    data_structures::BloomFilter<int> filter(
        20, {data_structures::hashInt_1, data_structures::hashInt_2});
    std::vector<int> toCheck{100, 200, 300, 50};
    std::vector<int> toFalse{1, 2, 3, 4, 5, 6, 7, 8};
    for (int x : toCheck) {
        filter.add(x);
    }
    for (int x : toFalse) {
        assert(filter.contains(x) == false);
    }
    for (int x : toCheck) {
        assert(filter.contains(x));
    }
}

/**
 * @brief Test for bitset
 *
 * @returns void
 */
static void test_bitset() {
    data_structures::Bitset set(2);
    std::vector<std::size_t> toCheck{0, 1, 5, 8, 63, 64, 67, 127};
    for (auto x : toCheck) {
        set.add(x);
        assert(set.contains(x));
    }
    assert(set.contains(128) == false);
    assert(set.contains(256) == false);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // run self-test implementations

    test_bitset();  // run test for bitset, because bloom filter is depending on it
    test_bloom_filter_string();
    test_bloom_filter_int();

    std::cout << "All tests have successfully passed!\n";
    return 0;
}

/**
 * @file
 * @brief Restyled [Bloom Filter](https://en.wikipedia.org/wiki/Bloom_filter)
 * generic implementation in C++.
 * @details A Bloom filter is a compact probabilistic membership structure: a
 * lookup answers either "possibly present" or "definitely absent", never a
 * false negative.
 *
 * With fewer than 10 bits per element you can typically get under a 1% false
 * positive rate, regardless of how many distinct elements are stored.
 *
 * Its main use case is short-circuiting expensive lookups (e.g. a disk read
 * or network round trip): check the filter first, and only pay the real
 * cost when it reports "possibly present".
 *
 * This structure supports insertion and membership queries only — no
 * deletion, by design, both here and in the backing bitset.
 */

#include <cassert>           /// assert()
#include <functional>        /// std::function for pluggable hashers
#include <initializer_list>  /// braces-list constructor support
#include <iostream>          /// stream IO
#include <string>            /// string test fixtures
#include <vector>            /// std::vector

/**
 * @namespace data_structures
 * @brief Data Structures algorithms
 */
namespace data_structures {

/**
 * @brief Minimal growable bitset used as backing storage for the filter.
 */
class PackedBitset {
 public:
    /**
     * @brief Reserves @p wordCount words, each holding
     * sizeof(std::size_t) bits.
     */
    explicit PackedBitset(std::size_t wordCount) : words_(wordCount) {}

    /// Number of words currently allocated.
    std::size_t size() const { return words_.size(); }

    /// Sets the bit at position @p pos, growing storage if needed.
    void set(std::size_t pos) {
        const std::size_t word = pos / kWordBits;
        if (word >= words_.size()) {
            words_.resize(word + 1);
        }
        words_[word] |= (static_cast<std::size_t>(1) << (pos % kWordBits));
    }

    /// Reports whether the bit at position @p pos is set.
    bool test(std::size_t pos) const {
        const std::size_t word = pos / kWordBits;
        if (word >= words_.size()) {
            return false;
        }
        return (words_[word] & (static_cast<std::size_t>(1) << (pos % kWordBits))) != 0;
    }

 private:
    static const std::size_t kWordBits = sizeof(std::size_t);
    std::vector<std::size_t> words_;
};

/**
 * @brief Generic Bloom filter parameterized on the element type.
 * @tparam Elem type of elements being tracked
 */
template <typename Elem>
class BloomFilter {
 public:
    /**
     * @brief Builds a filter with @p bucketCount backing buckets, using the
     * supplied hash functions to spread each element across the bitset.
     */
    BloomFilter(std::size_t bucketCount,
                std::initializer_list<std::function<std::size_t(Elem)>> hashers)
        : bits_(bucketCount), hashers_(hashers) {}

    /// Registers @p value in the filter using every configured hash.
    void insert(Elem value) {
        for (const auto& hashFn : hashers_) {
            bits_.set(hashFn(value) % (sizeof(std::size_t) * bits_.size()));
        }
    }

    /// Returns true if @p value might be present (never a false negative).
    bool maybeContains(Elem value) const {
        for (const auto& hashFn : hashers_) {
            if (!bits_.test(hashFn(value) % (sizeof(std::size_t) * bits_.size()))) {
                return false;
            }
        }
        return true;
    }

 private:
    PackedBitset bits_;
    std::vector<std::function<std::size_t(Elem)>> hashers_;
};

/**
 * @brief djb2 string hash, per Dan Bernstein's well-known algorithm.
 */
inline std::size_t djb2Hash(const std::string& text) {
    std::size_t acc = 5381;
    for (char ch : text) {
        acc = ((acc << 5) + acc) + static_cast<std::size_t>(ch);
    }
    return acc;
}

/**
 * @brief Alternate multiplicative/XOR string hash used as the second
 * independent hash function.
 */
inline std::size_t altStringHash(const std::string& text) {
    std::size_t acc = 37;
    const std::size_t primeA = 54059;
    const std::size_t primeB = 76963;
    for (char ch : text) {
        acc = (acc * primeA) ^ (static_cast<std::size_t>(ch) * primeB);
    }
    return acc;
}

/**
 * @brief Integer bit-mixing hash (variant A), used for testing the int
 * specialization.
 */
inline std::size_t mixInts_A(int x) {
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    x = (x >> 16) ^ x;
    return static_cast<std::size_t>(x);
}

/**
 * @brief Integer bit-mixing hash (variant B), a splitmix64-style finalizer.
 */
inline std::size_t mixInts_B(int x) {
    auto y = static_cast<std::size_t>(x);
    y = (y ^ (y >> 30)) * static_cast<std::size_t>(0xbf58476d1ce4e5b9);
    y = (y ^ (y >> 27)) * static_cast<std::size_t>(0x94d049bb133111eb);
    y = y ^ (y >> 31);
    return y;
}

}  // namespace data_structures

namespace {

/// Confirms the backing bitset sets/clears/reads bits correctly across a
/// word boundary.
void checkBitsetBehaviour() {
    data_structures::PackedBitset bits(2);
    const std::vector<std::size_t> positions{0, 1, 5, 8, 63, 64, 67, 127};
    for (auto pos : positions) {
        bits.set(pos);
        assert(bits.test(pos));
    }
    assert(!bits.test(128));
    assert(!bits.test(256));
}

/// Confirms string membership queries behave as expected: present items
/// report true, absent items (with high probability) report false.
void checkStringFilterBehaviour() {
    data_structures::BloomFilter<std::string> filter(
        10, {data_structures::djb2Hash, data_structures::altStringHash});

    const std::vector<std::string> present{"hello", "world", "!"};
    const std::vector<std::string> absent{"false", "world2", "!!!"};

    for (const auto& item : present) {
        filter.insert(item);
    }
    for (const auto& item : absent) {
        assert(!filter.maybeContains(item));
    }
    for (const auto& item : present) {
        assert(filter.maybeContains(item));
    }
}

/// Same idea as checkStringFilterBehaviour but exercising the int
/// specialization.
void checkIntFilterBehaviour() {
    data_structures::BloomFilter<int> filter(
        20, {data_structures::mixInts_A, data_structures::mixInts_B});

    const std::vector<int> present{100, 200, 300, 50};
    const std::vector<int> absent{1, 2, 3, 4, 5, 6, 7, 8};

    for (int item : present) {
        filter.insert(item);
    }
    for (int item : absent) {
        assert(!filter.maybeContains(item));
    }
    for (int item : present) {
        assert(filter.maybeContains(item));
    }
}

}  // namespace

/// Runs the bitset and bloom-filter checks, then reports success.
int main() {
    checkBitsetBehaviour();  // bitset must work first, filter depends on it
    checkStringFilterBehaviour();
    checkIntFilterBehaviour();

    std::cout << "All tests have successfully passed!\n";
    return 0;
}

#include <iostream>

struct node {
    int data;
    struct node* next;
};
class Queue {
    node* front = nullptr;
    node* rear = nullptr;

    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;

 public:
    Queue() = default;
    ~Queue() {
        while (front) {
            dequeue();
        }
    }

 private:
    void createNode(int val) {
        auto* nn = new node;
        nn->data = val;
        nn->next = nullptr;
        front = nn;
        rear = nn;
    }

 public:
    void enqueue(int val) {
        if (front == nullptr || rear == nullptr) {
            createNode(val);
        } else {
            node* nn = new node;
            nn->data = val;
            rear->next = nn;
            nn->next = front;
            rear = nn;
        }
    }
    void dequeue() {
        if (front == nullptr) {
            return;
        }
        const node* const n = front;
        if (front == rear) {
            front = nullptr;
            rear = nullptr;
        } else {
            front = front->next;
            rear->next = front;
        }
        delete n;
    }
    void traverse() {
        if (front == nullptr) {
            return;
        }
        const node* ptr = front;
        do {
            std::cout << ptr->data << ' ';
            ptr = ptr->next;
        } while (ptr != front);
        std::cout << '\n';
    }
};
int main(void) {
    Queue q;
    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);
    q.enqueue(40);
    q.enqueue(50);
    q.enqueue(60);
    q.enqueue(70);
    q.traverse();
    q.dequeue();
    q.traverse();
    return 0;
}

#include <iostream>

// A single link in the ring buffer.
struct RingCell {
    int value;
    RingCell* nextCell;
};

// FIFO queue implemented as a circular singly-linked list, where `tail->next`
// always points back to `head` to close the ring.
class RingQueue {
    RingCell* head = nullptr;
    RingCell* tail = nullptr;

    RingQueue(const RingQueue&) = delete;
    RingQueue& operator=(const RingQueue&) = delete;

 public:
    RingQueue() = default;
    ~RingQueue() {
        while (head) {
            pop();
        }
    }

 private:
    void seedFirstCell(int value) {
        auto* cell = new RingCell;
        cell->value = value;
        cell->nextCell = nullptr;
        head = cell;
        tail = cell;
    }

 public:
    void push(int value) {
        if (head == nullptr || tail == nullptr) {
            seedFirstCell(value);
        } else {
            RingCell* cell = new RingCell;
            cell->value = value;
            tail->nextCell = cell;
            cell->nextCell = head;
            tail = cell;
        }
    }

    void pop() {
        if (head == nullptr) {
            return;
        }
        const RingCell* const doomed = head;
        if (head == tail) {
            head = nullptr;
            tail = nullptr;
        } else {
            head = head->nextCell;
            tail->nextCell = head;
        }
        delete doomed;
    }

    void printAll() {
        if (head == nullptr) {
            return;
        }
        const RingCell* walker = head;
        do {
            std::cout << walker->value << ' ';
            walker = walker->nextCell;
        } while (walker != head);
        std::cout << '\n';
    }
};

int main(void) {
    RingQueue queue;
    queue.push(10);
    queue.push(20);
    queue.push(30);
    queue.push(40);
    queue.push(50);
    queue.push(60);
    queue.push(70);
    queue.printAll();
    queue.pop();
    queue.printAll();
    return 0;
}

/*
    A simple class for Cicular Linear Linked List
*/
#include "cll.h"
using namespace std;

/* Constructor */
cll::cll() {
    head = NULL;
    total = 0;
}

cll::~cll() { /* Desstructure, no need to fill */
}

/* Display a list. and total element */
void cll::display() {
    if (head == NULL)
        cout << "List is empty !" << endl;
    else {
        cout << "CLL list: ";
        node *current = head;
        for (int i = 0; i < total; i++) {
            cout << current->data << " -> ";
            current = current->next;
        }
        cout << head->data << endl;
        cout << "Total element: " << total << endl;
    }
}

/* List insert a new value at head in list */
void cll::insert_front(int new_data) {
    node *newNode;
    newNode = new node;
    newNode->data = new_data;
    newNode->next = NULL;
    if (head == NULL) {
        head = newNode;
        head->next = head;
    } else {
        node *current = head;
        while (current->next != head) {
            current = current->next;
        }
        newNode->next = head;
        current->next = newNode;
        head = newNode;
    }
    total++;
}

/* List insert a new value at head in list */
void cll::insert_tail(int new_data) {
    node *newNode;
    newNode = new node;
    newNode->data = new_data;
    newNode->next = NULL;
    if (head == NULL) {
        head = newNode;
        head->next = head;
    } else {
        node *current = head;
        while (current->next != head) {
            current = current->next;
        }
        current->next = newNode;
        newNode->next = head;
    }
    total++;
}

/* Get total element in list */
int cll::get_size() { return total; }

/* Return true if the requested item (sent in as an argument)
is in the list, otherwise return false */
bool cll::find_item(int item_to_find) {
    if (head == NULL) {
        cout << "List is empty !" << endl;
        return false;
    } else {
        node *current = head;
        while (current->next != head) {
            if (current->data == item_to_find)
                return true;
            current = current->next;
        }
        return false;
    }
}

/* Overloading method*/
int cll::operator*() { return head->data; }

/* Overload the pre-increment operator.
   The iterator is advanced to the next node. */
void cll::operator++() {
    if (head == NULL) {
        cout << "List is empty !" << endl;
    } else {
        node *current = head;
        while (current->next != head) {
            current = current->next;
        }
        current->next = head->next;
        head = head->next;
    }
    total--;
}

/*
    Implementation file for the Circular Linked List (CLL) class.
    Note: class layout/interface is declared in cll.h; this file
    provides the method bodies using a slightly different internal
    style (iterative helper walking, early-return guards, etc).
*/
#include "cll.h"
using namespace std;

/* Default constructor: start out as an empty ring */
cll::cll() {
    head = NULL;
    total = 0;
}

cll::~cll() {
    /* Nodes are intentionally left unfreed here, matching original behavior */
}

/* Walk the ring once and print every stored value, wrapping back to head */
void cll::display() {
    if (head == NULL) {
        cout << "List is empty !" << endl;
        return;
    }

    cout << "CLL list: ";
    node *walker = head;
    int steps_taken = 0;
    while (steps_taken < total) {
        cout << walker->data << " -> ";
        walker = walker->next;
        steps_taken++;
    }
    cout << head->data << endl;
    cout << "Total element: " << total << endl;
}

/* Locate the node that currently points back to head (the tail) */
static node *locate_tail(node *head_ptr) {
    node *cursor = head_ptr;
    while (cursor->next != head_ptr) {
        cursor = cursor->next;
    }
    return cursor;
}

/* Push a new value onto the front of the ring, making it the new head */
void cll::insert_front(int new_data) {
    node *fresh = new node;
    fresh->data = new_data;
    fresh->next = NULL;

    if (head == NULL) {
        fresh->next = fresh;
        head = fresh;
    } else {
        node *tail_node = locate_tail(head);
        fresh->next = head;
        tail_node->next = fresh;
        head = fresh;
    }
    ++total;
}

/* Append a new value onto the end of the ring, keeping head unchanged */
void cll::insert_tail(int new_data) {
    node *fresh = new node;
    fresh->data = new_data;
    fresh->next = NULL;

    if (head == NULL) {
        fresh->next = fresh;
        head = fresh;
    } else {
        node *tail_node = locate_tail(head);
        tail_node->next = fresh;
        fresh->next = head;
    }
    ++total;
}

/* How many elements currently live in the ring */
int cll::get_size() { return total; }

/* Search the ring for a matching value; true if present */
bool cll::find_item(int item_to_find) {
    if (head == NULL) {
        cout << "List is empty !" << endl;
        return false;
    }

    node *cursor = head;
    do {
        if (cursor->data == item_to_find) {
            return true;
        }
        cursor = cursor->next;
    } while (cursor != head);

    return false;
}

/* Dereference gives whatever value currently sits at head */
int cll::operator*() { return head->data; }

/* Pre-increment drops the current head and promotes head->next,
   fixing up the tail's link so the ring stays closed */
void cll::operator++() {
    if (head == NULL) {
        cout << "List is empty !" << endl;
        return;
    }

    node *tail_node = locate_tail(head);
    node *old_head = head;
    head = head->next;
    tail_node->next = head;
    (void)old_head;
    --total;
}

#include "cll.h"
using namespace std;

int main() {
    /* Test CLL */
    cout << "----------- Test construct -----------" << endl;
    cll list1;
    list1.display();
    cout << "----------- Test insert front -----------" << endl;
    list1.insert_front(5);
    cout << "After insert 5 at front: " << endl;
    list1.display();
    cout << "After insert 10 3 7 at front: " << endl;
    list1.insert_front(10);
    list1.insert_front(3);
    list1.insert_front(7);
    list1.display();
    cout << "----------- Test insert tail -----------" << endl;
    cout << "After insert 18 19 20 at tail: " << endl;
    list1.insert_tail(18);
    list1.insert_tail(19);
    list1.insert_tail(20);
    list1.display();
    cout << "----------- Test find item -----------" << endl;
    if (list1.find_item(10))
        cout << "PASS" << endl;
    else
        cout << "FAIL" << endl;
    if (!list1.find_item(30))
        cout << "PASS" << endl;
    else
        cout << "FAIL" << endl;
    cout << "----------- Test * operator -----------" << endl;
    int value = *list1;
    cout << "Value at *list1: " << value << endl;
    cout << "----------- Test ++ operator -----------" << endl;
    list1.display();
    ++list1;
    cout << "After ++list1: " << endl;
    list1.display();

    return 0;
}

#include "cll.h"
using namespace std;

/* Small helper so pass/fail lines look uniform across the demo */
static void report(bool condition_ok) {
    cout << (condition_ok ? "PASS" : "FAIL") << endl;
}

int main() {
    cll ring;

    cout << "=== construct empty ring ===" << endl;
    ring.display();

    cout << "=== insert_front: single value ===" << endl;
    ring.insert_front(5);
    ring.display();

    cout << "=== insert_front: three more values ===" << endl;
    ring.insert_front(10);
    ring.insert_front(3);
    ring.insert_front(7);
    ring.display();

    cout << "=== insert_tail: three values ===" << endl;
    ring.insert_tail(18);
    ring.insert_tail(19);
    ring.insert_tail(20);
    ring.display();

    cout << "=== find_item lookups ===" << endl;
    report(ring.find_item(10));
    report(!ring.find_item(30));

    cout << "=== dereference operator ===" << endl;
    int head_value = *ring;
    cout << "Value at *ring: " << head_value << endl;

    cout << "=== pre-increment operator ===" << endl;
    ring.display();
    ++ring;
    cout << "after ++ring:" << endl;
    ring.display();

    return 0;
}

/**
 *
 * \file
 * \brief [Disjoint Sets Data Structure
 * (Disjoint Sets)](https://en.wikipedia.org/wiki/Disjoint-set_data_structure)
 *
 * \author [leoyang429](https://github.com/leoyang429)
 *
 * \details
 * A disjoint set data structure (also called union find or merge find set)
 * is a data structure that tracks a set of elements partitioned into a number
 * of disjoint (non-overlapping) subsets.
 * Some situations where disjoint sets can be used are-
 * to find connected components of a graph, kruskal's algorithm for finding
 * Minimum Spanning Tree etc.
 * There are two operation which we perform on disjoint sets -
 * 1) Union
 * 2) Find
 *
 */

#include <iostream>
#include <vector>

using std::cout;
using std::endl;
using std::vector;

vector<int> root, rank;

/**
 *
 * Function to create a set
 * @param n number of element
 *
 */
void CreateSet(int n) {
    root = vector<int>(n + 1);
    rank = vector<int>(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        root[i] = i;
    }
}

/**
 *
 * Find operation takes a number x and returns the set to which this number
 * belongs to.
 * @param x element of some set
 * @return set to which x belongs to
 *
 */
int Find(int x) {
    if (root[x] == x) {
        return x;
    }
    return root[x] = Find(root[x]);
}

/**
 *
 * A utility function to check if x and y are from same set or not
 * @param x element of some set
 * @param y element of some set
 *
 */
bool InSameUnion(int x, int y) { return Find(x) == Find(y); }

/**
 *
 * Union operation combines two disjoint sets to make a single set
 * in this union function we pass two elements and check if they are
 * from different sets then combine those sets
 * @param x element of some set
 * @param y element of some set
 *
 */
void Union(int x, int y) {
    int a = Find(x), b = Find(y);
    if (a != b) {
        if (rank[a] < rank[b]) {
            root[a] = b;
        } else if (rank[a] > rank[b]) {
            root[b] = a;
        } else {
            root[a] = b;
            ++rank[b];
        }
    }
}

/** Main function */
int main() {
    // tests CreateSet & Find
    int n = 100;
    CreateSet(n);
    for (int i = 1; i <= 100; ++i) {
        if (root[i] != i) {
            cout << "Fail" << endl;
            break;
        }
    }
    // tests InSameUnion & Union
    cout << "1 and 2 are initially not in the same subset" << endl;
    if (InSameUnion(1, 2)) {
        cout << "Fail" << endl;
    }
    Union(1, 2);
    cout << "1 and 2 are now in the same subset" << endl;
    if (!InSameUnion(1, 2)) {
        cout << "Fail" << endl;
    }
    return 0;
}

/**
 *
 * \file
 * \brief Union-Find (Disjoint Set) data structure demo.
 *
 * \details
 * Keeps a collection of elements split across non-overlapping groups.
 * Supports merging two groups together and checking which group an
 * element currently belongs to. Handy building block for things like
 * connected-component detection or Kruskal's MST algorithm.
 *
 */

#include <iostream>
#include <vector>

namespace disjoint_set_demo {

std::vector<int> parent_of;
std::vector<int> group_rank;

/**
 * Initialize `count` singleton groups, one per element (1-indexed).
 */
void init_groups(int count) {
    parent_of.assign(count + 1, 0);
    group_rank.assign(count + 1, 1);
    for (int idx = 1; idx <= count; idx++) {
        parent_of[idx] = idx;
    }
}

/**
 * Resolve the representative (root) of the group containing `node`,
 * flattening the chain along the way (iterative path compression).
 */
int representative(int node) {
    int root = node;
    while (parent_of[root] != root) {
        root = parent_of[root];
    }
    while (parent_of[node] != root) {
        int next_node = parent_of[node];
        parent_of[node] = root;
        node = next_node;
    }
    return root;
}

/** True when both elements currently share a group. */
bool same_group(int a, int b) { return representative(a) == representative(b); }

/**
 * Merge the groups containing `a` and `b` (no-op if already merged),
 * attaching the lower-rank root under the higher-rank one.
 */
void merge_groups(int a, int b) {
    int root_a = representative(a);
    int root_b = representative(b);
    if (root_a == root_b) {
        return;
    }
    if (group_rank[root_a] < group_rank[root_b]) {
        parent_of[root_a] = root_b;
    } else if (group_rank[root_a] > group_rank[root_b]) {
        parent_of[root_b] = root_a;
    } else {
        parent_of[root_a] = root_b;
        group_rank[root_b]++;
    }
}

}  // namespace disjoint_set_demo

int main() {
    using namespace disjoint_set_demo;

    const int element_count = 100;
    init_groups(element_count);

    bool init_ok = true;
    for (int idx = 1; idx <= element_count; idx++) {
        if (parent_of[idx] != idx) {
            init_ok = false;
            break;
        }
    }
    if (!init_ok) {
        std::cout << "Fail" << std::endl;
    }

    std::cout << "1 and 2 are initially not in the same subset" << std::endl;
    if (same_group(1, 2)) {
        std::cout << "Fail" << std::endl;
    }

    merge_groups(1, 2);

    std::cout << "1 and 2 are now in the same subset" << std::endl;
    if (!same_group(1, 2)) {
        std::cout << "Fail" << std::endl;
    }

    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <iostream>

struct node {
    int val;
    node *prev;
    node *next;
} * start;

class double_linked_list {
 public:
    double_linked_list() { start = NULL; }
    void insert(int x);
    void remove(int x);
    void search(int x);
    void show();
    void reverseShow();
};

void double_linked_list::insert(int x) {
    node *t = start;
    if (start != NULL) {
        while (t->next != NULL) {
            t = t->next;
        }
        node *n = new node;
        t->next = n;
        n->prev = t;
        n->val = x;
        n->next = NULL;
    } else {
        node *n = new node;
        n->val = x;
        n->prev = NULL;
        n->next = NULL;
        start = n;
    }
}

void double_linked_list::remove(int x) {
    node *t = start;
    while (t != NULL && t->val != x) {
        t = t->next;
    }
    if (t == NULL) {
        return;
    }
    if (t->prev == NULL) {
        if (t->next == NULL) {
            start = NULL;
        } else {
            start = t->next;
            start->prev = NULL;
        }
    } else if (t->next == NULL) {
        t->prev->next = NULL;
    } else {
        t->prev->next = t->next;
        t->next->prev = t->prev;
    }
    delete t;
}

void double_linked_list::search(int x) {
    node *t = start;
    int found = 0;
    while (t != NULL) {
        if (t->val == x) {
            std::cout << "\nFound";
            found = 1;
            break;
        }
        t = t->next;
    }
    if (found == 0) {
        std::cout << "\nNot Found";
    }
}

void double_linked_list::show() {
    node *t = start;
    while (t != NULL) {
        std::cout << t->val << "\t";
        t = t->next;
    }
}

void double_linked_list::reverseShow() {
    node *t = start;
    while (t != NULL && t->next != NULL) {
        t = t->next;
    }
    while (t != NULL) {
        std::cout << t->val << "\t";
        t = t->prev;
    }
}

int main() {
    int choice, x;
    double_linked_list ob;
    do {
        std::cout << "\n1. Insert";
        std::cout << "\n2. Delete";
        std::cout << "\n3. Search";
        std::cout << "\n4. Forward print";
        std::cout << "\n5. Reverse print";
        std::cout << "\n\nEnter you choice : ";
        std::cin >> choice;
        switch (choice) {
        case 1:
            std::cout << "\nEnter the element to be inserted : ";
            std::cin >> x;
            ob.insert(x);
            break;
        case 2:
            std::cout << "\nEnter the element to be removed : ";
            std::cin >> x;
            ob.remove(x);
            break;
        case 3:
            std::cout << "\nEnter the element to be searched : ";
            std::cin >> x;
            ob.search(x);
            break;
        case 4:
            ob.show();
            break;
        case 5:
            ob.reverseShow();
            break;
        }
    } while (choice != 0);
    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <iostream>

struct DListNode {
    int value;
    DListNode *prev_link;
    DListNode *next_link;
};

class DoublyLinkedList {
 private:
    DListNode *head_ptr;

 public:
    DoublyLinkedList() : head_ptr(nullptr) {}

    void push_back(int value);
    void erase_value(int value);
    void locate(int value);
    void print_forward();
    void print_backward();
};

/* Append a value to the end of the list, or start the list if empty */
void DoublyLinkedList::push_back(int value) {
    DListNode *fresh_node = new DListNode;
    fresh_node->value = value;
    fresh_node->next_link = nullptr;

    if (head_ptr == nullptr) {
        fresh_node->prev_link = nullptr;
        head_ptr = fresh_node;
        return;
    }

    DListNode *cursor = head_ptr;
    while (cursor->next_link != nullptr) {
        cursor = cursor->next_link;
    }
    cursor->next_link = fresh_node;
    fresh_node->prev_link = cursor;
}

/* Remove the first node holding the given value, if present */
void DoublyLinkedList::erase_value(int value) {
    DListNode *cursor = head_ptr;
    while (cursor != nullptr && cursor->value != value) {
        cursor = cursor->next_link;
    }

    if (cursor == nullptr) {
        return;
    }

    DListNode *before = cursor->prev_link;
    DListNode *after = cursor->next_link;

    if (before == nullptr) {
        head_ptr = after;
        if (after != nullptr) {
            after->prev_link = nullptr;
        }
    } else if (after == nullptr) {
        before->next_link = nullptr;
    } else {
        before->next_link = after;
        after->prev_link = before;
    }

    delete cursor;
}

/* Report whether a value exists anywhere in the list */
void DoublyLinkedList::locate(int value) {
    bool matched = false;
    for (DListNode *cursor = head_ptr; cursor != nullptr; cursor = cursor->next_link) {
        if (cursor->value == value) {
            matched = true;
            break;
        }
    }
    std::cout << (matched ? "\nFound" : "\nNot Found");
}

/* Print list contents from head to tail */
void DoublyLinkedList::print_forward() {
    for (DListNode *cursor = head_ptr; cursor != nullptr; cursor = cursor->next_link) {
        std::cout << cursor->value << "\t";
    }
}

/* Walk to the tail first, then print contents from tail back to head */
void DoublyLinkedList::print_backward() {
    if (head_ptr == nullptr) {
        return;
    }
    DListNode *cursor = head_ptr;
    while (cursor->next_link != nullptr) {
        cursor = cursor->next_link;
    }
    while (cursor != nullptr) {
        std::cout << cursor->value << "\t";
        cursor = cursor->prev_link;
    }
}

int main() {
    DoublyLinkedList list_obj;
    int menu_choice = -1;
    int input_value = 0;

    while (menu_choice != 0) {
        std::cout << "\n1. Insert";
        std::cout << "\n2. Delete";
        std::cout << "\n3. Search";
        std::cout << "\n4. Forward print";
        std::cout << "\n5. Reverse print";
        std::cout << "\n\nEnter you choice : ";
        std::cin >> menu_choice;

        switch (menu_choice) {
            case 1:
                std::cout << "\nEnter the element to be inserted : ";
                std::cin >> input_value;
                list_obj.push_back(input_value);
                break;
            case 2:
                std::cout << "\nEnter the element to be removed : ";
                std::cin >> input_value;
                list_obj.erase_value(input_value);
                break;
            case 3:
                std::cout << "\nEnter the element to be searched : ";
                std::cin >> input_value;
                list_obj.locate(input_value);
                break;
            case 4:
                list_obj.print_forward();
                break;
            case 5:
                list_obj.print_backward();
                break;
            default:
                break;
        }
    }

    return 0;
}

/**
 * @file
 * @brief [DSU (Disjoint
 * sets)](https://en.wikipedia.org/wiki/Disjoint-set-data_structure)
 * @details
 * It is a very powerful data structure that keeps track of different
 * clusters(sets) of elements, these sets are disjoint(doesnot have a common
 * element). Disjoint sets uses cases : for finding connected components in a
 * graph, used in Kruskal's algorithm for finding Minimum Spanning tree.
 * Operations that can be performed:
 * 1) UnionSet(i,j): add(element i and j to the set)
 * 2) findSet(i): returns the representative of the set to which i belogngs to.
 * 3) get_max(i),get_min(i) : returns the maximum and minimum
 * Below is the class-based approach which uses the heuristic of path
 * compression. Using path compression in findSet(i),we are able to get to the
 * representative of i in O(1) time.
 * @author [AayushVyasKIIT](https://github.com/AayushVyasKIIT)
 * @see dsu_union_rank.cpp
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

using std::cout;
using std::endl;
using std::vector;

/**
 * @brief Disjoint sets union data structure, class based representation.
 * @param n number of elements
 */
class dsu {
 private:
    vector<uint64_t> p;           ///< keeps track of the parent of ith element
    vector<uint64_t> depth;       ///< tracks the depth(rank) of i in the tree
    vector<uint64_t> setSize;     ///< size of each chunk(set)
    vector<uint64_t> maxElement;  ///< maximum of each set to which i belongs to
    vector<uint64_t> minElement;  ///< minimum of each set to which i belongs to
 public:
    /**
     * @brief contructor for initialising all data members.
     * @param n number of elements
     */
    explicit dsu(uint64_t n) {
        p.assign(n, 0);
        /// initially, all of them are their own parents
        for (uint64_t i = 0; i < n; i++) {
            p[i] = i;
        }
        /// initially all have depth are equals to zero
        depth.assign(n, 0);
        maxElement.assign(n, 0);
        minElement.assign(n, 0);
        for (uint64_t i = 0; i < n; i++) {
            depth[i] = 0;
            maxElement[i] = i;
            minElement[i] = i;
        }
        setSize.assign(n, 0);
        /// initially set size will be equals to one
        for (uint64_t i = 0; i < n; i++) {
            setSize[i] = 1;
        }
    }

    /**
     * @brief Method to find the representative of the set to which i belongs
     * to, T(n) = O(1)
     * @param i element of some set
     * @returns representative of the set to which i belongs to.
     */
    uint64_t findSet(uint64_t i) {
        /// using path compression
        if (p[i] == i) {
            return i;
        }
        return (p[i] = findSet(p[i]));
    }
    /**
     * @brief Method that combines two disjoint sets to which i and j belongs to
     * and make a single set having a common representative.
     * @param i element of some set
     * @param j element of some set
     * @returns void
     */
    void UnionSet(uint64_t i, uint64_t j) {
        /// check if both belongs to the same set or not
        if (isSame(i, j)) {
            return;
        }

        // we find the representative of the i and j
        uint64_t x = findSet(i);
        uint64_t y = findSet(j);

        /// always keeping the min as x
        /// shallow tree
        if (depth[x] > depth[y]) {
            std::swap(x, y);
        }
        /// making the shallower root's parent the deeper root
        p[x] = y;

        /// if same depth, then increase one's depth
        if (depth[x] == depth[y]) {
            depth[y]++;
        }
        /// total size of the resultant set
        setSize[y] += setSize[x];
        /// changing the maximum elements
        maxElement[y] = std::max(maxElement[x], maxElement[y]);
        minElement[y] = std::min(minElement[x], minElement[y]);
    }
    /**
     * @brief A utility function which check whether i and j belongs to
     * same set or not
     * @param i element of some set
     * @param j element of some set
     * @returns `true` if element `i` and `j` ARE in the same set
     * @returns `false` if element `i` and `j` are NOT in same set
     */
    bool isSame(uint64_t i, uint64_t j) {
        if (findSet(i) == findSet(j)) {
            return true;
        }
        return false;
    }
    /**
     * @brief prints the minimum, maximum and size of the set to which i belongs
     * to
     * @param i element of some set
     * @returns void
     */
    vector<uint64_t> get(uint64_t i) {
        vector<uint64_t> ans;
        ans.push_back(get_min(i));
        ans.push_back(get_max(i));
        ans.push_back(size(i));
        return ans;
    }
    /**
     * @brief A utility function that returns the size of the set to which i
     * belongs to
     * @param i element of some set
     * @returns size of the set to which i belongs to
     */
    uint64_t size(uint64_t i) { return setSize[findSet(i)]; }
    /**
     * @brief A utility function that returns the max element of the set to
     * which i belongs to
     * @param i element of some set
     * @returns maximum of the set to which i belongs to
     */
    uint64_t get_max(uint64_t i) { return maxElement[findSet(i)]; }
    /**
     * @brief A utility function that returns the min element of the set to
     * which i belongs to
     * @param i element of some set
     * @returns minimum of the set to which i belongs to
     */
    uint64_t get_min(uint64_t i) { return minElement[findSet(i)]; }
};

/**
 * @brief Self-test implementations, 1st test
 * @returns void
 */
static void test1() {
    // the minimum, maximum, and size of the set
    uint64_t n = 10;  ///< number of items
    dsu d(n + 1);     ///< object of class disjoint sets
    // set 1
    d.UnionSet(1, 2);  // performs union operation on 1 and 2
    d.UnionSet(1, 4);  // performs union operation on 1 and 4
    vector<uint64_t> ans = {1, 4, 3};
    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.get(4).at(i) == ans[i]);  // makes sure algorithm works fine
    }
    cout << "1st test passed!" << endl;
}
/**
 * @brief Self-implementations, 2nd test
 * @returns void
 */
static void test2() {
    // the minimum, maximum, and size of the set
    uint64_t n = 10;  ///< number of items
    dsu d(n + 1);     ///< object of class disjoint sets
    // set 1
    d.UnionSet(3, 5);
    d.UnionSet(5, 6);
    d.UnionSet(5, 7);
    vector<uint64_t> ans = {3, 7, 4};
    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.get(3).at(i) == ans[i]);  // makes sure algorithm works fine
    }
    cout << "2nd test passed!" << endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 * */
int main() {
    uint64_t n = 10;  ///< number of items
    dsu d(n + 1);     ///< object of class disjoint sets

    test1();  // run 1st test case
    test2();  // run 2nd test case

    return 0;
}

/**
 * @file
 * @brief Union-Find with path compression.
 * @details
 * Tracks a family of disjoint groups over a fixed universe of elements,
 * exposing merge and query operations plus running min/max/size stats
 * per group. The find operation flattens the parent chain as it walks
 * (path compression), so lookups amortize toward O(1).
 * @see dsu_union_rank.cpp
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

using std::cout;
using std::endl;
using std::vector;

/**
 * @brief Disjoint-set forest supporting path-compressed root lookups.
 */
class UnionFindCompressed {
 public:
    /**
     * @brief Build a forest of `count` singleton groups.
     * @param count number of elements to track
     */
    explicit UnionFindCompressed(uint64_t count) {
        owner_.resize(count);
        rank_hint_.resize(count);
        group_count_.resize(count);
        lowest_.resize(count);
        highest_.resize(count);
        for (uint64_t idx = 0; idx < count; idx++) {
            owner_[idx] = idx;
            rank_hint_[idx] = 0;
            group_count_[idx] = 1;
            lowest_[idx] = idx;
            highest_[idx] = idx;
        }
    }

    /**
     * @brief Resolve the root of the group containing `elem`, compressing
     * the path so future lookups are cheaper.
     */
    uint64_t root_of(uint64_t elem) {
        if (owner_[elem] == elem) {
            return elem;
        }
        owner_[elem] = root_of(owner_[elem]);
        return owner_[elem];
    }

    /** @brief True if both elements currently sit in the same group. */
    bool shares_group(uint64_t a, uint64_t b) { return root_of(a) == root_of(b); }

    /**
     * @brief Merge the groups holding `a` and `b`, attaching the
     * lower-ranked root beneath the higher-ranked one.
     */
    void merge(uint64_t a, uint64_t b) {
        if (shares_group(a, b)) {
            return;
        }
        uint64_t root_a = root_of(a);
        uint64_t root_b = root_of(b);

        if (rank_hint_[root_a] > rank_hint_[root_b]) {
            std::swap(root_a, root_b);
        }
        owner_[root_a] = root_b;

        if (rank_hint_[root_a] == rank_hint_[root_b]) {
            rank_hint_[root_b]++;
        }
        group_count_[root_b] += group_count_[root_a];
        highest_[root_b] = std::max(highest_[root_a], highest_[root_b]);
        lowest_[root_b] = std::min(lowest_[root_a], lowest_[root_b]);
    }

    /** @brief Number of elements in the group containing `elem`. */
    uint64_t group_size(uint64_t elem) { return group_count_[root_of(elem)]; }

    /** @brief Largest element in the group containing `elem`. */
    uint64_t group_max(uint64_t elem) { return highest_[root_of(elem)]; }

    /** @brief Smallest element in the group containing `elem`. */
    uint64_t group_min(uint64_t elem) { return lowest_[root_of(elem)]; }

    /** @brief Convenience bundle: {min, max, size} for elem's group. */
    vector<uint64_t> stats_for(uint64_t elem) {
        return {group_min(elem), group_max(elem), group_size(elem)};
    }

 private:
    vector<uint64_t> owner_;       ///< parent pointer per element
    vector<uint64_t> rank_hint_;   ///< approximate tree depth per root
    vector<uint64_t> group_count_; ///< size of the group per root
    vector<uint64_t> highest_;     ///< max element seen per root
    vector<uint64_t> lowest_;      ///< min element seen per root
};

/** @brief First scenario: merge {1,2,4} and inspect group 4's stats. */
static void scenario_small_merge() {
    uint64_t total = 10;
    UnionFindCompressed forest(total + 1);

    forest.merge(1, 2);
    forest.merge(1, 4);

    vector<uint64_t> expected = {1, 4, 3};
    vector<uint64_t> actual = forest.stats_for(4);
    for (uint64_t idx = 0; idx < expected.size(); idx++) {
        assert(actual.at(idx) == expected[idx]);
    }
    cout << "1st test passed!" << endl;
}

/** @brief Second scenario: merge {3,5,6,7} and inspect group 3's stats. */
static void scenario_chain_merge() {
    uint64_t total = 10;
    UnionFindCompressed forest(total + 1);

    forest.merge(3, 5);
    forest.merge(5, 6);
    forest.merge(5, 7);

    vector<uint64_t> expected = {3, 7, 4};
    vector<uint64_t> actual = forest.stats_for(3);
    for (uint64_t idx = 0; idx < expected.size(); idx++) {
        assert(actual.at(idx) == expected[idx]);
    }
    cout << "2nd test passed!" << endl;
}

int main() {
    scenario_small_merge();
    scenario_chain_merge();
    return 0;
}

/**
 * @file
 * @brief [DSU (Disjoint
 * sets)](https://en.wikipedia.org/wiki/Disjoint-set-data_structure)
 * @details
 * dsu : It is a very powerful data structure which keeps track of different
 * clusters(sets) of elements, these sets are disjoint(doesnot have a common
 * element). Disjoint sets uses cases : for finding connected components in a
 * graph, used in Kruskal's algorithm for finding Minimum Spanning tree.
 * Operations that can be performed:
 * 1) UnionSet(i,j): add(element i and j to the set)
 * 2) findSet(i): returns the representative of the set to which i belogngs to.
 * 3) getParents(i): prints the parent of i and so on and so forth.
 * Below is the class-based approach which uses the heuristic of union-ranks.
 * Using union-rank in findSet(i),we are able to get to the representative of i
 * in slightly delayed O(logN) time but it allows us to keep tracks of the
 * parent of i.
 * @author [AayushVyasKIIT](https://github.com/AayushVyasKIIT)
 * @see dsu_path_compression.cpp
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

using std::cout;
using std::endl;
using std::vector;

/**
 * @brief Disjoint sets union data structure, class based representation.
 * @param n number of elements
 */
class dsu {
 private:
    vector<uint64_t> p;        ///< keeps track of the parent of ith element
    vector<uint64_t> depth;    ///< tracks the depth(rank) of i in the tree
    vector<uint64_t> setSize;  ///< size of each chunk(set)
 public:
    /**
     * @brief constructor for initialising all data members
     * @param n number of elements
     */
    explicit dsu(uint64_t n) {
        p.assign(n, 0);
        /// initially all of them are their own parents
        depth.assign(n, 0);
        setSize.assign(n, 0);
        for (uint64_t i = 0; i < n; i++) {
            p[i] = i;
            depth[i] = 0;
            setSize[i] = 1;
        }
    }
    /**
     * @brief Method to find the representative of the set to which i belongs
     * to, T(n) = O(logN)
     * @param i element of some set
     * @returns representative of the set to which i belongs to
     */
    uint64_t findSet(uint64_t i) {
        /// using union-rank
        while (i != p[i]) {
            i = p[i];
        }
        return i;
    }
    /**
     * @brief Method that combines two disjoint sets to which i and j belongs to
     * and make a single set having a common representative.
     * @param i element of some set
     * @param j element of some set
     * @returns void
     */
    void unionSet(uint64_t i, uint64_t j) {
        /// checks if both belongs to same set or not
        if (isSame(i, j)) {
            return;
        }
        /// we find representative of the i and j
        uint64_t x = findSet(i);
        uint64_t y = findSet(j);

        /// always keeping the min as x
        /// in order to create a shallow tree
        if (depth[x] > depth[y]) {
            std::swap(x, y);
        }
        /// making the shallower tree, root parent of the deeper root
        p[x] = y;

        /// if same depth, then increase one's depth
        if (depth[x] == depth[y]) {
            depth[y]++;
        }
        /// total size of the resultant set
        setSize[y] += setSize[x];
    }
    /**
     * @brief A utility function which check whether i and j belongs to same set
     * or not
     * @param i element of some set
     * @param j element of some set
     * @returns `true` if element i and j are in same set
     * @returns `false` if element i and j are not in same set
     */
    bool isSame(uint64_t i, uint64_t j) {
        if (findSet(i) == findSet(j)) {
            return true;
        }
        return false;
    }
    /**
     * @brief Method to print all the parents of i, or the path from i to
     * representative.
     * @param i element of some set
     * @returns void
     */
    vector<uint64_t> getParents(uint64_t i) {
        vector<uint64_t> ans;
        while (p[i] != i) {
            ans.push_back(i);
            i = p[i];
        }
        ans.push_back(i);
        return ans;
    }
};
/**
 * @brief Self-implementations, 1st test
 * @returns void
 */
static void test1() {
    /* checks the parents in the resultant structures */
    uint64_t n = 10;   ///< number of elements
    dsu d(n + 1);      ///< object of class disjoint sets
    d.unionSet(2, 1);  ///< performs union operation on 1 and 2
    d.unionSet(1, 4);
    d.unionSet(8, 1);
    d.unionSet(3, 5);
    d.unionSet(5, 6);
    d.unionSet(5, 7);
    d.unionSet(9, 10);
    d.unionSet(2, 10);
    // keeping track of the changes using parent pointers
    vector<uint64_t> ans = {7, 5};
    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.getParents(7).at(i) ==
               ans[i]);  // makes sure algorithm works fine
    }
    cout << "1st test passed!" << endl;
}
/**
 * @brief Self-implementations, 2nd test
 * @returns void
 */
static void test2() {
    // checks the parents in the resultant structures
    uint64_t n = 10;   ///< number of elements
    dsu d(n + 1);      ///< object of class disjoint sets
    d.unionSet(2, 1);  /// performs union operation on 1 and 2
    d.unionSet(1, 4);
    d.unionSet(8, 1);
    d.unionSet(3, 5);
    d.unionSet(5, 6);
    d.unionSet(5, 7);
    d.unionSet(9, 10);
    d.unionSet(2, 10);

    /// keeping track of the changes using parent pointers
    vector<uint64_t> ans = {2, 1, 10};
    for (uint64_t i = 0; i < ans.size(); i++) {
        assert(d.getParents(2).at(i) ==
               ans[i]);  /// makes sure algorithm works fine
    }
    cout << "2nd test passed!" << endl;
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test1();  // run 1st test case
    test2();  // run 2nd test case

    return 0;
}

/**
 * @file
 * @brief Union-Find (Disjoint Set) using the union-by-rank heuristic.
 * @details
 * Maintains disjoint groups over a fixed universe, merging via rank
 * comparison rather than path compression. find() walks parent links
 * iteratively without rewriting them, so the parent chain can still be
 * inspected afterward (see chain_to_root below).
 * @see dsu_path_compression.cpp
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

using std::cout;
using std::endl;
using std::vector;

/**
 * @brief Disjoint-set forest that merges by rank without path compression.
 */
class RankedUnionFind {
 public:
    explicit RankedUnionFind(uint64_t count) {
        link_.resize(count);
        tier_.resize(count);
        tally_.resize(count);
        for (uint64_t idx = 0; idx < count; idx++) {
            link_[idx] = idx;
            tier_[idx] = 0;
            tally_[idx] = 1;
        }
    }

    /** @brief Walk parent links up to the root, without compressing. */
    uint64_t root_of(uint64_t elem) {
        while (elem != link_[elem]) {
            elem = link_[elem];
        }
        return elem;
    }

    /** @brief True if `a` and `b` currently live in the same group. */
    bool shares_group(uint64_t a, uint64_t b) { return root_of(a) == root_of(b); }

    /** @brief Merge groups by attaching the shallower root under the deeper one. */
    void join(uint64_t a, uint64_t b) {
        if (shares_group(a, b)) {
            return;
        }
        uint64_t root_a = root_of(a);
        uint64_t root_b = root_of(b);

        if (tier_[root_a] > tier_[root_b]) {
            std::swap(root_a, root_b);
        }
        link_[root_a] = root_b;

        if (tier_[root_a] == tier_[root_b]) {
            tier_[root_b]++;
        }
        tally_[root_b] += tally_[root_a];
    }

    /** @brief Path from `elem` up to its root, inclusive of the root. */
    vector<uint64_t> chain_to_root(uint64_t elem) {
        vector<uint64_t> path;
        while (link_[elem] != elem) {
            path.push_back(elem);
            elem = link_[elem];
        }
        path.push_back(elem);
        return path;
    }

 private:
    vector<uint64_t> link_;   ///< parent pointer per element
    vector<uint64_t> tier_;   ///< approximate rank per root
    vector<uint64_t> tally_;  ///< group size per root
};

/** @brief Build the standard test forest of 11 elements (index 0..10). */
static RankedUnionFind build_sample_forest() {
    uint64_t total = 10;
    RankedUnionFind forest(total + 1);
    forest.join(2, 1);
    forest.join(1, 4);
    forest.join(8, 1);
    forest.join(3, 5);
    forest.join(5, 6);
    forest.join(5, 7);
    forest.join(9, 10);
    forest.join(2, 10);
    return forest;
}

/** @brief First scenario: verify the parent chain starting at element 7. */
static void scenario_chain_from_seven() {
    RankedUnionFind forest = build_sample_forest();
    vector<uint64_t> expected = {7, 5};
    vector<uint64_t> actual = forest.chain_to_root(7);
    for (uint64_t idx = 0; idx < expected.size(); idx++) {
        assert(actual.at(idx) == expected[idx]);
    }
    cout << "1st test passed!" << endl;
}

/** @brief Second scenario: verify the parent chain starting at element 2. */
static void scenario_chain_from_two() {
    RankedUnionFind forest = build_sample_forest();
    vector<uint64_t> expected = {2, 1, 10};
    vector<uint64_t> actual = forest.chain_to_root(2);
    for (uint64_t idx = 0; idx < expected.size(); idx++) {
        assert(actual.at(idx) == expected[idx]);
    }
    cout << "2nd test passed!" << endl;
}

int main() {
    scenario_chain_from_seven();
    scenario_chain_from_two();
    return 0;
}

/**
 * @file
 * @brief Implementation of singly linked list algorithm.
 * @details
 * The linked list is a data structure used for holding a sequence of
 * values, which can be added, removed and displayed.
 * ### Algorithm
 * Values can be added by iterating to the end of a list(by following
 * the pointers) starting from the first link. Whichever link points to null
 * is considered the last link and is pointed to the new value.
 *
 * Values can be removed by also iterating through the list. When the node
 * containing the value is found, the node pointing to the current node is made
 * to point to the node that the current node is pointing to, and then returning
 * the current node to heap store.
 */
#include <iostream>
#include <memory>
#include <string>

/**
 * @namespace data_structures
 * @brief Data Structures algorithms
 */
namespace data_structures {

/**
 * @namespace linked_list
 * @brief Functions for singly linked list algorithm
 */
namespace linked_list {

/**
 * This function checks if the string passed consists
 * of only digits.
 * @param s To be checked if s contains only integers
 * @returns true if there are only digits present in the string
 * @returns false if any other character is found
 */
bool isDigit(const std::string& s) {
    // function statements here
    for (char i : s) {
        if (!isdigit(i)) {
            return false;
        }
    }
    return true;
}

/**
 * A link class containing a value and pointer to another link
 */
class link {
 private:
    int pvalue;                   ///< value of the current link
    std::shared_ptr<link> psucc;  ///< pointer to the next value on the list

 public:
    /**
     * function returns the integer value stored in the link.
     * @returns the integer value stored in the link.
     */
    int val() { return pvalue; }

    /**
     * function returns the pointer to next link
     * @returns the pointer to the next link
     * */
    std::shared_ptr<link>& succ() { return psucc; }

    /**
     * Creates link with provided value and pointer to next link
     * @param value is the integer stored in the link
     */
    explicit link(int value = 0) : pvalue(value), psucc(nullptr) {}
};

/**
 * A list class containing a sequence of links
 */
class list {
 private:
    std::shared_ptr<link> first;  ///< link before the actual first element
    std::shared_ptr<link> last;   ///< last link on the list
 public:
    /**
     * List constructor. Initializes the first and last link.
     */
    list() {
        // Initialize the first link
        first = std::make_shared<link>();
        // Initialize the last link with the first link
        last = nullptr;
    }

    bool isEmpty();

    void push_back(int new_elem);
    void push_front(int new_elem);
    void erase(int old_elem);
    void display();
    std::shared_ptr<link> search(int find_elem);
    void reverse();
};

/**
 * function checks if list is empty
 * @returns true if list is empty
 * @returns false if list is not empty
 */
bool list::isEmpty() {
    if (last == nullptr) {
        return true;
    } else {
        return false;
    }
}

/**
 * function adds new element to the end of the list
 * @param new_elem to be added to the end of the list
 */
void list::push_back(int new_elem) {
    if (isEmpty()) {
        first->succ() = std::make_shared<link>(new_elem);
        last = first->succ();
    } else {
        last->succ() = std::make_shared<link>(new_elem);
        last = last->succ();
    }
}

/**
 * function adds new element to the beginning of the list
 * @param new_elem to be added to front of the list
 */
void list::push_front(int new_elem) {
    if (isEmpty()) {
        first->succ() = std::make_shared<link>(new_elem);
        last = first->succ();
    } else {
        std::shared_ptr<link> t = std::make_shared<link>(new_elem);
        t->succ() = first->succ();
        first->succ() = t;
    }
}

/**
 * function erases old element from the list
 * @param old_elem to be erased from the list
 */
void list::erase(int old_elem) {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return;
    }
    std::shared_ptr<link> t = first;
    std::shared_ptr<link> to_be_removed = nullptr;
    while (t != last && t->succ()->val() != old_elem) {
        t = t->succ();
    }
    if (t == last) {
        std::cout << "Element not found\n";
        return;
    }
    to_be_removed = t->succ();
    t->succ() = t->succ()->succ();
    to_be_removed.reset();
    if (t->succ() == nullptr) {
        last = t;
    }
    if (first == last){
        last = nullptr;
    }
}

/**
 * function displays all the elements in the list
 * @returns 'void'
 */
void list::display() {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return;
    }
    std::shared_ptr<link> t = first;
    while (t->succ() != nullptr) {
        std::cout << t->succ()->val() << "\t";
        t = t->succ();
    }
}

/**
 * function searchs for @param find_elem in the list
 * @param find_elem to be searched for in the list
 */
std::shared_ptr<link> list::search(int find_elem) {
    if (isEmpty()) {
        std::cout << "List is Empty!";
        return nullptr;
    }
    std::shared_ptr<link> t = first;
    while (t != last && t->succ()->val() != find_elem) {
        t = t->succ();
    }
    if (t == last) {
        std::cout << "Element not found\n";
        return nullptr;
    }
    std::cout << "Element was found\n";
    return t->succ();
}
}  // namespace linked_list
}  // namespace data_structures

/**
 * Main function:
 * Allows the user add and delete values from the list.
 * Also allows user to search for and display values in the list.
 * @returns 0 on exit
 */
int main() {
    data_structures::linked_list::list l;
    int choice = 0;
    int x = 0;
    std::string s;
    do {
        std::cout << "\n1. Insert";
        std::cout << "\n2. Delete";
        std::cout << "\n3. Search";
        std::cout << "\n4. Print";
        std::cout << "\n0. Exit";
        std::cout << "\n\nEnter you choice : ";
        std::cin >> choice;
        switch (choice) {
            case 0:
                std::cout << "\nQuitting the program...\n";
                break;
            case 1:
                std::cout << "\nEnter the element to be inserted : ";
                std::cin >> s;

                if (data_structures::linked_list::isDigit(s)) {
                    x = std::stoi(s);
                    l.push_back(x);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 2:
                std::cout << "\nEnter the element to be removed : ";
                std::cin >> s;
                if (data_structures::linked_list::isDigit(s)) {
                    x = std::stoi(s);
                    l.erase(x);
                } else {
                    std::cout << "Wrong Input!\n";
                }
                break;
            case 3:
                std::cout << "\nEnter the element to be searched : ";
                std::cin >> s;
                if (data_structures::linked_list::isDigit(s)) {
                    x = std::stoi(s);
