/**
 * \file
 * \brief Linked list implementation using Arrays
 *
 * The difference between the pointer implementation of linked list and array
 * implementation of linked list:
 * 1. The NULL is represented by -1;
 * 2. Limited size. (in the following case it is 100 nodes at max). But we can
 * reuse the nodes that are to be deleted by again linking it bacj to the list.
 */

#include <iostream>

struct Node {
    int data;
    int next;
};

Node AvailArray[100];  ///< array that will act as nodes of a linked list.

int head = -1;
int avail = 0;
void initialise_list() {
    for (int i = 0; i <= 98; i++) {
        AvailArray[i].next = i + 1;
    }
    AvailArray[99].next = -1;  // indicating the end of the linked list.
}

/** This will return the index of the first free node present in the avail list
 */
int getnode() {
    int NodeIndexToBeReturned = avail;
    avail = AvailArray[avail].next;
    return NodeIndexToBeReturned;
}

/** This function when called will delete the node with
 * the index presented as an argument, and will put
 * back that node into the array.
 */
void freeNode(int nodeToBeDeleted) {
    AvailArray[nodeToBeDeleted].next = avail;
    avail = nodeToBeDeleted;
}

/** The function will insert the given data
 * into the front of the linked list.
 */
void insertAtTheBeginning(int data) {
    int newNode = getnode();
    AvailArray[newNode].data = data;
    AvailArray[newNode].next = head;
    head = newNode;
}

void insertAtTheEnd(int data) {
    int newNode = getnode();
    int temp = head;
    while (AvailArray[temp].next != -1) {
        temp = AvailArray[temp].next;
    }
    // temp is now pointing to the end node.
    AvailArray[newNode].data = data;
    AvailArray[newNode].next = -1;
    AvailArray[temp].next = newNode;
}

void display() {
    int temp = head;
    while (temp != -1) {
        std::cout << AvailArray[temp].data << "->";
        temp = AvailArray[temp].next;
    }
    std::cout << "-1" << std::endl;
}

/** Main function */
int main() {
    initialise_list();
    int x, y, z;
    for (;;) {
        std::cout << "1. Insert At The Beginning" << std::endl;
        std::cout << "2. Insert At The End" << std::endl;
        std::cout << "3. Display" << std::endl;
        std::cout << "4.Exit" << std::endl;
        std::cout << "Enter Your choice" << std::endl;
        std::cin >> z;
        switch (z) {
        case 1:
            std::cout << "Enter the number you want to enter" << std::endl;
            std::cin >> x;
            insertAtTheBeginning(x);
            break;
        case 2:
            std::cout << "Enter the number you want to enter" << std::endl;
            std::cin >> y;
            insertAtTheEnd(y);
            break;
        case 3:
            std::cout
                << "The linked list contains the following element in order"
                << std::endl;
            display();
            break;
        case 4:
            return 0;
        default:
            std::cout << "The entered choice is not correct" << std::endl;
        }
    }

    return 0;
}

/**
 * \file
 * \brief Array-backed singly linked list.
 *
 * Instead of allocating nodes on the heap and chaining them with real
 * pointers, this version keeps a fixed-capacity pool of "slots" and links
 * them together using integer indices:
 *   - an index value of -1 plays the role of a null pointer
 *   - capacity is capped (here, 100 slots), but freed slots are recycled
 *     via a free-list so the pool can be reused after deletions.
 */

#include <iostream>

struct Slot {
    int value;
    int nextIdx;
};

Slot pool[100];  ///< backing storage that emulates heap-allocated nodes

int headIdx = -1;
int freeHead = 0;

/// Wires up the free-list so every slot points to the next unused slot.
void setupPool() {
    for (int idx = 0; idx < 99; ++idx) {
        pool[idx].nextIdx = idx + 1;
    }
    pool[99].nextIdx = -1;  // last slot terminates the free-list
}

/// Pops one slot off the free-list and hands its index back to the caller.
int claimSlot() {
    int claimed = freeHead;
    freeHead = pool[freeHead].nextIdx;
    return claimed;
}

/// Returns a slot to the free-list so it can be reused later.
void releaseSlot(int idx) {
    pool[idx].nextIdx = freeHead;
    freeHead = idx;
}

/// Prepends a value to the front of the list.
void pushFront(int value) {
    int idx = claimSlot();
    pool[idx].value = value;
    pool[idx].nextIdx = headIdx;
    headIdx = idx;
}

/// Appends a value to the tail of the list.
void pushBack(int value) {
    int idx = claimSlot();
    if (headIdx == -1) {
        pool[idx].value = value;
        pool[idx].nextIdx = -1;
        headIdx = idx;
        return;
    }
    int walker = headIdx;
    while (pool[walker].nextIdx != -1) {
        walker = pool[walker].nextIdx;
    }
    pool[idx].value = value;
    pool[idx].nextIdx = -1;
    pool[walker].nextIdx = idx;
}

/// Prints every element from head to tail.
void printAll() {
    int walker = headIdx;
    while (walker != -1) {
        std::cout << pool[walker].value << "->";
        walker = pool[walker].nextIdx;
    }
    std::cout << "-1" << std::endl;
}

int main() {
    setupPool();
    int inputA, inputB, menuChoice;
    while (true) {
        std::cout << "1. Insert At The Beginning" << std::endl;
        std::cout << "2. Insert At The End" << std::endl;
        std::cout << "3. Display" << std::endl;
        std::cout << "4.Exit" << std::endl;
        std::cout << "Enter Your choice" << std::endl;
        std::cin >> menuChoice;

        if (menuChoice == 1) {
            std::cout << "Enter the number you want to enter" << std::endl;
            std::cin >> inputA;
            pushFront(inputA);
        } else if (menuChoice == 2) {
            std::cout << "Enter the number you want to enter" << std::endl;
            std::cin >> inputB;
            pushBack(inputB);
        } else if (menuChoice == 3) {
            std::cout
                << "The linked list contains the following element in order"
                << std::endl;
            printAll();
        } else if (menuChoice == 4) {
            return 0;
        } else {
            std::cout << "The entered choice is not correct" << std::endl;
        }
    }

    return 0;
}

/**
 * @file
 * @brief [Dynamic Array](https://en.wikipedia.org/wiki/Dynamic_array)
 *
 * @details
 * The list_array is the implementation of list represented using array.
 * We can perform basic CRUD operations as well as other operations like sorting
 * etc.
 *
 * ### Algorithm
 * It implements various method like insert, sort, search etc. efficiently.
 * You can select the operation and methods will do the rest work for you.
 * You can insert element, sort them in order, search efficiently, delete values
 * and print the list.
 */

#include <array>     /// for std::array
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for io operations

/**
 * @namespace data_structures
 * @brief Algorithms with data structures
 */
namespace data_structures {
/**
 * @namespace list_array
 * @brief Functions for [Dynamic
 * Array](https://en.wikipedia.org/wiki/Dynamic_array) algorithm
 */
namespace list_array {
/**
 * @brief Structure of List with supporting methods.
 */
template <uint64_t N>
struct list {
    std::array<uint64_t, N> data{};  // Array that implement list
    uint64_t top = 0;                // Pointer to the last element
    bool isSorted = false;           // indicator whether list is sorted or not
    /**
     * @brief Search an element in the list using binarySearch.
     * @param dataArr list
     * @param first pointer to the first element in the remaining list
     * @param last pointer to the last element in the remaining list
     * @param val element that will be searched
     * @return index of element in the list if present else -1
     */
    uint64_t BinarySearch(const std::array<uint64_t, N> &dataArr,
                          const uint64_t &first, const uint64_t &last,
                          const uint64_t &val) {
        // If both pointer cross each other means no element present in the list
        // which is equal to the val
        if (last < first) {
            return -1;
        }
        uint64_t mid = (first + last) / 2;
        // check whether current mid pointer value is equal to element or not
        if (dataArr[mid] == val)
            return mid;
        // if current mid value is greater than  element we have to search in
        // first half
        else if (val < dataArr[mid])
            return (BinarySearch(dataArr, first, mid - 1, val));
        // if current mid value is greater than  element we have to search in
        // second half
        else if (val > dataArr[mid])
            return (BinarySearch(dataArr, mid + 1, last, val));

        std::cerr << __func__ << ":" << __LINE__ << ": Undefined condition\n";
        return -1;
    }

    /**
     * @brief Search an element using linear search
     * @param dataArr list
     * @param val element that will be searched
     * @return index of element in the list if present else -1
     */
    uint64_t LinearSearch(const std::array<uint64_t, N> &dataArr,
                          const uint64_t &val) const {
        // Going through each element in the list
        for (uint64_t i = 0; i < top; i++) {
            if (dataArr[i] == val) {
                return i;  // element found at ith index
            }
        }
        // element is not present in the list
        return -1;
    }

    /*
     * @brief Parent function of binarySearch and linearSearch methods
     * @param val element that will be searched
     * @return index of element in the list if present else -1
     */
    uint64_t search(const uint64_t &val) {
        uint64_t pos;  // pos variable to store index value of element.
        // if list is sorted, binary search works efficiently else linear search
        // is the only option
        if (isSorted) {
            pos = BinarySearch(data, 0, top - 1, val);
        } else {
            pos = LinearSearch(data, val);
        }
        // if index is equal to -1 means element does not present
        // else print the index of that element
        if (pos != -1) {
            std::cout << "\nElement found at position : " << pos;
        } else {
            std::cout << "\nElement not found";
        }
        // return the index of element or -1.
        return pos;
    }

    /**
     * @brief Sort the list
     * @returns void
     */
    void sort() {
        // Going through each element in the list
        for (uint64_t i = 0; i < top; i++) {
            uint64_t min_idx = i;  // Initialize the min variable
            for (uint64_t j = i + 1; j < top; j++) {
                // check whether any element less than current min value
                if (data[j] < data[min_idx]) {
                    min_idx = j;  // update index accordingly
                }
            }
            // swap min value and element at the ith index
            std::swap(data[min_idx], data[i]);
        }
        // mark isSorted variable as true
        isSorted = true;
    }

    /**
     * @brief Insert the new element in the list
     * @param val element that will be inserted
     * @returns void
     */
    void insert(const uint64_t &val) {
        // overflow check
        if (top == N) {
            std::cout << "\nOverflow";
            return;
        }
        // if list is not sorted, insert at the last
        // otherwise place it to correct position
        if (!isSorted) {
            data[top] = val;
            top++;
        } else {
            uint64_t pos = 0;  // Initialize the index variable
            // Going through each element and find correct position for element
            for (uint64_t i = 0; i < top - 1; i++) {
                // check for the correct position
                if (data[i] <= val && val <= data[i + 1]) {
                    pos = i + 1;  // assign correct pos to the index var
                    break;        // to get out from the loop
                }
            }
            // if all elements are smaller than the element
            if (pos == 0) {
                pos = top - 1;
            }
            // shift all element to make a room for new element
            for (uint64_t i = top; i > pos; i--) {
                data[i] = data[i - 1];
            }
            top++;  // Increment the value of top.
            data[pos] =
                val;  // Assign the value to the correct index in the array
        }
    }

    /**
     * @brief To remove the element from the list
     * @param val element that will be removed
     * @returns void
     */
    void remove(const uint64_t &val) {
        uint64_t pos = search(val);  // search the index of the value
        // if search returns -1, element does not present in the list
        if (pos == -1) {
            std::cout << "\n Element does not present in the list ";
            return;
        }
        std::cout << "\n"
                  << data[pos] << " deleted";  // print the appropriate message
        // shift all the element 1 left to fill vacant space
        for (uint64_t i = pos; i < top; i++) {
            data[i] = data[i + 1];
        }
        top--;  // decrement the top variable to maintain last index
    }

    /**
     * @brief Utility function to print array
     * @returns void
     */
    void show() {
        // Going through each element in the list
        std::cout << '\n';
        for (uint64_t i = 0; i < top; i++) {
            std::cout << data[i] << " ";  // print the element
        }
    }
};  // structure list
}  // namespace list_array
}  // namespace data_structures

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    data_structures::list_array::list<50> L;

    // Insert testing
    L.insert(11);
    L.insert(12);
    assert(L.top == 2);
    L.insert(15);
    L.insert(10);
    L.insert(12);
    L.insert(20);
    L.insert(18);
    assert(L.top == 7);
    L.show();  // To print the array

    // Remove testing
    L.remove(12);  // Remove Duplicate value in the list
    L.remove(15);  // Remove the existing value in the list
    assert(L.top == 5);
    L.remove(50);  // Try to remove the non-existing value in the list
    assert(L.top == 5);

    // LinearSearch testing
    assert(L.search(11) == 0);  // search for the existing element
    assert(L.search(12) == 2);
    assert(L.search(50) == -1);  // search for the non-existing element

    // Sort testing
    L.sort();
    assert(L.isSorted == true);
    L.show();

    // BinarySearch testing
    assert(L.search(11) == 1);  // search for the existing element
    assert(L.search(12) == 2);
    assert(L.search(50) == -1);  // search for the non-existing element
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // Execute the tests
    return 0;
}

/**
 * @file
 * @brief Fixed-capacity array-backed list with CRUD-style operations.
 *
 * @details
 * This is a bounded-capacity list built on top of std::array. It supports
 * insertion (kept sorted or unsorted), searching (linear or binary,
 * depending on current sortedness), removal, sorting, and printing.
 */

#include <array>     /// for std::array
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for io operations

/**
 * @namespace data_structures
 * @brief Algorithms with data structures
 */
namespace data_structures {
/**
 * @namespace list_array
 * @brief Bounded array-backed list container and its operations.
 */
namespace list_array {

/**
 * @brief Fixed-capacity list container backed by a std::array.
 */
template <uint64_t Capacity>
struct BoundedList {
    std::array<uint64_t, Capacity> slots{};  // underlying storage
    uint64_t count = 0;                      // number of elements currently stored
    bool sorted = false;                     // whether slots[0..count) is ordered

    /**
     * @brief Recursive binary search over a sorted sub-range.
     * @param storage backing array to search within
     * @param lo lower bound index of the remaining range
     * @param hi upper bound index of the remaining range
     * @param target value being searched for
     * @return index of target if found, otherwise -1 (as uint64_t)
     */
    uint64_t binarySearchRange(const std::array<uint64_t, Capacity> &storage,
                               const uint64_t &lo, const uint64_t &hi,
                               const uint64_t &target) {
        // Ranges have crossed: nothing left to inspect.
        if (hi < lo) {
            return -1;
        }
        uint64_t mid = (lo + hi) / 2;
        if (storage[mid] == target) {
            return mid;
        }
        if (target < storage[mid]) {
            return binarySearchRange(storage, lo, mid - 1, target);
        }
        if (target > storage[mid]) {
            return binarySearchRange(storage, mid + 1, hi, target);
        }

        std::cerr << __func__ << ":" << __LINE__ << ": Undefined condition\n";
        return -1;
    }

    /**
     * @brief Scans every stored element in order looking for target.
     * @param storage backing array to search within
     * @param target value being searched for
     * @return index of target if found, otherwise -1 (as uint64_t)
     */
    uint64_t linearSearchRange(const std::array<uint64_t, Capacity> &storage,
                               const uint64_t &target) const {
        for (uint64_t idx = 0; idx < count; ++idx) {
            if (storage[idx] == target) {
                return idx;
            }
        }
        return -1;
    }

    /**
     * @brief Picks a search strategy based on current sortedness and reports
     * the outcome.
     * @param target value being searched for
     * @return index of target if found, otherwise -1 (as uint64_t)
     */
    uint64_t locate(const uint64_t &target) {
        uint64_t foundAt;
        if (sorted) {
            foundAt = binarySearchRange(slots, 0, count - 1, target);
        } else {
            foundAt = linearSearchRange(slots, target);
        }
        if (foundAt != -1) {
            std::cout << "\nElement found at position : " << foundAt;
        } else {
            std::cout << "\nElement not found";
        }
        return foundAt;
    }

    /**
     * @brief Sorts the active region of the list via selection sort.
     */
    void sortAscending() {
        for (uint64_t i = 0; i < count; ++i) {
            uint64_t smallestAt = i;
            for (uint64_t j = i + 1; j < count; ++j) {
                if (slots[j] < slots[smallestAt]) {
                    smallestAt = j;
                }
            }
            std::swap(slots[smallestAt], slots[i]);
        }
        sorted = true;
    }

    /**
     * @brief Adds a value to the list, preserving order if already sorted.
     * @param value element to add
     */
    void addValue(const uint64_t &value) {
        if (count == Capacity) {
            std::cout << "\nOverflow";
            return;
        }
        if (!sorted) {
            slots[count] = value;
            ++count;
            return;
        }

        uint64_t insertAt = 0;
        for (uint64_t i = 0; i < count - 1; ++i) {
            if (slots[i] <= value && value <= slots[i + 1]) {
                insertAt = i + 1;
                break;
            }
        }
        if (insertAt == 0) {
            insertAt = count - 1;
        }
        for (uint64_t i = count; i > insertAt; --i) {
            slots[i] = slots[i - 1];
        }
        ++count;
        slots[insertAt] = value;
    }

    /**
     * @brief Removes the first occurrence of value from the list.
     * @param value element to remove
     */
    void removeValue(const uint64_t &value) {
        uint64_t at = locate(value);
        if (at == -1) {
            std::cout << "\n Element does not present in the list ";
            return;
        }
        std::cout << "\n" << slots[at] << " deleted";
        for (uint64_t i = at; i < count; ++i) {
            slots[i] = slots[i + 1];
        }
        --count;
    }

    /**
     * @brief Prints every currently stored element.
     */
    void printAll() {
        std::cout << '\n';
        for (uint64_t idx = 0; idx < count; ++idx) {
            std::cout << slots[idx] << " ";
        }
    }
};  // struct BoundedList

}  // namespace list_array
}  // namespace data_structures

/**
 * @brief Exercises BoundedList operations and validates results via assert.
 */
static void runChecks() {
    data_structures::list_array::BoundedList<50> roster;

    // insertion checks
    roster.addValue(11);
    roster.addValue(12);
    assert(roster.count == 2);
    roster.addValue(15);
    roster.addValue(10);
    roster.addValue(12);
    roster.addValue(20);
    roster.addValue(18);
    assert(roster.count == 7);
    roster.printAll();

    // removal checks
    roster.removeValue(12);  // duplicate entry
    roster.removeValue(15);  // existing entry
    assert(roster.count == 5);
    roster.removeValue(50);  // absent entry, no-op
    assert(roster.count == 5);

    // unsorted (linear) search checks
    assert(roster.locate(11) == 0);
    assert(roster.locate(12) == 2);
    assert(roster.locate(50) == -1);

    // sort, then re-check via binary search
    roster.sortAscending();
    assert(roster.sorted == true);
    roster.printAll();

    assert(roster.locate(11) == 1);
    assert(roster.locate(12) == 2);
    assert(roster.locate(50) == -1);
}

/**
 * @brief Entry point that runs the checks above.
 */
int main() {
    runChecks();
    return 0;
}

#include <iostream>
#include <queue>

/**************************
    @author shrutisheoran
**************************/

using namespace std;

struct Btree {
    int data;
    struct Btree *left;   // Pointer to left subtree
    struct Btree *right;  // Pointer to right subtree
};

void insert(Btree **root, int d) {
    Btree *nn = new Btree();  // Creating new node
    nn->data = d;
    nn->left = NULL;
    nn->right = NULL;
    if (*root == NULL) {
        *root = nn;
        return;
    } else {
        queue<Btree *> q;
        // Adding root node to queue
        q.push(*root);
        while (!q.empty()) {
            Btree *node = q.front();
            // Removing parent node from queue
            q.pop();
            if (node->left)
                // Adding left child of removed node to queue
                q.push(node->left);
            else {
                // Adding new node if no left child is present
                node->left = nn;
                return;
            }
            if (node->right)
                // Adding right child of removed node to queue
                q.push(node->right);
            else {
                // Adding new node if no right child is present
                node->right = nn;
                return;
            }
        }
    }
}

void morrisInorder(Btree *root) {
    Btree *curr = root;
    Btree *temp;
    while (curr) {
        if (curr->left == NULL) {
            cout << curr->data << " ";
            // If left of current node is NULL then curr is shifted to right
            curr = curr->right;
        } else {
            // Left of current node is stored in temp
            temp = curr->left;
            // Moving to extreme right of temp
            while (temp->right && temp->right != curr) temp = temp->right;
            // If extreme right is null it is made to point to currrent node
            // (will be used for backtracking)
            if (temp->right == NULL) {
                temp->right = curr;
                // current node is made to point its left subtree
                curr = curr->left;
            }
            // If extreme right already points to currrent node it it set to
            // null
            else if (temp->right == curr) {
                cout << curr->data << " ";
                temp->right = NULL;
                // current node is made to point its right subtree
                curr = curr->right;
            }
        }
    }
}

void deleteAll(const Btree *const root) {
    if (root) {
        deleteAll(root->left);
        deleteAll(root->right);
        delete root;
    }
}

int main() {
    // Testing morrisInorder funtion
    Btree *root = NULL;
    int i;
    for (i = 1; i <= 7; i++) insert(&root, i);
    cout << "Morris Inorder: ";
    morrisInorder(root);
    deleteAll(root);
    return 0;
}

#include <iostream>
#include <queue>

/**************************
    Threaded inorder traversal without recursion or a stack,
    rebuilt with renamed helpers.
**************************/

using namespace std;

struct TreeNode {
    int value;
    struct TreeNode *left;
    struct TreeNode *right;
};

/// Inserts value into the tree level-by-level, filling the first available
/// left/right slot found via BFS (keeps the tree roughly complete).
void insertLevelOrder(TreeNode **rootPtr, int value) {
    TreeNode *freshNode = new TreeNode();
    freshNode->value = value;
    freshNode->left = NULL;
    freshNode->right = NULL;

    if (*rootPtr == NULL) {
        *rootPtr = freshNode;
        return;
    }

    queue<TreeNode *> pending;
    pending.push(*rootPtr);
    while (!pending.empty()) {
        TreeNode *current = pending.front();
        pending.pop();

        if (current->left) {
            pending.push(current->left);
        } else {
            current->left = freshNode;
            return;
        }

        if (current->right) {
            pending.push(current->right);
        } else {
            current->right = freshNode;
            return;
        }
    }
}

/// Performs Morris inorder traversal: temporarily threads the tree using
/// otherwise-unused right pointers instead of recursion or an explicit stack.
void morrisInorderWalk(TreeNode *root) {
    TreeNode *cursor = root;
    TreeNode *predecessor;

    while (cursor) {
        if (cursor->left == NULL) {
            cout << cursor->value << " ";
            cursor = cursor->right;
            continue;
        }

        predecessor = cursor->left;
        while (predecessor->right && predecessor->right != cursor) {
            predecessor = predecessor->right;
        }

        if (predecessor->right == NULL) {
            // Create the temporary thread back to cursor for later backtracking.
            predecessor->right = cursor;
            cursor = cursor->left;
        } else {
            // Thread already exists: visit cursor, remove the thread, move right.
            cout << cursor->value << " ";
            predecessor->right = NULL;
            cursor = cursor->right;
        }
    }
}

/// Recursively frees every node in the tree.
void destroyTree(const TreeNode *const node) {
    if (node) {
        destroyTree(node->left);
        destroyTree(node->right);
        delete node;
    }
}

int main() {
    TreeNode *root = NULL;
    for (int n = 1; n <= 7; n++) {
        insertLevelOrder(&root, n);
    }
    cout << "Morris Inorder: ";
    morrisInorderWalk(root);
    destroyTree(root);
    return 0;
}

/**
 * @file
 * @brief Implementation of Linear [Queue using array]
 * (https://www.geeksforgeeks.org/array-implementation-of-queue-simple/).
 * @details
 * The Linear Queue is a data structure used for holding a sequence of
 * values, which can be added to the end line (enqueue), removed from
 * head of line (dequeue) and displayed.
 * ### Algorithm
 * Values can be added by increasing the `rear` variable by 1 (which points to
 * the end of the array), then assigning new value to `rear`'s element of the
 * array.
 *
 * Values can be removed by increasing the `front` variable by 1 (which points
 * to the first of the array), so it cannot reached any more.
 *
 * @author [Pooja](https://github.com/pooja-git11)
 * @author [Farbod Ahmadian](https://github.com/farbodahm)
 */
#include <array>     /// for std::array
#include <cstdint>
#include <iostream>  /// for io operations

constexpr uint16_t max_size{10};  ///< Maximum size of the queue

/**
 * @namespace data_structures
 * @brief Algorithms with data structures
 */
namespace data_structures {

/**
 * @namespace queue_using_array
 * @brief Functions for [Queue using Array]
 * (https://www.geeksforgeeks.org/array-implementation-of-queue-simple/)
 * implementation.
 */
namespace queue_using_array {

/**
 * @brief Queue_Array class containing the main data and also index of head and
 * tail of the array.
 */
class Queue_Array {
 public:
    void enqueue(const int16_t&);  ///< Add element to the first of the queue
    int dequeue();                 ///< Delete element from back of the queue
    void display() const;          ///< Show all saved data
 private:
    int8_t front{-1};                     ///< Index of head of the array
    int8_t rear{-1};                      ///< Index of tail of the array
    std::array<int16_t, max_size> arr{};  ///< All stored data
};

/**
 * @brief Adds new element to the end of the queue
 * @param ele to be added to the end of the queue
 */
void Queue_Array::enqueue(const int16_t& ele) {
    if (rear == arr.size() - 1) {
        std::cout << "\nStack is full";
    } else if (front == -1 && rear == -1) {
        front = 0;
        rear = 0;
        arr[rear] = ele;
    } else if (rear < arr.size()) {
        ++rear;
        arr[rear] = ele;
    }
}

/**
 * @brief Remove element that is located at the first of the queue
 * @returns data that is deleted if queue is not empty
 */
int Queue_Array::dequeue() {
    int8_t d{0};
    if (front == -1) {
        std::cout << "\nstack is empty ";
        return 0;
    } else if (front == rear) {
        d = arr.at(front);
        front = rear = -1;
    } else {
        d = arr.at(front++);
    }

    return d;
}

/**
 * @brief Utility function to show all elements in the queue
 */
void Queue_Array::display() const {
    if (front == -1) {
        std::cout << "\nStack is empty";
    } else {
        for (int16_t i{front}; i <= rear; ++i) std::cout << arr.at(i) << " ";
    }
}

}  // namespace queue_using_array
}  // namespace data_structures

