/**
 * @file
 * @brief Alternate implementation of a linear queue backed by a fixed array.
 * @details
 * A bounded FIFO queue where `tailIdx` marks the last occupied slot and
 * `headIdx` marks the first. Enqueue advances `tailIdx`; dequeue advances
 * `headIdx`, leaving earlier slots permanently behind (no wraparound).
 *
 * Rewritten variant of the classic array-backed queue exercise.
 */
#include <array>     /// for std::array
#include <cstdint>
#include <iostream>  /// for io operations

constexpr uint16_t kCapacity{10};  ///< maximum number of elements the queue holds

/**
 * @namespace data_structures
 * @brief Algorithms with data structures
 */
namespace data_structures {

/**
 * @namespace queue_using_array
 * @brief Array-backed bounded queue implementation.
 */
namespace queue_using_array {

/**
 * @brief Bounded FIFO queue built on a std::array with explicit head/tail
 * indices.
 */
class BoundedQueue {
 public:
    void enqueue(const int16_t&);  ///< push a value onto the back
    int dequeue();                 ///< pop and return the front value
    void display() const;          ///< print all currently queued values
 private:
    int8_t headIdx{-1};                     ///< index of the front element
    int8_t tailIdx{-1};                      ///< index of the back element
    std::array<int16_t, kCapacity> storage{};  ///< backing storage
};

/**
 * @brief Pushes a new value to the back of the queue if there is room.
 */
void BoundedQueue::enqueue(const int16_t& value) {
    if (tailIdx == storage.size() - 1) {
        std::cout << "\nStack is full";
        return;
    }
    if (headIdx == -1 && tailIdx == -1) {
        headIdx = 0;
        tailIdx = 0;
        storage[tailIdx] = value;
        return;
    }
    if (tailIdx < storage.size()) {
        ++tailIdx;
        storage[tailIdx] = value;
    }
}

/**
 * @brief Pops the front value, if any, and returns it.
 */
int BoundedQueue::dequeue() {
    int8_t popped{0};
    if (headIdx == -1) {
        std::cout << "\nstack is empty ";
        return 0;
    }
    if (headIdx == tailIdx) {
        popped = storage.at(headIdx);
        headIdx = tailIdx = -1;
    } else {
        popped = storage.at(headIdx++);
    }
    return popped;
}

/**
 * @brief Prints all elements currently between head and tail, inclusive.
 */
void BoundedQueue::display() const {
    if (headIdx == -1) {
        std::cout << "\nStack is empty";
        return;
    }
    for (int16_t i{headIdx}; i <= tailIdx; ++i) {
        std::cout << storage.at(i) << " ";
    }
}

}  // namespace queue_using_array
}  // namespace data_structures

