// Simple global-array queue with compaction-on-dequeue instead of
// wraparound indices.
int buffer[10];
int headPos = 0;
int tailPos = 0;

void enqueueValue(int value) {
    if (tailPos == 10) {
        std::cout << "\nOverflow";
        return;
    }
    buffer[tailPos++] = value;
}

void dequeueValue() {
    if (headPos == tailPos) {
        std::cout << "\nUnderflow";
        return;
    }

    std::cout << "\n" << buffer[headPos++] << " deleted";
    // Shift remaining elements down so headPos can reset to 0.
    for (int i = headPos; i < tailPos; i++) {
        buffer[i - headPos] = buffer[i];
    }
    tailPos = tailPos - headPos;
    headPos = 0;
}

void printQueue() {
    for (int i = headPos; i < tailPos; i++) {
        std::cout << buffer[i] << "\t";
    }
}

