#include <iostream>
using namespace std;

// Queue built on a singly linked list, tracked via raw head/tail pointers.
struct ListCell {
    int val;
    ListCell *next;
};

ListCell *head, *tail;

void enqueueValue(int x) {
    ListCell *fresh = new ListCell;
    fresh->val = x;
    fresh->next = NULL;

    if (tail == NULL) {
        // Queue was empty: the new cell becomes both ends.
        head = fresh;
        tail = fresh;
    } else {
        tail->next = fresh;
        tail = fresh;
    }
}

void dequeueValue() {
    if (tail == NULL && head == NULL) {
        cout << "\nUnderflow";
        return;
    }

    ListCell *victim = head;
    cout << "\n" << victim->val << " deleted";
    head = head->next;
    delete victim;
    if (head == NULL) {
        tail = NULL;
    }
}

void printQueue() {
    ListCell *cursor = head;
    while (cursor != NULL) {
        cout << cursor->val << "\t";
        cursor = cursor->next;
    }
}

