        cin >> choice;

        if (choice == 1) {
            cout << "\nInsert : ";
            cin >> value;
            enqueueValue(value);
        } else if (choice == 2) {
            dequeueValue();
        } else if (choice == 3) {
            printQueue();
        }
    } while (choice != 0);

    return 0;
}

