/**
 * @file
 * @brief A prefix-tree (trie) built on top of hash maps, supporting insert,
 * lookup, prefix queries, deletion, and prefix-based word suggestions.
 * @details Rather than a fixed-size array of child pointers per node, this
 * variant keeps an unordered_map from character to child node, which keeps
 * memory usage proportional to the actual branching factor observed rather
 * than the full alphabet size. Shared pointers manage node lifetimes.
 */
#include <cassert>        /// for assert
#include <iostream>       /// for IO operations
#include <memory>         /// for std::shared_ptr
#include <stack>          /// for std::stack
#include <unordered_map>  /// for std::unordered_map
#include <vector>         /// for std::vector

/**
 * @namespace data_structures
 * @brief Data structures algorithms
 */
namespace data_structures {

/**
 * @namespace trie_using_hashmap
 * @brief Hashmap-backed trie implementation
 */
namespace trie_using_hashmap {

/**
 * @brief A prefix tree whose nodes store their children in a hash map keyed
 * by character, allowing insertion, membership tests, prefix tests, removal,
 * and prefix-based auto-completion.
 */
class PrefixTree {
 private:
    /**
     * @brief A single node of the tree, holding links to children and a
     * flag marking whether a word terminates here.
     */
    struct TreeNode {
        std::unordered_map<char16_t, std::shared_ptr<TreeNode>>
            links;  ///< maps a character to the corresponding child node
        bool terminal = false;  ///< true when a full word ends at this node
    };

    std::shared_ptr<TreeNode> head_ =
        std::make_shared<TreeNode>();  ///< sentinel root of the tree

    /**
     * @brief Walks down the tree following the characters of a given key.
     * @param key the string whose path should be followed
     * @returns the node reached, or nullptr if the path does not exist
     */
    std::shared_ptr<TreeNode> walk(const std::string& key) const {
        std::shared_ptr<TreeNode> cursor = head_;
        for (char letter : key) {
            auto found = cursor->links.find(letter);
            if (found == cursor->links.end()) {
                return nullptr;
            }
            cursor = found->second;
        }
        return cursor;
    }

    /**
     * @brief Recursively gathers every complete word reachable below a node,
     * reconstructing each word by appending characters along the path.
     * @param node current position in the tree
     * @param built the characters accumulated so far to reach `node`
     * @param out accumulator collecting every discovered word
     */
    void collect_words(const std::shared_ptr<TreeNode>& node,
                        std::string built,
                        std::vector<std::string>* out) const {
        if (node->terminal) {
            out->push_back(built);
        }
        for (auto const& entry : node->links) {
            collect_words(entry.second, built + std::string(1, entry.first),
                          out);
        }
    }

 public:
    PrefixTree() = default;

    /**
     * @brief Adds a word to the tree, creating any missing nodes along the
     * way and marking the final node as a terminal word.
     * @param word the word to store
     */
    void insert(const std::string& word) {
        std::shared_ptr<TreeNode> cursor = head_;
        for (char letter : word) {
            if (cursor->links.find(letter) == cursor->links.end()) {
                cursor->links[letter] = std::make_shared<TreeNode>();
            }
            cursor = cursor->links[letter];
        }
        if (cursor != head_) {
            cursor->terminal = true;
        }
    }

    /**
     * @brief Checks whether an exact word has been stored in the tree.
     * @param word candidate word to look up
     * @returns true if the word was previously inserted, false otherwise
     */
    bool search(const std::string& word) {
        std::shared_ptr<TreeNode> cursor = walk(word);
        return cursor != nullptr && cursor->terminal;
    }

    /**
     * @brief Checks whether any stored word begins with the given prefix.
     * @param prefix candidate prefix
     * @returns true if the prefix path exists in the tree
     */
    bool startwith(const std::string& prefix) {
        return walk(prefix) != nullptr;
    }

    /**
     * @brief Removes a word from the tree, pruning any nodes that become
     * unreachable dead ends once the word is gone.
     * @param word the word to remove
     */
    void delete_word(std::string word) {
        std::shared_ptr<TreeNode> cursor = head_;
        std::stack<std::shared_ptr<TreeNode>> path;
        for (char letter : word) {
            auto found = cursor->links.find(letter);
            if (found == cursor->links.end()) {
                return;
            }
            path.push(found->second);
            cursor = found->second;
        }

        if (path.top()->terminal) {
            path.top()->terminal = false;
        }

        while (!path.top()->terminal && path.top()->links.empty()) {
            path.pop();
            path.top()->links.erase(word.back());
            word.pop_back();
        }
    }

    /**
     * @brief Produces every stored word that begins with the given prefix.
     * @param prefix the prefix to match against
     * @returns a vector of matching words (empty if none match)
     */
    std::vector<std::string> predict_words(const std::string& prefix) {
        std::vector<std::string> matches;
        std::shared_ptr<TreeNode> cursor = walk(prefix);
        if (cursor == nullptr) {
            return matches;
        }

        if (cursor->terminal && cursor->links.empty()) {
            matches.push_back(prefix);
            return matches;
        }

        collect_words(cursor, prefix, &matches);
        return matches;
    }
};
}  // namespace trie_using_hashmap
}  // namespace data_structures

/**
 * @brief Runs a battery of checks against the PrefixTree implementation.
 * @returns void
 */
static void run_self_checks() {
    data_structures::trie_using_hashmap::PrefixTree dict;

    // Load up a handful of overlapping words to exercise shared prefixes.
    dict.insert("cat");
    dict.insert("catalog");
    dict.insert("category");
    dict.insert("cats");
    dict.insert("catnip");
    dict.insert("cattle");
    dict.insert("cataract");
    dict.insert("cathedral");
    dict.insert("dog");
    dict.insert("dogma");
    dict.insert("Catapult");
    dict.insert("Dodge");

    assert(!dict.search("caterpillar"));
    std::cout << "'caterpillar' is absent from the dictionary" << std::endl;

    assert(!dict.search("fox"));
    std::cout << "'fox' is absent from the dictionary" << std::endl;
    assert(dict.search("cat"));
    assert(dict.search("cattle"));
    assert(dict.search("cataract"));
    assert(dict.search("cats"));
    assert(dict.search("catnip"));
    assert(dict.search("cathedral"));
    assert(dict.search("category"));
    assert(dict.search("catalog"));
    assert(dict.search("dog"));
    assert(dict.search("dogma"));
    assert(dict.search("Dodge"));
    assert(dict.search("Catapult"));

    std::cout << "Every inserted word can be found again" << std::endl;

    // prefix membership checks
    assert(!dict.startwith("categorys"));
    assert(dict.startwith("category"));
    assert(dict.startwith("catalog"));
    assert(!dict.startwith("caterpillar"));
    assert(dict.startwith("cataract"));
    assert(dict.startwith("dog"));
    assert(dict.startwith("dogma"));
    assert(dict.startwith("Dodge"));
    assert(dict.startwith("Catapult"));
    assert(dict.startwith("cat"));
    assert(dict.startwith("d"));
    assert(dict.startwith("dog"));
    assert(dict.startwith("Do"));
    assert(dict.startwith("C"));
    assert(!dict.startwith("Fo"));

    assert(!dict.startwith("F"));

    std::cout << "Prefix-check tests all passed" << std::endl;

    // prefix suggestion checks
    std::vector<std::string> suggestions = dict.predict_words("c");

    for (const std::string& word : dict.predict_words("c")) {
        std::cout << word << std::endl;
    }
    assert(suggestions.size() == 8);
    std::cout << "Listed every word beginning with 'c'" << std::endl;
    suggestions = dict.predict_words("cat");

    for (const std::string& word : suggestions) {
        std::cout << word << std::endl;
    }

    assert(suggestions.size() == 5);
    std::cout << "Listed every word beginning with 'cat'" << std::endl;
    suggestions = dict.predict_words("C");

    for (const std::string& word : suggestions) {
        std::cout << word << std::endl;
    }

    assert(suggestions.size() == 1);
    std::cout << "Listed every word beginning with 'C'" << std::endl;
    suggestions = dict.predict_words("do");

    for (const std::string& word : suggestions) {
        std::cout << word << std::endl;
    }

    assert(suggestions.size() == 2);
    std::cout << "Listed every word beginning with 'do'" << std::endl;

    // removal checks
    dict.delete_word("cat");
    assert(!dict.search("cat"));
    std::cout << "'cat' was removed successfully" << std::endl;

    suggestions = dict.predict_words("cat");
    for (const std::string& word : suggestions) {
        std::cout << word << std::endl;
    }
    assert(suggestions.size() == 4);
    std::cout << "'cat' removal left the remaining prefix matches intact"
              << std::endl;

    // non-ASCII coverage
    dict.insert("猫咪");
    assert(dict.startwith("猫"));
    suggestions = dict.predict_words("z");

    assert(suggestions.size() == 0);
    std::cout << "No word begins with the prefix 'z'" << std::endl;

    std::cout << "All checks completed successfully" << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on exit
 */
int main() {
    run_self_checks();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Karatsuba algorithm for fast
 * multiplication](https://en.wikipedia.org/wiki/Karatsuba_algorithm)
 * @details
 * Given two strings in binary notation we want to multiply them and return the
 * value. Simple approach is to multiply bits one by one which will give the time
 * complexity of around O(n^2). To make it more efficient we will be using
 * Karatsuba algorithm to find the product which will solve the problem
 * O(nlogn) of time.
 * @author [Swastika Gupta](https://github.com/Swastyy)
 * @author [Ameer Carlo Lubang](https://github.com/poypoyan)
 */

#include <cassert>   /// for assert
#include <cstring>   /// for string
#include <iostream>  /// for IO operations

/**
 * @namespace divide_and_conquer
 * @brief Divide and Conquer algorithms
 */
namespace divide_and_conquer {
/**
 * @namespace karatsuba_algorithm
 * @brief Functions for the [Karatsuba algorithm for fast
 * multiplication](https://en.wikipedia.org/wiki/Karatsuba_algorithm) implementation
 */
namespace karatsuba_algorithm {
/**
 * @brief Binary addition
 * @param first, the input string 1
 * @param second, the input string 2
 * @returns the sum binary string
 */
std::string add_strings(std::string first, std::string second) {
    std::string result;  // to store the resulting sum bits

    // make the string lengths equal
    int64_t len1 = first.size();
    int64_t len2 = second.size();
    std::string zero = "0";
    if (len1 < len2) {
        for (int64_t i = 0; i < len2 - len1; i++) {
            zero += first;
            first = zero;
            zero = "0"; // Prevents CI from failing
        }
    } else if (len1 > len2) {
        for (int64_t i = 0; i < len1 - len2; i++) {
            zero += second;
            second = zero;
            zero = "0"; // Prevents CI from failing
        }
    }

    int64_t length = std::max(len1, len2);
    int64_t carry = 0;
    for (int64_t i = length - 1; i >= 0; i--) {
        int64_t firstBit = first.at(i) - '0';
        int64_t secondBit = second.at(i) - '0';

        int64_t sum = (char(firstBit ^ secondBit ^ carry)) + '0';  // sum of 3 bits
        result.insert(result.begin(), sum);

        carry = char((firstBit & secondBit) | (secondBit & carry) |
                (firstBit & carry));  // sum of 3 bits
    }

    if (carry) {
        result.insert(result.begin(), '1');  // adding 1 incase of overflow
    }
    return result;
}

/**
 * @brief Wrapper function for substr that considers leading zeros.
 * @param str, the binary input string.
 * @param x1, the substr parameter integer 1
 * @param x2, the substr parameter integer 2
 * @param n, is the length of the "whole" string: leading zeros + str
 * @returns the "safe" substring for the algorithm *without* leading zeros
 * @returns "0" if substring spans to leading zeros only
 */
std::string safe_substr(const std::string &str, int64_t x1, int64_t x2, int64_t n) {
    int64_t len = str.size();

    if (len >= n) {
        return str.substr(x1, x2);
    }

    int64_t y1 = x1 - (n - len);  // index in str of first char of substring of "whole" string
    int64_t y2 = (x1 + x2 - 1) - (n - len);  // index in str of last char of substring of "whole" string

    if (y2 < 0) {
        return "0";
    } else if (y1 < 0) {
        return str.substr(0, y2 + 1);
    } else {
        return str.substr(y1, x2);
    }
}

/**
 * @brief The main function implements Karatsuba's algorithm for fast
 * multiplication
 * @param str1 the input string 1
 * @param str2 the input string 2
 * @returns the product number value
 */
int64_t karatsuba_algorithm(std::string str1, std::string str2) {
    int64_t len1 = str1.size();
    int64_t len2 = str2.size();
    int64_t n = std::max(len1, len2);

    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return (str1[0] - '0') * (str2[0] - '0');
    }

    int64_t fh = n / 2;     // first half of string
    int64_t sh = n - fh;  // second half of string

    std::string Xl = divide_and_conquer::karatsuba_algorithm::safe_substr(str1, 0, fh, n);   // first half of first string
    std::string Xr = divide_and_conquer::karatsuba_algorithm::safe_substr(str1, fh, sh, n);  // second half of first string

    std::string Yl = divide_and_conquer::karatsuba_algorithm::safe_substr(str2, 0, fh, n);   // first half of second string
    std::string Yr = divide_and_conquer::karatsuba_algorithm::safe_substr(str2, fh, sh, n);  // second half of second string

    // calculating the three products of inputs of size n/2 recursively
    int64_t product1 = karatsuba_algorithm(Xl, Yl);
    int64_t product2 = karatsuba_algorithm(Xr, Yr);
    int64_t product3 = karatsuba_algorithm(
        divide_and_conquer::karatsuba_algorithm::add_strings(Xl, Xr),
        divide_and_conquer::karatsuba_algorithm::add_strings(Yl, Yr));

    return product1 * (1 << (2 * sh)) +
           (product3 - product1 - product2) * (1 << sh) +
           product2;  // combining the three products to get the final result.
}
}  // namespace karatsuba_algorithm
}  // namespace divide_and_conquer

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::string s11 = "1";     // 1
    std::string s12 = "1010";  // 10
    std::cout << "1st test... ";
    assert(divide_and_conquer::karatsuba_algorithm::karatsuba_algorithm(
               s11, s12) == 10);
    std::cout << "passed" << std::endl;

    // 2nd test
    std::string s21 = "11";    // 3
    std::string s22 = "1010";  // 10
    std::cout << "2nd test... ";
    assert(divide_and_conquer::karatsuba_algorithm::karatsuba_algorithm(
               s21, s22) == 30);
    std::cout << "passed" << std::endl;

    // 3rd test
    std::string s31 = "110";   // 6
    std::string s32 = "1010";  // 10
    std::cout << "3rd test... ";
    assert(divide_and_conquer::karatsuba_algorithm::karatsuba_algorithm(
               s31, s32) == 60);
    std::cout << "passed" << std::endl;
}

