/**
 * @file
 * @brief contains an alternative implementation of
 * ::longest_common_substring_length
 * @details
 * ::longest_common_substring_length computes how long a string can be if it
 * is built by deleting characters (but never reordering the rest) from each
 * of two given input strings simultaneously - i.e. the classic Longest
 * Common Subsequence length problem.
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout
#include <string>    /// for std::string
#include <utility>   /// for std::move
#include <vector>    /// for std::vector

/**
 * @brief computes the length of the longest subsequence shared by both
 * inputs
 * @details fills a (size_a+1) x (size_b+1) table bottom-up; O(size_a*size_b)
 * time and memory
 * @param lhs first input string
 * @param rhs second input string
 * @returns length of the longest string obtainable from both lhs and rhs by
 * deleting characters
 */
std::size_t longest_common_substring_length(const std::string& lhs,
                                             const std::string& rhs) {
    const auto lhs_len = lhs.size();
    const auto rhs_len = rhs.size();

    std::vector<std::vector<std::size_t>> table(
        lhs_len + 1, std::vector<std::size_t>(rhs_len + 1, 0));

    // Walk the table from the bottom-right corner up to the top-left,
    // so that each cell only depends on cells already computed.
    std::size_t row = lhs_len;
    while (row > 0) {
        --row;
        std::size_t col = rhs_len;
        while (col > 0) {
            --col;
            if (lhs[row] == rhs[col]) {
                table[row][col] = 1 + table[row + 1][col + 1];
            } else {
                table[row][col] =
                    std::max(table[row + 1][col], table[row][col + 1]);
            }
        }
    }

    return table[0][0];
}

/**
 * @brief bundles one example pair of strings with the expected LCS length
 */
struct Sample {
    const std::string lhs;
    const std::string rhs;
    const std::size_t expected_len;

    Sample(std::string in_lhs, std::string in_rhs, const std::size_t len)
        : lhs(std::move(in_lhs)), rhs(std::move(in_rhs)), expected_len(len) {}
};

/**
 * @return the collection of example pairs used by the checks below
 */
std::vector<Sample> build_samples() {
    return {Sample("", "", 0),
            Sample("ab", "ab", 2),
            Sample("ab", "ba", 1),
            Sample("", "xyz", 0),
            Sample("abcde", "ace", 3),
            Sample("BADANA", "ANADA", 3),
            Sample("BADANA", "CANADAS", 3),
            Sample("a1a234a5aaaa6", "A1AAAA234AAA56AAAAA", 6),
            Sample("123x", "123", 3),
            Sample("12x3x", "123", 3),
            Sample("1x2x3x", "123", 3),
            Sample("x1x2x3x", "123", 3),
            Sample("x12x3x", "123", 3)};
}

/**
 * @brief verifies the raw output of longest_common_substring_length against
 * expectations
 * @tparam Samples container type holding Sample entries
 */
template <typename Samples>
static void check_basic_results(const Samples& samples) {
    for (const auto& s : samples) {
        assert(longest_common_substring_length(s.lhs, s.rhs) ==
               s.expected_len);
    }
}

/**
 * @brief verifies that swapping the two arguments doesn't change the result
 * @tparam Samples container type holding Sample entries
 */
template <typename Samples>
static void check_argument_order_is_irrelevant(const Samples& samples) {
    for (const auto& s : samples) {
        assert(longest_common_substring_length(s.rhs, s.lhs) ==
               s.expected_len);
    }
}

/**
 * @brief produces a reversed copy of a string
 * @param text input string
 * @return a new string with the characters of text in reverse order
 */
std::string mirror(const std::string& text) {
    return {text.rbegin(), text.rend()};
}

/**
 * @brief verifies the function is invariant to reversing both inputs
 * together
 * @tparam Samples container type holding Sample entries
 */
template <typename Samples>
static void check_reversal_invariance(const Samples& samples) {
    for (const auto& s : samples) {
        assert(longest_common_substring_length(mirror(s.lhs),
                                                mirror(s.rhs)) ==
               s.expected_len);
    }
}

/**
 * @brief runs every check defined above
 */
static void run_all_checks() {
    const auto samples = build_samples();
    assert(!samples.empty());
    check_basic_results(samples);
    check_argument_order_is_irrelevant(samples);
    check_reversal_invariance(samples);

    std::cout << "Every check completed without failures!\n";
}

/**
 * @brief Program entry point
 * @returns 0 on exit
 */
int main() {
    run_all_checks();
    return 0;
}

// Longest common subsequence - Dynamic Programming
#include <iostream>
#include <vector>
using namespace std;

void Print(int trace[20][20], int m, int n, string a) {
    if (m == 0 || n == 0) {
        return;
    }
    if (trace[m][n] == 1) {
        Print(trace, m - 1, n - 1, a);
        cout << a[m - 1];
    } else if (trace[m][n] == 2) {
        Print(trace, m - 1, n, a);
    } else if (trace[m][n] == 3) {
        Print(trace, m, n - 1, a);
    }
}

int lcs(string a, string b) {
    int m = a.length(), n = b.length();
    std::vector<std::vector<int> > res(m + 1, std::vector<int>(n + 1));
    int trace[20][20];

    // fills up the arrays with zeros.
    for (int i = 0; i < m + 1; i++) {
        for (int j = 0; j < n + 1; j++) {
            res[i][j] = 0;
            trace[i][j] = 0;
        }
    }

    for (int i = 0; i < m + 1; ++i) {
        for (int j = 0; j < n + 1; ++j) {
            if (i == 0 || j == 0) {
                res[i][j] = 0;
                trace[i][j] = 0;
            }

            else if (a[i - 1] == b[j - 1]) {
                res[i][j] = 1 + res[i - 1][j - 1];
                trace[i][j] = 1;  // 1 means trace the matrix in upper left
                                  // diagonal direction.
            } else {
                if (res[i - 1][j] > res[i][j - 1]) {
                    res[i][j] = res[i - 1][j];
                    trace[i][j] =
                        2;  // 2 means trace the matrix in upwards direction.
                } else {
                    res[i][j] = res[i][j - 1];
                    trace[i][j] =
                        3;  //  means trace the matrix in left direction.
                }
            }
        }
    }
    Print(trace, m, n, a);
    return res[m][n];
}

int main() {
    string a, b;
    cin >> a >> b;
    cout << lcs(a, b);
    return 0;
}

// Longest Common Subsequence, solved with a bottom-up DP table plus
// backtracking to reconstruct the actual subsequence text.
#include <iostream>
#include <vector>
using namespace std;

// Directions used while walking back through the DP table to rebuild the
// subsequence: DIAG means both characters matched, UP means we came from the
// row above, LEFT means we came from the column to the left.
enum TraceDir { NONE = 0, DIAG = 1, UP = 2, LEFT = 3 };

// Walks the trace table backwards from (row, col) and prints the characters
// belonging to the reconstructed common subsequence in order.
void emitSubsequence(const vector<vector<int>>& trace, int row, int col,
                     const string& source) {
    if (row == 0 || col == 0) {
        return;
    }
    if (trace[row][col] == DIAG) {
        emitSubsequence(trace, row - 1, col - 1, source);
        cout << source[row - 1];
    } else if (trace[row][col] == UP) {
        emitSubsequence(trace, row - 1, col, source);
    } else if (trace[row][col] == LEFT) {
        emitSubsequence(trace, row, col - 1, source);
    }
}

// Computes the length of the LCS between first and second, printing the
// reconstructed subsequence as a side effect before returning the length.
int longestCommonSubsequence(const string& first, const string& second) {
    const int rows = static_cast<int>(first.length());
    const int cols = static_cast<int>(second.length());

    vector<vector<int>> lengths(rows + 1, vector<int>(cols + 1, 0));
    vector<vector<int>> trace(rows + 1, vector<int>(cols + 1, NONE));

    for (int i = 0; i <= rows; ++i) {
        for (int j = 0; j <= cols; ++j) {
            if (i == 0 || j == 0) {
                lengths[i][j] = 0;
                trace[i][j] = NONE;
                continue;
            }

            if (first[i - 1] == second[j - 1]) {
                lengths[i][j] = 1 + lengths[i - 1][j - 1];
                trace[i][j] = DIAG;
            } else if (lengths[i - 1][j] > lengths[i][j - 1]) {
                lengths[i][j] = lengths[i - 1][j];
                trace[i][j] = UP;
            } else {
                lengths[i][j] = lengths[i][j - 1];
                trace[i][j] = LEFT;
            }
        }
    }

    emitSubsequence(trace, rows, cols, first);
    return lengths[rows][cols];
}

int main() {
    string first, second;
    cin >> first >> second;
    cout << longestCommonSubsequence(first, second);
    return 0;
}

/**
 * @file
 * @brief Calculate the length of the [longest increasing
 * subsequence](https://en.wikipedia.org/wiki/Longest_increasing_subsequence) in
 * an array
 *
 * @details
 * In computer science, the longest increasing subsequence problem is to find a
 * subsequence of a given sequence in which the subsequence's elements are in
 * sorted order, lowest to highest, and in which the subsequence is as long as
 * possible. This subsequence is not necessarily contiguous, or unique. Longest
 * increasing subsequences are studied in the context of various disciplines
 * related to mathematics, including algorithmics, random matrix theory,
 * representation theory, and physics. The longest increasing subsequence
 * problem is solvable in time O(n log n), where n denotes the length of the
 * input sequence.
 *
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <cassert>   /// for assert
#include <climits>   /// for std::max
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {
/**
 * @brief Calculate the longest increasing subsequence for the specified numbers
 * @param a the array used to calculate the longest increasing subsequence
 * @param n the size used for the arrays
 * @returns the length of the longest increasing
 * subsequence in the `a` array of size `n`
 */
uint64_t LIS(const std::vector<uint64_t> &a, const uint32_t &n) {
    std::vector<int> lis(n);
    for (int i = 0; i < n; ++i) {
        lis[i] = 1;
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (a[i] > a[j] && lis[i] < lis[j] + 1) {
                lis[i] = lis[j] + 1;
            }
        }
    }
    int res = 0;
    for (int i = 0; i < n; ++i) {
        res = std::max(res, lis[i]);
    }
    return res;
}
}  // namespace dynamic_programming

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    std::vector<uint64_t> a = {15, 21, 2, 3, 4, 5, 8, 4, 1, 1};
    uint32_t n = a.size();

    uint32_t result = dynamic_programming::LIS(a, n);
    assert(result ==
           5);  ///< The longest increasing subsequence is `{2,3,4,5,8}`

    std::cout << "Self-test implementations passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    uint32_t n = 0;

    std::cout << "Enter size of array: ";
    std::cin >> n;

    std::vector<uint64_t> a(n);

    std::cout << "Enter array elements: ";
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    std::cout << "\nThe result is: " << dynamic_programming::LIS(a, n)
              << std::endl;
    test();  // run self-test implementations

    return 0;
}

/**
 * @file
 * @brief Alternative implementation for computing the length of the
 * [longest increasing
 * subsequence](https://en.wikipedia.org/wiki/Longest_increasing_subsequence)
 * of an array.
 *
 * @details
 * Given a sequence of numbers, we want the length of the longest subset of
 * elements (not necessarily contiguous) that appears in strictly increasing
 * order while preserving the original relative ordering. This file uses the
 * classic quadratic O(n^2) dynamic programming approach: for every index we
 * remember the best increasing run that can end there.
 */

#include <cassert>   /// for assert
#include <climits>   /// for std::max
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {

/**
 * @brief Finds the length of the longest strictly increasing subsequence
 * within the provided values.
 * @param values the sequence to analyze
 * @param length how many entries of `values` are valid
 * @returns the length of the longest increasing run achievable
 */
uint64_t LIS(const std::vector<uint64_t> &values, const uint32_t &length) {
    std::vector<int> bestEndingAt(length, 1);  // every single element is a run of length 1

    for (uint32_t cur = 0; cur < length; ++cur) {
        for (uint32_t prev = 0; prev < cur; ++prev) {
            const bool increasing = values[cur] > values[prev];
            const bool improves = bestEndingAt[cur] < bestEndingAt[prev] + 1;
            if (increasing && improves) {
                bestEndingAt[cur] = bestEndingAt[prev] + 1;
            }
        }
    }

    int longest = 0;
    for (uint32_t idx = 0; idx < length; ++idx) {
        longest = std::max(longest, bestEndingAt[idx]);
    }
    return longest;
}

}  // namespace dynamic_programming

/**
 * @brief Runs a fixed self-check to confirm LIS behaves as expected
 * @returns void
 */
static void selfCheck() {
    std::vector<uint64_t> sample = {15, 21, 2, 3, 4, 5, 8, 4, 1, 1};
    const uint32_t sampleSize = sample.size();

    const uint32_t computed = dynamic_programming::LIS(sample, sampleSize);
    assert(computed == 5);  ///< expected run is `{2,3,4,5,8}`

    std::cout << "Built-in self-check succeeded!" << std::endl;
}

/**
 * @brief Program entry point
 * @returns 0 on exit
 */
int main() {
    uint32_t count = 0;

    std::cout << "How many numbers will you enter? ";
    std::cin >> count;

    std::vector<uint64_t> values(count);

    std::cout << "Enter the numbers, separated by whitespace: ";
    for (uint32_t idx = 0; idx < count; ++idx) {
        std::cin >> values[idx];
    }

    std::cout << "\nLongest increasing subsequence length: "
              << dynamic_programming::LIS(values, count) << std::endl;

    selfCheck();

    return 0;
}

// Program to calculate length of longest increasing subsequence in an array
// in O(n log n)
// tested on : https://cses.fi/problemset/task/1145/

#include <iostream>
#include <set>
#include <vector>

using namespace std;
int LIS(const std::vector<int>& arr, int n) {
    set<int> active;  // The current built LIS.
    active.insert(arr[0]);
    // Loop through every element.
    for (int i = 1; i < n; ++i) {
        auto get = active.lower_bound(arr[i]);
        if (get == active.end()) {
            active.insert(arr[i]);
        }  // current element is the greatest so LIS increases by 1.
        else {
            int val = *get;  // we find the position where arr[i] will be in the
                             // LIS. If it is in the LIS already we do nothing
            if (val > arr[i]) {
                // else we remove the bigger element and add a smaller element
                // (which is arr[i]) and continue;
                active.erase(get);
                active.insert(arr[i]);
            }
        }
    }
    return active.size();  // size of the LIS.
}
int main() {
    int n;
    cout << "Enter size of array: ";
    cin >> n;
    std::vector<int> a(n);
    cout << "Enter array elements: ";
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    cout << LIS(a, n) << endl;
    return 0;
}

// Computes the length of the longest increasing subsequence of an array in
// O(n log n) time by maintaining the smallest possible "tail" value for every
// achievable subsequence length.
// verified against: https://cses.fi/problemset/task/1145/

#include <iostream>
#include <set>
#include <vector>

using namespace std;

int longestIncreasingSubsequenceLength(const std::vector<int>& sequence,
                                        int count) {
    set<int> tails;  // tails[k] roughly tracks the best (smallest) end value
                     // for an increasing run of length k+1
    tails.insert(sequence[0]);

    int idx = 1;
    while (idx < count) {
        const auto slot = tails.lower_bound(sequence[idx]);
        if (slot == tails.end()) {
            // sequence[idx] is larger than everything seen, so it extends
            // the longest run found so far by one.
            tails.insert(sequence[idx]);
        } else if (*slot > sequence[idx]) {
            // sequence[idx] can replace an existing tail with a smaller
            // value, keeping future extensions easier without changing the
            // run length.
            tails.erase(slot);
            tails.insert(sequence[idx]);
        }
        // if *slot == sequence[idx] there's nothing to do, the value is
        // already represented.
        ++idx;
    }

    return static_cast<int>(tails.size());
}

int main() {
    int count;
    cout << "Enter size of array: ";
    cin >> count;

    std::vector<int> sequence(count);
    cout << "Enter array elements: ";
    for (int idx = 0; idx < count; ++idx) {
        cin >> sequence[idx];
    }

    cout << longestIncreasingSubsequenceLength(sequence, count) << endl;
    return 0;
}

/**
 * @file
 * @brief Program to find the [Longest Palindormic
 * Subsequence](https://www.geeksforgeeks.org/longest-palindromic-subsequence-dp-12/) of a string
 *
 * @details
 * [Palindrome](https://en.wikipedia.org/wiki/Palindrome) string sequence of
 * characters which reads the same backward as forward
 * [Subsequence](https://en.wikipedia.org/wiki/Subsequence)  is a sequence that
 * can be derived from another sequence by deleting some or no elements without
 * changing the order of the remaining elements.

 * @author [Anjali Jha](https://github.com/anjali1903)
 */

#include <cassert>  /// for assert
#include <string>   /// for std::string
#include <vector>   /// for std::vector

/**
 * @namespace
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {
/**
 * @brief Function that returns the longest palindromic
 * subsequence of a string
 * @param a string whose longest palindromic subsequence is to be found
 * @returns longest palindromic subsequence of the string
 */
std::string lps(const std::string& a) {
    const auto b = std::string(a.rbegin(), a.rend());
    const auto m = a.length();
    using ind_type = std::string::size_type;
    std::vector<std::vector<ind_type> > res(m + 1,
                                            std::vector<ind_type>(m + 1));

    // Finding the length of the longest
    // palindromic subsequence and storing
    // in a 2D array in bottoms-up manner
    for (ind_type i = 0; i <= m; i++) {
        for (ind_type j = 0; j <= m; j++) {
            if (i == 0 || j == 0) {
                res[i][j] = 0;
            } else if (a[i - 1] == b[j - 1]) {
                res[i][j] = res[i - 1][j - 1] + 1;
            } else {
                res[i][j] = std::max(res[i - 1][j], res[i][j - 1]);
            }
        }
    }
    // Length of longest palindromic subsequence
    auto idx = res[m][m];
    // Creating string of index+1 length
    std::string ans(idx, '\0');
    ind_type i = m, j = m;

    // starting from right-most bottom-most corner
    // and storing them one by one in ans
    while (i > 0 && j > 0) {
        // if current characters in a and b are same
        // then it is a part of the ans
        if (a[i - 1] == b[j - 1]) {
            ans[idx - 1] = a[i - 1];
            i--;
            j--;
            idx--;
        }
        // If they are not same, find the larger of the
        // two and move in that direction
        else if (res[i - 1][j] > res[i][j - 1]) {
            i--;
        } else {
            j--;
        }
    }

    return ans;
}
}  // namespace dynamic_programming

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    assert(dynamic_programming::lps("radar") == "radar");
    assert(dynamic_programming::lps("abbcbaa") == "abcba");
    assert(dynamic_programming::lps("bbbab") == "bbbb");
    assert(dynamic_programming::lps("") == "");
}

/**
 * @brief Main Function
 * @returns 0 on exit
 */
int main() {
    test();  // execute the tests
    return 0;
}

/**
 * @file
 * @brief Alternative solution for finding the [Longest Palindromic
 * Subsequence](https://www.geeksforgeeks.org/longest-palindromic-subsequence-dp-12/)
 * contained within a string.
 *
 * @details
 * A palindrome reads identically forwards and backwards. A subsequence keeps
 * the relative order of the original characters but may skip some of them.
 * This file finds the longest subsequence of the input that is itself a
 * palindrome, by comparing the string against its own reverse with a
 * standard LCS-style dynamic programming table, then walking the table back
 * to reconstruct the actual characters.
 */

#include <cassert>  /// for assert
#include <string>   /// for std::string
#include <vector>   /// for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {

/**
 * @brief Returns the longest palindromic subsequence found within the input
 * string.
 * @param text the string to search
 * @returns the palindromic subsequence itself (not just its length)
 */
std::string longestPalindromicSubsequence(const std::string& text) {
    const auto flipped = std::string(text.rbegin(), text.rend());
    const auto n = text.length();
    using SizeT = std::string::size_type;

    // table[i][j] = length of the LCS between text[0..i) and flipped[0..j)
    std::vector<std::vector<SizeT>> table(n + 1, std::vector<SizeT>(n + 1));

    for (SizeT i = 0; i <= n; i++) {
        for (SizeT j = 0; j <= n; j++) {
            if (i == 0 || j == 0) {
                table[i][j] = 0;
            } else if (text[i - 1] == flipped[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;
            } else {
                table[i][j] = std::max(table[i - 1][j], table[i][j - 1]);
            }
        }
    }

    // The bottom-right cell holds the total palindromic-subsequence length.
    auto remaining = table[n][n];
    std::string built(remaining, '\0');

    SizeT i = n;
    SizeT j = n;
    while (i > 0 && j > 0) {
        if (text[i - 1] == flipped[j - 1]) {
            // Matching characters belong to the answer; place from the
            // back since we are walking backwards through the table.
            built[remaining - 1] = text[i - 1];
            --i;
            --j;
            --remaining;
        } else if (table[i - 1][j] > table[i][j - 1]) {
            --i;
        } else {
            --j;
        }
    }

    return built;
}

}  // namespace dynamic_programming

/**
 * @brief Runs a batch of sanity assertions against
 * longestPalindromicSubsequence
 * @returns void
 */
static void runSelfTests() {
    assert(dynamic_programming::longestPalindromicSubsequence("radar") ==
           "radar");
    assert(dynamic_programming::longestPalindromicSubsequence("abbcbaa") ==
           "abcba");
    assert(dynamic_programming::longestPalindromicSubsequence("bbbab") ==
           "bbbb");
    assert(dynamic_programming::longestPalindromicSubsequence("") == "");
}

/**
 * @brief Program entry point
 * @returns 0 on exit
 */
int main() {
    runSelfTests();
    return 0;
}

#include <climits>
#include <iostream>
using namespace std;

#define MAX 10

// dp table to store the solution for already computed sub problems
int dp[MAX][MAX];

// Function to find the most efficient way to multiply the given sequence of
// matrices
int MatrixChainMultiplication(int dim[], int i, int j) {
    // base case: one matrix
    if (j <= i + 1)
        return 0;

    // stores minimum number of scalar multiplications (i.e., cost)
    // needed to compute the matrix M[i+1]...M[j] = M[i..j]
    int min = INT_MAX;

    // if dp[i][j] is not calculated (calculate it!!)

    if (dp[i][j] == 0) {
        // take the minimum over each possible position at which the
        // sequence of matrices can be split

        for (int k = i + 1; k <= j - 1; k++) {
            // recur for M[i+1]..M[k] to get a i x k matrix
            int cost = MatrixChainMultiplication(dim, i, k);

            // recur for M[k+1]..M[j] to get a k x j matrix
            cost += MatrixChainMultiplication(dim, k, j);

            // cost to multiply two (i x k) and (k x j) matrix
            cost += dim[i] * dim[k] * dim[j];

            if (cost < min)
                min = cost;  // store the minimum cost
        }
        dp[i][j] = min;
    }

    // return min cost to multiply M[j+1]..M[j]
    return dp[i][j];
}

// main function
int main() {
    // Matrix i has Dimensions dim[i-1] & dim[i] for i=1..n
    // input is 10 x 30 matrix, 30 x 5 matrix, 5 x 60 matrix
    int dim[] = {10, 30, 5, 60};
    int n = sizeof(dim) / sizeof(dim[0]);

    // Function Calling: MatrixChainMultiplications(dimensions_array, starting,
    // ending);

    cout << "Minimum cost is " << MatrixChainMultiplication(dim, 0, n - 1)
         << "\n";

    return 0;
}

#include <climits>
#include <iostream>
using namespace std;

#define MAX_MATRICES 10

// Memo table holding already-solved subproblem costs, indexed by the
// (start, end) split boundaries used below.
int memo[MAX_MATRICES][MAX_MATRICES];

// Recursively determines the cheapest way (fewest scalar multiplications) to
// multiply the chain of matrices whose boundary dimensions live in
// dims[start..end].
int cheapestChainCost(int dims[], int start, int end) {
    // Base case: a single matrix requires no multiplication.
    if (end <= start + 1) {
        return 0;
    }

    // Only do the work if this subproblem hasn't been solved before.
    if (memo[start][end] == 0) {
        int bestCost = INT_MAX;

        // Try every valid split point and keep whichever is cheapest.
        for (int split = start + 1; split <= end - 1; split++) {
            // Cost of multiplying the left half of the split...
            int cost = cheapestChainCost(dims, start, split);

            // ...plus the cost of multiplying the right half...
            cost += cheapestChainCost(dims, split, end);

            // ...plus the cost of combining the two resulting matrices.
            cost += dims[start] * dims[split] * dims[end];

            if (cost < bestCost) {
                bestCost = cost;
            }
        }
        memo[start][end] = bestCost;
    }

    return memo[start][end];
}

int main() {
    // dims[i-1] and dims[i] give the dimensions of matrix i, for i = 1..n.
    // Here: a 10x30 matrix, followed by 30x5, followed by 5x60.
    int dims[] = {10, 30, 5, 60};
    int matrixCount = sizeof(dims) / sizeof(dims[0]);

    cout << "Minimum cost is " << cheapestChainCost(dims, 0, matrixCount - 1)
         << "\n";

    return 0;
}

/**
* @file
* @brief C++ program for maximum contiguous circular sum problem using [Kadane's Algorithm](https://en.wikipedia.org/wiki/Maximum_subarray_problem)
* @details
* The idea is to modify Kadane’s algorithm to find a minimum contiguous subarray sum and the maximum contiguous subarray sum,
* then check for the maximum value between the max_value and the value left after subtracting min_value from the total sum.
* For more information, check [Geeks For Geeks](https://www.geeksforgeeks.org/maximum-contiguous-circular-sum/) explanation page.
*/

#include <cassert>     /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector


/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {
/**
 * @brief returns the maximum contiguous circular sum of an array
 * 
 * @param arr is the array/vector
 * @return int which is the maximum sum
 */
int maxCircularSum(std::vector<int>& arr)
{
    // Edge Case
    if (arr.size() == 1)
        return arr[0];

    // Sum variable which stores total sum of the array.
    int sum = 0;
    for (int i = 0; i < arr.size(); i++) {
        sum += arr[i];
    }

    // Every variable stores first value of the array.
    int current_max = arr[0], max_so_far = arr[0], current_min = arr[0], min_so_far = arr[0];

    // Concept of Kadane's Algorithm
    for (int i = 1; i < arr.size(); i++) {
        // Kadane's Algorithm to find Maximum subarray sum.
        current_max = std::max(current_max + arr[i], arr[i]);
        max_so_far = std::max(max_so_far, current_max);

        // Kadane's Algorithm to find Minimum subarray sum.
        current_min = std::min(current_min + arr[i], arr[i]);
        min_so_far = std::min(min_so_far, current_min);
    }

    if (min_so_far == sum)
        return max_so_far;

    // Return the maximum value
    return std::max(max_so_far, sum - min_so_far);
}
}  // namespace dynamic_programming

/**
 * @brief Self-test implementation
 * @returns void
 */
static void test() {
    // Description of the test
    // Input: arr[] = {8, -8, 9, -9, 10, -11, 12}
    // Output: 22 
    // Explanation: Subarray 12, 8, -8, 9, -9, 10 gives the maximum sum, that is 22.

    std::vector<int> arr = {8, -8, 9, -9, 10, -11, 12}; 
    assert(dynamic_programming::maxCircularSum(arr) == 22); // this ensures that the algorithm works as expected

    arr = {8, -8, 10, -9, 10, -11, 12};
    assert(dynamic_programming::maxCircularSum(arr) == 23);

    std::cout << "All tests have successfully passed!\n";
}


/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
     test();  // run self-test implementations
     return 0;
}

/**
* @file
* @brief Alternative implementation of the maximum contiguous circular
* subarray sum problem, built on top of [Kadane's
* Algorithm](https://en.wikipedia.org/wiki/Maximum_subarray_problem).
* @details
* We run Kadane's algorithm twice: once to obtain the best ordinary
* (non-wrapping) subarray sum, and once (with min/max swapped) to obtain the
* worst subarray sum. Subtracting the worst subarray from the array's total
* yields the best possible *wrapping* subarray sum. The final answer is the
* larger of the two, unless every element is negative, in which case the
* non-wrapping result must be used since a "wrap everything" answer would be
* an empty subarray.
* See also: https://www.geeksforgeeks.org/maximum-contiguous-circular-sum/
*/

#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {

/**
 * @brief Finds the maximum possible sum of a contiguous subarray, allowing
 * the subarray to wrap around from the end of the array back to the start.
 * @param values the array/vector to inspect
 * @return the largest achievable circular subarray sum
 */
int maxCircularSum(std::vector<int>& values) {
    const std::size_t count = values.size();

    // With a single element, that element is the only possible subarray.
    if (count == 1) {
        return values[0];
    }

    // Total of every element, needed to derive the wrap-around sum later.
    int total = 0;
    for (std::size_t idx = 0; idx < count; idx++) {
        total += values[idx];
    }

    // Track the best/worst running subarray sums simultaneously.
    int runningMax = values[0];
    int bestNonWrap = values[0];
    int runningMin = values[0];
    int worstSubarray = values[0];

    for (std::size_t idx = 1; idx < count; idx++) {
        // Standard Kadane step for the maximum subarray.
        runningMax = std::max(runningMax + values[idx], values[idx]);
        bestNonWrap = std::max(bestNonWrap, runningMax);

        // Mirror-image Kadane step for the minimum subarray.
        runningMin = std::min(runningMin + values[idx], values[idx]);
        worstSubarray = std::min(worstSubarray, runningMin);
    }

    // If the "worst" subarray is actually the whole array, wrapping around
    // would leave nothing behind, so only the plain answer is valid.
    if (worstSubarray == total) {
        return bestNonWrap;
    }

    return std::max(bestNonWrap, total - worstSubarray);
}

}  // namespace dynamic_programming

/**
 * @brief Exercises maxCircularSum against a couple of known-answer cases
 * @returns void
 */
static void runChecks() {
    // Case 1: wrapping around the end beats any non-wrapping run.
    // arr = {8, -8, 9, -9, 10, -11, 12} -> best is 12,8,-8,9,-9,10 = 22
    std::vector<int> caseOne = {8, -8, 9, -9, 10, -11, 12};
    assert(dynamic_programming::maxCircularSum(caseOne) == 22);

    // Case 2: a slight tweak to the values raises the best wrap-around sum.
    std::vector<int> caseTwo = {8, -8, 10, -9, 10, -11, 12};
    assert(dynamic_programming::maxCircularSum(caseTwo) == 23);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Program entry point
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Minimum Edit
 * Distance](https://en.wikipedia.org/wiki/Edit_distance) using Dynamic
 * Programing
 *
 * @details
 *
 * Given two strings str1 & str2 and we have to calculate the minimum
 * number of operations (Insert, Remove, Replace) required to convert
 * str1 to str2.
 *
 * ### Algorithm
 *
 * We will solve this problem using Naive recursion. But as we are
 * approaching with a DP solution. So, we will take a DP array to
 * store the solution of all sub-problems so that we don't have to
 * perform recursion again and again. Now to solve the problem, We
 * can traverse all characters from either right side of the strings
 * or left side. Suppose we will do it from the right side. So, there
 * are two possibilities for every pair of characters being traversed.
 * 1. If the last characters of two strings are the same, Ignore
 * the characters and get the count for the remaining string.
 * So, we get the solution for lengths m-1 and n-1 in a DP array.
 *
 * 2. Else, (If last characters are not the same), we will consider all
 * three operations (Insert, Remove, Replace) on the last character of
 * the first string and compute the minimum cost for all three operations
 * and take the minimum of three values in the DP array.
 * For Insert: Recur for m and n-1
 * For Remove: Recur for for m-1 and n
 * For Replace: Recur for for m-1 and n-1
 *
 * @author [Nirjas Jakilim](github.com/nirzak)
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */

namespace dynamic_programming {

/**
 * @namespace Minimum Edit Distance
 * @brief Implementation of [Minimum Edit
 * Distance](https://en.wikipedia.org/wiki/Edit_distance) algorithm
 */

namespace minimum_edit_distance {

/**
 * @brief Takes input of the cost of
 * three operations: Insert, Replace and Delete
 * and return the minimum cost among them.
 * @param x used to pass minimum cost of Insert operations
 * @param y used to pass minimum cost of Replace operations
 * @param z used to pass minimum cost of Delete operations
 * @returns x if `x` is the minimum value
 * @returns y if `y` is the minimum value
 * @returns z if `z` is the minimum value
 */
uint64_t min(uint64_t x, uint64_t y, uint64_t z) {
    if (x <= y && x <= z) {
        return x;  /// returns x, if x is the minimum value
    }
    if (y <= x && y <= z) {
        return y;  /// returns y, if y is the minimum value
    } else {
        return z;  /// returns z if z is the minimum value
    }
}

/**
 * @brief Calculates and stores the result
 * of all the sub-problems, so that we don't have to recur to compute
 * the minimum cost of a particular operation if it is already
 * computed and stored in the `dp` vector.
 * @param dp vector to store the computed minimum costs
 * @param str1 to pass the 1st string
 * @param str2 to pass the 2nd string
 * @param m the length of str1
 * @param n the length of str2
 * @returns dp[m][n] the minimum cost of operations
 * needed to convert str1 to str2
 */
uint64_t editDistDP(std::string str1, std::string str2, uint64_t m,
                    uint64_t n) {
    /// Create a table to store results of subproblems
    std::vector<std::vector<uint64_t>> dp(
        m + 1,
        std::vector<uint64_t>(
            n +
            1));  /// creasting 2D vector dp to store the results of subproblems

    /// Fill d[][] in bottom up manner
    for (uint64_t i = 0; i <= m; i++) {
        for (uint64_t j = 0; j <= n; j++) {
            /// If first string is empty, only option is to
            /// insert all characters of second string
            if (i == 0) {
                dp[i][j] = j;  /// Minimum operations = j
            }

            /// If second string is empty, only option is to
            /// remove all characters of second string
            else if (j == 0) {
                dp[i][j] = i;  /// Minimum operations = i
            }

            /// If last characters are same, ignore last char
            /// and recur for remaining string
            else if (str1[i - 1] == str2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            }

            /// If the last character is different, consider all
            /// possibilities and find the minimum
            else {
                dp[i][j] = 1 + min(dp[i][j - 1],       // Insert
                                   dp[i - 1][j],       // Remove
                                   dp[i - 1][j - 1]);  // Replace
            }
        }
    }

    return dp[m][n];  /// returning the minimum cost of operations needed to
                      /// convert str1 to str2
}
}  // namespace minimum_edit_distance
}  // namespace dynamic_programming

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    std::string str1 = "INTENTION";  // Sample input of 1st string
    std::string str2 = "EXECUTION";  // Sample input of 2nd string
    uint64_t expected_output1 = 5;   // Expected minimum cost
    uint64_t output1 = dynamic_programming::minimum_edit_distance::editDistDP(
        str1, str2, str1.length(),
        str2.length());  // calling the editDistDP function and storing the
                         // result on output1
    assert(output1 ==
           expected_output1);  // comparing the output with the expected output
    std::cout << "Minimum Number of Operations Required: " << output1
              << std::endl;

    // 2nd test
    std::string str3 = "SATURDAY";
    std::string str4 = "SUNDAY";
    uint64_t expected_output2 = 3;
    uint64_t output2 = dynamic_programming::minimum_edit_distance::editDistDP(
        str3, str4, str3.length(), str4.length());
    assert(output2 == expected_output2);
    std::cout << "Minimum Number of Operations Required: " << output2
              << std::endl;
}

/**
 * @brief main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Alternate implementation of the classic "edit distance" problem
 * using bottom-up tabulation.
 *
 * @details
 * Given two words `source` and `target`, compute the least number of
 * single-character insert / delete / substitute operations that turn
 * `source` into `target`.
 *
 * The approach fills a 2D table row by row. Each cell (r, c) answers:
 * "what is the cheapest way to transform the first r letters of source
 * into the first c letters of target?" When the trailing letters match,
 * we simply inherit the diagonal answer. Otherwise we look at the three
 * neighboring cells (representing insert, delete, substitute) and take
 * the cheapest, adding one operation.
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for std::cout
#include <string>    /// for std::string
#include <vector>    /// for std::vector

namespace dynamic_programming {

namespace minimum_edit_distance {

/**
 * @brief Picks the smallest of three candidate operation costs.
 * @param insertCost cost if we insert a character
 * @param deleteCost cost if we delete a character
 * @param substituteCost cost if we substitute a character
 * @returns the smallest of the three
 */
uint64_t smallestOfThree(uint64_t insertCost, uint64_t deleteCost,
                          uint64_t substituteCost) {
    uint64_t best = insertCost;
    if (deleteCost < best) {
        best = deleteCost;
    }
    if (substituteCost < best) {
        best = substituteCost;
    }
    return best;
}

/**
 * @brief Builds the tabulation grid and returns the edit distance between
 * two words.
 * @param source the word we start with
 * @param target the word we want to end up with
 * @param sourceLen number of characters considered from `source`
 * @param targetLen number of characters considered from `target`
 * @returns the minimum number of edits needed
 */
uint64_t computeEditDistance(std::string source, std::string target,
                              uint64_t sourceLen, uint64_t targetLen) {
    // grid[r][c] holds the answer for source[0..r) -> target[0..c)
    std::vector<std::vector<uint64_t>> grid(
        sourceLen + 1, std::vector<uint64_t>(targetLen + 1, 0));

    for (uint64_t r = 0; r <= sourceLen; ++r) {
        for (uint64_t c = 0; c <= targetLen; ++c) {
            if (r == 0) {
                // nothing left of source: must insert every remaining
                // target character
                grid[r][c] = c;
                continue;
            }
            if (c == 0) {
                // nothing left of target: must delete every remaining
                // source character
                grid[r][c] = r;
                continue;
            }
            if (source[r - 1] == target[c - 1]) {
                // trailing letters already agree, skip both
                grid[r][c] = grid[r - 1][c - 1];
            } else {
                grid[r][c] = 1 + smallestOfThree(grid[r][c - 1],      // insert
                                                  grid[r - 1][c],      // delete
                                                  grid[r - 1][c - 1]);  // substitute
            }
        }
    }

    return grid[sourceLen][targetLen];
}

}  // namespace minimum_edit_distance
}  // namespace dynamic_programming

/**
 * @brief Runs a couple of sanity checks against known answers.
 */
static void runChecks() {
    // case A: two classic textbook words
    std::string wordA1 = "INTENTION";
    std::string wordA2 = "EXECUTION";
    uint64_t expectedA = 5;
    uint64_t resultA = dynamic_programming::minimum_edit_distance::computeEditDistance(
        wordA1, wordA2, wordA1.length(), wordA2.length());
    assert(resultA == expectedA);
    std::cout << "Edits needed (case A): " << resultA << std::endl;

    // case B: day-of-week style strings
    std::string wordB1 = "SATURDAY";
    std::string wordB2 = "SUNDAY";
    uint64_t expectedB = 3;
    uint64_t resultB = dynamic_programming::minimum_edit_distance::computeEditDistance(
        wordB1, wordB2, wordB1.length(), wordB2.length());
    assert(resultB == expectedB);
    std::cout << "Edits needed (case B): " << resultB << std::endl;
}

int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implements [Palindrome
 * Partitioning](https://leetcode.com/problems/palindrome-partitioning-ii/)
 * algorithm, giving you the minimum number of partitions you need to make
 *
 * @details
 * palindrome partitioning uses dynamic programming and goes to all the possible
 * partitions to find the minimum you are given a string and you need to give
 * minimum number of partitions needed to divide it into a number of palindromes
 * [Palindrome Partitioning]
 * (https://www.geeksforgeeks.org/palindrome-partitioning-dp-17/) overall time
 * complexity O(n^2) For example: example 1:- String : "nitik" Output : 2 => "n
 * | iti | k" For example: example 2:- String : "ababbbabbababa" Output : 3 =>
 * "aba | b | bbabb | ababa"
 * @author [Sujay Kaushik] (https://github.com/sujaykaushik008)
 */

#include <algorithm>  // for std::min
#include <cassert>    // for std::assert
#include <climits>    // for INT_MAX
#include <iostream>   // for io operations
#include <vector>     // for std::vector

/**
 * @namespace dynamic_programming
 * @brief Dynamic Programming algorithms
 */
namespace dynamic_programming {

/**
 * @namespace palindrome_partitioning
 * @brief Functions for [Palindrome
 * Partitioning](https://leetcode.com/problems/palindrome-partitioning-ii/)
 * algorithm
 */
namespace palindrome_partitioning {

/**
 * Function implementing palindrome partitioning algorithm using lookup table
 * method.
 * @param str input string
 * @returns minimum number of partitions
 */
int pal_part(const std::string &str) {
    int n = str.size();

    // creating lookup table for minimum number of cuts
    std::vector<std::vector<int> > cuts(n, std::vector<int>(n, 0));

    // creating lookup table for palindrome checking
    std::vector<std::vector<bool> > is_palindrome(n,
                                                  std::vector<bool>(n, false));

    // initialization
    for (int i = 0; i < n; i++) {
        is_palindrome[i][i] = true;
        cuts[i][i] = 0;
    }

    for (int len = 2; len <= n; len++) {
        for (int start_index = 0; start_index < n - len + 1; start_index++) {
            int end_index = start_index + len - 1;

            if (len == 2) {
                is_palindrome[start_index][end_index] =
                    (str[start_index] == str[end_index]);
            } else {
                is_palindrome[start_index][end_index] =
                    (str[start_index] == str[end_index]) &&
                    is_palindrome[start_index + 1][end_index - 1];
            }

            if (is_palindrome[start_index][end_index]) {
                cuts[start_index][end_index] = 0;
            } else {
                cuts[start_index][end_index] = INT_MAX;
                for (int partition = start_index; partition <= end_index - 1;
                     partition++) {
                    cuts[start_index][end_index] =
                        std::min(cuts[start_index][end_index],
                                 cuts[start_index][partition] +
                                     cuts[partition + 1][end_index] + 1);
                }
            }
        }
    }

    return cuts[0][n - 1];
}
}  // namespace palindrome_partitioning
}  // namespace dynamic_programming

