/**
 * @file
 * @brief Rewritten take on minimum-cut palindrome partitioning: split a
 * string into the fewest possible palindromic pieces.
 *
 * @details
 * We precompute, for every substring, whether it reads the same forwards
 * and backwards, then use that table to figure out the fewest cuts needed
 * so every resulting piece is itself a palindrome. Runs in roughly O(n^2).
 * e.g. "nitik" -> 2 cuts ("n | iti | k"); "abdc" -> 3 cuts.
 */

#include <algorithm>  // for std::min
#include <cassert>    // for assert
#include <climits>    // for INT_MAX
#include <iostream>   // for std::cout
#include <string>     // for std::string
#include <vector>     // for std::vector

namespace dynamic_programming {

namespace palindrome_partitioning {

/**
 * @brief Fills the palindrome-membership table for all substrings.
 * @param text the source string
 * @returns a square boolean matrix where entry [i][j] is true iff
 * text[i..j] is a palindrome
 */
std::vector<std::vector<bool>> buildPalindromeTable(const std::string &text) {
    int length = static_cast<int>(text.size());
    std::vector<std::vector<bool>> flag(length, std::vector<bool>(length, false));

    // every single character is trivially a palindrome
    for (int idx = 0; idx < length; ++idx) {
        flag[idx][idx] = true;
    }

    for (int span = 2; span <= length; ++span) {
        for (int left = 0; left + span - 1 < length; ++left) {
            int right = left + span - 1;
            bool endsMatch = (text[left] == text[right]);
            if (span == 2) {
                flag[left][right] = endsMatch;
            } else {
                flag[left][right] = endsMatch && flag[left + 1][right - 1];
            }
        }
    }
    return flag;
}

/**
 * @brief Computes the minimum number of cuts needed to partition the
 * string into palindromic segments.
 * @param text input string
 * @returns fewest cuts required
 */
int minimumPalindromeCuts(const std::string &text) {
    int length = static_cast<int>(text.size());
    std::vector<std::vector<bool>> isPal = buildPalindromeTable(text);

    std::vector<std::vector<int>> cutCount(length, std::vector<int>(length, 0));

    for (int span = 2; span <= length; ++span) {
        for (int left = 0; left + span - 1 < length; ++left) {
            int right = left + span - 1;

            if (isPal[left][right]) {
                cutCount[left][right] = 0;
                continue;
            }

            int best = INT_MAX;
            for (int splitAt = left; splitAt < right; ++splitAt) {
                int candidate =
                    cutCount[left][splitAt] + cutCount[splitAt + 1][right] + 1;
                best = std::min(best, candidate);
            }
            cutCount[left][right] = best;
        }
    }

    return cutCount[0][length - 1];
}

}  // namespace palindrome_partitioning
}  // namespace dynamic_programming

