 * @brief Exercises the partitioning function against known answers.
 */
static void runChecks() {
    std::vector<std::string> samples{"nitik", "ababbbabbababa", "abdc"};
    std::vector<int> expected{2, 3, 3};

    std::vector<int> actual;
    for (const auto &sample : samples) {
        actual.push_back(
            dynamic_programming::palindrome_partitioning::minimumPalindromeCuts(
                sample));
    }

    for (size_t idx = 0; idx < samples.size(); ++idx) {
        assert(actual[idx] == expected[idx]);
    }

    std::cout << "All palindrome-partitioning checks passed!\n";
}

int main() {
    runChecks();
    return 0;
}

/******************************************************************************
 * @file
 * @brief Implementation of the [Partition
 * Problem](https://en.wikipedia.org/wiki/Partition_problem )
 * @details
 * The partition problem, or number partitioning, is the task of deciding
 * whether a given multiset S of positive integers can be partitioned into two
 * subsets S1 and S2 such that the sum of the numbers in S1 equals the sum of
 * the numbers in S2. Although the partition problem is NP-complete, there is a
 * pseudo-polynomial time dynamic programming solution, and there are heuristics
 * that solve the problem in many instances, either optimally or approximately.
 * For this reason, it has been called "the easiest hard problem".
 *
 * The worst case time complexity of Jarvis’s Algorithm is O(n^2). Using
 * Graham’s scan algorithm, we can find Convex Hull in O(nLogn) time.
 *
 * ### Implementation
 *
 * Step 1
 * Calculate sum of the array. If sum is odd, there can not be two subsets with
 * equal sum, so return false.
 *
 * Step 2
 * If sum of array elements is even, calculate sum/2 and find a subset of array
 * with sum equal to sum/2.
 *
 * @author [Lajat Manekar](https://github.com/Lazeeez)
 *
 *******************************************************************************/
#include <cassert>   /// for assert
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for IO Operations
#include <numeric>   /// for std::accumulate
#include <vector>    /// for std::vector
/******************************************************************************
 * @namespace dp
 * @brief Dynamic programming algorithms
 *******************************************************************************/
namespace dp {

/******************************************************************************
 * @namespace partitionProblem
 * @brief Partition problem algorithm
 *******************************************************************************/
namespace partitionProblem {

/******************************************************************************
 * @brief Returns true if arr can be partitioned in two subsets of equal sum,
 * otherwise false
 * @param arr vector containing elements
 * @param size Size of the vector.
 * @returns @param bool whether the vector can be partitioned or not.
 *******************************************************************************/
bool findPartiion(const std::vector<uint64_t> &arr, uint64_t size) {
    uint64_t sum = std::accumulate(arr.begin(), arr.end(),
                                   0);  // Calculate sum of all elements

    if (sum % 2 != 0) {
        return false;  // if sum is odd, it cannot be divided into two equal sum
    }
    std::vector<bool> part;
    // bool part[sum / 2 + 1];

    // Initialize the part array as 0
    for (uint64_t it = 0; it <= sum / 2; ++it) {
        part.push_back(false);
    }

    // Fill the partition table in bottom up manner
    for (uint64_t it = 0; it < size; ++it) {
        // The element to be included in the sum cannot be greater than the sum
        for (uint64_t it2 = sum / 2; it2 >= arr[it];
             --it2) {  // Check if sum - arr[i]
            // ould be formed from a subset using elements before index i
            if (part[it2 - arr[it]] == 1 || it2 == arr[it]) {
                part[it2] = true;
            }
        }
    }
    return part[sum / 2];
}
}  // namespace partitionProblem
}  // namespace dp

/*******************************************************************************
 * @brief Self-test implementations
 * @returns void
 *******************************************************************************/
static void test() {
    std::vector<uint64_t> arr = {{1, 3, 3, 2, 3, 2}};
    uint64_t n = arr.size();
    bool expected_result = true;
    bool derived_result = dp::partitionProblem::findPartiion(arr, n);
    std::cout << "1st test: ";
    assert(expected_result == derived_result);
    std::cout << "Passed!" << std::endl;
}

/*******************************************************************************
 * @brief Main function
 * @returns 0 on exit
 *******************************************************************************/
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Reworked solver for the equal-sum partition problem: can a
 * multiset of positive integers be split into two subsets with matching
 * totals?
 *
 * @details
 * First we sum everything up; an odd total immediately rules out an
 * even split. Otherwise we hunt for a subset whose sum equals half the
 * total, using a classic 0/1-knapsack style boolean table filled from
 * the top of the sum range down (so each item is only used once).
 */
#include <cassert>   /// for assert
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for std::cout
#include <numeric>   /// for std::accumulate
#include <vector>    /// for std::vector

namespace dp {

namespace partitionProblem {

/**
 * @brief Determines whether the given multiset can be split into two
 * subsets of equal sum.
 * @param values the numbers to partition
 * @param count how many numbers are in `values`
 * @returns true if an equal-sum split exists, false otherwise
 */
bool canSplitEvenly(const std::vector<uint64_t> &values, uint64_t count) {
    uint64_t total = std::accumulate(values.begin(), values.end(),
                                      static_cast<uint64_t>(0));

    if (total % 2 != 0) {
        // odd totals can never be split into two equal halves
        return false;
    }

    uint64_t half = total / 2;
    std::vector<bool> reachable(half + 1, false);

    // for each candidate value, update which sums up to `half` become
    // reachable; iterate downward so we never reuse an item twice
    for (uint64_t itemIdx = 0; itemIdx < count; ++itemIdx) {
        uint64_t item = values[itemIdx];
        for (uint64_t target = half; target >= item; --target) {
            if (target == item || reachable[target - item]) {
                reachable[target] = true;
            }
            if (target == 0) {
                break;  // guard against uint64_t underflow on decrement
            }
        }
    }

    return reachable[half];
}

}  // namespace partitionProblem
}  // namespace dp

/**
 * @brief Sanity check against a known-splittable multiset.
 */
static void runChecks() {
    std::vector<uint64_t> sample = {1, 3, 3, 2, 3, 2};
    uint64_t total = sample.size();
    bool expected = true;
    bool actual = dp::partitionProblem::canSplitEvenly(sample, total);
    std::cout << "Equal-sum partition check: ";
    assert(expected == actual);
    std::cout << "Passed!" << std::endl;
}

int main() {
    runChecks();
    return 0;
}

