 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // execute the test
    return 0;
}

/**
 * @file
 * @brief Alternate memoized solution to the subset-sum decision problem:
 * does some subset of the array add up to exactly a given target?
 *
 * @details
 * Explores the classic "include or exclude the current element" recursion
 * tree, but caches answers per (index, remainingTarget) pair in a vector
 * of hash maps so overlapping subproblems are only solved once. Overall
 * complexity is roughly O(n * targetRange).
 * e.g. values = [1, -10, 2, 31, -6], target = -14 -> true, via
 * (-10) + 2 + (-6) = -14.
 */

#include <cassert>        /// for assert
#include <iostream>       /// for std::cout
#include <unordered_map>  /// for std::unordered_map
#include <vector>         /// for std::vector

namespace dynamic_programming {

namespace subset_sum {

/**
 * @brief Recursive helper with memoization that decides whether a
 * remaining-target subset can be formed from the elements at or after
 * `position`.
 * @param values the full input array
 * @param remaining the sum still needed
 * @param memo per-index cache of previously computed answers
 * @param position current index being considered
 * @returns whether such a subset exists
 */
bool canReachTarget(const std::vector<int> &values, int remaining,
                     std::vector<std::unordered_map<int, bool>> *memo,
                     int position = 0) {
    if (remaining == 0) {
        // exact match found, no more elements needed
        return true;
    }
    if (position == static_cast<int>(values.size())) {
        // ran out of elements without hitting the target
        return false;
    }

    auto &cacheForPosition = (*memo)[position];
    auto cached = cacheForPosition.find(remaining);
    if (cached != cacheForPosition.end()) {
        return cached->second;
    }

    bool takeCurrent =
        canReachTarget(values, remaining - values[position], memo, position + 1);
    bool skipCurrent = takeCurrent
                            ? true
                            : canReachTarget(values, remaining, memo, position + 1);

    bool outcome = takeCurrent || skipCurrent;
    cacheForPosition[remaining] = outcome;
    return outcome;
}

/**
 * @brief Public entry point: checks if any subset of `values` sums to
 * `target`.
 * @param values input array
 * @param target desired subset sum
 * @returns true if such a subset exists
 */
bool subset_sum_problem(const std::vector<int> &values, const int target) {
    std::vector<std::unordered_map<int, bool>> memo(values.size());
    return canReachTarget(values, target, &memo);
}

}  // namespace subset_sum
}  // namespace dynamic_programming

/**
 * @brief Runs a handful of known-answer checks.
 */
static void runChecks() {
    std::vector<std::vector<int>> arrays{
        {1, -10, 2, 31, -6},
        {2, 3, 4},
        {0, 1, 0, 1, 0},
    };
    std::vector<int> targets{-14, 10, 2};
    std::vector<bool> expected{true, false, true};

    for (size_t idx = 0; idx < arrays.size(); ++idx) {
        bool actual = dynamic_programming::subset_sum::subset_sum_problem(
            arrays[idx], targets[idx]);
        assert(actual == expected[idx]);
    }

    std::cout << "All tests passed successfully!\n";
}

int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Trapped Rainwater
 * Problem](https://www.geeksforgeeks.org/trapping-rain-water/)
 * @details
 * This implementation calculates the amount of rainwater that can be trapped
 * between walls represented by an array of heights.
 * @author [SOZEL](https://github.com/TruongNhanNguyen)
 */

#include <algorithm>  /// For std::min and std::max
#include <cassert>    /// For assert
#include <cstddef>    /// For std::size_t
#include <cstdint>
#include <vector>  /// For std::vector

/*
 * @namespace
 * @brief Dynamic Programming Algorithms
 */
namespace dynamic_programming {
/**
 * @brief Function to calculate the trapped rainwater
 * @param heights Array representing the heights of walls
 * @return The amount of trapped rainwater
 */
uint32_t trappedRainwater(const std::vector<uint32_t>& heights) {
    std::size_t n = heights.size();
    if (n <= 2)
        return 0;  // No water can be trapped with less than 3 walls

    std::vector<uint32_t> leftMax(n), rightMax(n);

    // Calculate the maximum height of wall to the left of each wall
    leftMax[0] = heights[0];
    for (std::size_t i = 1; i < n; ++i) {
        leftMax[i] = std::max(leftMax[i - 1], heights[i]);
    }

    // Calculate the maximum height of wall to the right of each wall
    rightMax[n - 1] = heights[n - 1];
    for (std::size_t i = n - 2; i < n; --i) {
        rightMax[i] = std::max(rightMax[i + 1], heights[i]);
    }

    // Calculate the trapped rainwater between walls
    uint32_t trappedWater = 0;
    for (std::size_t i = 0; i < n; ++i) {
        trappedWater +=
            std::max(0u, std::min(leftMax[i], rightMax[i]) - heights[i]);
    }

    return trappedWater;
}

}  // namespace dynamic_programming

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    std::vector<uint32_t> test_basic = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
    assert(dynamic_programming::trappedRainwater(test_basic) == 6);

    std::vector<uint32_t> test_peak_under_water = {3, 0, 2, 0, 4};
    assert(dynamic_programming::trappedRainwater(test_peak_under_water) == 7);

    std::vector<uint32_t> test_bucket = {5, 1, 5};
    assert(dynamic_programming::trappedRainwater(test_bucket) == 4);

    std::vector<uint32_t> test_skewed_bucket = {4, 1, 5};
    assert(dynamic_programming::trappedRainwater(test_skewed_bucket) == 3);

    std::vector<uint32_t> test_empty = {};
    assert(dynamic_programming::trappedRainwater(test_empty) == 0);

    std::vector<uint32_t> test_flat = {0, 0, 0, 0, 0};
    assert(dynamic_programming::trappedRainwater(test_flat) == 0);

    std::vector<uint32_t> test_no_trapped_water = {1, 1, 2, 4, 0, 0, 0};
    assert(dynamic_programming::trappedRainwater(test_no_trapped_water) == 0);

    std::vector<uint32_t> test_single_elevation = {5};
    assert(dynamic_programming::trappedRainwater(test_single_elevation) == 0);

    std::vector<uint32_t> test_two_point_elevation = {5, 1};
    assert(dynamic_programming::trappedRainwater(test_two_point_elevation) ==
           0);

    std::vector<uint32_t> test_large_elevation_map_difference = {5, 1, 6, 1,
                                                                 7, 1, 8};
    assert(dynamic_programming::trappedRainwater(
               test_large_elevation_map_difference) == 15);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Rewritten variant computing rainwater capacity trapped between bars
 * @details
 * Given a row of wall segments with varying heights, this file computes how
 * much water would pool between them after rainfall. The classic approach
 * pre-computes, for each column, the tallest wall seen so far scanning from
 * the left and from the right; the smaller of those two bounds minus the
 * local height (if positive) is the water column resting there.
 * @author (rewritten variant for educational dataset)
 */

#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <vector>

namespace dynamic_programming {

/**
 * @brief Builds a prefix array where each slot holds the maximum wall height
 * encountered from the start of the range up to and including that slot.
 */
std::vector<uint32_t> buildPrefixCeiling(const std::vector<uint32_t>& walls) {
    std::vector<uint32_t> ceiling(walls.size());
    uint32_t runningMax = 0;
    for (std::size_t idx = 0; idx < walls.size(); ++idx) {
        runningMax = std::max(runningMax, walls[idx]);
        ceiling[idx] = runningMax;
    }
    return ceiling;
}

/**
 * @brief Builds a suffix array where each slot holds the maximum wall height
 * encountered from that slot to the end of the range.
 */
std::vector<uint32_t> buildSuffixCeiling(const std::vector<uint32_t>& walls) {
    std::vector<uint32_t> ceiling(walls.size());
    uint32_t runningMax = 0;
    for (std::size_t idx = walls.size(); idx-- > 0;) {
        runningMax = std::max(runningMax, walls[idx]);
        ceiling[idx] = runningMax;
    }
    return ceiling;
}

/**
 * @brief Computes the total volume of rainwater trapped between wall bars.
 * @param wallHeights heights of consecutive unit-width wall segments
 * @return total trapped water volume
 */
uint32_t computeTrappedVolume(const std::vector<uint32_t>& wallHeights) {
    const std::size_t count = wallHeights.size();
    if (count <= 2) {
        return 0;  // fewer than three bars cannot form a basin
    }

    const std::vector<uint32_t> leftBound = buildPrefixCeiling(wallHeights);
    const std::vector<uint32_t> rightBound = buildSuffixCeiling(wallHeights);

    uint32_t poolTotal = 0;
    for (std::size_t idx = 0; idx < count; ++idx) {
        const uint32_t basinCeiling = std::min(leftBound[idx], rightBound[idx]);
        if (basinCeiling > wallHeights[idx]) {
            poolTotal += basinCeiling - wallHeights[idx];
        }
    }
    return poolTotal;
}

}  // namespace dynamic_programming

/**
 * @brief Runs a battery of sanity checks against computeTrappedVolume.
 */
static void runSanityChecks() {
    const std::vector<uint32_t> jagged = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
    assert(dynamic_programming::computeTrappedVolume(jagged) == 6);

    const std::vector<uint32_t> hiddenPeak = {3, 0, 2, 0, 4};
    assert(dynamic_programming::computeTrappedVolume(hiddenPeak) == 7);

    const std::vector<uint32_t> symmetricCup = {5, 1, 5};
    assert(dynamic_programming::computeTrappedVolume(symmetricCup) == 4);

    const std::vector<uint32_t> lopsidedCup = {4, 1, 5};
    assert(dynamic_programming::computeTrappedVolume(lopsidedCup) == 3);

    const std::vector<uint32_t> nothingHere = {};
    assert(dynamic_programming::computeTrappedVolume(nothingHere) == 0);

    const std::vector<uint32_t> levelGround = {0, 0, 0, 0, 0};
    assert(dynamic_programming::computeTrappedVolume(levelGround) == 0);

    const std::vector<uint32_t> downhillOnly = {1, 1, 2, 4, 0, 0, 0};
    assert(dynamic_programming::computeTrappedVolume(downhillOnly) == 0);

    const std::vector<uint32_t> lonelyBar = {5};
    assert(dynamic_programming::computeTrappedVolume(lonelyBar) == 0);

    const std::vector<uint32_t> pairOfBars = {5, 1};
    assert(dynamic_programming::computeTrappedVolume(pairOfBars) == 0);

    const std::vector<uint32_t> sawtooth = {5, 1, 6, 1, 7, 1, 8};
    assert(dynamic_programming::computeTrappedVolume(sawtooth) == 15);
}

/**
 * @brief Entry point that triggers the sanity checks.
 */
int main() {
    runSanityChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Trapped Rainwater
 * Problem](https://www.geeksforgeeks.org/trapping-rain-water/)
 * @details
 * This implementation calculates the total trapped rainwater using a
 * two-pointer approach. It maintains two pointers (`left` and `right`) and
 * tracks the maximum height seen so far from both ends (`leftMax` and
 * `rightMax`). At each step, the algorithm decides which side to process based
 * on which boundary is smaller, ensuring O(n) time and O(1) space complexity.
 * @author [kanavgoyal898](https://github.com/kanavgoyal898)
 */

#include <algorithm>  /// For std::min and std::max
#include <cassert>    /// For assert
#include <cstddef>    /// For std::size_t
#include <cstdint>    /// For std::uint32_t
#include <vector>     /// For std::vector

/*
 * @namespace
 * @brief Dynamic Programming Algorithms
 */
namespace dynamic_programming {
/**
 * @brief Function to calculate the trapped rainwater
 * @param heights Array representing the heights of walls
 * @return The amount of trapped rainwater
 */
uint32_t trappedRainwater(const std::vector<uint32_t>& heights) {
    std::size_t n = heights.size();
    if (n <= 2)
        return 0;  // Not enough walls to trap water

    std::size_t left = 0, right = n - 1;
    uint32_t leftMax = 0, rightMax = 0, trappedWater = 0;

    // Traverse from both ends towards the center
    while (left < right) {
        if (heights[left] < heights[right]) {
            // Water trapped depends on the tallest wall to the left
            if (heights[left] >= leftMax)
                leftMax = heights[left];  // Update left max
            else
                trappedWater +=
                    leftMax - heights[left];  // Water trapped at current left
            ++left;
        } else {
            // Water trapped depends on the tallest wall to the right
            if (heights[right] >= rightMax)
                rightMax = heights[right];  // Update right max
            else
                trappedWater +=
                    rightMax -
                    heights[right];  // Water trapped at current right
            --right;
        }
    }

    return trappedWater;
}

}  // namespace dynamic_programming

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    std::vector<uint32_t> test_basic = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
    assert(dynamic_programming::trappedRainwater(test_basic) == 6);

    std::vector<uint32_t> test_peak_under_water = {3, 0, 2, 0, 4};
    assert(dynamic_programming::trappedRainwater(test_peak_under_water) == 7);

    std::vector<uint32_t> test_bucket = {5, 1, 5};
    assert(dynamic_programming::trappedRainwater(test_bucket) == 4);

    std::vector<uint32_t> test_skewed_bucket = {4, 1, 5};
    assert(dynamic_programming::trappedRainwater(test_skewed_bucket) == 3);

    std::vector<uint32_t> test_empty = {};
    assert(dynamic_programming::trappedRainwater(test_empty) == 0);

    std::vector<uint32_t> test_flat = {0, 0, 0, 0, 0};
    assert(dynamic_programming::trappedRainwater(test_flat) == 0);

    std::vector<uint32_t> test_no_trapped_water = {1, 1, 2, 4, 0, 0, 0};
    assert(dynamic_programming::trappedRainwater(test_no_trapped_water) == 0);

    std::vector<uint32_t> test_single_elevation = {5};
    assert(dynamic_programming::trappedRainwater(test_single_elevation) == 0);

    std::vector<uint32_t> test_two_point_elevation = {5, 1};
    assert(dynamic_programming::trappedRainwater(test_two_point_elevation) ==
           0);

    std::vector<uint32_t> test_large_elevation_map_difference = {5, 1, 6, 1,
                                                                 7, 1, 8};
    assert(dynamic_programming::trappedRainwater(
               test_large_elevation_map_difference) == 15);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Rewritten two-pointer variant for the trapped rainwater problem
 * @details
 * Instead of pre-building left/right maximum arrays, this version walks two
 * cursors inward from either edge of the terrain. Whichever side currently
 * has the smaller boundary height is the side that gets advanced, since the
 * amount of water above that cursor is capped by the smaller of the two
 * running maxima. This keeps the algorithm at O(n) time and O(1) extra space.
 * @author (rewritten variant for educational dataset)
 */

#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <vector>

namespace dynamic_programming {

/**
 * @brief Computes total trapped rainwater volume using converging cursors.
 * @param terrain heights of consecutive unit-width wall segments
 * @return total trapped water volume
 */
uint32_t computeTrappedVolume(const std::vector<uint32_t>& terrain) {
    const std::size_t total = terrain.size();
    if (total <= 2) {
        return 0;  // need at least three columns to hold anything
    }

    std::size_t lowCursor = 0;
    std::size_t highCursor = total - 1;
    uint32_t seenFromLeft = 0;
    uint32_t seenFromRight = 0;
    uint32_t accumulated = 0;

    while (lowCursor < highCursor) {
        const bool leftIsShorter = terrain[lowCursor] < terrain[highCursor];

        if (leftIsShorter) {
            seenFromLeft = std::max(seenFromLeft, terrain[lowCursor]);
            accumulated += seenFromLeft - terrain[lowCursor];
            ++lowCursor;
        } else {
            seenFromRight = std::max(seenFromRight, terrain[highCursor]);
            accumulated += seenFromRight - terrain[highCursor];
            --highCursor;
        }
    }

    return accumulated;
}

}  // namespace dynamic_programming

/**
 * @brief Exercises computeTrappedVolume against known scenarios.
 */
static void runSanityChecks() {
    const std::vector<uint32_t> jagged = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
    assert(dynamic_programming::computeTrappedVolume(jagged) == 6);

    const std::vector<uint32_t> hiddenPeak = {3, 0, 2, 0, 4};
    assert(dynamic_programming::computeTrappedVolume(hiddenPeak) == 7);

    const std::vector<uint32_t> symmetricCup = {5, 1, 5};
    assert(dynamic_programming::computeTrappedVolume(symmetricCup) == 4);

    const std::vector<uint32_t> lopsidedCup = {4, 1, 5};
    assert(dynamic_programming::computeTrappedVolume(lopsidedCup) == 3);

    const std::vector<uint32_t> nothingHere = {};
    assert(dynamic_programming::computeTrappedVolume(nothingHere) == 0);

    const std::vector<uint32_t> levelGround = {0, 0, 0, 0, 0};
    assert(dynamic_programming::computeTrappedVolume(levelGround) == 0);

    const std::vector<uint32_t> downhillOnly = {1, 1, 2, 4, 0, 0, 0};
    assert(dynamic_programming::computeTrappedVolume(downhillOnly) == 0);

    const std::vector<uint32_t> lonelyBar = {5};
    assert(dynamic_programming::computeTrappedVolume(lonelyBar) == 0);

    const std::vector<uint32_t> pairOfBars = {5, 1};
    assert(dynamic_programming::computeTrappedVolume(pairOfBars) == 0);

    const std::vector<uint32_t> sawtooth = {5, 1, 6, 1, 7, 1, 8};
    assert(dynamic_programming::computeTrappedVolume(sawtooth) == 15);
}

/**
 * @brief Entry point that triggers the sanity checks.
 */
int main() {
    runSanityChecks();
    return 0;
}

// C++ Program to find height of the tree using bottom-up dynamic programming.

/*
 * Given a rooted tree with node 1.
 * Task is to find the height of the tree.
 * Example: -
 * 4
 * 1 2
 * 1 3
 * 2 4
 * which can be represented as
 *   1
 *  / \
 * 2   3
 * |
 * 4
 *
 * Height of the tree : - 2
 */

#include <iostream>
#include <vector>

// global declarations
// no of nodes max limit.
const int MAX = 1e5;
// adjacency list
std::vector<int> adj[MAX];
std::vector<bool> visited;
std::vector<int> dp;

void depth_first_search(int u) {
    visited[u] = true;
    int child_height = 1;
    for (int v : adj[u]) {
        if (!visited[v]) {
            depth_first_search(v);

            // select maximum sub-tree height from all children.
            child_height = std::max(child_height, dp[v] + 1);
        }
    }
    // assigned the max child height to current visited node.
    dp[u] = child_height;
}

int main() {
    // number of nodes
    int number_of_nodes;
    std::cout << "Enter number of nodes of the tree : " << std::endl;
    std::cin >> number_of_nodes;

    // u, v denotes an undirected edge of tree.
    int u, v;
    // Tree contains exactly n-1 edges where n denotes the number of nodes.
    std::cout << "Enter edges of the tree : " << std::endl;
    for (int i = 0; i < number_of_nodes - 1; i++) {
        std::cin >> u >> v;
        // undirected tree u -> v and v -> u.
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    // initialize all nodes as unvisited.
    visited.assign(number_of_nodes + 1, false);
    // initialize depth of all nodes to 0.
    dp.assign(number_of_nodes + 1, 0);
    // function call which will initialize the height of all nodes.
    depth_first_search(1);
    std::cout << "Height of the Tree : " << dp[1] << std::endl;
}

// C++ program that computes the height of a rooted tree via a post-order
// (children-first) traversal, memoizing each node's subtree height.

/*
 * We are handed an undirected tree rooted arbitrarily at node 1.
 * The goal: report how many edges lie on the longest downward path from
 * the root to any leaf.
 *
 * Sample layout with 4 nodes and edges (1,2) (1,3) (2,4):
 *
 *        1
 *       / \
 *      2   3
 *      |
 *      4
 *
 * The longest root-to-leaf path is 1 -> 2 -> 4, which has height 2.
 */

#include <iostream>
#include <vector>

// Upper bound on how many nodes we can support.
constexpr int kMaxNodeCount = 100000;

// adjacency[v] lists every neighbor of node v in the undirected tree.
std::vector<int> adjacency[kMaxNodeCount];
std::vector<bool> seen;
std::vector<int> subtreeHeight;

// Explores the tree rooted at `node`, filling in subtreeHeight for the
// entire subtree rooted there before returning (post-order style).
void explore(int node) {
    seen[node] = true;
    int tallestBranch = 1;

    for (int neighbor : adjacency[node]) {
        if (seen[neighbor]) {
            continue;
        }
        explore(neighbor);
        // A child contributes its own height plus the edge connecting to it.
        if (subtreeHeight[neighbor] + 1 > tallestBranch) {
            tallestBranch = subtreeHeight[neighbor] + 1;
        }
    }

    subtreeHeight[node] = tallestBranch;
}

int main() {
    int nodeCount = 0;
    std::cout << "Enter number of nodes of the tree : " << std::endl;
    std::cin >> nodeCount;

    std::cout << "Enter edges of the tree : " << std::endl;
    for (int edgeIdx = 0; edgeIdx < nodeCount - 1; ++edgeIdx) {
        int endpointA = 0;
        int endpointB = 0;
        std::cin >> endpointA >> endpointB;
        // Register the edge in both directions since the tree is undirected.
        adjacency[endpointA].push_back(endpointB);
        adjacency[endpointB].push_back(endpointA);
    }

    seen.assign(nodeCount + 1, false);
    subtreeHeight.assign(nodeCount + 1, 0);

    explore(1);

    std::cout << "Height of the Tree : " << subtreeHeight[1] << std::endl;
}

/**
 * @file
 * @brief Implementation of the Unbounded 0/1 Knapsack Problem
 *
 * @details
 * The Unbounded 0/1 Knapsack problem allows taking unlimited quantities of each
 * item. The goal is to maximize the total value without exceeding the given
 * knapsack capacity. Unlike the 0/1 knapsack, where each item can be taken only
 * once, in this variation, any item can be picked any number of times as long
 * as the total weight stays within the knapsack's capacity.
 *
 * Given a set of N items, each with a weight and a value, represented by the
 * arrays `wt` and `val` respectively, and a knapsack with a weight limit W, the
 * task is to fill the knapsack to maximize the total value.
 *
 * @note weight and value of items is greater than zero
 *
 * ### Algorithm
 * The approach uses dynamic programming to build a solution iteratively.
 * A 2D array is used for memoization to store intermediate results, allowing
 * the function to avoid redundant calculations.
 *
 * @author [Sanskruti Yeole](https://github.com/yeolesanskruti)
 * @see dynamic_programming/0_1_knapsack.cpp
 */

#include <cassert>   // For using assert function to validate test cases
#include <cstdint>   // For fixed-width integer types like std::uint16_t
#include <iostream>  // Standard input-output stream
#include <vector>    // Standard library for using dynamic arrays (vectors)

/**
 * @namespace dynamic_programming
 * @brief Namespace for dynamic programming algorithms
 */
namespace dynamic_programming {

/**
 * @namespace Knapsack
 * @brief Implementation of unbounded 0-1 knapsack problem
 */
namespace unbounded_knapsack {

/**
 * @brief Recursive function to calculate the maximum value obtainable using
 *        an unbounded knapsack approach.
 *
 * @param i Current index in the value and weight vectors.
 * @param W Remaining capacity of the knapsack.
 * @param val Vector of values corresponding to the items.
 * @note "val" data type can be changed according to the size of the input.
 * @param wt Vector of weights corresponding to the items.
 * @note "wt" data type can be changed according to the size of the input.
 * @param dp 2D vector for memoization to avoid redundant calculations.
 * @return The maximum value that can be obtained for the given index and
 * capacity.
 */
std::uint16_t KnapSackFilling(std::uint16_t i, std::uint16_t W,
                              const std::vector<std::uint16_t>& val,
                              const std::vector<std::uint16_t>& wt,
                              std::vector<std::vector<int>>& dp) {
    if (i == 0) {
        if (wt[0] <= W) {
            return (W / wt[0]) *
                   val[0];  // Take as many of the first item as possible
        } else {
            return 0;  // Can't take the first item
        }
    }
    if (dp[i][W] != -1)
        return dp[i][W];  // Return result if available

    int nottake =
        KnapSackFilling(i - 1, W, val, wt, dp);  // Value without taking item i
    int take = 0;
    if (W >= wt[i]) {
        take = val[i] + KnapSackFilling(i, W - wt[i], val, wt,
                                        dp);  // Value taking item i
    }
    return dp[i][W] =
               std::max(take, nottake);  // Store and return the maximum value
}

/**
 * @brief Wrapper function to initiate the unbounded knapsack calculation.
 *
 * @param N Number of items.
 * @param W Maximum weight capacity of the knapsack.
 * @param val Vector of values corresponding to the items.
 * @param wt Vector of weights corresponding to the items.
 * @return The maximum value that can be obtained for the given capacity.
 */
std::uint16_t unboundedKnapsack(std::uint16_t N, std::uint16_t W,
                                const std::vector<std::uint16_t>& val,
                                const std::vector<std::uint16_t>& wt) {
    if (N == 0)
        return 0;  // Expect 0 since no items
    std::vector<std::vector<int>> dp(
        N, std::vector<int>(W + 1, -1));  // Initialize memoization table
    return KnapSackFilling(N - 1, W, val, wt, dp);  // Start the calculation
}

}  // namespace unbounded_knapsack

}  // namespace dynamic_programming

