/**
 * @file
 * @brief Rewritten implementation of the Unbounded Knapsack Problem
 *
 * @details
 * In this knapsack variant, every item may be selected an unlimited number
 * of times (contrast with 0/1 knapsack, which allows each item at most
 * once). Given parallel arrays of item weights and values plus a capacity
 * limit, we want the greatest total value achievable without exceeding the
 * capacity.
 *
 * @note All weights and values are assumed strictly positive.
 *
 * ### Approach
 * A top-down recursive solution with a 2D memo table (indexed by item
 * cursor and remaining capacity) avoids recomputation of overlapping
 * subproblems.
 *
 * @see dynamic_programming/0_1_knapsack.cpp
 */

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

/**
 * @namespace dynamic_programming
 * @brief Namespace for dynamic programming algorithms
 */
namespace dynamic_programming {

/**
 * @namespace unbounded_knapsack
 * @brief Rewritten implementation of the unbounded knapsack problem
 */
namespace unbounded_knapsack {

/**
 * @brief Recursively determines the best achievable value considering items
 * [0..itemCursor] with the given remaining capacity, memoizing results.
 *
 * @param itemCursor index of the last item still eligible for selection
 * @param remainingCap capacity still available in the sack
 * @param itemValues values of each item
 * @param itemWeights weights of each item
 * @param memo memo table indexed by [itemCursor][remainingCap]
 * @return best total value obtainable
 */
std::uint16_t solveFrom(std::uint16_t itemCursor, std::uint16_t remainingCap,
                        const std::vector<std::uint16_t>& itemValues,
                        const std::vector<std::uint16_t>& itemWeights,
                        std::vector<std::vector<int>>& memo) {
    // Base case: only the first item is eligible, so cram in as many
    // copies of it as capacity allows.
    if (itemCursor == 0) {
        if (itemWeights[0] <= remainingCap) {
            return static_cast<std::uint16_t>((remainingCap / itemWeights[0]) *
                                               itemValues[0]);
        }
        return 0;
    }

    if (memo[itemCursor][remainingCap] != -1) {
        return static_cast<std::uint16_t>(memo[itemCursor][remainingCap]);
    }

    // Option A: skip this item entirely.
    const int skipValue =
        solveFrom(itemCursor - 1, remainingCap, itemValues, itemWeights, memo);

    // Option B: include another copy of this item, if it fits.
    int includeValue = 0;
    if (remainingCap >= itemWeights[itemCursor]) {
        includeValue =
            itemValues[itemCursor] +
            solveFrom(itemCursor, remainingCap - itemWeights[itemCursor],
                      itemValues, itemWeights, memo);
    }

    const int best = std::max(includeValue, skipValue);
    memo[itemCursor][remainingCap] = best;
    return static_cast<std::uint16_t>(best);
}

/**
 * @brief Entry point for computing the unbounded knapsack optimum.
 *
 * @param itemCount total number of distinct items available
 * @param capacity maximum weight the sack can carry
 * @param itemValues values of each item
 * @param itemWeights weights of each item
 * @return best total value obtainable within capacity
 */
std::uint16_t unboundedKnapsack(std::uint16_t itemCount, std::uint16_t capacity,
                                const std::vector<std::uint16_t>& itemValues,
                                const std::vector<std::uint16_t>& itemWeights) {
    if (itemCount == 0) {
        return 0;
    }
    std::vector<std::vector<int>> memo(itemCount,
                                       std::vector<int>(capacity + 1, -1));
    return solveFrom(itemCount - 1, capacity, itemValues, itemWeights, memo);
}

}  // namespace unbounded_knapsack

}  // namespace dynamic_programming

