/**
 * @file
 * @brief [Word Break Problem](https://leetcode.com/problems/word-break/)
 * @details
 * Given a non-empty string s and a dictionary wordDict containing a list of
 * non-empty words, determine if s can be segmented into a space-separated
 * sequence of one or more dictionary words.
 *
 * Note:
 * The same word in the dictionary may be reused multiple times in the
 * segmentation. You may assume the dictionary does not contain duplicate words.
 *
 * Example 1:
 * Input: s = "leetcode", wordDict = ["leet", "code"]
 * Output: true
 * Explanation: Return true because "leetcode" can be segmented as "leet code".
 *
 * Example 2:
 * Input: s = "applepenapple", wordDict = ["apple", "pen"]
 * Output: true
 * Explanation: Return true because "applepenapple" can be segmented as "apple
 * pen apple". Note that you are allowed to reuse a dictionary word.
 *
 * Example 3:
 * Input: s = "catsandog", wordDict = ["cats", "dog", "sand", "and", "cat"]
 * Output: false
 *
 * @author [Akshay Anand] (https://github.com/axayjha)
 */

#include <cassert>
#include <climits>
#include <iostream>
#include <string>
#include <unordered_set>
#include <vector>

/**
 * @namespace dynamic_programming
 * @brief Dynamic programming algorithms
 */
namespace dynamic_programming {

/**
 * @namespace word_break
 * @brief Functions for [Word Break](https://leetcode.com/problems/word-break/)
 * problem
 */
namespace word_break {

/**
 * @brief Function that checks if the string passed in param is present in
 * the the unordered_set passed
 *
 * @param str the string to be searched
 * @param strSet unordered set of string, that is to be looked into
 * @returns `true` if str is present in strSet
 * @returns `false` if str is not present in strSet
 */
bool exists(const std::string &str,
            const std::unordered_set<std::string> &strSet) {
    return strSet.find(str) != strSet.end();
}

/**
 * @brief Function that checks if the string passed in param can be
 * segmented from position 'pos', and then correctly go on to segment the
 * rest of the string correctly as well to reach a solution
 *
 * @param s the complete string to be segmented
 * @param strSet unordered set of string, that is to be used as the
 * reference dictionary
 * @param pos the index value at which we will segment string and test
 * further if it is correctly segmented at pos
 * @param dp the vector to memoize solution for each position
 * @returns `true` if a valid solution/segmentation is possible by segmenting at
 * index pos
 * @returns `false` otherwise
 */
bool check(const std::string &s, const std::unordered_set<std::string> &strSet,
           int pos, std::vector<int> *dp) {
    if (pos == s.length()) {
        // if we have reached till the end of the string, means we have
        // segmented throughout correctly hence we have a solution, thus
        // returning true
        return true;
    }

    if (dp->at(pos) != INT_MAX) {
        // if dp[pos] is not INT_MAX, means we must have saved a solution
        // for the position pos; then return if the solution at pos is true
        // or not
        return dp->at(pos) == 1;
    }

    std::string wordTillNow =
        "";  // string to save the prefixes of word till different positons

    for (int i = pos; i < s.length(); i++) {
        // Loop starting from pos to end, to check valid set of
        // segmentations if any
        wordTillNow +=
            std::string(1, s[i]);  // storing the prefix till the position i

        // if the prefix till current position is present in the dictionary
        // and the remaining substring can also be segmented legally, then
        // set solution at position pos in the memo, and return true
        if (exists(wordTillNow, strSet) && check(s, strSet, i + 1, dp)) {
            dp->at(pos) = 1;
            return true;
        }
    }
    // if function has still not returned, then there must be no legal
    // segmentation possible after segmenting at pos
    dp->at(pos) = 0;  // so set solution at pos as false
    return false;     // and return no solution at position pos
}

/**
 * @brief Function that checks if the string passed in param can be
 * segmented into the strings present in the vector.
 * In others words, it checks if any permutation of strings in
 * the vector can be concatenated to form the final string.
 *
 * @param s the complete string to be segmented
 * @param wordDict a vector of words to be used as dictionary to look into
 * @returns `true` if s can be formed by a combination of strings present in
 * wordDict
 * @return `false` otherwise
 */
bool wordBreak(const std::string &s, const std::vector<std::string> &wordDict) {
    // unordered set to store words in the dictionary for constant time
    // search
    std::unordered_set<std::string> strSet;
    for (const auto &s : wordDict) {
        strSet.insert(s);
    }
    // a vector to be used for memoization, whose value at index i will
    // tell if the string s can be segmented (correctly) at position i.
    // initializing it with INT_MAX (which will denote no solution)
    std::vector<int> dp(s.length(), INT_MAX);

    // calling check method with position = 0, to check from left
    // from where can be start segmenting the complete string in correct
    // manner
    return check(s, strSet, 0, &dp);
}

}  // namespace word_break
}  // namespace dynamic_programming

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // the complete string
    const std::string s = "applepenapple";
    // the dictionary to be used
    const std::vector<std::string> wordDict = {"apple", "pen"};

    assert(dynamic_programming::word_break::wordBreak(s, wordDict));

    // should return true, as applepenapple can be segmented as apple + pen +
    // apple
    std::cout << dynamic_programming::word_break::wordBreak(s, wordDict)
              << std::endl;
    std::cout << "Test implementation passed!\n";
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // call the test function :)

    // the complete string
    const std::string s = "applepenapple";
    // the dictionary to be used
    const std::vector<std::string> wordDict = {"apple", "pen"};

    // should return true, as applepenapple can be segmented as apple + pen +
    // apple
    std::cout << dynamic_programming::word_break::wordBreak(s, wordDict)
              << std::endl;
}

/**
 * @file
 * @brief Rewritten [Word Break](https://leetcode.com/problems/word-break/)
 * solution
 * @details
 * Given a string and a dictionary of words, decide whether the string can be
 * split into a sequence of dictionary words (words may repeat). This
 * rewrite uses top-down memoized recursion driven by a substring-existence
 * lookup backed by a hash set.
 *
 * Example 1:
 * Input: s = "leetcode", dict = ["leet", "code"]
 * Output: true
 *
 * Example 2:
 * Input: s = "applepenapple", dict = ["apple", "pen"]
 * Output: true
 *
 * Example 3:
 * Input: s = "catsandog", dict = ["cats", "dog", "sand", "and", "cat"]
 * Output: false
 *
 * @author (rewritten variant for educational dataset)
 */

#include <cassert>
#include <iostream>
#include <optional>
#include <string>
#include <unordered_set>
#include <vector>

/**
 * @namespace dynamic_programming
 * @brief Dynamic programming algorithms
 */
namespace dynamic_programming {

/**
 * @namespace word_break
 * @brief Rewritten helpers for the word break segmentation problem
 */
namespace word_break {

/**
 * @brief Tells whether a candidate substring is a member of the dictionary.
 * @param candidate substring being tested
 * @param dictionary set of legal dictionary words
 * @returns true when candidate is found in dictionary
 */
bool isDictionaryWord(const std::string& candidate,
                      const std::unordered_set<std::string>& dictionary) {
    return dictionary.count(candidate) > 0;
}

/**
 * @brief Determines whether the suffix of `text` starting at `startPos` can
 * be fully segmented into dictionary words. Uses a memo vector of optional
 * booleans keyed by starting position so repeated queries are O(1).
 *
 * @param text the full string being segmented
 * @param dictionary reference dictionary of legal words
 * @param startPos index from which segmentation is attempted
 * @param memo per-position cache of already-computed results
 * @returns true if a valid segmentation exists starting at startPos
 */
bool canSegmentFrom(const std::string& text,
                    const std::unordered_set<std::string>& dictionary,
                    std::size_t startPos,
                    std::vector<std::optional<bool>>& memo) {
    if (startPos == text.size()) {
        // Reached the end cleanly: everything before was validly segmented.
        return true;
    }

    if (memo[startPos].has_value()) {
        return memo[startPos].value();
    }

    std::string prefixSoFar;
    for (std::size_t cut = startPos; cut < text.size(); ++cut) {
        prefixSoFar.push_back(text[cut]);
        if (isDictionaryWord(prefixSoFar, dictionary) &&
            canSegmentFrom(text, dictionary, cut + 1, memo)) {
            memo[startPos] = true;
            return true;
        }
    }

    memo[startPos] = false;
    return false;
}

/**
 * @brief Checks whether `text` can be reconstructed by concatenating one or
 * more words (with repetition allowed) drawn from `dictionaryWords`.
 *
 * @param text string to segment
 * @param dictionaryWords list of allowed words
 * @returns true if such a segmentation exists, false otherwise
 */
bool wordBreak(const std::string& text,
              const std::vector<std::string>& dictionaryWords) {
    std::unordered_set<std::string> dictionary(dictionaryWords.begin(),
                                               dictionaryWords.end());
    std::vector<std::optional<bool>> memo(text.size());
    return canSegmentFrom(text, dictionary, 0, memo);
}

}  // namespace word_break
}  // namespace dynamic_programming

/**
 * @brief Exercises wordBreak against a known-good scenario.
 */
static void runDemoCheck() {
    const std::string phrase = "applepenapple";
    const std::vector<std::string> dictionary = {"apple", "pen"};

    assert(dynamic_programming::word_break::wordBreak(phrase, dictionary));

    // Expect true: "applepenapple" == "apple" + "pen" + "apple"
    std::cout << dynamic_programming::word_break::wordBreak(phrase, dictionary)
              << std::endl;
    std::cout << "Test implementation passed!\n";
}

