/**
 * @file
 * @brief A simple [Memory Game](https://en.wikipedia.org/wiki/Matching_game)
 * with **3 different sizes** and multiple letters.
 * @details
 * The game consists on finding **the pair** of all the given letters depending
 * on the table size. Once all of the instances are all found, the game will end
 * and will ask you if you'd like to play again or not.
 *
 * It provides **3 different sizes** available that the user can choose (4x2,
 * 5x2, 7x2). 7x2 being the biggest table size and hardest mode. The bigger the
 * size, **the more letters are available**.
 *
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <algorithm>  /// for std::shuffle()
#include <cstdlib>    /// for std::srand()
#include <ctime>      /// for std::time()
#include <iostream>   /// for IO operations
#include <random>     /// for std::mt19937
#include <vector>     /// for std::vector

// `Sleep` is only available in Windows in milliseconds.
// However, on Unix/Linux systems it is `sleep`, in seconds.
#ifdef _WIN32
#include <Windows.h>  /// for Sleep()
template <typename T>
constexpr typename std::enable_if<std::is_integral<T>::value, void>::type SLEEP(
    T milliseconds) {
    Sleep(milliseconds * 1000);
}
#else
#include <unistd.h>  /// for sleep()
template <typename T>
constexpr T SLEEP(T seconds) {
    return sleep(seconds);
}
#endif

/**
 * @namespace
 * @brief (Mini)game implementations.
 */
namespace games {
/**
 * @namespace
 * @brief Functions for the [Memory
 * Game](https://en.wikipedia.org/wiki/Matching_game) implementation
 */
namespace memory_game {
/**
 * @brief Utility function to verify if the given input is a number or not.
 * This is very useful to prevent the program being stuck in a loop.
 * @tparam T The type of the input
 * @param input The input to check.
 * @returns false if the input IS empty or if it contains a non-digit character
 * @returns true if the input is NOT empty and if it contains only digit
 * characters
 */
template <typename T>
bool is_number(const T &input) {
    if (std::cin.fail()) {
        std::cin.clear();
        std::cin.ignore(256, '\n');

        return false;
    }

    return true;
}

/**
 * @brief Initializes the table with the letters.
 * @tparam T The type of the table.
 * @param table The table to initialize.
 * @returns void
 */
template <typename T>
void init(std::vector<T> *table) {
    std::vector<char> letters(7);

    // Decrease / increase the number of letters depending on the size.
    if ((*table).size() == 10) {  // 5x2
        letters = {'A', 'E', 'Z', 'P', 'D'};
    } else if ((*table).size() == 8) {  // 4x2
        letters = {'A', 'E', 'Z', 'D'};
    } else if ((*table).size() == 14) {  // 7x2
        letters = {'A', 'E', 'Z', 'P', 'D', 'B', 'M'};
    }

    std::vector<char> pairs;
    for (char letter : letters) {
        pairs.push_back(letter);
        pairs.push_back(letter);
    }

    std::shuffle(pairs.begin(), pairs.end(),
                 std::mt19937(std::random_device()()));

    for (int i = 0; i < (*table).size(); i++) {
        (*table)[i] = pairs[i];
    }

    std::cout << "All available types are: ";

    for (int i = 0; i < letters.size(); i++) {
        if (i == letters.size() - 1) {
            std::cout << "and " << letters[i] << ".\n\n";
        } else {
            std::cout << letters[i] << ", ";
        }
    }
}

/**
 * @brief Utility function to print the table.
 * @tparam T The type of the table.
 * @param table The table to print.
 * @returns void
 */
template <typename T>
void print_table(const std::vector<T> &table) {
    std::cout << "| ";
    std::vector<T> table_print(table.size());

    for (int i = 0; i < table.size(); i++) {
        table_print[i] = ' ';

        if (table[i] != 0) {
            table_print[i] = table[i];
        }
    }

    for (int i = 0; i < table.size(); i++) {
        if (i % 5 == 0 && i != 0) {
            std::cout << "\n| ";
        }

        std::cout << table_print[i] << " | ";
    }
}

// Prototype function. This is needed as `ask_data` calls `reset_data`, and
// `reset_data` calls `ask_data`.
template <typename T>
void reset_data(const std::vector<T> &, int *, int *, int *);

/**
 * @brief Function that asks the user for their
 * input in the table they previously chose.
 * @tparam T The type of the table.
 * @param table The table that's used to get the user's input and data.
 * @param answer The user's answer.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns void
 */
template <typename T>
void ask_data(const std::vector<T> &table, int *answer, int *old_answer,
              int *memory_count) {
    (*old_answer) = (*answer);
    print_table(table);

    std::cout << "\n\nType your response here (number index):\n";
    std::cin >> (*answer);

    if (!is_number((*answer))) {
        std::cout << "\nYou must enter a valid number.\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }

    // Increase the memory count, which will be later on used for checking if
    // the user has already answered two values.
    (*memory_count)++;

    if (((*answer) > table.size()) || ((*answer) < 1)) {
        std::cout << "\nYou can't check a value that doesn't exist (or an "
                     "invalid number).\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }

    if ((*old_answer) == (*answer)) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }

    // If two matches are answered already, but the user checkes a non-answered
    // and an answered value, the program will mark it as no match, however, we
    // must not allow the user to check the same value twice.
    if ((table[(*answer) - 1] != 0) &&
        ((table[(*old_answer)] == 0) || (table[(*old_answer)] != 0))) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        reset_data(table, answer, old_answer, memory_count);
    }
}

/**
 * @brief Utility function that resets the data if the user enters an invalid
 * value.
 * @tparam T The type of the table.
 * @param table The table that will be used to call `ask_data()`.
 * @param answer The user's answer.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns void
 */
template <typename T>
void reset_data(const std::vector<T> &table, int *answer, int *old_answer,
                int *memory_count) {
    (*answer) = (*old_answer);
    (*memory_count)--;

    ask_data(table, answer, old_answer, memory_count);
}

/**
 * @brief Checks if the two values given by the user match.
 * @tparam T The type of the table.
 * @param table_empty The table with no values, slowly assigned from `table`
 * depending on the user's input.
 * @param table The table with the original values.
 * @param answer The user's answer.
 * @param first_time A boolean to check if the user has already answered a
 * value.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns true IF the values given by the user match
 * @returns false if the values given by the user do NOT match
 */
template <typename T>
bool match(const std::vector<T> &table, std::vector<T> *table_empty,
           const int &answer, bool *first_time, int *old_answer,
           int *memory_count) {
    if ((*first_time) == true) {
        return true;
    }

    // Search across the whole table and if the two values match, keep results,
    // otherwise, hide 'em up.
    for (int i = 0; i < table.size() + 1; i++) {
        if (i == answer) {
            if (table[i - 1] == table[(*old_answer) - 1]) {
                (*first_time) = true;
                (*memory_count) = 0;

                (*old_answer) = 0;
                return true;
            } else {
                std::cout << "\nNo match (value was " << table[i - 1]
                          << ", index is " << i << ").\n\n";

                (*table_empty)[(*old_answer) - 1] = 0;
                (*table_empty)[answer - 1] = 0;

                (*first_time) = true;
                (*memory_count) = 0;

                (*old_answer) = 0;
                return false;
            }
        }
    }

    return false;
}

/**
 * @brief Function to assign the results to the table.
 *
 * Also checkes if the user has answered all the values already, as well as
 * verify if the user made a match or not.
 * @tparam T The type of the tables.
 * @param table_empty The table with no values, slowly assigned from `table`
 * depending on the user's input.
 * @param table The table with the original values.
 * @param answer The user's answer.
 * @param first_time A boolean to check if the user has already answered a
 * value.
 * @param old_answer The user's previous answer.
 * @param memory_count A counter to check if the user has already answered two
 * values.
 * @returns void
 */
template <typename T>
void assign_results(std::vector<T> *table_empty, std::vector<T> *table,
                    int *answer, bool *first_time, int *old_answer,
                    int *memory_count) {
    // Search through the entire table and if the answer matches the index, show
    // the value. If it doesn't match, hide both the values. Don't forget to
    // keep older values already answered.
    for (int i = 0; i < (*table).size() + 1; i++) {
        if (i == (*answer)) {
            if (match((*table), table_empty, (*answer), first_time, old_answer,
                      memory_count) == true) {
                (*table_empty)[i - 1] = (*table)[i - 1];
                (*first_time) = true;
            }
        }
    }

    if ((*memory_count) == 1) {
        (*first_time) = false;
        (*memory_count) = 0;
    }

    char try_again = 'n';

    // Has the user finished the game? Use a `for` loop, and if the table is
    // full, ask the user if he wants to play again.
    for (int i = 0; i < (*table).size() + 1; i++) {
        if ((*table_empty)[i] == 0) {
            break;
        } else if (i == (*table).size() - 1) {
            print_table((*table));

            std::cout << "\n\nYou won. Congratulations! Do you want to play "
                         "again? (y/n)\n";
            std::cout
                << "Size " << (*table).size()
                << " will be used. This can be changed by re-running the game.";
            std::cin >> try_again;
            if (try_again == 'y') {
                // This is needed when checking if the user has two matches
                // already.
                for (int i = 0; i < (*table_empty).size(); i++) {
                    (*table_empty)[i] = 0;
                }

                init(table);
            } else if (try_again == 'n') {
                std::cout << "\nThanks for playing the game!\n";
                SLEEP(3);

                exit(0);
            } else {
                std::cout << "\nInvalid input (exitting...).\n";
                SLEEP(3);

                exit(0);
            }
        }
    }

    // Ask data again.
    ask_data((*table_empty), answer, old_answer, memory_count);
    assign_results(table_empty, table, answer, first_time, old_answer,
                   memory_count);
}
}  // namespace memory_game
}  // namespace games

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Start randomizer. This changes the values every time.
    std::srand(std::time(nullptr));

    int size = 0;       ///< Size of the table.
    int selection = 0;  ///< Selection of the size (4x2, 5x2, 7x2).

    int response = 0;    ///< The answer (number index) that the user chose.
    int old_answer = 0;  ///< Previous answer (number index).

    int memory_count =
        0;  ///< Counter to check if the user has already answered two values.
    bool first_time = true;  ///< Whether the user has answered 1 value or not
                             ///< (previous answered values do not count).

    std::cout << "\tMEMORY GAME\n";

    do {
        std::cout << "\n1. 4x2 (1)";
        std::cout << "\n2. 5x2 (2)";
        std::cout << "\n3. 7x2 (3)\n";

        std::cout << "\nChoose table size: ";
        std::cin >> selection;
    } while ((selection < 1 || selection > 3) &&
             (!games::memory_game::is_number(selection)));

    switch (selection) {
        case 1:
            size = 8;
            break;
        case 2:
            size = 10;
            break;
        case 3:
            size = 14;
            break;
        default:
            size = 10;
            break;
    }

    std::vector<char> table(size);
    std::vector<char> table_empty(size);

    std::cout << "\n";

    games::memory_game::init(&table);
    games::memory_game::ask_data(table_empty, &response, &old_answer,
                                 &memory_count);
    games::memory_game::assign_results(&table_empty, &table, &response,
                                       &first_time, &old_answer, &memory_count);

    return 0;
}

/**
 * @file
 * @brief A console-based tile-matching memory puzzle offering three board
 * sizes and a rotating set of letter tiles.
 * @details
 * Two hidden copies of each letter are scattered across a grid. The player
 * repeatedly reveals two cells; matching letters stay uncovered, mismatches
 * flip back down. The round ends once every tile has been paired, after
 * which the player may start a fresh round or quit.
 *
 * Board options: 4x2 (8 cells), 5x2 (10 cells), 7x2 (14 cells). Larger
 * boards draw from a bigger alphabet pool.
 *
 * @author Rewritten variant for educational similarity-detection dataset.
 */

#include <algorithm>  /// for std::shuffle()
#include <cstdlib>    /// for std::srand(), exit()
#include <ctime>      /// for std::time()
#include <iostream>   /// for IO operations
#include <random>     /// for std::mt19937
#include <vector>     /// for std::vector

// Cross-platform pause helper: Windows measures Sleep() in milliseconds,
// POSIX systems measure sleep() in whole seconds.
#ifdef _WIN32
#include <Windows.h>
template <typename DurationT>
constexpr typename std::enable_if<std::is_integral<DurationT>::value,
                                   void>::type
pause_execution(DurationT seconds) {
    Sleep(seconds * 1000);
}
#else
#include <unistd.h>
template <typename DurationT>
constexpr DurationT pause_execution(DurationT seconds) {
    return sleep(seconds);
}
#endif

/**
 * @namespace arcade
 * @brief Collection of small terminal-based games.
 */
namespace arcade {
/**
 * @namespace tile_match
 * @brief Core logic for the letter-matching memory puzzle.
 */
namespace tile_match {

/**
 * @brief Confirms that the last extraction from std::cin actually produced
 * a usable numeric value, clearing the stream on failure.
 * @tparam ValueT type of the value being validated
 * @param value the just-read value (unused directly, kept for symmetry)
 * @returns false when the stream is in a failed state, true otherwise.
 */
template <typename ValueT>
bool looks_numeric(const ValueT &value) {
    if (std::cin.fail()) {
        std::cin.clear();
        std::cin.ignore(256, '\n');
        return false;
    }
    return true;
}

/**
 * @brief Populates the board with shuffled letter pairs matching its size.
 * @tparam CellT cell value type stored in the board
 * @param board pointer to the vector representing the game board
 */
template <typename CellT>
void seed_board(std::vector<CellT> *board) {
    std::vector<char> alphabet(7);

    switch (board->size()) {
        case 8:
            alphabet = {'A', 'E', 'Z', 'D'};
            break;
        case 10:
            alphabet = {'A', 'E', 'Z', 'P', 'D'};
            break;
        case 14:
            alphabet = {'A', 'E', 'Z', 'P', 'D', 'B', 'M'};
            break;
        default:
            break;
    }

    std::vector<char> tiles;
    for (char symbol : alphabet) {
        tiles.push_back(symbol);
        tiles.push_back(symbol);
    }

    std::mt19937 rng(std::random_device{}());
    std::shuffle(tiles.begin(), tiles.end(), rng);

    for (std::size_t idx = 0; idx < board->size(); ++idx) {
        (*board)[idx] = tiles[idx];
    }

    std::cout << "All available types are: ";
    for (std::size_t idx = 0; idx < alphabet.size(); ++idx) {
        std::cout << alphabet[idx];
        if (idx + 1 == alphabet.size()) {
            std::cout << " -- that's the full set.\n\n";
        } else {
            std::cout << ", ";
        }
    }
}

/**
 * @brief Renders the current state of the board, five cells per row.
 * @tparam CellT cell value type stored in the board
 * @param board board to render
 */
template <typename CellT>
void render_board(const std::vector<CellT> &board) {
    const int columns_per_row = 5;
    std::cout << "| ";

    std::vector<CellT> visible(board.size());
    for (std::size_t idx = 0; idx < board.size(); ++idx) {
        visible[idx] = (board[idx] != 0) ? board[idx] : ' ';
    }

    for (std::size_t idx = 0; idx < visible.size(); ++idx) {
        if (idx != 0 && idx % columns_per_row == 0) {
            std::cout << "\n| ";
        }
        std::cout << visible[idx] << " | ";
    }
}

// Forward declaration: prompt_choice() and retry_prompt() are mutually
// recursive.
template <typename CellT>
void retry_prompt(const std::vector<CellT> &, int *, int *, int *);

/**
 * @brief Prompts the player for a one-based index into the board and
 * validates the response, retrying on any malformed or repeated input.
 * @tparam CellT cell value type stored in the board
 * @param board board used to display state and validate bounds
 * @param choice output: the player's latest choice
 * @param previous_choice output: the player's prior choice
 * @param picks_made counter tracking how many picks were made this turn
 */
template <typename CellT>
void prompt_choice(const std::vector<CellT> &board, int *choice,
                    int *previous_choice, int *picks_made) {
    *previous_choice = *choice;
    render_board(board);

    std::cout << "\n\nType your response here (number index):\n";
    std::cin >> *choice;

    if (!looks_numeric(*choice)) {
        std::cout << "\nYou must enter a valid number.\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }

    ++(*picks_made);

    if (*choice > static_cast<int>(board.size()) || *choice < 1) {
        std::cout << "\nYou can't check a value that doesn't exist (or an "
                     "invalid number).\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }

    if (*previous_choice == *choice) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }

    if (board[*choice - 1] != 0 &&
        (board[*previous_choice] == 0 || board[*previous_choice] != 0)) {
        std::cout << "\nYou can't check the same value twice.\n\n";
        retry_prompt(board, choice, previous_choice, picks_made);
    }
}

/**
 * @brief Rewinds the pick counter and re-issues the prompt after an
 * invalid entry.
 * @tparam CellT cell value type stored in the board
 * @param board board forwarded to prompt_choice()
 * @param choice output: the player's latest choice
 * @param previous_choice output: the player's prior choice
 * @param picks_made counter tracking how many picks were made this turn
 */
template <typename CellT>
void retry_prompt(const std::vector<CellT> &board, int *choice,
                   int *previous_choice, int *picks_made) {
    *choice = *previous_choice;
    --(*picks_made);
    prompt_choice(board, choice, previous_choice, picks_made);
}

/**
 * @brief Determines whether the two most recently picked tiles are equal.
 * @tparam CellT cell value type stored in the board
 * @param solved_board board holding the true (hidden) values
 * @param visible_board board tracking what's currently shown to the player
 * @param choice the newest pick
 * @param awaiting_first_pick whether this is the first pick of the turn
 * @param previous_choice the earlier pick this turn
 * @param picks_made counter of picks made so far this turn
 * @returns true when the two picks reveal identical letters (or when this
 * is only the first pick of the turn), false on a mismatch.
 */
template <typename CellT>
bool tiles_match(const std::vector<CellT> &solved_board,
                  std::vector<CellT> *visible_board, const int &choice,
                  bool *awaiting_first_pick, int *previous_choice,
                  int *picks_made) {
    if (*awaiting_first_pick) {
        return true;
    }

    for (std::size_t idx = 0; idx < solved_board.size() + 1; ++idx) {
        if (static_cast<int>(idx) != choice) {
            continue;
        }

        bool same = solved_board[idx - 1] == solved_board[*previous_choice - 1];
        *awaiting_first_pick = true;
        *picks_made = 0;
        *previous_choice = 0;

        if (same) {
            return true;
        }

        std::cout << "\nNo match (value was " << solved_board[idx - 1]
                   << ", index is " << idx << ").\n\n";
        (*visible_board)[*previous_choice - 1] = 0;
        (*visible_board)[choice - 1] = 0;
        return false;
    }

    return false;
}

/**
 * @brief Applies the outcome of the latest pick to the visible board,
 * checks for a completed round, and loops back for the next pick.
 * @tparam CellT cell value type stored in the board
 * @param visible_board board tracking what's currently shown to the player
 * @param solved_board board holding the true (hidden) values
 * @param choice the newest pick
 * @param awaiting_first_pick whether the next pick starts a fresh turn
 * @param previous_choice the earlier pick this turn
 * @param picks_made counter of picks made so far this turn
 */
template <typename CellT>
void apply_turn(std::vector<CellT> *visible_board,
                 std::vector<CellT> *solved_board, int *choice,
                 bool *awaiting_first_pick, int *previous_choice,
                 int *picks_made) {
    for (std::size_t idx = 0; idx < solved_board->size() + 1; ++idx) {
        if (static_cast<int>(idx) == *choice) {
            if (tiles_match(*solved_board, visible_board, *choice,
                            awaiting_first_pick, previous_choice, picks_made)) {
                (*visible_board)[idx - 1] = (*solved_board)[idx - 1];
                *awaiting_first_pick = true;
            }
        }
    }

    if (*picks_made == 1) {
        *awaiting_first_pick = false;
        *picks_made = 0;
    }

    bool round_complete = true;
    for (std::size_t idx = 0; idx < visible_board->size(); ++idx) {
        if ((*visible_board)[idx] == 0) {
            round_complete = false;
            break;
        }
    }

    if (round_complete) {
        render_board(*solved_board);
        std::cout << "\n\nYou won. Congratulations! Do you want to play "
                     "again? (y/n)\n";
        std::cout << "Size " << solved_board->size()
                   << " will be used. This can be changed by re-running the "
                      "game.";

        char play_again = 'n';
        std::cin >> play_again;

        if (play_again == 'y') {
            std::fill(visible_board->begin(), visible_board->end(), 0);
            seed_board(solved_board);
        } else if (play_again == 'n') {
            std::cout << "\nThanks for playing the game!\n";
            pause_execution(3);
            exit(0);
        } else {
            std::cout << "\nInvalid input (exitting...).\n";
            pause_execution(3);
            exit(0);
        }
    }

    prompt_choice(*visible_board, choice, previous_choice, picks_made);
    apply_turn(visible_board, solved_board, choice, awaiting_first_pick,
               previous_choice, picks_made);
}

}  // namespace tile_match
}  // namespace arcade

/**
 * @brief Entry point: gathers the board-size selection then hands off to
 * the game loop.
 * @returns 0 on exit
 */
int main() {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    int board_cells = 0;
    int size_choice = 0;

    int player_pick = 0;
    int prior_pick = 0;

    int picks_this_turn = 0;
    bool awaiting_first_pick = true;

    std::cout << "\tMEMORY GAME\n";

    do {
        std::cout << "\n1. 4x2 (1)";
        std::cout << "\n2. 5x2 (2)";
        std::cout << "\n3. 7x2 (3)\n";
        std::cout << "\nChoose table size: ";
        std::cin >> size_choice;
    } while ((size_choice < 1 || size_choice > 3) &&
             !arcade::tile_match::looks_numeric(size_choice));

    switch (size_choice) {
        case 1:
            board_cells = 8;
            break;
        case 2:
            board_cells = 10;
            break;
        case 3:
            board_cells = 14;
            break;
        default:
            board_cells = 10;
            break;
    }

    std::vector<char> solved_board(board_cells);
    std::vector<char> visible_board(board_cells);

    std::cout << "\n";

    arcade::tile_match::seed_board(&solved_board);
    arcade::tile_match::prompt_choice(visible_board, &player_pick, &prior_pick,
                                       &picks_this_turn);
    arcade::tile_match::apply_turn(&visible_board, &solved_board, &player_pick,
                                    &awaiting_first_pick, &prior_pick,
                                    &picks_this_turn);

    return 0;
}

/******************************************************************************
 * @file
 * @brief Implementation of the [Convex
 * Hull](https://en.wikipedia.org/wiki/Convex_hull) implementation using [Graham
 * Scan](https://en.wikipedia.org/wiki/Graham_scan)
 * @details
 * In geometry, the convex hull or convex envelope or convex closure of a shape
 * is the smallest convex set that contains it. The convex hull may be defined
 * either as the intersection of all convex sets containing a given subset of a
 * Euclidean space, or equivalently as the set of all convex combinations of
 * points in the subset. For a bounded subset of the plane, the convex hull may
 * be visualized as the shape enclosed by a rubber band stretched around the
 * subset.
 *
 * The worst case time complexity of Jarvis’s Algorithm is O(n^2). Using
 * Graham’s scan algorithm, we can find Convex Hull in O(nLogn) time.
 *
 * ### Implementation
 *
 * Sort points
 * We first find the bottom-most point. The idea is to pre-process
 * points be sorting them with respect to the bottom-most point. Once the points
 * are sorted, they form a simple closed path.
 * The sorting criteria is to use the orientation to compare angles without
 * actually computing them (See the compare() function below) because
 * computation of actual angles would be inefficient since trigonometric
 * functions are not simple to evaluate.
 *
 * Accept or Reject Points
 * Once we have the closed path, the next step is to traverse the path and
 * remove concave points on this path using orientation. The first two points in
 * sorted array are always part of Convex Hull. For remaining points, we keep
 * track of recent three points, and find the angle formed by them. Let the
 * three points be prev(p), curr(c) and next(n). If the orientation of these
 * points (considering them in the same order) is not counterclockwise, we
 * discard c, otherwise we keep it.
 *
 * @author [Lajat Manekar](https://github.com/Lazeeez)
 *
 *******************************************************************************/
#include <cassert>   /// for std::assert
#include <iostream>  /// for IO Operations
#include <vector>    /// for std::vector

#include "./graham_scan_functions.hpp"  /// for all the functions used

/*******************************************************************************
 * @brief Self-test implementations
 * @returns void
 *******************************************************************************/
static void test() {
    std::vector<geometry::grahamscan::Point> points = {
        {0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}};
    std::vector<geometry::grahamscan::Point> expected_result = {
        {0, 3}, {4, 4}, {3, 1}, {0, 0}};
    std::vector<geometry::grahamscan::Point> derived_result;
    std::vector<geometry::grahamscan::Point> res;

    derived_result = geometry::grahamscan::convexHull(points, points.size());

    std::cout << "1st test: ";
    for (int i = 0; i < expected_result.size(); i++) {
        assert(derived_result[i].x == expected_result[i].x);
        assert(derived_result[i].y == expected_result[i].y);
    }
    std::cout << "passed!" << std::endl;
}

/*******************************************************************************
 * @brief Main function
 * @returns 0 on exit
 *******************************************************************************/
int main() {
    test();  // run self-test implementations
    return 0;
}

/******************************************************************************
 * @file
 * @brief Self-contained variant computing the [Convex
 * Hull](https://en.wikipedia.org/wiki/Convex_hull) of a 2D point set via the
 * [Graham Scan](https://en.wikipedia.org/wiki/Graham_scan) technique.
 * @details
 * A convex hull is the smallest convex polygon enclosing a set of points --
 * picture stretching a rubber band around every point and letting it snap
 * tight.
 *
 * The approach here:
 *   1. Pick the point with the lowest y-coordinate (ties broken by lowest
 *      x) as a fixed anchor.
 *   2. Sort every other point by the polar angle they make with that
 *      anchor, so walking the sorted list traces a simple, non-crossing
 *      path.
 *   3. Walk the sorted path with a stack, popping the last accepted point
 *      whenever adding the next point would create a clockwise (i.e.
 *      "concave") turn.
 *
 * Jarvis's March runs in O(n^2); this angular-sort approach runs in
 * O(n log n) thanks to the sorting step dominating.
 *
 * @author Rewritten variant for educational similarity-detection dataset.
 ******************************************************************************/
#include <algorithm>  /// for std::swap, std::sort
#include <cassert>    /// for assert
#include <cstdint>    /// for uint64_t
#include <iostream>   /// for IO operations
#include <stack>      /// for std::stack
#include <vector>     /// for std::vector

/******************************************************************************
 * @namespace geometry
 * @brief Geometric algorithms
 ******************************************************************************/
namespace geometry {

/******************************************************************************
 * @namespace hull_by_angle
 * @brief Angular-sort convex hull construction (Graham's scan variant)
 ******************************************************************************/
namespace hull_by_angle {

/******************************************************************************
 * @struct Coord
 * @brief Simple 2D integer coordinate.
 ******************************************************************************/
struct Coord {
    int x, y;
};

// Anchor point that every other point is measured against while sorting.
static Coord anchor;

/******************************************************************************
 * @brief Retrieves the point just below the top of a stack without
 * mutating the stack's final contents.
 * @param history stack of accepted hull points
 * @returns the coordinate one below the current top
 ******************************************************************************/
Coord peek_below_top(std::stack<Coord> *history) {
    Coord top_point = history->top();
    history->pop();
    Coord second_point = history->top();
    history->push(top_point);
    return second_point;
}

/******************************************************************************
 * @brief Squared Euclidean distance -- avoids a sqrt() call since only
 * relative ordering matters here.
 * @param a first coordinate
 * @param b second coordinate
 * @returns squared distance between a and b
 ******************************************************************************/
int squared_distance(Coord a, Coord b) {
    return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
}

/******************************************************************************
 * @brief Determines the turn direction formed by three ordered points.
 * @param a first point
 * @param b second point (the pivot of the turn)
 * @param c third point
 * @returns 0 when collinear, 1 when clockwise, 2 when counterclockwise
 ******************************************************************************/
int turn_direction(Coord a, Coord b, Coord c) {
    int cross = (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y);
    if (cross == 0) {
        return 0;
    }
    return (cross > 0) ? 1 : 2;
}

/******************************************************************************
 * @brief Comparator ordering points by polar angle around `anchor`, with
 * ties broken by placing the farther point later.
 * @param lhs left-hand coordinate
 * @param rhs right-hand coordinate
 * @returns true if lhs should precede rhs in angular order
 ******************************************************************************/
bool angular_less(const Coord &lhs, const Coord &rhs) {
    int orient = turn_direction(anchor, lhs, rhs);
    if (orient == 0) {
        return squared_distance(anchor, rhs) >= squared_distance(anchor, lhs);
    }
    return orient == 2;
}

/******************************************************************************
 * @brief Computes the convex hull of the given point cloud.
 * @param cloud vector of input coordinates (taken by value; reordered
 * internally)
 * @param count number of points to consider from `cloud`
 * @returns vector of coordinates forming the convex hull boundary
 ******************************************************************************/
std::vector<Coord> build_hull(std::vector<Coord> cloud, uint64_t count) {
    // Locate the bottom-most point (break ties toward the leftmost).
    int lowest_y = cloud[0].y;
    std::size_t anchor_index = 0;
    for (std::size_t i = 1; i < count; ++i) {
        int y = cloud[i].y;
        if (y < lowest_y || (y == lowest_y && cloud[i].x < cloud[anchor_index].x)) {
            lowest_y = cloud[i].y;
            anchor_index = i;
        }
    }

    std::swap(cloud[0], cloud[anchor_index]);
    anchor = cloud[0];

    std::sort(cloud.begin() + 1, cloud.begin() + count, angular_less);

    // Collapse runs of collinear points, keeping only the farthest of
    // each run.
    std::size_t kept = 1;
    for (std::size_t i = 1; i < count; ++i) {
        while (i < count - 1 && turn_direction(anchor, cloud[i], cloud[i + 1]) == 0) {
            ++i;
        }
        cloud[kept] = cloud[i];
        ++kept;
    }

    if (kept < 3) {
        return {};
    }

    std::stack<Coord> accepted;
    accepted.push(cloud[0]);
    accepted.push(cloud[1]);
    accepted.push(cloud[2]);

    for (std::size_t i = 3; i < kept; ++i) {
        while (accepted.size() > 1 &&
               turn_direction(peek_below_top(&accepted), accepted.top(), cloud[i]) != 2) {
            accepted.pop();
        }
        accepted.push(cloud[i]);
    }

    std::vector<Coord> boundary;
    while (!accepted.empty()) {
        boundary.push_back(accepted.top());
        accepted.pop();
    }

    return boundary;
}

}  // namespace hull_by_angle
}  // namespace geometry

/*******************************************************************************
 * @brief Exercises build_hull() against a known point set and expected
 * boundary.
 * @returns void
 *******************************************************************************/
static void verify_known_hull() {
    std::vector<geometry::hull_by_angle::Coord> sample = {
        {0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}};
    std::vector<geometry::hull_by_angle::Coord> expected = {
        {0, 3}, {4, 4}, {3, 1}, {0, 0}};

    std::vector<geometry::hull_by_angle::Coord> actual =
        geometry::hull_by_angle::build_hull(sample, sample.size());

    std::cout << "Convex hull regression check: ";
    for (std::size_t i = 0; i < expected.size(); ++i) {
        assert(actual[i].x == expected[i].x);
        assert(actual[i].y == expected[i].y);
    }
    std::cout << "passed!" << std::endl;
}

/*******************************************************************************
 * @brief Main function
 * @returns 0 on exit
 *******************************************************************************/
int main() {
    verify_known_hull();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Jarvis’s](https://en.wikipedia.org/wiki/Gift_wrapping_algorithm) algorithm.
 *
 * @details
 * Given a set of points in the plane. the convex hull of the set
 * is the smallest convex polygon that contains all the points of it.
 *
 * ### Algorithm
 * The idea of Jarvis’s Algorithm is simple, we start from the leftmost point
 * (or point with minimum x coordinate value) and we
 * keep wrapping points in counterclockwise direction.
 *
 * The idea is to use orientation() here. Next point is selected as the
 * point that beats all other points at counterclockwise orientation, i.e.,
 * next point is q if for any other point r,
 * we have “orientation(p, q, r) = counterclockwise”.
 *
 * For Example,
 * If points = {{0, 3}, {2, 2}, {1, 1}, {2, 1},
                      {3, 0}, {0, 0}, {3, 3}};
 *
 * then the convex hull is
 * (0, 3), (0, 0), (3, 0), (3, 3)
 *
 * @author [Rishabh Agarwal](https://github.com/rishabh-997)
 */

#include <vector>
#include <cassert>
#include <iostream>

/**
 *  @namespace geometry
 *  @brief Geometry algorithms
 */
namespace geometry {
    /**
     * @namespace jarvis
     * @brief Functions for [Jarvis’s](https://en.wikipedia.org/wiki/Gift_wrapping_algorithm) algorithm
     */
    namespace jarvis {
        /**
         * Structure defining the x and y co-ordinates of the given
         * point in space
         */
        struct Point {
            int x, y;
        };

        /**
         * Class which can be called from main and is globally available
         * throughout the code
         */
        class Convexhull {
            std::vector<Point> points;
            int size;

        public:
            /**
             * Constructor of given class
             *
             * @param pointList list of all points in the space
             * @param n number of points in space
             */
            explicit Convexhull(const std::vector<Point> &pointList) {
                points = pointList;
                size = points.size();
            }

            /**
             * Creates convex hull of a set of n points.
             * There must be 3 points at least for the convex hull to exist
             *
             * @returns an vector array containing points in space
             * which enclose all given points thus forming a hull
             */
            std::vector<Point> getConvexHull() const {
                // Initialize Result
                std::vector<Point> hull;

                // Find the leftmost point
                int leftmost_point = 0;
                for (int i = 1; i < size; i++) {
                    if (points[i].x < points[leftmost_point].x) {
                        leftmost_point = i;
                    }
                }
                // Start from leftmost point, keep moving counterclockwise
                // until reach the start point again.  This loop runs O(h)
                // times where h is number of points in result or output.
                int p = leftmost_point, q = 0;
                do {
                    // Add current point to result
                    hull.push_back(points[p]);

                    // Search for a point 'q' such that orientation(p, x, q)
                    // is counterclockwise for all points 'x'. The idea
                    // is to keep track of last visited most counter clock-
                    // wise point in q. If any point 'i' is more counter clock-
                    // wise than q, then update q.
                    q = (p + 1) % size;
                    for (int i = 0; i < size; i++) {
                        // If i is more counterclockwise than current q, then
                        // update q
                        if (orientation(points[p], points[i], points[q]) == 2) {
                            q = i;
                        }
                    }

                    // Now q is the most counterclockwise with respect to p
                    // Set p as q for next iteration, so that q is added to
                    // result 'hull'
                    p = q;

                } while (p != leftmost_point);        // While we don't come to first point

                return hull;
            }

            /**
             * This function returns the geometric orientation for the three points
             * in a space, ie, whether they are linear ir clockwise or
             * anti-clockwise
             * @param p first point selected
             * @param q adjacent point for q
             * @param r adjacent point for q
             *
             * @returns 0 -> Linear
             * @returns 1 -> Clock Wise
             * @returns 2 -> Anti Clock Wise
             */
            static int orientation(const Point &p, const Point &q, const Point &r) {
                int val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);

                if (val == 0) {
                    return 0;
                }
                return (val > 0) ? 1 : 2;
            }

        };

    } // namespace jarvis
} // namespace geometry

/**
 * Test function
 * @returns void
 */
static void test() {
    std::vector<geometry::jarvis::Point> points = {{0, 3},
                                                   {2, 2},
                                                   {1, 1},
                                                   {2, 1},
                                                   {3, 0},
                                                   {0, 0},
                                                   {3, 3}
    };
    geometry::jarvis::Convexhull hull(points);
    std::vector<geometry::jarvis::Point> actualPoint;
    actualPoint = hull.getConvexHull();

    std::vector<geometry::jarvis::Point> expectedPoint = {{0, 3},
                                                          {0, 0},
                                                          {3, 0},
                                                          {3, 3}};
    for (int i = 0; i < expectedPoint.size(); i++) {
        assert(actualPoint[i].x == expectedPoint[i].x);
        assert(actualPoint[i].y == expectedPoint[i].y);
    }
    std::cout << "Test implementations passed!\n";
}

/** Driver Code */
int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [gift-wrapping (Jarvis's)
 * algorithm](https://en.wikipedia.org/wiki/Gift_wrapping_algorithm) for
 * convex hull construction.
 *
 * @details
 * Given a scattered set of 2D points, the convex hull is the smallest
 * convex polygon that encloses every one of them.
 *
 * ### Approach
 * Start at the point with the smallest x-coordinate (guaranteed to lie on
 * the hull) and repeatedly "wrap" to the next hull vertex by picking
 * whichever candidate point keeps every other point on the same side --
 * i.e., the most counterclockwise candidate relative to the current edge.
 * Stop once the walk returns to the starting point.
 *
 * Example: for points {(0,3), (2,2), (1,1), (2,1), (3,0), (0,0), (3,3)}
 * the resulting hull is (0,3), (0,0), (3,0), (3,3).
 *
 * @author Rewritten variant for educational similarity-detection dataset.
 */

#include <cassert>
#include <iostream>
#include <vector>

/**
 *  @namespace geometry
 *  @brief Geometry algorithms
 */
namespace geometry {
/**
 * @namespace gift_wrap
 * @brief Gift-wrapping (Jarvis's march) convex hull implementation
 */
namespace gift_wrap {

/**
 * A single 2D coordinate with integer components.
 */
struct Vertex {
    int x, y;
};

/**
 * @brief Determines the turn direction of an ordered vertex triple.
 * @param origin the pivot vertex
 * @param mid the vertex the turn is measured through
 * @param dest the destination vertex
 * @returns 0 when collinear, 1 when clockwise, 2 when counterclockwise
 */
inline int turn_kind(const Vertex &origin, const Vertex &mid,
                      const Vertex &dest) {
    int cross = (mid.y - origin.y) * (dest.x - mid.x) -
                (mid.x - origin.x) * (dest.y - mid.y);

    if (cross == 0) {
        return 0;
    }
    return (cross > 0) ? 1 : 2;
}

/**
 * Wraps a point cloud with a convex boundary using the gift-wrapping
 * technique. Exposed as a small value type so callers can build one from a
 * point list and immediately ask for the hull.
 */
class HullWrapper {
    std::vector<Vertex> cloud;
    std::size_t count;

 public:
    /**
     * @brief Builds a wrapper around the given point list.
     * @param source the points to wrap
     */
    explicit HullWrapper(const std::vector<Vertex> &source) {
        cloud = source;
        count = cloud.size();
    }

    /**
     * @brief Produces the convex hull boundary for the wrapped points.
     * Requires at least 3 points for a non-degenerate hull.
     * @returns the ordered vertices forming the hull
     */
    std::vector<Vertex> trace_boundary() const {
        std::vector<Vertex> boundary;
        if (count < 3) {
            return boundary;
        }

        std::size_t start = 0;
        for (std::size_t i = 1; i < count; ++i) {
            if (cloud[i].x < cloud[start].x) {
                start = i;
            }
        }

        std::size_t current = start;
        std::size_t candidate;
        do {
            boundary.push_back(cloud[current]);

            candidate = (current + 1) % count;
            for (std::size_t i = 0; i < count; ++i) {
                if (turn_kind(cloud[current], cloud[i], cloud[candidate]) == 2) {
                    candidate = i;
                }
            }

            current = candidate;
        } while (current != start);

        return boundary;
    }
};

}  // namespace gift_wrap
}  // namespace geometry

/**
 * Regression check comparing the wrapper's output against a known hull.
 * @returns void
 */
static void run_regression_check() {
    std::vector<geometry::gift_wrap::Vertex> cloud = {
        {0, 3}, {2, 2}, {1, 1}, {2, 1}, {3, 0}, {0, 0}, {3, 3}};

    geometry::gift_wrap::HullWrapper wrapper(cloud);
    std::vector<geometry::gift_wrap::Vertex> produced = wrapper.trace_boundary();

    std::vector<geometry::gift_wrap::Vertex> expected = {
        {0, 3}, {0, 0}, {3, 0}, {3, 3}};

    for (std::size_t i = 0; i < expected.size(); ++i) {
        assert(produced[i].x == expected[i].x);
        assert(produced[i].y == expected[i].y);
    }
    std::cout << "Gift-wrapping regression check passed!\n";
}

/** Driver Code */
int main() {
    run_regression_check();
    return 0;
}

/**
 * @file
 * @brief check whether two line segments intersect each other
 * or not.
 */
#include <algorithm>
#include <iostream>

/**
 * Define a Point.
 */
struct Point {
    int x;  /// Point respect to x coordinate
    int y;  /// Point respect to y coordinate
};

/**
 * intersect returns true if segments of two line intersects and
 * false if they do not. It calls the subroutines direction
 * which computes the orientation.
 */
struct SegmentIntersection {
    inline bool intersect(Point first_point, Point second_point,
                          Point third_point, Point forth_point) {
        int direction1 = direction(third_point, forth_point, first_point);
        int direction2 = direction(third_point, forth_point, second_point);
        int direction3 = direction(first_point, second_point, third_point);
        int direction4 = direction(first_point, second_point, forth_point);

        if ((direction1 < 0 || direction2 > 0) &&
            (direction3 < 0 || direction4 > 0))
            return true;

        else if (direction1 == 0 &&
                 on_segment(third_point, forth_point, first_point))
            return true;

        else if (direction2 == 0 &&
                 on_segment(third_point, forth_point, second_point))
            return true;

        else if (direction3 == 0 &&
                 on_segment(first_point, second_point, third_point))
            return true;

        else if (direction3 == 0 &&
                 on_segment(first_point, second_point, forth_point))
            return true;

        else
            return false;
    }

    /**
     * We will find direction of line here respect to @first_point.
     * Here @second_point and @third_point is first and second points
     * of the line respectively. we want a method to determine which way a
     * given angle these three points turns. If returned number is negative,
     * then the angle is counter-clockwise. That means the line is going to
     * right to left. We will fount angle as clockwise if the method returns
     * positive number.
     */
    inline int direction(Point first_point, Point second_point,
                         Point third_point) {
        return ((third_point.x - first_point.x) *
                (second_point.y - first_point.y)) -
               ((second_point.x - first_point.x) *
                (third_point.y - first_point.y));
    }

    /**
     * This method determines whether a point known to be colinear
     * with a segment lies on that segment.
     */
    inline bool on_segment(Point first_point, Point second_point,
                           Point third_point) {
        if (std::min(first_point.x, second_point.x) <= third_point.x &&
            third_point.x <= std::max(first_point.x, second_point.x) &&
            std::min(first_point.y, second_point.y) <= third_point.y &&
            third_point.y <= std::max(first_point.y, second_point.y))
            return true;

        else
            return false;
    }
};

/**
 * This is the main function to test whether the algorithm is
 * working well.
 */
int main() {
    SegmentIntersection segment;
    Point first_point, second_point, third_point, forth_point;

    std::cin >> first_point.x >> first_point.y;
    std::cin >> second_point.x >> second_point.y;
    std::cin >> third_point.x >> third_point.y;
    std::cin >> forth_point.x >> forth_point.y;

    printf("%d", segment.intersect(first_point, second_point, third_point,
                                   forth_point));
    std::cout << std::endl;
}

/**
 * @file
 * @brief Determine whether two 2D line segments cross each other.
 * Uses the standard orientation-test approach with a colinear/on-segment
 * fallback check.
 */
#include <algorithm>
#include <iostream>

/**
 * A simple 2D coordinate.
 */
struct Coord2D {
    int px;  /// horizontal coordinate
    int py;  /// vertical coordinate
};

/**
 * Encapsulates the segment-intersection test. orientationOf() computes the
 * turn direction of a triple of points, and liesBetween() checks whether a
 * colinear point actually falls within the bounding box of a segment.
 */
struct SegmentCrossTest {
    inline bool crosses(Coord2D a1, Coord2D a2, Coord2D b1, Coord2D b2) {
        int o1 = orientationOf(b1, b2, a1);
        int o2 = orientationOf(b1, b2, a2);
        int o3 = orientationOf(a1, a2, b1);
        int o4 = orientationOf(a1, a2, b2);

        if ((o1 < 0 || o2 > 0) && (o3 < 0 || o4 > 0)) {
            return true;
        } else if (o1 == 0 && liesBetween(b1, b2, a1)) {
            return true;
        } else if (o2 == 0 && liesBetween(b1, b2, a2)) {
            return true;
        } else if (o3 == 0 && liesBetween(a1, a2, b1)) {
            return true;
        } else if (o3 == 0 && liesBetween(a1, a2, b2)) {
            return true;
        }
        return false;
    }

    /**
     * Returns the orientation of the triple (p, q, r): negative for a
     * counter-clockwise turn, positive for a clockwise turn, zero when the
     * three points are colinear.
     */
    inline int orientationOf(Coord2D p, Coord2D q, Coord2D r) {
        return ((r.px - p.px) * (q.py - p.py)) - ((q.px - p.px) * (r.py - p.py));
    }

    /**
     * Assuming p, q, r are colinear, decides whether r sits within the
     * axis-aligned bounding rectangle spanned by p and q.
     */
    inline bool liesBetween(Coord2D p, Coord2D q, Coord2D r) {
        if (std::min(p.px, q.px) <= r.px && r.px <= std::max(p.px, q.px) &&
            std::min(p.py, q.py) <= r.py && r.py <= std::max(p.py, q.py)) {
            return true;
        }
        return false;
    }
};

/**
 * Reads four points from stdin (two segments) and reports whether they
 * intersect.
 */
int main() {
    SegmentCrossTest tester;
    Coord2D a1{}, a2{}, b1{}, b2{};

    std::cin >> a1.px >> a1.py;
    std::cin >> a2.px >> a2.py;
    std::cin >> b1.px >> b1.py;
    std::cin >> b2.px >> b2.py;

    printf("%d", tester.crosses(a1, a2, b1, b2));
    std::cout << std::endl;
}

/**
 * @file
 * @brief [Bidirectional Dijkstra Shortest Path Algorithm]
 * (https://www.coursera.org/learn/algorithms-on-graphs/lecture/7ml18/bidirectional-dijkstra)
 *
 * @author [Marinovksy](http://github.com/Marinovsky)
 *
 * @details
 * This is basically the same Dijkstra Algorithm but faster because it goes from
 * the source to the target and from target to the source and stops when
 * finding a vertex visited already by the direct search or the reverse one.
 * Here some simulations of it:
 * https://www.youtube.com/watch?v=DINCL5cd_w0&t=24s
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for io operations
#include <limits>    /// for variable INF
#include <queue>     /// for the priority_queue of distances
#include <utility>   /// for make_pair function
#include <vector>    /// for store the graph, the distances, and the path

constexpr int64_t INF = std::numeric_limits<int64_t>::max();

/**
 * @namespace graph
 * @brief Graph Algorithms
 */
namespace graph {
/**
 * @namespace bidirectional_dijkstra
 * @brief Functions for [Bidirectional Dijkstra Shortest Path]
 * (https://www.coursera.org/learn/algorithms-on-graphs/lecture/7ml18/bidirectional-dijkstra)
 * algorithm
 */
namespace bidirectional_dijkstra {
/**
 * @brief Function that add edge between two nodes or vertices of graph
 *
 * @param adj1 adjacency list for the direct search
 * @param adj2 adjacency list for the reverse search
 * @param u any node or vertex of graph
 * @param v any node or vertex of graph
 */
void addEdge(std::vector<std::vector<std::pair<uint64_t, uint64_t>>> *adj1,
             std::vector<std::vector<std::pair<uint64_t, uint64_t>>> *adj2,
             uint64_t u, uint64_t v, uint64_t w) {
    (*adj1)[u - 1].push_back(std::make_pair(v - 1, w));
    (*adj2)[v - 1].push_back(std::make_pair(u - 1, w));
    // (*adj)[v - 1].push_back(std::make_pair(u - 1, w));
}
/**
 * @brief This function returns the shortest distance from the source
 * to the target if there is path between vertices 's' and 't'.
 *
 * @param workset_ vertices visited in the search
 * @param distance_ vector of distances from the source to the target and
 * from the target to the source
 *
 */
uint64_t Shortest_Path_Distance(
    const std::vector<uint64_t> &workset_,
    const std::vector<std::vector<uint64_t>> &distance_) {
    int64_t distance = INF;
    for (uint64_t i : workset_) {
        if (distance_[0][i] + distance_[1][i] < distance) {
            distance = distance_[0][i] + distance_[1][i];
        }
    }
    return distance;
}

/**
 * @brief Function runs the dijkstra algorithm for some source vertex and
 * target vertex in the graph and returns the shortest distance of target
 * from the source.
 *
 * @param adj1 input graph
 * @param adj2 input graph reversed
 * @param s source vertex
 * @param t target vertex
 *
 * @return shortest distance if target is reachable from source else -1 in
 * case if target is not reachable from source.
 */
int Bidijkstra(std::vector<std::vector<std::pair<uint64_t, uint64_t>>> *adj1,
               std::vector<std::vector<std::pair<uint64_t, uint64_t>>> *adj2,
               uint64_t s, uint64_t t) {
    /// n denotes the number of vertices in graph
    uint64_t n = adj1->size();

    /// setting all the distances initially to INF
    std::vector<std::vector<uint64_t>> dist(2, std::vector<uint64_t>(n, INF));

    /// creating a a vector of min heap using priority queue
    /// pq[0] contains the min heap for the direct search
    /// pq[1] contains the min heap for the reverse search

    /// first element of pair contains the distance
    /// second element of pair contains the vertex
    std::vector<
        std::priority_queue<std::pair<uint64_t, uint64_t>,
                            std::vector<std::pair<uint64_t, uint64_t>>,
                            std::greater<std::pair<uint64_t, uint64_t>>>>
        pq(2);
    /// vector for store the nodes or vertices in the shortest path
    std::vector<uint64_t> workset(n);
    /// vector for store the nodes or vertices visited
    std::vector<bool> visited(n);

    /// pushing the source vertex 's' with 0 distance in pq[0] min heap
    pq[0].push(std::make_pair(0, s));

    /// marking the distance of source as 0
    dist[0][s] = 0;

    /// pushing the target vertex 't' with 0 distance in pq[1] min heap
    pq[1].push(std::make_pair(0, t));

    /// marking the distance of target as 0
    dist[1][t] = 0;

    while (true) {
        /// direct search

        // If pq[0].size() is equal to zero then the node/ vertex is not
        // reachable from s
        if (pq[0].size() == 0) {
            break;
        }
        /// second element of pair denotes the node / vertex
        uint64_t currentNode = pq[0].top().second;

        /// first element of pair denotes the distance
        uint64_t currentDist = pq[0].top().first;

        pq[0].pop();

        /// for all the reachable vertex from the currently exploring vertex
        /// we will try to minimize the distance
        for (std::pair<int, int> edge : (*adj1)[currentNode]) {
            /// minimizing distances
            if (currentDist + edge.second < dist[0][edge.first]) {
                dist[0][edge.first] = currentDist + edge.second;
                pq[0].push(std::make_pair(dist[0][edge.first], edge.first));
            }
        }
        // store the processed node/ vertex
        workset.push_back(currentNode);

        /// check if currentNode has already been visited
        if (visited[currentNode] == 1) {
            return Shortest_Path_Distance(workset, dist);
        }
        visited[currentNode] = true;
        /// reversed search

        // If pq[1].size() is equal to zero then the node/ vertex is not
        // reachable from t
        if (pq[1].size() == 0) {
            break;
        }
        /// second element of pair denotes the node / vertex
        currentNode = pq[1].top().second;

        /// first element of pair denotes the distance
        currentDist = pq[1].top().first;

        pq[1].pop();

        /// for all the reachable vertex from the currently exploring vertex
        /// we will try to minimize the distance
        for (std::pair<int, int> edge : (*adj2)[currentNode]) {
            /// minimizing distances
            if (currentDist + edge.second < dist[1][edge.first]) {
                dist[1][edge.first] = currentDist + edge.second;
                pq[1].push(std::make_pair(dist[1][edge.first], edge.first));
            }
        }
        // store the processed node/ vertex
        workset.push_back(currentNode);

        /// check if currentNode has already been visited
        if (visited[currentNode] == 1) {
            return Shortest_Path_Distance(workset, dist);
        }
        visited[currentNode] = true;
    }
    return -1;
}
}  // namespace bidirectional_dijkstra
}  // namespace graph

