/**
 * @file
 * @brief Two-sided (bidirectional) Dijkstra shortest-path search.
 *
 * @details
 * Instead of running a single Dijkstra search from the source all the
 * way out to the target, this variant grows two search frontiers at
 * once: one rooted at the source walking forward edges, one rooted at
 * the target walking reversed edges. The two frontiers race toward
 * each other and the search halts as soon as a vertex has been
 * finalized by both sides, which in practice touches far fewer nodes
 * than a single-direction search on large graphs.
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <limits>
#include <queue>
#include <utility>
#include <vector>

namespace graph {
namespace bidirectional_dijkstra {

using WeightT = uint64_t;
using NodeId = uint64_t;
using EdgeList = std::vector<std::vector<std::pair<NodeId, WeightT>>>;
using MinHeap =
    std::priority_queue<std::pair<WeightT, NodeId>,
                        std::vector<std::pair<WeightT, NodeId>>,
                        std::greater<std::pair<WeightT, NodeId>>>;

constexpr WeightT kUnreachable = std::numeric_limits<WeightT>::max();

/**
 * @brief Registers a weighted edge in both the forward and the
 * transposed adjacency structures used by the two search directions.
 */
inline void connect(EdgeList &forward, EdgeList &reversed, NodeId from,
                     NodeId to, WeightT cost) {
    forward[from - 1].emplace_back(to - 1, cost);
    reversed[to - 1].emplace_back(from - 1, cost);
}

/**
 * @brief Given the set of vertices that have been settled by either
 * search direction, scans them to find the smallest combined distance
 * (forward-distance + backward-distance), which is the length of the
 * best path found so far that crosses between the two frontiers.
 */
inline WeightT bestMeetingDistance(
    const std::vector<NodeId> &settled,
    const std::vector<std::vector<WeightT>> &dist) {
    WeightT best = kUnreachable;
    for (NodeId v : settled) {
        WeightT combined = dist[0][v] + dist[1][v];
        if (combined < best) {
            best = combined;
        }
    }
    return best;
}

/**
 * @brief Relaxes all outgoing edges of `node` in the given search
 * direction, pushing improved distances into the corresponding heap.
 */
inline void relaxNeighbors(const EdgeList &adj, NodeId node, WeightT baseDist,
                            std::vector<WeightT> *dist, MinHeap *heap) {
    for (const auto &edge : adj[node]) {
        NodeId neighbor = edge.first;
        WeightT weight = edge.second;
        WeightT candidate = baseDist + weight;
        if (candidate < (*dist)[neighbor]) {
            (*dist)[neighbor] = candidate;
            heap->emplace(candidate, neighbor);
        }
    }
}

/**
 * @brief Runs the alternating bidirectional Dijkstra search between
 * `source` and `target` and reports the shortest distance, or -1 when
 * no path connects them.
 */
int64_t shortestPathLength(const EdgeList &forward, const EdgeList &reversed,
                            NodeId source, NodeId target) {
    const size_t vertexCount = forward.size();

    std::vector<std::vector<WeightT>> dist(
        2, std::vector<WeightT>(vertexCount, kUnreachable));
    std::vector<MinHeap> frontier(2);
    std::vector<NodeId> settled;
    std::vector<bool> finalized(vertexCount, false);

    dist[0][source] = 0;
    dist[1][target] = 0;
    frontier[0].emplace(0, source);
    frontier[1].emplace(0, target);

    for (;;) {
        for (int side = 0; side < 2; ++side) {
            const EdgeList &adj = (side == 0) ? forward : reversed;

            if (frontier[side].empty()) {
                return -1;
            }

            auto [currentDist, currentNode] = frontier[side].top();
            frontier[side].pop();

            relaxNeighbors(adj, currentNode, currentDist, &dist[side],
                           &frontier[side]);
            settled.push_back(currentNode);

            if (finalized[currentNode]) {
                return static_cast<int64_t>(bestMeetingDistance(settled, dist));
            }
            finalized[currentNode] = true;
        }
    }
}

}  // namespace bidirectional_dijkstra
}  // namespace graph

/**
 * @brief Exercises the bidirectional search against a couple of small,
 * hand-checked graphs.
 */
static void runSelfChecks() {
    std::cout << "Running bidirectional dijkstra self-checks..." << std::endl;

    std::cout << "Case A: small 4-node graph" << std::endl;
    graph::bidirectional_dijkstra::EdgeList fwdA(4), revA(4);
    graph::bidirectional_dijkstra::connect(fwdA, revA, 1, 2, 1);
    graph::bidirectional_dijkstra::connect(fwdA, revA, 4, 1, 2);
    graph::bidirectional_dijkstra::connect(fwdA, revA, 2, 3, 2);
    graph::bidirectional_dijkstra::connect(fwdA, revA, 1, 3, 5);

    assert(graph::bidirectional_dijkstra::shortestPathLength(fwdA, revA, 0, 2) ==
           3);
    std::cout << "  1 -> 3 distance ok" << std::endl;

    assert(graph::bidirectional_dijkstra::shortestPathLength(fwdA, revA, 3, 2) ==
           5);
    std::cout << "  4 -> 3 distance ok" << std::endl;

    std::cout << "Case B: 5-node graph with multiple routes" << std::endl;
    graph::bidirectional_dijkstra::EdgeList fwdB(5), revB(5);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 1, 2, 4);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 1, 3, 2);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 2, 3, 2);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 3, 2, 1);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 2, 4, 2);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 3, 5, 4);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 5, 4, 1);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 2, 5, 3);
    graph::bidirectional_dijkstra::connect(fwdB, revB, 3, 4, 4);

    assert(graph::bidirectional_dijkstra::shortestPathLength(fwdB, revB, 0, 4) ==
           6);
    std::cout << "  1 -> 5 distance ok" << std::endl;

    std::cout << "All self-checks passed." << std::endl << std::endl;
}

int main() {
    runSelfChecks();

    uint64_t vertexCount = 0;
    uint64_t edgeCount = 0;
    std::cout << "Number of vertices: ";
    std::cin >> vertexCount;
    std::cout << "Number of edges: ";
    std::cin >> edgeCount;

    graph::bidirectional_dijkstra::EdgeList forward(vertexCount);
    graph::bidirectional_dijkstra::EdgeList reversed(vertexCount);

    std::cout << "Provide each edge as: u v w" << std::endl;
    std::cout << "(e.g. an edge between node 1 and node 4 with weight 7 is "
                 "entered as: 1 4 7)"
              << std::endl;
    for (uint64_t i = 0; i < edgeCount; ++i) {
        uint64_t u = 0, v = 0, w = 0;
        std::cin >> u >> v >> w;
        graph::bidirectional_dijkstra::connect(forward, reversed, u, v, w);
        if (i + 1 != edgeCount) {
            std::cout << "Next edge, please" << std::endl;
        }
    }

    std::cout << "Now provide the source and target node, separated by a space"
              << std::endl;
    std::cout << "(e.g. source 5, target 6 is entered as: 5 6)" << std::endl;
    uint64_t src = 0, dst = 0;
    std::cin >> src >> dst;

    int64_t result = graph::bidirectional_dijkstra::shortestPathLength(
        forward, reversed, src - 1, dst - 1);
    if (result == -1) {
        std::cout << "There is no path from source to target" << std::endl;
    } else {
        std::cout << "Shortest distance: " << result << std::endl;
    }

    return 0;
}

/**
 *
 * \file
 * \brief [Breadth First Search Algorithm
 * (Breadth First Search)](https://en.wikipedia.org/wiki/Breadth-first_search)
 *
 * \author [Ayaan Khan](https://github.com/ayaankhan98)
 * \author [Aman Kumar Pandey](https://github.com/gpamangkp)
 *
 *
 * \details
 * Breadth First Search also quoted as BFS is a Graph Traversal Algorithm.
 * Time Complexity O(|V| + |E|) where V are the number of vertices and E
 * are the number of edges in the graph.
 *
 * Applications of Breadth First Search are
 *
 * 1. Finding shortest path between two vertices say u and v, with path
 *    length measured by number of edges (an advantage over depth first
 *    search algorithm)
 * 2. Ford-Fulkerson Method for computing the maximum flow in a flow network.
 * 3. Testing bipartiteness of a graph.
 * 4. Cheney's Algorithm, Copying garbage collection.
 *
 * And there are many more...
 *
 * <h4>working</h4>
 * In the implementation below we first created a graph using the adjacency
 * list representation of graph.
 * Breadth First Search Works as follows
 * it requires a vertex as a start vertex, Start vertex is that vertex
 * from where you want to start traversing the graph.
 * We maintain a bool array or a vector to keep track of the vertices
 * which we have visited so that we do not traverse the visited vertices
 * again and again and eventually fall into an infinite loop. Along with this
 * boolen array we use a Queue.
 *
 * 1. First we mark the start vertex as visited.
 * 2. Push this visited vertex in the Queue.
 * 3. while the queue is not empty we repeat the following steps
 *
 *      1. Take out an element from the front of queue
 *      2. Explore the adjacency list of this vertex
 *         if element in the adjacency list is not visited then we
 *         push that element into the queue and mark this as visited
 *
 */
#include <algorithm>
#include <cassert>
#include <iostream>
#include <list>
#include <map>
#include <queue>
#include <string>

/**
 * \namespace graph
 * \brief Graph algorithms
 */
namespace graph {
/* Class Graph definition */
template <typename T>
class Graph {
    /**
     *  adjacency_list maps every vertex to the list of its neighbours in the
     * order in which they are added.
     */
    std::map<T, std::list<T> > adjacency_list;

 public:
    Graph() = default;
    ;
    void add_edge(T u, T v, bool bidir = true) {
        /**
         *  add_edge(u,v,bidir) is used to add an edge between node u and
         * node v by default , bidir is made true , i.e graph is
         * bidirectional . It means if edge(u,v) is added then u-->v  and
         * v-->u both edges exist.
         *
         *  to make the graph unidirectional pass the third parameter of
         * add_edge as false which will
         */
        adjacency_list[u].push_back(v);  // u-->v edge added
        if (bidir == true) {
            // if graph is bidirectional
            adjacency_list[v].push_back(u);  // v-->u edge added
        }
    }

    /**
     *  this function performs the breadth first search on graph and return a
     *  mapping which maps the nodes to a boolean value representing whether the
     *  node was traversed or not.
     */
    std::map<T, bool> breadth_first_search(T src) {
        /// mapping to keep track of all visited nodes
        std::map<T, bool> visited;
        /// initialise every possible vertex to map to false
        /// initially none of the vertices are unvisited
        for (auto const &adjlist : adjacency_list) {
            visited[adjlist.first] = false;
            for (auto const &node : adjacency_list[adjlist.first]) {
                visited[node] = false;
            }
        }

        /// queue to store the nodes which are yet to be traversed
        std::queue<T> tracker;

        /// push the source vertex to queue to begin traversing
        tracker.push(src);
        /// mark the source vertex as visited
        visited[src] = true;
        while (!tracker.empty()) {
            /// traverse the graph till no connected vertex are left
            /// extract a node from queue for further traversal
            T node = tracker.front();
            /// remove the node from the queue
            tracker.pop();
            for (T const &neighbour : adjacency_list[node]) {
                /// check every vertex connected to the node which are still
                /// unvisited
                if (!visited[neighbour]) {
                    /// if the neighbour is unvisited , push it into the queue
                    tracker.push(neighbour);
                    /// mark the neighbour as visited
                    visited[neighbour] = true;
                }
            }
        }
        return visited;
    }
};
/* Class definition ends */
}  // namespace graph

/** Test function */
static void tests() {
    /// Test 1 Begin
    graph::Graph<int> g;
    std::map<int, bool> correct_result;
    g.add_edge(0, 1);
    g.add_edge(1, 2);
    g.add_edge(2, 3);
    correct_result[0] = true;
    correct_result[1] = true;
    correct_result[2] = true;
    correct_result[3] = true;

    std::map<int, bool> returned_result = g.breadth_first_search(2);

    assert(returned_result == correct_result);
    std::cout << "Test 1 Passed..." << std::endl;

    /// Test 2 Begin
    returned_result = g.breadth_first_search(0);

    assert(returned_result == correct_result);
    std::cout << "Test 2 Passed..." << std::endl;

    /// Test 3 Begins
    graph::Graph<std::string> g2;

    g2.add_edge("Gorakhpur", "Lucknow", false);
    g2.add_edge("Gorakhpur", "Kanpur", false);
    g2.add_edge("Lucknow", "Agra", false);
    g2.add_edge("Kanpur", "Agra", false);
    g2.add_edge("Lucknow", "Prayagraj", false);
    g2.add_edge("Agra", "Noida", false);

    std::map<std::string, bool> correct_res;
    std::map<std::string, bool> returned_res =
        g2.breadth_first_search("Kanpur");
    correct_res["Gorakhpur"] = false;
    correct_res["Lucknow"] = false;
    correct_res["Kanpur"] = true;
    correct_res["Agra"] = true;
    correct_res["Prayagraj"] = false;
    correct_res["Noida"] = true;
    assert(correct_res == returned_res);
    std::cout << "Test 3 Passed..." << std::endl;
}

/** Main function */
int main() {
    tests();
    size_t edges = 0;
    std::cout << "Enter the number of edges: ";
    std::cin >> edges;

    graph::Graph<int> g;

    std::cout << "Enter space-separated pairs of vertices that form edges: "
              << std::endl;
    while (edges--) {
        int u = 0, v = 0;
        std::cin >> u >> v;
        g.add_edge(u, v);
    }

    g.breadth_first_search(0);
    return 0;
}

/**
 * \file
 * \brief Level-order graph traversal (Breadth First Search).
 *
 * \details
 * BFS explores a graph outward in "rings" around a starting vertex:
 * first the start node, then everything one hop away, then everything
 * two hops away, and so on. This ordering makes it useful whenever you
 * need the fewest-edges path between two vertices, for testing whether
 * a graph is bipartite, for Ford-Fulkerson style flow augmentation, and
 * for copying/garbage-collection style graph walks.
 *
 * The traversal keeps a FIFO queue of "discovered but not yet expanded"
 * vertices and a visited-set so no vertex is ever queued twice:
 *
 *   1. Mark the start vertex visited and enqueue it.
 *   2. While the queue isn't empty, dequeue a vertex, and for each of
 *      its neighbours that hasn't been visited yet, mark it visited
 *      and enqueue it.
 */
#include <algorithm>
#include <cassert>
#include <iostream>
#include <list>
#include <map>
#include <queue>
#include <string>

/**
 * \namespace graph
 * \brief Graph algorithms
 */
namespace graph {

/// A simple adjacency-list graph supporting BFS traversal over any
/// hashable/orderable vertex label type.
template <typename Label>
class Network {
    /// Maps each vertex to the ordered list of vertices reachable
    /// directly from it.
    std::map<Label, std::list<Label>> neighbors_;

 public:
    Network() = default;

    /// Records a link between `a` and `b`. When `mutual` is true (the
    /// default) the link is added in both directions; pass false to
    /// register a one-way link from `a` to `b` only.
    void link(Label a, Label b, bool mutual = true) {
        neighbors_[a].push_back(b);
        if (mutual) {
            neighbors_[b].push_back(a);
        }
    }

    /// Traverses the graph breadth-first starting at `start` and
    /// returns, for every known vertex, whether it was reached.
    std::map<Label, bool> exploreFrom(Label start) {
        std::map<Label, bool> reached;

        // Every vertex that appears anywhere (as a key or as someone's
        // neighbour) begins unreached.
        for (auto const &entry : neighbors_) {
            reached[entry.first] = false;
            for (auto const &nbr : entry.second) {
                reached[nbr] = false;
            }
        }

        std::queue<Label> pending;
        pending.push(start);
        reached[start] = true;

        while (!pending.empty()) {
            Label current = pending.front();
            pending.pop();

            for (Label const &nbr : neighbors_[current]) {
                if (reached[nbr]) {
                    continue;
                }
                reached[nbr] = true;
                pending.push(nbr);
            }
        }

        return reached;
    }
};

}  // namespace graph

/** Runs a handful of hand-verified BFS scenarios. */
static void runSelfChecks() {
    // Scenario 1: a simple path graph 0-1-2-3, BFS from the middle.
    graph::Network<int> chain;
    chain.link(0, 1);
    chain.link(1, 2);
    chain.link(2, 3);

    std::map<int, bool> expectedAllReached;
    expectedAllReached[0] = true;
    expectedAllReached[1] = true;
    expectedAllReached[2] = true;
    expectedAllReached[3] = true;

    std::map<int, bool> resultFromMiddle = chain.exploreFrom(2);
    assert(resultFromMiddle == expectedAllReached);
    std::cout << "Chain graph from middle vertex: passed" << std::endl;

    // Scenario 2: same graph, BFS from an endpoint should still reach all.
    std::map<int, bool> resultFromEnd = chain.exploreFrom(0);
    assert(resultFromEnd == expectedAllReached);
    std::cout << "Chain graph from end vertex: passed" << std::endl;

    // Scenario 3: a city road map, directed one-way style edges added
    // via `link(..., false)`, checking that unreachable cities stay false.
    graph::Network<std::string> cities;
    cities.link("Gorakhpur", "Lucknow", false);
    cities.link("Gorakhpur", "Kanpur", false);
    cities.link("Lucknow", "Agra", false);
    cities.link("Kanpur", "Agra", false);
    cities.link("Lucknow", "Prayagraj", false);
    cities.link("Agra", "Noida", false);

    std::map<std::string, bool> expectedCityResult;
    expectedCityResult["Gorakhpur"] = false;
    expectedCityResult["Lucknow"] = false;
    expectedCityResult["Kanpur"] = true;
    expectedCityResult["Agra"] = true;
    expectedCityResult["Prayagraj"] = false;
    expectedCityResult["Noida"] = true;

    std::map<std::string, bool> actualCityResult = cities.exploreFrom("Kanpur");
    assert(actualCityResult == expectedCityResult);
    std::cout << "City map from Kanpur: passed" << std::endl;
}

/** Entry point: run the self-checks, then build and traverse a
 * user-supplied graph. */
int main() {
    runSelfChecks();

    size_t edgeCount = 0;
    std::cout << "How many edges will you enter? ";
    std::cin >> edgeCount;

    graph::Network<int> userGraph;

    std::cout << "Enter each edge as a space-separated pair of vertices:"
              << std::endl;
    for (size_t i = 0; i < edgeCount; ++i) {
        int a = 0, b = 0;
        std::cin >> a >> b;
        userGraph.link(a, b);
    }

    userGraph.exploreFrom(0);
    return 0;
}

