#include <algorithm>  //  for min & max
#include <iostream>   //  for cout
#include <vector>     //  for std::vector

class Solution {
    std::vector<std::vector<int>> graph;
    std::vector<int> in_time, out_time;
    int timer = 0;
    std::vector<std::vector<int>> bridge;
    std::vector<bool> visited;
    void dfs(int current_node, int parent) {
        visited.at(current_node) = true;
        in_time[current_node] = out_time[current_node] = timer++;
        for (auto& itr : graph[current_node]) {
            if (itr == parent) {
                continue;
            }
            if (!visited[itr]) {
                dfs(itr, current_node);
                if (out_time[itr] > in_time[current_node]) {
                    bridge.push_back({itr, current_node});
                }
            }
            out_time[current_node] =
                std::min(out_time[current_node], out_time[itr]);
        }
    }

 public:
    std::vector<std::vector<int>> search_bridges(
        int n, const std::vector<std::vector<int>>& connections) {
        timer = 0;
        graph.resize(n);
        in_time.assign(n, 0);
        visited.assign(n, false);
        out_time.assign(n, 0);
        for (auto& itr : connections) {
            graph.at(itr[0]).push_back(itr[1]);
            graph.at(itr[1]).push_back(itr[0]);
        }
        dfs(0, -1);
        return bridge;
    }
};

/**
 * Main function
 */
int main() {
    Solution s1;
    int number_of_node = 5;
    std::vector<std::vector<int>> node;
    node.push_back({0, 1});
    node.push_back({1, 3});
    node.push_back({1, 2});
    node.push_back({2, 4});
    /*
     *     0 <--> 1 <---> 2
     *            ^       ^
     *            |       |
     *            |       |
     *            \/     \/
     *            3       4
     *
     *    In this graph there are 4 bridges [0,2] , [2,4] , [3,5] , [1,2]
     *
     *    I assumed that the graph is bi-directional and connected.
     *
     */
    std::vector<std::vector<int>> bridges =
        s1.search_bridges(number_of_node, node);
    std::cout << bridges.size() << " bridges found!\n";
    for (auto& itr : bridges) {
        std::cout << itr[0] << " --> " << itr[1] << '\n';
    }
    return 0;
}

/*
 * Bridge-finding in an undirected graph using Tarjan's low-link technique.
 *
 * A "bridge" is an edge whose removal splits its connected component
 * into two pieces (i.e. it is not part of any cycle). We find all of
 * them with a single DFS pass that tracks, for every vertex, the
 * earliest-discovered vertex reachable from its subtree (the "low"
 * value) alongside its own discovery time. An edge (parent, child) is
 * a bridge exactly when nothing in child's subtree can reach back to
 * parent or anything discovered before it.
 */
#include <algorithm>  // for std::min
#include <iostream>   // for std::cout
#include <vector>     // for std::vector

class BridgeFinder {
    std::vector<std::vector<int>> adjacency;
    std::vector<int> discoveryTime;
    std::vector<int> lowLink;
    std::vector<bool> seen;
    std::vector<std::pair<int, int>> bridgesFound;
    int clock = 0;

    /// Depth-first walk that computes discovery/low-link values and
    /// records any bridge edges it encounters along the way.
    void walk(int node, int parentEdge) {
        seen[node] = true;
        discoveryTime[node] = lowLink[node] = clock++;

        for (int neighbor : adjacency[node]) {
            if (neighbor == parentEdge) {
                continue;
            }

            if (seen[neighbor]) {
                // back-edge to an ancestor: tighten our low-link value
                lowLink[node] = std::min(lowLink[node], discoveryTime[neighbor]);
                continue;
            }

            walk(neighbor, node);
            lowLink[node] = std::min(lowLink[node], lowLink[neighbor]);

            if (lowLink[neighbor] > discoveryTime[node]) {
                bridgesFound.emplace_back(neighbor, node);
            }
        }
    }

 public:
    /// Builds the adjacency list from the given undirected edge list
    /// and runs the DFS from vertex 0, returning every bridge as a
    /// {u, v} pair.
    std::vector<std::pair<int, int>> findBridges(
        int vertexCount, const std::vector<std::vector<int>> &edges) {
        clock = 0;
        adjacency.assign(vertexCount, {});
        discoveryTime.assign(vertexCount, 0);
        lowLink.assign(vertexCount, 0);
        seen.assign(vertexCount, false);
        bridgesFound.clear();

        for (const auto &edge : edges) {
            adjacency[edge[0]].push_back(edge[1]);
            adjacency[edge[1]].push_back(edge[0]);
        }

        walk(0, -1);
        return bridgesFound;
    }
};

/**
 * Demo/main function.
 */
int main() {
    BridgeFinder finder;
    const int vertexCount = 5;

    std::vector<std::vector<int>> edges;
    edges.push_back({0, 1});
    edges.push_back({1, 3});
    edges.push_back({1, 2});
    edges.push_back({2, 4});
    /*
     *     0 <--> 1 <---> 2
     *            ^       ^
     *            |       |
     *            |       |
     *            \/     \/
     *            3       4
     *
     * This graph (assumed undirected and connected) has 4 bridges:
     * [0,1], [1,2], [1,3], [2,4].
     */
    auto bridges = finder.findBridges(vertexCount, edges);

    std::cout << bridges.size() << " bridges found!\n";
    for (const auto &b : bridges) {
        std::cout << b.first << " --> " << b.second << '\n';
    }
    return 0;
}

/**
 *
 * \file
 * \brief [Graph Connected Components
 * (Connected Components)]
 * (https://en.wikipedia.org/wiki/Component_(graph_theory))
 *
 * \author [Ayaan Khan](http://github.com/ayaankhan98)
 *
 * \details
 * A graph is a collection of nodes also called vertices and these vertices
 * are connected by edges. A connected component in a graph refers to a set of
 * vertices which are reachable form one another.
 *
 * <pre>
 * Example - Here is graph with 3 connected components
 *
 *      1   4           5               8
 *     / \ /           / \             / \
 *    2---3           6   7           9   10
 *
 *    first          second           third
 *    component      component        component
 * </pre>
 *
 */

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace graph
 * @brief Graph Algorithms
 */

namespace graph {
/**
 * @brief Function that add edge between two nodes or vertices of graph
 *
 * @param adj adjacency list of graph.
 * @param u any node or vertex of graph.
 * @param v any node or vertex of graph.
 */
void addEdge(std::vector<std::vector<int>> *adj, int u, int v) {
    (*adj)[u - 1].push_back(v - 1);
    (*adj)[v - 1].push_back(u - 1);
}

/**
 * @brief Utility function for depth first seach algorithm
 * this function explores the vertex which is passed into.
 *
 * @param adj adjacency list of graph.
 * @param u vertex or node to be explored.
 * @param visited already visited vertices.
 */
void explore(const std::vector<std::vector<int>> *adj, int u,
             std::vector<bool> *visited) {
    (*visited)[u] = true;
    for (auto v : (*adj)[u]) {
        if (!(*visited)[v]) {
            explore(adj, v, visited);
        }
    }
}

/**
 * @brief Function that perfoms depth first search algorithm on graph
 * and calculated the number of connected components.
 *
 * @param adj adjacency list of graph.
 *
 * @return connected_components number of connected components in graph.
 */
int getConnectedComponents(const std::vector<std::vector<int>> *adj) {
    int n = adj->size();
    int connected_components = 0;
    std::vector<bool> visited(n, false);

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            explore(adj, i, &visited);
            connected_components++;
        }
    }
    return connected_components;
}
}  // namespace graph

