/**
 * \file
 * \brief Counting connected components in an undirected graph.
 *
 * \details
 * A connected component is a maximal group of vertices that can all
 * reach one another through some sequence of edges. To count them we
 * repeatedly pick any vertex we haven't looked at yet, flood-fill
 * (depth-first) everything reachable from it marking each as seen,
 * and count that as one component; once every vertex has been
 * flood-filled from some starting point, the number of times we
 * started a new flood-fill is the number of components.
 *
 * <pre>
 * Example - a graph with 3 connected components:
 *
 *      1   4           5               8
 *     / \ /           / \             / \
 *    2---3           6   7           9   10
 *
 *    first          second           third
 *    component      component        component
 * </pre>
 */

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace graph
 * @brief Graph Algorithms
 */
namespace graph {

using AdjacencyList = std::vector<std::vector<int>>;

/**
 * @brief Registers an undirected edge between 1-indexed vertices `a`
 * and `b` in the adjacency list (stored internally 0-indexed).
 */
void link(AdjacencyList *graph, int a, int b) {
    (*graph)[a - 1].push_back(b - 1);
    (*graph)[b - 1].push_back(a - 1);
}

/**
 * @brief Recursively marks every vertex reachable from `start` as
 * visited, flood-fill style.
 */
void floodFill(const AdjacencyList &graph, int start, std::vector<bool> *seen) {
    (*seen)[start] = true;
    for (int neighbor : graph[start]) {
        if (!(*seen)[neighbor]) {
            floodFill(graph, neighbor, seen);
        }
    }
}

/**
 * @brief Counts how many connected components the graph has by
 * flood-filling from every not-yet-visited vertex.
 */
int countComponents(const AdjacencyList &graph) {
    const int vertexCount = static_cast<int>(graph.size());
    std::vector<bool> seen(vertexCount, false);
    int componentTally = 0;

    for (int v = 0; v < vertexCount; ++v) {
        if (seen[v]) {
            continue;
        }
        floodFill(graph, v, &seen);
        ++componentTally;
    }

    return componentTally;
}

}  // namespace graph

/** Runs a couple of hand-verified component-counting scenarios. */
void runSelfChecks() {
    std::cout << "Running connected-components self-checks..." << std::endl;

    std::cout << "Scenario A: three separate clusters" << std::endl;
    graph::AdjacencyList clusterGraph(9);
    graph::link(&clusterGraph, 1, 2);
    graph::link(&clusterGraph, 1, 3);
    graph::link(&clusterGraph, 3, 4);
    graph::link(&clusterGraph, 5, 7);
    graph::link(&clusterGraph, 5, 6);
    graph::link(&clusterGraph, 8, 9);

    assert(graph::countComponents(clusterGraph) == 3);
    std::cout << "  expected 3 components: passed" << std::endl;

    std::cout << "Scenario B: two larger clusters" << std::endl;
    graph::AdjacencyList largerGraph(10);
    graph::link(&largerGraph, 1, 2);
    graph::link(&largerGraph, 1, 3);
    graph::link(&largerGraph, 1, 4);
    graph::link(&largerGraph, 2, 3);
    graph::link(&largerGraph, 3, 4);
    graph::link(&largerGraph, 4, 8);
    graph::link(&largerGraph, 4, 10);
    graph::link(&largerGraph, 8, 10);
    graph::link(&largerGraph, 8, 9);
    graph::link(&largerGraph, 5, 7);
    graph::link(&largerGraph, 5, 6);
    graph::link(&largerGraph, 6, 7);

    assert(graph::countComponents(largerGraph) == 2);
    std::cout << "  expected 2 components: passed" << std::endl;
}

/** Entry point: run self-checks, then read a graph from stdin and
 * report its component count. */
int main() {
    runSelfChecks();

    int vertexCount = 0, edgeCount = 0;
    std::cout << "Number of vertices: ";
    std::cin >> vertexCount;
    std::cout << "Number of edges: ";
    std::cin >> edgeCount;

    graph::AdjacencyList graph(vertexCount);

    for (int i = 0; i < edgeCount; ++i) {
        int a = 0, b = 0;
        std::cin >> a >> b;
        graph::link(&graph, a, b);
    }

    std::cout << graph::countComponents(graph) << std::endl;
    return 0;
}

/**
 * @file
 * @brief [Disjoint union](https://en.wikipedia.org/wiki/Disjoint_union)
 *
 * @details
 * The Disjoint union is the technique to find connected component in graph
 * efficiently.
 *
 * ### Algorithm
 * In Graph, if you have to find out the number of connected components, there
 * are 2 options
 * 1. Depth first search
 * 2. Disjoint union
 * 1st option is inefficient, Disjoint union is the most optimal way to find
 * this.
 *
 * @author Unknown author
 * @author [Sagar Pandya](https://github.com/sagarpandyansit)
 */
#include <cstdint>
#include <iostream>  /// for IO operations
#include <set>       /// for std::set
#include <vector>    /// for std::vector

/**
 * @namespace graph
 * @brief Graph Algorithms
 */
namespace graph {
/**
 * @namespace disjoint_union
 * @brief Functions for [Disjoint
 * union](https://en.wikipedia.org/wiki/Disjoint_union) implementation
 */
namespace disjoint_union {
uint32_t number_of_nodes = 0;                // denotes number of nodes
std::vector<int64_t> parent{};               // parent of each node
std::vector<uint32_t> connected_set_size{};  // size of each set
/**
 * @brief function the initialize every node as it's own parent
 * @returns void
 */
void make_set() {
    for (uint32_t i = 1; i <= number_of_nodes; i++) {
        parent[i] = i;
        connected_set_size[i] = 1;
    }
}
/**
 * @brief Find the component where following node belongs to
 * @param val parent of val should be found
 * @return parent of val
 */
int64_t find_set(int64_t val) {
    while (parent[val] != val) {
        parent[val] = parent[parent[val]];
        val = parent[val];
    }
    return val;
}
/**
 * @brief Merge 2 components to become one
 * @param node1 1st component
 * @param node2 2nd component
 * @returns void
 */
void union_sets(int64_t node1, int64_t node2) {
    node1 = find_set(node1);  // find the parent of node1
    node2 = find_set(node2);  // find the parent of node2

    // If parents of both nodes are not same, combine them
    if (node1 != node2) {
        if (connected_set_size[node1] < connected_set_size[node2]) {
            std::swap(node1, node2);  // swap both components
        }
        parent[node2] = node1;  // make node1 as parent of node2.
        connected_set_size[node1] +=
            connected_set_size[node2];  // sum the size of both as they combined
    }
}
/**
 * @brief Find total no. of connected components
 * @return Number of connected components
 */
uint32_t no_of_connected_components() {
    std::set<int64_t> temp;  // temp set to count number of connected components
    for (uint32_t i = 1; i <= number_of_nodes; i++) temp.insert(find_set(i));
    return temp.size();  // return the size of temp set
}
}  // namespace disjoint_union
}  // namespace graph

/**
 * @brief Test Implementations
 * @returns void
 */
static void test() {
    namespace dsu = graph::disjoint_union;
    std::cin >> dsu::number_of_nodes;
    dsu::parent.resize(dsu::number_of_nodes + 1);
    dsu::connected_set_size.resize(dsu::number_of_nodes + 1);
    dsu::make_set();
    uint32_t edges = 0;
    std::cin >> edges;  // no of edges in the graph
    while (edges--) {
        int64_t node_a = 0, node_b = 0;
        std::cin >> node_a >> node_b;
        dsu::union_sets(node_a, node_b);
    }
    std::cout << dsu::no_of_connected_components() << std::endl;
}

