/**
 * @file
 * @brief Union-Find (Disjoint Set Union) based counting of connected
 * components in an undirected graph.
 *
 * @details
 * Rather than running a DFS/BFS from every unvisited vertex, we can merge
 * vertices into sets as we process edges and then simply count how many
 * distinct set representatives remain. This is the classic "weighted union
 * with path halving" approach, which keeps every operation close to O(1)
 * amortized.
 *
 * Rewritten variant of the disjoint-union connected-components example for
 * a labeled training corpus (same behavior, different naming/structure).
 */
#include <cstdint>
#include <iostream>
#include <set>
#include <vector>

namespace graph {
namespace union_find_components {

/// total number of tracked elements
uint32_t g_elementCount = 0;
/// link[i] points toward the representative of i's set
std::vector<int64_t> g_link{};
/// rank[i] approximates the size of the set rooted at i
std::vector<uint32_t> g_rank{};

/**
 * @brief Reset every element to be its own singleton set.
 */
void resetForest() {
    for (uint32_t idx = 1; idx <= g_elementCount; ++idx) {
        g_link[idx] = idx;
        g_rank[idx] = 1;
    }
}

/**
 * @brief Locate the representative (root) of the set containing item.
 * Uses path halving to flatten the tree as we walk up.
 */
int64_t representative(int64_t item) {
    int64_t cursor = item;
    while (g_link[cursor] != cursor) {
        g_link[cursor] = g_link[g_link[cursor]];
        cursor = g_link[cursor];
    }
    return cursor;
}

/**
 * @brief Merge the sets containing two elements, attaching the
 * smaller-ranked root beneath the larger-ranked one.
 */
void mergeSets(int64_t a, int64_t b) {
    int64_t rootA = representative(a);
    int64_t rootB = representative(b);

    if (rootA == rootB) {
        return;  // already in the same component, nothing to do
    }

    if (g_rank[rootA] < g_rank[rootB]) {
        std::swap(rootA, rootB);
    }
    g_link[rootB] = rootA;
    g_rank[rootA] += g_rank[rootB];
}

/**
 * @brief Count the number of distinct connected components currently
 * represented in the forest.
 */
uint32_t countComponents() {
    std::set<int64_t> roots;
    for (uint32_t idx = 1; idx <= g_elementCount; ++idx) {
        roots.insert(representative(idx));
    }
    return static_cast<uint32_t>(roots.size());
}

}  // namespace union_find_components
}  // namespace graph

/**
 * @brief Reads a graph description from stdin and prints the number of
 * connected components.
 */
static void runDemo() {
    namespace ufc = graph::union_find_components;

    std::cin >> ufc::g_elementCount;
    ufc::g_link.resize(ufc::g_elementCount + 1);
    ufc::g_rank.resize(ufc::g_elementCount + 1);
    ufc::resetForest();

    uint32_t edgeCount = 0;
    std::cin >> edgeCount;
    for (uint32_t e = 0; e < edgeCount; ++e) {
        int64_t left = 0, right = 0;
        std::cin >> left >> right;
        ufc::mergeSets(left, right);
    }

    std::cout << ufc::countComponents() << std::endl;
}

/**
 * @brief Program entry point.
 */
int main() {
    runDemo();
    return 0;
}

/**
 * @file cycle_check_directed graph.cpp
 *
 * @brief BFS and DFS algorithms to check for cycle in a directed graph.
 *
 * @author [Anmol3299](mailto:mittalanmol22@gmail.com)
 *
 */

#include <cstdint>
#include <iostream>     // for std::cout
#include <map>          // for std::map
#include <queue>        // for std::queue
#include <stdexcept>    // for throwing errors
#include <type_traits>  // for std::remove_reference
#include <utility>      // for std::move
#include <vector>       // for std::vector

/**
 * Implementation of non-weighted directed edge of a graph.
 *
 * The source vertex of the edge is labelled "src" and destination vertex is
 * labelled "dest".
 */
struct Edge {
    unsigned int src;
    unsigned int dest;

    Edge() = delete;
    ~Edge() = default;
    Edge(Edge&&) = default;
    Edge& operator=(Edge&&) = default;
    Edge(Edge const&) = default;
    Edge& operator=(Edge const&) = default;

    /** Set the source and destination of the vertex.
     *
     * @param source is the source vertex of the edge.
     * @param destination is the destination vertex of the edge.
     */
    Edge(unsigned int source, unsigned int destination)
        : src(source), dest(destination) {}
};

using AdjList = std::map<unsigned int, std::vector<unsigned int>>;

/**
 * Implementation of graph class.
 *
 * The graph will be represented using Adjacency List representation.
 * This class contains 2 data members "m_vertices" & "m_adjList" used to
 * represent the number of vertices and adjacency list of the graph
 * respectively. The vertices are labelled 0 - (m_vertices - 1).
 */
class Graph {
 public:
    Graph() : m_adjList({}) {}
    ~Graph() = default;
    Graph(Graph&&) = default;
    Graph& operator=(Graph&&) = default;
    Graph(Graph const&) = default;
    Graph& operator=(Graph const&) = default;

    /** Create a graph from vertices and adjacency list.
     *
     * @param vertices specify the number of vertices the graph would contain.
     * @param adjList is the adjacency list representation of graph.
     */
    Graph(unsigned int vertices, AdjList adjList)
        : m_vertices(vertices), m_adjList(std::move(adjList)) {}

    /** Create a graph from vertices and adjacency list.
     *
     * @param vertices specify the number of vertices the graph would contain.
     * @param adjList is the adjacency list representation of graph.
     */
    Graph(unsigned int vertices, AdjList&& adjList)
        : m_vertices(vertices), m_adjList(std::move(adjList)) {}

    /** Create a graph from vertices and a set of edges.
     *
     * Adjacency list of the graph would be created from the set of edges. If
     * the source or destination of any edge has a value greater or equal to
     * number of vertices, then it would throw a range_error.
     *
     * @param vertices specify the number of vertices the graph would contain.
     * @param edges is a vector of edges.
     */
    Graph(unsigned int vertices, std::vector<Edge> const& edges)
        : m_vertices(vertices) {
        for (auto const& edge : edges) {
            if (edge.src >= vertices || edge.dest >= vertices) {
                throw std::range_error(
                    "Either src or dest of edge out of range");
            }
            m_adjList[edge.src].emplace_back(edge.dest);
        }
    }

    /** Return a const reference of the adjacency list.
     *
     * @return const reference to the adjacency list
     */
    std::remove_reference<AdjList>::type const& getAdjList() const {
        return m_adjList;
    }

    /**
     * @return number of vertices in the graph.
     */
    unsigned int getVertices() const { return m_vertices; }

    /** Add vertices in the graph.
     *
     * @param num is the number of vertices to be added. It adds 1 vertex by
     * default.
     *
     */
    void addVertices(unsigned int num = 1) { m_vertices += num; }

    /** Add an edge in the graph.
     *
     * @param edge that needs to be added.
     */
    void addEdge(Edge const& edge) {
        if (edge.src >= m_vertices || edge.dest >= m_vertices) {
            throw std::range_error("Either src or dest of edge out of range");
        }
        m_adjList[edge.src].emplace_back(edge.dest);
    }

    /** Add an Edge in the graph
     *
     * @param source is source vertex of the edge.
     * @param destination is the destination vertex of the edge.
     */
    void addEdge(unsigned int source, unsigned int destination) {
        if (source >= m_vertices || destination >= m_vertices) {
            throw std::range_error(
                "Either source or destination of edge out of range");
        }
        m_adjList[source].emplace_back(destination);
    }

 private:
    unsigned int m_vertices = 0;
    AdjList m_adjList;
};

/**
 * Check if a directed graph has a cycle or not.
 *
 * This class provides 2 methods to check for cycle in a directed graph:
 * isCyclicDFS & isCyclicBFS.
 *
 * - isCyclicDFS uses DFS traversal method to check for cycle in a graph.
 * - isCyclidBFS used BFS traversal method to check for cycle in a graph.
 */
class CycleCheck {
 private:
    enum nodeStates : uint8_t { not_visited = 0, in_stack, visited };

    /** Helper function of "isCyclicDFS".
     *
     * @param adjList is the adjacency list representation of some graph.
     * @param state is the state of the nodes of the graph.
     * @param node is the node being evaluated.
     *
     * @return true if graph has a cycle, else false.
     */
    static bool isCyclicDFSHelper(AdjList const& adjList,
                                  std::vector<nodeStates>* state,
                                  unsigned int node) {
        // Add node "in_stack" state.
        (*state)[node] = in_stack;

        // If the node has children, then recursively visit all children of the
        // node.
        auto const it = adjList.find(node);
        if (it != adjList.end()) {
            for (auto child : it->second) {
                // If state of child node is "not_visited", evaluate that child
                // for presence of cycle.
                auto state_of_child = (*state)[child];
                if (state_of_child == not_visited) {
                    if (isCyclicDFSHelper(adjList, state, child)) {
                        return true;
                    }
                } else if (state_of_child == in_stack) {
                    // If child node was "in_stack", then that means that there
                    // is a cycle in the graph. Return true for presence of the
                    // cycle.
                    return true;
                }
            }
        }

        // Current node has been evaluated for the presence of cycle and had no
        // cycle. Mark current node as "visited".
        (*state)[node] = visited;
        // Return that current node didn't result in any cycles.
        return false;
    }

 public:
    /** Driver function to check if a graph has a cycle.
     *
     * This function uses DFS to check for cycle in the graph.
     *
     * @param graph which needs to be evaluated for the presence of cycle.
     * @return true if a cycle is detected, else false.
     */
    static bool isCyclicDFS(Graph const& graph) {
        auto vertices = graph.getVertices();

        /** State of the node.
         *
         * It is a vector of "nodeStates" which represents the state node is in.
         * It can take only 3 values: "not_visited", "in_stack", and "visited".
         *
         * Initially, all nodes are in "not_visited" state.
         */
        std::vector<nodeStates> state(vertices, not_visited);

        // Start visiting each node.
        for (unsigned int node = 0; node < vertices; node++) {
            // If a node is not visited, only then check for presence of cycle.
            // There is no need to check for presence of cycle for a visited
            // node as it has already been checked for presence of cycle.
            if (state[node] == not_visited) {
                // Check for cycle.
                if (isCyclicDFSHelper(graph.getAdjList(), &state, node)) {
                    return true;
                }
            }
        }

        // All nodes have been safely traversed, that means there is no cycle in
        // the graph. Return false.
        return false;
    }

    /** Check if a graph has cycle or not.
     *
     * This function uses BFS to check if a graph is cyclic or not.
     *
     * @param graph which needs to be evaluated for the presence of cycle.
     * @return true if a cycle is detected, else false.
     */
    static bool isCyclicBFS(Graph const& graph) {
        auto graphAjdList = graph.getAdjList();
        auto vertices = graph.getVertices();

        std::vector<unsigned int> indegree(vertices, 0);
        // Calculate the indegree i.e. the number of incident edges to the node.
        for (auto const& list : graphAjdList) {
            auto children = list.second;
            for (auto const& child : children) {
                indegree[child]++;
            }
        }

        std::queue<unsigned int> can_be_solved;
        for (unsigned int node = 0; node < vertices; node++) {
            // If a node doesn't have any input edges, then that node will
            // definately not result in a cycle and can be visited safely.
            if (!indegree[node]) {
                can_be_solved.emplace(node);
            }
        }

        // Vertices that need to be traversed.
        auto remain = vertices;
        // While there are safe nodes that we can visit.
        while (!can_be_solved.empty()) {
            auto solved = can_be_solved.front();
            // Visit the node.
            can_be_solved.pop();
            // Decrease number of nodes that need to be traversed.
            remain--;

            // Visit all the children of the visited node.
            auto it = graphAjdList.find(solved);
            if (it != graphAjdList.end()) {
                for (auto child : it->second) {
                    // Check if we can visited the node safely.
                    if (--indegree[child] == 0) {
                        // if node can be visited safely, then add that node to
                        // the visit queue.
                        can_be_solved.emplace(child);
                    }
                }
            }
        }

        // If there are still nodes that we can't visit, then it means that
        // there is a cycle and return true, else return false.
        return !(remain == 0);
    }
};

/**
 * Main function.
 */
int main() {
    // Instantiate the graph.
    Graph g(7, std::vector<Edge>{{0, 1}, {1, 2}, {2, 0}, {2, 5}, {3, 5}});
    // Check for cycle using BFS method.
    std::cout << CycleCheck::isCyclicBFS(g) << '\n';

    // Check for cycle using DFS method.
    std::cout << CycleCheck::isCyclicDFS(g) << '\n';
    return 0;
}

/**
 * @file cycle_check_directed_graph_variant.cpp
 *
 * @brief Alternate implementation of BFS (Kahn-style) and DFS based cycle
 * detection for a directed graph.
 *
 * Rewritten variant for a labeled training corpus: same algorithmic
 * behavior as the original cycle-detection example, restructured with
 * different names, helper decomposition, and comments.
 */

#include <cstdint>
#include <iostream>
#include <map>
#include <queue>
#include <stdexcept>
#include <type_traits>
#include <utility>
#include <vector>

/**
 * A single directed connection between two vertex indices.
 */
struct Arc {
    unsigned int from;
    unsigned int to;

    Arc() = delete;
    ~Arc() = default;
    Arc(Arc&&) = default;
    Arc& operator=(Arc&&) = default;
    Arc(Arc const&) = default;
    Arc& operator=(Arc const&) = default;

    Arc(unsigned int fromVertex, unsigned int toVertex)
        : from(fromVertex), to(toVertex) {}
};

using Adjacency = std::map<unsigned int, std::vector<unsigned int>>;

/**
 * Directed graph stored as an adjacency list keyed by vertex index.
 * Vertices are labelled 0 .. (vertexTotal - 1).
 */
class DirectedGraph {
 public:
    DirectedGraph() : adjacency_({}) {}
    ~DirectedGraph() = default;
    DirectedGraph(DirectedGraph&&) = default;
    DirectedGraph& operator=(DirectedGraph&&) = default;
    DirectedGraph(DirectedGraph const&) = default;
    DirectedGraph& operator=(DirectedGraph const&) = default;

    DirectedGraph(unsigned int vertexTotal, Adjacency adjacency)
        : vertexTotal_(vertexTotal), adjacency_(std::move(adjacency)) {}

    DirectedGraph(unsigned int vertexTotal, Adjacency&& adjacency)
        : vertexTotal_(vertexTotal), adjacency_(std::move(adjacency)) {}

    /**
     * Build the adjacency list from an explicit collection of arcs.
     * Throws std::range_error if any endpoint falls outside the declared
     * vertex range.
     */
    DirectedGraph(unsigned int vertexTotal, std::vector<Arc> const& arcs)
        : vertexTotal_(vertexTotal) {
        for (auto const& arc : arcs) {
            if (arc.from >= vertexTotal || arc.to >= vertexTotal) {
                throw std::range_error("Arc endpoint outside of vertex range");
            }
            adjacency_[arc.from].emplace_back(arc.to);
        }
    }

    std::remove_reference<Adjacency>::type const& adjacency() const {
        return adjacency_;
    }

    unsigned int vertexTotal() const { return vertexTotal_; }

    void growBy(unsigned int extra = 1) { vertexTotal_ += extra; }

    void connect(Arc const& arc) {
        if (arc.from >= vertexTotal_ || arc.to >= vertexTotal_) {
            throw std::range_error("Arc endpoint outside of vertex range");
        }
        adjacency_[arc.from].emplace_back(arc.to);
    }

    void connect(unsigned int fromVertex, unsigned int toVertex) {
        if (fromVertex >= vertexTotal_ || toVertex >= vertexTotal_) {
            throw std::range_error("Arc endpoint outside of vertex range");
        }
        adjacency_[fromVertex].emplace_back(toVertex);
    }

 private:
    unsigned int vertexTotal_ = 0;
    Adjacency adjacency_;
};

/**
 * Provides two independent strategies for detecting a cycle in a directed
 * graph: a recursive coloring DFS, and an indegree-elimination (Kahn-like)
 * BFS.
 */
class CycleDetector {
 private:
    enum class Color : uint8_t { White = 0, Gray, Black };

    /**
     * Recursive helper used by hasCycleDFS. Returns true the moment a
     * back-edge (an edge into a Gray/"currently on stack" vertex) is found.
     */
    static bool visitDFS(Adjacency const& adjacency,
                          std::vector<Color>* colors, unsigned int vertex) {
        (*colors)[vertex] = Color::Gray;

        auto found = adjacency.find(vertex);
        if (found != adjacency.end()) {
            for (auto neighbor : found->second) {
                Color neighborColor = (*colors)[neighbor];
                if (neighborColor == Color::White) {
                    if (visitDFS(adjacency, colors, neighbor)) {
                        return true;
                    }
                } else if (neighborColor == Color::Gray) {
                    return true;  // back-edge found -> cycle
                }
            }
        }

        (*colors)[vertex] = Color::Black;
        return false;
    }

 public:
    /**
     * Detect a cycle by coloring vertices White/Gray/Black during a DFS
     * traversal launched from every unvisited vertex.
     */
    static bool hasCycleDFS(DirectedGraph const& g) {
        unsigned int total = g.vertexTotal();
        std::vector<Color> colors(total, Color::White);

        for (unsigned int vertex = 0; vertex < total; ++vertex) {
            if (colors[vertex] == Color::White) {
                if (visitDFS(g.adjacency(), &colors, vertex)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Detect a cycle using Kahn's algorithm: repeatedly strip vertices
     * whose indegree has dropped to zero. If some vertices are never
     * stripped, they must belong to a cycle.
     */
    static bool hasCycleBFS(DirectedGraph const& g) {
        auto adjacency = g.adjacency();
        unsigned int total = g.vertexTotal();

        std::vector<unsigned int> incoming(total, 0);
        for (auto const& entry : adjacency) {
            for (auto const& neighbor : entry.second) {
                ++incoming[neighbor];
            }
        }

        std::queue<unsigned int> ready;
        for (unsigned int vertex = 0; vertex < total; ++vertex) {
            if (incoming[vertex] == 0) {
                ready.push(vertex);
            }
        }

        unsigned int processed = 0;
        while (!ready.empty()) {
            unsigned int current = ready.front();
            ready.pop();
            ++processed;

            auto found = adjacency.find(current);
            if (found != adjacency.end()) {
                for (auto neighbor : found->second) {
                    if (--incoming[neighbor] == 0) {
                        ready.push(neighbor);
                    }
                }
            }
        }

        return processed != total;
    }
};

/**
 * Program entry point: build a sample directed graph containing a cycle
 * among vertices 0-1-2 and verify both detectors agree.
 */
int main() {
    DirectedGraph graph(7,
                        std::vector<Arc>{{0, 1}, {1, 2}, {2, 0}, {2, 5}, {3, 5}});

    std::cout << CycleDetector::hasCycleBFS(graph) << '\n';
    std::cout << CycleDetector::hasCycleDFS(graph) << '\n';
    return 0;
}

/**
 *
 * \file
 * \brief [Depth First Search Algorithm
 * (Depth First Search)](https://en.wikipedia.org/wiki/Depth-first_search)
 *
 * \author [Ayaan Khan](http://github.com/ayaankhan98)
 *
 * \details
 * Depth First Search also quoted as DFS is a Graph Traversal Algorithm.
 * Time Complexity O(|V| + |E|) where V is number of vertices and E
 * is number of edges in graph.
 *
 * Application of Depth First Search are
 *
 * 1. Finding connected components
 * 2. Finding 2-(edge or vertex)-connected components.
 * 3. Finding 3-(edge or vertex)-connected components.
 * 4. Finding the bridges of a graph.
 * 5. Generating words in order to plot the limit set of a group.
 * 6. Finding strongly connected components.
 *
 * And there are many more...
 *
 * <h4>Working</h4>
 * 1. Mark all vertices as unvisited first
 * 2. start exploring from some starting vertex.
 *
 *      While exploring vertex we mark the vertex as visited
 *      and start exploring the vertices connected to this
 *      vertex in recursive way.
 *
 */

#include <algorithm>
#include <iostream>
#include <vector>

/**
 *
 * \namespace graph
 * \brief Graph Algorithms
 *
 */
namespace graph {
/**
 * \brief
 * Adds and edge between two vertices of graph say u and v in this
 * case.
 *
 * @param adj Adjacency list representation of graph
 * @param u first vertex
 * @param v second vertex
 *
 */
void addEdge(std::vector<std::vector<size_t>> *adj, size_t u, size_t v) {
    /*
     *
     * Here we are considering undirected graph that's the
     * reason we are adding v to the adjacency list representation of u
     * and also adding u to the adjacency list representation of v
     *
     */
    (*adj)[u - 1].push_back(v - 1);
    (*adj)[v - 1].push_back(u - 1);
}

/**
 *
 * \brief
 * Explores the given vertex, exploring a vertex means traversing
 * over all the vertices which are connected to the vertex that is
 * currently being explored.
 *
 * @param adj garph
 * @param v vertex to be explored
 * @param visited already visited vertices
 *
 */
void explore(const std::vector<std::vector<size_t>> &adj, size_t v,
             std::vector<bool> *visited) {
    std::cout << v + 1 << " ";
    (*visited)[v] = true;
    for (auto x : adj[v]) {
        if (!(*visited)[x]) {
            explore(adj, x, visited);
        }
    }
}

/**
 * \brief
 * initiates depth first search algorithm.
 *
 * @param adj adjacency list of graph
 * @param start vertex from where DFS starts traversing.
 *
 */
void depth_first_search(const std::vector<std::vector<size_t>> &adj,
                        size_t start) {
    size_t vertices = adj.size();

    std::vector<bool> visited(vertices, false);
    explore(adj, start, &visited);
}
}  // namespace graph

/** Main function */
int main() {
    size_t vertices = 0, edges = 0;
    std::cout << "Enter the Vertices : ";
    std::cin >> vertices;
    std::cout << "Enter the Edges : ";
    std::cin >> edges;

    /// creating graph
    std::vector<std::vector<size_t>> adj(vertices, std::vector<size_t>());

    /// taking input for edges
    std::cout << "Enter the vertices which have edges between them : "
              << std::endl;
    while (edges--) {
        size_t u = 0, v = 0;
        std::cin >> u >> v;
        graph::addEdge(&adj, u, v);
    }

    /// running depth first search over graph
    graph::depth_first_search(adj, 2);

    std::cout << std::endl;
    return 0;
}

/**
 * @file
 * @brief Recursive Depth First Search over an undirected graph.
 *
 * Rewritten variant of the classic recursive-DFS demo for a labeled
 * training corpus: identical traversal behavior, different naming and
 * decomposition of helper routines.
 *
 * DFS visits a start vertex, marks it as seen, and then recurses into each
 * unseen neighbor, backtracking once a branch is exhausted. Runtime is
 * O(V + E).
 */

#include <algorithm>
#include <iostream>
#include <vector>

namespace graph {

/**
 * @brief Registers an undirected connection between two 1-indexed
 * vertices inside the adjacency table (stored 0-indexed internally).
 */
void linkVertices(std::vector<std::vector<size_t>> *table, size_t a,
                   size_t b) {
    // undirected: each side needs to know about the other
    (*table)[a - 1].push_back(b - 1);
    (*table)[b - 1].push_back(a - 1);
}

/**
 * @brief Recursively walks outward from a vertex, printing each vertex
 * (1-indexed) the moment it is first reached.
 */
void walk(const std::vector<std::vector<size_t>> &table, size_t current,
          std::vector<bool> *seen) {
    std::cout << current + 1 << " ";
    (*seen)[current] = true;
    for (auto neighbor : table[current]) {
        if (!(*seen)[neighbor]) {
            walk(table, neighbor, seen);
        }
    }
}

/**
 * @brief Kicks off a depth-first traversal from the given start vertex.
 */
void depth_first_search(const std::vector<std::vector<size_t>> &table,
                         size_t start) {
    size_t total = table.size();
    std::vector<bool> seen(total, false);
    walk(table, start, &seen);
}

}  // namespace graph

/** Program entry point */
int main() {
    size_t vertexTotal = 0, edgeTotal = 0;
    std::cout << "Enter the Vertices : ";
    std::cin >> vertexTotal;
    std::cout << "Enter the Edges : ";
    std::cin >> edgeTotal;

    std::vector<std::vector<size_t>> table(vertexTotal, std::vector<size_t>());

    std::cout << "Enter the vertices which have edges between them : "
              << std::endl;
    for (size_t i = 0; i < edgeTotal; ++i) {
        size_t a = 0, b = 0;
        std::cin >> a >> b;
        graph::linkVertices(&table, a, b);
    }

    graph::depth_first_search(table, 2);

    std::cout << std::endl;
    return 0;
}

/**
 *
 * @file
 * @brief [Depth First Search Algorithm using Stack
 * (Depth First Search Algorithm)](https://en.wikipedia.org/wiki/Depth-first_search)
 *
 * @author [Ayaan Khan](http://github.com/ayaankhan98)
 * @author [Saurav Uppoor](https://github.com/sauravUppoor)
 *
 * @details
 * Depth First Search also quoted as DFS is a Graph Traversal Algorithm.
 * Time Complexity O(|V| + |E|) where V is number of vertices and E
 * is number of edges in graph.
 *
 * Application of Depth First Search are
 *
 * 1. Finding connected components
 * 2. Finding 2-(edge or vertex)-connected components.
 * 3. Finding 3-(edge or vertex)-connected components.
 * 4. Finding the bridges of a graph.
 * 5. Generating words in order to plot the limit set of a group.
 * 6. Finding strongly connected components.
 *
 * <h4>Working</h4>
 * 1. Mark all vertices as unvisited (colour it WHITE).
 * 2. Push starting vertex into the stack and colour it GREY.
 * 3. Once a node is popped out of the stack and is coloured GREY, we colour it BLACK.
 * 4. Push all its neighbours which are not coloured BLACK.
 * 5. Repeat steps 4 and 5 until the stack is empty.
 */

#include <iostream> 	 /// for IO operations
#include <stack>    	 /// header for std::stack
#include <vector>   	 /// header for std::vector
#include <cassert>  	 /// header for preprocessor macro assert() 
#include <limits>   	 /// header for limits of integral types

constexpr int WHITE = 0; /// indicates the node hasn't been explored
constexpr int GREY = 1;	 /// indicates node is in stack waiting to be explored
constexpr int BLACK = 2; /// indicates node has already been explored
constexpr int64_t INF = std::numeric_limits<int16_t>::max();


/**
 * @namespace graph
 * @brief Graph algorithms
 */
namespace graph {
/**
 * @namespace depth_first_search
 * @brief Functions for [Depth First Search](https://en.wikipedia.org/wiki/Depth-first_search) algorithm
 */
namespace depth_first_search {
/**
 * @brief
 * Adds and edge between two vertices of graph say u and v in this
 * case.
 *
 * @param adj Adjacency list representation of graph
 * @param u first vertex
 * @param v second vertex
 *
 */
void addEdge(std::vector<std::vector<size_t>> *adj, size_t u, size_t v) {
	/*
	*
	* Here we are considering undirected graph that's the
	* reason we are adding v to the adjacency list representation of u
	* and also adding u to the adjacency list representation of v
	*
	*/
	(*adj)[u - 1].push_back(v - 1);
}

/**
 *
 * @brief
 * Explores the given vertex, exploring a vertex means traversing
 * over all the vertices which are connected to the vertex that is
 * currently being explored and push it onto the stack.
 *
 * @param adj graph
 * @param start starting vertex for DFS
 * @return vector with nodes stored in the order of DFS traversal
 *
 */
std::vector<size_t> dfs(const std::vector<std::vector<size_t> > &graph, size_t start) {
    /// checked[i] stores the status of each node
    std::vector<size_t> checked(graph.size(), WHITE), traversed_path;

    checked[start] = GREY;
    std::stack<size_t> stack;
    stack.push(start);

    /// while stack is not empty we keep exploring the node on top of stack
    while (!stack.empty()) {
        int act = stack.top();
        stack.pop();

        if (checked[act] == GREY) {
            /// push the node to the final result vector
            traversed_path.push_back(act + 1);

            /// exploring the neighbours of the current node
            for (auto it : graph[act]) {
                stack.push(it);
                if (checked[it] != BLACK) {
                    checked[it] = GREY;
                }
            }
            checked[act] = BLACK;  /// Node has been explored
        }
    }
    return traversed_path;
}
}  // namespace depth_first_search
}  // namespace graph

