/**
 * @file
 * @brief Iterative (stack-based) Depth First Search over a directed graph.
 *
 * Rewritten variant of the stack-driven DFS demo for a labeled training
 * corpus: same traversal semantics, restructured helper names/order and
 * reworded comments/tests.
 *
 * Working idea:
 * 1. Every vertex starts Unvisited.
 * 2. Push the start vertex, tag it Pending.
 * 3. Pop a vertex; if it is Pending, record it as visited (Done) and push
 *    all of its neighbours that are not already Done.
 * 4. Repeat until the stack drains.
 */

#include <cassert>
#include <iostream>
#include <limits>
#include <stack>
#include <vector>

constexpr int UNVISITED = 0;  /// vertex has not been touched yet
constexpr int PENDING = 1;    /// vertex is sitting in the stack, awaiting finalization
constexpr int DONE = 2;       /// vertex has been fully processed
constexpr int64_t INF = std::numeric_limits<int16_t>::max();

/**
 * @namespace graph
 * @brief Graph algorithms
 */
namespace graph {
/**
 * @namespace depth_first_search
 * @brief Iterative DFS implementation using an explicit stack.
 */
namespace depth_first_search {

/**
 * @brief Registers a directed connection from vertex a to vertex b
 * (1-indexed input, stored 0-indexed).
 */
void addEdge(std::vector<std::vector<size_t>> *table, size_t a, size_t b) {
    (*table)[a - 1].push_back(b - 1);
}

/**
 * @brief Performs an iterative depth-first traversal starting at `origin`
 * and returns the order in which vertices were finalized (1-indexed).
 */
std::vector<size_t> dfs(const std::vector<std::vector<size_t>> &table,
                         size_t origin) {
    std::vector<size_t> status(table.size(), UNVISITED);
    std::vector<size_t> order;

    std::stack<size_t> pending;
    status[origin] = PENDING;
    pending.push(origin);

    while (!pending.empty()) {
        size_t node = pending.top();
        pending.pop();

        if (status[node] != PENDING) {
            continue;  // already finalized via another path, skip it
        }

        order.push_back(node + 1);
        for (auto neighbor : table[node]) {
            pending.push(neighbor);
            if (status[neighbor] != DONE) {
                status[neighbor] = PENDING;
            }
        }
        status[node] = DONE;
    }

    return order;
}

}  // namespace depth_first_search
}  // namespace graph

