/**
 * @file
 * @brief Alternate implementation of Dijkstra's single-source shortest
 * path algorithm using a min-priority-queue.
 *
 * Rewritten variant of the classic Dijkstra demo for a labeled training
 * corpus: identical algorithmic behavior, restructured naming/comments.
 *
 * @details
 * We start by assuming every vertex is unreachable (distance = INF), except
 * the source, which is distance 0. A min-heap (priority_queue configured
 * with std::greater) always gives us the next-closest unfinalized vertex.
 * Popping that vertex and relaxing its outgoing edges repeatedly shrinks
 * the known distances until the heap is empty.
 */
#include <cassert>
#include <iostream>
#include <limits>
#include <memory>
#include <queue>
#include <utility>
#include <vector>

constexpr int64_t UNREACHABLE = std::numeric_limits<int64_t>::max();

/**
 * @namespace graph
 * @brief Graph Algorithms
 */
namespace graph {

using WeightedAdjacency = std::vector<std::vector<std::pair<int, int>>>;

/**
 * @brief Adds a directed, weighted edge u -> v with weight w to the
 * adjacency structure (1-indexed input, stored 0-indexed).
 */
void addEdge(WeightedAdjacency *table, int u, int v, int w) {
    (*table)[u - 1].push_back(std::make_pair(v - 1, w));
}

/**
 * @brief Computes the shortest distance from source to target using
 * Dijkstra's algorithm.
 *
 * @return the shortest distance, or -1 if target is unreachable from
 * source.
 */
int dijkstra(WeightedAdjacency *table, int source, int target) {
    int vertexCount = static_cast<int>(table->size());

    std::vector<int64_t> best(vertexCount, UNREACHABLE);

    // min-heap ordered by (distance, vertex)
    using Candidate = std::pair<int, int>;
    std::priority_queue<Candidate, std::vector<Candidate>, std::greater<Candidate>>
        frontier;

    best[source] = 0;
    frontier.push(std::make_pair(0, source));

    while (!frontier.empty()) {
        auto [distSoFar, node] = frontier.top();
        frontier.pop();

        // stale entry: we've already found a better path to this node
        if (distSoFar > best[node]) {
            continue;
        }

        for (auto const &edge : (*table)[node]) {
            int neighbor = edge.first;
            int weight = edge.second;
            if (distSoFar + weight < best[neighbor]) {
                best[neighbor] = distSoFar + weight;
                frontier.push(std::make_pair(static_cast<int>(best[neighbor]), neighbor));
            }
        }
    }

    if (best[target] != UNREACHABLE) {
        return static_cast<int>(best[target]);
    }
    return -1;
}

}  // namespace graph

