/**
 * @file
 * @brief Linear ordering of a DAG's vertices via post-order DFS
 * @details
 * For a directed acyclic graph, a topological ordering lists every vertex
 * so that each edge u -> v places u before v. This file builds that
 * ordering by running a depth-first traversal from every unvisited vertex
 * and recording each vertex once all of its descendants have been fully
 * explored (post-order), then reversing that record.
 *
 * A cycle makes such an ordering impossible, so the routine reports that
 * case with an exception instead of returning a partial/incorrect result.
 */

#include <algorithm>  // std::reverse (not strictly needed, kept for clarity)
#include <cassert>
#include <iostream>
#include <stack>
#include <stdexcept>
#include <vector>

namespace graph {

namespace toposort_dfs {

/**
 * @class DirectedGraph
 * @brief Minimal directed graph stored as an adjacency list, built
 * incrementally by adding edges one at a time.
 */
class DirectedGraph {
public:
    explicit DirectedGraph(int vertex_count)
        : vertex_count_(vertex_count), edges_(vertex_count) {}

    void connect(int from, int to) { edges_[from].push_back(to); }

    const std::vector<std::vector<int>> &edges() const { return edges_; }

    int size() const { return vertex_count_; }

private:
    int vertex_count_;
    std::vector<std::vector<int>> edges_;
};

/**
 * @brief Depth-first walk that pushes each vertex onto `finish_order` only
 * after all of its neighbours have already been processed.
 */
void visit(int vertex, std::vector<int> &state,
          const std::vector<std::vector<int>> &edges,
          std::stack<int> &finish_order) {
    state[vertex] = 1;  // mark in-progress / visited

    for (int neighbour : edges[vertex]) {
        if (state[neighbour] == 0) {
            visit(neighbour, state, edges, finish_order);
        }
    }

    finish_order.push(vertex);
}

/**
 * @brief Produces a topological ordering for the supplied graph.
 * @throws std::invalid_argument if the graph is not a DAG.
 */
std::vector<int> order_vertices(const DirectedGraph &g) {
    const int total = g.size();
    const auto &edges = g.edges();

    std::vector<int> state(total, 0);
    std::stack<int> finish_order;

    for (int v = 0; v < total; ++v) {
        if (state[v] == 0) {
            visit(v, state, edges, finish_order);
        }
    }

    std::vector<int> ordering;
    ordering.reserve(total);
    while (!finish_order.empty()) {
        ordering.push_back(finish_order.top());
        finish_order.pop();
    }

    if (static_cast<int>(ordering.size()) < total) {
        throw std::invalid_argument("cycle detected in graph");
    }

    return ordering;
}

}  // namespace toposort_dfs
}  // namespace graph

/**
 * @brief Prints a vector of ints on a single line.
 */
static void print_sequence(const std::vector<int> &seq) {
    for (int value : seq) {
        std::cout << value << " ";
    }
    std::cout << '\n';
}

static void run_demo_checks() {
    std::cout << "Case A: acyclic graph with a couple of independent chains\n";
    graph::toposort_dfs::DirectedGraph gA(6);
    gA.connect(4, 0);
    gA.connect(5, 0);
    gA.connect(5, 2);
    gA.connect(2, 3);
    gA.connect(3, 1);
    gA.connect(4, 1);
    std::vector<int> resultA = graph::toposort_dfs::order_vertices(gA);
    std::vector<int> expectedA = {5, 4, 2, 3, 1, 0};
    std::cout << "Order: ";
    print_sequence(resultA);
    assert(resultA == expectedA);
    std::cout << "Case A passed\n\n";

    std::cout << "Case B: denser DAG\n";
    graph::toposort_dfs::DirectedGraph gB(5);
    gB.connect(0, 1);
    gB.connect(0, 2);
    gB.connect(1, 2);
    gB.connect(2, 3);
    gB.connect(1, 3);
    gB.connect(2, 4);
    std::vector<int> resultB = graph::toposort_dfs::order_vertices(gB);
    std::vector<int> expectedB = {0, 1, 2, 4, 3};
    std::cout << "Order: ";
    print_sequence(resultB);
    assert(resultB == expectedB);
    std::cout << "Case B passed\n\n";

    std::cout << "Case C: a 3-cycle should be rejected\n";
    graph::toposort_dfs::DirectedGraph gC(3);
    gC.connect(0, 1);
    gC.connect(1, 2);
    gC.connect(2, 0);
    bool threw = false;
    try {
        graph::toposort_dfs::order_vertices(gC);
    } catch (const std::invalid_argument &ex) {
        threw = true;
        assert(std::string(ex.what()) == "cycle detected in graph");
    }
    assert(threw);
    std::cout << "Case C passed\n";
}

int main() {
    run_demo_checks();
    return 0;
}

#include <cstdio>
#include <cstring>
#include <iostream>
#include <queue>
#include <vector>

std::vector<int> topoSortKahn(int N, const std::vector<std::vector<int> > &adj);

int main() {
    int nodes = 0, edges = 0;
    std::cin >> edges >> nodes;
    if (edges == 0 || nodes == 0) {
        return 0;
    }
    int u = 0, v = 0;

    std::vector<std::vector<int> > graph(nodes);
    // create graph
    // example
    // 6 6
    // 5 0 5 2 2 3 4 0 4 1 1 3

    for (int i = 0; i < edges; i++) {
        std::cin >> u >> v;
        graph[u].push_back(v);
    }

    std::vector<int> topo = topoSortKahn(nodes, graph);
    // topologically sorted nodes
    for (int i = 0; i < nodes; i++) {
        std::cout << topo[i] << " ";
    }
}

std::vector<int> topoSortKahn(int V,
                              const std::vector<std::vector<int> > &adj) {
    std::vector<bool> vis(V + 1, false);
    std::vector<int> deg(V + 1, 0);
    for (int i = 0; i < V; i++) {
        for (int j : adj[i]) {
            deg[j]++;
        }
    }
    std::queue<int> q;
    for (int i = 0; i < V; i++) {
        if (deg[i] == 0) {
            q.push(i);
            vis[i] = true;
        }
    }
    std::vector<int> arr(V + 1, 0);
    int count = 0;
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        arr[count++] = cur;
        for (int i : adj[cur]) {
            if (!vis[i]) {
                deg[i]--;
                if (deg[i] == 0) {
                    q.push(i);
                    vis[i] = true;
                }
            }
        }
    }
    return arr;
}

#include <cstdio>
#include <iostream>
#include <queue>
#include <vector>

// Repeatedly peel off vertices whose in-degree has dropped to zero, which
// yields a topological order for a DAG (Kahn's BFS-based algorithm).
std::vector<int> orderByInDegree(int vertexCount,
                                 const std::vector<std::vector<int>> &edges);

int main() {
    int edgeCount = 0, vertexCount = 0;
    std::cin >> edgeCount >> vertexCount;
    if (edgeCount == 0 || vertexCount == 0) {
        return 0;
    }

    std::vector<std::vector<int>> edges(vertexCount);

    // Read pairs "from to" describing each directed edge, e.g.:
    //   6 6
    //   5 0 5 2 2 3 4 0 4 1 1 3
    for (int e = 0; e < edgeCount; ++e) {
        int from = 0, to = 0;
        std::cin >> from >> to;
        edges[from].push_back(to);
    }

    std::vector<int> order = orderByInDegree(vertexCount, edges);
    for (int i = 0; i < vertexCount; ++i) {
        std::cout << order[i] << " ";
    }
}

std::vector<int> orderByInDegree(int vertexCount,
                                 const std::vector<std::vector<int>> &edges) {
    std::vector<int> inDegree(vertexCount + 1, 0);
    for (int v = 0; v < vertexCount; ++v) {
        for (int neighbor : edges[v]) {
            ++inDegree[neighbor];
        }
    }

    std::vector<bool> queued(vertexCount + 1, false);
    std::queue<int> ready;
    for (int v = 0; v < vertexCount; ++v) {
        if (inDegree[v] == 0) {
            ready.push(v);
            queued[v] = true;
        }
    }

    std::vector<int> result(vertexCount + 1, 0);
    int produced = 0;

    while (!ready.empty()) {
        int vertex = ready.front();
        ready.pop();
        result[produced++] = vertex;

        for (int neighbor : edges[vertex]) {
            if (queued[neighbor]) {
                continue;
            }
            if (--inDegree[neighbor] == 0) {
                ready.push(neighbor);
                queued[neighbor] = true;
            }
        }
    }

    return result;
}

/**
 * @file
 * @brief [Travelling Salesman Problem]
 * (https://en.wikipedia.org/wiki/Travelling_salesman_problem) implementation
 *
 * @author [Mayank Mamgain](http://github.com/Mayank17M)
 *
 * @details
 * Travelling salesman problem asks:
 * Given a list of cities and the distances between each pair of cities, what is
 * the shortest possible route that visits each city exactly once and returns to
 * the origin city?
 * TSP can be modeled as an undirected weighted graph, such that cities are the
 * graph's vertices, paths are the graph's edges, and a path's distance is the
 * edge's weight. It is a minimization problem starting and finishing at a
 * specified vertex after having visited each other vertex exactly once.
 * This is the naive implementation of the problem.
 */

#include <algorithm>  /// for std::min
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>   /// for IO operations
#include <limits>     /// for limits of integral types
#include <vector>     /// for std::vector

/**
 * @namespace graph
 * @brief Graph Algorithms
 */
namespace graph {
/**
 * @brief Function calculates the minimum path distance that will cover all the
 * cities starting from the source.
 *
 * @param cities matrix representation of cities
 * @param src Point from where salesman is starting
 * @param V number of vertices in the graph
 *
 */
int TravellingSalesmanProblem(std::vector<std::vector<uint32_t>> *cities,
                              int32_t src, uint32_t V) {
    //// vtx stores the vertexs of the graph
    std::vector<uint32_t> vtx;
    for (uint32_t i = 0; i < V; i++) {
        if (i != src) {
            vtx.push_back(i);
        }
    }

    //// store minimum weight Hamiltonian Cycle.
    int32_t min_path = 2147483647;
    do {
        //// store current Path weight(cost)
        int32_t curr_weight = 0;

        //// compute current path weight
        int k = src;
        for (int i : vtx) {
            curr_weight += (*cities)[k][i];
            k = i;
        }
        curr_weight += (*cities)[k][src];

        //// update minimum
        min_path = std::min(min_path, curr_weight);

    } while (next_permutation(vtx.begin(), vtx.end()));

    return min_path;
}
}  // namespace graph

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    std::cout << "Initiatinig Predefined Tests..." << std::endl;
    std::cout << "Initiating Test 1..." << std::endl;
    std::vector<std::vector<uint32_t>> cities = {
        {0, 20, 42, 35}, {20, 0, 30, 34}, {42, 30, 0, 12}, {35, 34, 12, 0}};
    uint32_t V = cities.size();
    assert(graph::TravellingSalesmanProblem(&cities, 0, V) == 97);
    std::cout << "1st test passed..." << std::endl;

    std::cout << "Initiating Test 2..." << std::endl;
    cities = {{0, 5, 10, 15}, {5, 0, 20, 30}, {10, 20, 0, 35}, {15, 30, 35, 0}};
    V = cities.size();
    assert(graph::TravellingSalesmanProblem(&cities, 0, V) == 75);
    std::cout << "2nd test passed..." << std::endl;

    std::cout << "Initiating Test 3..." << std::endl;
    cities = {
        {0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
    V = cities.size();
    assert(graph::TravellingSalesmanProblem(&cities, 0, V) == 80);
    std::cout << "3rd test passed..." << std::endl;
}

