    return 0;
}

/**
 * @file
 * @brief Brute-force [Travelling Salesman Problem]
 * (https://en.wikipedia.org/wiki/Travelling_salesman_problem) solver
 *
 * @details
 * Given pairwise distances between a set of cities, find the cheapest tour
 * that starts at a fixed city, visits every other city exactly once, and
 * returns to the start. This implementation tries every permutation of the
 * non-source cities and keeps the cheapest resulting cycle, so it only
 * scales to small instances (factorial time).
 */

#include <algorithm>  /// std::min, std::next_permutation
#include <cassert>
#include <cstdint>
#include <iostream>
#include <limits>
#include <vector>

namespace graph {

/**
 * @brief Evaluates every ordering of the non-source cities and returns the
 * weight of the cheapest full tour that returns to `start`.
 *
 * @param distance square matrix of pairwise city distances
 * @param start city index the tour must begin and end at
 * @param city_count number of cities in the instance
 */
int solve_tsp_bruteforce(std::vector<std::vector<uint32_t>> *distance,
                         int32_t start, uint32_t city_count) {
    std::vector<uint32_t> remaining_cities;
    for (uint32_t city = 0; city < city_count; ++city) {
        if (static_cast<int32_t>(city) != start) {
            remaining_cities.push_back(city);
        }
    }

    int32_t best_cost = std::numeric_limits<int32_t>::max();

    // Every permutation of the remaining cities corresponds to one candidate
    // tour; std::next_permutation walks through all of them in turn.
    do {
        int32_t tour_cost = 0;
        int previous = start;
        for (int city : remaining_cities) {
            tour_cost += static_cast<int32_t>((*distance)[previous][city]);
            previous = city;
        }
        tour_cost += static_cast<int32_t>((*distance)[previous][start]);

        best_cost = std::min(best_cost, tour_cost);
    } while (std::next_permutation(remaining_cities.begin(), remaining_cities.end()));

    return best_cost;
}

}  // namespace graph

/**
 * @brief Exercises the solver against a few hand-checked distance matrices.
 */
static void run_reference_cases() {
    std::cout << "Running reference TSP instances...\n";

    std::cout << "Instance 1\n";
    std::vector<std::vector<uint32_t>> map_a = {
        {0, 20, 42, 35}, {20, 0, 30, 34}, {42, 30, 0, 12}, {35, 34, 12, 0}};
    assert(graph::solve_tsp_bruteforce(&map_a, 0, map_a.size()) == 97);
    std::cout << "Instance 1 OK\n";

    std::cout << "Instance 2\n";
    std::vector<std::vector<uint32_t>> map_b = {
        {0, 5, 10, 15}, {5, 0, 20, 30}, {10, 20, 0, 35}, {15, 30, 35, 0}};
    assert(graph::solve_tsp_bruteforce(&map_b, 0, map_b.size()) == 75);
    std::cout << "Instance 2 OK\n";

    std::cout << "Instance 3\n";
    std::vector<std::vector<uint32_t>> map_c = {
        {0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
    assert(graph::solve_tsp_bruteforce(&map_c, 0, map_c.size()) == 80);
    std::cout << "Instance 3 OK\n";
}

int main() {
    run_reference_cases();

    std::vector<std::vector<uint32_t>> map_demo = {
        {0, 5, 10, 15}, {5, 0, 20, 30}, {10, 20, 0, 35}, {15, 30, 35, 0}};
    std::cout << graph::solve_tsp_bruteforce(&map_demo, 0, map_demo.size()) << std::endl;
    return 0;
}

/**
 * @file
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Implementation of
 * [Spirograph](https://en.wikipedia.org/wiki/Spirograph)
 *
 * @details
 * Implementation of the program is based on the geometry shown in the figure
 * below:
 *
 * <a
 * href="https://commons.wikimedia.org/wiki/File:Resonance_Cascade.svg"><img
 * src="https://upload.wikimedia.org/wikipedia/commons/3/39/Resonance_Cascade.svg"
 * alt="Spirograph geometry from Wikipedia" style="width: 250px"/></a>
 */
#ifdef USE_GLUT
#ifdef __APPLE__
#include <GLUT/glut.h>  // include path on Macs is different
#else
#include <GL/glut.h>
#endif  // __APPLE__
#endif
#define _USE_MATH_DEFINES /**< required for MSVC compiler */
#include <array>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#ifdef _OPENMP
#include <omp.h>
#endif

/**
 * @namespace spirograph Functions related to spirograph.cpp
 */
namespace spirograph {
/** Generate spirograph curve into arrays `x` and `y` such that the i^th point
 * in 2D is represented by `(x[i],y[i])`. The generating function is given by:
 * \f{eqnarray*}{
 * x &=& R\left[ (1-k) \cos (t) + l\cdot k\cdot\cos \left(\frac{1-k}{k}t\right)
 * \right]\\
 * y &=& R\left[ (1-k) \sin (t) - l\cdot k\cdot\sin \left(\frac{1-k}{k}t\right)
 * \right] \f}
 * where
 * * \f$R\f$ is the scaling parameter that we will consider \f$=1\f$
 * * \f$l=\frac{\rho}{r}\f$ is the relative distance of marker from the centre
 * of inner circle and \f$0\le l\le1\f$
 * * \f$\rho\f$ is physical distance of marker from centre of inner circle
 * * \f$r\f$ is the radius of inner circle
 * * \f$k=\frac{r}{R}\f$ is the ratio of radius of inner circle to outer circle
 * and \f$0<k<1\f$
 * * \f$R\f$ is the radius of outer circle
 * * \f$t\f$ is the angle of rotation of the point i.e., represents the time
 * parameter
 *
 * Since we are considering ratios, the actual values of \f$r\f$ and
 * \f$R\f$ are immaterial.
 *
 * @tparam N number of points = size of array
 * @param [out] points Array of 2D points represented as std::pair
 * @param l the relative distance of marker from the centre of
 * inner circle and \f$0\le l\le1\f$
 * @param k the ratio of radius of inner circle to outer circle and \f$0<k<1\f$
 * @param rot the number of rotations to perform (can be fractional value)
 */
template <std::size_t N>
void spirograph(std::array<std::pair<double, double>, N> *points, double l,
                double k, double rot) {
    double dt = rot * 2.f * M_PI / N;
    double R = 1.f;
    const double k1 = 1.f - k;
    int32_t step = 0;

#ifdef _OPENMP
#pragma omp for
#endif
    for (step = 0; step < N; step++) {
        double t = dt * step;
        double first = R * (k1 * std::cos(t) + l * k * std::cos(k1 * t / k));
        double second = R * (k1 * std::sin(t) - l * k * std::sin(k1 * t / k));
        points[0][step].first = first;
        points[0][step].second = second;
    }
}

/**
 * @brief Test function to save resulting points to a CSV file.
 *
 */
void test() {
    const size_t N = 500;
    double l = 0.3, k = 0.75, rot = 10.;
    std::stringstream fname;
    fname << std::setw(3) << "spirograph_" << l << "_" << k << "_" << rot
          << ".csv";
    std::ofstream fp(fname.str());
    if (!fp.is_open()) {
        perror(fname.str().c_str());
        exit(EXIT_FAILURE);
    }

    std::array<std::pair<double, double>, N> points;

    spirograph(&points, l, k, rot);

    for (size_t i = 0; i < N; i++) {
        fp << points[i].first << "," << points[i].first;
        if (i < N - 1) {
            fp << '\n';
        }
    }

    fp.close();
}

