/**
 * @file
 * @brief Alternate demonstration of the "cheapest incident edge per vertex"
 * step that underlies Kruskal's minimum-spanning-tree construction.
 *
 * @details
 * Kruskal's algorithm treats every vertex as its own tree initially and
 * repeatedly merges the two trees connected by the cheapest edge that does
 * not create a cycle. This file focuses on the per-vertex cheapest-edge
 * lookup used as a building block, tested against a variety of adjacency
 * matrices (square, non-square, negative weights, directed, etc).
 *
 * @author rewritten for the classroom dataset
 */

#include <array>     /// fixed-size array container
#include <iostream>  /// console IO
#include <limits>    /// numeric_limits
#include <cstdint>   /// uint32_t

/**
 * @namespace
 * @brief Greedy Algorithms
 */
namespace greedy_algorithms {

/**
 * @brief Prints, for every vertex, the cheapest outgoing edge in an
 * adjacency-matrix graph.
 * @param noEdgeMarker Sentinel value that represents "no edge"/infinity.
 * @param adjMatrix The square adjacency matrix describing edge weights.
 * @returns void
 */
template <typename Weight, std::size_t Rows, std::size_t Cols>
void reportCheapestEdges(const Weight &noEdgeMarker,
                          const std::array<std::array<Weight, Rows>, Cols> &adjMatrix) {
    if (Rows != Cols) {
        std::cout << "\nWrong input passed. Provided array has dimensions " << Rows
                  << "x" << Cols << ". Please provide a square matrix.\n";
        return;
    }
    for (int row = 0; row < adjMatrix.size(); row++) {
        int cheapest = noEdgeMarker;
        int cheapestCol = 0;
        for (int col = 0; col < adjMatrix.size(); col++) {
            if (row != col && adjMatrix[row][col] != 0 && adjMatrix[row][col] < cheapest) {
                cheapest = adjMatrix[row][col];
                cheapestCol = col;
            }
        }
        std::cout << row << "  -  " << cheapestCol << "\t" << adjMatrix[row][cheapestCol]
                  << "\n";
    }
}

}  // namespace greedy_algorithms

/**
 * @brief Runs a battery of scenario checks against reportCheapestEdges.
 * @returns void
 */
static void runScenarios() {
    constexpr int NO_EDGE_INT = std::numeric_limits<int>::max();
    constexpr float NO_EDGE_FLOAT = std::numeric_limits<float>::max();
    constexpr double NO_EDGE_DOUBLE = std::numeric_limits<double>::max();
    constexpr uint32_t NO_EDGE_UINT32 = UINT32_MAX;

    // Scenario 1: integer-weighted graph
    std::cout << "\nTest Case 1 :\n";
    std::array<std::array<int, 6>, 6> g1{
             0,            4,            1,             4,        NO_EDGE_INT,   NO_EDGE_INT,
             4,            0,            3,             8,             3,         NO_EDGE_INT,
             1,            3,            0,        NO_EDGE_INT,       1,         NO_EDGE_INT,
             4,            8,       NO_EDGE_INT,        0,            5,              7,
        NO_EDGE_INT,      3,            1,              5,            0,         NO_EDGE_INT,
        NO_EDGE_INT, NO_EDGE_INT, NO_EDGE_INT,        7,       NO_EDGE_INT,       0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, g1);

    // Scenario 2: floating-point weights
    std::cout << "\nTest Case 2 :\n";
    std::array<std::array<float, 3>, 3> g2{
             0.0f,           2.5f,  NO_EDGE_FLOAT,
             2.5f,           0.0f,       3.2f,
        NO_EDGE_FLOAT,      3.2f,       0.0f};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_FLOAT, g2);

    // Scenario 3: double-precision weights
    std::cout << "\nTest Case 3 :\n";
    std::array<std::array<double, 5>, 5> g3{
               0.0,             10.5,       NO_EDGE_DOUBLE,        6.7,              3.3,
               10.5,            0.0,              8.1,              15.4,       NO_EDGE_DOUBLE,
        NO_EDGE_DOUBLE,        8.1,              0.0,        NO_EDGE_DOUBLE,         7.8,
               6.7,             15.4,       NO_EDGE_DOUBLE,        0.0,               9.9,
               3.3,       NO_EDGE_DOUBLE,        7.8,              9.9,               0.0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_DOUBLE, g3);

    // Scenario 4: negative weights
    std::cout << "\nTest Case 4 :\n";
    std::array<std::array<int, 3>, 3> gNeg{
        0,   -2,   4,
       -2,    0,   3,
        4,    3,   0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gNeg);

    // Scenario 5: self-loops present
    std::cout << "\nTest Case 5 :\n";
    std::array<std::array<int, 3>, 3> gSelfLoop{
               2,       1, NO_EDGE_INT,
        NO_EDGE_INT,   0,        4,
        NO_EDGE_INT,   4,        0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gSelfLoop);

    // Scenario 6: no edges at all
    std::cout << "\nTest Case 6 :\n";
    std::array<std::array<int, 4>, 4> gNoEdges{
               0,       NO_EDGE_INT,   NO_EDGE_INT,   NO_EDGE_INT,
        NO_EDGE_INT,         0,        NO_EDGE_INT,   NO_EDGE_INT,
        NO_EDGE_INT,   NO_EDGE_INT,          0,       NO_EDGE_INT,
        NO_EDGE_INT,   NO_EDGE_INT,   NO_EDGE_INT,           0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gNoEdges);

    // Scenario 7: disconnected components
    std::cout << "\nTest Case 7:\n";
    std::array<std::array<int, 4>, 4> gPartial{
                0,             2,    NO_EDGE_INT,         6,
                2,             0,            3,     NO_EDGE_INT,
        NO_EDGE_INT,          3,            0,             4,
                6,     NO_EDGE_INT,         4,             0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gPartial);

    // Scenario 8: directed graph (result is not a true MST in this case)
    std::cout << "\nTest Case 8:\n";
    std::array<std::array<int, 4>, 4> gDirected{
                0,            3,            7,   NO_EDGE_INT,
        NO_EDGE_INT,         0,            2,           5,
        NO_EDGE_INT, NO_EDGE_INT,         0,           1,
        NO_EDGE_INT, NO_EDGE_INT, NO_EDGE_INT,        0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gDirected);

    // Scenario 9: malformed (non-square) input
    std::cout << "\nTest Case 9:\n";
    std::array<std::array<int, 4>, 3> gBadShape{
        0,        5,        5,        5,
        5,        0,        5,        5,
        5,        5,        5,        5};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gBadShape);

    // Scenario 10: uniform edge weights
    std::cout << "\nTest Case 10:\n";
    std::array<std::array<int, 5>, 5> gUniform{
        0,        5,        5,        5,        5,
        5,        0,        5,        5,        5,
        5,        5,        0,        5,        5,
        5,        5,        5,        0,        5,
        5,        5,        5,        5,        0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_INT, gUniform);

    // Scenario 11: unsigned 32-bit weights
    std::cout << "\nTest Case 11 :\n";
    std::array<std::array<uint32_t, 4>, 4> gUint32{
                0,                      5,        NO_EDGE_UINT32,          9,
                5,                      0,                2,        NO_EDGE_UINT32,
        NO_EDGE_UINT32,                2,                0,                6,
                9,               NO_EDGE_UINT32,         6,                0};
    greedy_algorithms::reportCheapestEdges(NO_EDGE_UINT32, gUint32);

    std::cout << "\nAll tests have successfully passed!\n";
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runScenarios();
    return 0;
}

#include <iostream>
using namespace std;

#define V 4
#define INFINITY 99999

int graph[V][V] = {{0, 5, 1, 2}, {5, 0, 3, 3}, {1, 3, 0, 4}, {2, 3, 4, 0}};

struct mst {
    bool visited;
    int key;
    int near;
};

mst MST_Array[V];

void initilize() {
    for (int i = 0; i < V; i++) {
        MST_Array[i].visited = false;
        MST_Array[i].key = INFINITY;  // considering INFINITY as inifinity
        MST_Array[i].near = i;
    }

    MST_Array[0].key = 0;
}

void updateNear() {
    for (int v = 0; v < V; v++) {
        int min = INFINITY;
        int minIndex = 0;
        for (int i = 0; i < V; i++) {
            if (MST_Array[i].key < min && MST_Array[i].visited == false &&
                MST_Array[i].key != INFINITY) {
                min = MST_Array[i].key;
                minIndex = i;
            }
        }

        MST_Array[minIndex].visited = true;

        for (int i = 0; i < V; i++) {
            if (graph[minIndex][i] != 0 && graph[minIndex][i] < INFINITY) {
                if (graph[minIndex][i] < MST_Array[i].key) {
                    MST_Array[i].key = graph[minIndex][i];
                    MST_Array[i].near = minIndex;
                }
            }
        }
    }
}

void show() {
    for (int i = 0; i < V; i++) {
        cout << i << "  -  " << MST_Array[i].near << "\t"
             << graph[i][MST_Array[i].near] << "\n";
    }
}

int main() {
    initilize();
    updateNear();
    show();
    return 0;
}

#include <iostream>
using namespace std;

#define NUM_VERTICES 4
#define BIG_NUMBER 99999

// Adjacency matrix describing edge weights between the 4 vertices.
int adjacency[NUM_VERTICES][NUM_VERTICES] = {
    {0, 5, 1, 2}, {5, 0, 3, 3}, {1, 3, 0, 4}, {2, 3, 4, 0}};

// Per-vertex bookkeeping for Prim's algorithm: whether it has joined the
// spanning tree yet, its current best connecting cost, and which tree
// vertex it currently connects through.
struct VertexRecord {
    bool inTree;
    int bestCost;
    int viaVertex;
};

VertexRecord records[NUM_VERTICES];

// Resets bookkeeping so vertex 0 is the tree's starting point.
void resetRecords() {
    for (int i = 0; i < NUM_VERTICES; i++) {
        records[i].inTree = false;
        records[i].bestCost = BIG_NUMBER;  // BIG_NUMBER stands in for infinity
        records[i].viaVertex = i;
    }
    records[0].bestCost = 0;
}

// Repeatedly pulls the cheapest untouched vertex into the tree and relaxes
// its neighbors' connecting costs.
void growTree() {
    for (int round = 0; round < NUM_VERTICES; round++) {
        int cheapest = BIG_NUMBER;
        int chosen = 0;
        for (int i = 0; i < NUM_VERTICES; i++) {
            if (records[i].bestCost < cheapest && !records[i].inTree &&
                records[i].bestCost != BIG_NUMBER) {
                cheapest = records[i].bestCost;
                chosen = i;
            }
        }

        records[chosen].inTree = true;

        for (int i = 0; i < NUM_VERTICES; i++) {
            if (adjacency[chosen][i] != 0 && adjacency[chosen][i] < BIG_NUMBER) {
                if (adjacency[chosen][i] < records[i].bestCost) {
                    records[i].bestCost = adjacency[chosen][i];
                    records[i].viaVertex = chosen;
                }
            }
        }
    }
}

// Prints the resulting spanning tree edges.
void printTree() {
    for (int i = 0; i < NUM_VERTICES; i++) {
        cout << i << "  -  " << records[i].viaVertex << "\t"
             << adjacency[i][records[i].viaVertex] << "\n";
    }
}

int main() {
    resetRecords();
    growTree();
    printTree();
    return 0;
}

/**
 * @file chaining.cpp
 * @author [vasutomar](https://github.com/vasutomar)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Implementation of [hash
 * chains](https://en.wikipedia.org/wiki/Hash_chain).
 */
#include <cmath>
#include <iostream>
#include <memory>
#include <vector>

/**
 * @brief Chain class with a given modulus
 */
class hash_chain {
 private:
    /**
     * @brief Define a linked node
     */
    using Node = struct Node {
        int data{};                         ///< data stored in the node
        std::shared_ptr<struct Node> next;  ///< pointer to the next node
    };

    std::vector<std::shared_ptr<Node>> head;  ///< array of nodes
    int _mod;                                 ///< modulus of the class

 public:
    /**
     * @brief Construct a new chain object
     *
     * @param mod modulus of the chain
     */
    explicit hash_chain(int mod) : _mod(mod) {
        while (mod--) head.push_back(nullptr);
    }

    /**
     * @brief create and add a new node with a give value and at a given height
     *
     * @param x value at the new node
     * @param h height of the node
     */
    void add(int x, int h) {
        std::shared_ptr<Node> curr;
        std::shared_ptr<Node> temp(new Node);
        temp->data = x;
        temp->next = nullptr;
        if (!head[h]) {
            head[h] = temp;
            curr = head[h];
        } else {
            curr = head[h];
            while (curr->next) curr = curr->next;
            curr->next = temp;
        }
    }

    /**
     * @brief Display the chain
     */
    void display() {
        std::shared_ptr<Node> temp = nullptr;
        int i = 0;
        for (i = 0; i < _mod; i++) {
            if (!head[i]) {
                std::cout << "Key " << i << " is empty" << std::endl;
            } else {
                std::cout << "Key " << i << " has values = " << std::endl;
                temp = head[i];
                while (temp->next) {
                    std::cout << temp->data << " " << std::endl;
                    temp = temp->next;
                }
                std::cout << temp->data;
                std::cout << std::endl;
            }
        }
    }

    /**
     * @brief Compute the hash of a value for current chain
     *
     * @param x value to compute modulus of
     * @return modulus of `x`
     * @note declared as a
     * [`virtual`](https://en.cppreference.com/w/cpp/language/virtual) so that
     * custom implementations of the class can modify the hash function.
     */
    virtual int hash(int x) const { return x % _mod; }

    /**
     * @brief Find if a value and corresponding hash exist
     *
     * @param x value to search for
     * @param h corresponding hash key
     * @returns `true` if element found
     * @returns `false` if element not found
     */
    bool find(int x, int h) const {
        std::shared_ptr<Node> temp = head[h];
        if (!head[h]) {
            // index does not exist!
            std::cout << "Element not found" << std::endl;
            return false;
        }

        // scan for data value
        while (temp->data != x && temp->next) temp = temp->next;

        if (temp->next) {
            std::cout << "Element found" << std::endl;
            return true;
        }

        // implicit else condition
        // i.e., temp->next == nullptr
        if (temp->data == x) {
            std::cout << "Element found" << std::endl;
            return true;
        }

        // further implicit else condition
        std::cout << "Element not found" << std::endl;
        return false;
    }
};

/** Main function
 * @returns `0` always
 */
int main() {
    int c = 0, x = 0, mod = 0, h = 0;
    std::cout << "Enter the size of Hash Table. = " << std::endl;
    std::cin >> mod;

    hash_chain mychain(mod);

    bool loop = true;
    while (loop) {
        std::cout << std::endl;
        std::cout << "PLEASE CHOOSE -" << std::endl;
        std::cout << "1. Add element." << std::endl;
        std::cout << "2. Find element." << std::endl;
        std::cout << "3. Generate Hash." << std::endl;
        std::cout << "4. Display Hash table." << std::endl;
        std::cout << "5. Exit." << std::endl;
        std::cin >> c;
        switch (c) {
            case 1:
                std::cout << "Enter element to add = " << std::endl;
                std::cin >> x;
                h = mychain.hash(x);
                h = std::abs(h);
                mychain.add(x, h);
                break;
            case 2:
                std::cout << "Enter element to search = " << std::endl;
                std::cin >> x;
                h = mychain.hash(x);
                mychain.find(x, h);
                break;
            case 3:
                std::cout << "Enter element to generate hash = " << std::endl;
                std::cin >> x;
                std::cout << "Hash of " << x << " is = " << mychain.hash(x)
                          << std::endl;
                break;
            case 4:
                mychain.display();
                break;
            default:
                loop = false;
                break;
        }
        std::cout << std::endl;
    }
    /*add(1,&head1);
    add(2,&head1);
    add(3,&head2);
    add(5,&head1);
    display(&head1);
    display(&head2);*/
    return 0;
}

/**
 * Separate-chaining hash table demo.
 *
 * Every bucket keeps a singly linked list of the integers that hash
 * into it. Collisions are resolved simply by appending to the tail
 * of that bucket's list. See: https://en.wikipedia.org/wiki/Hash_chain
 */
#include <cmath>
#include <iostream>
#include <memory>
#include <vector>

/**
 * Bucketed integer set keyed by (value % bucketCount).
 */
class BucketedIntSet {
 private:
    struct Link {
        int value{};
        std::shared_ptr<Link> nxt;
    };

    std::vector<std::shared_ptr<Link>> buckets_;  // one list-head per bucket
    int bucketCount_;

 public:
    explicit BucketedIntSet(int bucketCount) : bucketCount_(bucketCount) {
        for (int i = 0; i < bucketCount; ++i) buckets_.push_back(nullptr);
    }

    /**
     * Insert value `v` into the bucket identified by `bucketIdx`.
     */
    void insert(int v, int bucketIdx) {
        auto fresh = std::make_shared<Link>();
        fresh->value = v;
        fresh->nxt = nullptr;

        if (!buckets_[bucketIdx]) {
            buckets_[bucketIdx] = fresh;
            return;
        }

        std::shared_ptr<Link> walker = buckets_[bucketIdx];
        while (walker->nxt) walker = walker->nxt;
        walker->nxt = fresh;
    }

    /**
     * Print every bucket and its contents.
     */
    void printAll() {
        for (int i = 0; i < bucketCount_; ++i) {
            if (!buckets_[i]) {
                std::cout << "Bucket " << i << " is empty" << std::endl;
                continue;
            }
            std::cout << "Bucket " << i << " has values = " << std::endl;
            auto walker = buckets_[i];
            while (walker->nxt) {
                std::cout << walker->value << " " << std::endl;
                walker = walker->nxt;
            }
            std::cout << walker->value << std::endl;
        }
    }

    /**
     * Compute the bucket index for a value. Declared virtual so
     * subclasses may swap in a different hashing scheme.
     */
    virtual int bucketFor(int v) const { return v % bucketCount_; }

    /**
     * Check whether `v` (expected in bucket `bucketIdx`) is present.
     */
    bool contains(int v, int bucketIdx) const {
        if (!buckets_[bucketIdx]) {
            std::cout << "Element not found" << std::endl;
            return false;
        }

        std::shared_ptr<Link> walker = buckets_[bucketIdx];
        while (walker->value != v && walker->nxt) walker = walker->nxt;

        if (walker->nxt || walker->value == v) {
            std::cout << "Element found" << std::endl;
            return true;
        }

        std::cout << "Element not found" << std::endl;
        return false;
    }
};

/**
 * Interactive demo: build a bucketed set and let the user add,
 * search and inspect it.
 */
int main() {
    int choice = 0, value = 0, bucketCount = 0, bucketIdx = 0;
    std::cout << "Enter the size of Hash Table. = " << std::endl;
    std::cin >> bucketCount;

    BucketedIntSet mySet(bucketCount);

    bool running = true;
    while (running) {
        std::cout << std::endl;
        std::cout << "PLEASE CHOOSE -" << std::endl;
        std::cout << "1. Add element." << std::endl;
        std::cout << "2. Find element." << std::endl;
        std::cout << "3. Generate Hash." << std::endl;
        std::cout << "4. Display Hash table." << std::endl;
        std::cout << "5. Exit." << std::endl;
        std::cin >> choice;
        switch (choice) {
            case 1:
                std::cout << "Enter element to add = " << std::endl;
                std::cin >> value;
                bucketIdx = std::abs(mySet.bucketFor(value));
                mySet.insert(value, bucketIdx);
                break;
            case 2:
                std::cout << "Enter element to search = " << std::endl;
                std::cin >> value;
                bucketIdx = mySet.bucketFor(value);
                mySet.contains(value, bucketIdx);
                break;
            case 3:
                std::cout << "Enter element to generate hash = " << std::endl;
                std::cin >> value;
                std::cout << "Hash of " << value
                          << " is = " << mySet.bucketFor(value) << std::endl;
                break;
            case 4:
                mySet.printAll();
                break;
            default:
                running = false;
                break;
        }
        std::cout << std::endl;
    }
    return 0;
}

/**
 * @file double_hash_hash_table.cpp
 * @author [achance6](https://github.com/achance6)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Storage mechanism using [double-hashed
 * keys](https://en.wikipedia.org/wiki/Double_hashing).
 * @note The implementation can be optimized by using OOP style.
 */
#include <iostream>
#include <memory>
#include <vector>

/**
 * @addtogroup open_addressing Open Addressing
 * @{
 * @namespace double_hashing
 * @brief An implementation of hash table using [double
 * hashing](https://en.wikipedia.org/wiki/Double_hashing) algorithm.
 */
namespace double_hashing {
// fwd declarations
using Entry = struct Entry;
bool putProber(const Entry& entry, int key);
bool searchingProber(const Entry& entry, int key);
void add(int key);

// Undocumented globals
int notPresent;
std::vector<Entry> table;
int totalSize;
int tomb = -1;
int size;
bool rehashing;

/** Node object that holds key */
struct Entry {
    explicit Entry(int key = notPresent) : key(key) {}  ///< constructor
    int key;                                            ///< key value
};

/**
 * @brief Hash a key. Uses the STL library's `std::hash()` function.
 *
 * @param key value to hash
 * @return hash value of the key
 */
size_t hashFxn(int key) {
    std::hash<int> hash;
    return hash(key);
}

/**
 * @brief Used for second hash function
 *
 * @param key key value to hash
 * @return  hash value of the key
 */
size_t otherHashFxn(int key) {
    std::hash<int> hash;
    return 1 + (7 - (hash(key) % 7));
}

/**
 * @brief Performs double hashing to resolve collisions
 *
 * @param key key value to apply double-hash on
 * @param searching `true` to check for conflicts
 * @return Index of key when found
 * @return new hash if no conflicts present
 */
int doubleHash(int key, bool searching) {
    int hash = static_cast<int>(hashFxn(key));
    int i = 0;
    Entry entry;
    do {
        int index =
            static_cast<int>(hash + (i * otherHashFxn(key))) % totalSize;
        entry = table[index];
        if (searching) {
            if (entry.key == notPresent) {
                return notPresent;
            }
            if (searchingProber(entry, key)) {
                std::cout << "Found key!" << std::endl;
                return index;
            }
            std::cout << "Found tombstone or equal hash, checking next"
                      << std::endl;
            i++;
        } else {
            if (putProber(entry, key)) {
                if (!rehashing) {
                    std::cout << "Spot found!" << std::endl;
                }
                return index;
            }
            if (!rehashing) {
                std::cout << "Spot taken, looking at next (next index:"
                          << " "
                          << static_cast<int>(hash + (i * otherHashFxn(key))) %
                                 totalSize
                          << ")" << std::endl;
            }
            i++;
        }
        if (i == totalSize * 100) {
            std::cout << "DoubleHash probe failed" << std::endl;
            return notPresent;
        }
    } while (entry.key != notPresent);
    return notPresent;
}

/** Finds empty spot in a vector
 * @param entry vector to search in
 * @param key key to search for
 * @returns `true` if key is not present or is a `toumb`
 * @returns `false` is already occupied
 */
bool putProber(const Entry& entry, int key) {
    if (entry.key == notPresent || entry.key == tomb) {
        return true;
    }
    return false;
}

/** Looks for a matching key
 * @param entry vector to search in
 * @param key key value to search
 * @returns `true` if found
 * @returns `false` if not found
 */
bool searchingProber(const Entry& entry, int key) {
    if (entry.key == key) {
        return true;
    }
    return false;
}

/** Displays the table
 * @returns None
 */
void display() {
    for (int i = 0; i < totalSize; i++) {
        if (table[i].key == notPresent) {
            std::cout << " Empty ";
        } else if (table[i].key == tomb) {
            std::cout << " Tomb ";
        } else {
            std::cout << " ";
            std::cout << table[i].key;
            std::cout << " ";
        }
    }
    std::cout << std::endl;
}

/** Rehashes the table into a bigger table
 * @returns None
 */
void rehash() {
    // Necessary so wall of add info isn't printed all at once
    rehashing = true;
    int oldSize = totalSize;
    std::vector<Entry> oldTable(table);
    // Really this should use the next prime number greater than totalSize * 2
    table = std::vector<Entry>(totalSize * 2);
    totalSize *= 2;
    for (int i = 0; i < oldSize; i++) {
        if (oldTable[i].key != -1 && oldTable[i].key != notPresent) {
            size--;  // Size stays the same (add increments size)
            add(oldTable[i].key);
        }
    }
    // delete[] oldTable;
    // oldTable.reset();

    rehashing = false;
    std::cout << "Table was rehashed, new size is: " << totalSize << std::endl;
}

/** Checks for load factor here
 * @param key key value to add to the table
 */
void add(int key) {
    // auto* entry = new Entry();
    // entry->key = key;
    int index = doubleHash(key, false);
    table[index].key = key;
    // Load factor greater than 0.5 causes resizing
    if (++size / static_cast<double>(totalSize) >= 0.5) {
        rehash();
    }
}

/** Removes key. Leaves tombstone upon removal.
 * @param key key value to remove
 */
void remove(int key) {
    int index = doubleHash(key, true);
    if (index == notPresent) {
        std::cout << "key not found" << std::endl;
    }
    table[index].key = tomb;
    std::cout << "Removal successful, leaving tombstone" << std::endl;
    size--;
}

/** Information about the adding process
 * @param key key value to add to table
 */
void addInfo(int key) {
    std::cout << "Initial table: ";
    display();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << hashFxn(key) << " % "
              << totalSize << " == " << hashFxn(key) % totalSize;
    std::cout << std::endl;
    add(key);
    std::cout << "New table: ";
    display();
}

/** Information about removal process
 * @param key key value to remove from table
 */
void removalInfo(int key) {
    std::cout << "Initial table: ";
    display();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << hashFxn(key) << " % "
              << totalSize << " == " << hashFxn(key) % totalSize;
    std::cout << std::endl;
    remove(key);
    std::cout << "New table: ";
    display();
}
}  // namespace double_hashing
/**
 * @}
 */

