/**
 * Open-addressing hash table resolving collisions via double hashing.
 * See: https://en.wikipedia.org/wiki/Double_hashing
 *
 * Note: a procedural / global-state style is used here on purpose,
 * mirroring a "quick script" implementation rather than a clean class.
 */
#include <iostream>
#include <memory>
#include <vector>

namespace dh_table {
// forward declarations
using Slot = struct Slot;
bool slotFreeForInsert(const Slot& slot, int key);
bool slotMatches(const Slot& slot, int key);
void insertKey(int key);

// shared mutable state (kept global to match the original quick-script feel)
int EMPTY_MARK;
std::vector<Slot> slots;
int capacity;
int GRAVE = -1;
int occupied;
bool inResizePass;

/** A single hash-table slot holding one key. */
struct Slot {
    explicit Slot(int key = EMPTY_MARK) : key(key) {}
    int key;
};

/**
 * Primary hash, delegated to std::hash<int>.
 */
size_t primaryHash(int key) {
    std::hash<int> hasher;
    return hasher(key);
}

/**
 * Secondary hash used as the probing step size.
 */
size_t stepHash(int key) {
    std::hash<int> hasher;
    return 1 + (7 - (hasher(key) % 7));
}

/**
 * Probe the table using double hashing until either the key is
 * located (searching == true) or a usable slot is found (searching
 * == false).
 */
int probe(int key, bool searching) {
    int base = static_cast<int>(primaryHash(key));
    int step = 0;
    Slot current;
    do {
        int idx = static_cast<int>(base + (step * stepHash(key))) % capacity;
        current = slots[idx];
        if (searching) {
            if (current.key == EMPTY_MARK) {
                return EMPTY_MARK;
            }
            if (slotMatches(current, key)) {
                std::cout << "Found key!" << std::endl;
                return idx;
            }
            std::cout << "Found tombstone or equal hash, checking next"
                      << std::endl;
            step++;
        } else {
            if (slotFreeForInsert(current, key)) {
                if (!inResizePass) {
                    std::cout << "Spot found!" << std::endl;
                }
                return idx;
            }
            if (!inResizePass) {
                std::cout << "Spot taken, looking at next (next index:"
                          << " "
                          << static_cast<int>(base + (step * stepHash(key))) %
                                 capacity
                          << ")" << std::endl;
            }
            step++;
        }
        if (step == capacity * 100) {
            std::cout << "DoubleHash probe failed" << std::endl;
            return EMPTY_MARK;
        }
    } while (current.key != EMPTY_MARK);
    return EMPTY_MARK;
}

/** True when the slot can accept a new key (empty or a tombstone). */
bool slotFreeForInsert(const Slot& slot, int key) {
    if (slot.key == EMPTY_MARK || slot.key == GRAVE) {
        return true;
    }
    return false;
}

/** True when the slot's key equals the one being searched for. */
bool slotMatches(const Slot& slot, int key) {
    if (slot.key == key) {
        return true;
    }
    return false;
}

/** Print the whole table, slot by slot. */
void printTable() {
    for (int i = 0; i < capacity; i++) {
        if (slots[i].key == EMPTY_MARK) {
            std::cout << " Empty ";
        } else if (slots[i].key == GRAVE) {
            std::cout << " Tomb ";
        } else {
            std::cout << " " << slots[i].key << " ";
        }
    }
    std::cout << std::endl;
}

/** Double the table capacity and reinsert every live key. */
void growTable() {
    inResizePass = true;
    int prevCapacity = capacity;
    std::vector<Slot> prevSlots(slots);
    slots = std::vector<Slot>(capacity * 2);
    capacity *= 2;
    for (int i = 0; i < prevCapacity; i++) {
        if (prevSlots[i].key != -1 && prevSlots[i].key != EMPTY_MARK) {
            occupied--;  // insertKey() re-increments this
            insertKey(prevSlots[i].key);
        }
    }
    inResizePass = false;
    std::cout << "Table was rehashed, new size is: " << capacity << std::endl;
}

/** Insert `key`, growing the table once load factor crosses 0.5. */
void insertKey(int key) {
    int idx = probe(key, false);
    slots[idx].key = key;
    if (++occupied / static_cast<double>(capacity) >= 0.5) {
        growTable();
    }
}

/** Remove `key`, replacing its slot with a tombstone. */
void deleteKey(int key) {
    int idx = probe(key, true);
    if (idx == EMPTY_MARK) {
        std::cout << "key not found" << std::endl;
    }
    slots[idx].key = GRAVE;
    std::cout << "Removal successful, leaving tombstone" << std::endl;
    occupied--;
}

/** Verbose insert that also prints before/after table snapshots. */
void insertVerbose(int key) {
    std::cout << "Initial table: ";
    printTable();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << primaryHash(key) << " % "
              << capacity << " == " << primaryHash(key) % capacity;
    std::cout << std::endl;
    insertKey(key);
    std::cout << "New table: ";
    printTable();
}

/** Verbose delete that also prints before/after table snapshots. */
void deleteVerbose(int key) {
    std::cout << "Initial table: ";
    printTable();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << primaryHash(key) << " % "
              << capacity << " == " << primaryHash(key) % capacity;
    std::cout << std::endl;
    deleteKey(key);
    std::cout << "New table: ";
    printTable();
}
}  // namespace dh_table

using dh_table::Slot;
using dh_table::slots;
using dh_table::capacity;

/**
 * Interactive demo for the double-hashing table.
 */
int main() {
    int cmd = 0, key = 0;
    std::cout << "Enter the initial size of Hash Table. = ";
    std::cin >> capacity;
    slots = std::vector<Slot>(capacity);
    bool running = true;
    while (running) {
        std::cout << std::endl;
        std::cout << "PLEASE CHOOSE -" << std::endl;
        std::cout << "1. Add key. (Numeric only)" << std::endl;
        std::cout << "2. Remove key." << std::endl;
        std::cout << "3. Find key." << std::endl;
        std::cout << "4. Generate Hash. (Numeric only)" << std::endl;
        std::cout << "5. Display Hash table." << std::endl;
        std::cout << "6. Exit." << std::endl;
        std::cin >> cmd;
        switch (cmd) {
            case 1:
                std::cout << "Enter key to add = ";
                std::cin >> key;
                dh_table::insertVerbose(key);
                break;
            case 2:
                std::cout << "Enter key to remove = ";
                std::cin >> key;
                dh_table::deleteVerbose(key);
                break;
            case 3: {
                std::cout << "Enter key to search = ";
                std::cin >> key;
                Slot found = slots[dh_table::probe(key, true)];
                if (found.key == dh_table::EMPTY_MARK) {
                    std::cout << "Key not present";
                }
                break;
            }
            case 4:
                std::cout << "Enter element to generate hash = ";
                std::cin >> key;
                std::cout << "Hash of " << key
                          << " is = " << dh_table::primaryHash(key);
                break;
            case 5:
                dh_table::printTable();
                break;
            default:
                running = false;
                break;
        }
        std::cout << std::endl;
    }
    return 0;
}

/**
 * @file
 * @author [achance6](https://github.com/achance6)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Storage mechanism using [linear probing
 * hash](https://en.wikipedia.org/wiki/Linear_probing) keys.
 * @note The implementation can be optimized by using OOP style.
 */
#include <iostream>
#include <vector>

/**
 * @addtogroup open_addressing Open Addressing
 * @{
 * @namespace linear_probing
 * @brief An implementation of hash table using [linear
 * probing](https://en.wikipedia.org/wiki/Linear_probing) algorithm.
 */
namespace linear_probing {
// fwd declarations
using Entry = struct Entry;
bool putProber(const Entry& entry, int key);
bool searchingProber(const Entry& entry, int key);
void add(int key);

// Undocumented globals
int notPresent;
std::vector<Entry> table;
int totalSize;
int tomb = -1;
int size;
bool rehashing;

/** Node object that holds key */
struct Entry {
    explicit Entry(int key = notPresent) : key(key) {}  ///< constructor
    int key;                                            ///< key value
};

/**
 * @brief Hash a key. Uses the STL library's `std::hash()` function.
 *
 * @param key value to hash
 * @return hash value of the key
 */
size_t hashFxn(int key) {
    std::hash<int> hash;
    return hash(key);
}

/** Performs linear probing to resolve collisions
 * @param key key value to hash
 * @return hash value of the key
 */
int linearProbe(int key, bool searching) {
    int hash = static_cast<int>(hashFxn(key));
    int i = 0;
    Entry entry;
    do {
        int index = static_cast<int>((hash + i) % totalSize);
        entry = table[index];
        if (searching) {
            if (entry.key == notPresent) {
                return notPresent;
            }
            if (searchingProber(entry, key)) {
                std::cout << "Found key!" << std::endl;
                return index;
            }
            std::cout << "Found tombstone or equal hash, checking next"
                      << std::endl;
            i++;
        } else {
            if (putProber(entry, key)) {
                if (!rehashing) {
                    std::cout << "Spot found!" << std::endl;
                }
                return index;
            }
            if (!rehashing) {
                std::cout << "Spot taken, looking at next" << std::endl;
            }
            i++;
        }
        if (i == totalSize) {
            std::cout << "Linear probe failed" << std::endl;
            return notPresent;
        }
    } while (entry.key != notPresent);
    return notPresent;
}

/** Finds empty spot
 * @param entry instance to check in
 * @param key key value to hash
 * @return hash value of the key
 */
bool putProber(const Entry& entry, int key) {
    if (entry.key == notPresent || entry.key == tomb) {
        return true;
    }
    return false;
}

/** Looks for a matching key
 * @param entry instance to check in
 * @param key key value to hash
 * @return hash value of the key
 */
bool searchingProber(const Entry& entry, int key) {
    if (entry.key == key) {
        return true;
    }
    return false;
}

/** Function to displays the table
 * @returns none
 */
void display() {
    for (int i = 0; i < totalSize; i++) {
        if (table[i].key == notPresent) {
            std::cout << " Empty ";
        } else if (table[i].key == tomb) {
            std::cout << " Tomb ";
        } else {
            std::cout << " ";
            std::cout << table[i].key;
            std::cout << " ";
        }
    }
    std::cout << std::endl;
}

/** Rehashes the table into a bigger table
 * @returns None
 */
void rehash() {
    // Necessary so wall of add info isn't printed all at once
    rehashing = true;
    int oldSize = totalSize;
    std::vector<Entry> oldTable(table);
    // Really this should use the next prime number greater than totalSize *
    // 2
    totalSize *= 2;
    table = std::vector<Entry>(totalSize);
    for (int i = 0; i < oldSize; i++) {
        if (oldTable[i].key != -1 && oldTable[i].key != notPresent) {
            size--;  // Size stays the same (add increments size)
            add(oldTable[i].key);
        }
    }
    // delete[] oldTable;
    rehashing = false;
    std::cout << "Table was rehashed, new size is: " << totalSize << std::endl;
}

/** Adds entry using linear probing. Checks for load factor here
 * @param key key value to hash and add
 */
void add(int key) {
    int index = linearProbe(key, false);
    table[index].key = key;
    // Load factor greater than 0.5 causes resizing
    if (++size / static_cast<double>(totalSize) >= 0.5) {
        rehash();
    }
}

/** Removes key. Leaves tombstone upon removal.
 * @param key key value to hash and remove
 */
void remove(int key) {
    int index = linearProbe(key, true);
    if (index == notPresent) {
        std::cout << "key not found" << std::endl;
    }
    std::cout << "Removal Successful, leaving tomb" << std::endl;
    table[index].key = tomb;
    size--;
}

/** Information about the adding process
 * @param key key value to hash and add
 */
void addInfo(int key) {
    std::cout << "Initial table: ";
    display();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << hashFxn(key) << " % "
              << totalSize << " == " << hashFxn(key) % totalSize;
    std::cout << std::endl;
    add(key);
    std::cout << "New table: ";
    display();
}

/** Information about removal process
 * @param key key value to hash and remove
 */
void removalInfo(int key) {
    std::cout << "Initial table: ";
    display();
    std::cout << std::endl;
    std::cout << "hash of " << key << " is " << hashFxn(key) << " % "
              << totalSize << " == " << hashFxn(key) % totalSize;
    std::cout << std::endl;
    remove(key);
    std::cout << "New table: ";
    display();
}
}  // namespace linear_probing
/**
 * @}
 */

using linear_probing::Entry;
