    std::clock_t start_clk = std::clock();
    test1();
    auto end_clk = std::clock();
    std::cout << "Test 1 completed in " << get_clock_diff(start_clk, end_clk)
              << " sec\n";

    start_clk = std::clock();
    test2();
    end_clk = std::clock();
    std::cout << "Test 2 completed in " << get_clock_diff(start_clk, end_clk)
              << " sec\n";

    start_clk = std::clock();
    test3();
    end_clk = std::clock();
    std::cout << "Test 3 completed in " << get_clock_diff(start_clk, end_clk)
              << " sec\n";

    std::cout
        << "(Note: Calculated times include: creating test sets, training "
           "model and writing files to disk.)\n\n";
    return 0;
}

/**
 * \addtogroup machine_learning Machine Learning Algorithms
 * @{
 * \file
 * \brief Alternate implementation of a Kohonen self-organizing map (SOM)
 * that preserves 2D topology.
 *
 * \details
 * A self-organizing map is an unsupervised learning technique that trains a
 * grid of weight vectors ("output nodes") so the grid's spatial layout
 * mirrors the structure of the input data — nearby points in input space end
 * up mapped to nearby nodes in the output grid.
 * \see kohonen_som_trace.cpp
 */
#define _USE_MATH_DEFINES
#include <algorithm>
#include <array>
#include <cerrno>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <fstream>
#include <iostream>
#include <valarray>
#include <vector>
#ifdef _OPENMP
#include <omp.h>
#endif

/**
 * Draws a uniform random double from the interval [lo, hi).
 * \param[in] lo lower bound
 * \param[in] hi upper bound
 * \returns a pseudo-random value in [lo, hi)
 */
double drawUniform(double lo, double hi) {
    return ((hi - lo) * (std::rand() % 100) / 100.f) + lo;
}

/**
 * Writes a matrix of N-dimensional points to a CSV file.
 * \param[in] path output filename (overwritten without confirmation)
 * \param[in] points row-major matrix of points to save
 * \returns 0 on success, -1 if the file could not be opened
 */
int writePointsCsv(const char *path, const std::vector<std::valarray<double>> &points) {
    size_t rowCount = points.size();
    size_t colCount = points[0].size();

    std::ofstream out;
    out.open(path);
    if (!out.is_open()) {
        std::cerr << "Error opening file " << path << ": " << std::strerror(errno) << "\n";
        return -1;
    }

    for (int i = 0; i < rowCount; i++) {
        for (int j = 0; j < colCount; j++) {
            out << points[i][j];
            if (j < colCount - 1) {
                out << ",";
            }
        }
        if (i < rowCount - 1) {
            out << "\n";
        }
    }

    out.close();
    return 0;
}

/**
 * Finds the minimum value in a 2D grid of scalars along with its location.
 * \param[in] grid grid to search
 * \param[out] bestVal smallest value found
 * \param[out] bestRow row of the smallest value
 * \param[out] bestCol column of the smallest value
 */
void locateGridMinimum(const std::vector<std::valarray<double>> &grid, double *bestVal,
                        int *bestRow, int *bestCol) {
    bestVal[0] = INFINITY;
    size_t rows = grid.size();

    for (int i = 0; i < rows; i++) {
        auto it = std::min_element(std::begin(grid[i]), std::end(grid[i]));
        double localMin = *it;
        std::ptrdiff_t col = std::distance(std::begin(grid[i]), it);

        if (localMin < bestVal[0]) {
            bestRow[0] = i;
            bestCol[0] = col;
            bestVal[0] = localMin;
        }
    }
}

/** \namespace machine_learning
 * \brief Machine learning algorithms
 */
namespace machine_learning {

/** Convergence threshold for the average minimum distance. */
constexpr double CONVERGENCE_EPS = 1e-4;

/**
 * Builds a U-matrix (unified distance matrix) from a trained 3D weight
 * tensor and writes it to disk.
 * \param[in] path output filename (overwritten without confirmation)
 * \param[in] weights trained weight grid
 * \returns 0 on success, -1 if the file could not be opened
 */
int writeUMatrix(const char *path,
                  const std::vector<std::vector<std::valarray<double>>> &weights) {
    std::ofstream out(path);
    if (!out) {
        std::cerr << "File error (" << path << "): " << std::strerror(errno) << std::endl;
        return -1;
    }

    unsigned int neighborhood = 1;

    for (int i = 0; i < weights.size(); i++) {
        for (int j = 0; j < weights[0].size(); j++) {
            double avgDist = 0.f;

            int rowStart = std::max<int>(0, i - neighborhood);
            int rowEnd = std::min<int>(weights.size(), i + neighborhood + 1);
            int colStart = std::max<int>(0, j - neighborhood);
            int colEnd = std::min<int>(weights[0].size(), j + neighborhood + 1);
            int r = 0, c = 0;
#ifdef _OPENMP
#pragma omp parallel for reduction(+ : avgDist)
#endif
            for (r = rowStart; r < rowEnd; r++) {
                for (c = colStart; c < colEnd; c++) {
                    auto diff = weights[i][j] - weights[r][c];
                    double sq = std::pow(diff, 2).sum();
                    avgDist += std::sqrt(sq);
                }
            }

            avgDist /= neighborhood * neighborhood;
            out << avgDist;
            if (j < weights[0].size() - 1) {
                out << ',';
            }
        }
        if (i < weights.size() - 1) {
            out << '\n';
        }
    }

    out.close();
    return 0;
}

/**
 * Applies one Kohonen weight-update step for a single input sample.
 * \param[in] sample the current training point
 * \param[in,out] weights the PxQxN weight grid
 * \param[in,out] scratch reusable PxQ scratch buffer for distances
 * \param[in] learnRate current learning rate (0, 1]
 * \param[in] neighborhood current neighborhood radius
 * \returns the distance between the sample and its best-matching node
 */
double applyWeightUpdate(const std::valarray<double> &sample,
                          std::vector<std::vector<std::valarray<double>>> *weights,
                          std::vector<std::valarray<double>> *scratch, double learnRate,
                          int neighborhood) {
    int gx = 0, gy = 0;
    int gridRows = static_cast<int>(weights->size());
    int gridCols = static_cast<int>((*weights)[0].size());
    double bestDist = 0.f;

#ifdef _OPENMP
#pragma omp for
#endif
    for (gx = 0; gx < gridRows; gx++) {
        for (gy = 0; gy < gridCols; gy++) {
            (*scratch)[gx][gy] = 0.f;
            auto diff = ((*weights)[gx][gy] - sample);
            (*scratch)[gx][gy] = (diff * diff).sum();
            (*scratch)[gx][gy] = std::sqrt((*scratch)[gx][gy]);
        }
    }

    int bmuRow = 0, bmuCol = 0;
    locateGridMinimum(*scratch, &bestDist, &bmuRow, &bmuCol);

    int rowStart = std::max(0, bmuRow - neighborhood);
    int rowEnd = std::min(gridRows, bmuRow + neighborhood + 1);
    int colStart = std::max(0, bmuCol - neighborhood);
    int colEnd = std::min(gridCols, bmuCol + neighborhood + 1);

#ifdef _OPENMP
#pragma omp for
#endif
    for (gx = rowStart; gx < rowEnd; gx++) {
        for (gy = colStart; gy < colEnd; gy++) {
            double sqDist = (bmuRow - gx) * (bmuRow - gx) + (bmuCol - gy) * (bmuCol - gy);
            double falloff = std::exp(-sqDist / (2.f * learnRate * learnRate));

            (*weights)[gx][gy] += (sample - (*weights)[gx][gy]) * learnRate * falloff;
        }
    }
    return bestDist;
}

/**
 * Trains the SOM over the full dataset, decaying the learning rate and
 * shrinking the neighborhood as training proceeds.
 * \param[in] dataset the training samples
 * \param[in,out] weights the weight grid to train
 * \param[in] minLearnRate (unused terminal threshold, kept for API parity)
 */
void trainTopologicalMap(const std::vector<std::valarray<double>> &dataset,
                          std::vector<std::vector<std::valarray<double>>> *weights,
                          double minLearnRate) {
    size_t sampleCount = dataset.size();
    size_t gridSize = weights->size();
    size_t neighborhood = gridSize >> 2, iteration = 0;
    double learnRate = 1.f;

    std::vector<std::valarray<double>> scratch(gridSize);
    for (int i = 0; i < gridSize; i++) scratch[i] = std::valarray<double>(gridSize);

    double meanDist = 1.f;
    double prevMeanDist = 1.f;
    double improvementRatio = 1.f;

    for (; learnRate > 0 && improvementRatio > 1e-5; learnRate -= 1e-4, iteration++) {
        for (int sample = 0; sample < sampleCount; sample++) {
            meanDist += applyWeightUpdate(dataset[sample], weights, &scratch, learnRate,
                                           neighborhood);
        }

        if (iteration % 300 == 0 && neighborhood > 1) {
            neighborhood--;
        }

        meanDist /= sampleCount;

        improvementRatio = (prevMeanDist - meanDist) / prevMeanDist;
        if (improvementRatio < 0) {
            improvementRatio = 1.f;
        }
        prevMeanDist = meanDist;

        std::cout << "iter: " << iteration << "\t alpha: " << learnRate
                  << "\t R: " << neighborhood << "\t d_min: " << improvementRatio << "\r";
    }

    std::cout << "\n";
}

}  // namespace machine_learning

