/** Generates points scattered around four cluster centers in 2D space.
 * \param[out] data matrix to fill with generated points
 */
void makeFourClusterData(std::vector<std::valarray<double>> *data) {
    const int N = data->size();
    const double R = 0.3;
    int i = 0;
    const int classCount = 4;
    std::array<std::array<double, 2>, classCount> centers = {
        std::array<double, 2>({.5, .5}), std::array<double, 2>({.5, -.5}),
        std::array<double, 2>({-.5, .5}), std::array<double, 2>({-.5, -.5})};

#ifdef _OPENMP
#pragma omp for
#endif
    for (i = 0; i < N; i++) {
        int cls = std::rand() % classCount;
        data[0][i][0] = drawUniform(centers[cls][0] - R, centers[cls][0] + R);
        data[0][i][1] = drawUniform(centers[cls][1] - R, centers[cls][1] + R);
    }
}

/** Scenario 1: 2D four-cluster dataset. Writes test1.csv, w11.csv, w12.csv. */
void scenarioOne() {
    int j = 0, N = 300;
    int dims = 2;
    int gridSize = 30;
    std::vector<std::valarray<double>> X(N);
    std::vector<std::vector<std::valarray<double>>> W(gridSize);
    for (int i = 0; i < std::max(gridSize, N); i++) {
        if (i < N) {
            X[i] = std::valarray<double>(dims);
        }
        if (i < gridSize) {
            W[i] = std::vector<std::valarray<double>>(gridSize);
            for (int k = 0; k < gridSize; k++) {
                W[i][k] = std::valarray<double>(dims);
#ifdef _OPENMP
#pragma omp for
#endif
                for (j = 0; j < dims; j++) {
                    W[i][k][j] = drawUniform(-10, 10);
                }
            }
        }
    }

    makeFourClusterData(&X);
    writePointsCsv("test1.csv", X);
    writeUMatrix("w11.csv", W);
    trainTopologicalMap(X, &W, 1e-4);
    writeUMatrix("w12.csv", W);
}

