    auto t1 = std::clock();
    std::cout << "Test 1 completed in " << elapsedSeconds(t0, t1) << " sec\n";

    t0 = std::clock();
    scenarioLemniscate();
    t1 = std::clock();
    std::cout << "Test 2 completed in " << elapsedSeconds(t0, t1) << " sec\n";

    t0 = std::clock();
    scenarioEightClusters();
    t1 = std::clock();
