/**
 * @file
 * @brief Formulas for computing the area (or surface area) of common
 * geometric shapes.
 * @details Each helper below implements a closed-form area formula for a
 * particular shape and is templated so it can be evaluated with integer or
 * floating-point inputs.
 *
 * Rewritten variant for dataset generation - identical formulas, different
 * function names/layout and reworded test harness.
 */
#define _USE_MATH_DEFINES
#include <cassert>
#include <cmath>
#include <cstdint>
#include <iostream>

/// Grouping of geometric area helpers.
namespace math {

/// Area of a square: side length squared.
template <typename T>
T areaOfSquare(T side) {
    return side * side;
}

/// Area of a rectangle: length times width.
template <typename T>
T areaOfRectangle(T length, T width) {
    return length * width;
}

/// Area of a triangle: half of base times height.
template <typename T>
T areaOfTriangle(T base, T height) {
    return base * height / 2;
}

/// Area of a circle: pi times radius squared.
template <typename T>
T areaOfCircle(T radius) {
    return M_PI * std::pow(radius, 2);
}

/// Area of a parallelogram: base times height.
template <typename T>
T areaOfParallelogram(T base, T height) {
    return base * height;
}

/// Surface area of a cube: six times side squared.
template <typename T>
T surfaceAreaOfCube(T side) {
    return 6 * side * side;
}

/// Surface area of a sphere: four pi r^2.
template <typename T>
T surfaceAreaOfSphere(T radius) {
    return 4 * M_PI * std::pow(radius, 2);
}

/// Surface area of a cylinder (including both circular caps).
template <typename T>
T surfaceAreaOfCylinder(T radius, T height) {
    return 2 * M_PI * radius * height + 2 * M_PI * std::pow(radius, 2);
}

/// Surface area of a hemisphere: three pi r^2 (dome plus its flat base).
template <typename T>
T surfaceAreaOfHemisphere(T radius) {
    return 3 * M_PI * std::pow(radius, 2);
}

}  // namespace math

/// Run each formula against a known input/output pair and assert equality.
static void runSelfChecks() {
    uint16_t inIntA = 0;
    uint16_t inIntB = 0;
    uint16_t inIntC = 0;
    uint16_t inIntD = 0;
    uint16_t expectInt = 0;
    uint16_t gotInt = 0;

    float inFloat = NAN;
    float expectFloat = NAN;
    float gotFloat = NAN;

    double inDblA = NAN;
    double inDblB = NAN;
    double inDblRadius = NAN;
    double inDblHeight = NAN;
    double expectDbl = NAN;
    double gotDbl = NAN;

    // square, integer
    inIntA = 5;
    expectInt = 25;
    gotInt = math::areaOfSquare(inIntA);
    std::cout << "SQUARE AREA (int)\n";
    std::cout << "Side: " << inIntA << std::endl;
    std::cout << "Expected: " << expectInt << std::endl;
    std::cout << "Got: " << gotInt << std::endl;
    assert(gotInt == expectInt);
    std::cout << "OK\n\n";

    // square, float
    inFloat = 2.5;
    expectFloat = 6.25;
    gotFloat = math::areaOfSquare(inFloat);
    std::cout << "SQUARE AREA (float)\n";
    std::cout << "Side: " << inFloat << std::endl;
    std::cout << "Expected: " << expectFloat << std::endl;
    std::cout << "Got: " << gotFloat << std::endl;
    assert(gotFloat == expectFloat);
