    std::cout << "PARALLELOGRAM AREA\n";
    std::cout << "Base: " << inIntC << std::endl;
    std::cout << "Height: " << inIntD << std::endl;
    std::cout << "Expected: " << expectInt << std::endl;
    std::cout << "Got: " << gotInt << std::endl;
    assert(gotInt == expectInt);
    std::cout << "OK\n\n";

    // cube surface
    inDblA = 5.5;
    expectDbl = 181.5;
    gotDbl = math::surfaceAreaOfCube(inDblA);
    std::cout << "CUBE SURFACE AREA\n";
    std::cout << "Side: " << inDblA << std::endl;
