    std::cout << "Got: " << gotDbl << std::endl;
    assert(gotDbl == expectDbl);
    std::cout << "OK\n\n";

    // sphere surface
    inDblRadius = 10.0;
    expectDbl = 1256.6370614359172;
    gotDbl = math::surfaceAreaOfSphere(inDblRadius);
    std::cout << "SPHERE SURFACE AREA\n";
    std::cout << "Radius: " << inDblRadius << std::endl;
    std::cout << "Expected: " << expectDbl << std::endl;
    std::cout << "Got: " << gotDbl << std::endl;
    assert(gotDbl == expectDbl);
    std::cout << "OK\n\n";

    // cylinder surface
    inDblRadius = 4.0;
    inDblHeight = 7.0;
    expectDbl = 276.46015351590177;
    gotDbl = math::surfaceAreaOfCylinder(inDblRadius, inDblHeight);
    std::cout << "CYLINDER SURFACE AREA\n";
    std::cout << "Radius: " << inDblRadius << std::endl;
    std::cout << "Height: " << inDblHeight << std::endl;
    std::cout << "Expected: " << expectDbl << std::endl;
    std::cout << "Got: " << gotDbl << std::endl;
    assert(gotDbl == expectDbl);
    std::cout << "OK\n\n";

    // hemisphere surface
    inDblRadius = 10.0;
    expectDbl = 942.4777960769379;
    gotDbl = math::surfaceAreaOfHemisphere(inDblRadius);
    std::cout << "HEMISPHERE SURFACE AREA\n";
    std::cout << "Radius: " << inDblRadius << std::endl;
    std::cout << "Expected: " << expectDbl << std::endl;
    std::cout << "Got: " << gotDbl << std::endl;
    assert(gotDbl == expectDbl);
    std::cout << "OK\n\n";
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief Program to check if a number is an [Armstrong/Narcissistic
 * number](https://en.wikipedia.org/wiki/Narcissistic_number) in decimal system.
 *
 * @details
 * Armstrong number or [Narcissistic
 * number](https://en.wikipedia.org/wiki/Narcissistic_number) is a number that
 * is the sum of its own digits raised to the power of the number of digits.
 *
 * let n be the narcissistic number,
 * \f[F_b(n) = \sum_{i=0}^{k-1}d_{i}^{k}\f] for
 * \f$ b > 1 F_b : \N \to \N \f$ where
 * \f$ k = \lfloor log_b n\rfloor is the number of digits in the number in base
 * \f$b\f$, and \f$ d_i = \frac{n mod b^{i+1} - n mod b^{i}}{b^{i}} \f$
 *
 * @author [Neeraj Cherkara](https://github.com/iamnambiar)
 */
#include <cassert>   /// for assert
#include <cmath>     /// for std::pow
#include <iostream>  /// for IO operations

/**
 * @brief Function to calculate the total number of digits in the number.
 * @param num Number
 * @return Total number of digits.
 */
int number_of_digits(int num) {
    int total_digits = 0;
    while (num > 0) {
        num = num / 10;
        ++total_digits;
    }
    return total_digits;
}

/**
 * @brief Function to check whether the number is armstrong number or not.
 * @param number to be checked
 * @return `true` if the number is armstrong.
 * @return `false` if the number is not armstrong.
 */
bool is_armstrong(int number) {
    // If the number is less than 0, then it is not an armstrong number.
    if (number < 0) {
        return false;
    }

    int sum = 0;
    int temp = number;
    // Finding the total number of digits in the number
    int total_digits = number_of_digits(number);
    while (temp > 0) {
        int rem = temp % 10;
        // Finding each digit raised to the power total digit and add it to the
        // total sum
        sum += static_cast<int>(std::pow(rem, total_digits));
        temp = temp / 10;
    }
    return number == sum;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // is_armstrong(370) returns true.
    assert(is_armstrong(370) == true);
    // is_armstrong(225) returns false.
    assert(is_armstrong(225) == false);
    // is_armstrong(-23) returns false.
    assert(is_armstrong(-23) == false);
    // is_armstrong(153) returns true.
    assert(is_armstrong(153) == true);
    // is_armstrong(0) returns true.
    assert(is_armstrong(0) == true);
    // is_armstrong(12) returns false.
    assert(is_armstrong(12) == false);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main Function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Determines whether a given number is an Armstrong (narcissistic)
 * number: the sum of each digit raised to the power of the digit count
 * equals the number itself.
 *
 * @details
 * For a k-digit number n, an Armstrong number satisfies
 * n = sum(d_i ^ k) over all digits d_i of n. Example: 153 = 1^3 + 5^3 + 3^3.
 *
 * Rewritten variant for dataset generation - same logic, different helper
 * names and control flow layout.
 */
#include <cassert>
#include <cmath>
#include <iostream>

/**
 * @brief Count how many decimal digits a non-negative number has.
 * @param value the number to inspect
 * @return digit count
 */
int countDigits(int value) {
    int digits = 0;
    while (value > 0) {
        value /= 10;
        digits++;
    }
    return digits;
}

/**
 * @brief Determine whether the given integer is an Armstrong number.
 * @param candidate value to check
 * @return true when candidate equals the sum of its digits raised to the
 * power of its digit count
 */
bool checkArmstrong(int candidate) {
    if (candidate < 0) {
        return false;  // negative values are never Armstrong numbers
    }

    const int digitCount = countDigits(candidate);
    int runningTotal = 0;
    int remainder = candidate;

    while (remainder > 0) {
        int digit = remainder % 10;
        runningTotal += static_cast<int>(std::pow(digit, digitCount));
        remainder /= 10;
    }

    return runningTotal == candidate;
}

/// Exercise checkArmstrong against known Armstrong and non-Armstrong values.
static void runSelfChecks() {
    assert(checkArmstrong(370) == true);
    assert(checkArmstrong(225) == false);
    assert(checkArmstrong(-23) == false);
    assert(checkArmstrong(153) == true);
    assert(checkArmstrong(0) == true);
    assert(checkArmstrong(12) == false);

    std::cout << "Every check completed without issue!\n";
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief C++ Program to find Binary Exponent Iteratively and Recursively.
 *
 * Calculate \f$a^b\f$ in \f$O(\log(b))\f$ by converting \f$b\f$ to a
 * binary number. Binary exponentiation is also known as exponentiation by
 * squaring.
 * @note This is a far better approach compared to naive method which
 * provide \f$O(b)\f$ operations.
 *
 * Example:
 * </br>10 in base 2 is 1010.
 * \f{eqnarray*}{
 * 2^{10_d} &=& 2^{1010_b} = 2^8 * 2^2\\
 * 2^1 &=& 2\\
 * 2^2 &=& (2^1)^2 = 2^2 = 4\\
 * 2^4 &=& (2^2)^2 = 4^2 = 16\\
 * 2^8 &=& (2^4)^2 = 16^2 = 256\\
 * \f}
 * Hence to calculate 2^10 we only need to multiply \f$2^8\f$ and \f$2^2\f$
 * skipping \f$2^1\f$ and \f$2^4\f$.
 */

#include <iostream>

/// Recursive function to calculate exponent in \f$O(\log(n))\f$ using binary
/// exponent.
int binExpo(int a, int b) {
    if (b == 0) {
        return 1;
    }
    int res = binExpo(a, b / 2);
    if (b % 2) {
        return res * res * a;
    } else {
        return res * res;
    }
}

/// Iterative function to calculate exponent in \f$O(\log(n))\f$ using binary
/// exponent.
int binExpo_alt(int a, int b) {
    int res = 1;
    while (b > 0) {
        if (b % 2) {
            res = res * a;
        }
        a = a * a;
        b /= 2;
    }
    return res;
}

/// Main function
int main() {
    int a, b;
    /// Give two numbers a, b
    std::cin >> a >> b;
    if (a == 0 && b == 0) {
        std::cout << "Math error" << std::endl;
    } else if (b < 0) {
        std::cout << "Exponent must be positive !!" << std::endl;
    } else {
        int resRecurse = binExpo(a, b);
        /// int resIterate = binExpo_alt(a, b);

        /// Result of a^b (where '^' denotes exponentiation)
        std::cout << resRecurse << std::endl;
        /// std::cout << resIterate << std::endl;
    }
}

/**
 * @file
 * @brief Computes a^b using exponentiation by squaring (binary
 * exponentiation), both recursively and iteratively.
 *
 * @details
 * By expressing the exponent b in binary, a^b can be produced with only
 * O(log b) multiplications instead of the O(b) multiplications a naive loop
 * would need. E.g. 2^10 = 2^(1010 in binary) = 2^8 * 2^2, so only the
 * squarings that correspond to set bits are actually needed.
 *
 * Rewritten variant for dataset generation - same algorithm, renamed
 * functions and reworded commentary.
 */

#include <iostream>

/// Recursive exponentiation-by-squaring: computes base^power in O(log power).
long long powerRecursive(long long base, long long power) {
    if (power == 0) {
        return 1;
    }
    long long half = powerRecursive(base, power / 2);
    if (power % 2) {
        return half * half * base;
    }
    return half * half;
}

/// Iterative exponentiation-by-squaring: same result, no call stack growth.
long long powerIterative(long long base, long long power) {
    long long product = 1;
    while (power > 0) {
        if (power % 2) {
            product *= base;
        }
        base *= base;
        power /= 2;
    }
    return product;
}

int main() {
    long long base = 0, exponent = 0;
    std::cin >> base >> exponent;

    if (base == 0 && exponent == 0) {
        std::cout << "Math error" << std::endl;
    } else if (exponent < 0) {
        std::cout << "Exponent must be positive !!" << std::endl;
    } else {
        long long viaRecursion = powerRecursive(base, exponent);
        // long long viaLoop = powerIterative(base, exponent);

        std::cout << viaRecursion << std::endl;
        // std::cout << viaLoop << std::endl;
    }

    return 0;
}

/**
 * @file
 * @brief Program to calculate [Binomial
 * coefficients](https://en.wikipedia.org/wiki/Binomial_coefficient)
 *
 * @author [astronmax](https://github.com/astronmax)
 */

#include <cassert>   /// for assert
#include <cstdint>   /// for int32_t type
#include <cstdlib>   /// for atoi
#include <iostream>  /// for IO operations

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @namespace binomial
 * @brief Functions for [Binomial
 * coefficients](https://en.wikipedia.org/wiki/Binomial_coefficient)
 * implementation
 */
namespace binomial {
/**
 * @brief Function to calculate binomial coefficients
 * @param n first value
 * @param k second value
 * @return binomial coefficient for n and k
 */
size_t calculate(int32_t n, int32_t k) {
    // basic cases
    if (k > (n / 2))
        k = n - k;
    if (k == 1)
        return n;
    if (k == 0)
        return 1;

    size_t result = 1;
    for (int32_t i = 1; i <= k; ++i) {
        result *= n - k + i;
        result /= i;
    }

    return result;
}
}  // namespace binomial
}  // namespace math

/**
 * @brief Test implementations
 * @returns void
 */
static void tests() {
    // tests for calculate function
    assert(math::binomial::calculate(1, 1) == 1);
    assert(math::binomial::calculate(57, 57) == 1);
    assert(math::binomial::calculate(6, 3) == 20);
    assert(math::binomial::calculate(10, 5) == 252);
    assert(math::binomial::calculate(20, 10) == 184756);
    assert(math::binomial::calculate(30, 15) == 155117520);
    assert(math::binomial::calculate(40, 20) == 137846528820);
    assert(math::binomial::calculate(50, 25) == 126410606437752);
    assert(math::binomial::calculate(60, 30) == 118264581564861424);
    assert(math::binomial::calculate(62, 31) == 465428353255261088);

    std::cout << "[+] Binomial coefficients calculate test completed"
              << std::endl;
}

/**
 * @brief Main function
 * @param argc commandline argument count
 * @param argv commandline array of arguments
 * @returns 0 on exit
 */
int main(int argc, const char* argv[]) {
    tests();  // run self-test implementations

    if (argc < 3) {
        std::cout << "Usage ./binomial_calculate {n} {k}" << std::endl;
        return 0;
    }

    int32_t n = atoi(argv[1]);
    int32_t k = atoi(argv[2]);

    std::cout << math::binomial::calculate(n, k) << std::endl;
    return 0;
}

/**
 * @file
 * @brief Computes binomial coefficients "n choose k" using an accumulation
 * loop that avoids computing full factorials.
 *
 * Rewritten variant for dataset generation - same math, restructured
 * namespaces/functions and reworded test harness.
 */

#include <cassert>
#include <cstdint>
#include <cstdlib>
#include <iostream>

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @namespace combinatorics
 * @brief Combinatorics helpers, including binomial coefficients
 */
namespace combinatorics {

/**
 * @brief Compute C(n, k), the number of ways to choose k items from n.
 * @param n total item count
 * @param k subset size
 * @return the binomial coefficient
 */
size_t nChooseK(int32_t n, int32_t k) {
    // exploit symmetry: C(n, k) == C(n, n-k)
    if (k > (n / 2)) {
        k = n - k;
    }
    if (k == 1) {
        return n;
    }
    if (k == 0) {
        return 1;
    }

    size_t accumulated = 1;
    for (int32_t step = 1; step <= k; ++step) {
        accumulated *= n - k + step;
        accumulated /= step;
    }

    return accumulated;
}

}  // namespace combinatorics
}  // namespace math

/// Verify nChooseK against several known coefficient values.
static void runSelfChecks() {
    assert(math::combinatorics::nChooseK(1, 1) == 1);
    assert(math::combinatorics::nChooseK(57, 57) == 1);
    assert(math::combinatorics::nChooseK(6, 3) == 20);
    assert(math::combinatorics::nChooseK(10, 5) == 252);
    assert(math::combinatorics::nChooseK(20, 10) == 184756);
    assert(math::combinatorics::nChooseK(30, 15) == 155117520);
    assert(math::combinatorics::nChooseK(40, 20) == 137846528820);
    assert(math::combinatorics::nChooseK(50, 25) == 126410606437752);
    assert(math::combinatorics::nChooseK(60, 30) == 118264581564861424);
    assert(math::combinatorics::nChooseK(62, 31) == 465428353255261088);

    std::cout << "[+] Binomial coefficient checks completed" << std::endl;
}

int main(int argc, const char* argv[]) {
    runSelfChecks();

    if (argc < 3) {
        std::cout << "Usage ./binomial_calculate {n} {k}" << std::endl;
        return 0;
    }

    int32_t n = atoi(argv[1]);
    int32_t k = atoi(argv[2]);

    std::cout << math::combinatorics::nChooseK(n, k) << std::endl;
    return 0;
}

/**
 * @file
 * @brief A C++ Program to check whether a pair of numbers is an [amicable
 * pair](https://en.wikipedia.org/wiki/Amicable_numbers) or not.
 *
 * @details
 * An Amicable Pair is two positive integers such that the sum of the proper
 * divisor for each number is equal to the other number.
 *
 * @note Remember that a proper divisor is any positive whole number that
 * divides into a selected number, apart from the selected number itself, and
 * returns a positive integer. for example 1, 2 and  5 are all proper divisors
 * of 10.
 *
 * @author [iamnambiar](https://github.com/iamnambiar)
 */
#include <cassert>   /// for assert
#include <iostream>  /// for IO operations

/**
 * @brief Mathematical algorithms
 * @namespace
 */
namespace math {
/**
 * @brief Function to calculate the sum of all the proper divisor
 * of an integer.
 * @param num selected number.
 * @return Sum of the proper divisor of the number.
 */
int sum_of_divisor(int num) {
    // Variable to store the sum of all proper divisors.
    int sum = 1;
    // Below loop condition helps to reduce Time complexity by a factor of
    // square root of the number.
    for (int div = 2; div * div <= num; ++div) {
        // Check 'div' is divisor of 'num'.
        if (num % div == 0) {
            // If both divisor are same, add once to 'sum'
            if (div == (num / div)) {
                sum += div;
            } else {
                // If both divisor are not the same, add both to 'sum'.
                sum += (div + (num / div));
            }
        }
    }
    return sum;
}

/**
 * @brief Function to check whether the pair is amicable or not.
 * @param x First number.
 * @param y Second number.
 * @return `true` if the pair is amicable
 * @return `false` if the pair is not amicable
 */
bool are_amicable(int x, int y) {
    return (sum_of_divisor(x) == y) && (sum_of_divisor(y) == x);
}
}  // namespace math

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    assert(math::are_amicable(220, 284) == true);
    assert(math::are_amicable(6368, 6232) == true);
    assert(math::are_amicable(458, 232) == false);
    assert(math::are_amicable(17296, 18416) == true);
    assert(math::are_amicable(18416, 17296) == true);

    std::cout << "All tests have successfully passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // perform self-tests implementations
    return 0;
}

/**
 * @file
 * @brief Determines whether two positive integers form an amicable pair,
 * meaning the proper-divisor sum of each equals the other number.
 *
 * @details
 * A proper divisor of n is any positive divisor of n excluding n itself.
 * Two numbers x and y are amicable when sum-of-proper-divisors(x) == y and
 * sum-of-proper-divisors(y) == x.
 *
 * Rewritten variant for dataset generation - same logic, renamed helpers
 * and reworded comments.
 */
#include <cassert>
#include <iostream>

/// Grouping of number-theory helpers.
namespace math {

/**
 * @brief Sum all proper divisors of an integer using a sqrt(n) scan.
 * @param value the number to analyze
 * @return sum of proper divisors
 */
int properDivisorSum(int value) {
    int total = 1;  // 1 always divides value (for value > 1)
    for (int factor = 2; factor * factor <= value; ++factor) {
        if (value % factor == 0) {
            int partner = value / factor;
            if (factor == partner) {
                total += factor;  // perfect square factor, count once
            } else {
                total += factor + partner;
            }
        }
    }
    return total;
}

/**
 * @brief Check whether two integers form an amicable pair.
 * @param first first candidate
 * @param second second candidate
 * @return true when the pair is amicable
 */
bool isAmicablePair(int first, int second) {
    return properDivisorSum(first) == second &&
           properDivisorSum(second) == first;
}

}  // namespace math

/// Confirm isAmicablePair against known amicable and non-amicable pairs.
static void runSelfChecks() {
    assert(math::isAmicablePair(220, 284) == true);
    assert(math::isAmicablePair(6368, 6232) == true);
    assert(math::isAmicablePair(458, 232) == false);
    assert(math::isAmicablePair(17296, 18416) == true);
    assert(math::isAmicablePair(18416, 17296) == true);

    std::cout << "Every check completed without issue!" << std::endl;
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief A simple program to check if the given number is a
 * [factorial](https://en.wikipedia.org/wiki/Factorial) of some number or not.
 *
 * @details A factorial number is the sum of k! where any value of k is a
 * positive integer. https://www.mathsisfun.com/numbers/factorial.html
 *
 * @author [Divyajyoti Ukirde](https://github.com/divyajyotiuk)
 * @author [ewd00010](https://github.com/ewd00010)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for cout

/**
 * @namespace
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @brief Function to check if the given number is factorial of some number or
 * not.
 * @param n number to be checked.
 * @return true if number is a factorial returns true
 * @return false if number is not a factorial
 */
bool is_factorial(uint64_t n) {
    if (n <= 0) {  // factorial numbers are only ever positive Integers
        return false;
    }

    /*!
     * this loop is basically a reverse factorial calculation, where instead
     * of multiplying we are dividing. We start at i = 2 since i = 1 has
     * no impact division wise
     */
    int i = 2;
    while (n % i == 0) {
        n = n / i;
        i++;
    }

    /*!
     * if n was the sum of a factorial then it should be divided until it
     * becomes 1
     */
    return (n == 1);
}
}  // namespace math

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    assert(math::is_factorial(50) == false);
    assert(math::is_factorial(720) == true);
    assert(math::is_factorial(0) == false);
    assert(math::is_factorial(1) == true);
    assert(math::is_factorial(479001600) == true);
    assert(math::is_factorial(-24) == false);

    std::cout << "All tests have successfully passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Determines whether a given number equals k! (k factorial) for some
 * positive integer k.
 *
 * @details A factorial number is the product 1*2*3*...*k for some positive
 * integer k. This checker reverses that product by repeatedly dividing out
 * consecutive integers starting at 2.
 *
 * Rewritten variant for dataset generation - same algorithm, renamed
 * function/variables and reworded commentary.
 */
#include <cassert>
#include <cstdint>
#include <iostream>

/// Grouping of number-theory helpers.
namespace math {

/**
 * @brief Check whether n is exactly k! for some positive integer k.
 * @param n the value to test
 * @return true when n is a factorial number, false otherwise
 */
bool isFactorialNumber(uint64_t n) {
    if (n <= 0) {  // factorials are always positive
        return false;
    }

    // Undo the factorial multiplication one divisor at a time, starting
    // from 2 since dividing by 1 changes nothing.
    uint64_t divisor = 2;
    while (n % divisor == 0) {
        n = n / divisor;
        divisor++;
    }

    // If n truly was a factorial, this process should whittle it down to 1.
    return n == 1;
}

}  // namespace math

/// Exercise isFactorialNumber against known factorial and non-factorial values.
static void runSelfChecks() {
    assert(math::isFactorialNumber(50) == false);
    assert(math::isFactorialNumber(720) == true);
    assert(math::isFactorialNumber(0) == false);
    assert(math::isFactorialNumber(1) == true);
    assert(math::isFactorialNumber(479001600) == true);
    assert(math::isFactorialNumber(-24) == false);

    std::cout << "Every check completed without issue!" << std::endl;
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief
 * A simple program to check if the given number is
 * [Prime](https://en.wikipedia.org/wiki/Primality_test) or not.
 * @details
 * A prime number is any number that can be divided only by itself and 1. It
 * must be positive and a whole number, therefore any prime number is part of
 * the set of natural numbers. The majority of prime numbers are even numbers,
 * with the exception of 2. This algorithm finds prime numbers using this
 * information. additional ways to solve the prime check problem:
 * https://cp-algorithms.com/algebra/primality_tests.html#practice-problems
 * @author [Omkar Langhe](https://github.com/omkarlanghe)
 * @author [ewd00010](https://github.com/ewd00010)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations

/**
 * @brief Mathematical algorithms
 * @namespace
 */
namespace math {
/**
 * @brief Function to check if the given number is prime or not.
 * @param num number to be checked.
 * @return true if number is a prime
 * @return false if number is not a prime.
 */
bool is_prime(int64_t num) {
    /*!
     * Reduce all possibilities of a number which cannot be prime with the first
     * 3 if, else if conditionals. Example: Since no even number, except 2 can
     * be a prime number and the next prime we find after our checks is 5,
     * we will start the for loop with i = 5. then for each loop we increment
     * i by +6 and check if i or i+2 is a factor of the number; if it's a factor
     * then we will return false. otherwise, true will be returned after the
     * loop terminates at the terminating condition which is i*i <= num
     */
    if (num <= 1) {
        return false;
    } else if (num == 2 || num == 3) {
        return true;
    } else if (num % 2 == 0 || num % 3 == 0) {
        return false;
    } else {
        for (int64_t i = 5; i * i <= num; i = i + 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
    }
    return true;
}
}  // namespace math

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    assert(math::is_prime(1) == false);
    assert(math::is_prime(2) == true);
    assert(math::is_prime(3) == true);
    assert(math::is_prime(4) == false);
    assert(math::is_prime(-4) == false);
    assert(math::is_prime(7) == true);
    assert(math::is_prime(-7) == false);
    assert(math::is_prime(19) == true);
    assert(math::is_prime(50) == false);
    assert(math::is_prime(115249) == true);

    std::cout << "All tests have successfully passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // perform self-tests implementations
    return 0;
}

/**
 * @file
 * @brief Determines whether a given integer is prime.
 * @details
 * A prime number has exactly two positive divisors: 1 and itself. Aside
 * from 2, every prime is odd, and aside from 2 and 3, every prime is of the
 * form 6k +/- 1. This checker exploits that pattern to skip most composite
 * candidates quickly.
 *
 * Rewritten variant for dataset generation - same algorithm, renamed
 * function and reworded commentary.
 */

#include <cassert>
#include <iostream>

/// Grouping of number-theory helpers.
namespace math {

/**
 * @brief Test primality of an integer using the 6k +/- 1 wheel.
 * @param num candidate value
 * @return true if num is prime, false otherwise
 */
bool isPrimeNumber(int64_t num) {
    // Quickly rule out the easy cases before falling back to the wheel
    // scan: values <= 1 are never prime; 2 and 3 are prime; any other
    // multiple of 2 or 3 cannot be prime.
    if (num <= 1) {
        return false;
    }
    if (num == 2 || num == 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }

    for (int64_t candidate = 5; candidate * candidate <= num; candidate += 6) {
        if (num % candidate == 0 || num % (candidate + 2) == 0) {
            return false;
        }
    }
    return true;
}

}  // namespace math

/// Exercise isPrimeNumber against a mix of prime and non-prime inputs.
static void runSelfChecks() {
    assert(math::isPrimeNumber(1) == false);
    assert(math::isPrimeNumber(2) == true);
    assert(math::isPrimeNumber(3) == true);
    assert(math::isPrimeNumber(4) == false);
    assert(math::isPrimeNumber(-4) == false);
    assert(math::isPrimeNumber(7) == true);
    assert(math::isPrimeNumber(-7) == false);
    assert(math::isPrimeNumber(19) == true);
    assert(math::isPrimeNumber(50) == false);
    assert(math::isPrimeNumber(115249) == true);

    std::cout << "Every check completed without issue!" << std::endl;
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @author tjgurwara99
 * @file
 *
 * \brief An implementation of Complex Number as Objects
 * \details A basic implementation of Complex Number field as a class with
 * operators overloaded to accommodate (mathematical) field operations.
 */

#include <cassert>
#include <cmath>
#include <complex>
#include <ctime>
#include <iostream>
#include <stdexcept>

/**
 * \brief Class Complex to represent complex numbers as a field.
 */
class Complex {
    // The real value of the complex number
    double re;
    // The imaginary value of the complex number
    double im;

 public:
    /**
     * \brief Complex Constructor which initialises our complex number.
     * \details
     * Complex Constructor which initialises the complex number which takes
     * three arguments.
     * @param x If the third parameter is 'true' then this x is the absolute
     * value of the complex number, if the third parameter is 'false' then this
     * x is the real value of the complex number (optional).
     * @param y If the third parameter is 'true' then this y is the argument of
     * the complex number, if the third parameter is 'false' then this y is the
     * imaginary value of the complex number (optional).
     * @param is_polar 'false' by default. If we want to initialise our complex
     * number using polar form then set this to true, otherwise set it to false
     * to use initialiser which initialises real and imaginary values using the
     * first two parameters (optional).
     */
    explicit Complex(double x = 0.f, double y = 0.f, bool is_polar = false) {
        if (!is_polar) {
            re = x;
            im = y;
            return;
        }

        re = x * std::cos(y);
        im = x * std::sin(y);
    }

    /**
     * \brief Copy Constructor
     * @param other The other number to equate our number to.
     */
    Complex(const Complex &other) : re(other.real()), im(other.imag()) {}

    /**
     * \brief Member function to get real value of our complex number.
     * Member function (getter) to access the class' re value.
     */
    double real() const { return this->re; }

    /**
     * \brief Member function to get imaginary value of our complex number.
     * Member function (getter) to access the class' im value.
     */
    double imag() const { return this->im; }

    /**
     * \brief Member function to give the modulus of our complex number.
     * Member function to which gives the absolute value (modulus) of our
     * complex number
     * @return \f$ \sqrt{z \bar{z}} \f$ where \f$ z \f$ is our complex
     * number.
     */
    double abs() const {
        return std::sqrt(this->re * this->re + this->im * this->im);
    }

    /**
     * \brief Member function to give the argument of our complex number.
     * @return Argument of our Complex number in radians.
     */
    double arg() const { return std::atan2(this->im, this->re); }

    /**
     * \brief Operator overload of '+' on Complex class.
     * Operator overload to be able to add two complex numbers.
     * @param other The other number that is added to the current number.
     * @return result current number plus other number
     */
    Complex operator+(const Complex &other) {
        Complex result(this->re + other.re, this->im + other.im);
        return result;
    }

    /**
     * \brief Operator overload of '-' on Complex class.
     * Operator overload to be able to subtract two complex numbers.
     * @param other The other number being subtracted from the current number.
     * @return result current number subtract other number
     */
    Complex operator-(const Complex &other) {
        Complex result(this->re - other.re, this->im - other.im);
        return result;
    }

    /**
     * \brief Operator overload of '*' on Complex class.
     * Operator overload to be able to multiple two complex numbers.
     * @param other The other number to multiply the current number to.
     * @return result current number times other number.
     */
    Complex operator*(const Complex &other) {
        Complex result(this->re * other.re - this->im * other.im,
                       this->re * other.im + this->im * other.re);
        return result;
    }

    /**
     * \brief Operator overload of '~' on Complex class.
     * Operator overload of the BITWISE NOT which gives us the conjugate of our
     * complex number. NOTE: This is overloading the BITWISE operator but its
     * not a BITWISE operation in this definition.
     * @return result The conjugate of our complex number.
     */
    Complex operator~() const {
        Complex result(this->re, -(this->im));
        return result;
    }

    /**
     * \brief Operator overload of '/' on Complex class.
     * Operator overload to be able to divide two complex numbers. This function
     * would throw an exception if the other number is zero.
     * @param other The other number we divide our number by.
     * @return result Current number divided by other number.
     */
    Complex operator/(const Complex &other) {
        Complex result = *this * ~other;
        double denominator =
            other.real() * other.real() + other.imag() * other.imag();
        if (denominator != 0) {
            result = Complex(result.real() / denominator,
                             result.imag() / denominator);
            return result;
        } else {
            throw std::invalid_argument("Undefined Value");
        }
    }

    /**
     * \brief Operator overload of '=' on Complex class.
     * Operator overload to be able to copy RHS instance of Complex to LHS
     * instance of Complex
     */
    const Complex &operator=(const Complex &other) {
        this->re = other.real();
        this->im = other.imag();
        return *this;
    }
};

/**
 * \brief Operator overload of '==' on Complex class.
 * Logical Equal overload for our Complex class.
 * @param a Left hand side of our expression
 * @param b Right hand side of our expression
 * @return 'True' If real and imaginary parts of a and b are same
 * @return 'False' Otherwise.
 */
bool operator==(const Complex &a, const Complex &b) {
    return a.real() == b.real() && a.imag() == b.imag();
}

/**
 * \brief Operator overload of '<<' of ostream for Complex class.
 * Overloaded insersion operator to accommodate the printing of our complex
 * number in their standard form.
 * @param os The console stream
 * @param num The complex number.
 */
std::ostream &operator<<(std::ostream &os, const Complex &num) {
    os << "(" << num.real();
    if (num.imag() < 0) {
        os << " - " << -num.imag();
    } else {
        os << " + " << num.imag();
    }
    os << "i)";
    return os;
}

/**
 * \brief Function to get random numbers to generate our complex numbers for
 * test
 */
double get_rand() { return (std::rand() % 100 - 50) / 100.f; }

/**
 * Tests Function
 */
void tests() {
    std::srand(std::time(nullptr));
    double x1 = get_rand(), y1 = get_rand(), x2 = get_rand(), y2 = get_rand();
    Complex num1(x1, y1), num2(x2, y2);
    std::complex<double> cnum1(x1, y1), cnum2(x2, y2);
    Complex result;
    std::complex<double> expected;
    // Test for addition
    result = num1 + num2;
    expected = cnum1 + cnum2;
    assert(((void)"1 + 1i + 1 + 1i is equal to 2 + 2i but the addition doesn't "
                  "add up \n",
            (result.real() == expected.real() &&
             result.imag() == expected.imag())));
    std::cout << "First test passes." << std::endl;
    // Test for subtraction
    result = num1 - num2;
    expected = cnum1 - cnum2;
    assert(((void)"1 + 1i - 1 - 1i is equal to 0 but the program says "
                  "otherwise. \n",
            (result.real() == expected.real() &&
             result.imag() == expected.imag())));
    std::cout << "Second test passes." << std::endl;
    // Test for multiplication
    result = num1 * num2;
    expected = cnum1 * cnum2;
    assert(((void)"(1 + 1i) * (1 + 1i) is equal to 2i but the program says "
                  "otherwise. \n",
            (result.real() == expected.real() &&
             result.imag() == expected.imag())));
    std::cout << "Third test passes." << std::endl;
    // Test for division
    result = num1 / num2;
    expected = cnum1 / cnum2;
    assert(((void)"(1 + 1i) / (1 + 1i) is equal to 1 but the program says "
                  "otherwise.\n",
            (result.real() == expected.real() &&
             result.imag() == expected.imag())));
    std::cout << "Fourth test passes." << std::endl;
    // Test for conjugates
    result = ~num1;
    expected = std::conj(cnum1);
    assert(((void)"(1 + 1i) has a conjugate which is equal to (1 - 1i) but the "
                  "program says otherwise.\n",
            (result.real() == expected.real() &&
             result.imag() == expected.imag())));
    std::cout << "Fifth test passes.\n";
    // Test for Argument of our complex number
    assert(((void)"(1 + 1i) has argument PI / 4 but the program differs from "
                  "the std::complex result.\n",
            (num1.arg() == std::arg(cnum1))));
    std::cout << "Sixth test passes.\n";
    // Test for absolute value of our complex number
    assert(((void)"(1 + 1i) has absolute value sqrt(2) but the program differs "
                  "from the std::complex result. \n",
            (num1.abs() == std::abs(cnum1))));
    std::cout << "Seventh test passes.\n";
}

/**
 * Main function
 */
int main() {
    tests();
    return 0;
}

/**
 * @file
 *
 * \brief A hand-rolled complex-number type with the usual field operations
 * overloaded.
 * \details Wraps a real and imaginary component in a small class and
 * implements addition, subtraction, multiplication, division, conjugation,
 * modulus and argument, mirroring what std::complex provides.
 *
 * Rewritten variant for dataset generation - same public behavior, renamed
 * members/methods, restructured tests.
 */

#include <cassert>
#include <cmath>
#include <complex>
#include <ctime>
#include <iostream>
#include <stdexcept>

/**
 * \brief A minimal complex-number class supporting field arithmetic.
 */
class ComplexValue {
    double realPart;
    double imagPart;

 public:
    /**
     * \brief Construct a complex value either from Cartesian or polar
     * coordinates.
     * @param a real part, or magnitude when usePolar is true
     * @param b imaginary part, or angle (radians) when usePolar is true
     * @param usePolar when true, interpret (a, b) as (magnitude, angle)
     */
    explicit ComplexValue(double a = 0.0, double b = 0.0, bool usePolar = false) {
        if (!usePolar) {
            realPart = a;
            imagPart = b;
            return;
        }
        realPart = a * std::cos(b);
        imagPart = a * std::sin(b);
    }

    /// Copy constructor.
    ComplexValue(const ComplexValue &other)
        : realPart(other.real()), imagPart(other.imag()) {}

    /// Accessor for the real component.
    double real() const { return this->realPart; }

    /// Accessor for the imaginary component.
    double imag() const { return this->imagPart; }

    /// Modulus (magnitude) of the value: sqrt(re^2 + im^2).
    double abs() const {
        return std::sqrt(this->realPart * this->realPart +
                          this->imagPart * this->imagPart);
    }

    /// Argument (angle in radians) of the value.
    double arg() const { return std::atan2(this->imagPart, this->realPart); }

    /// Add two complex values.
    ComplexValue operator+(const ComplexValue &other) {
        return ComplexValue(this->realPart + other.realPart,
                             this->imagPart + other.imagPart);
    }

    /// Subtract another complex value from this one.
    ComplexValue operator-(const ComplexValue &other) {
        return ComplexValue(this->realPart - other.realPart,
                             this->imagPart - other.imagPart);
    }

    /// Multiply two complex values.
    ComplexValue operator*(const ComplexValue &other) {
        return ComplexValue(
            this->realPart * other.realPart - this->imagPart * other.imagPart,
            this->realPart * other.imagPart + this->imagPart * other.realPart);
    }

    /// Conjugate operator, borrowing the bitwise-NOT symbol for convenience.
    ComplexValue operator~() const {
        return ComplexValue(this->realPart, -(this->imagPart));
    }

    /// Divide this value by another; throws if the divisor is zero.
    ComplexValue operator/(const ComplexValue &other) {
        ComplexValue numerator = *this * ~other;
        double denom = other.real() * other.real() + other.imag() * other.imag();
        if (denom == 0) {
            throw std::invalid_argument("Undefined Value");
        }
        return ComplexValue(numerator.real() / denom, numerator.imag() / denom);
    }

    /// Assignment operator.
    const ComplexValue &operator=(const ComplexValue &other) {
        this->realPart = other.real();
        this->imagPart = other.imag();
        return *this;
    }
};

/// Equality comparison: both components must match exactly.
bool operator==(const ComplexValue &a, const ComplexValue &b) {
    return a.real() == b.real() && a.imag() == b.imag();
}

/// Stream insertion for printing in "(re +/- imi)" form.
std::ostream &operator<<(std::ostream &os, const ComplexValue &value) {
    os << "(" << value.real();
    if (value.imag() < 0) {
        os << " - " << -value.imag();
    } else {
        os << " + " << value.imag();
    }
    os << "i)";
    return os;
}

/// Produce a small pseudo-random value in [-0.5, 0.5) for test fixtures.
double randomComponent() { return (std::rand() % 100 - 50) / 100.f; }

/// Cross-check ComplexValue operations against std::complex for correctness.
void runSelfChecks() {
    std::srand(static_cast<unsigned>(std::time(nullptr)));
    double a1 = randomComponent(), b1 = randomComponent();
    double a2 = randomComponent(), b2 = randomComponent();

    ComplexValue lhs(a1, b1), rhs(a2, b2);
    std::complex<double> refLhs(a1, b1), refRhs(a2, b2);
    ComplexValue got;
    std::complex<double> want;

    got = lhs + rhs;
    want = refLhs + refRhs;
    assert(((void)"addition mismatch",
            (got.real() == want.real() && got.imag() == want.imag())));
    std::cout << "First test passes." << std::endl;

    got = lhs - rhs;
    want = refLhs - refRhs;
    assert(((void)"subtraction mismatch",
            (got.real() == want.real() && got.imag() == want.imag())));
    std::cout << "Second test passes." << std::endl;

    got = lhs * rhs;
    want = refLhs * refRhs;
    assert(((void)"multiplication mismatch",
            (got.real() == want.real() && got.imag() == want.imag())));
    std::cout << "Third test passes." << std::endl;

    got = lhs / rhs;
    want = refLhs / refRhs;
    assert(((void)"division mismatch",
            (got.real() == want.real() && got.imag() == want.imag())));
    std::cout << "Fourth test passes." << std::endl;

    got = ~lhs;
    want = std::conj(refLhs);
    assert(((void)"conjugate mismatch",
            (got.real() == want.real() && got.imag() == want.imag())));
    std::cout << "Fifth test passes.\n";

    assert(((void)"argument mismatch", (lhs.arg() == std::arg(refLhs))));
    std::cout << "Sixth test passes.\n";

    assert(((void)"modulus mismatch", (lhs.abs() == std::abs(refLhs))));
    std::cout << "Seventh test passes.\n";
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief Compute [double
 * factorial](https://en.wikipedia.org/wiki/Double_factorial): \f$n!!\f$
 *
 * Double factorial of a non-negative integer `n`, is defined as the product of
 * all the integers from 1 to n that have the same parity (odd or even) as n.
 * <br/>It is also called as semifactorial of a number and is denoted by
 * \f$n!!\f$
 */

#include <cassert>
#include <cstdint>
#include <iostream>

/** Compute double factorial using iterative method
 */
uint64_t double_factorial_iterative(uint64_t n) {
    uint64_t res = 1;
    for (uint64_t i = n;; i -= 2) {
        if (i == 0 || i == 1)
            return res;
        res *= i;
    }
    return res;
}

/** Compute double factorial using resursive method.
 * <br/>Recursion can be costly for large numbers.
 */
uint64_t double_factorial_recursive(uint64_t n) {
    if (n <= 1)
        return 1;
    return n * double_factorial_recursive(n - 2);
}

/** Wrapper to run tests using both recursive and iterative implementations.
 * The checks are only valid in debug builds due to the use of `assert()`
 * statements.
 * \param [in] n number to check double factorial for
 * \param [in] expected expected result
 */
void test(uint64_t n, uint64_t expected) {
    assert(double_factorial_iterative(n) == expected);
    assert(double_factorial_recursive(n) == expected);
}

/**
 * Test implementations
 */
void tests() {
    std::cout << "Test 1:\t n=5\t...";
    test(5, 15);
    std::cout << "passed\n";

    std::cout << "Test 2:\t n=15\t...";
    test(15, 2027025);
    std::cout << "passed\n";

    std::cout << "Test 3:\t n=0\t...";
    test(0, 1);
    std::cout << "passed\n";
}

/**
 * Main function
 */
int main() {
    tests();
    return 0;
}

/**
 * @file
 * @brief Alternate implementation for computing the semifactorial (double
 * factorial) of a non-negative integer.
 *
 * The double factorial n!! multiplies together every integer from 1 up to n
 * that shares the same parity as n. For instance 6!! = 6*4*2 and
 * 7!! = 7*5*3*1. This file demonstrates both a loop-based and a
 * self-calling (recursive) approach and cross-checks them against each
 * other.
 */

#include <cassert>
#include <cstdint>
#include <iostream>

/** Loop-driven computation of the double factorial.
 *  Repeatedly multiplies in the next lower value of the same parity until
 *  we hit the base case of 0 or 1.
 */
uint64_t semifactorial_loop(uint64_t value) {
    uint64_t product = 1;
    uint64_t current = value;
    while (true) {
        if (current == 0 || current == 1) {
            break;
        }
        product *= current;
        current -= 2;
    }
    return product;
}

/** Self-referential computation of the double factorial.
 *  Note: deep recursion may be inefficient for very large inputs.
 */
uint64_t semifactorial_recursive(uint64_t value) {
    if (value <= 1) {
        return 1;
    }
    return value * semifactorial_recursive(value - 2);
}

/** Compares both strategies against a known answer.
 *  \param value input to evaluate
 *  \param known_answer the value we expect both routines to produce
 */
void check_both_strategies(uint64_t value, uint64_t known_answer) {
    assert(semifactorial_loop(value) == known_answer);
    assert(semifactorial_recursive(value) == known_answer);
}

/**
 * Runs a small battery of sanity checks.
 */
void run_checks() {
    std::cout << "Check A (n=5) ... ";
    check_both_strategies(5, 15);
    std::cout << "ok\n";

    std::cout << "Check B (n=15) ... ";
    check_both_strategies(15, 2027025);
    std::cout << "ok\n";

    std::cout << "Check C (n=0) ... ";
    check_both_strategies(0, 1);
    std::cout << "ok\n";
}

/**
 * Program entry point.
 */
int main() {
    run_checks();
    return 0;
}

/**
 * @file
 * @brief [The Sieve of
 * Eratosthenes](https://en.wikipedia.org/wiki/Sieve_of_Eratosthenes)
 * @details
 * Store an array of booleans where a true value indicates that it's index is
 * prime. For all the values in the array starting from 2 which we know is
 * prime, we walk the array in multiples of the current outer value setting them
 * to not prime. If we remove all multiples of a value as we see it, we'll be
 * left with just primes.
 *
 * Pass "print" as a command line arg to see the generated list of primes
 * @author [Keval Kapdee](https://github.com/thechubbypanda)
 */

#include <cassert>   /// For assert
#include <chrono>    /// For timing the sieve
#include <iostream>  /// For IO operations
#include <string>    /// For string handling
#include <vector>    /// For std::vector

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @brief Performs the sieve
 * @param vec Array of bools, all initialised to true, where the number of
 * elements is the highest number we wish to check for primeness
 * @returns void
 */
void sieve(std::vector<bool> *vec) {
    (*vec)[0] = false;
    (*vec)[1] = false;

    // The sieve sets values to false as they are found not prime
    for (uint64_t n = 2; n < vec->size(); n++) {
        for (uint64_t multiple = n << 1; multiple < vec->size();
             multiple += n) {
            (*vec)[multiple] = false;
        }
    }
}

/**
 * @brief Prints all the indexes of true values in the passed std::vector
 * @param primes The vector that has been passed through `sieve(...)`
 * @returns void
 */
void print_primes(std::vector<bool> const &primes) {
    for (uint64_t i = 0; i < primes.size(); i++) {
        if (primes[i]) {
            std::cout << i << std::endl;
        }
    }
}
}  // namespace math

/**
 * @brief Self-tests the sieve function for major inconsistencies
 * @returns void
 */
static void test() {
    auto primes = std::vector<bool>(10, true);
    math::sieve(&primes);
    assert(primes[0] == false);
    assert(primes[1] == false);
    assert(primes[2] == true);
    assert(primes[3] == true);
    assert(primes[4] == false);
    assert(primes[5] == true);
    assert(primes[6] == false);
    assert(primes[7] == true);
    assert(primes[8] == false);
    assert(primes[9] == false);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @param argc commandline argument count
 * @param argv commandline array of arguments
 * @returns 0 on exit
 */
int main(int argc, char *argv[]) {
    test();  // run self-test implementations

    // The largest prime we will check for
    auto max = 10000;

    // Store a boolean for every number which states if that index is prime or
    // not
    auto primes = std::vector<bool>(max, true);

    // Store the algorithm start time
    auto start = std::chrono::high_resolution_clock::now();

    // Run the sieve
    math::sieve(&primes);

    // Time difference calculation
    auto time = std::chrono::duration_cast<
                    std::chrono::duration<double, std::ratio<1>>>(
                    std::chrono::high_resolution_clock::now() - start)
                    .count();

    // Print the primes if we see that "print" was passed as an arg
    if (argc > 1 && argv[1] == std::string("print")) {
        math::print_primes(primes);
    }

    // Print the time taken we found earlier
    std::cout << "Time taken: " << time << " seconds" << std::endl;

    return 0;
}

/**
 * @file
 * @brief Alternative rendering of the [Sieve of
 * Eratosthenes](https://en.wikipedia.org/wiki/Sieve_of_Eratosthenes) prime
 * generator.
 * @details
 * We keep a flag per candidate number; a flag that stays "on" means the
 * corresponding index survived as prime. Starting from the first prime (2),
 * every multiple of it gets flipped off, then we move to the next surviving
 * candidate and repeat. What's left switched on at the end are the primes.
 *
 * Run the binary with the argument "show" to print the discovered primes.
 */

#include <cassert>   /// assertion checks
#include <chrono>    /// wall-clock timing
#include <iostream>  /// console output
#include <string>    /// argument comparison
#include <vector>    /// dynamic flag array

/**
 * @namespace numeric_tools
 * @brief Collection of elementary number-theory routines
 */
namespace numeric_tools {

/**
 * @brief Marks off all composite numbers in-place.
 * @param flags pointer to a vector where flags[i] denotes "i might be prime"
 */
void mark_composites(std::vector<bool> *flags) {
    if (flags->size() > 0) (*flags)[0] = false;
    if (flags->size() > 1) (*flags)[1] = false;

    for (uint64_t candidate = 2; candidate < flags->size(); candidate++) {
        for (uint64_t hit = candidate * 2; hit < flags->size();
             hit += candidate) {
            (*flags)[hit] = false;
        }
    }
}

/**
 * @brief Emits every surviving prime index to stdout.
 * @param flags result vector produced by mark_composites
 */
void report_primes(const std::vector<bool> &flags) {
    for (uint64_t idx = 0; idx < flags.size(); idx++) {
        if (flags[idx]) {
            std::cout << idx << std::endl;
        }
    }
}

}  // namespace numeric_tools

/**
 * @brief Runs a handful of hard-coded checks against a small case.
 */
static void self_check() {
    std::vector<bool> flags(10, true);
    numeric_tools::mark_composites(&flags);

    assert(!flags[0]);
    assert(!flags[1]);
    assert(flags[2]);
    assert(flags[3]);
    assert(!flags[4]);
    assert(flags[5]);
    assert(!flags[6]);
    assert(flags[7]);
    assert(!flags[8]);
    assert(!flags[9]);

    std::cout << "self_check: everything checks out!\n";
}

/**
 * @brief Program entry point.
 * @param argc argument count
 * @param argv argument values
 */
int main(int argc, char *argv[]) {
    self_check();

    const int upper_bound = 10000;
    std::vector<bool> flags(upper_bound, true);

    const auto begin_time = std::chrono::high_resolution_clock::now();
    numeric_tools::mark_composites(&flags);
    const auto elapsed = std::chrono::duration_cast<
                             std::chrono::duration<double, std::ratio<1>>>(
                             std::chrono::high_resolution_clock::now() -
                             begin_time)
                             .count();

    bool wants_output = argc > 1 && std::string(argv[1]) == "show";
    if (wants_output) {
        numeric_tools::report_primes(flags);
    }

    std::cout << "Elapsed: " << elapsed << " seconds" << std::endl;
    return 0;
}

/**
 * @file
 * @brief Implementation of [Euler's
 * Totient](https://en.wikipedia.org/wiki/Euler%27s_totient_function)
 * @description
 * Euler Totient Function is also known as phi function.
 * \f[\phi(n) =
 * \phi\left({p_1}^{a_1}\right)\cdot\phi\left({p_2}^{a_2}\right)\ldots\f] where
 * \f$p_1\f$, \f$p_2\f$, \f$\ldots\f$ are prime factors of n.
 * <br/>3 Euler's properties:
 * 1. \f$\phi(n) = n-1\f$
 * 2. \f$\phi(n^k) = n^k - n^{k-1}\f$
 * 3. \f$\phi(a,b) = \phi(a)\cdot\phi(b)\f$ where a and b are relative primes.
 *
 * Applying this 3 properties on the first equation.
 * \f[\phi(n) =
 * n\cdot\left(1-\frac{1}{p_1}\right)\cdot\left(1-\frac{1}{p_2}\right)\cdots\f]
 * where \f$p_1\f$,\f$p_2\f$... are prime factors.
 * Hence Implementation in \f$O\left(\sqrt{n}\right)\f$.
 * <br/>Some known values are:
 * * \f$\phi(100) = 40\f$
 * * \f$\phi(1) = 1\f$
 * * \f$\phi(17501) = 15120\f$
 * * \f$\phi(1420) = 560\f$
 * @author [Mann Mehta](https://github.com/mann2108)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations

/**
 * @brief Mathematical algorithms
 * @namespace
 */
namespace math {
/**
 * @brief Function to calculate Euler's Totient
 * @param n the number to find the Euler's Totient of
 */
uint64_t phiFunction(uint64_t n) {
    uint64_t result = n;
    for (uint64_t i = 2; i * i <= n; i++) {
        if (n % i != 0)
            continue;
        while (n % i == 0) n /= i;

        result -= result / i;
    }
    if (n > 1)
        result -= result / n;

    return result;
}
}  // namespace math

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    assert(math::phiFunction(1) == 1);
    assert(math::phiFunction(2) == 1);
    assert(math::phiFunction(10) == 4);
    assert(math::phiFunction(123456) == 41088);
    assert(math::phiFunction(808017424794) == 263582333856);
    assert(math::phiFunction(3141592) == 1570792);
    assert(math::phiFunction(27182818) == 12545904);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief Alternate take on [Euler's Totient
 * Function](https://en.wikipedia.org/wiki/Euler%27s_totient_function).
 * @details
 * The totient of n counts the integers in [1, n] that are coprime to n.
 * Using its multiplicative decomposition over the distinct prime factors of
 * n, we can compute it in roughly O(sqrt(n)) by trial division: for every
 * prime factor p found, multiply the running result by (1 - 1/p).
 */

#include <cassert>   /// assertion checks
#include <cstdint>
#include <iostream>  /// console output

/**
 * @brief Number theory helpers
 * @namespace
 */
namespace numeric_tools {

/**
 * @brief Computes phi(n), the count of integers up to n coprime with n.
 * @param value the number under inspection
 */
uint64_t totient(uint64_t value) {
    uint64_t answer = value;
    uint64_t remaining = value;

    for (uint64_t factor = 2; factor * factor <= remaining; ++factor) {
        if (remaining % factor != 0) {
            continue;
        }
        while (remaining % factor == 0) {
            remaining /= factor;
        }
        answer -= answer / factor;
    }

    if (remaining > 1) {
        answer -= answer / remaining;
    }

    return answer;
}

}  // namespace numeric_tools

/**
 * @brief Exercises totient() against known reference values.
 */
static void verify_known_values() {
    assert(numeric_tools::totient(1) == 1);
    assert(numeric_tools::totient(2) == 1);
    assert(numeric_tools::totient(10) == 4);
    assert(numeric_tools::totient(123456) == 41088);
    assert(numeric_tools::totient(808017424794) == 263582333856);
    assert(numeric_tools::totient(3141592) == 1570792);
    assert(numeric_tools::totient(27182818) == 12545904);

    std::cout << "Every reference case matched!\n";
}

/**
 * @brief Entry point.
 */
int main() {
    verify_known_values();
    return 0;
}

/**
 * @file
 * @brief GCD using [extended Euclid's algorithm]
 * (https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm)
 *
 * Finding coefficients of a and b ie x and y in  Bézout's identity
 * \f[\text{gcd}(a, b) = a \times x + b \times y \f]
 * This is also used in finding Modular
 * multiplicative inverse of a number. (A * B)%M == 1 Here B is the MMI of A for
 * given M, so extendedEuclid (A, M) gives B.
 */
#include <algorithm>  // for swap function
#include <iostream>
#include <cstdint>

/**
 * function to update the coefficients per iteration
 * \f[r_0,\,r = r,\, r_0 - \text{quotient}\times r\f]
 *
 * @param[in,out] r signed or unsigned
 * @param[in,out] r0 signed or unsigned
 * @param[in] quotient  unsigned
 */
template <typename T, typename T2>
inline void update_step(T *r, T *r0, const T2 quotient) {
    T temp = *r;
    *r = *r0 - (quotient * temp);
    *r0 = temp;
}

/**
 * Implementation using iterative algorithm from
 * [Wikipedia](https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Pseudocode)
 *
 * @param[in] A unsigned
 * @param[in] B unsigned
 * @param[out] GCD unsigned
 * @param[out] x signed
 * @param[out] y signed
 */
template <typename T1, typename T2>
void extendedEuclid_1(T1 A, T1 B, T1 *GCD, T2 *x, T2 *y) {
    if (B > A)
        std::swap(A, B);  // Ensure that A >= B

    T2 s = 0, s0 = 1;
    T2 t = 1, t0 = 0;
    T1 r = B, r0 = A;

    while (r != 0) {
        T1 quotient = r0 / r;
        update_step(&r, &r0, quotient);
        update_step(&s, &s0, quotient);
        update_step(&t, &t0, quotient);
    }
    *GCD = r0;
    *x = s0;
    *y = t0;
}

/**
 * Implementation using recursive algorithm
 *
 * @param[in] A unsigned
 * @param[in] B unsigned
 * @param[out] GCD unsigned
 * @param[in,out] x signed
 * @param[in,out] y signed
 */
template <typename T, typename T2>
void extendedEuclid(T A, T B, T *GCD, T2 *x, T2 *y) {
    if (B > A)
        std::swap(A, B);  // Ensure that A >= B

    if (B == 0) {
        *GCD = A;
        *x = 1;
        *y = 0;
    } else {
        extendedEuclid(B, A % B, GCD, x, y);
        T2 temp = *x;
        *x = *y;
        *y = temp - (A / B) * (*y);
    }
}

/// Main function
int main() {
    uint32_t a, b, gcd;
    int32_t x, y;
    std::cin >> a >> b;
    extendedEuclid(a, b, &gcd, &x, &y);
    std::cout << gcd << " " << x << " " << y << std::endl;
    extendedEuclid_1(a, b, &gcd, &x, &y);
    std::cout << gcd << " " << x << " " << y << std::endl;
    return 0;
}

/**
 * @file
 * @brief Alternative walk-through of the [Extended Euclidean
 * Algorithm](https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm)
 *
 * Besides gcd(a, b), this also recovers coefficients x, y satisfying
 * Bezout's identity: a*x + b*y = gcd(a, b). This is handy, among other
 * things, for computing modular multiplicative inverses.
 */
#include <algorithm>  // std::swap
#include <cstdint>
#include <iostream>

/**
 * Advances one column of the extended-Euclid table.
 * new_r0 becomes old_r, new_r becomes old_r0 - quotient * old_r.
 *
 * @param cur pointer to the "current" running value
 * @param prev pointer to the "previous" running value
 * @param q the quotient for this step
 */
template <typename NumT, typename QuotT>
inline void advance_column(NumT *cur, NumT *prev, const QuotT q) {
    NumT snapshot = *cur;
    *cur = *prev - (q * snapshot);
    *prev = snapshot;
}

/**
 * Iterative variant, following the pseudocode from Wikipedia.
 *
 * @param[in] lhs first input
 * @param[in] rhs second input
 * @param[out] gcd_out resulting gcd
 * @param[out] coeff_x Bezout coefficient for lhs
 * @param[out] coeff_y Bezout coefficient for rhs
 */
template <typename T1, typename T2>
void bezout_iterative(T1 lhs, T1 rhs, T1 *gcd_out, T2 *coeff_x, T2 *coeff_y) {
    if (rhs > lhs) {
        std::swap(lhs, rhs);  // normalize so lhs >= rhs
    }

    T2 x_cur = 0, x_prev = 1;
    T2 y_cur = 1, y_prev = 0;
    T1 r_cur = rhs, r_prev = lhs;

    while (r_cur != 0) {
        T1 q = r_prev / r_cur;
        advance_column(&r_cur, &r_prev, q);
        advance_column(&x_cur, &x_prev, q);
        advance_column(&y_cur, &y_prev, q);
    }

    *gcd_out = r_prev;
    *coeff_x = x_prev;
    *coeff_y = y_prev;
}

/**
 * Recursive variant.
 *
 * @param[in] lhs first input
 * @param[in] rhs second input
 * @param[out] gcd_out resulting gcd
 * @param[in,out] coeff_x Bezout coefficient for lhs
 * @param[in,out] coeff_y Bezout coefficient for rhs
 */
template <typename T, typename T2>
void bezout_recursive(T lhs, T rhs, T *gcd_out, T2 *coeff_x, T2 *coeff_y) {
    if (rhs > lhs) {
        std::swap(lhs, rhs);  // normalize so lhs >= rhs
    }

    if (rhs == 0) {
        *gcd_out = lhs;
        *coeff_x = 1;
        *coeff_y = 0;
        return;
    }

    bezout_recursive(rhs, lhs % rhs, gcd_out, coeff_x, coeff_y);
    T2 saved_x = *coeff_x;
    *coeff_x = *coeff_y;
    *coeff_y = saved_x - (lhs / rhs) * (*coeff_y);
}

/// Program entry point
int main() {
    uint32_t first_val, second_val, gcd_result;
    int32_t bezout_x, bezout_y;

    std::cin >> first_val >> second_val;

    bezout_recursive(first_val, second_val, &gcd_result, &bezout_x, &bezout_y);
    std::cout << gcd_result << " " << bezout_x << " " << bezout_y << std::endl;

    bezout_iterative(first_val, second_val, &gcd_result, &bezout_x, &bezout_y);
    std::cout << gcd_result << " " << bezout_x << " " << bezout_y << std::endl;

    return 0;
}

/**
 * @file
 * @brief Find the [factorial](https://en.wikipedia.org/wiki/Factorial) of a
 * given number
 * @details Calculate factorial via recursion
 * \f[n! = n\times(n-1)\times(n-2)\times(n-3)\times\ldots\times3\times2\times1
 *       = n\times(n-1)!\f]
 * for example:
 * \f$5! = 5\times4! = 5\times4\times3\times2\times1 = 120\f$
 *
 * @author [Akshay Gupta](https://github.com/Akshay1910)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for I/O operations
/**
 * @namespace
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * @brief function to find factorial of given number
 * @param n is the number which is to be factorialized
 * @warning Maximum value for the parameter is 20 as 21!
 * cannot be represented in 64 bit unsigned int
 */
uint64_t factorial(uint8_t n) {
    if (n > 20) {
        throw std::invalid_argument("maximum value is 20\n");
    }
    if (n == 0) {
        return 1;
    }
    return n * factorial(n - 1);
}
}  // namespace math

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    assert(math::factorial(1) == 1);
    assert(math::factorial(0) == 1);
    assert(math::factorial(5) == 120);
    assert(math::factorial(10) == 3628800);
    assert(math::factorial(20) == 2432902008176640000);
    std::cout << "All tests have passed successfully!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Alternate presentation of the classic recursive
 * [factorial](https://en.wikipedia.org/wiki/Factorial) computation.
 * @details
 * n! is the product of every positive integer up to n, and can be defined
 * recursively as n! = n * (n-1)! with 0! = 1 as the base case.
 */

#include <cassert>   /// for runtime assertions
#include <cstdint>
#include <iostream>  /// for console output

/**
 * @namespace
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * @brief Recursively computes n! for small n.
 * @param n value to take the factorial of
 * @warning n must not exceed 20, since 21! overflows a 64-bit unsigned type.
 */
uint64_t factorial(uint8_t n) {
    if (n > 20) {
        throw std::invalid_argument("input must not exceed 20\n");
    }
    if (n == 0) {
        return 1;
    }
    return n * factorial(n - 1);
}

}  // namespace math

/**
 * @brief Runs a sequence of assertions to validate factorial().
 */
static void run_self_tests() {
    assert(math::factorial(1) == 1);
    assert(math::factorial(0) == 1);
    assert(math::factorial(5) == 120);
    assert(math::factorial(10) == 3628800);
    assert(math::factorial(20) == 2432902008176640000);
    std::cout << "Every self-test succeeded!\n";
}

/**
 * @brief Program entry point.
 */
int main() {
    run_self_tests();
    return 0;
}

/**
 * @file
 * @brief [Factorial](https://en.wikipedia.org/wiki/Factorial) calculation using
 * recursion and [memoization](https://en.wikipedia.org/wiki/Memoization)
 * @details
 * This program computes the factorial of a non-negative integer using recursion
 * with memoization (top-down dynamic programming). It stores intermediate
 * results to avoid redundant calculations for improved efficiency.
 *
 * Memoization is a form of caching where the result to an expensive function
 * call is stored and returned. Example: Input: n = 5 Output: 120
 *
 * Explanation: 5! = 5 × 4 × 3 × 2 × 1 = 120
 *
 * The program uses a recursive function which caches computed
 * results in a memo array to avoid recalculating factorials for the same
 * numbers.
 *
 * Time Complexity: O(n)
 * Space Complexity: O(n)
 */

#include <cassert>  // For test cases
#include <cstdint>  // For uint64_t
#include <vector>   // For std::vector

class MemorisedFactorial {
    std::vector<std::uint64_t> known_values = {1};

 public:
    /**
     * @note This function was intentionally written as recursive
     * and it does not handle overflows.
     * @returns factorial of n
     */
    std::uint64_t operator()(std::uint64_t n) {
        if (n >= this->known_values.size()) {
            this->known_values.push_back(n * this->operator()(n - 1));
        }
        return this->known_values.at(n);
    }
};

void test_MemorisedFactorial_in_order() {
    auto factorial = MemorisedFactorial();
    assert(factorial(0) == 1);
    assert(factorial(1) == 1);
    assert(factorial(5) == 120);
    assert(factorial(10) == 3628800);
}

void test_MemorisedFactorial_no_order() {
    auto factorial = MemorisedFactorial();
    assert(factorial(10) == 3628800);
}

/**
 * @brief Main function to run tests
 * @returns 0 on program success
 */
int main() {
    test_MemorisedFactorial_in_order();
    test_MemorisedFactorial_no_order();
    return 0;
}

/**
 * @file
 * @brief Alternate demonstration of computing factorials with a cache
 * (top-down [memoization](https://en.wikipedia.org/wiki/Memoization)).
 * @details
 * Rather than recomputing n! from scratch each time, previously computed
 * results are stashed away and reused. E.g. once 4! is known, 5! is just
 * 5 * (cached 4!).
 *
 * Time complexity: O(n) amortized across repeated calls.
 * Space complexity: O(n) for the cache.
 */

#include <cassert>  // for assert
#include <cstdint>  // for std::uint64_t
#include <vector>   // for std::vector

/**
 * Callable object that lazily fills in a factorial cache as needed.
 */
class CachingFactorial {
    std::vector<std::uint64_t> cache_ = {1};

 public:
    /**
     * @note Deliberately implemented via recursion; overflow is not
     * guarded against.
     * @returns n! using (and extending) the internal cache
     */
    std::uint64_t operator()(std::uint64_t n) {
        if (n >= cache_.size()) {
            std::uint64_t previous = this->operator()(n - 1);
            cache_.push_back(n * previous);
        }
        return cache_.at(n);
    }
};

/**
 * Exercises the cache by requesting factorials in increasing order.
 */
void scenario_sequential_lookups() {
    CachingFactorial fac;
    assert(fac(0) == 1);
    assert(fac(1) == 1);
    assert(fac(5) == 120);
    assert(fac(10) == 3628800);
}

/**
 * Exercises the cache by jumping straight to a larger value.
 */
void scenario_direct_lookup() {
    CachingFactorial fac;
    assert(fac(10) == 3628800);
}

/**
 * @brief Drives both test scenarios.
 * @returns 0 on success
 */
int main() {
    scenario_sequential_lookups();
    scenario_direct_lookup();
    return 0;
}

/**
 * @file
 * @brief Faster computation for \f$a^b\f$
 *
 * Program that computes \f$a^b\f$ in \f$O(logN)\f$ time.
 * It is based on formula that:
 * 1. if \f$b\f$ is even:
 *  \f$a^b = a^\frac{b}{2} \cdot a^\frac{b}{2} = {a^\frac{b}{2}}^2\f$
 * 2. if \f$b\f$ is odd: \f$a^b = a^\frac{b-1}{2}
 *  \cdot a^\frac{b-1}{2} \cdot a = {a^\frac{b-1}{2}}^2 \cdot a\f$
 *
 * We can compute \f$a^b\f$ recursively using above algorithm.
 */

#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <ctime>
#include <iostream>

/**
 * algorithm implementation for \f$a^b\f$
 */
template <typename T>
double fast_power_recursive(T a, T b) {
    // negative power. a^b = 1 / (a^-b)
    if (b < 0)
        return 1.0 / fast_power_recursive(a, -b);

    if (b == 0)
        return 1;
    T bottom = fast_power_recursive(a, b >> 1);
    // Since it is integer division b/2 = (b-1)/2 where b is odd.
    // Therefore, case2 is easily solved by integer division.

    double result;
    if ((b & 1) == 0)  // case1
        result = bottom * bottom;
    else  // case2
        result = bottom * bottom * a;
    return result;
}

/**
    Same algorithm with little different formula.
    It still calculates in \f$O(\log N)\f$
*/
template <typename T>
double fast_power_linear(T a, T b) {
    // negative power. a^b = 1 / (a^-b)
    if (b < 0)
        return 1.0 / fast_power_linear(a, -b);

    double result = 1;
    while (b) {
        if (b & 1)
            result = result * a;
        a = a * a;
        b = b >> 1;
    }
    return result;
}

/**
 * Main function
 */
int main() {
    std::srand(std::time(nullptr));
    std::ios_base::sync_with_stdio(false);

    std::cout << "Testing..." << std::endl;
    for (int i = 0; i < 20; i++) {
        int a = std::rand() % 20 - 10;
        int b = std::rand() % 20 - 10;
        std::cout << std::endl << "Calculating " << a << "^" << b << std::endl;
        assert(fast_power_recursive(a, b) == std::pow(a, b));
        assert(fast_power_linear(a, b) == std::pow(a, b));

        std::cout << "------ " << a << "^" << b << " = "
                  << fast_power_recursive(a, b) << std::endl;
    }

    int64_t a, b;
    std::cin >> a >> b;

    std::cout << a << "^" << b << " = " << fast_power_recursive(a, b)
              << std::endl;

    std::cout << a << "^" << b << " = " << fast_power_linear(a, b) << std::endl;

    return 0;
}

/**
 * @file
 * @brief Alternate look at rapid exponentiation, computing a^b in
 * O(log b) time.
 *
 * The trick: split the exponent in half each step.
 *   - even exponent:  a^b = (a^(b/2))^2
 *   - odd exponent:   a^b = (a^((b-1)/2))^2 * a
 * Both a recursive and an iterative ("binary exponentiation") version are
 * provided below.
 */

#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <ctime>
#include <iostream>

/**
 * Recursive divide-and-conquer exponentiation.
 */
template <typename T>
double power_via_recursion(T base, T exponent) {
    if (exponent < 0) {
        return 1.0 / power_via_recursion(base, -exponent);
    }
    if (exponent == 0) {
        return 1;
    }

    double half = power_via_recursion(base, exponent >> 1);
    // integer division already floors (exp-1)/2 for odd exponents
    if ((exponent & 1) == 0) {
        return half * half;
    }
    return half * half * base;
}

/**
 * Iterative ("square and multiply") exponentiation, still O(log b).
 */
template <typename T>
double power_via_loop(T base, T exponent) {
    if (exponent < 0) {
        return 1.0 / power_via_loop(base, -exponent);
    }

    double accum = 1;
    while (exponent != 0) {
        if (exponent & 1) {
            accum = accum * base;
        }
        base = base * base;
        exponent = exponent >> 1;
    }
    return accum;
}

/**
 * Entry point: runs randomized cross-checks then reads a and b for a
 * manual computation.
 */
int main() {
    std::srand(std::time(nullptr));
    std::ios_base::sync_with_stdio(false);

    std::cout << "Running randomized cross-checks..." << std::endl;
    for (int trial = 0; trial < 20; trial++) {
        int base = std::rand() % 20 - 10;
        int exponent = std::rand() % 20 - 10;
        std::cout << std::endl
                  << "Trying " << base << "^" << exponent << std::endl;
        assert(power_via_recursion(base, exponent) == std::pow(base, exponent));
        assert(power_via_loop(base, exponent) == std::pow(base, exponent));

        std::cout << "------ " << base << "^" << exponent << " = "
                  << power_via_recursion(base, exponent) << std::endl;
    }

    int64_t base_in, exp_in;
    std::cin >> base_in >> exp_in;

    std::cout << base_in << "^" << exp_in << " = "
              << power_via_recursion(base_in, exp_in) << std::endl;
    std::cout << base_in << "^" << exp_in << " = "
              << power_via_loop(base_in, exp_in) << std::endl;

    return 0;
}

/**
 * @file
 * @brief n-th [Fibonacci
 * number](https://en.wikipedia.org/wiki/Fibonacci_sequence).
 *
 * @details
 * Naive recursive implementation to calculate the n-th Fibonacci number.
 * \f[\text{fib}(n) = \text{fib}(n-1) + \text{fib}(n-2)\f]
 *
 * @see fibonacci_large.cpp, fibonacci_fast.cpp, string_fibonacci.cpp
 */

#include <cstdint>
#include <cassert>   /// for assert
#include <iostream>  /// for IO operations

/**
 * @namespace math
 * @brief Math algorithms
 */
namespace math {
/**
 * @namespace fibonacci
 * @brief Functions for Fibonacci sequence
 */
namespace fibonacci {
/**
 * @brief Function to compute the n-th Fibonacci number
 * @param n the index of the Fibonacci number
 * @returns n-th element of the Fibonacci's sequence
 */
uint64_t fibonacci(uint64_t n) {
    // If the input is 0 or 1 just return the same (Base Case)
    // This will set the first 2 values of the sequence
    if (n <= 1) {
        return n;
    }

    // Add the preceding 2 values of the sequence to get next
    return fibonacci(n - 1) + fibonacci(n - 2);
}
}  // namespace fibonacci
}  // namespace math

/**
 * @brief Self-test implementation
 * @returns `void`
 */
static void test() {
    assert(math::fibonacci::fibonacci(0) == 0);
    assert(math::fibonacci::fibonacci(1) == 1);
    assert(math::fibonacci::fibonacci(2) == 1);
    assert(math::fibonacci::fibonacci(3) == 2);
    assert(math::fibonacci::fibonacci(4) == 3);
    assert(math::fibonacci::fibonacci(15) == 610);
    assert(math::fibonacci::fibonacci(20) == 6765);
    std::cout << "All tests have passed successfully!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Alternative take on the naive recursive [Fibonacci
 * sequence](https://en.wikipedia.org/wiki/Fibonacci_sequence) computation.
 *
 * @details
 * The straightforward (and exponential-time) definition
 * fib(n) = fib(n-1) + fib(n-2), with fib(0) = 0 and fib(1) = 1.
 *
 * @see fibonacci_large.cpp, fibonacci_fast.cpp, string_fibonacci.cpp
 */

#include <cstdint>
#include <cassert>   /// assertion checks
#include <iostream>  /// console output

/**
 * @namespace math
 * @brief Math algorithms
 */
namespace math {
/**
 * @namespace sequences
 * @brief Sequence generators, including Fibonacci
 */
namespace sequences {

/**
 * @brief Recursively determines the n-th term of the Fibonacci sequence.
 * @param n index into the sequence (0-based)
 * @returns the n-th Fibonacci number
 */
uint64_t nth_fibonacci(uint64_t n) {
    // Base cases seed the first two terms directly.
    if (n <= 1) {
        return n;
    }

    // Otherwise, sum the two prior terms.
    return nth_fibonacci(n - 1) + nth_fibonacci(n - 2);
}

}  // namespace sequences
}  // namespace math

