}

/**
 * @file
 * @brief Rewritten driver for computing arbitrarily large Fibonacci
 * numbers using a custom big-integer type.
 *
 * Reads an index N from the command line (or prompts interactively) and
 * reports the N-th Fibonacci number, its digit count, and how long the
 * computation took. Finishes with a fixed regression check against a
 * precomputed 5000th Fibonacci number.
 *
 * \author rewritten for educational/classroom comparison purposes
 * @see fibonacci.cpp, fibonacci_fast.cpp, string_fibonacci.cpp
 */

#include <cinttypes>
#include <ctime>
#include <iostream>

#include "./large_number.h"

/**
 * Iteratively builds up Fibonacci values using the big-integer type,
 * following f(n) = f(n-1) + f(n-2).
 */
large_number compute_big_fibonacci(uint64_t target_index) {
    large_number older(1);
    large_number newer(1);

    uint64_t remaining = target_index;
    do {
        large_number swap_holder = newer;
        newer += older;
        older = swap_holder;
        remaining--;
    } while (remaining > 2);  // sequence effectively starts counting from 2

    return newer;
}

int main(int argc, char *argv[]) {
    uint64_t requested_index;

    if (argc == 2) {
        requested_index = strtoull(argv[1], NULL, 10);
    } else {
        std::cout << "Enter N: ";
        std::cin >> requested_index;
    }

    clock_t started_at = std::clock();
    large_number computed = compute_big_fibonacci(requested_index);
    clock_t finished_at = std::clock();
    double seconds_elapsed = static_cast<double>(finished_at - started_at) /
                              static_cast<double>(CLOCKS_PER_SEC);

    std::cout << std::endl
              << requested_index << "^th Fibonacci number: " << computed
              << std::endl
              << "Number of digits: " << computed.num_digits() << std::endl
              << "Time taken: " << std::scientific << seconds_elapsed << " s"
              << std::endl;

    uint64_t regression_index = 5000;
    large_number expected_5000th(
