/**
 * @file
 * @brief This program computes the N^th Fibonacci number in modulo mod
 * input argument .
 *
 * Takes O(logn) time to compute nth Fibonacci number
 *
 *
 * \author [villayatali123](https://github.com/villayatali123)
 * \author [unknown author]()
 * @see fibonacci.cpp, fibonacci_fast.cpp, string_fibonacci.cpp,
 * fibonacci_large.cpp
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

/**
 * This function finds nth fibonacci number in a given modulus
 * @param n nth fibonacci number
 * @param mod  modulo number
 */
uint64_t fibo(uint64_t n, uint64_t mod) {
    std::vector<uint64_t> result(2, 0);
    std::vector<std::vector<uint64_t>> transition(2,
                                                  std::vector<uint64_t>(2, 0));
    std::vector<std::vector<uint64_t>> Identity(2, std::vector<uint64_t>(2, 0));
    n--;
    result[0] = 1, result[1] = 1;
    Identity[0][0] = 1;
    Identity[0][1] = 0;
    Identity[1][0] = 0;
    Identity[1][1] = 1;

    transition[0][0] = 0;
    transition[1][0] = transition[1][1] = transition[0][1] = 1;

    while (n) {
        if (n % 2) {
            std::vector<std::vector<uint64_t>> res(2,
                                                   std::vector<uint64_t>(2, 0));
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    for (int k = 0; k < 2; k++) {
                        res[i][j] =
                            (res[i][j] % mod +
                             ((Identity[i][k] % mod * transition[k][j] % mod)) %
                                 mod) %
                            mod;
                    }
                }
            }
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    Identity[i][j] = res[i][j];
                }
            }
            n--;
        } else {
            std::vector<std::vector<uint64_t>> res1(
                2, std::vector<uint64_t>(2, 0));
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    for (int k = 0; k < 2; k++) {
                        res1[i][j] =
                            (res1[i][j] % mod + ((transition[i][k] % mod *
                                                  transition[k][j] % mod)) %
                                                    mod) %
                            mod;
                    }
                }
            }
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < 2; j++) {
                    transition[i][j] = res1[i][j];
                }
            }
            n = n / 2;
        }
    }
    return ((result[0] % mod * Identity[0][0] % mod) % mod +
            (result[1] % mod * Identity[1][0] % mod) % mod) %
           mod;
}

/**
 * Function to test above algorithm
 */
static void test() {
    assert(fibo(6, 1000000007) == 8);
    std::cout << "test case:1 passed\n";
    assert(fibo(5, 1000000007) == 5);
    std::cout << "test case:2 passed\n";
    assert(fibo(10, 1000000007) == 55);
    std::cout << "test case:3 passed\n";
    assert(fibo(500, 100) == 25);
    std::cout << "test case:3 passed\n";
    assert(fibo(500, 10000) == 4125);
    std::cout << "test case:3 passed\n";
    std::cout << "--All tests passed--\n";
}

/**
 * Main function
 */
int main() {
    test();
    uint64_t mod = 1000000007;
    std::cout << "Enter the value of N: ";
    uint64_t n = 0;
    std::cin >> n;
    std::cout << n << "th Fibonacci number in modulo " << mod << ": "
              << fibo(n, mod) << std::endl;
}

/**
 * @file
 * @brief Alternative implementation for computing the N-th Fibonacci
 * number modulo m via 2x2 matrix exponentiation.
 *
 * Runs in O(log n) by repeatedly squaring the transformation matrix
 * [[1,1],[1,0]], rather than iterating n times.
 *
 * @see fibonacci.cpp, fibonacci_fast.cpp, string_fibonacci.cpp,
 * fibonacci_large.cpp
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

using Matrix2 = std::vector<std::vector<uint64_t>>;

/**
 * Multiplies two 2x2 matrices without any modular reduction (caller
 * applies mod separately where needed).
 */
static Matrix2 mat_mult_plain(const Matrix2 &lhs, const Matrix2 &rhs) {
    Matrix2 product(2, std::vector<uint64_t>(2, 0));
    product[0][0] = lhs[0][0] * rhs[0][0] + lhs[0][1] * rhs[1][0];
    product[0][1] = lhs[0][0] * rhs[0][1] + lhs[0][1] * rhs[1][1];
    product[1][0] = lhs[1][0] * rhs[0][0] + lhs[1][1] * rhs[1][0];
    product[1][1] = lhs[1][0] * rhs[0][1] + lhs[1][1] * rhs[1][1];
    return product;
}

/**
 * Multiplies two 2x2 matrices with every intermediate product reduced
 * modulo `modulus`, to avoid overflow when values get large.
 */
static Matrix2 mat_mult_mod(const Matrix2 &lhs, const Matrix2 &rhs,
                             uint64_t modulus) {
    Matrix2 product(2, std::vector<uint64_t>(2, 0));
    for (int row = 0; row < 2; row++) {
        for (int col = 0; col < 2; col++) {
            uint64_t total = 0;
            for (int k = 0; k < 2; k++) {
                total = (total % modulus +
                         ((lhs[row][k] % modulus * rhs[k][col] % modulus)) %
                             modulus) %
                        modulus;
            }
            product[row][col] = total;
        }
    }
    return product;
}

/**
 * Raises the Fibonacci transition matrix to the power `exponent`, modulo
 * `modulus`, using binary exponentiation (square-and-multiply).
 */
static Matrix2 transition_matrix_power(uint64_t exponent, uint64_t modulus) {
    Matrix2 base{{0, 1}, {1, 1}};
    Matrix2 acc{{1, 0}, {0, 1}};  // identity matrix

    while (exponent > 0) {
        if (exponent % 2 == 1) {
            acc = mat_mult_mod(acc, base, modulus);
        }
        base = mat_mult_mod(base, base, modulus);
        exponent /= 2;
    }
    return acc;
}

/**
 * Computes the n-th Fibonacci number modulo `modulus` using matrix
 * exponentiation.
 * @param n index to compute
 * @param modulus the modulus to reduce by
 */
uint64_t fibonacci_mod(uint64_t n, uint64_t modulus) {
    if (n == 0) {
        return 0 % modulus;
    }
    // We want M^(n-1) applied to the base vector (1, 1).
    Matrix2 powered = transition_matrix_power(n - 1, modulus);
    uint64_t f_n_minus_1 = 1, f_n = 1;
    uint64_t answer = (powered[0][0] % modulus * f_n_minus_1 % modulus +
                        powered[0][1] % modulus * f_n % modulus) %
                       modulus;
    return answer;
}

/**
 * @brief Runs a handful of regression checks against fibonacci_mod.
 */
static void run_checks() {
    assert(fibonacci_mod(6, 1000000007) == 8);
    std::cout << "check 1 passed\n";
    assert(fibonacci_mod(5, 1000000007) == 5);
    std::cout << "check 2 passed\n";
    assert(fibonacci_mod(10, 1000000007) == 55);
    std::cout << "check 3 passed\n";
    assert(fibonacci_mod(500, 100) == 25);
    std::cout << "check 4 passed\n";
    assert(fibonacci_mod(500, 10000) == 4125);
    std::cout << "check 5 passed\n";
    std::cout << "--all checks passed--\n";
}

/**
 * @brief Program entry point.
 */
int main() {
    run_checks();
    uint64_t modulus = 1000000007;
    std::cout << "Enter the value of N: ";
    uint64_t index = 0;
    std::cin >> index;
    std::cout << index << "th Fibonacci number in modulo " << modulus << ": "
              << fibonacci_mod(index, modulus) << std::endl;
}

/**
 * @file
 * @brief An algorithm to calculate the sum of [Fibonacci
 * Sequence](https://en.wikipedia.org/wiki/Fibonacci_number): \f$\mathrm{F}(n) +
 * \mathrm{F}(n+1) + .. + \mathrm{F}(m)\f$
 * @details An algorithm to calculate the sum of Fibonacci Sequence:
 * \f$\mathrm{F}(n) + \mathrm{F}(n+1) + .. + \mathrm{F}(m)\f$ where
 * \f$\mathrm{F}(i)\f$ denotes the i-th Fibonacci Number . Note that F(0) = 0
 * and F(1) = 1. The value of the sum is calculated using matrix exponentiation.
 * Reference source:
 * https://stackoverflow.com/questions/4357223/finding-the-sum-of-fibonacci-numbers
 * @author [Sarthak Sahu](https://github.com/SarthakSahu1009)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for std::cin and std::cout
#include <vector>    /// for std::vector

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @namespace fibonacci_sum
 * @brief Functions for the sum of the Fibonacci Sequence: \f$\mathrm{F}(n) +
 * \mathrm{F}(n+1) + .. + \mathrm{F}(m)\f$
 */
namespace fibonacci_sum {
using matrix = std::vector<std::vector<uint64_t> >;

/**
 * Function to multiply two matrices
 * @param T matrix 1
 * @param A martix 2
 * @returns resultant matrix
 */
math::fibonacci_sum::matrix multiply(const math::fibonacci_sum::matrix &T,
                                     const math::fibonacci_sum::matrix &A) {
    math::fibonacci_sum::matrix result(2, std::vector<uint64_t>(2, 0));

    // multiplying matrices
    result[0][0] = T[0][0] * A[0][0] + T[0][1] * A[1][0];
    result[0][1] = T[0][0] * A[0][1] + T[0][1] * A[1][1];
    result[1][0] = T[1][0] * A[0][0] + T[1][1] * A[1][0];
    result[1][1] = T[1][0] * A[0][1] + T[1][1] * A[1][1];

    return result;
}

/**
 * Function to compute A^n where A is a matrix.
 * @param T matrix
 * @param ex power
 * @returns resultant matrix
 */
math::fibonacci_sum::matrix power(math::fibonacci_sum::matrix T, uint64_t ex) {
    math::fibonacci_sum::matrix A{{1, 1}, {1, 0}};
    if (ex == 0 || ex == 1) {
        return T;
    }

    T = power(T, ex / 2);
    T = multiply(T, T);
    if (ex & 1) {
        T = multiply(T, A);
    }
    return T;
}

/**
 * Function to compute sum of fibonacci sequence from 0 to n.
 * @param n number
 * @returns uint64_t ans, the sum of sequence
 */
uint64_t result(uint64_t n) {
    math::fibonacci_sum::matrix T{{1, 1}, {1, 0}};
    T = power(T, n);
    uint64_t ans = T[0][1];
    ans = (ans - 1);
    return ans;
}

/**
 * Function to compute sum of fibonacci sequence from n to m.
 * @param n start of sequence
 * @param m end of sequence
 * @returns uint64_t the sum of sequence
 */
uint64_t fiboSum(uint64_t n, uint64_t m) {
    return (result(m + 2) - result(n + 1));
}
}  // namespace fibonacci_sum
}  // namespace math

/**
 * Function for testing fiboSum function.
 * test cases and assert statement.
 * @returns `void`
 */
static void test() {
    uint64_t n = 0, m = 3;
    uint64_t test_1 = math::fibonacci_sum::fiboSum(n, m);
    assert(test_1 == 4);
    std::cout << "Passed Test 1!" << std::endl;

    n = 3;
    m = 5;
    uint64_t test_2 = math::fibonacci_sum::fiboSum(n, m);
    assert(test_2 == 10);
    std::cout << "Passed Test 2!" << std::endl;

    n = 5;
    m = 7;
    uint64_t test_3 = math::fibonacci_sum::fiboSum(n, m);
    assert(test_3 == 26);
    std::cout << "Passed Test 3!" << std::endl;

    n = 7;
    m = 10;
    uint64_t test_4 = math::fibonacci_sum::fiboSum(n, m);
    assert(test_4 == 123);
    std::cout << "Passed Test 4!" << std::endl;

    n = 9;
    m = 12;
    uint64_t test_5 = math::fibonacci_sum::fiboSum(n, m);
    assert(test_5 == 322);
    std::cout << "Passed Test 5!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // execute the tests
    return 0;
}

/**
 * @file
 * @brief Alternative computation of the running sum of [Fibonacci
 * numbers](https://en.wikipedia.org/wiki/Fibonacci_number) between two
 * indices, i.e. F(n) + F(n+1) + ... + F(m).
 * @details
 * We rely on the closed identity that the sum of the first k Fibonacci
 * numbers (starting at F(0)=0) equals F(k+2) - 1. Subtracting the prefix
 * sum up to n-1 from the prefix sum up to m gives the requested range
 * sum. Matrix exponentiation is used to compute individual Fibonacci
 * terms in O(log n).
 */

#include <cassert>   /// assertion checks
#include <cstdint>
#include <iostream>  /// std::cin / std::cout
#include <vector>    /// std::vector

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @namespace range_sum
 * @brief Helpers for summing a contiguous range of Fibonacci numbers
 */
namespace range_sum {

using Grid = std::vector<std::vector<uint64_t>>;

/**
 * Multiplies two 2x2 grids together (matrix multiplication).
 */
Grid combine(const Grid &left, const Grid &right) {
    Grid out(2, std::vector<uint64_t>(2, 0));

    out[0][0] = left[0][0] * right[0][0] + left[0][1] * right[1][0];
    out[0][1] = left[0][0] * right[0][1] + left[0][1] * right[1][1];
    out[1][0] = left[1][0] * right[0][0] + left[1][1] * right[1][0];
    out[1][1] = left[1][0] * right[0][1] + left[1][1] * right[1][1];

    return out;
}

/**
 * Raises grid `base` to the power `exponent` via repeated squaring.
 */
Grid raise_to_power(Grid base, uint64_t exponent) {
    Grid multiplier{{1, 1}, {1, 0}};
    if (exponent == 0 || exponent == 1) {
        return base;
    }

    base = raise_to_power(base, exponent / 2);
    base = combine(base, base);
    if (exponent & 1) {
        base = combine(base, multiplier);
    }
    return base;
}

/**
 * Prefix sum of Fibonacci numbers F(0) + F(1) + ... + F(k-1), derived
 * from the identity sum == F(k+1) - 1 via matrix exponentiation.
 */
uint64_t prefix_sum(uint64_t k) {
    Grid transition{{1, 1}, {1, 0}};
    transition = raise_to_power(transition, k);
    uint64_t value = transition[0][1];
    return value - 1;
}

/**
 * Sum of F(from) + F(from+1) + ... + F(to).
 */
uint64_t range_total(uint64_t from, uint64_t to) {
    return prefix_sum(to + 2) - prefix_sum(from + 1);
}

}  // namespace range_sum
}  // namespace math

/**
 * @brief Runs a series of checks against known range sums.
 */
static void run_range_sum_checks() {
    uint64_t lo = 0, hi = 3;
    assert(math::range_sum::range_total(lo, hi) == 4);
    std::cout << "Range-sum check 1 passed!" << std::endl;

    lo = 3;
    hi = 5;
    assert(math::range_sum::range_total(lo, hi) == 10);
    std::cout << "Range-sum check 2 passed!" << std::endl;

    lo = 5;
    hi = 7;
    assert(math::range_sum::range_total(lo, hi) == 26);
    std::cout << "Range-sum check 3 passed!" << std::endl;

    lo = 7;
    hi = 10;
    assert(math::range_sum::range_total(lo, hi) == 123);
    std::cout << "Range-sum check 4 passed!" << std::endl;

    lo = 9;
    hi = 12;
    assert(math::range_sum::range_total(lo, hi) == 322);
    std::cout << "Range-sum check 5 passed!" << std::endl;
}

/**
 * @brief Program entry point.
 */
int main() {
    run_range_sum_checks();
    return 0;
}

/**
 * @author [aminos 🇮🇳](https://github.com/amino19)
 * @file
 *
 * @brief [Program to count digits
 * in an
 * integer](https://www.geeksforgeeks.org/program-count-digits-integer-3-different-methods)
 * @details It is a very basic math of finding number of digits in a given
 * number i.e, we can use it by inputting values whether it can be a
 * positive/negative value, let's say: an integer. There is also a second
 * method: by using "K = floor(log10(N) + 1)", but it's only applicable for
 * numbers (not integers). The code for that is also included
 * (finding_number_of_digits_in_a_number_using_log). For more details, refer to
 * the
 * [Algorithms-Explanation](https://github.com/TheAlgorithms/Algorithms-Explanation/blob/master/en/Basic%20Math/Finding
 * the number of digits in a number.md) repository.
 */

#include <cassert>   /// for assert
#include <cmath>     /// for log calculation
#include <cstdint>
#include <iostream>  /// for IO operations

/**
 * @brief The main function that checks
 * the number of digits in a number.
 * TC : O(number of digits)
 * @param n the number to check its digits
 * @returns the digits count
 */
uint64_t finding_number_of_digits_in_a_number(uint64_t n) {
    uint64_t count = 0;  ///< the variable used for the digits count

    // iterate until `n` becomes 0
    // remove last digit from `n` in each iteration
    // increase `count` by 1 in each iteration
    while (n != 0) {
        // we can also use `n = n / 10`
        n /= 10;
        // each time the loop is running, `count` will be incremented by 1.
        ++count;
    }

    return count;
}

/**
 * @brief This function finds the number of digits
 * in constant time using logarithmic function
 * TC: O(1)
 * @param n the number to check its digits
 * @returns the digits count
 */
double finding_number_of_digits_in_a_number_using_log(double n) {
    // log(0) is undefined
    if (n == 0) {
        return 0;
    }

    // to handle the negative numbers
    if (n < 0) {
        n = -n;
    }

    double count = floor(log10(n) + 1);

    return count;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void first_test() {
    assert(finding_number_of_digits_in_a_number(5492) == 4);
    assert(finding_number_of_digits_in_a_number(-0) == 0);
    assert(finding_number_of_digits_in_a_number(10000) == 5);
    assert(finding_number_of_digits_in_a_number(9) == 1);
    assert(finding_number_of_digits_in_a_number(100000) == 6);
    assert(finding_number_of_digits_in_a_number(13) == 2);
    assert(finding_number_of_digits_in_a_number(564) == 3);
}

static void second_test() {
    assert(finding_number_of_digits_in_a_number_using_log(5492) == 4);
    assert(finding_number_of_digits_in_a_number_using_log(-0) == 0);
    assert(finding_number_of_digits_in_a_number_using_log(10000) == 5);
    assert(finding_number_of_digits_in_a_number_using_log(9) == 1);
    assert(finding_number_of_digits_in_a_number_using_log(100000) == 6);
    assert(finding_number_of_digits_in_a_number_using_log(13) == 2);
    assert(finding_number_of_digits_in_a_number_using_log(564) == 3);
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // run self-test implementations
    first_test();
    second_test();
    std::cout << "All tests have successfully passed!\n";
    return 0;
}

/**
 * @file
 *
 * @brief Counts how many decimal digits a number has, using two different
 * strategies: iterative division and a logarithm-based shortcut.
 * @details The iterative approach repeatedly strips the last digit until
 * nothing remains, counting each step. The logarithmic approach instead
 * uses floor(log10(n)) + 1, which works in constant time for non-integer
 * inputs too.
 *
 * Rewritten variant for dataset generation - same two algorithms, renamed
 * functions and reworded test harness.
 */

#include <cassert>
#include <cmath>
#include <cstdint>
#include <iostream>

/**
 * @brief Count digits by repeatedly dividing by 10.
 * Time complexity: O(number of digits)
 * @param value the number to inspect
 * @returns digit count
 */
uint64_t digitCountByDivision(uint64_t value) {
    uint64_t digits = 0;

    while (value != 0) {
        value /= 10;
        digits += 1;
    }

    return digits;
}

/**
 * @brief Count digits in constant time using base-10 logarithms.
 * Time complexity: O(1)
 * @param value the number to inspect (may be fractional or negative)
 * @returns digit count
 */
double digitCountByLog(double value) {
    if (value == 0) {
        return 0;  // log10(0) is undefined
    }

    if (value < 0) {
        value = -value;  // sign doesn't affect digit count
    }

    return std::floor(std::log10(value) + 1);
}

/// Verify the division-based counter against known digit counts.
static void checkDivisionApproach() {
    assert(digitCountByDivision(5492) == 4);
    assert(digitCountByDivision(-0) == 0);
    assert(digitCountByDivision(10000) == 5);
    assert(digitCountByDivision(9) == 1);
    assert(digitCountByDivision(100000) == 6);
    assert(digitCountByDivision(13) == 2);
    assert(digitCountByDivision(564) == 3);
}

/// Verify the logarithm-based counter against the same known digit counts.
static void checkLogApproach() {
    assert(digitCountByLog(5492) == 4);
    assert(digitCountByLog(-0) == 0);
    assert(digitCountByLog(10000) == 5);
    assert(digitCountByLog(9) == 1);
    assert(digitCountByLog(100000) == 6);
    assert(digitCountByLog(13) == 2);
    assert(digitCountByLog(564) == 3);
}

int main() {
    checkDivisionApproach();
    checkLogApproach();
    std::cout << "Every check completed without issue!\n";
    return 0;
}

/**
 * @file
 * @brief Compute the greatest common denominator of two integers using
 * *iterative form* of
 * [Euclidean algorithm](https://en.wikipedia.org/wiki/Euclidean_algorithm)
 *
 * @see gcd_recursive_euclidean.cpp, gcd_of_n_numbers.cpp
 */
#include <iostream>
#include <stdexcept>

/**
 * algorithm
 */
int gcd(int num1, int num2) {
    if (num1 <= 0 | num2 <= 0) {
        throw std::domain_error("Euclidean algorithm domain is for ints > 0");
    }

    if (num1 == num2) {
        return num1;
    }

    int base_num = 0;
    int previous_remainder = 1;

    if (num1 > num2) {
        base_num = num1;
        previous_remainder = num2;
    } else {
        base_num = num2;
        previous_remainder = num1;
    }

    while ((base_num % previous_remainder) != 0) {
        int old_base = base_num;
        base_num = previous_remainder;
        previous_remainder = old_base % previous_remainder;
    }

    return previous_remainder;
}

/**
 * Main function
 */
int main() {
    std::cout << "gcd of 120,7 is " << (gcd(120, 7)) << std::endl;
    try {
        std::cout << "gcd of -120,10 is " << gcd(-120, 10) << std::endl;
    } catch (const std::domain_error &e) {
        std::cout << "Error handling was successful" << std::endl;
    }
    std::cout << "gcd of 312,221 is " << (gcd(312, 221)) << std::endl;
    std::cout << "gcd of 289,204 is " << (gcd(289, 204)) << std::endl;

    return 0;
}

/**
 * @file
 * @brief Computes the greatest common divisor of two positive integers using
 * the *iterative* Euclidean algorithm (successive remainder reduction).
 *
 * @see gcd_recursive_euclidean.cpp, gcd_of_n_numbers.cpp
 *
 * Rewritten variant for dataset generation - same algorithm, renamed
 * variables and reworded comments.
 */
#include <iostream>
#include <stdexcept>

/// Compute gcd(num1, num2) iteratively; both inputs must be positive.
int computeGcd(int num1, int num2) {
    if (num1 <= 0 || num2 <= 0) {
        throw std::domain_error("Euclidean algorithm domain is for ints > 0");
    }

    if (num1 == num2) {
        return num1;
    }

    // Work with (larger, smaller) so the modulo loop below always shrinks.
    int larger = (num1 > num2) ? num1 : num2;
    int smaller = (num1 > num2) ? num2 : num1;

    while ((larger % smaller) != 0) {
        int temp = larger;
        larger = smaller;
        smaller = temp % smaller;
    }

    return smaller;
}

int main() {
    std::cout << "gcd of 120,7 is " << computeGcd(120, 7) << std::endl;
    try {
        std::cout << "gcd of -120,10 is " << computeGcd(-120, 10) << std::endl;
    } catch (const std::domain_error &e) {
        std::cout << "Error handling was successful" << std::endl;
    }
    std::cout << "gcd of 312,221 is " << computeGcd(312, 221) << std::endl;
    std::cout << "gcd of 289,204 is " << computeGcd(289, 204) << std::endl;

    return 0;
}

/**
 * @file
 * @brief This program aims at calculating the GCD of n numbers
 *
 * @details
 * The GCD of n numbers can be calculated by
 * repeatedly calculating the GCDs of pairs of numbers
 * i.e. \f$\gcd(a, b, c)\f$ = \f$\gcd(\gcd(a, b), c)\f$
 * Euclidean algorithm helps calculate the GCD of each pair of numbers
 * efficiently
 *
 * @see gcd_iterative_euclidean.cpp, gcd_recursive_euclidean.cpp
 */
#include <algorithm> /// for std::abs
#include <array>     /// for std::array
#include <cassert>   /// for assert
#include <iostream>  /// for IO operations

/**
 * @namespace math
 * @brief Maths algorithms
 */
namespace math {
/**
 * @namespace gcd_of_n_numbers
 * @brief Compute GCD of numbers in an array
 */
namespace gcd_of_n_numbers {
/**
 * @brief Function to compute GCD of 2 numbers x and y
 * @param x First number
 * @param y Second number
 * @return GCD of x and y via recursion
 */
int gcd_two(int x, int y) {
  // base cases
  if (y == 0) {
    return x;
  }
  if (x == 0) {
    return y;
  }
  return gcd_two(y, x % y); // Euclidean method
}

/**
 * @brief Function to check if all elements in the array are 0
 * @param a Array of numbers
 * @return 'True' if all elements are 0
 * @return 'False' if not all elements are 0
 */
template <std::size_t n>
bool check_all_zeros(const std::array<int, n> &a) {
  // Use std::all_of to simplify zero-checking
  return std::all_of(a.begin(), a.end(), [](int x) { return x == 0; });
}

/**
 * @brief Main program to compute GCD using the Euclidean algorithm
 * @param a Array of integers to compute GCD for
 * @return GCD of the numbers in the array or std::nullopt if undefined
 */
template <std::size_t n>
int gcd(const std::array<int, n> &a) {
  // GCD is undefined if all elements in the array are 0
  if (check_all_zeros(a)) {
    return -1; // Use std::optional to represent undefined GCD
  }

  // divisors can be negative, we only want the positive value
  int result = std::abs(a[0]);
  for (std::size_t i = 1; i < n; ++i) {
    result = gcd_two(result, std::abs(a[i]));
    if (result == 1) {
      break; // Further computations still result in gcd of 1
    }
  }
  return result;
}
} // namespace gcd_of_n_numbers
} // namespace math

/**
 * @brief Self-test implementation
 * @return void
 */
static void test() {
  std::array<int, 1> array_1 = {0};
  std::array<int, 1> array_2 = {1};
  std::array<int, 2> array_3 = {0, 2};
  std::array<int, 3> array_4 = {-60, 24, 18};
  std::array<int, 4> array_5 = {100, -100, -100, 200};
  std::array<int, 5> array_6 = {0, 0, 0, 0, 0};
  std::array<int, 7> array_7 = {10350, -24150, 0, 17250, 37950, -127650, 51750};
  std::array<int, 7> array_8 = {9500000, -12121200, 0, 4444, 0, 0, 123456789};

  assert(math::gcd_of_n_numbers::gcd(array_1) == -1);
  assert(math::gcd_of_n_numbers::gcd(array_2) == 1);
  assert(math::gcd_of_n_numbers::gcd(array_3) == 2);
  assert(math::gcd_of_n_numbers::gcd(array_4) == 6);
  assert(math::gcd_of_n_numbers::gcd(array_5) == 100);
  assert(math::gcd_of_n_numbers::gcd(array_6) == -1);
  assert(math::gcd_of_n_numbers::gcd(array_7) == 3450);
  assert(math::gcd_of_n_numbers::gcd(array_8) == 1);
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
  test(); // run self-test implementation
  return 0;
}

/**
 * @file
 * @brief Computes the GCD across an entire array of integers.
 *
 * @details
 * The GCD of a list of numbers can be found by folding the pairwise GCD
 * across the list: gcd(a, b, c) = gcd(gcd(a, b), c). Each pairwise GCD is
 * found with the Euclidean algorithm.
 *
 * @see gcd_iterative_euclidean.cpp, gcd_recursive_euclidean.cpp
 *
 * Rewritten variant for dataset generation - same algorithm, renamed
 * namespaces/functions and reworded comments.
 */
#include <algorithm>
#include <array>
#include <cassert>
#include <iostream>

/**
 * @namespace math
 * @brief Maths algorithms
 */
namespace math {
/**
 * @namespace multi_gcd
 * @brief Compute the GCD across a collection of integers
 */
namespace multi_gcd {

/**
 * @brief Recursive Euclidean GCD for a pair of numbers.
 * @param a first number
 * @param b second number
 * @return gcd(a, b)
 */
int pairwiseGcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    if (a == 0) {
        return b;
    }
    return pairwiseGcd(b, a % b);
}

/**
 * @brief Determine whether every element of the array is zero.
 * @param values array to inspect
 * @return true when every entry is zero
 */
template <std::size_t n>
bool allZero(const std::array<int, n> &values) {
    return std::all_of(values.begin(), values.end(),
                        [](int v) { return v == 0; });
}

/**
 * @brief Fold the Euclidean algorithm across an array to find its overall
 * GCD.
 * @param values array of integers
 * @return the GCD, or -1 if every element is zero (GCD undefined)
 */
template <std::size_t n>
int gcdOfArray(const std::array<int, n> &values) {
    if (allZero(values)) {
        return -1;  // GCD is undefined when everything is zero
    }

    int running = std::abs(values[0]);
    for (std::size_t i = 1; i < n; ++i) {
        running = pairwiseGcd(running, std::abs(values[i]));
        if (running == 1) {
            break;  // cannot go any lower than 1
        }
    }
    return running;
}

}  // namespace multi_gcd
}  // namespace math

/// Verify gcdOfArray against a range of fixed-size test arrays.
static void runSelfChecks() {
    std::array<int, 1> case1 = {0};
    std::array<int, 1> case2 = {1};
    std::array<int, 2> case3 = {0, 2};
    std::array<int, 3> case4 = {-60, 24, 18};
    std::array<int, 4> case5 = {100, -100, -100, 200};
    std::array<int, 5> case6 = {0, 0, 0, 0, 0};
    std::array<int, 7> case7 = {10350, -24150, 0, 17250, 37950, -127650, 51750};
    std::array<int, 7> case8 = {9500000, -12121200, 0, 4444, 0, 0, 123456789};

    assert(math::multi_gcd::gcdOfArray(case1) == -1);
    assert(math::multi_gcd::gcdOfArray(case2) == 1);
    assert(math::multi_gcd::gcdOfArray(case3) == 2);
    assert(math::multi_gcd::gcdOfArray(case4) == 6);
    assert(math::multi_gcd::gcdOfArray(case5) == 100);
    assert(math::multi_gcd::gcdOfArray(case6) == -1);
    assert(math::multi_gcd::gcdOfArray(case7) == 3450);
    assert(math::multi_gcd::gcdOfArray(case8) == 1);
}

int main() {
    runSelfChecks();
    return 0;
}

/**
 * @file
 * @brief Compute the greatest common denominator of two integers using
 * *recursive form* of
 * [Euclidean algorithm](https://en.wikipedia.org/wiki/Euclidean_algorithm)
 *
 * @see gcd_iterative_euclidean.cpp, gcd_of_n_numbers.cpp
 */
#include <iostream>

/**
 * algorithm
 */
int gcd(int num1, int num2) {
    if (num1 <= 0 | num2 <= 0) {
        throw std::domain_error("Euclidean algorithm domain is for ints > 0");
    }

    if (num1 == num2) {
        return num1;
    }

    // Everything divides 0
    if (num1 == 0)
        return num2;
    if (num2 == 0)
        return num1;

    // base case
    if (num1 == num2)
        return num1;

    // a is greater
    if (num1 > num2)
        return gcd(num1 - num2, num2);
    return gcd(num1, num2 - num1);
}

/**
 * Main function
 */
int main() {
    std::cout << "gcd of 120,7 is " << (gcd(120, 7)) << std::endl;
    try {
        std::cout << "gcd of -120,10 is " << gcd(-120, 10) << std::endl;
    } catch (const std::domain_error &e) {
        std::cout << "Error handling was successful" << std::endl;
    }
    std::cout << "gcd of 312,221 is " << (gcd(312, 221)) << std::endl;
    std::cout << "gcd of 289,204 is " << (gcd(289, 204)) << std::endl;
    return 0;
}

/**
 * @file
 * @brief Computes the greatest common divisor of two positive integers using
 * the *recursive* Euclidean algorithm (subtraction-based variant).
 *
 * @see gcd_iterative_euclidean.cpp, gcd_of_n_numbers.cpp
 *
 * Rewritten variant for dataset generation - same algorithm, renamed
 * function and reworded comments.
 */
#include <iostream>

/// Recursively compute gcd(num1, num2) by repeated subtraction; both inputs
/// must be positive.
int computeGcd(int num1, int num2) {
    if (num1 <= 0 || num2 <= 0) {
        throw std::domain_error("Euclidean algorithm domain is for ints > 0");
    }

    if (num1 == num2) {
        return num1;
    }

    // Zero is a divisor of everything.
    if (num1 == 0) return num2;
    if (num2 == 0) return num1;

    // Reduce the larger value by the smaller one and recurse.
    if (num1 > num2) {
        return computeGcd(num1 - num2, num2);
    }
    return computeGcd(num1, num2 - num1);
}

int main() {
    std::cout << "gcd of 120,7 is " << computeGcd(120, 7) << std::endl;
    try {
        std::cout << "gcd of -120,10 is " << computeGcd(-120, 10) << std::endl;
    } catch (const std::domain_error &e) {
        std::cout << "Error handling was successful" << std::endl;
    }
    std::cout << "gcd of 312,221 is " << computeGcd(312, 221) << std::endl;
    std::cout << "gcd of 289,204 is " << computeGcd(289, 204) << std::endl;
    return 0;
}

/**
 * @file
 * @brief Compute integral approximation of the function using [Riemann
 * sum](https://en.wikipedia.org/wiki/Riemann_sum)
 * @details In mathematics, a Riemann sum is a certain kind of approximation of
 * an integral by a finite sum. It is named after nineteenth-century German
 * mathematician Bernhard Riemann. One very common application is approximating
 * the area of functions or lines on a graph and the length of curves and other
 * approximations. The sum is calculated by partitioning the region into shapes
 * (rectangles, trapezoids, parabolas, or cubics) that form a region similar to
 * the region being measured, then calculating the area for each of these
 * shapes, and finally adding all of these small areas together. This approach
 * can be used to find a numerical approximation for a definite integral even if
 * the fundamental theorem of calculus does not make it easy to find a
 * closed-form solution. Because the region filled by the small shapes is
 * usually not the same shape as the region being measured, the Riemann sum will
 * differ from the area being measured. This error can be reduced by dividing up
 * the region more finely, using smaller and smaller shapes. As the shapes get
 * smaller and smaller, the sum approaches the Riemann integral. \author
 * [Benjamin Walton](https://github.com/bwalton24) \author [Shiqi
 * Sheng](https://github.com/shiqisheng00)
 */
#include <cassert>     /// for assert
#include <cmath>       /// for mathematical functions
#include <cstdint>
#include <functional>  /// for passing in functions
#include <iostream>    /// for IO operations

/**
 * @namespace math
 * @brief Mathematical functions
 */
namespace math {
/**
 * @brief Computes integral approximation
 * @param lb lower bound
 * @param ub upper bound
 * @param func function passed in
 * @param delta
 * @returns integral approximation of function from [lb, ub]
 */
double integral_approx(double lb, double ub,
                       const std::function<double(double)>& func,
                       double delta = .0001) {
    double result = 0;
    uint64_t numDeltas = static_cast<uint64_t>((ub - lb) / delta);
    for (int i = 0; i < numDeltas; i++) {
        double begin = lb + i * delta;
        double end = lb + (i + 1) * delta;
        result += delta * (func(begin) + func(end)) / 2;
    }
    return result;
}

/**
 * @brief Wrapper to evaluate if the approximated
 * value is within `.XX%` threshold of the exact value.
 * @param approx aprroximate value
 * @param exact expected value
 * @param threshold values from [0, 1)
 */
void test_eval(double approx, double expected, double threshold) {
    assert(approx >= expected * (1 - threshold));
    assert(approx <= expected * (1 + threshold));
}

/**
 * @brief Self-test implementations to
 * test the `integral_approx` function.
 *
 * @returns `void`
 */
}  // namespace math

static void test() {
    double test_1 = math::integral_approx(
        3.24, 7.56, [](const double x) { return log(x) + exp(x) + x; });
    std::cout << "Test Case 1" << std::endl;
    std::cout << "function: log(x) + e^x + x" << std::endl;
    std::cout << "range: [3.24, 7.56]" << std::endl;
    std::cout << "value: " << test_1 << std::endl;
    math::test_eval(test_1, 1924.80384023549, .001);
    std::cout << "Test 1 Passed!" << std::endl;
    std::cout << "=====================" << std::endl;

    double test_2 = math::integral_approx(0.023, 3.69, [](const double x) {
        return x * x + cos(x) + exp(x) + log(x) * log(x);
    });
    std::cout << "Test Case 2" << std::endl;
    std::cout << "function: x^2 + cos(x) + e^x + log^2(x)" << std::endl;
    std::cout << "range: [.023, 3.69]" << std::endl;
    std::cout << "value: " << test_2 << std::endl;
    math::test_eval(test_2, 58.71291345202729, .001);
    std::cout << "Test 2 Passed!" << std::endl;
    std::cout << "=====================" << std::endl;

    double test_3 = math::integral_approx(
        10.78, 24.899, [](const double x) { return x * x * x - x * x + 378; });
    std::cout << "Test Case 3" << std::endl;
    std::cout << "function: x^3 - x^2 + 378" << std::endl;
    std::cout << "range: [10.78, 24.899]" << std::endl;
    std::cout << "value: " << test_3 << std::endl;
    math::test_eval(test_3, 93320.65915078377, .001);
    std::cout << "Test 3 Passed!" << std::endl;
    std::cout << "=====================" << std::endl;

    double test_4 = math::integral_approx(
        .101, .505,
        [](const double x) { return cos(x) * tan(x) * x * x + exp(x); },
        .00001);
    std::cout << "Test Case 4" << std::endl;
    std::cout << "function: cos(x)*tan(x)*x^2 + e^x" << std::endl;
    std::cout << "range: [.101, .505]" << std::endl;
    std::cout << "value: " << test_4 << std::endl;
    math::test_eval(test_4, 0.566485986311631, .001);
    std::cout << "Test 4 Passed!" << std::endl;
    std::cout << "=====================" << std::endl;

    double test_5 = math::integral_approx(
        -1, 1, [](const double x) { return exp(-1 / (x * x)); });
    std::cout << "Test Case 5" << std::endl;
    std::cout << "function: e^(-1/x^2)" << std::endl;
    std::cout << "range: [-1, 1]" << std::endl;
    std::cout << "value: " << test_5 << std::endl;
    math::test_eval(test_5, 0.1781477117815607, .001);
    std::cout << "Test 5 Passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Numerically estimates a definite integral using the trapezoid
 * rule (a discretized Riemann-sum style approach).
 * @details Instead of solving an integral analytically, we slice the
 * interval [a, b] into many narrow strips of width `step`, treat each
 * strip as a trapezoid whose parallel sides are f(x_i) and f(x_i+step),
 * and sum up all of those trapezoid areas. As `step` shrinks, the sum
 * converges toward the true value of the integral. This is essentially
 * the same idea behind the Riemann sum, just applying the trapezoidal
 * rather than purely rectangular approximation.
 */
#include <cassert>     // assert macro
#include <cmath>       // log, exp, cos, tan
#include <cstdint>     // fixed width integers
#include <functional>  // std::function
#include <iostream>    // console output

/**
 * @namespace numeric_methods
 * @brief Helper routines for numerical approximation
 */
namespace numeric_methods {

/**
 * @brief Approximates the definite integral of `fn` on [a, b] using the
 * trapezoidal rule.
 * @param a lower bound of integration
 * @param b upper bound of integration
 * @param fn the callable to integrate
 * @param step width of each trapezoid slice (smaller = more accurate)
 * @return the estimated area under the curve
 */
double trapezoid_integral(double a, double b,
                           const std::function<double(double)>& fn,
                           double step = .0001) {
    double accumulated_area = 0;
    uint64_t slice_count = static_cast<uint64_t>((b - a) / step);
    for (uint64_t idx = 0; idx < slice_count; ++idx) {
        double left_x = a + idx * step;
        double right_x = a + (idx + 1) * step;
        accumulated_area += step * (fn(left_x) + fn(right_x)) / 2;
    }
    return accumulated_area;
}

/**
 * @brief Checks whether an estimated value lies within a relative
 * tolerance band of the expected (analytical) value.
 * @param estimate the value produced by trapezoid_integral
 * @param reference the known correct value
 * @param tolerance fractional tolerance, e.g. .001 for 0.1%
 */
void assert_within_tolerance(double estimate, double reference,
                              double tolerance) {
    assert(estimate >= reference * (1 - tolerance));
    assert(estimate <= reference * (1 + tolerance));
}

}  // namespace numeric_methods

/**
 * @brief Runs a handful of hand-checked cases against known closed-form
 * results to make sure the trapezoid rule implementation is sound.
 */
static void run_checks() {
    double case_a = numeric_methods::trapezoid_integral(
        3.24, 7.56, [](const double x) { return log(x) + exp(x) + x; });
    std::cout << "Check A" << std::endl;
    std::cout << "f(x) = log(x) + e^x + x" << std::endl;
    std::cout << "interval: [3.24, 7.56]" << std::endl;
    std::cout << "estimate: " << case_a << std::endl;
    numeric_methods::assert_within_tolerance(case_a, 1924.80384023549, .001);
    std::cout << "Check A OK" << std::endl;
    std::cout << "---------------------" << std::endl;

    double case_b = numeric_methods::trapezoid_integral(
        0.023, 3.69, [](const double x) {
            return x * x + cos(x) + exp(x) + log(x) * log(x);
        });
    std::cout << "Check B" << std::endl;
    std::cout << "f(x) = x^2 + cos(x) + e^x + log^2(x)" << std::endl;
    std::cout << "interval: [.023, 3.69]" << std::endl;
    std::cout << "estimate: " << case_b << std::endl;
    numeric_methods::assert_within_tolerance(case_b, 58.71291345202729, .001);
    std::cout << "Check B OK" << std::endl;
    std::cout << "---------------------" << std::endl;

    double case_c = numeric_methods::trapezoid_integral(
        10.78, 24.899,
        [](const double x) { return x * x * x - x * x + 378; });
    std::cout << "Check C" << std::endl;
    std::cout << "f(x) = x^3 - x^2 + 378" << std::endl;
    std::cout << "interval: [10.78, 24.899]" << std::endl;
    std::cout << "estimate: " << case_c << std::endl;
    numeric_methods::assert_within_tolerance(case_c, 93320.65915078377, .001);
    std::cout << "Check C OK" << std::endl;
    std::cout << "---------------------" << std::endl;

    double case_d = numeric_methods::trapezoid_integral(
        .101, .505,
        [](const double x) { return cos(x) * tan(x) * x * x + exp(x); },
        .00001);
    std::cout << "Check D" << std::endl;
    std::cout << "f(x) = cos(x)*tan(x)*x^2 + e^x" << std::endl;
    std::cout << "interval: [.101, .505]" << std::endl;
    std::cout << "estimate: " << case_d << std::endl;
    numeric_methods::assert_within_tolerance(case_d, 0.566485986311631, .001);
    std::cout << "Check D OK" << std::endl;
    std::cout << "---------------------" << std::endl;

    double case_e = numeric_methods::trapezoid_integral(
        -1, 1, [](const double x) { return exp(-1 / (x * x)); });
    std::cout << "Check E" << std::endl;
    std::cout << "f(x) = e^(-1/x^2)" << std::endl;
    std::cout << "interval: [-1, 1]" << std::endl;
    std::cout << "estimate: " << case_e << std::endl;
    numeric_methods::assert_within_tolerance(case_e, 0.1781477117815607, .001);
    std::cout << "Check E OK" << std::endl;
}

/**
 * @brief Program entry point.
 */
int main() {
    run_checks();
    return 0;
}

/**
 * @file
 * @brief [Monte Carlo
 * Integration](https://en.wikipedia.org/wiki/Monte_Carlo_integration)
 *
 * @details
 * In mathematics, Monte Carlo integration is a technique for numerical
 * integration using random numbers. It is a particular Monte Carlo method that
 * numerically computes a definite integral. While other algorithms usually
 * evaluate the integrand at a regular grid, Monte Carlo randomly chooses points
 * at which the integrand is evaluated. This method is particularly useful for
 * higher-dimensional integrals.
 *
 * This implementation supports arbitrary pdfs.
 * These pdfs are sampled using the [Metropolis-Hastings
 * algorithm](https://en.wikipedia.org/wiki/Metropolis–Hastings_algorithm). This
 * can be swapped out by every other sampling techniques for example the inverse
 * method. Metropolis-Hastings was chosen because it is the most general and can
 * also be extended for a higher dimensional sampling space.
 *
 * @author [Domenic Zingsheim](https://github.com/DerAndereDomenic)
 */

#define _USE_MATH_DEFINES  /// for M_PI on windows
#include <cmath>           /// for math functions
#include <cstdint>         /// for fixed size data types
#include <ctime>           /// for time to initialize rng
#include <functional>      /// for function pointers
#include <iostream>        /// for std::cout
#include <random>          /// for random number generation
#include <vector>          /// for std::vector

/**
 * @namespace math
 * @brief Math algorithms
 */
namespace math {
/**
 * @namespace monte_carlo
 * @brief Functions for the [Monte Carlo
 * Integration](https://en.wikipedia.org/wiki/Monte_Carlo_integration)
 * implementation
 */
namespace monte_carlo {

using Function = std::function<double(
    double&)>;  /// short-hand for std::functions used in this implementation

/**
 * @brief Generate samples according to some pdf
 * @details This function uses Metropolis-Hastings to generate random numbers.
 * It generates a sequence of random numbers by using a markov chain. Therefore,
 * we need to define a start_point and the number of samples we want to
 * generate. Because the first samples generated by the markov chain may not be
 * distributed according to the given pdf, one can specify how many samples
 * should be discarded before storing samples.
 * @param start_point The starting point of the markov chain
 * @param pdf The pdf to sample
 * @param num_samples The number of samples to generate
 * @param discard How many samples should be discarded at the start
 * @returns A vector of size num_samples with samples distributed according to
 * the pdf
 */
std::vector<double> generate_samples(const double& start_point,
                                     const Function& pdf,
                                     const uint32_t& num_samples,
                                     const uint32_t& discard = 100000) {
    std::vector<double> samples;
    samples.reserve(num_samples);

    double x_t = start_point;

    std::default_random_engine generator;
    std::uniform_real_distribution<double> uniform(0.0, 1.0);
    std::normal_distribution<double> normal(0.0, 1.0);
    generator.seed(time(nullptr));

    for (uint32_t t = 0; t < num_samples + discard; ++t) {
        // Generate a new proposal according to some mutation strategy.
        // This is arbitrary and can be swapped.
        double x_dash = normal(generator) + x_t;
        double acceptance_probability = std::min(pdf(x_dash) / pdf(x_t), 1.0);
        double u = uniform(generator);

        // Accept "new state" according to the acceptance_probability
        if (u <= acceptance_probability) {
            x_t = x_dash;
        }

        if (t >= discard) {
            samples.push_back(x_t);
        }
    }

    return samples;
}

/**
 * @brief Compute an approximation of an integral using Monte Carlo integration
 * @details The integration domain [a,b] is given by the pdf.
 * The pdf has to fulfill the following conditions:
 * 1) for all x \in [a,b] : p(x) > 0
 * 2) for all x \not\in [a,b] : p(x) = 0
 * 3) \int_a^b p(x) dx = 1
 * @param start_point The start point of the Markov Chain (see generate_samples)
 * @param function The function to integrate
 * @param pdf The pdf to sample
 * @param num_samples The number of samples used to approximate the integral
 * @returns The approximation of the integral according to 1/N \sum_{i}^N f(x_i)
 * / p(x_i)
 */
double integral_monte_carlo(const double& start_point, const Function& function,
                            const Function& pdf,
                            const uint32_t& num_samples = 1000000) {
    double integral = 0.0;
    std::vector<double> samples =
        generate_samples(start_point, pdf, num_samples);

    for (double sample : samples) {
        integral += function(sample) / pdf(sample);
    }

    return integral / static_cast<double>(samples.size());
}

}  // namespace monte_carlo
}  // namespace math

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    std::cout << "Disclaimer: Because this is a randomized algorithm,"
              << std::endl;
    std::cout
        << "it may happen that singular samples deviate from the true result."
        << std::endl
        << std::endl;
    ;

    math::monte_carlo::Function f;
    math::monte_carlo::Function pdf;
    double integral = 0;
    double lower_bound = 0, upper_bound = 0;

    /* \int_{-2}^{2} -x^2 + 4 dx */
    f = [&](double& x) { return -x * x + 4.0; };

    lower_bound = -2.0;
    upper_bound = 2.0;
    pdf = [&](double& x) {
        if (x >= lower_bound && x <= -1.0) {
            return 0.1;
        }
        if (x <= upper_bound && x >= 1.0) {
            return 0.1;
        }
        if (x > -1.0 && x < 1.0) {
            return 0.4;
        }
        return 0.0;
    };

    integral = math::monte_carlo::integral_monte_carlo(
        (upper_bound - lower_bound) / 2.0, f, pdf);

    std::cout << "This number should be close to 10.666666: " << integral
              << std::endl;

    /* \int_{0}^{1} e^x dx */
    f = [&](double& x) { return std::exp(x); };

    lower_bound = 0.0;
    upper_bound = 1.0;
    pdf = [&](double& x) {
        if (x >= lower_bound && x <= 0.2) {
            return 0.1;
        }
        if (x > 0.2 && x <= 0.4) {
            return 0.4;
        }
        if (x > 0.4 && x < upper_bound) {
            return 1.5;
        }
        return 0.0;
    };

    integral = math::monte_carlo::integral_monte_carlo(
        (upper_bound - lower_bound) / 2.0, f, pdf);

    std::cout << "This number should be close to 1.7182818: " << integral
              << std::endl;

    /* \int_{-\infty}^{\infty} sinc(x) dx, sinc(x) = sin(pi * x) / (pi * x)
       This is a difficult integral because of its infinite domain.
       Therefore, it may deviate largely from the expected result.
    */
    f = [&](double& x) { return std::sin(M_PI * x) / (M_PI * x); };

    pdf = [&](double& x) {
        return 1.0 / std::sqrt(2.0 * M_PI) * std::exp(-x * x / 2.0);
    };

    integral = math::monte_carlo::integral_monte_carlo(0.0, f, pdf, 10000000);

    std::cout << "This number should be close to 1.0: " << integral
              << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Estimates a definite integral via Monte Carlo sampling.
 * @details Rather than sampling the integrand on a fixed grid, this
 * approach draws random points from a probability density function
 * (pdf) covering the integration domain and averages f(x)/p(x) over
 * those draws. Because arbitrary pdfs are supported, we generate the
 * samples with a Metropolis-Hastings random walk (a Markov Chain Monte
 * Carlo technique). Any other sampler (e.g. inverse-CDF sampling) could
 * be substituted; Metropolis-Hastings was picked here because it
 * generalizes cleanly to higher dimensional sampling spaces.
 */

#define _USE_MATH_DEFINES  // needed for M_PI on some Windows toolchains
#include <cmath>           // exp, sin, sqrt
#include <cstdint>         // fixed width integers
#include <ctime>           // seed the RNG from wall clock
#include <functional>      // std::function
#include <iostream>        // std::cout
#include <random>          // distributions & engine
#include <vector>          // std::vector

/**
 * @namespace numeric_methods
 * @brief Numerical approximation helpers
 */
namespace numeric_methods {

/**
 * @namespace mcmc
 * @brief Monte Carlo integration built on a Metropolis-Hastings sampler
 */
namespace mcmc {

using RealFn = std::function<double(double&)>;

/**
 * @brief Draws a chain of samples distributed (approximately) according
 * to a target pdf using the Metropolis-Hastings algorithm.
 * @details A candidate state is proposed by perturbing the current
 * state with Gaussian noise; it is accepted with probability
 * min(1, p(candidate)/p(current)). Because early samples in the chain
 * haven't "forgotten" the arbitrary starting point yet, a burn-in
 * (`burn_in`) number of initial samples are thrown away.
 * @param seed_state where the Markov chain begins
 * @param density the target pdf to sample from
 * @param sample_count how many (post burn-in) samples to keep
 * @param burn_in how many initial samples to discard
 * @return vector of samples approximately distributed as `density`
 */
std::vector<double> draw_chain(const double& seed_state,
                                const RealFn& density,
                                const uint32_t& sample_count,
                                const uint32_t& burn_in = 100000) {
    std::vector<double> chain;
    chain.reserve(sample_count);

    double current_state = seed_state;

    std::default_random_engine rng;
    std::uniform_real_distribution<double> unit_uniform(0.0, 1.0);
    std::normal_distribution<double> proposal_noise(0.0, 1.0);
    rng.seed(time(nullptr));

    for (uint32_t step = 0; step < sample_count + burn_in; ++step) {
        // Propose a nearby candidate state. The proposal strategy is
        // arbitrary here and could be swapped for something smarter.
        double candidate_state = proposal_noise(rng) + current_state;
        double accept_prob =
            std::min(density(candidate_state) / density(current_state), 1.0);
        double roll = unit_uniform(rng);

        if (roll <= accept_prob) {
            current_state = candidate_state;
        }

        if (step >= burn_in) {
            chain.push_back(current_state);
        }
    }

    return chain;
}

/**
 * @brief Approximates \int f(x) dx over the support of `density` using
 * Monte Carlo integration.
 * @details The density must satisfy: positive over the domain, zero
 * outside it, and integrate to 1 over the domain.
 * @param seed_state starting point for the underlying Markov chain
 * @param target_fn the function being integrated
 * @param density the pdf used to draw samples
 * @param sample_count number of samples used in the estimate
 * @return estimate of the integral as mean(f(x_i)/p(x_i))
 */
double monte_carlo_estimate(const double& seed_state, const RealFn& target_fn,
                             const RealFn& density,
                             const uint32_t& sample_count = 1000000) {
    double running_total = 0.0;
    std::vector<double> chain = draw_chain(seed_state, density, sample_count);

    for (double x : chain) {
        running_total += target_fn(x) / density(x);
    }

    return running_total / static_cast<double>(chain.size());
}

}  // namespace mcmc
}  // namespace numeric_methods

/**
 * @brief Runs a few sanity-check integrals whose approximate answers
 * are known ahead of time.
 */
static void run_checks() {
    std::cout << "Note: this is a randomized method, so individual runs"
              << std::endl;
    std::cout << "can drift somewhat from the expected value." << std::endl
              << std::endl;

    numeric_methods::mcmc::RealFn target;
    numeric_methods::mcmc::RealFn density;
    double estimate = 0;
    double low = 0, high = 0;

    /* \int_{-2}^{2} -x^2 + 4 dx */
    target = [&](double& x) { return -x * x + 4.0; };

    low = -2.0;
    high = 2.0;
    density = [&](double& x) {
        if (x >= low && x <= -1.0) {
            return 0.1;
        }
        if (x <= high && x >= 1.0) {
            return 0.1;
        }
        if (x > -1.0 && x < 1.0) {
            return 0.4;
        }
        return 0.0;
    };

    estimate =
        numeric_methods::mcmc::monte_carlo_estimate((high - low) / 2.0, target, density);

    std::cout << "Should be close to 10.666666: " << estimate << std::endl;

    /* \int_{0}^{1} e^x dx */
    target = [&](double& x) { return std::exp(x); };

    low = 0.0;
    high = 1.0;
    density = [&](double& x) {
        if (x >= low && x <= 0.2) {
            return 0.1;
        }
        if (x > 0.2 && x <= 0.4) {
            return 0.4;
        }
        if (x > 0.4 && x < high) {
            return 1.5;
        }
        return 0.0;
    };

    estimate =
        numeric_methods::mcmc::monte_carlo_estimate((high - low) / 2.0, target, density);

    std::cout << "Should be close to 1.7182818: " << estimate << std::endl;

    /* \int_{-\infty}^{\infty} sinc(x) dx
       Infinite-domain integral, so expect more deviation. */
    target = [&](double& x) { return std::sin(M_PI * x) / (M_PI * x); };

    density = [&](double& x) {
        return 1.0 / std::sqrt(2.0 * M_PI) * std::exp(-x * x / 2.0);
    };

    estimate = numeric_methods::mcmc::monte_carlo_estimate(0.0, target, density, 10000000);

    std::cout << "Should be close to 1.0: " << estimate << std::endl;
}

/**
 * @brief Program entry point.
 */
int main() {
    run_checks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [the inverse square root
 * Root](https://medium.com/hard-mode/the-legendary-fast-inverse-square-root-e51fee3b49d9).
 * @details
 * Two implementation to calculate inverse inverse root,
 * from Quake III Arena (C++ version) and with a standard library (`cmath`).
 * This algorithm is used to calculate shadows in Quake III Arena.
 */

#include <cassert>   /// for assert
#include <cmath>     /// for `std::sqrt`
#include <cstdint>
#include <iostream>  /// for IO operations
#include <limits>    /// for numeric_limits
/**
 * @brief This is the function that calculates the fast inverse square root.
 * The following code is the fast inverse square root implementation from
 * Quake III Arena (Adapted for C++). More information can be found at
 * [Wikipedia](https://en.wikipedia.org/wiki/Fast_inverse_square_root)
 * @tparam T floating type
 * @tparam iterations inverse square root, the greater the number of
 * iterations, the more exact the result will be (1 or 2).
 * @param x value to calculate
 * @return the inverse square root
 */
template <typename T = double, char iterations = 2>
inline T Fast_InvSqrt(T x) {
    using Tint = typename std::conditional<sizeof(T) == 8, std::int64_t,
                                           std::int32_t>::type;
    T y = x;
    T x2 = y * 0.5;

    Tint i =
        *reinterpret_cast<Tint *>(&y);  // Store floating-point bits in integer

    i = (sizeof(T) == 8 ? 0x5fe6eb50c7b537a9 : 0x5f3759df) -
        (i >> 1);  // Initial guess for Newton's method

    y = *reinterpret_cast<T *>(&i);  // Convert new bits into float

    y = y * (1.5 - (x2 * y * y));  // 1st iteration Newton's method
    if (iterations == 2) {
        y = y * (1.5 - (x2 * y * y));  // 2nd iteration, the more exact result
    }
    return y;
}

/**
 * @brief This is the function that calculates the fast inverse square root.
 * The following code is the fast inverse square root with standard lib (cmath)
 * More information can be found at
 * [LinkedIn](https://www.linkedin.com/pulse/fast-inverse-square-root-still-armin-kassemi-langroodi)
 * @tparam T floating type
 * @param number value to calculate
 * @return the inverse square root
 */
template <typename T = double>
T Standard_InvSqrt(T number) {
    T squareRoot = sqrt(number);
    return 1.0f / squareRoot;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    const float epsilon = 1e-3f;

    /* Tests with multiple values */
    assert(std::fabs(Standard_InvSqrt<float>(100.0f) - 0.0998449f) < epsilon);
    assert(std::fabs(Standard_InvSqrt<double>(36.0f) - 0.166667f) < epsilon);
    assert(std::fabs(Standard_InvSqrt(12.0f) - 0.288423f) < epsilon);
    assert(std::fabs(Standard_InvSqrt<double>(5.0f) - 0.447141f) < epsilon);

    assert(std::fabs(Fast_InvSqrt<float, 1>(100.0f) - 0.0998449f) < epsilon);
    assert(std::fabs(Fast_InvSqrt<double, 1>(36.0f) - 0.166667f) < epsilon);
    assert(std::fabs(Fast_InvSqrt(12.0f) - 0.288423) < epsilon);
    assert(std::fabs(Fast_InvSqrt<double>(5.0f) - 0.447141) < epsilon);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    std::cout << "The Fast inverse square root of 36 is: "
              << Fast_InvSqrt<float, 1>(36.0f) << std::endl;
    std::cout << "The Fast inverse square root of 36 is: "
              << Fast_InvSqrt<double, 2>(36.0f) << " (2 iterations)"
              << std::endl;
    std::cout << "The Fast inverse square root of 100 is: "
              << Fast_InvSqrt(100.0f)
              << " (With default template type and iterations: double, 2)"
              << std::endl;
    std::cout << "The Standard inverse square root of 36 is: "
              << Standard_InvSqrt<float>(36.0f) << std::endl;
    std::cout << "The Standard inverse square root of 100 is: "
              << Standard_InvSqrt(100.0f)
              << " (With default template type: double)" << std::endl;
}

/**
 * @file
 * @brief Two ways to compute 1/sqrt(x): the classic Quake-style bit-hack
 * approximation, and the plain library-based version.
 * @details The "fast" version reinterprets the float's bit pattern as an
 * integer, does a magic-number subtraction to get a rough initial guess,
 * then refines that guess with one or two rounds of Newton's method.
 * This trick was famously used in Quake III Arena to speed up lighting
 * calculations.
 */

#include <cassert>   // assert
#include <cmath>     // std::sqrt
#include <cstdint>   // int32_t / int64_t
#include <iostream>  // console output
#include <limits>    // numeric_limits

/**
 * @brief Bit-hack approximation of 1/sqrt(x), following the well-known
 * Quake III Arena technique.
 * @tparam T floating point type used for the computation
 * @tparam refine_steps number of Newton refinement passes (1 or 2); more
 * passes give a more accurate result at extra cost
 * @param value the number to compute the inverse square root of
 * @return approximate value of 1/sqrt(value)
 */
template <typename T = double, char refine_steps = 2>
inline T quake_rsqrt(T value) {
    using IntEquiv = typename std::conditional<sizeof(T) == 8, std::int64_t,
                                                std::int32_t>::type;
    T working = value;
    T half_value = working * 0.5;

    // Reinterpret the float bits as an integer so we can manipulate them.
    IntEquiv bits = *reinterpret_cast<IntEquiv*>(&working);

    // Magic constant subtraction gives a surprisingly good initial guess.
    bits = (sizeof(T) == 8 ? 0x5fe6eb50c7b537a9 : 0x5f3759df) - (bits >> 1);

    working = *reinterpret_cast<T*>(&bits);  // reinterpret back as float

    working = working * (1.5 - (half_value * working * working));  // pass 1
    if (refine_steps == 2) {
        working = working * (1.5 - (half_value * working * working));  // pass 2
    }
    return working;
}

/**
 * @brief Plain, library-based computation of 1/sqrt(x) for comparison
 * against the bit-hack version.
 * @tparam T floating point type
 * @param value the number to compute the inverse square root of
 * @return exact (to floating point precision) value of 1/sqrt(value)
 */
template <typename T = double>
T library_rsqrt(T value) {
    T root = sqrt(value);
    return 1.0f / root;
}

/**
 * @brief Self-checks comparing both implementations against expected
 * numeric results within a small epsilon.
 */
static void run_self_checks() {
    const float epsilon = 1e-3f;

    assert(std::fabs(library_rsqrt<float>(100.0f) - 0.0998449f) < epsilon);
    assert(std::fabs(library_rsqrt<double>(36.0f) - 0.166667f) < epsilon);
    assert(std::fabs(library_rsqrt(12.0f) - 0.288423f) < epsilon);
    assert(std::fabs(library_rsqrt<double>(5.0f) - 0.447141f) < epsilon);

    assert(std::fabs(quake_rsqrt<float, 1>(100.0f) - 0.0998449f) < epsilon);
    assert(std::fabs(quake_rsqrt<double, 1>(36.0f) - 0.166667f) < epsilon);
    assert(std::fabs(quake_rsqrt(12.0f) - 0.288423) < epsilon);
    assert(std::fabs(quake_rsqrt<double>(5.0f) - 0.447141) < epsilon);
}

/**
 * @brief Program entry point. Runs checks then prints a few sample
 * computations for manual eyeballing.
 */
int main() {
    run_self_checks();
    std::cout << "quake_rsqrt(36) with 1 pass: "
              << quake_rsqrt<float, 1>(36.0f) << std::endl;
    std::cout << "quake_rsqrt(36) with 2 passes: "
              << quake_rsqrt<double, 2>(36.0f) << std::endl;
    std::cout << "quake_rsqrt(100) with defaults (double, 2 passes): "
              << quake_rsqrt(100.0f) << std::endl;
    std::cout << "library_rsqrt(36) as float: " << library_rsqrt<float>(36.0f)
              << std::endl;
    std::cout << "library_rsqrt(100) with default type (double): "
              << library_rsqrt(100.0f) << std::endl;
}

/**
 * @file
 * @brief Iterative implementation of
 * [Factorial](https://en.wikipedia.org/wiki/Factorial)
 *
 * @author [Renjian-buchai](https://github.com/Renjian-buchai)
 *
 * @details Calculates factorial iteratively.
 * \f[n! = n\times(n-1)\times(n-2)\times(n-3)\times\ldots\times3\times2\times1
 *       = n\times(n-1)!\f]
 * for example:
 * \f$4! = 4\times3! = 4\times3\times2\times1 = 24\f$
 *
 * @example
 *
 * 5! = 5 * 4 * 3 * 2 * 1
 *
 * Recursive implementation of factorial pseudocode:
 *
 * function factorial(n):
 *     if n == 1:
 *         return 1
 *     else:
 *         return factorial(n-1)
 *
 */

#include <cassert>    /// for assert
#include <cstdint>    /// for integral types
#include <exception>  /// for std::invalid_argument
#include <iostream>   /// for std::cout

/**
 * @namespace
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * @brief Calculates the factorial iteratively.
 * @param n Nth factorial.
 * @return Factorial.
 * @note 0! = 1.
 * @warning Maximum=20 because there are no 128-bit integers in C++. 21!
 * returns 1.419e+19, which is not 21! but (21! % UINT64_MAX).
 */
uint64_t iterativeFactorial(uint8_t n) {
    if (n > 20) {
        throw std::invalid_argument("Maximum n value is 20");
    }

    // 1 because it is the identity number of multiplication.
    uint64_t accumulator = 1;

    while (n > 1) {
        accumulator *= n;
        --n;
    }

    return accumulator;
}

}  // namespace math

/**
 * @brief Self-test implementations to test iterativeFactorial function.
 * @note There is 1 special case: 0! = 1.
 */
static void test() {
    // Special case test
    std::cout << "Exception case test \n"
                 "Input: 0 \n"
                 "Expected output: 1 \n\n";
    assert(math::iterativeFactorial(0) == 1);

