/**
 * @file
 * @brief Loop-based (non-recursive) computation of n factorial.
 * @details n! = n * (n-1) * (n-2) * ... * 2 * 1, computed here by
 * repeatedly multiplying an accumulator starting from 1 and counting
 * down to 1. Avoiding recursion sidesteps call-stack growth for larger
 * n, though the result still overflows a 64-bit unsigned integer for
 * n beyond 20.
 */

#include <cassert>    // assert
#include <cstdint>    // fixed-width integer types
#include <exception>  // std::invalid_argument
#include <iostream>   // std::cout

/**
 * @namespace factorial_ops
 * @brief Factorial-related routines
 */
namespace factorial_ops {

/**
 * @brief Computes n! using a simple counting-down loop.
 * @param n value to compute the factorial of
 * @return n! as an unsigned 64-bit integer
 * @note By convention 0! = 1.
 * @warning n must be <= 20: without 128-bit integers, 21! would
 * overflow a uint64_t and silently wrap around.
 */
uint64_t loop_factorial(uint8_t n) {
    if (n > 20) {
        throw std::invalid_argument("n must not exceed 20");
    }

    // Start at 1 since it's the multiplicative identity.
    uint64_t product = 1;

    while (n > 1) {
        product *= n;
        --n;
    }

    return product;
}

}  // namespace factorial_ops

/**
 * @brief Exercises loop_factorial across a spread of inputs, including
 * the 0! edge case and the overflow guard.
 */
static void run_tests() {
    std::cout << "Case: n = 0 (edge case)\n"
                 "expected: 1\n\n";
    assert(factorial_ops::loop_factorial(0) == 1);

    std::cout << "Case: n = 1 (base case)\n"
                 "expected: 1\n\n";
    assert(factorial_ops::loop_factorial(1) == 1);

    std::cout << "Case: n = 5\n"
                 "expected: 120\n\n";
    assert(factorial_ops::loop_factorial(5) == 120);

    std::cout << "Case: n = 10\n"
                 "expected: 3628800\n\n";
    assert(factorial_ops::loop_factorial(10) == 3628800);

    std::cout << "Case: n = 20 (largest supported)\n"
                 "expected: 2432902008176640000\n\n";
    assert(factorial_ops::loop_factorial(20) == 2432902008176640000);

    std::cout << "Case: n = 21 (should throw)\n";

    bool caught = false;
    try {
        factorial_ops::loop_factorial(21);
    } catch (const std::invalid_argument&) {
        caught = true;
    }
    assert(caught);

    std::cout << "All checks completed without failure.\n";
}

/**
 * @brief Program entry point.
 */
int main() {
    run_tests();
    return 0;
}

