/**
 * @file
 * @brief Formulas for the perimeter (boundary length) of assorted shapes.
 * @details Every shape below has a closed-form perimeter formula; these
 * templated helpers work with whatever numeric type the caller supplies
 * (int, float, double, ...).
 */
#define _USE_MATH_DEFINES
#include <cassert>   /// assert()
#include <cmath>     /// M_PI
#include <cstdint>   /// uint16_t
#include <iostream>  /// console IO

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {

/// Perimeter of a square: 4 times the side length.
template <typename T>
T square_boundary(T side) {
    return 4 * side;
}

/// Perimeter of a rectangle: twice the sum of its two side lengths.
template <typename T>
T rectangle_boundary(T length, T width) {
    return 2 * (length + width);
}

/// Perimeter of a triangle: the sum of its three side lengths.
template <typename T>
T triangle_boundary(T side_a, T side_b, T side_c) {
    return side_a + side_b + side_c;
}

/// Circumference of a circle: 2 * pi * radius.
template <typename T>
T circle_boundary(T radius) {
    return 2 * M_PI * radius;
}

/// Perimeter of a parallelogram: twice the sum of base and height sides.
template <typename T>
T parallelogram_boundary(T base, T slant_side) {
    return 2 * (base + slant_side);
}

/// Total edge length of a cube: 12 times one edge length.
template <typename T>
T cube_edge_total(T edge) {
    return 12 * edge;
}

/// Perimeter of a regular n-sided polygon: sides * edge length.
template <typename T>
T regular_polygon_boundary(T sides, T edge_length) {
    return sides * edge_length;
}

/// A simplified "surface perimeter" measure for a cylinder: 2r + 2h.
template <typename T>
T cylinder_boundary(T radius, T height) {
    return (2 * radius) + (2 * height);
}

}  // namespace math

namespace {

/**
 * @brief Prints a labeled test result and asserts it matches expectations.
 */
template <typename T>
void report(const char *shape_name, T expected, T actual) {
    std::cout << shape_name << std::endl;
    std::cout << "Expected: " << expected << std::endl;
    std::cout << "Got:      " << actual << std::endl;
    assert(actual == expected);
    std::cout << "PASSED" << std::endl << std::endl;
}

