/**
 * @file
 * @brief Determine whether an integer is an exact power of two.
 *
 * @details
 * A number that is a power of two has exactly one bit set in its binary
 * representation (e.g. 32 = 0b100000). Subtracting 1 from such a number
 * flips that single bit off and sets every lower bit on (31 = 0b011111).
 * ANDing the two together therefore always yields zero for powers of two,
 * and something non-zero otherwise.
 *
 * Example:
 *   40 -> 0b101000, 39 -> 0b100111, AND = 0b100000 (non-zero) -> not power of 2
 *   64 -> 0b1000000, 63 -> 0b0111111, AND = 0                -> power of 2
 *
 * This bit-trick approach runs in O(1), beating naive loops/recursion that
 * repeatedly divide by two.
 */

#include <cassert>   /// for runtime assertions in the self-checks
#include <iostream>  /// for console input/output

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * @brief Reports whether `value` is a power of two.
 * @param value the integer under test
 * @returns true when value is a power of two, false otherwise
 */
bool isExactPowerOfTwo(int value) {
    int bitwise_probe = value & (value - 1);
    return bitwise_probe == 0;
}

}  // namespace math

/**
 * @brief Runs a fixed battery of checks against isExactPowerOfTwo.
 */
static void runSelfChecks() {
    std::cout << "Checking 32 ...\n";
    assert(math::isExactPowerOfTwo(32));
    std::cout << "ok\n";

    std::cout << "Checking 5 ...\n";
    assert(!math::isExactPowerOfTwo(5));
    std::cout << "ok\n";

    std::cout << "Checking 232 ...\n";
    assert(!math::isExactPowerOfTwo(232));
    std::cout << "ok\n";

    std::cout << "\nEvery self-check passed.\n";
}

/**
 * @brief Interactive helper that asks the user for a number and reports on it.
 * Left in place for manual experimentation; not wired into main() by default.
 */
void promptAndClassify() {
    int candidate = 0;

    std::cout << "Give me an integer: " << std::endl;
    std::cin >> candidate;

    if (math::isExactPowerOfTwo(candidate)) {
        std::cout << candidate << " is a power of two.\n";
    } else {
        std::cout << candidate << " is NOT a power of two.\n";
    }
}

/** Program entry point. */
int main() {
    runSelfChecks();

    // Swap the comment to try interactive mode instead of the fixed checks.
    // promptAndClassify();

    return 0;
}

/**
 * @file
 * @brief Prime factorization of positive integers
 */
#include <algorithm>
#include <cstring>
#include <iostream>
#include <vector>

/** Declaring variables for maintaing prime numbers and to check whether a
 * number is prime or not
 */
bool isprime[1000006];

/** list of prime numbers */
std::vector<int> prime_numbers;

/** list of prime factor-pairs */
std::vector<std::pair<int, int>> factors;

/** Calculating prime number upto a given range
 */
void SieveOfEratosthenes(int N) {
    // initializes the array isprime
    memset(isprime, true, sizeof isprime);

    for (int i = 2; i <= N; i++) {
        if (isprime[i]) {
            for (int j = 2 * i; j <= N; j += i) isprime[j] = false;
        }
    }

    for (int i = 2; i <= N; i++) {
        if (isprime[i])
            prime_numbers.push_back(i);
    }
}

/** Prime factorization of a number */
void prime_factorization(int num) {
    int number = num;

    for (int i = 0; prime_numbers[i] <= num; i++) {
        int count = 0;

        // termination condition
        if (number == 1) {
            break;
        }

        while (number % prime_numbers[i] == 0) {
            count++;
            number = number / prime_numbers[i];
        }

        if (count)
            factors.push_back(std::make_pair(prime_numbers[i], count));
    }
}

/** Main program */
int main() {
    int num;
    std::cout << "\t\tComputes the prime factorization\n\n";
    std::cout << "Type in a number: ";
    std::cin >> num;

    SieveOfEratosthenes(num);

    prime_factorization(num);

    // Prime factors with their powers in the given number in new line
    for (auto it : factors) {
        std::cout << it.first << " " << it.second << std::endl;
    }

    return 0;
}

/**
 * @file
 * @brief Break a positive integer down into its prime factors and exponents.
 */
#include <algorithm>
#include <cstring>
#include <iostream>
#include <vector>

/// Flags used while sieving: flagged[i] stays true while i still looks prime.
bool flagged[1000006];

/// Primes discovered by the sieve, in ascending order.
std::vector<int> discoveredPrimes;

/// Resulting (prime, exponent) pairs for the factorized number.
std::vector<std::pair<int, int>> factorization;

/**
 * Populates discoveredPrimes with every prime up to and including `limit`
 * using a standard Sieve of Eratosthenes.
 */
void buildPrimeTable(int limit) {
    memset(flagged, true, sizeof flagged);

    for (int candidate = 2; candidate <= limit; ++candidate) {
        if (flagged[candidate]) {
            for (int multiple = candidate * 2; multiple <= limit; multiple += candidate) {
                flagged[multiple] = false;
            }
        }
    }

    for (int candidate = 2; candidate <= limit; ++candidate) {
        if (flagged[candidate]) {
            discoveredPrimes.push_back(candidate);
        }
    }
}

/**
 * Divides `target` down by each prime in discoveredPrimes, tallying how many
 * times each prime divides evenly, and records the (prime, count) pairs.
 */
void factorize(int target) {
    int remainder = target;

    for (size_t idx = 0; discoveredPrimes[idx] <= target; ++idx) {
        int exponent = 0;

        if (remainder == 1) {
            break;  // nothing left to factor
        }

        while (remainder % discoveredPrimes[idx] == 0) {
            ++exponent;
            remainder /= discoveredPrimes[idx];
        }

        if (exponent > 0) {
            factorization.emplace_back(discoveredPrimes[idx], exponent);
        }
    }
}

/** Program entry point. */
int main() {
    int target_number = 0;

    std::cout << "\t\tPrime factorization calculator\n\n";
    std::cout << "Type in a number: ";
    std::cin >> target_number;

    buildPrimeTable(target_number);
    factorize(target_number);

    for (const auto& factor_pair : factorization) {
        std::cout << factor_pair.first << " " << factor_pair.second << std::endl;
    }

    return 0;
}

/**
 * @file
 * @brief Get list of prime numbers
 * @see primes_up_to_billion.cpp sieve_of_eratosthenes.cpp
 */
#include <iostream>
#include <vector>

/** Generate an increasingly large number of primes
 * and store in a list
 */
std::vector<int> primes(size_t max) {
    std::vector<int> res;
    std::vector<bool> is_not_prime(max + 1, false);
    for (size_t i = 2; i <= max; i++) {
        if (!is_not_prime[i]) {
            res.emplace_back(i);
        }
        for (int p : res) {
            size_t k = i * p;
            if (k > max) {
                break;
            }
            is_not_prime[k] = true;
            if (i % p == 0) {
                break;
            }
        }
    }
    return res;
}

/** main function */
int main() {
    std::cout << "Calculate primes up to:\n>> ";
    int n = 0;
    std::cin >> n;
    std::vector<int> ans = primes(n);
    for (int p : ans) std::cout << p << ' ';
    std::cout << std::endl;
}

/**
 * @file
 * @brief Build the list of all primes up to a given bound.
 * @see primes_up_to_billion.cpp sieve_of_eratosthenes.cpp
 */
#include <iostream>
#include <vector>

/**
 * Incrementally builds the list of primes not exceeding `upperBound`.
 *
 * For each candidate value we walk the primes already found so far and mark
 * their multiples as composite; this lets us grow the sieve and the prime
 * list together in a single pass rather than pre-sizing a full sieve array.
 *
 * @param upperBound largest value to consider (inclusive)
 * @return vector of every prime <= upperBound, in increasing order
 */
std::vector<int> collectPrimesUpTo(size_t upperBound) {
    std::vector<int> foundPrimes;
    std::vector<bool> markedComposite(upperBound + 1, false);

    for (size_t candidate = 2; candidate <= upperBound; ++candidate) {
        if (!markedComposite[candidate]) {
            foundPrimes.emplace_back(static_cast<int>(candidate));
        }

        for (int knownPrime : foundPrimes) {
            size_t product = candidate * static_cast<size_t>(knownPrime);
            if (product > upperBound) {
                break;
            }
            markedComposite[product] = true;
            if (candidate % knownPrime == 0) {
                break;
            }
        }
    }

    return foundPrimes;
}

/** Program entry point: reads a bound and prints all primes up to it. */
int main() {
    std::cout << "Calculate primes up to:\n>> ";
    int limit = 0;
    std::cin >> limit;

    std::vector<int> primeList = collectPrimesUpTo(limit);
    for (int value : primeList) {
        std::cout << value << ' ';
    }
    std::cout << std::endl;
}

/**
 * @file
 * @brief Compute prime numbers upto 1 billion
 * @see prime_numbers.cpp sieve_of_eratosthenes.cpp
 */
#include <cstring>
#include <iostream>

/** array to store the primes */
char prime[100000000];

/** Perform Sieve algorithm */
void Sieve(int64_t n) {
    memset(prime, '1', sizeof(prime));  // intitize '1' to every index
    prime[0] = '0';                     // 0 is not prime
    prime[1] = '0';                     // 1 is not prime
    for (int64_t p = 2; p * p <= n; p++) {
        if (prime[p] == '1') {
            for (int64_t i = p * p; i <= n; i += p)
                prime[i] = '0';  // set all multiples of p to false
        }
    }
}

/** Main function */
int main() {
    Sieve(100000000);
    int64_t n;
    std::cin >> n;  // 10006187
    if (prime[n] == '1')
        std::cout << "YES\n";
    else
        std::cout << "NO\n";

    return 0;
}

/**
 * @file
 * @brief Precompute primality up to 100,000,000 and answer lookups.
 * @see prime_numbers.cpp sieve_of_eratosthenes.cpp
 *
 * The naive "sieve of Eratosthenes" scales to fairly large bounds if we
 * store one byte of state per candidate rather than doing anything fancier
 * (a true segmented sieve would trade memory for locality, but a flat
 * char table already comfortably covers the 10^8 range used here).
 */
#include <cstring>
#include <iostream>

/// One entry per candidate number: '1' means "still looks prime", '0' means composite.
char primeFlags[100000000];

/**
 * Runs a Sieve of Eratosthenes over [0, upperLimit], filling primeFlags so
 * that primeFlags[k] == '1' iff k is prime.
 *
 * @param upperLimit largest number to test (inclusive)
 */
void buildSieve(int64_t upperLimit) {
    memset(primeFlags, '1', sizeof(primeFlags));  // assume everyone is prime at first
    primeFlags[0] = '0';                          // 0 is excluded by definition
    primeFlags[1] = '0';                          // 1 is excluded by definition

    for (int64_t factor = 2; factor * factor <= upperLimit; ++factor) {
        if (primeFlags[factor] == '1') {
            for (int64_t multiple = factor * factor; multiple <= upperLimit; multiple += factor) {
                primeFlags[multiple] = '0';  // composite: divisible by `factor`
            }
        }
    }
}

/** Program entry point: builds the sieve once, then answers a single query. */
int main() {
    const int64_t kSieveBound = 100000000;
    buildSieve(kSieveBound);

    int64_t query = 0;
    std::cin >> query;  // e.g. 10006187

    if (primeFlags[query] == '1') {
        std::cout << "YES\n";
    } else {
        std::cout << "NO\n";
    }

    return 0;
}

/**
 * @file
 * @brief Calculate quadratic equation with complex roots, i.e. b^2 - 4ac < 0.
 *
 * @author [Renjian-buchai](https://github.com/Renjian-buchai)
 *
 * @description Calculates any quadratic equation in form ax^2 + bx + c.
 *
 * Quadratic equation:
 * x = (-b +/- sqrt(b^2 - 4ac)) / 2a
 *
 * @example
 * int main() {
 *   using std::array;
 *   using std::complex;
 *   using std::cout;
 *
 *   array<complex<long double, 2> solutions = quadraticEquation(1, 2, 1);
 *   cout << solutions[0] << " " << solutions[1] << "\n";
 *
 *   solutions = quadraticEquation(1, 1, 1);  // Reusing solutions.
 *   cout << solutions[0] << " " << solutions[1] << "\n";
 *   return 0;
 * }
 *
 * Output:
 * (-1, 0) (-1, 0)
 * (-0.5,0.866025) (-0.5,0.866025)
 */

#include <array>      /// std::array
#include <cassert>    /// assert
#include <cmath>      /// std::sqrt, std::trunc, std::pow
#include <complex>    /// std::complex
#include <exception>  /// std::invalid_argument
#include <iomanip>    /// std::setprecision
#include <iostream>   /// std::cout

/**
 * @namespace
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * @brief Quadratic equation calculator.
 * @param a quadratic coefficient.
 * @param b linear coefficient.
 * @param c constant
 * @return Array containing the roots of quadratic equation, incl. complex
 * root.
 */
std::array<std::complex<long double>, 2> quadraticEquation(long double a,
                                                           long double b,
                                                           long double c) {
    if (a == 0) {
        throw std::invalid_argument("quadratic coefficient cannot be 0");
    }

    long double discriminant = b * b - 4 * a * c;
    std::array<std::complex<long double>, 2> solutions{0, 0};

    if (discriminant == 0) {
        solutions[0] = -b * 0.5 / a;
        solutions[1] = -b * 0.5 / a;
        return solutions;
    }

    // Complex root (discriminant < 0)
    // Note that the left term (-b / 2a) is always real. The imaginary part
    // appears when b^2 - 4ac < 0, so sqrt(b^2 - 4ac) has no real roots. So,
    // the imaginary component is i * (+/-)sqrt(abs(b^2 - 4ac)) / 2a.
    if (discriminant > 0) {
        // Since discriminant > 0, there are only real roots. Therefore,
        // imaginary component = 0.
        solutions[0] = std::complex<long double>{
            (-b - std::sqrt(discriminant)) * 0.5 / a, 0};
        solutions[1] = std::complex<long double>{
            (-b + std::sqrt(discriminant)) * 0.5 / a, 0};
        return solutions;
    }
    // Since b^2 - 4ac is < 0, for faster computation, -discriminant is
    // enough to make it positive.
    solutions[0] = std::complex<long double>{
        -b * 0.5 / a, -std::sqrt(-discriminant) * 0.5 / a};
    solutions[1] = std::complex<long double>{
        -b * 0.5 / a, std::sqrt(-discriminant) * 0.5 / a};

    return solutions;
}

}  // namespace math

/**
 * @brief Asserts an array of complex numbers.
 * @param input Input array of complex numbers. .
 * @param expected Expected array of complex numbers.
 * @param precision Precision to be asserted. Default=10
 */
void assertArray(std::array<std::complex<long double>, 2> input,
                 std::array<std::complex<long double>, 2> expected,
                 size_t precision = 10) {
    long double exponent = std::pow(10, precision);
    input[0].real(std::round(input[0].real() * exponent));
    input[1].real(std::round(input[1].real() * exponent));
    input[0].imag(std::round(input[0].imag() * exponent));
    input[1].imag(std::round(input[1].imag() * exponent));

    expected[0].real(std::round(expected[0].real() * exponent));
    expected[1].real(std::round(expected[1].real() * exponent));
    expected[0].imag(std::round(expected[0].imag() * exponent));
    expected[1].imag(std::round(expected[1].imag() * exponent));

    assert(input == expected);
}

/**
 * @brief Self-test implementations to test quadraticEquation function.
 * @note There are 4 different types of solutions: Real and equal, real,
 * complex, complex and equal.
 */
static void test() {
    // Values are equal and real.
    std::cout << "Input: \n"
                 "a=1 \n"
                 "b=-2 \n"
                 "c=1 \n"
                 "Expected output: \n"
                 "(1, 0), (1, 0)\n\n";
    std::array<std::complex<long double>, 2> equalCase{
        std::complex<long double>{1, 0}, std::complex<long double>{1, 0}};
    assert(math::quadraticEquation(1, -2, 1) == equalCase);

    // Values are equal and complex.
    std::cout << "Input: \n"
                 "a=1 \n"
                 "b=4 \n"
                 "c=5 \n"
                 "Expected output: \n"
                 "(-2, -1), (-2, 1)\n\n";
    std::array<std::complex<long double>, 2> complexCase{
        std::complex<long double>{-2, -1}, std::complex<long double>{-2, 1}};
    assert(math::quadraticEquation(1, 4, 5) == complexCase);

    // Values are real.
    std::cout << "Input: \n"
                 "a=1 \n"
                 "b=5 \n"
                 "c=1 \n"
                 "Expected output: \n"
                 "(-4.7912878475, 0), (-0.2087121525, 0)\n\n";
    std::array<std::complex<long double>, 2> floatCase{
        std::complex<long double>{-4.7912878475, 0},
        std::complex<long double>{-0.2087121525, 0}};
    assertArray(math::quadraticEquation(1, 5, 1), floatCase);

    // Values are complex.
    std::cout << "Input: \n"
                 "a=1 \n"
                 "b=1 \n"
                 "c=1 \n"
                 "Expected output: \n"
                 "(-0.5, -0.8660254038), (-0.5, 0.8660254038)\n\n";
    std::array<std::complex<long double>, 2> ifloatCase{
        std::complex<long double>{-0.5, -0.8660254038},
        std::complex<long double>{-0.5, 0.8660254038}};
    assertArray(math::quadraticEquation(1, 1, 1), ifloatCase);

    std::cout << "Exception test: \n"
                 "Input: \n"
                 "a=0 \n"
                 "b=0 \n"
                 "c=0\n"
                 "Expected output: Exception thrown \n";
    try {
        math::quadraticEquation(0, 0, 0);
    } catch (std::invalid_argument& e) {
        std::cout << "Exception thrown successfully \n";
    }
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // Run self-test implementation.
    return 0;
}

/**
 * @file
 * @brief Solve a quadratic equation ax^2 + bx + c = 0, including the case
 * where the roots are complex (b^2 - 4ac < 0).
 *
 * @description
 * Uses the standard formula x = (-b +/- sqrt(b^2 - 4ac)) / (2a), branching
 * on the sign of the discriminant to decide whether the result is a
 * repeated real root, two distinct real roots, or a conjugate pair of
 * complex roots.
 *
 * @example
 * int main() {
 *   auto roots = solveQuadratic(1, 2, 1);
 *   std::cout << roots[0] << " " << roots[1] << "\n";
 *   return 0;
 * }
 *
 * Sample output for a=1,b=2,c=1: (-1, 0) (-1, 0)
 */

#include <array>      /// std::array
#include <cassert>    /// assert
#include <cmath>      /// std::sqrt, std::round, std::pow
#include <complex>    /// std::complex
#include <exception>  /// std::invalid_argument
#include <iomanip>    /// std::setprecision
#include <iostream>   /// std::cout

/**
 * @namespace
 * @brief Mathematical algorithms
 */
namespace math {

using RootPair = std::array<std::complex<long double>, 2>;

/**
 * @brief Solves ax^2 + bx + c = 0 for real or complex roots.
 * @param a quadratic coefficient (must be non-zero)
 * @param b linear coefficient
 * @param c constant term
 * @return pair of roots as complex numbers (imaginary part 0 if real)
 */
RootPair solveQuadratic(long double a, long double b, long double c) {
    if (a == 0) {
        throw std::invalid_argument("quadratic coefficient cannot be 0");
    }

    long double disc = b * b - 4 * a * c;
    RootPair roots{0, 0};

    if (disc == 0) {
        // Repeated real root.
        long double onlyRoot = -b * 0.5 / a;
        roots[0] = onlyRoot;
        roots[1] = onlyRoot;
        return roots;
    }

    if (disc > 0) {
        // Two distinct real roots; imaginary component is zero.
        long double sqrtDisc = std::sqrt(disc);
        roots[0] = std::complex<long double>{(-b - sqrtDisc) * 0.5 / a, 0};
        roots[1] = std::complex<long double>{(-b + sqrtDisc) * 0.5 / a, 0};
        return roots;
    }

    // disc < 0: conjugate pair of complex roots. Real part is always -b/2a;
    // imaginary part comes from sqrt of the (now positive) negated discriminant.
    long double realPart = -b * 0.5 / a;
    long double imagMagnitude = std::sqrt(-disc) * 0.5 / a;
    roots[0] = std::complex<long double>{realPart, -imagMagnitude};
    roots[1] = std::complex<long double>{realPart, imagMagnitude};

    return roots;
}

}  // namespace math

/**
 * @brief Compares two root-pairs after rounding to a fixed number of decimal
 * places, to make floating point comparisons in tests reliable.
 * @param actual computed roots
 * @param expected roots we expect
 * @param decimals how many decimal digits of precision to keep (default 10)
 */
void expectRootsNear(math::RootPair actual, math::RootPair expected,
                      size_t decimals = 10) {
    long double scale = std::pow(10, decimals);

    for (int i = 0; i < 2; ++i) {
        actual[i].real(std::round(actual[i].real() * scale));
        actual[i].imag(std::round(actual[i].imag() * scale));
        expected[i].real(std::round(expected[i].real() * scale));
        expected[i].imag(std::round(expected[i].imag() * scale));
    }

    assert(actual == expected);
}

/**
 * @brief Runs a handful of fixed scenarios against solveQuadratic, covering
 * the repeated-real, distinct-real, complex, and invalid-input cases.
 */
static void runDemoChecks() {
    std::cout << "Case: a=1 b=-2 c=1 -> expect (1,0),(1,0)\n";
    math::RootPair repeatedReal{std::complex<long double>{1, 0},
                                 std::complex<long double>{1, 0}};
    assert(math::solveQuadratic(1, -2, 1) == repeatedReal);

    std::cout << "Case: a=1 b=4 c=5 -> expect (-2,-1),(-2,1)\n";
    math::RootPair repeatedComplex{std::complex<long double>{-2, -1},
                                    std::complex<long double>{-2, 1}};
    assert(math::solveQuadratic(1, 4, 5) == repeatedComplex);

    std::cout << "Case: a=1 b=5 c=1 -> expect approx (-4.7912878475,0),(-0.2087121525,0)\n";
    math::RootPair distinctReal{std::complex<long double>{-4.7912878475, 0},
                                 std::complex<long double>{-0.2087121525, 0}};
    expectRootsNear(math::solveQuadratic(1, 5, 1), distinctReal);

    std::cout << "Case: a=1 b=1 c=1 -> expect approx (-0.5,-0.8660254038),(-0.5,0.8660254038)\n";
    math::RootPair distinctComplex{
        std::complex<long double>{-0.5, -0.8660254038},
        std::complex<long double>{-0.5, 0.8660254038}};
    expectRootsNear(math::solveQuadratic(1, 1, 1), distinctComplex);

    std::cout << "Case: a=0 b=0 c=0 -> expect exception\n";
    try {
        math::solveQuadratic(0, 0, 0);
        std::cout << "ERROR: no exception thrown\n";
    } catch (std::invalid_argument&) {
        std::cout << "Exception thrown as expected\n";
    }
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runDemoChecks();
    return 0;
}

/**
 * \file
 * \brief Compute statistics for data entered in rreal-time
 *
 * This algorithm is really beneficial to compute statistics on data read in
 * realtime. For example, devices reading biometrics data. The algorithm is
 * simple enough to be easily implemented in an embedded system.
 * \author [Krishna Vedala](https://github.com/kvedala)
 */
#include <cassert>
#include <cmath>
#include <iostream>

/**
 * \namespace statistics
 * \brief Statistical algorithms
 */
namespace statistics {

/**
 * continuous mean and variance computance using
 * first value as an approximation for the mean.
 * If the first number is much far form the mean, the algorithm becomes very
 * inaccurate to compute variance and standard deviation.
 */
template <typename T>
class stats_computer1 {
 public:
    /** Constructor
     * \param[in] x new data sample
     */
    void new_val(T x) {
        if (n == 0)
            K = x;
        n++;
        T tmp = x - K;
        Ex += tmp;
        Ex2 += static_cast<double>(tmp) * tmp;
    }

    /** return sample mean computed till last sample */
    double mean() const { return K + Ex / n; }

    /** return data variance computed till last sample */
    double variance() const { return (Ex2 - (Ex * Ex) / n) / (n - 1); }

    /** return sample standard deviation computed till last sample */
    double std() const { return std::sqrt(this->variance()); }

    /** short-hand operator to read new sample from input stream
     * \n e.g.: `std::cin >> stats1;`
     */
    friend std::istream &operator>>(std::istream &input,
                                    stats_computer1 &stat) {
        T val;
        input >> val;
        stat.new_val(val);
        return input;
    }

 private:
    unsigned int n = 0;
    double Ex, Ex2;
    T K;
};

/**
 * continuous mean and variance computance using
 * Welford's algorithm  (very accurate)
 */
template <typename T>
class stats_computer2 {
 public:
    /** Constructor
     * \param[in] x new data sample
     */
    void new_val(T x) {
        n++;
        double delta = x - mu;
        mu += delta / n;
        double delta2 = x - mu;
        M += delta * delta2;
    }

    /** return sample mean computed till last sample */
    double mean() const { return mu; }

    /** return data variance computed till last sample */
    double variance() const { return M / n; }

    /** return sample standard deviation computed till last sample */
    double std() const { return std::sqrt(this->variance()); }

    /** short-hand operator to read new sample from input stream
     * \n e.g.: `std::cin >> stats1;`
     */
    friend std::istream &operator>>(std::istream &input,
                                    stats_computer2 &stat) {
        T val;
        input >> val;
        stat.new_val(val);
        return input;
    }

 private:
    unsigned int n = 0;
    double mu = 0, var = 0, M = 0;
};

}  // namespace statistics

using statistics::stats_computer1;
using statistics::stats_computer2;

/** Test the algorithm implementation
 * \param[in] test_data array of data to test the algorithms
 */
void test_function(const float *test_data, const int number_of_samples) {
    float mean = 0.f, variance = 0.f;

    stats_computer1<float> stats01;
    stats_computer2<float> stats02;

    for (int i = 0; i < number_of_samples; i++) {
        stats01.new_val(test_data[i]);
        stats02.new_val(test_data[i]);
        mean += test_data[i];
    }

    mean /= number_of_samples;

    for (int i = 0; i < number_of_samples; i++) {
        float temp = test_data[i] - mean;
        variance += temp * temp;
    }
    variance /= number_of_samples;

    std::cout << "<<<<<<<< Test Function >>>>>>>>" << std::endl
              << "Expected: Mean: " << mean << "\t Variance: " << variance
              << std::endl;
    std::cout << "\tMethod 1:"
              << "\tMean: " << stats01.mean()
              << "\t Variance: " << stats01.variance()
              << "\t Std: " << stats01.std() << std::endl;
    std::cout << "\tMethod 2:"
              << "\tMean: " << stats02.mean()
              << "\t Variance: " << stats02.variance()
              << "\t Std: " << stats02.std() << std::endl;

    assert(std::abs(stats01.mean() - mean) < 0.01);
    assert(std::abs(stats02.mean() - mean) < 0.01);
    assert(std::abs(stats02.variance() - variance) < 0.01);

    std::cout << "(Tests passed)" << std::endl;
}

/** Main function */
int main() {
    const float test_data1[] = {3, 4, 5, -1.4, -3.6, 1.9, 1.};
    test_function(test_data1, sizeof(test_data1) / sizeof(test_data1[0]));

    std::cout
        << "Enter data. Any non-numeric data will terminate the data input."
        << std::endl;

    stats_computer1<float> stats1;
    stats_computer2<float> stats2;

    while (1) {
        double val;
        std::cout << "Enter number: ";
        std::cin >> val;

        // check for failure to read input. Happens for
        // non-numeric data
        if (std::cin.fail())
            break;

        stats1.new_val(val);
        stats2.new_val(val);

        std::cout << "\tMethod 1:"
                  << "\tMean: " << stats1.mean()
                  << "\t Variance: " << stats1.variance()
                  << "\t Std: " << stats1.std() << std::endl;
        std::cout << "\tMethod 2:"
                  << "\tMean: " << stats2.mean()
                  << "\t Variance: " << stats2.variance()
                  << "\t Std: " << stats2.std() << std::endl;
    }

    return 0;
}

/**
 * \file
 * \brief Streaming statistics helpers for live data feeds.
 *
 * When numbers arrive one at a time (sensor readings, telemetry, etc.) it is
 * often impractical to store the whole history just to compute a mean or a
 * variance. The two accumulators below update their state incrementally so
 * memory usage stays constant regardless of how many samples are ingested.
 */
#include <cassert>
#include <cmath>
#include <iostream>

/**
 * \namespace live_metrics
 * \brief Incremental (single-pass) statistical accumulators
 */
namespace live_metrics {

/**
 * Naive shifted-data accumulator: the very first observed value is used as
 * an anchor point (K) to keep intermediate sums well-conditioned. If that
 * first sample happens to be an outlier, the variance estimate degrades.
 */
template <typename T>
class ShiftedMomentTracker {
 public:
    /** Feed a new observation into the tracker. */
    void observe(T sample) {
        if (count_ == 0) {
            anchor_ = sample;
        }
        ++count_;
        T shifted = sample - anchor_;
        sum_ += shifted;
        sum_sq_ += static_cast<double>(shifted) * shifted;
    }

    /** Running mean up to the most recent observation. */
    double average() const { return anchor_ + sum_ / count_; }

    /** Running (sample) variance up to the most recent observation. */
    double dispersion() const {
        return (sum_sq_ - (sum_ * sum_) / count_) / (count_ - 1);
    }

    /** Running standard deviation. */
    double spread() const { return std::sqrt(this->dispersion()); }

    /** Stream-extraction convenience so a tracker can consume `std::cin`. */
    friend std::istream &operator>>(std::istream &in, ShiftedMomentTracker &tracker) {
        T v;
        in >> v;
        tracker.observe(v);
        return in;
    }

 private:
    unsigned int count_ = 0;
    double sum_ = 0, sum_sq_ = 0;
    T anchor_{};
};

/**
 * Welford-style accumulator. Numerically robust because it never forms the
 * sum of squares directly; instead it refines the mean and the sum of
 * squared deviations from the mean together on every update.
 */
template <typename T>
class WelfordMomentTracker {
 public:
    /** Feed a new observation into the tracker. */
    void observe(T sample) {
        ++count_;
        double delta_before = sample - mean_;
        mean_ += delta_before / count_;
        double delta_after = sample - mean_;
        m2_ += delta_before * delta_after;
    }

    /** Running mean up to the most recent observation. */
    double average() const { return mean_; }

    /** Running (population) variance up to the most recent observation. */
    double dispersion() const { return m2_ / count_; }

    /** Running standard deviation. */
    double spread() const { return std::sqrt(this->dispersion()); }

    /** Stream-extraction convenience so a tracker can consume `std::cin`. */
    friend std::istream &operator>>(std::istream &in, WelfordMomentTracker &tracker) {
        T v;
        in >> v;
        tracker.observe(v);
        return in;
    }

 private:
    unsigned int count_ = 0;
    double mean_ = 0, m2_ = 0;
};

}  // namespace live_metrics

using live_metrics::ShiftedMomentTracker;
using live_metrics::WelfordMomentTracker;

/**
 * Runs both accumulators over a fixed sample set and cross-checks the
 * results against a plain two-pass computation of mean/variance.
 */
void run_self_check(const float *samples, int sample_count) {
    float reference_mean = 0.f, reference_variance = 0.f;

    ShiftedMomentTracker<float> shifted_tracker;
    WelfordMomentTracker<float> welford_tracker;

    for (int idx = 0; idx < sample_count; ++idx) {
        shifted_tracker.observe(samples[idx]);
        welford_tracker.observe(samples[idx]);
        reference_mean += samples[idx];
    }
    reference_mean /= sample_count;

    for (int idx = 0; idx < sample_count; ++idx) {
        float centered = samples[idx] - reference_mean;
        reference_variance += centered * centered;
    }
    reference_variance /= sample_count;

    std::cout << "==== self check ====" << std::endl
              << "reference -> mean: " << reference_mean
              << "  variance: " << reference_variance << std::endl;
    std::cout << "  shifted tracker -> mean: " << shifted_tracker.average()
              << "  variance: " << shifted_tracker.dispersion()
              << "  stddev: " << shifted_tracker.spread() << std::endl;
    std::cout << "  welford tracker -> mean: " << welford_tracker.average()
              << "  variance: " << welford_tracker.dispersion()
              << "  stddev: " << welford_tracker.spread() << std::endl;

    assert(std::abs(shifted_tracker.average() - reference_mean) < 0.01);
    assert(std::abs(welford_tracker.average() - reference_mean) < 0.01);
    assert(std::abs(welford_tracker.dispersion() - reference_variance) < 0.01);

    std::cout << "self check ok" << std::endl;
}

int main() {
    const float sample_batch[] = {3, 4, 5, -1.4, -3.6, 1.9, 1.};
    run_self_check(sample_batch, sizeof(sample_batch) / sizeof(sample_batch[0]));

    std::cout << "Type numbers one per line; a non-numeric entry stops input."
              << std::endl;

    ShiftedMomentTracker<float> live_shifted;
    WelfordMomentTracker<float> live_welford;

    for (;;) {
        double reading;
        std::cout << "value> ";
        std::cin >> reading;

        if (std::cin.fail()) {
            break;  // reached a non-numeric token, stop the loop
        }

        live_shifted.observe(reading);
        live_welford.observe(reading);

        std::cout << "  shifted tracker -> mean: " << live_shifted.average()
                  << "  variance: " << live_shifted.dispersion()
                  << "  stddev: " << live_shifted.spread() << std::endl;
        std::cout << "  welford tracker -> mean: " << live_welford.average()
                  << "  variance: " << live_welford.dispersion()
                  << "  stddev: " << live_welford.spread() << std::endl;
    }

    return 0;
}

/**
 * @file
 * @brief Prime Numbers using [Sieve of
 * Eratosthenes](https://en.wikipedia.org/wiki/Sieve_of_Eratosthenes)
 * @details
 * Sieve of Eratosthenes is an algorithm that finds all the primes
 * between 2 and N.
 *
 * Time Complexity  : \f$O(N \cdot\log \log N)\f$
 * <br/>Space Complexity : \f$O(N)\f$
 *
 * @see primes_up_to_billion.cpp prime_numbers.cpp
 */

#include <cstdint>
#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @namespace sieve_of_eratosthenes
 * @brief Functions for finding Prime Numbers using Sieve of Eratosthenes
 */
namespace sieve_of_eratosthenes {
/**
 * @brief Function to sieve out the primes
 * @details
 * This function finds all the primes between 2 and N using the Sieve of
 * Eratosthenes algorithm. It starts by assuming all numbers (except zero and
 * one) are prime and then iteratively marks the multiples of each prime as
 * non-prime.
 *
 * Contains a common optimization to start eliminating multiples of
 * a prime p starting from p * p since all of the lower multiples
 * have been already eliminated.
 * @param N number till which primes are to be found
 * @return is_prime a vector of `N + 1` booleans identifying if `i`^th number is
 * a prime or not
 */
std::vector<bool> sieve(uint32_t N) {
    std::vector<bool> is_prime(N + 1, true);  // Initialize all as prime numbers
    is_prime[0] = is_prime[1] = false;        // 0 and 1 are not prime numbers

    for (uint32_t i = 2; i * i <= N; i++) {
        if (is_prime[i]) {
            for (uint32_t j = i * i; j <= N; j += i) {
                is_prime[j] = false;
            }
        }
    }
    return is_prime;
}

/**
 * @brief Function to print the prime numbers
 * @param N number till which primes are to be found
 * @param is_prime a vector of `N + 1` booleans identifying if `i`^th number is
 * a prime or not
 */
void print(uint32_t N, const std::vector<bool> &is_prime) {
    for (uint32_t i = 2; i <= N; i++) {
        if (is_prime[i]) {
            std::cout << i << ' ';
        }
    }
    std::cout << std::endl;
}

}  // namespace sieve_of_eratosthenes
}  // namespace math

/**
 * @brief Self-test implementations
 * @return void
 */
static void tests() {
    std::vector<bool> is_prime_1 =
        math::sieve_of_eratosthenes::sieve(static_cast<uint32_t>(10));
    std::vector<bool> is_prime_2 =
        math::sieve_of_eratosthenes::sieve(static_cast<uint32_t>(20));
    std::vector<bool> is_prime_3 =
        math::sieve_of_eratosthenes::sieve(static_cast<uint32_t>(100));

    std::vector<bool> expected_1{false, false, true,  true,  false, true,
                                 false, true,  false, false, false};
    assert(is_prime_1 == expected_1);

    std::vector<bool> expected_2{false, false, true,  true,  false, true,
                                 false, true,  false, false, false, true,
                                 false, true,  false, false, false, true,
                                 false, true,  false};
    assert(is_prime_2 == expected_2);

    std::vector<bool> expected_3{
        false, false, true,  true,  false, true,  false, true,  false, false,
        false, true,  false, true,  false, false, false, true,  false, true,
        false, false, false, true,  false, false, false, false, false, true,
        false, true,  false, false, false, false, false, true,  false, false,
        false, true,  false, true,  false, false, false, true,  false, false,
        false, false, false, true,  false, false, false, false, false, true,
        false, true,  false, false, false, false, false, true,  false, false,
        false, true,  false, true,  false, false, false, false, false, true,
