/**
 * @file
 * @brief Enumerate primes up to a bound using the classic Eratosthenes sieve.
 * @details
 * Starting from the assumption that every integer 2..N might be prime, we
 * repeatedly cross out multiples of each newly confirmed prime. Whatever
 * survives the crossing-out process is prime.
 *
 * Running time is roughly O(N log log N); memory usage is O(N) for the flag
 * table.
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @namespace prime_sieve
 * @brief Prime enumeration via elimination of composites
 */
namespace prime_sieve {

/**
 * @brief Build a boolean table marking primality of every value 0..limit.
 * @details
 * Composite numbers get crossed off starting at p*p for each prime p,
 * because smaller multiples of p were already eliminated by smaller primes.
 * @param limit largest value to test for primality
 * @return flags such that flags[i] is true exactly when i is prime
 */
std::vector<bool> build_prime_table(uint32_t limit) {
    std::vector<bool> flags(limit + 1, true);
    if (flags.size() > 0) flags[0] = false;
    if (flags.size() > 1) flags[1] = false;

    for (uint32_t candidate = 2; candidate * candidate <= limit; ++candidate) {
        if (!flags[candidate]) {
            continue;  // already known composite, nothing to eliminate with it
        }
        for (uint64_t multiple = static_cast<uint64_t>(candidate) * candidate;
             multiple <= limit; multiple += candidate) {
            flags[static_cast<uint32_t>(multiple)] = false;
        }
    }
    return flags;
}

/**
 * @brief Print every prime number up to a bound, space separated.
 * @param limit largest value considered
 * @param flags primality table produced by build_prime_table
 */
void print_primes(uint32_t limit, const std::vector<bool> &flags) {
    for (uint32_t value = 2; value <= limit; ++value) {
        if (flags[value]) {
            std::cout << value << ' ';
        }
    }
    std::cout << std::endl;
}

}  // namespace prime_sieve
}  // namespace math

/**
 * @brief Self-test implementations checking a handful of known bounds.
 */
static void run_tests() {
    std::vector<bool> table_10 =
        math::prime_sieve::build_prime_table(static_cast<uint32_t>(10));
    std::vector<bool> table_20 =
        math::prime_sieve::build_prime_table(static_cast<uint32_t>(20));
    std::vector<bool> table_100 =
        math::prime_sieve::build_prime_table(static_cast<uint32_t>(100));

    std::vector<bool> want_10{false, false, true,  true,  false, true,
                              false, true,  false, false, false};
    assert(table_10 == want_10);

    std::vector<bool> want_20{false, false, true,  true,  false, true,
                              false, true,  false, false, false, true,
                              false, true,  false, false, false, true,
                              false, true,  false};
    assert(table_20 == want_20);

    std::vector<bool> want_100{
        false, false, true,  true,  false, true,  false, true,  false, false,
        false, true,  false, true,  false, false, false, true,  false, true,
        false, false, false, true,  false, false, false, false, false, true,
        false, true,  false, false, false, false, false, true,  false, false,
        false, true,  false, true,  false, false, false, true,  false, false,
        false, false, false, true,  false, false, false, false, false, true,
        false, true,  false, false, false, false, false, true,  false, false,
        false, true,  false, true,  false, false, false, false, false, true,
        false, false, false, true,  false, false, false, false, false, true,
        false, false, false, false, false, false, false, true,  false, false,
        false};
    assert(table_100 == want_100);
}

/**
