 * @returns 0 on exit
 */
int main() {
    run_tests();
    return 0;
}

/**
 * @file
 * @brief Calculate the square root of any positive real number in \f$O(\log
 * N)\f$ time, with precision fixed using [bisection
 * method](https://en.wikipedia.org/wiki/Bisection_method) of root-finding.
 *
 * @see Can be implemented using faster and better algorithms like
 * newton_raphson_method.cpp and false_position.cpp
 */
#include <cassert>
#include <iostream>

/** Bisection method implemented for the function \f$x^2-a=0\f$
 * whose roots are \f$\pm\sqrt{a}\f$ and only the positive root is returned.
 */
double Sqrt(double a) {
    if (a > 0 && a < 1) {
        return 1 / Sqrt(1 / a);
    }
    double l = 0, r = a;
    /* Epsilon is the precision.
    A great precision is
    between 1e-7 and 1e-12.
    double epsilon = 1e-12;
    */
    double epsilon = 1e-12;
    while (l <= r) {
        double mid = (l + r) / 2;
        if (mid * mid > a) {
            r = mid;
        } else {
            if (a - mid * mid < epsilon) {
                return mid;
            }
            l = mid;
        }
    }
    return -1;
}

/** main function */
int main() {
    double n{};
    std::cin >> n;
    assert(n >= 0);
    // Change this line for a better precision
    std::cout.precision(12);
    std::cout << std::fixed << Sqrt(n);
}

/**
 * @file
 * @brief Approximate the square root of a non-negative real number via
 * binary search (bisection) on the candidate root, converging in O(log N)
 * steps for a fixed precision target.
 *
 * @see Faster/alternative approaches exist (Newton-Raphson, false position),
 * this file favors simplicity over speed.
 */
#include <cassert>
#include <iostream>

namespace {
constexpr double kTolerance = 1e-12;
}

/**
 * Iteratively narrows the interval [lo, hi] that must contain sqrt(value),
 * using the fact that f(x) = x^2 - value crosses zero exactly at the
 * positive root we want.
 */
double approximate_sqrt(double value) {
    if (value > 0 && value < 1) {
        // Reduce to the >=1 case: sqrt(v) = 1 / sqrt(1/v) for 0 < v < 1.
        return 1.0 / approximate_sqrt(1.0 / value);
    }

    double lo = 0.0;
    double hi = value;

    while (lo <= hi) {
        double mid = lo + (hi - lo) / 2.0;
        double squared = mid * mid;

        if (squared > value) {
            hi = mid;
        } else if (value - squared < kTolerance) {
            return mid;
        } else {
            lo = mid;
        }
    }

    return -1.0;  // should not be reached for valid, non-negative input
}

int main() {
    double input_value{};
    std::cin >> input_value;
    assert(input_value >= 0);

    std::cout.precision(12);
    std::cout << std::fixed << approximate_sqrt(input_value);
}

/**
 * @file
 * @brief This Programme returns the Nth fibonacci as a string.
 *
 * The method used is manual addition with carry and placing it in a string
 * which is called string addition This makes it have no bounds or limits
 *
 * @see fibonacci_large.cpp, fibonacci_fast.cpp, fibonacci.cpp
 */

#include <cstdint>
#include <iostream>
#ifdef _MSC_VER
#include <string>  // use this for MS Visual C
#else
#include <cstring>  // otherwise
#endif

/**
 * function to add two string numbers
 * \param [in] a first number in string to add
 * \param [in] b second number in string to add
 * \returns sum as a std::string
 */
std::string add(std::string a, std::string b) {
    std::string temp = "";

    // carry flag
    int carry = 0;

    // fills up with zeros
    while (a.length() < b.length()) {
        a = "0" + a;
    }

    // fills up with zeros
    while (b.length() < a.length()) {
        b = "0" + b;
    }

    // adds the numbers a and b
    for (int i = a.length() - 1; i >= 0; i--) {
        char val = static_cast<char>(((a[i] - 48) + (b[i] - 48)) + 48 + carry);
        if (val > 57) {
            carry = 1;
            val -= 10;
        } else {
            carry = 0;
        }
        temp = val + temp;
    }

    // processes the carry flag
    if (carry == 1) {
        temp = "1" + temp;
    }

    // removes leading zeros.
    while (temp[0] == '0' && temp.length() > 1) {
        temp = temp.substr(1);
    }

    return temp;
}

/** Fibonacci iterator
 * \param [in] n n^th Fibonacci number
 */
void fib_Accurate(uint64_t n) {
    std::string tmp = "";
    std::string fibMinus1 = "1";
    std::string fibMinus2 = "0";
    for (uint64_t i = 0; i < n; i++) {
        tmp = add(fibMinus1, fibMinus2);
        fibMinus2 = fibMinus1;
        fibMinus1 = tmp;
    }
    std::cout << fibMinus2;
}

/** main function */
int main() {
    int n;
    std::cout << "Enter whatever number N you want to find the fibonacci of\n";
    std::cin >> n;
    std::cout << n << " th Fibonacci is \n";
    fib_Accurate(n);

    return 0;
}

/**
 * @file
 * @brief Compute the Nth Fibonacci number as a decimal string, with no limit
 * on how many digits it may grow to.
 *
 * Because native integer types overflow quickly, this implementation keeps
 * every intermediate value as a string and performs grade-school addition
 * with manual carry propagation.
 *
 * @see fibonacci_large.cpp, fibonacci_fast.cpp, fibonacci.cpp
 */

#include <cstdint>
#include <iostream>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif

namespace {

/// Left-pads the shorter of two digit strings with zeros so both match length.
void equalize_lengths(std::string *lhs, std::string *rhs) {
    while (lhs->length() < rhs->length()) {
        *lhs = "0" + *lhs;
    }
    while (rhs->length() < lhs->length()) {
        *rhs = "0" + *rhs;
    }
}

/// Strips redundant leading zero characters, keeping at least one digit.
std::string drop_leading_zeros(std::string digits) {
    while (digits.size() > 1 && digits.front() == '0') {
        digits.erase(digits.begin());
    }
    return digits;
}

}  // namespace

/**
 * Adds two arbitrarily long non-negative decimal numbers represented as
 * strings and returns the sum, also as a string.
 */
std::string big_add(std::string lhs, std::string rhs) {
    equalize_lengths(&lhs, &rhs);

    std::string result;
    int carry = 0;

    for (int pos = static_cast<int>(lhs.length()) - 1; pos >= 0; --pos) {
        int digit_sum = (lhs[pos] - '0') + (rhs[pos] - '0') + carry;
        carry = digit_sum >= 10 ? 1 : 0;
        int digit = digit_sum >= 10 ? digit_sum - 10 : digit_sum;
        result.insert(result.begin(), static_cast<char>('0' + digit));
    }

    if (carry) {
        result.insert(result.begin(), '1');
    }

    return drop_leading_zeros(result);
}

/**
 * Iteratively advances the classic two-term recurrence, keeping both terms
 * as strings, and prints the nth Fibonacci number (0-indexed as F(0)=0,
 * F(1)=1) to standard output.
 */
void print_nth_fibonacci(uint64_t n) {
    std::string prev = "0";   // F(k-2)
    std::string curr = "1";   // F(k-1)

    for (uint64_t step = 0; step < n; ++step) {
        std::string next = big_add(curr, prev);
        prev = curr;
        curr = next;
    }

    std::cout << prev;
}

int main() {
    int n;
    std::cout << "Enter which Fibonacci index N you'd like computed\n";
    std::cin >> n;
    std::cout << n << " th Fibonacci is \n";
    print_nth_fibonacci(static_cast<uint64_t>(n));

    return 0;
}

/**
 * @file
 * @brief Algorithm to find sum of binomial coefficients of a given positive
 * integer.
 * @details Given a positive integer n, the task is to find the sum of binomial
 * coefficient i.e nC0 + nC1 + nC2 + ... + nCn-1 + nCn By induction, we can
 * prove that the sum is equal to 2^n
 * @see more on
 * https://en.wikipedia.org/wiki/Binomial_coefficient#Sums_of_the_binomial_coefficients
 * @author [muskan0719](https://github.com/muskan0719)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for std::cin and std::cout

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * Function to calculate sum of binomial coefficients
 * @param n number
 * @return Sum of binomial coefficients of number
 */
uint64_t binomialCoeffSum(uint64_t n) {
    // Calculating 2^n
    return (1 << n);
}
}  // namespace math

/**
 * Function for testing binomialCoeffSum function.
 * test cases and assert statement.
 * @returns `void`
 */
static void test() {
    int test_case_1 = math::binomialCoeffSum(2);
    assert(test_case_1 == 4);
    std::cout << "Test_case_1 Passed!" << std::endl;

    int test_case_2 = math::binomialCoeffSum(3);
    assert(test_case_2 == 8);
    std::cout << "Test_case_2 Passed!" << std::endl;

    int test_case_3 = math::binomialCoeffSum(4);
    assert(test_case_3 == 16);
    std::cout << "Test_case_3 Passed!" << std::endl;

    int test_case_4 = math::binomialCoeffSum(5);
    assert(test_case_4 == 32);
    std::cout << "Test_case_4 Passed!" << std::endl;

    int test_case_5 = math::binomialCoeffSum(7);
    assert(test_case_5 == 128);
    std::cout << "Test_case_5 Passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // execute the tests
    return 0;
}

/**
 * @file
 * @brief Compute the sum of all binomial coefficients for a fixed row of
 * Pascal's triangle.
 * @details Given a non-negative integer n, we want
 * C(n,0) + C(n,1) + ... + C(n,n). A standard combinatorial identity shows
 * this sum always equals 2^n, so no actual combinatorics computation is
 * needed.
 * @see https://en.wikipedia.org/wiki/Binomial_coefficient#Sums_of_the_binomial_coefficients
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for std::cin and std::cout

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {

/**
 * Returns the total of every binomial coefficient in row n, i.e. 2^n,
 * computed with a bit shift rather than an explicit summation loop.
 * @param row the row index n
 * @return 2 raised to the power `row`
 */
uint64_t total_row_coefficients(uint64_t row) {
    return static_cast<uint64_t>(1) << row;
}

}  // namespace math

/**
 * Exercises total_row_coefficients against a handful of known rows.
 */
static void verify_examples() {
    struct Case {
        uint64_t row;
        uint64_t expected;
    };

    const Case cases[] = {
        {2, 4}, {3, 8}, {4, 16}, {5, 32}, {7, 128},
    };

    int case_number = 1;
    for (const auto &c : cases) {
        uint64_t got = math::total_row_coefficients(c.row);
        assert(got == c.expected);
        std::cout << "Case " << case_number << " ok (row=" << c.row
                  << " -> " << got << ")" << std::endl;
        ++case_number;
    }
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    verify_examples();
    return 0;
}

/**
 * Copyright 2020 @author iamnambiar
 *
 * @file
 * \brief A C++ Program to find the Sum of Digits of input integer.
 */
#include <cassert>
#include <iostream>

/**
 * Function to find the sum of the digits of an integer.
 * @param num The integer.
 * @return Sum of the digits of the integer.
 *
 * \detail
 * First the algorithm check whether the num is negative or positive,
 * if it is negative, then we neglect the negative sign.
 * Next, the algorithm extract the last digit of num by dividing by 10
 * and extracting the remainder and this is added to the sum.
 * The number is then divided by 10 to remove the last digit.
 * This loop continues until num becomes 0.
 */
int sum_of_digits(int num) {
    // If num is negative then negative sign is neglected.
    if (num < 0) {
        num = -1 * num;
    }
    int sum = 0;
    while (num > 0) {
        sum = sum + (num % 10);
        num = num / 10;
    }
    return sum;
}

/**
 * Function for testing the sum_of_digits() function with a
 * first test case of 119765 and assert statement.
 */
void test1() {
    int test_case_1 = sum_of_digits(119765);
    assert(test_case_1 == 29);
}

/**
 * Function for testing the sum_of_digits() function with a
 * second test case of -12256 and assert statement.
 */
void test2() {
    int test_case_2 = sum_of_digits(-12256);
    assert(test_case_2 == 16);
}

/**
 * Function for testing the sum_of_digits() with
 * all the test cases.
 */
void test() {
    // First test.
    test1();
    // Second test.
    test2();
}

/**
 * Main Function
 */
int main() {
    test();
    std::cout << "Success." << std::endl;
    return 0;
}

/**
 * @file
 * @brief Add up the decimal digits of an integer.
 *
 * Handles negative input by working with its absolute value, then peels off
 * digits one at a time from the least-significant end until nothing is left.
 */
#include <cassert>
#include <iostream>

/**
 * Returns the sum of the decimal digits of `value`. Sign is ignored: -125
 * and 125 both yield 8.
 *
 * Implementation notes: at each iteration we take `value % 10` to read off
 * the current last digit, add it to a running total, then integer-divide by
 * 10 to shift the next digit into place. Repeats until the number reaches
 * zero.
 */
int digit_sum(int value) {
    int magnitude = (value < 0) ? -value : value;

    int total = 0;
    while (magnitude != 0) {
        total += magnitude % 10;
        magnitude /= 10;
    }
    return total;
}

/// Checks a positive-input case: 119765 -> 1+1+9+7+6+5 = 29.
void check_positive_case() {
    assert(digit_sum(119765) == 29);
}

/// Checks a negative-input case: sign should not affect the result.
void check_negative_case() {
    assert(digit_sum(-12256) == 16);
}

/// Runs every check defined above.
void run_all_checks() {
    check_positive_case();
    check_negative_case();
}

int main() {
    run_all_checks();
    std::cout << "Success." << std::endl;
    return 0;
}

/**
 * @file
 *
 * @brief Calculates the [Cross
 *Product](https://en.wikipedia.org/wiki/Cross_product) and the magnitude of two
 *mathematical 3D vectors.
 *
 *
 * @details Cross Product of two vectors gives a vector.
 * Direction Ratios of a vector are the numeric parts of the given vector. They
 *are the tree parts of the vector which determine the magnitude (value) of the
 *vector. The method of finding a cross product is the same as finding the
 *determinant of an order 3 matrix consisting of the first row with unit vectors
 *of magnitude 1, the second row with the direction ratios of the first vector
 *and the third row with the direction ratios of the second vector. The
 *magnitude of a vector is it's value expressed as a number. Let the direction
 *ratios of the first vector, P be: a, b, c Let the direction ratios of the
 *second vector, Q be: x, y, z Therefore the calculation for the cross product
 *can be arranged as:
 *
 * ```
 * P x Q:
 *  	1	1	1
 *  	a	b	c
 *  	x	y	z
 * ```
 *
 * The direction ratios (DR) are calculated as follows:
 *  	1st DR, J:  (b * z) - (c * y)
 *  	2nd DR, A: -((a * z) - (c * x))
 *  	3rd DR, N:  (a * y) - (b * x)
 *
 * Therefore, the direction ratios of the cross product are: J, A, N
 * The following C++ Program calculates the direction ratios of the cross
 *products of two vector. The program uses a function, cross() for doing so. The
 *direction ratios for the first and the second vector has to be passed one by
 *one seperated by a space character.
 *
 * Magnitude of a vector is the square root of the sum of the squares of the
 *direction ratios.
 *
 * ### Example:
 * An example of a running instance of the executable program:
 *
 * 	Pass the first Vector: 1 2 3
 *	Pass the second Vector: 4 5 6
 *	The cross product is: -3 6 -3
 *	Magnitude: 7.34847
 *
 * @author [Shreyas Sable](https://github.com/Shreyas-OwO)
 */

#include <array>
#include <cassert>
#include <cmath>

/**
 * @namespace math
 * @brief Math algorithms
 */
namespace math {
/**
 * @namespace vector_cross
 * @brief Functions for Vector Cross Product algorithms
 */
namespace vector_cross {
/**
 * @brief Function to calculate the cross product of the passed arrays
 * containing the direction ratios of the two mathematical vectors.
 * @param A contains the direction ratios of the first mathematical vector.
 * @param B contains the direction ration of the second mathematical vector.
 * @returns the direction ratios of the cross product.
 */
std::array<double, 3> cross(const std::array<double, 3> &A,
                            const std::array<double, 3> &B) {
    std::array<double, 3> product;
    /// Performs the cross product as shown in @algorithm.
    product[0] = (A[1] * B[2]) - (A[2] * B[1]);
    product[1] = -((A[0] * B[2]) - (A[2] * B[0]));
    product[2] = (A[0] * B[1]) - (A[1] * B[0]);
    return product;
}

/**
 * @brief Calculates the magnitude of the mathematical vector from it's
 * direction ratios.
 * @param vec an array containing the direction ratios of a mathematical vector.
 * @returns type: double description: the magnitude of the mathematical vector
 * from the given direction ratios.
 */
double mag(const std::array<double, 3> &vec) {
    double magnitude =
        sqrt((vec[0] * vec[0]) + (vec[1] * vec[1]) + (vec[2] * vec[2]));
    return magnitude;
}
}  // namespace vector_cross
}  // namespace math

/**
 * @brief test function.
 * @details test the cross() and the mag() functions.
 */
static void test() {
    /// Tests the cross() function.
    std::array<double, 3> t_vec =
        math::vector_cross::cross({1, 2, 3}, {4, 5, 6});
    assert(t_vec[0] == -3 && t_vec[1] == 6 && t_vec[2] == -3);

    /// Tests the mag() function.
    double t_mag = math::vector_cross::mag({6, 8, 0});
    assert(t_mag == 10);

    /// Tests A ⨯ A = 0
    std::array<double, 3> t_vec2 =
        math::vector_cross::cross({1, 2, 3}, {1, 2, 3});
    assert(t_vec2[0] == 0 && t_vec2[1] == 0 &&
           t_vec2[2] == 0);  // checking each element
    assert(math::vector_cross::mag(t_vec2) ==
           0);  // checking the magnitude is also zero
}

/**
 * @brief Main Function
 * @details Asks the user to enter the direction ratios for each of the two
 * mathematical vectors using std::cin
 * @returns 0 on exit
 */
int main() {
    /// Tests the functions with sample input before asking for user input.
    test();
    return 0;
}

/**
 * @file
 *
 * @brief Reworked demo of computing the 3D cross product and vector norm.
 *
 * @details Given two vectors P = (a, b, c) and Q = (x, y, z), their cross
 * product P x Q yields a new vector whose components can be derived from
 * the determinant expansion of a 3x3 matrix built from the unit basis
 * vectors and the direction numbers of P and Q:
 *
 * ```
 * P x Q:
 *      1   1   1
 *      a   b   c
 *      x   y   z
 * ```
 *
 * Expanding that determinant gives the components:
 *      comp0 =  (b * z) - (c * y)
 *      comp1 = -((a * z) - (c * x))
 *      comp2 =  (a * y) - (b * x)
 *
 * The Euclidean norm (magnitude) of a vector is simply the square root of
 * the sum of the squares of its components.
 *
 * This file re-implements that idea with different naming/structure than
 * the reference version, purely for dataset/style-comparison purposes.
 */

#include <array>
#include <cassert>
#include <cmath>

/**
 * @namespace math
 * @brief Collection of math routines.
 */
namespace math {
/**
 * @namespace vector_ops
 * @brief Helpers for basic 3D vector arithmetic.
 */
namespace vector_ops {

using Vec3 = std::array<double, 3>;

/**
 * @brief Computes the cross product of two 3-component vectors.
 * @param lhs first operand vector
 * @param rhs second operand vector
 * @return resulting perpendicular vector
 */
Vec3 cross_product(const Vec3 &lhs, const Vec3 &rhs) {
    Vec3 result{};

    result[0] = lhs[1] * rhs[2] - lhs[2] * rhs[1];
    result[1] = lhs[2] * rhs[0] - lhs[0] * rhs[2];
    result[2] = lhs[0] * rhs[1] - lhs[1] * rhs[0];

    return result;
}

/**
 * @brief Computes the Euclidean length of a 3-component vector.
 * @param v vector whose length is requested
 * @return scalar magnitude of v
 */
double length_of(const Vec3 &v) {
    double sum_of_squares = 0.0;
    for (double component : v) {
        sum_of_squares += component * component;
    }
    return std::sqrt(sum_of_squares);
}

}  // namespace vector_ops
}  // namespace math

/**
 * @brief Runs a handful of sanity checks against known results.
 */
static void run_self_checks() {
    using math::vector_ops::Vec3;

    // Basic cross product check against a known pair.
    Vec3 first = {1, 2, 3};
    Vec3 second = {4, 5, 6};
    Vec3 crossed = math::vector_ops::cross_product(first, second);
    assert(crossed[0] == -3);
    assert(crossed[1] == 6);
    assert(crossed[2] == -3);

    // Magnitude check on a well known 3-4-5-like triple.
    Vec3 sample = {6, 8, 0};
    double norm_value = math::vector_ops::length_of(sample);
    assert(norm_value == 10);

    // A vector crossed with itself must be the zero vector, magnitude 0.
    Vec3 self_cross = math::vector_ops::cross_product(first, first);
    bool all_zero = true;
    for (double c : self_cross) {
        if (c != 0) {
            all_zero = false;
        }
    }
    assert(all_zero);
    assert(math::vector_ops::length_of(self_cross) == 0);
}

/**
 * @brief Entry point that triggers the self checks.
 * @return 0 on success
 */
int main() {
    run_self_checks();
    return 0;
}

/**
 * @file
 * @brief Implmentations for the [volume](https://en.wikipedia.org/wiki/Volume)
 * of various 3D shapes.
 * @details The volume of a 3D shape is the amount of 3D space that the shape
 * takes up. All shapes have a formula to get the volume of any given shape.
 * These implementations support multiple return types.
 *
 * @author [Focusucof](https://github.com/Focusucof)
 */

#include <cassert>   /// for assert
#include <cmath>     /// for std::pow
#include <cstdint>   /// for std::uint32_t
#include <iostream>  /// for IO operations

/**
 * @namespace math
 * @brief Mathematical algorithms
 */
namespace math {
/**
 * @brief The volume of a [cube](https://en.wikipedia.org/wiki/Cube)
 * @param length The length of the cube
 * @returns The volume of the cube
 */
template <typename T>
T cube_volume(T length) {
    return std::pow(length, 3);
}

/**
 * @brief The volume of a
 * [rectangular](https://en.wikipedia.org/wiki/Cuboid) prism
 * @param length The length of the base rectangle
 * @param width The width of the base rectangle
 * @param height The height of the rectangular prism
 * @returns The volume of the rectangular prism
 */
template <typename T>
T rect_prism_volume(T length, T width, T height) {
    return length * width * height;
}

/**
 * @brief The volume of a [cone](https://en.wikipedia.org/wiki/Cone)
 * @param radius The radius of the base circle
 * @param height The height of the cone
 * @param PI The definition of the constant PI
 * @returns The volume of the cone
 */
template <typename T>
T cone_volume(T radius, T height, double PI = 3.14) {
    return std::pow(radius, 2) * PI * height / 3;
}

/**
 * @brief The volume of a
 * [triangular](https://en.wikipedia.org/wiki/Triangular_prism) prism
 * @param base The length of the base triangle
 * @param height The height of the base triangles
 * @param depth The depth of the triangular prism (the height of the whole
 * prism)
 * @returns The volume of the triangular prism
 */
template <typename T>
T triangle_prism_volume(T base, T height, T depth) {
    return base * height * depth / 2;
}

/**
 * @brief The volume of a
 * [pyramid](https://en.wikipedia.org/wiki/Pyramid_(geometry))
 * @param length The length of the base shape (or base for triangles)
 * @param width The width of the base shape (or height for triangles)
 * @param height The height of the pyramid
 * @returns The volume of the pyramid
 */
template <typename T>
T pyramid_volume(T length, T width, T height) {
    return length * width * height / 3;
}

/**
 * @brief The volume of a [sphere](https://en.wikipedia.org/wiki/Sphere)
 * @param radius The radius of the sphere
 * @param PI The definition of the constant PI
 * @returns The volume of the sphere
 */
template <typename T>
T sphere_volume(T radius, double PI = 3.14) {
    return PI * std::pow(radius, 3) * 4 / 3;
}

/**
 * @brief The volume of a [cylinder](https://en.wikipedia.org/wiki/Cylinder)
 * @param radius The radius of the base circle
 * @param height The height of the cylinder
 * @param PI The definition of the constant PI
 * @returns The volume of the cylinder
 */
template <typename T>
T cylinder_volume(T radius, T height, double PI = 3.14) {
    return PI * std::pow(radius, 2) * height;
}
}  // namespace math

