/**
 * @{
 * \file
 * \brief Alternate rewrite of the classical fourth-order Runge-Kutta method
 * for solving a first-order ODE dy/dx = f(x, y).
 *
 * \details
 * The example equation handled below is:
 *   dy/dx = (x - y) / 2
 * Given an initial condition (x0, y0), we march forward to a target x using
 * a fixed step size h, applying the standard four-stage RK4 update at each
 * step.
 */
#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

/**
 * Evaluates the slope function f(x, y) = (x - y) / 2 used by the demo ODE.
 */
static double slope_function(double x, double y) { return (x - y) / 2.0; }

/**
 * @namespace numerical_methods
 * @brief Numerical Methods
 */
namespace numerical_methods {
/**
 * @namespace runge_kutta
 * @brief Fourth-order Runge-Kutta integration helpers.
 */
namespace runge_kutta {

/**
 * Integrates from (start_x, start_y) up to target_x using fixed step size
 * step_h, applying the classic four-stage RK4 formula at each step.
 *
 * @param start_x initial x value (kept as a running/updated cursor)
 * @param start_y initial y value
 * @param target_x the x value at which we want the approximate y
 * @param step_h   fixed step size used for marching forward
 * @return approximate y at target_x
 */
double rungeKutta(double start_x, const double &start_y,
                   const double &target_x, const double &step_h) {
    // Determine how many fixed-size steps are needed to reach target_x.
    auto steps_needed = static_cast<uint64_t>((target_x - start_x) / step_h);

    // Four RK stage coefficients, recomputed fresh on each iteration.
    std::vector<double> stage(4, 0.0);

    double current_y = start_y;
    double cursor_x = start_x;
    for (uint64_t step = 0; step < steps_needed; ++step) {
        stage[0] = step_h * slope_function(cursor_x, current_y);
        stage[1] = step_h * slope_function(cursor_x + 0.5 * step_h,
                                            current_y + 0.5 * stage[0]);
        stage[2] = step_h * slope_function(cursor_x + 0.5 * step_h,
                                            current_y + 0.5 * stage[1]);
        stage[3] = step_h * slope_function(cursor_x + step_h,
                                            current_y + stage[2]);

        current_y += (stage[0] + 2 * stage[1] + 2 * stage[2] + stage[3]) / 6.0;
        cursor_x += step_h;
    }

    return current_y;
}

}  // namespace runge_kutta
}  // namespace numerical_methods

