/**
 * @file
 * @brief Alternate rewrite of the array left-rotation exercise: given a
 * vector and a shift amount, produce a new vector rotated left by that many
 * positions, leaving the source untouched.
 */

#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * Prints every element of a vector on one line, space separated, followed by
 * a newline.
 */
void print(const std::vector<int32_t> &values) {
    for (size_t idx = 0; idx < values.size(); ++idx) {
        std::cout << values[idx] << " ";
    }
    std::cout << "\n";
}

/**
 * Builds a new vector that is `source` rotated left by `positions` slots.
 * Rotating left means the element originally at index `positions` becomes
 * the new first element, wrapping the first `positions` elements around to
 * the tail.
 *
 * @param source     the vector to rotate (not modified)
 * @param positions  how many slots to rotate left by
 * @return a new vector with the rotated contents, or an empty vector if
 *         `positions` is out of range (>= source.size())
 */
std::vector<int32_t> shift_left(const std::vector<int32_t> &source,
                                 size_t positions) {
    if (positions >= source.size()) {
        return {};
    }

    std::vector<int32_t> rotated;
    rotated.reserve(source.size());

    // First, take everything from the rotation point to the end.
    for (size_t idx = positions; idx < source.size(); ++idx) {
        rotated.push_back(source[idx]);
    }
    // Then wrap the leading chunk around to the back.
    for (size_t idx = 0; idx < positions; ++idx) {
        rotated.push_back(source[idx]);
    }

    return rotated;
}

}  // namespace operations_on_datastructures

/**
 * @namespace verification
 * @brief Self-checks exercising shift_left() against known outcomes.
 */
namespace verification {
using operations_on_datastructures::print;
using operations_on_datastructures::shift_left;

/** Basic rotation of a small non-empty vector. */
void case_basic_rotation() {
    std::cout << "CASE: basic rotation\n";
    std::cout << "Input = {1, 2, 3, 4, 5}, shift = 2\n";
    std::cout << "Expected = {3, 4, 5, 1, 2}\n";
    std::vector<int32_t> input = {1, 2, 3, 4, 5};
    std::vector<int32_t> actual = shift_left(input, 2);
    std::vector<int32_t> expected = {3, 4, 5, 1, 2};
    assert(actual == expected);
    print(actual);
    std::cout << "CASE PASSED\n\n";
}

/** Rotating an empty vector should still yield an empty vector. */
void case_empty_input() {
    std::cout << "CASE: empty input\n";
    std::cout << "Input = {}, shift = 2\n";
    std::cout << "Expected = {}\n";
    std::vector<int32_t> input = {};
    std::vector<int32_t> actual = shift_left(input, 2);
    std::vector<int32_t> expected = {};
    assert(actual == expected);
    print(actual);
    std::cout << "CASE PASSED\n\n";
}

/** A shift amount that exceeds the vector length is invalid -> empty result. */
void case_shift_out_of_range() {
    std::cout << "CASE: shift larger than size\n";
    std::cout << "Input = {1, 2, 3, 4, 5}, shift = 7\n";
    std::cout << "Expected = {}\n";
    std::vector<int32_t> input = {1, 2, 3, 4, 5};
    std::vector<int32_t> actual = shift_left(input, 7);
    std::vector<int32_t> expected = {};
    assert(actual == expected);
    print(actual);
    std::cout << "CASE PASSED\n\n";
}

/** Larger input to make sure the rotation scales correctly. */
void case_large_input() {
    std::cout << "CASE: large input\n";
    std::cout << "Input = {2, 4, ..., 420}, shift = 1\n";
    std::cout << "Expected = {4, 6, ..., 420, 2}\n";
    std::vector<int32_t> input;
    for (int val = 1; val <= 210; val++) {
        input.push_back(val * 2);
    }
    print(input);

    std::vector<int32_t> actual = shift_left(input, 1);

    std::vector<int32_t> expected;
    for (size_t idx = 1; idx < input.size(); idx++) {
        expected.push_back(input[idx]);
    }
    expected.push_back(input[0]);

    assert(actual == expected);
    print(actual);
    std::cout << "CASE PASSED\n\n";
}

/** A shift of zero should return the vector unchanged. */
void case_zero_shift() {
    std::cout << "CASE: zero shift\n";
    std::cout << "Input = {1, 2, 3, 4, 5}, shift = 0\n";
    std::cout << "Expected = {1, 2, 3, 4, 5}\n";
    std::vector<int32_t> input = {1, 2, 3, 4, 5};
    std::vector<int32_t> actual = shift_left(input, 0);
    assert(actual == input);
    print(actual);
    std::cout << "CASE PASSED\n\n";
}

}  // namespace verification

/**
 * Runs the full battery of self-checks against shift_left().
 */
static void run_all_checks() {
    verification::case_basic_rotation();
    verification::case_empty_input();
    verification::case_shift_out_of_range();
    verification::case_large_input();
    verification::case_zero_shift();
}

