// A singly linked list whose tail wraps back to the head, forming a ring.
// Any node can serve as an entry point since traversal simply loops until
// it returns to wherever it started.

#include <cassert>
#include <iostream>
#include <vector>

namespace operations_on_datastructures {
namespace ring_list {

// One link in the ring: a payload plus a pointer to the following link.
struct Link {
    int64_t payload;
    Link* follower;

    explicit Link(int64_t value) : payload(value), follower(nullptr) {}
    Link(int64_t value, Link* next_link) : payload(value), follower(next_link) {}
};

// Owns a ring of Link nodes and provides insertion, printing and
// value-extraction operations relative to an arbitrary starting node.
class Ring {
 public:
    Ring() : head_(nullptr), tail_(nullptr) {}

    Ring(const Ring& other) : head_(nullptr), tail_(nullptr) {
        clear();
        Link* cursor = other.head_;
        while (cursor != nullptr) {
            append(cursor->payload);
            cursor = cursor->follower;
        }
    }

    Ring(Ring&& other) noexcept : head_(other.head_), tail_(other.tail_) {
        other.head_ = nullptr;
        other.tail_ = nullptr;
    }

    Ring& operator=(const Ring& other) {
        if (this == &other) return *this;
        clear();
        head_ = nullptr;
        Link* cursor = other.head_;
        while (cursor != nullptr) {
            append(cursor->payload);
            cursor = cursor->follower;
        }
        return *this;
    }

    Ring& operator=(Ring&& other) noexcept {
        head_ = other.head_;
        tail_ = other.tail_;
        other.head_ = nullptr;
        other.tail_ = nullptr;
        return *this;
    }

    ~Ring() { clear(); }

    // Releases every node currently owned by the ring.
    void clear() {
        if (head_ == nullptr) return;
        Link* cursor = head_;
        do {
            Link* victim = cursor;
            cursor = cursor->follower;
            delete victim;
        } while (cursor != head_);
        head_ = nullptr;
        tail_ = nullptr;
    }

    // Appends each element of `data`, preserving order.
    void append(const std::vector<int64_t>& data) {
        for (size_t i = 0; i < data.size(); ++i) {
            append(data[i]);
        }
    }

    // Wraps `value` in a fresh Link and appends it to the ring.
    void append(int64_t value) {
        Link* fresh = new Link(value, head_);
        append(fresh);
    }

    // Splices an already-allocated Link into the ring, fixing up head/tail
    // and the wraparound pointer.
    void append(Link* fresh) {
        if (head_ == nullptr) {
            head_ = fresh;
            fresh->follower = head_;
            tail_ = head_;
        } else {
            tail_->follower = fresh;
            fresh->follower = head_;
            tail_ = fresh;
        }
    }

    // Prints the ring starting from the internal head.
    void show() { show(head_); }

    // Prints the ring starting from an arbitrary node used as the
    // traversal's entry point.
    void show(Link* start) {
        if (start == nullptr) {
            std::cout << "Empty List!\n";
            return;
        }
        Link* cursor = start;
        do {
            std::cout << cursor->payload << " ";
            cursor = cursor->follower;
        } while (cursor != start);
        std::cout << "\n";
    }

    // Collects the ring's values into a vector, beginning at the head.
    std::vector<int64_t> collect() { return collect(head_); }

    // Collects the ring's values into a vector, beginning at an
    // arbitrary node.
    std::vector<int64_t> collect(Link* start) {
        std::vector<int64_t> out;
        if (start == nullptr) {
            return out;
        }
        Link* cursor = start;
        do {
            out.push_back(cursor->payload);
            cursor = cursor->follower;
        } while (cursor != start);
        return out;
    }

 private:
    Link* head_;
    Link* tail_;
};

}  // namespace ring_list
}  // namespace operations_on_datastructures

namespace self_checks {
using operations_on_datastructures::ring_list::Link;
using operations_on_datastructures::ring_list::Ring;

// Single-element ring behaves sanely.
void check_single_element() {
    std::cout << "[check_single_element]\n";
    Ring ring;
    ring.append(int64_t{9});
    std::vector<int64_t> want = {9};
    assert(ring.collect() == want);
    ring.show();
    std::cout << "ok\n\n";
}

// A handful of sequential insertions.
void check_multiple_elements() {
    std::cout << "[check_multiple_elements]\n";
    Ring ring;
    ring.append(int64_t{1});
    ring.append(int64_t{2});
    ring.append(int64_t{3});
    std::vector<int64_t> want = {1, 2, 3};
    assert(ring.collect() == want);
    ring.show();
    std::cout << "ok\n\n";
}

// Bulk insertion via a vector overload.
void check_bulk_insert() {
    std::cout << "[check_bulk_insert]\n";
    Ring ring;
    std::vector<int64_t> data = {4, 9, 1, 7, 4, 2};
    ring.append(data);
    ring.show();
    assert(ring.collect() == data);
    std::cout << "ok\n\n";
}

// Traversal can begin from any node, not just the original head.
void check_alternate_start_node() {
    std::cout << "[check_alternate_start_node]\n";
    Ring ring;
    ring.append(int64_t{1});
    Link* alt_start = new Link(2);
    ring.append(alt_start);
    std::vector<int64_t> want = {2, 1};
    assert(ring.collect(alt_start) == want);
    ring.show(alt_start);
    std::cout << "ok\n\n";
}

// An untouched ring should behave like an empty list.
void check_empty_ring() {
    std::cout << "[check_empty_ring]\n";
    Ring ring;
    assert(ring.collect().empty());
    ring.show();
    std::cout << "ok\n\n";
}

void run_all() {
    check_single_element();
    check_multiple_elements();
    check_bulk_insert();
    check_alternate_start_node();
    check_empty_ring();
}

}  // namespace self_checks

int main() {
    self_checks::run_all();
    return 0;
}

#include <iostream>
using std::cin;
using std::cout;

int queue[10];
int front = 0;
int rear = 0;
int count = 0;

void Enque(int x) {
    if (count == 10) {
        cout << "\nOverflow";
    } else {
        queue[rear] = x;
        rear = (rear + 1) % 10;
        count++;
    }
}

void Deque() {
    if (front == rear) {
        cout << "\nUnderflow";
    }

    else {
        cout << "\n" << queue[front] << " deleted";
        front = (front + 1) % 10;
        count--;
    }
}

void show() {
    for (int i = 0; i < count; i++) {
        cout << queue[(i + front) % 10] << "\t";
    }
}

int main() {
    int ch, x;
    do {
        cout << "\n1. Enque";
        cout << "\n2. Deque";
        cout << "\n3. Print";
        cout << "\nEnter Your Choice : ";
        cin >> ch;
        if (ch == 1) {
            cout << "\nInsert : ";
            cin >> x;
            Enque(x);
        } else if (ch == 2) {
            Deque();
        } else if (ch == 3) {
            show();
        }
    } while (ch != 0);

    return 0;
}

// Fixed-capacity circular queue backed by a plain array, wrapped in a
// small class instead of loose global functions.

#include <iostream>

namespace ring_buffer_queue {

constexpr int kCapacity = 10;

class RingBufferQueue {
 public:
    RingBufferQueue() : head_(0), tail_(0), stored_(0) {}

    void push(int value) {
        if (stored_ == kCapacity) {
            std::cout << "\nOverflow";
            return;
        }
        slots_[tail_] = value;
        tail_ = (tail_ + 1) % kCapacity;
        ++stored_;
    }

    void pop() {
        if (stored_ == 0) {
            std::cout << "\nUnderflow";
            return;
        }
        std::cout << "\n" << slots_[head_] << " deleted";
        head_ = (head_ + 1) % kCapacity;
        --stored_;
    }

    void dump() const {
        for (int offset = 0; offset < stored_; ++offset) {
            std::cout << slots_[(head_ + offset) % kCapacity] << "\t";
        }
    }

 private:
    int slots_[kCapacity];
    int head_;
    int tail_;
    int stored_;
};

}  // namespace ring_buffer_queue

int main() {
    ring_buffer_queue::RingBufferQueue queue;
    int choice = -1;
    int value = 0;

    while (true) {
        std::cout << "\n1. Push";
        std::cout << "\n2. Pop";
        std::cout << "\n3. Dump";
        std::cout << "\nEnter Your Choice : ";
        std::cin >> choice;

        switch (choice) {
            case 1:
                std::cout << "\nInsert : ";
                std::cin >> value;
                queue.push(value);
                break;
            case 2:
                queue.pop();
                break;
            case 3:
                queue.dump();
                break;
            default:
                break;
        }

        if (choice == 0) {
            break;
        }
    }

    return 0;
}

#include <iostream>

class Node {
 public:
    int val;
    Node *next;

    Node(int v, Node *n) : val(v), next(n) {}  // Default constructor for Node
};

int getSize(Node *root) {
    if (root == NULL) {
        return 0;
    }
    // Each node will return 1 so the total adds up to be the size
    return 1 + getSize(root->next);
}

/*
 * @brief This function dealocates memory related to the given list
 * It recursively deletes all of the nodes of the input list.
 * @param room the root/head of the input list
 * @warning Plese note that the memory for each node has to be alocated using new.
 */
void deleteList(Node *const root) {
    if (root != NULL)
    {
        deleteList(root->next);
        delete root;
    }
}

int main() {
    Node *myList = new Node(0, NULL);  // Initializes the LinkedList
    Node *temp = myList;
    // Creates a linked lists of total size 10, numbered 1 - 10
    for (int i = 1; i < 10; i++) {
        temp->next = new Node(i, NULL);
        temp = temp->next;
    }
    // Creating other lists for checking purposes
    Node *secondList = new Node(0, NULL);  // List of size 1
    Node *thirdList = NULL;                // List of size 0

    std::cout << getSize(myList) << std::endl
              << getSize(secondList) << std::endl
              << getSize(thirdList) << std::endl;
    deleteList(secondList);
    deleteList(myList);

    return 0;
}

// Counts the number of nodes in a singly linked list using an
// iterative walk instead of recursion.

#include <iostream>

struct ListCell {
    int value;
    ListCell *link;

    ListCell(int v, ListCell *l) : value(v), link(l) {}
};

// Walks the chain of cells one step at a time, tallying how many
// nodes are visited before hitting the null terminator.
int length_of(ListCell *head) {
    int tally = 0;
    for (ListCell *cursor = head; cursor != nullptr; cursor = cursor->link) {
        ++tally;
    }
    return tally;
}

// Frees every cell in the chain, walking front to back and deleting
// as it goes (safe because we grab the next pointer before freeing).
void free_chain(ListCell *head) {
    while (head != nullptr) {
        ListCell *next = head->link;
        delete head;
        head = next;
    }
}

int main() {
    // Build a chain holding values 0 through 9.
    ListCell *chainA = new ListCell(0, nullptr);
    ListCell *walker = chainA;
    for (int i = 1; i < 10; ++i) {
        walker->link = new ListCell(i, nullptr);
        walker = walker->link;
    }

    ListCell *chainB = new ListCell(0, nullptr);  // single-element chain
    ListCell *chainC = nullptr;                   // empty chain

    std::cout << length_of(chainA) << std::endl
              << length_of(chainB) << std::endl
              << length_of(chainC) << std::endl;

    free_chain(chainB);
    free_chain(chainA);

    return 0;
}

/**
 * @file
 * @brief An implementation for finding the [Inorder successor of a binary
 * search tree](https://www.youtube.com/watch?v=5cPbNCrdotA) Inorder
 * successor of a node is the next node in Inorder traversal of the Binary Tree.
 * Inorder Successor is NULL for the last node in Inorder traversal.
 * @details
 * ### Case 1: The given node has the right node/subtree
 *
 *      * In this case, the left-most deepest node in the right subtree will
 * come just after the given node as we go to left deep in inorder.
 *      - Go deep to left most node in right subtree.
 *        OR, we can also say in case if BST, find the minimum of the subtree
 * for a given node.
 *
 * ### Case 2: The given node does not have a right node/subtree
 *
 * #### Method 1: Use parent pointer (store the address of parent nodes)
 *      * If a node does not have the right subtree, and we already visited the
 * node itself, then the next node will be its parent node according to inorder
 * traversal, and if we are going to parent from left, then the parent would be
 * unvisited.
 *      * In other words, go to the nearest ancestor for which given node would
 * be in left subtree.
 *
 * #### Method 2: Search from the root node
 *      * In case if there is no link from a child node to the parent node, we
 * need to walk down the tree starting from the root node to the given node, by
 * doing so, we are visiting every ancestor of the given node.
 *      * In order successor would be the deepest node in this path for which
 * given node is in left subtree.
 *
 * @author [Nitin Sharma](https://github.com/foo290)
 * */

#include <cassert>   ///  for assert
#include <iostream>  ///  for IO Operations
#include <vector>    ///  for std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on data structures
 */
namespace operations_on_datastructures {

/**
 * @namespace inorder_successor_of_bst
 * @brief Functions for the [Inorder successor of a binary search
 * tree](https://www.youtube.com/watch?v=5cPbNCrdotA) implementation
 */
namespace inorder_traversal_of_bst {

/**
 * @brief A Node structure representing a single node in BST
 */
class Node {
 public:
    int64_t data;  ///< The key/value of the node
    Node *left;    ///< Pointer to Left child
    Node *right;   ///< Pointer to right child
};

/**
 * @brief Allocates a new node in heap for given data and returns it's pointer.
 * @param data Data for the node.
 * @returns A pointer to the newly allocated Node.
 * */
Node *makeNode(int64_t data) {
    Node *node = new Node();
    node->data = data;      ///< setting data for node
    node->left = nullptr;   ///< setting left child as null
    node->right = nullptr;  ///< setting right child as null
    return node;
}

/**
 * @brief Inserts the given data in BST while maintaining the properties of BST.
 * @param root Pointer to the root node of the BST
 * @param data Data to be inserted.
 * @returns Node* Pointer to the root node.
 * */
Node *Insert(Node *root, int64_t data) {
    if (root == nullptr) {
        root = makeNode(data);
    } else if (data <= root->data) {
        root->left = Insert(root->left, data);
    } else {
        root->right = Insert(root->right, data);
    }
    return root;
}

/**
 * @brief Searches the given data in BST and returns the pointer to the node
 * containing that data.
 * @param root Pointer to the root node of the BST
 * @param data Data to be Searched.
 * @returns Node* pointer to the found node
 * */
Node *getNode(Node *root, int64_t data) {
    if (root == nullptr) {
        return nullptr;
    } else if (root->data == data) {
        return root;  /// Node found!
    } else if (data > root->data) {
        /// Traverse right subtree recursively as the given data is greater than
        /// the data in root node, data must be present in right subtree.
        return getNode(root->right, data);
    } else {
        /// Traverse left subtree recursively as the given data is less than the
        /// data in root node, data must be present in left subtree.
        return getNode(root->left, data);
    }
}

/**
 * @brief Finds and return the minimum node in BST.
 * @param root A pointer to root node.
 * @returns Node* Pointer to the found node
 * */
Node *findMinNode(Node *root) {
    if (root == nullptr) {
        return root;
    }
    while (root->left != nullptr) {
        root = root->left;
    }
    return root;
}

/**
 * @brief Prints the BST in inorder traversal using recursion.
 * @param root A pointer to the root node of the BST.
 * @returns void
 * */
void printInorder(Node *root) {
    if (root == nullptr) {
        return;
    }

    printInorder(root->left);  /// recursive call to left subtree
    std::cout << root->data << " ";
    printInorder(root->right);  /// recursive call to right subtree
}

/**
 * @brief This function is used in test cases to quickly create BST containing
 * large data instead of hard coding it in code. For a given root, this will add
 * all the nodes containing data passes in data vector.
 * @param root Pointer to the root node.
 * @param data A vector containing integer values which are suppose to be
 * inserted as nodes in BST.
 * @returns Node pointer to the root node.
 * */
Node *makeBST(Node *root, const std::vector<int64_t> &data) {
    for (int64_t values : data) {
        root = Insert(root, values);
    }
    return root;
}

/**
 * @brief Inorder successor of a node is the next node in inorder traversal of
 * the Binary Tree. This function takes the root node and the data of the node
 * for which we have to find the inorder successor, and returns the inorder
 * successor node.
 * @details Search from the root node as we need to walk the tree starting from
 * the root node to the given node, by doing so, we are visiting every ancestor
 * of the given node. In order successor would be the deepest node in this path
 * for which given node is in left subtree. Time complexity O(h)
 * @param root A pointer to the root node of the BST
 * @param data The data (or the data of node) for which we have to find inorder
 * successor.
 * @returns Node pointer to the inorder successor node.
 * */
Node *getInorderSuccessor(Node *root, int64_t data) {
    Node *current = getNode(root, data);
    if (current == nullptr) {
        return nullptr;
    }

    // Case - 1
    if (current->right != nullptr) {
        return findMinNode(current->right);
    }
    // case - 2
    else {
        Node *successor = nullptr;
        Node *ancestor = root;

        while (ancestor != current && ancestor != nullptr) {
            // This means my current node is in left of the root node
            if (current->data < ancestor->data) {
                successor = ancestor;
                ancestor = ancestor->left;  // keep going left
            } else {
                ancestor = ancestor->right;
            }
        }
        return successor;  // Nodes with maximum vales will not have a successor
    }
}

/**
 * @brief This function clears the memory allocated to entire tree recursively.
 * Its just for clean up the memory and not relevant to the actual topic.
 * @param root Root node of the tree.
 * @returns void
 * */
void deallocate(Node *rootNode) {
    if (rootNode == nullptr) {
        return;
    }
    deallocate(rootNode->left);
    deallocate(rootNode->right);
    delete (rootNode);
}

}  // namespace inorder_traversal_of_bst
}  // namespace operations_on_datastructures

