// Finds the inorder successor of a given key inside a binary search
// tree.
//
// Two scenarios:
//   1. The target node has a right child: its successor is the
//      leftmost (smallest) node of that right subtree.
//   2. The target node has no right child: walk down from the root,
//      remembering the last ancestor for which the target lay in the
//      left subtree; that ancestor is the successor. If no such
//      ancestor exists, the target was the maximum element and has
//      no successor.

#include <cassert>
#include <iostream>
#include <vector>

namespace operations_on_datastructures {
namespace bst_successor {

// A single BST node holding an integer key.
class TreeNode {
 public:
    int64_t key;
    TreeNode *left_child;
    TreeNode *right_child;
};

// Heap-allocates a leaf node carrying the given key.
TreeNode *new_leaf(int64_t key) {
    TreeNode *node = new TreeNode();
    node->key = key;
    node->left_child = nullptr;
    node->right_child = nullptr;
    return node;
}

// Inserts `key` into the subtree rooted at `node`, preserving BST
// ordering, and returns the (possibly new) subtree root.
TreeNode *insert_key(TreeNode *node, int64_t key) {
    if (node == nullptr) {
        return new_leaf(key);
    }
    if (key <= node->key) {
        node->left_child = insert_key(node->left_child, key);
    } else {
        node->right_child = insert_key(node->right_child, key);
    }
    return node;
}

// Builds a BST from a batch of keys by inserting them in sequence.
TreeNode *build_tree(TreeNode *node, const std::vector<int64_t> &keys) {
    for (size_t i = 0; i < keys.size(); ++i) {
        node = insert_key(node, keys[i]);
    }
    return node;
}

// Locates the node holding `key`, or nullptr if absent.
TreeNode *find_key(TreeNode *node, int64_t key) {
    while (node != nullptr && node->key != key) {
        node = (key > node->key) ? node->right_child : node->left_child;
    }
    return node;
}

// Follows left children until there are none left, returning the
// smallest-keyed node in the subtree.
TreeNode *leftmost(TreeNode *node) {
    if (node == nullptr) {
        return nullptr;
    }
    while (node->left_child != nullptr) {
        node = node->left_child;
    }
    return node;
}

// Prints keys in ascending (inorder) order.
void print_sorted(TreeNode *node) {
    if (node == nullptr) {
        return;
    }
    print_sorted(node->left_child);
    std::cout << node->key << " ";
    print_sorted(node->right_child);
}

// Determines the inorder successor of the node holding `key`.
TreeNode *successor_of(TreeNode *tree_root, int64_t key) {
    TreeNode *target = find_key(tree_root, key);
    if (target == nullptr) {
        return nullptr;
    }

    if (target->right_child != nullptr) {
        return leftmost(target->right_child);
    }

    TreeNode *best_candidate = nullptr;
    TreeNode *cursor = tree_root;
    while (cursor != nullptr && cursor != target) {
        if (target->key < cursor->key) {
            best_candidate = cursor;
            cursor = cursor->left_child;
        } else {
            cursor = cursor->right_child;
        }
    }
    return best_candidate;
}

// Recursively frees every node in the tree.
void destroy_tree(TreeNode *node) {
    if (node == nullptr) {
        return;
    }
    destroy_tree(node->left_child);
    destroy_tree(node->right_child);
    delete node;
}

}  // namespace bst_successor
}  // namespace operations_on_datastructures

namespace self_checks {
using operations_on_datastructures::bst_successor::build_tree;
using operations_on_datastructures::bst_successor::destroy_tree;
using operations_on_datastructures::bst_successor::print_sorted;
using operations_on_datastructures::bst_successor::successor_of;
using operations_on_datastructures::bst_successor::TreeNode;

void log_line(const std::string &msg) {
    std::cout << "[check] " << msg << std::endl;
}

// The maximum-valued node should have no inorder successor.
void check_no_successor_for_max_node() {
    log_line("largest key in the tree has no successor");

    TreeNode *root = nullptr;
    std::vector<int64_t> keys{15, 8, 40, 2, 12, 25, 60, 50, 30};
    root = build_tree(root, keys);

    std::cout << "sorted keys: ";
    print_sorted(root);
    std::cout << std::endl;

    TreeNode *succ = successor_of(root, 60);
    assert(succ == nullptr);
    log_line("passed");

    destroy_tree(root);
}

// Successor of an internal node with a right subtree.
void check_successor_uses_right_subtree_min() {
    log_line("successor found via right subtree minimum");

    TreeNode *root = nullptr;
    std::vector<int64_t> keys{15, 8, 40, 2, 12, 25, 60, 50, 30};
    root = build_tree(root, keys);

    std::cout << "sorted keys: ";
    print_sorted(root);
    std::cout << std::endl;

    TreeNode *succ = successor_of(root, 15);
    assert(succ != nullptr && succ->key == 25);
    log_line("passed");

    destroy_tree(root);
}

// Successor found by climbing through ancestors (no right child case).
void check_successor_uses_ancestor_walk() {
    log_line("successor found via ancestor walk");

    TreeNode *root = nullptr;
    std::vector<int64_t> keys{70, 55, 20, 45, 80, 95, 90, 85, 60};
    root = build_tree(root, keys);

    std::cout << "sorted keys: ";
    print_sorted(root);
    std::cout << std::endl;

    TreeNode *succ = successor_of(root, 45);
    assert(succ != nullptr && succ->key == 55);
    log_line("passed");

    destroy_tree(root);
}

void run_all() {
    check_no_successor_for_max_node();
    check_successor_uses_right_subtree_min();
    check_successor_uses_ancestor_walk();
}

}  // namespace self_checks

int main() {
    self_checks::run_all();

    operations_on_datastructures::bst_successor::TreeNode *root = nullptr;
    std::vector<int64_t> keys{10, 18, 3, 44, 9, 7};
    int64_t query_key = 9;

    root = operations_on_datastructures::bst_successor::build_tree(root, keys);
    operations_on_datastructures::bst_successor::TreeNode *succ =
        operations_on_datastructures::bst_successor::successor_of(root,
                                                                   query_key);

    std::cout << "Sorted sequence: ";
    operations_on_datastructures::bst_successor::print_sorted(root);
    std::cout << std::endl;

    if (succ == nullptr) {
        std::cout << "No successor exists for the largest key" << std::endl;
    } else {
        std::cout << "Query key: " << query_key << std::endl;
        std::cout << "Its inorder successor is: " << succ->key << std::endl;
    }

    operations_on_datastructures::bst_successor::destroy_tree(root);
    return 0;
}

/**
 * @file
 * @brief Implementation for the [Intersection of two sorted
 * Arrays](https://en.wikipedia.org/wiki/Intersection_(set_theory))
 * algorithm.
 * @details The intersection of two arrays is the collection of all the elements
 * that are common in both the first and second arrays. This implementation uses
 * ordered arrays, and an algorithm to correctly order them and return the
 * result as a new array (vector).
 * @see union_of_two_arrays.cpp
 * @author [Alvin](https://github.com/polarvoid)
 */

#include <algorithm>  /// for std::sort
#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @brief Prints the values of a vector sequentially, ending with a newline
 * character.
 * @param array Reference to the array to be printed
 * @returns void
 */
void print(const std::vector<int32_t> &array) {
    for (int32_t i : array) {
        std::cout << i << " ";  /// Print each value in the array
    }
    std::cout << "\n";  /// Print newline
}

/**
 * @brief Gets the intersection of two sorted arrays, and returns them in a
 * vector.
 * @details An algorithm is used that compares the elements of the two vectors,
 * incrementing the index of the smaller of the two. If the elements are the
 * same, the element is appended to the result array to be returned.
 * @param first A std::vector of sorted integer values
 * @param second A std::vector of sorted integer values
 * @returns A std::vector of the intersection of the two arrays, in ascending
 * order
 */
std::vector<int32_t> get_intersection(const std::vector<int32_t> &first,
                                      const std::vector<int32_t> &second) {
    std::vector<int32_t> res;         ///< Vector to hold the intersection
    size_t f_index = 0;               ///< Index for the first array
    size_t s_index = 0;               ///< Index for the second array
    size_t f_length = first.size();   ///< Length of first array
    size_t s_length = second.size();  ///< Length of second array

    while (f_index < f_length && s_index < s_length) {
        if (first[f_index] < second[s_index]) {
            f_index++;  ///< Increment index of second array
        } else if (first[f_index] > second[s_index]) {
            s_index++;  ///< Increment index of second array
        } else {
            if ((res.size() == 0) || (first[f_index] != res.back())) {
                res.push_back(
                    first[f_index]);  ///< Add the element if it is unique
            }
            f_index++;  ///< Increment index of first array
            s_index++;  ///< Increment index of second array too
        }
    }
    return res;
}

}  // namespace operations_on_datastructures

