#include <iostream>
using namespace std;

struct node {
    int val;
    node *next;
};

node *start;

void insert(int x) {
    node *t = start;
    if (start != NULL) {
        while (t->next != NULL) {
            t = t->next;
        }
        node *n = new node;
        t->next = n;
        n->val = x;
        n->next = NULL;
    } else {
        node *n = new node;
        n->val = x;
        n->next = NULL;
        start = n;
    }
}

void reverse(node *p, node *q) {
    if (q->next == NULL) {
        q->next = p;
        p->next = NULL;
        start = q;
        return;
    } else {
        reverse(q, q->next);
        q->next = p;
        p->next = NULL;
    }
}

void show() {
    node *t = start;
    while (t != NULL) {
        cout << t->val << "\t";
        t = t->next;
    }
}

int main() {
    insert(1);
    insert(2);
    insert(3);
    insert(4);
    insert(5);
    insert(6);

    reverse(start, start->next);

    show();

    return 0;
}

// Reverses a singly linked list in place using recursion.
#include <iostream>
using namespace std;

// A single list element holding an integer and a pointer to the next
// element.
struct ListCell {
    int value;
    ListCell *next;
};

ListCell *head_ptr;

// Appends a new value to the end of the list, walking from head_ptr
// until it finds the tail.
void append_value(int value) {
    ListCell *walker = head_ptr;
    if (head_ptr != NULL) {
        while (walker->next != NULL) {
            walker = walker->next;
        }
        ListCell *fresh = new ListCell;
        walker->next = fresh;
        fresh->value = value;
        fresh->next = NULL;
    } else {
        ListCell *fresh = new ListCell;
        fresh->value = value;
        fresh->next = NULL;
        head_ptr = fresh;
    }
}

// Recursively reverses the list rooted at `first`, where `second` is
// first->next. Once `second` is the tail (second->next == NULL), we've
// hit the base case: `second` becomes the new head and we start
// re-linking backwards as the recursion unwinds.
void reverse_recursive(ListCell *first, ListCell *second) {
    if (second->next == NULL) {
        second->next = first;
        first->next = NULL;
        head_ptr = second;
        return;
    }
    reverse_recursive(second, second->next);
    second->next = first;
    first->next = NULL;
}

// Prints the list from head_ptr to the end, tab-separated.
void display_list() {
    ListCell *walker = head_ptr;
    while (walker != NULL) {
        cout << walker->value << "\t";
        walker = walker->next;
    }
}

int main() {
    append_value(1);
    append_value(2);
    append_value(3);
    append_value(4);
    append_value(5);
    append_value(6);

    reverse_recursive(head_ptr, head_ptr->next);

    display_list();

    return 0;
}

/**
 * @file
 * @brief Implementation for the [Reversing a Binary
 * Tree](https://www.geeksforgeeks.org/reverse-tree-path/) recursively
 * algorithm.
 * @details A binary tree can be reversed by swapping the left and
 * right child of a node at each node, starting from the root, and
 * cascading below. This solution aims to provide an implementation of
 * a recursive reversal of a binary tree.
 * @author [Alvin](https://github.com/polarvoid)
 */

#include <cassert>   /// For assert
#include <iostream>  /// For IO operations
#include <queue>     /// For std::queue
#include <vector>    /// For std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @namespace reverse_binary_tree
 * @brief Functions for the [Reverse a Binary
 * Tree](https://www.geeksforgeeks.org/reverse-tree-path/) implementation
 */
namespace reverse_binary_tree {

/**
 * @brief A Node struct that represents a single node in a Binary Tree
 */
struct Node {
    int64_t data;  ///< The value of the Node
    Node* left;    ///< The Node's left child
    Node* right;   ///< The Node's right child
    /**
     * @brief Creates a new Node with some initial data
     */
    explicit Node(int64_t _data) {
        data = _data;     ///< Set value of Node data
        left = nullptr;   ///< Initialize left child to NULL
        right = nullptr;  ///< Initialize right child to NULL
    }
};

/**
 * @brief A Binary Tree class that implements a Binary Search Tree
 *(BST) by default.
 */
class BinaryTree {
 private:
    Node* root;  ///< Pointer to root node of Binary Tree
    /**
     * @brief inserts a node in the Binary Tree, with the behaviouur of
     * a Binary Search Tree.
     * @details Nodes with smaller values are inserted in the left
     * subtree, and Nodes with larger values are inserted into the
     * right subtree recursively. Time Complexity: O(log(n))
     * @param data The data/value of the Node to be inserted
     * @param pivot A pointer to the root node of the (sub)tree
     * @returns Node pointer to the root
     */
    Node* insert(int64_t data, Node* pivot) {
        if (pivot == nullptr) {
            return new Node(data);  ///< Create new node
        }
        if (data <= pivot->data) {
            pivot->left =
                insert(data, pivot->left);  ///< Insert Node to the left
        } else {
            pivot->right =
                insert(data, pivot->right);  ///< Insert node to the right
        }
        return pivot;
    }
    /**
     * @brief Reverses a Binary Tree recursively by swapping the left and
     * right subtrees and their children.
     * @param pivot A reference to the root of the (sub)tree
     * @returns Node pointer to root node
     */
    Node* reverseBinaryTree(Node* pivot) {
        if (pivot == nullptr) {
            return pivot;  ///< Base case
        }
        Node* temp = pivot->left;  ///< pointer to the left subtree
        pivot->left = reverseBinaryTree(pivot->right);  ///< Swap
        pivot->right = reverseBinaryTree(temp);         ///< Swap
        return pivot;
    }

    BinaryTree(const BinaryTree&) = delete;
    BinaryTree& operator=(const BinaryTree&) = delete;

 public:
    /**
     * @brief Creates a BinaryTree with a root pointing to NULL.
     */
    BinaryTree() { root = nullptr; }
    /**
     * @brief Creates a BinaryTree with a root with an initial value.
     */
    explicit BinaryTree(int64_t data) { root = new Node(data); }

    ~BinaryTree() {
        std::vector<Node*> nodes;
        nodes.emplace_back(root);
        while (!nodes.empty()) {
            const auto cur_node = nodes.back();
            nodes.pop_back();
            if (cur_node) {
                nodes.emplace_back(cur_node->left);
                nodes.emplace_back(cur_node->right);
                delete cur_node;
            }
        }
    }

    /**
     * @brief Adds a new Node to the Binary Tree
     */
    void add(int64_t data) { root = insert(data, root); }
    /**
     * Reverses the Binary Tree
     */
    void reverse() { root = reverseBinaryTree(root); }
    /**
     * @brief Level order traversal of a tree consists of visiting its
     * elements, top to bottom, left to right. This function performs
     * level order traversal and returns the node datas as a vector.
     * @details The function uses a queue to append and remove elements
     * as they are visited, and then adds their children, if any. This
     * ensures that the elements are visited layer-by-layer, starting
     * from the root of the Tree.
     * @returns vector<int64_t> of nodes of the tree.
     */
    std::vector<int64_t> get_level_order() {
        std::vector<int64_t> data;  ///< Result vector of int
        if (root == nullptr) {
            return data;  ///< Return empty vector if root is Invalid
        }
        std::queue<Node*> nodes;  ///< Queue of the nodes in the tree
        nodes.push(root);         ///< Insert root into the queue
        while (!nodes.empty()) {
            Node* temp = nodes.front();  ///< Copy the first element
            data.push_back(temp->data);  ///< Add the element to the data
            nodes.pop();                 ///< Remove element
            if (temp->left != nullptr) {
                nodes.push(temp->left);  ///< Insert left node
            }
            if (temp->right != nullptr) {
                nodes.push(temp->right);  ///< Insert right node
            }
        }  /// Add nodes while Tree is not empty
        return data;
    }
    /**
     * @brief Prints all of the elements in the tree to stdout
     * level-by-level, using the get_level_order() function.
     * @returns void
     */
    void print() {
        for (int i : get_level_order()) {
            std::cout << i << " ";  /// Print each element in the tree
        }
        std::cout << "\n";  /// Print newline
    }
};

}  // namespace reverse_binary_tree
}  // namespace operations_on_datastructures

/**
 * @namespace tests
 * @brief Testcases to check Reversal of Binary Tree.
 */
namespace tests {
using operations_on_datastructures::reverse_binary_tree::
    BinaryTree;  ///< Use the BinaryTree
/**
 * @brief A Test to check an edge case (single element reversal)
 */
void test1() {
    BinaryTree bst;
    std::vector<int64_t> pre_reversal, post_reversal;
    std::cout << "TEST CASE 1\n";
    std::cout << "Initializing tree with a single element (5)\n";
    bst.add(5);
    pre_reversal = bst.get_level_order();
    std::cout << "Before reversal: ";
    bst.print();
    std::cout << "After reversal: ";
    bst.reverse();
    post_reversal = bst.get_level_order();
    assert(pre_reversal.size() ==
           post_reversal.size());  ///< Check for equal sizes
    assert(pre_reversal.size() ==
           1);  ///< Ensure that there is only one element
    assert(pre_reversal[0] ==
           post_reversal[0]);  ///< Check if both elements are same
    bst.print();
    std::cout << "TEST PASSED!\n\n";
}
/**
 * @brief A Test to check an edge case (NULL root element)
 */
void test2() {
    BinaryTree bst;
    std::vector<int64_t> pre_reversal, post_reversal;
    std::cout << "TEST CASE 2\n";
    std::cout << "Creating empty tree (root points to NULL)\n";
    pre_reversal = bst.get_level_order();
    std::cout << "Before reversal: ";
    bst.print();
    std::cout << "After reversal: ";
    bst.reverse();
    post_reversal = bst.get_level_order();
    assert(pre_reversal.size() ==
           post_reversal.size());  ///< Check for equal sizes
    assert(pre_reversal.size() ==
           0);  ///< Ensure that there is only one element
    bst.print();
    std::cout << "TEST PASSED!\n\n";
}
/**
 * @brief A Test to check correct reversal of a Binary Tree
 */
void test3() {
    BinaryTree bst;
    std::vector<int64_t> pre_reversal, post_reversal;
    std::vector<int64_t> pre_res = {4, 3, 6, 2, 5, 7, 1};
    std::vector<int64_t> post_res = {4, 6, 3, 7, 5, 2, 1};
    std::cout << "TEST CASE 3\n";
    std::cout << "Creating tree with elements (4, 6, 3, 2, 5, 7, 1)\n";
    bst.add(4);
    bst.add(6);
    bst.add(3);
    bst.add(2);
    bst.add(5);
    bst.add(7);
    bst.add(1);
    pre_reversal = bst.get_level_order();
    assert(pre_reversal == pre_res);  ///< Check for equality
    std::cout << "Before reversal: ";
    bst.print();
    std::cout << "After reversal: ";
    bst.reverse();
    post_reversal = bst.get_level_order();
    assert(post_reversal == post_res);  ///< Check for equality
    bst.print();
    std::cout << "TEST PASSED!\n\n";
}
}  // namespace tests

/**
 * @brief Function to test the correctness of the Tree Reversal
 */
static void test() {
    tests::test1();  ///< Single element test
    tests::test2();  ///< No element test
    tests::test3();  ///< Correct reversal test
}

/**
 * @brief main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Mirrors (reverses) a binary tree by swapping each node's left
 * and right children, recursively, starting from the root.
 * @details A tree is "reversed" (mirrored) when, at every node, the
 * left and right subtrees are swapped with each other and this swap
 * cascades all the way down to the leaves. This file implements a
 * small BST class and the recursive mirroring routine.
 */

#include <cassert>   // assert
#include <iostream>  // console IO
#include <queue>     // std::queue
#include <vector>    // std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @namespace mirror_tree
 * @brief Binary tree mirroring implementation
 */
namespace mirror_tree {

/**
 * @brief A single binary tree node holding an integer payload and
 * pointers to its two children.
 */
struct TreeCell {
    int64_t value;      ///< payload stored at this node
    TreeCell* left_kid;  ///< left child (nullptr if absent)
    TreeCell* right_kid;  ///< right child (nullptr if absent)

    explicit TreeCell(int64_t v) {
        value = v;
        left_kid = nullptr;
        right_kid = nullptr;
    }
};

/**
 * @brief A binary search tree wrapper that supports insertion, level
 * order dumping, and mirroring (reversal).
 */
class SearchTree {
 private:
    TreeCell* root_node;

    /**
     * @brief Inserts `value` into the subtree rooted at `node`,
     * keeping BST ordering (smaller values go left).
     * @param value value to insert
     * @param node root of the (sub)tree being inserted into
     * @return the (possibly new) root of this subtree
     */
    TreeCell* insert_at(int64_t value, TreeCell* node) {
        if (node == nullptr) {
            return new TreeCell(value);
        }
        if (value <= node->value) {
            node->left_kid = insert_at(value, node->left_kid);
        } else {
            node->right_kid = insert_at(value, node->right_kid);
        }
        return node;
    }

    /**
     * @brief Recursively mirrors the subtree rooted at `node` by
     * swapping its children (and their children, and so on).
     * @param node root of the (sub)tree to mirror
     * @return the (unchanged pointer to the) root of the mirrored
     * subtree
     */
    TreeCell* mirror_at(TreeCell* node) {
        if (node == nullptr) {
            return node;
        }
        TreeCell* old_left = node->left_kid;
        node->left_kid = mirror_at(node->right_kid);
        node->right_kid = mirror_at(old_left);
        return node;
    }

    SearchTree(const SearchTree&) = delete;
    SearchTree& operator=(const SearchTree&) = delete;

 public:
    /** @brief Builds an empty tree. */
    SearchTree() { root_node = nullptr; }
    /** @brief Builds a tree whose root holds `value`. */
    explicit SearchTree(int64_t value) { root_node = new TreeCell(value); }

    ~SearchTree() {
        std::vector<TreeCell*> stack;
        stack.emplace_back(root_node);
        while (!stack.empty()) {
            TreeCell* current = stack.back();
            stack.pop_back();
            if (current) {
                stack.emplace_back(current->left_kid);
                stack.emplace_back(current->right_kid);
                delete current;
            }
        }
    }

    /** @brief Inserts a new value into the tree. */
    void insert(int64_t value) { root_node = insert_at(value, root_node); }

    /** @brief Mirrors the whole tree in place. */
    void mirror() { root_node = mirror_at(root_node); }

    /**
     * @brief Returns the tree's contents visited top-to-bottom,
     * left-to-right (level order / BFS), using a queue to track the
     * frontier of unvisited nodes.
     * @return vector of values in level order
     */
    std::vector<int64_t> level_order() {
        std::vector<int64_t> values;
        if (root_node == nullptr) {
            return values;
        }
        std::queue<TreeCell*> frontier;
        frontier.push(root_node);
        while (!frontier.empty()) {
            TreeCell* current = frontier.front();
            values.push_back(current->value);
            frontier.pop();
            if (current->left_kid != nullptr) {
                frontier.push(current->left_kid);
            }
            if (current->right_kid != nullptr) {
                frontier.push(current->right_kid);
            }
        }
        return values;
    }

    /** @brief Prints the tree's level-order contents on one line. */
    void show() {
        for (int64_t v : level_order()) {
            std::cout << v << " ";
        }
        std::cout << "\n";
    }
};

}  // namespace mirror_tree
}  // namespace operations_on_datastructures

/**
 * @namespace checks
 * @brief Verification routines for tree mirroring
 */
namespace checks {
using operations_on_datastructures::mirror_tree::SearchTree;

/** @brief Mirroring a single-node tree should be a no-op. */
void check_single_node() {
    SearchTree tree;
    std::vector<int64_t> before, after;
    std::cout << "CHECK 1\n";
    std::cout << "Single-node tree containing 5\n";
    tree.insert(5);
    before = tree.level_order();
    std::cout << "before: ";
    tree.show();
    std::cout << "after: ";
    tree.mirror();
    after = tree.level_order();
    assert(before.size() == after.size());
    assert(before.size() == 1);
    assert(before[0] == after[0]);
    tree.show();
    std::cout << "PASSED\n\n";
}

/** @brief Mirroring an empty tree should remain empty. */
void check_empty_tree() {
    SearchTree tree;
    std::vector<int64_t> before, after;
    std::cout << "CHECK 2\n";
    std::cout << "Empty tree (root is null)\n";
    before = tree.level_order();
    std::cout << "before: ";
    tree.show();
    std::cout << "after: ";
    tree.mirror();
    after = tree.level_order();
    assert(before.size() == after.size());
    assert(before.size() == 0);
    tree.show();
    std::cout << "PASSED\n\n";
}

/** @brief Mirroring a multi-node tree should swap subtrees correctly. */
void check_full_tree() {
    SearchTree tree;
    std::vector<int64_t> before, after;
    std::vector<int64_t> expect_before = {4, 3, 6, 2, 5, 7, 1};
    std::vector<int64_t> expect_after = {4, 6, 3, 7, 5, 2, 1};
    std::cout << "CHECK 3\n";
    std::cout << "Tree built from (4, 6, 3, 2, 5, 7, 1)\n";
    tree.insert(4);
    tree.insert(6);
    tree.insert(3);
    tree.insert(2);
    tree.insert(5);
    tree.insert(7);
    tree.insert(1);
    before = tree.level_order();
    assert(before == expect_before);
    std::cout << "before: ";
    tree.show();
    std::cout << "after: ";
    tree.mirror();
    after = tree.level_order();
    assert(after == expect_after);
    tree.show();
    std::cout << "PASSED\n\n";
}
}  // namespace checks

/**
 * @brief Runs every mirroring check.
 */
static void run_checks() {
    checks::check_single_node();
    checks::check_empty_tree();
    checks::check_full_tree();
}

/**
 * @brief Program entry point.
 */
int main() {
    run_checks();
    return 0;
}

#include <iostream>
using namespace std;

// node defined
class node {
 public:
    int data;
    node *link;
    node(int d) {
        data = d;
        link = NULL;
    }
};

// printing the linked list
void print(node *head) {
    node *current = head;
    while (current != NULL) {
        cout << current->data << " ";
        current = current->link;
    }
    cout << endl;
}

// creating the linked list with 'n' nodes
node *createlist(int n) {
    node *head = NULL;
    node *t = NULL;
    for (int i = 0; i < n; i++) {
        node *temp = NULL;
        int num;
        cin >> num;
        temp = new node(num);
        if (head == NULL) {
            head = temp;
            t = temp;
            continue;
        }
        if (t->link == NULL)
            t->link = temp;
        t = temp;
    }
    return head;
}

// performing selection sort on the linked list in an iterative manner
void my_selection_sort_linked_list(node *&head) {
    node *min = head;  // throughout the algorithm 'min' is used to denote the
                       // node with min value out of all the nodes left for
                       // scanning while scanning if we find a node 'X' with
                       // value lesser than min, then we update the pointers in
                       // such a way that 'X' becomes the predecessor of 'min'
    node *current =
        min->link;  // 'current' refers to the current node we are scanning
    node *previous = min;  //'previous' refers to the node that is previous to
                           // the current node
    node *temp =
        NULL;  // 'temp' in this algo is used to point to the last node of the
               // sorted part of the linked list.
               // eg. If at any time instance the state of the linked list is
               // suppose 1->2->5->3->8->NULL then, we see that "1->2" is the
               // sorted part of the LL, and therefore temp will be pointing to
               // the last node of the sorted part,i.e,'2' We keep on arranging
               // the Linked list in such a way that after each iteration the
               // node with 'min' value is placed at its correct position. Eg.
               // Let suppose initially we have 5->4->1->3->2->NULL After 1st
               // iteration : 1->4->5->3->2->NULL and so on

    while (
        min->link !=
        NULL)  // so that all the nodes are scanned or until there exists a node
    {
        // pick the first node from the unsorted part and assume that it is the
        // minimum and then start scanning from the next node

        while (current != NULL)  // suppose you choose the min node to be X,
                                 // then scan starts from the (X+1)th node until
                                 // its NULL. current = (X+1)th node and min = X
        {
            if (current->data < min->data)  // if the current node is smaller
                                            // than the presumed node 'min'
            {
                if (temp == NULL)  // temp stays null for the first iteration,
                                   // therefore it symbolizes that we are
                                   // scanning for the first time
                {
                    if (previous ==
                        min)  // if the 'previous' is pointing to the 'min' node
                    {
                        // Update the pointers
                        head = current;  // update the head pointer with the
                                         // current node
                        min->link = current->link;
                        current->link = previous;
                        min = current;
                        current = previous->link;
                    } else  // if the 'previous' is not pointing to the 'min'
                            // node
                    {
                        // Update the pointers
                        head = current;  // update the head pointer with the
                                         // current node
                        previous->link = current->link;
                        current->link = min;
                        min = current;
                        current = previous->link;
                    }
                } else  // if 'temp' is not NULL, i.e., its not the 1st
                        // iteration
                {
                    temp->link = current;
                    previous->link = current->link;
                    current->link = min;
                    min = current;
                    current = previous->link;
                }
            } else  // if the current node is greater than min, just move the
                    // previous and the current pointer a step further
            {
                previous = previous->link;
                current = current->link;
            }
        }

        // update the pointers. Set 'temp' to the last node in the sorted part.
        // Make 'min' move a step further so that 'min' points to the 1st node
        // of the unsorted part start the iteration again
        temp = min;
        min = min->link;
        previous = min;
        current = min->link;
    }
}

// Test cases:

// enter the no. of nodes : 5
// 8 9 3 1 4
// original list is : 8 9 3 1 4
// sorted list is : 1 3 4 8 9

// enter the no. of nodes : 3
// -1 -2 -3
// original list is : -1 -2 -3
// sorted list is : -3 -2 -1

// enter the no. of nodes : 8
// 8 7 6 5 4 3 2 1
// original list is : 8 7 6 5 4 3 2 1
// sorted list is : 1 2 3 4 5 6 7 8

// enter the no. of nodes : 6
// 5 3 4 1 -2 -4
// original list is : 5 3 4 1 -2 -4
// sorted list is : -4 -2 1 3 4 5

int main() {
    node *head = NULL;
    int n;
    cout << "enter the no. of nodes : ";  // taking input from user about the
                                          // number of nodes in linked list
    cin >> n;
    if (n == 0)
        return 0;
    head = createlist(n);  // creating the list
    cout << "original list is : ";
    print(head);                          // printing the original linked list
    my_selection_sort_linked_list(head);  // applying selection sort
    cout << "sorted list is : ";
    print(head);  // printing the sorted linked list
    return 0;
}

#include <iostream>
using namespace std;

// A single element of a singly linked list.
class Elem {
 public:
    int data;
    Elem *nxt;
    explicit Elem(int d) {
        data = d;
        nxt = NULL;
    }
};

// Prints the list starting at `head`, space separated, ending with a
// newline.
void printList(Elem *head) {
    Elem *walker = head;
    while (walker != NULL) {
        cout << walker->data << " ";
        walker = walker->nxt;
    }
    cout << endl;
}

// Builds a linked list of `count` nodes by reading `count` integers
// from stdin, in order.
Elem *buildList(int count) {
    Elem *head = NULL;
    Elem *tail = NULL;
    for (int idx = 0; idx < count; idx++) {
        int value;
        cin >> value;
        Elem *fresh = new Elem(value);
        if (head == NULL) {
            head = fresh;
            tail = fresh;
            continue;
        }
        if (tail->nxt == NULL)
            tail->nxt = fresh;
        tail = fresh;
    }
    return head;
}

// Sorts a linked list in place using selection sort, iteratively.
//
// The general idea: keep a pointer `smallest` to the node believed to
// hold the minimum value among all nodes not yet placed in sorted
// order. Scan forward from `smallest` with `scan`; whenever a smaller
// value is found, relink the nodes so that node becomes the new
// `smallest`, positioned right where the previous smallest node was.
// After a full scan, `smallest` holds the true minimum of the
// remaining unsorted section, and we advance past it to continue with
// the rest of the list.
void selectionSortList(Elem *&head) {
    Elem *smallest = head;
    Elem *scan = smallest->nxt;
    Elem *before_scan = smallest;
    Elem *sorted_tail = NULL;  // tail of the already-sorted prefix

    while (smallest->nxt != NULL) {
        while (scan != NULL) {
            if (scan->data < smallest->data) {
                if (sorted_tail == NULL) {
                    // First iteration: no sorted prefix exists yet.
                    if (before_scan == smallest) {
                        head = scan;
                        smallest->nxt = scan->nxt;
                        scan->nxt = before_scan;
                        smallest = scan;
                        scan = before_scan->nxt;
                    } else {
                        head = scan;
                        before_scan->nxt = scan->nxt;
                        scan->nxt = smallest;
                        smallest = scan;
                        scan = before_scan->nxt;
                    }
                } else {
                    sorted_tail->nxt = scan;
                    before_scan->nxt = scan->nxt;
                    scan->nxt = smallest;
                    smallest = scan;
                    scan = before_scan->nxt;
                }
            } else {
                before_scan = before_scan->nxt;
                scan = scan->nxt;
            }
        }

        // `smallest` now holds the minimum of the remaining nodes;
        // extend the sorted prefix past it and restart scanning.
        sorted_tail = smallest;
        smallest = smallest->nxt;
        before_scan = smallest;
        scan = smallest->nxt;
    }
}

// Sample runs:
//
// nodes: 5, input: 8 9 3 1 4  -> sorted: 1 3 4 8 9
// nodes: 3, input: -1 -2 -3   -> sorted: -3 -2 -1
// nodes: 8, input: 8 7 6 5 4 3 2 1 -> sorted: 1 2 3 4 5 6 7 8
// nodes: 6, input: 5 3 4 1 -2 -4 -> sorted: -4 -2 1 3 4 5

int main() {
    Elem *head = NULL;
    int count;
    cout << "enter the no. of nodes : ";
    cin >> count;
    if (count == 0)
        return 0;
    head = buildList(count);
    cout << "original list is : ";
    printList(head);
    selectionSortList(head);
    cout << "sorted list is : ";
    printList(head);
    return 0;
}

/**
 * @file
 * @brief [Trie
 * datastructure](https://iq.opengenus.org/autocomplete-using-trie-data-structure/)
 * with search variants
 * @details
 * This provides multiple variants of search functions
 * on a trie structure utilizing STL. The trie is valid
 * for only English alphabets.
 * @author [Ghanashyam](https://github.com/g-s-k-zoro)
 */

#include <algorithm>  /// for std::count
#include <cassert>    /// for assert
#include <cctype>     /// for tolower
#include <cstdint>    /// for std::uint32_t
#include <cstring>    /// for string operations
#include <iostream>   /// for IO Operations
#include <queue>      /// for std::priority_queue

/**
 * @namespace operations_on_datastructures
 * @brief Operations on data structures
 */
namespace operations_on_datastructures {
/**
 * @namespace trie_operations
 * @brief Functions for [Trie
 * datastructure](https://iq.opengenus.org/autocomplete-using-trie-data-structure/)
 * implementation
 */
namespace trie_operations {
/**
 * @brief Class defining the structure of trie node and containing the methods
 * to perform operations on them.
 */
class Tnode {
 private:
    static constexpr uint8_t ENGLISH_ALPHABET_SIZE = 26;
    // pointers to alphabets
    std::vector<Tnode *> english;

    // To mark the end of word
    bool endOfWord;

    // To store the frequency of searches for the word
    uint32_t frequency;

 public:
    Tnode() {
        english.resize(ENGLISH_ALPHABET_SIZE, nullptr);
        endOfWord = false;
        frequency = 0;
    }
    // Copy Constructor
    Tnode(const Tnode &node) {
        english = node.english;
        endOfWord = node.endOfWord;
        frequency = node.frequency;
    }

    Tnode &operator=(const Tnode &node) = default;

    Tnode(Tnode &&) = default;

    Tnode &operator=(Tnode &&) = default;
    /**
     * @brief Function to count the number of children a node in the trie has
     * @param node a trie node whose children need to be counted
     * @return count of the number of children of the given node (max 26)
     */
    inline uint8_t numberOfChildren(Tnode *node) {
        return ENGLISH_ALPHABET_SIZE -
               std::count(node->english.begin(), node->english.end(), nullptr);
    }

    // Functions to perform operations on trie
    void Insert(const std::string &entry);
    void Delete(std::string entry);
    void DeleteFrom(Tnode *delete_from, std::string delete_string,
                    int remove_index);
    bool SearchPresence(const std::string &key);
    void SuggestAutocomplete(Tnode *new_root, const std::string &prefix);
    void SearchSuggestions(const std::string &key);
    void SuggestFreqAutocomplete(
        Tnode *new_root, const std::string &prefix,
        std::priority_queue<std::pair<int, std::string> > *suggestions);
    void SearchFreqSuggestions(const std::string &key);
    void SelectionTop_3(
        std::priority_queue<std::pair<int, std::string> > *suggestions);

    // To free up the dynamically allocated objects
    ~Tnode() {
        int i = 0;
        for (i = 0; i < ENGLISH_ALPHABET_SIZE; i++) {
            if (english[i]) {
                delete english[i];
            }
        }
    }
};

/**
 * @brief Function to insert a word in the trie
 * @param entry string entry to be inserted in the trie
 */
void Tnode::Insert(const std::string &entry) {
    Tnode *cur_pos = this;
    int letter_index = 0;

    for (auto &i : entry) {
        // To ignore case
        letter_index = tolower(i) - 97;

        // Allocate a node for each character of entry if not present in the
        // trie
        if (cur_pos->english[letter_index] == nullptr) {
            cur_pos->english[letter_index] = new Tnode();
        }

        cur_pos = cur_pos->english[letter_index];
    }
    // cur_pos points to the last char, mark it as end of word
    cur_pos->endOfWord = true;
}

/**
 * @brief Function recursively deletes the substring character by
 * character iterating through the string to be deleted. It traverses till the
 * end of word in a recursive fashion, from there it deletes characters one by
 * one till it reaches back to the initial call.
 * @param delete_from the acting root to the required suffix to be deleted
 * @param delete_string the string to be deleted from the trie
 * @param remove_index index denoting the beginning of the substring to be
 * deleted
 */
void Tnode::DeleteFrom(Tnode *delete_from, std::string delete_string,
                       int remove_index) {
    if (delete_string.size() == remove_index) {
        int letter_index = tolower(delete_string[remove_index]) - 97;

        DeleteFrom(delete_from->english[letter_index], delete_string,
                   remove_index + 1);

        delete delete_from;
    }
}

/**
 * @brief Function to verify presence and hence delete an entry from the trie
 * @param entry string entry to be deleted from the trie
 */
void Tnode::Delete(std::string entry) {
    Tnode *cur_pos = this,
          *delete_from = this;  // Current pointer pointing to root
    int letter_index = 0, delete_from_index = 0, i = 0, n = entry.size();

    for (i = 0; i < n; i++) {
        // To ignore case
        letter_index = tolower(entry[i]) - 97;

        // Display error message when given entry is not present in the tree
        if (cur_pos->english[letter_index] == nullptr) {
            std::cout << "Entry not Found" << std::endl;
            return;
        }
        // If the current node is end of word for the current prefix or if it
        // has 2 or more branches It cannot be deleted while deleting the
        // required entry.
        if (numberOfChildren(cur_pos) > 1 || cur_pos->endOfWord) {
            delete_from = cur_pos;      // denotes the beginning of the shortest
                                        // suffix that is allowed to be deleted
            delete_from_index = i - 1;  // Beginning index of the suffix
                                        // corresponding to the 'entry'
        }

        // Traversing through the entry
        cur_pos = cur_pos->english[letter_index];
    }

    // cur_pos now points to the last char of entry. Display message if that
    // entry does not exist
    if (!cur_pos->endOfWord) {
        std::cout << "Entry not Found" << std::endl;
        return;
    }

    // If cur_pos is not a leaf node, unmark end of word and assign 0 to it's
    // frequency for deletion
    if (numberOfChildren(cur_pos)) {
        cur_pos->endOfWord = false;
        cur_pos->frequency = 0;
        return;
    }

    // The first character of the suffix to be deleted
    letter_index = tolower(entry[delete_from_index + 1]) - 97;
    // Point cur_pos to the next node
    cur_pos = delete_from->english[letter_index];
    // Sever the connection from the main trie
    delete_from->english[letter_index] = nullptr;

    // If number of characters in the suffix are more than 1, recursively delete
    // each character starting from cur_pos using the helper function
    if (n > delete_from_index + 2) {
        DeleteFrom(cur_pos, entry, delete_from_index + 2);
    }
    // If the suffix is only 1 char in length
    else {
        delete cur_pos;
    }
}

/**
 * @brief Function to check a word's presence in the trie (Basic)
 * @param key the string key to be searched in the trie
 * @return true if the key is found
 * @return false if the key is not found
 */
bool Tnode::SearchPresence(const std::string &key) {
    Tnode *cur_pos = this;
    int letter_index = 0;

    for (auto &i : key) {
        letter_index = tolower(i) - 97;
        // If any character in the order of the key is absent, word not found!
        if (cur_pos->english[letter_index] == nullptr) {
            return false;
        }
        cur_pos = cur_pos->english[letter_index];
    }
    // Word is only present in the trie if the key is a valid complete entry and
    // not just a prefix.
    if (cur_pos->endOfWord) {
        (cur_pos->frequency)++;
        return true;
    } else {
        return false;
    }
}

/**
 * @brief Recursive function to suggest all the entries of trie
 * which have a given common prefix
 * @param new_root pointer pointing to the node corresponding to the last char
 * of prefix
 * @param prefix the common prefix that all the suggestions must have
 */
void Tnode::SuggestAutocomplete(Tnode *new_root, const std::string &prefix) {
    // Iterate through all 26 nodes as we have to print all strings with the
    // given prefix
    int i = 0;
    for (i = 0; i < ENGLISH_ALPHABET_SIZE; i++) {
        if (new_root->english[i] != nullptr) {
            // Print the sugestion only if it's a valid complete entry and not
            // just a prefix
            if (new_root->english[i]->endOfWord) {
                std::cout << prefix + char(i + 97) << std::endl;
            }

            SuggestAutocomplete(new_root->english[i], prefix + char(i + 97));
        }
    }
}

/**
 * @brief Lists out all the words in trie with the longest prefix
 * of the search key that is present in the trie. For example - if trie contains
 * "abc", "abcde", "abcdefg", "abcddef" and if the search key is "abcdezz", then
 * the longest common prefix is "abcde" and hence search results will be
 * "abcde", "abcdefg".
 * @param key the string key to be searched for suggestions
 */
void Tnode::SearchSuggestions(const std::string &key) {
    Tnode *cur_pos = nullptr, *prev_pos = nullptr;
    cur_pos = prev_pos = this;  // maintaining 2 pointers, initialized to root
    int letter_index = 0;
    std::string prefix =
        "";  // variable storing the updated value of longest common prefix

    for (auto &i : key) {
        letter_index = tolower(i) - 97;
        prev_pos = cur_pos;  // Previous pointer updated to point to the last
                             // char of the longest common prefix

        // When the node for the character does not exist, longest prefix has
        // been determined and SuggestAutocomplete is called
        if (cur_pos->english[letter_index] == nullptr) {
            SuggestAutocomplete(prev_pos, prefix);
            std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
                      << std::endl;
            return;
        }
        // Updating the longest common prefix
        prefix += char(tolower(i));
        cur_pos = cur_pos->english[letter_index];
    }
    // If the key is a valid entry of trie, display it @ top of the suggestions
    if (cur_pos->endOfWord) {
        std::cout << key << std::endl;
        (cur_pos->frequency)++;
    }

    (void)prev_pos;  // Idiom to ignore previous pointer

    // Call for suggestions when the search key is present as an entry/a prefix
    // in the trie
    SuggestAutocomplete(cur_pos, prefix);
    std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
              << std::endl;
    return;
}

/**
 * @brief Function to display the 3 suggestions with highest frequency
 * of search hits
 * @param suggestions a max heap that contains pairs of (frequency, word)
 * heapified based on frequency
 */
void Tnode::SelectionTop_3(
    std::priority_queue<std::pair<int, std::string> > *suggestions) {
    // Display Either top 3 or total number of suggestions, whichever is smaller
    int n = suggestions->size(), Top = 0;
    Top = n < 3 ? n : 3;
    while (Top--) {
        std::cout << suggestions->top().second << std::endl;
        suggestions->pop();
    }
}

/**
 * @brief Recursive function to suggest most frequently
 * searched entries of trie which have a given common prefix
 * @param new_root pointer pointing to the node corresponding to the last char
 * of prefix
 * @param prefix the common prefix that all the suggestions must have
 * @param suggestions a max heap that contains pairs of (frequency, word)
 * heapified based on frequency
 */
void Tnode::SuggestFreqAutocomplete(
    Tnode *new_root, const std::string &prefix,
    std::priority_queue<std::pair<int, std::string> > *suggestions) {
    int i = 0;
    for (i = 0; i < ENGLISH_ALPHABET_SIZE; i++) {
        if (new_root->english[i] != nullptr) {
            // Add to sugestions only if it's a valid complete entry and not
            // just a prefix
            if (new_root->english[i]->endOfWord) {
                suggestions->push(std::make_pair(
                    new_root->english[i]->frequency, prefix + char(i + 97)));
            }

            SuggestFreqAutocomplete(new_root->english[i], prefix + char(i + 97),
                                    suggestions);
        }
    }
}

/**
 * @brief Lists out the most frequent words in trie with the
 * longest prefix of the search key that is present in the trie. For example -
 * if trie contains "abc", "abcde", "abcdefg", "abcddef" and they have been
 * previously searched for 3, 1, 2, 4 times respectively, if the search key is
 * "ab", then the longest common prefix is "ab" and only the top 3 frequencies
 * among the matches would be displayed viz. "abcddef", "abc", "abcdefg".
 * @param key the string key to be searched for suggestions
 */
void Tnode::SearchFreqSuggestions(const std::string &key) {
    Tnode *cur_pos = nullptr, *prev_pos = nullptr;
    cur_pos = prev_pos = this;  // maintaining 2 pointers, initialized to root
    int letter_index = 0;
    std::string prefix =
        "";  // variable storing the updated value of longest common prefix
    std::priority_queue<std::pair<int, std::string> >
        suggestions;  // max heap to store (frequency, word) in descending order
                      // of freq

    std::priority_queue<std::pair<int, std::string> > *Suggestions =
        &suggestions;

    for (auto &i : key) {
        letter_index = tolower(i) - 97;
        prev_pos = cur_pos;  // Previous pointer updated to point to the last
                             // char of the longest common prefix

        // When the node for the character does not exist, longest prefix has
        // been determined and SuggestFreqAutocomplete is called
        if (cur_pos->english[letter_index] == nullptr) {
            SuggestFreqAutocomplete(prev_pos, prefix, Suggestions);
            // To display the top 3 results
            SelectionTop_3(Suggestions);
            std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
                      << std::endl;
            return;
        }
        // Updating the longest common prefix
        prefix += char(tolower(i));
        cur_pos = cur_pos->english[letter_index];
    }
    // If the key is a valid entry of trie, display it @ top of the suggestions
    if (cur_pos->endOfWord) {
        (cur_pos->frequency)++;
        std::cout << key << std::endl;
    }

    (void)prev_pos;  // Idiom to ignore previous pointer

    // Call for Suggestions when the search key is present as an entry/a prefix
    // in the trie
    SuggestFreqAutocomplete(cur_pos, prefix, Suggestions);
    // Display the top 3 results
    SelectionTop_3(Suggestions);

    std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
              << std::endl;
    return;
}
}  // namespace trie_operations
}  // namespace operations_on_datastructures

/**
 * @brief Function to test a simple search before and after deleting
 * an entry. And to test out the multiple variants of search.
 */
static void test() {
    auto root = new operations_on_datastructures::trie_operations::Tnode();
    std::vector<std::string> inputs = {
        "abcde", "sss",    "ssss",  "ssst", "sssu", "sssv",
        "sst",   "ssts",   "sstt",  "sstu", "tutu", "tutuv",
        "tutuu", "tutuvs", "tutus", "tvst", "tvsu", "vvvv"};

    for (auto &i : inputs) {
        root->Insert(i);
    }
    // Search an existing entry
    assert(root->SearchPresence("vvvv"));
    std::cout << root->SearchPresence("vvvv") << std::endl;
    // Delete it
    root->Delete("vvvv");
    // Search for the entry again
    assert(!root->SearchPresence("vvvv"));
    std::cout << root->SearchPresence("vvvv") << std::endl;

    std::cout << root->SearchPresence("tutu") << std::endl;
    root->SearchSuggestions("tutu");
    std::cout << root->SearchPresence("tutu") << std::endl;

    root->SearchSuggestions("tutuv");
    std::cout << root->SearchPresence("tutuv") << std::endl;

    root->SearchSuggestions("tutuvs");

    root->SearchFreqSuggestions(
        "tu");  // The top 3 frequent entries with prefix tu are tutu, tutuv &
                // tutuvs respectively
    root->SearchSuggestions(
        "");  // Empty search to list all the entries in the trie
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief A prefix-tree (trie) supporting several distinct kinds of
 * lookup, built on the STL.
 * @details Beyond basic membership testing, this trie can suggest
 * autocomplete-style word completions for a given prefix, and can
 * additionally rank those completions by how often they have been
 * searched for previously. Only lowercase/uppercase English letters are
 * supported (case is folded to lowercase internally).
 */

#include <algorithm>  // std::count
#include <cassert>    // assert
#include <cctype>     // tolower
#include <cstdint>    // std::uint32_t
#include <cstring>    // string helpers
#include <iostream>   // console IO
#include <queue>      // std::priority_queue
#include <string>     // std::string
#include <vector>     // std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on data structures
 */
namespace operations_on_datastructures {
/**
 * @namespace prefix_tree
 * @brief A trie supporting insert/delete/search plus autocomplete-style
 * suggestion features
 */
namespace prefix_tree {

/**
 * @brief A single node of the trie, along with the operations used to
 * manipulate the structure it's part of.
 */
class TrieNode {
 private:
    static constexpr uint8_t ALPHABET_SIZE = 26;
    // One child slot per lowercase letter.
    std::vector<TrieNode *> children;

    // Marks whether a complete word ends at this node.
    bool is_terminal;

    // How many times a search has landed exactly on this node.
    uint32_t hit_count;

 public:
    TrieNode() {
        children.resize(ALPHABET_SIZE, nullptr);
        is_terminal = false;
        hit_count = 0;
    }
    TrieNode(const TrieNode &other) {
        children = other.children;
        is_terminal = other.is_terminal;
        hit_count = other.hit_count;
    }

    TrieNode &operator=(const TrieNode &other) = default;
    TrieNode(TrieNode &&) = default;
    TrieNode &operator=(TrieNode &&) = default;

    /**
     * @brief Counts how many non-null child slots a node has.
     * @param node the node whose children should be counted
     * @return number of populated children (0-26)
     */
    inline uint8_t child_count(TrieNode *node) {
        return ALPHABET_SIZE -
               std::count(node->children.begin(), node->children.end(),
                          nullptr);
    }

    void insert_word(const std::string &word);
    void remove_word(std::string word);
    void prune_from(TrieNode *from_node, std::string word, int from_index);
    bool contains(const std::string &word);
    void collect_completions(TrieNode *subtree_root, const std::string &prefix);
    void suggest_for(const std::string &key);
    void collect_ranked_completions(
        TrieNode *subtree_root, const std::string &prefix,
        std::priority_queue<std::pair<int, std::string> > *ranked);
    void suggest_ranked_for(const std::string &key);
    void print_top_3(std::priority_queue<std::pair<int, std::string> > *ranked);

    ~TrieNode() {
        for (int idx = 0; idx < ALPHABET_SIZE; idx++) {
            if (children[idx]) {
                delete children[idx];
            }
        }
    }
};

/**
 * @brief Inserts a word into the trie one character at a time,
 * allocating nodes as needed.
 * @param word the word to insert (case-insensitive)
 */
void TrieNode::insert_word(const std::string &word) {
    TrieNode *cursor = this;
    int slot = 0;

    for (auto &ch : word) {
        slot = tolower(ch) - 97;

        if (cursor->children[slot] == nullptr) {
            cursor->children[slot] = new TrieNode();
        }

        cursor = cursor->children[slot];
    }
    cursor->is_terminal = true;
}

/**
 * @brief Helper that recursively frees a chain of single-child nodes
 * that no longer lead to any remaining word.
 * @param from_node node marking the start of the dangling suffix
 * @param word the word being removed
 * @param from_index index into `word` where deletion should resume
 */
void TrieNode::prune_from(TrieNode *from_node, std::string word,
                           int from_index) {
    if (word.size() == from_index) {
        int slot = tolower(word[from_index]) - 97;

        prune_from(from_node->children[slot], word, from_index + 1);

        delete from_node;
    }
}

/**
 * @brief Removes a word from the trie if present, pruning any nodes
 * that become unnecessary as a result.
 * @param word the word to remove
 */
void TrieNode::remove_word(std::string word) {
    TrieNode *cursor = this, *prune_anchor = this;
    int slot = 0, prune_anchor_index = 0, idx = 0, len = word.size();

    for (idx = 0; idx < len; idx++) {
        slot = tolower(word[idx]) - 97;

        if (cursor->children[slot] == nullptr) {
            std::cout << "Entry not Found" << std::endl;
            return;
        }
        // A node can't be pruned away if it terminates another word or
        // branches into 2+ other paths.
        if (child_count(cursor) > 1 || cursor->is_terminal) {
            prune_anchor = cursor;
            prune_anchor_index = idx - 1;
        }

        cursor = cursor->children[slot];
    }

    if (!cursor->is_terminal) {
        std::cout << "Entry not Found" << std::endl;
        return;
    }

    // If this node still has children, just unmark it rather than
    // deleting it outright.
    if (child_count(cursor)) {
        cursor->is_terminal = false;
        cursor->hit_count = 0;
        return;
    }

    slot = tolower(word[prune_anchor_index + 1]) - 97;
    cursor = prune_anchor->children[slot];
    prune_anchor->children[slot] = nullptr;

    if (len > prune_anchor_index + 2) {
        prune_from(cursor, word, prune_anchor_index + 2);
    } else {
        delete cursor;
    }
}

/**
 * @brief Checks whether `word` is present in the trie as a complete
 * entry (not merely a prefix of some other entry).
 * @param word the word to look up
 * @return true if found, false otherwise
 */
bool TrieNode::contains(const std::string &word) {
    TrieNode *cursor = this;
    int slot = 0;

    for (auto &ch : word) {
        slot = tolower(ch) - 97;
        if (cursor->children[slot] == nullptr) {
            return false;
        }
        cursor = cursor->children[slot];
    }
    if (cursor->is_terminal) {
        (cursor->hit_count)++;
        return true;
    }
    return false;
}

/**
 * @brief Recursively walks every branch under `subtree_root`, printing
 * any complete words found.
 * @param subtree_root node to start walking from
 * @param prefix the prefix accumulated so far on the path to this node
 */
void TrieNode::collect_completions(TrieNode *subtree_root,
                                    const std::string &prefix) {
    for (int idx = 0; idx < ALPHABET_SIZE; idx++) {
        if (subtree_root->children[idx] != nullptr) {
            if (subtree_root->children[idx]->is_terminal) {
                std::cout << prefix + char(idx + 97) << std::endl;
            }

            collect_completions(subtree_root->children[idx],
                                 prefix + char(idx + 97));
        }
    }
}

/**
 * @brief Lists every stored word that shares the longest prefix of
 * `key` present in the trie. E.g. if the trie has "abc", "abcde",
 * "abcdefg", "abcddef" and the key is "abcdezz", the longest matching
 * prefix is "abcde", so completions under "abcde" are reported.
 * @param key the search key
 */
void TrieNode::suggest_for(const std::string &key) {
    TrieNode *cursor = nullptr, *last_valid = nullptr;
    cursor = last_valid = this;
    int slot = 0;
    std::string matched_prefix = "";

    for (auto &ch : key) {
        slot = tolower(ch) - 97;
        last_valid = cursor;

        if (cursor->children[slot] == nullptr) {
            collect_completions(last_valid, matched_prefix);
            std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
                      << std::endl;
            return;
        }
        matched_prefix += char(tolower(ch));
        cursor = cursor->children[slot];
    }
    if (cursor->is_terminal) {
        std::cout << key << std::endl;
        (cursor->hit_count)++;
    }

    (void)last_valid;

    collect_completions(cursor, matched_prefix);
    std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
              << std::endl;
    return;
}

/**
 * @brief Prints the top (up to) 3 entries from a max-heap of
 * (hit_count, word) pairs, in descending order of hit count.
 * @param ranked pointer to the priority queue of candidates
 */
void TrieNode::print_top_3(
    std::priority_queue<std::pair<int, std::string> > *ranked) {
    int total = ranked->size(), show = 0;
    show = total < 3 ? total : 3;
    while (show--) {
        std::cout << ranked->top().second << std::endl;
        ranked->pop();
    }
}

/**
 * @brief Like collect_completions, but pushes (hit_count, word) pairs
 * into a max-heap instead of printing directly.
 * @param subtree_root node to start walking from
 * @param prefix accumulated prefix on the path to this node
 * @param ranked heap collecting (hit_count, word) pairs
 */
void TrieNode::collect_ranked_completions(
    TrieNode *subtree_root, const std::string &prefix,
    std::priority_queue<std::pair<int, std::string> > *ranked) {
    for (int idx = 0; idx < ALPHABET_SIZE; idx++) {
        if (subtree_root->children[idx] != nullptr) {
            if (subtree_root->children[idx]->is_terminal) {
                ranked->push(std::make_pair(subtree_root->children[idx]->hit_count,
                                             prefix + char(idx + 97)));
            }

            collect_ranked_completions(subtree_root->children[idx],
                                        prefix + char(idx + 97), ranked);
        }
    }
}

/**
 * @brief Like suggest_for, but reports only the top 3 most-frequently
 * searched completions for the longest matching prefix of `key`.
 * @param key the search key
 */
void TrieNode::suggest_ranked_for(const std::string &key) {
    TrieNode *cursor = nullptr, *last_valid = nullptr;
    cursor = last_valid = this;
    int slot = 0;
    std::string matched_prefix = "";
    std::priority_queue<std::pair<int, std::string> > ranked;

    std::priority_queue<std::pair<int, std::string> > *ranked_ptr = &ranked;

    for (auto &ch : key) {
        slot = tolower(ch) - 97;
        last_valid = cursor;

        if (cursor->children[slot] == nullptr) {
            collect_ranked_completions(last_valid, matched_prefix, ranked_ptr);
            print_top_3(ranked_ptr);
            std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
                      << std::endl;
            return;
        }
        matched_prefix += char(tolower(ch));
        cursor = cursor->children[slot];
    }
    if (cursor->is_terminal) {
        (cursor->hit_count)++;
        std::cout << key << std::endl;
    }

    (void)last_valid;

    collect_ranked_completions(cursor, matched_prefix, ranked_ptr);
    print_top_3(ranked_ptr);

    std::cout << "- - - - - - - - - - - - - - - - - - - - - - - - - - "
              << std::endl;
    return;
}
}  // namespace prefix_tree
}  // namespace operations_on_datastructures

/**
 * @brief Exercises basic search, deletion, and the various suggestion
 * modes offered by the trie.
 */
static void run_checks() {
    auto trie_root = new operations_on_datastructures::prefix_tree::TrieNode();
    std::vector<std::string> words = {
        "abcde", "sss",    "ssss",  "ssst", "sssu", "sssv",
        "sst",   "ssts",   "sstt",  "sstu", "tutu", "tutuv",
        "tutuu", "tutuvs", "tutus", "tvst", "tvsu", "vvvv"};

    for (auto &w : words) {
        trie_root->insert_word(w);
    }
    // Look up something that exists.
    assert(trie_root->contains("vvvv"));
    std::cout << trie_root->contains("vvvv") << std::endl;
    // Remove it.
    trie_root->remove_word("vvvv");
    // Confirm it's gone.
    assert(!trie_root->contains("vvvv"));
    std::cout << trie_root->contains("vvvv") << std::endl;

    std::cout << trie_root->contains("tutu") << std::endl;
    trie_root->suggest_for("tutu");
    std::cout << trie_root->contains("tutu") << std::endl;

    trie_root->suggest_for("tutuv");
    std::cout << trie_root->contains("tutuv") << std::endl;

    trie_root->suggest_for("tutuvs");

    trie_root->suggest_ranked_for("tu");
    trie_root->suggest_for("");
}

/**
 * @brief Program entry point.
 */
int main() {
    run_checks();
    return 0;
}

/**
 * @file
 * @brief Implementation for the [Union of two sorted
 * Arrays](https://en.wikipedia.org/wiki/Union_(set_theory))
 * algorithm.
 * @details The Union of two arrays is the collection of all the unique elements
 * in the first array, combined with all of the unique elements of a second
 * array. This implementation uses ordered arrays, and an algorithm to correctly
 * order them and return the result as a new array (vector).
 * @see intersection_of_two_arrays.cpp
 * @author [Alvin](https://github.com/polarvoid)
 */

#include <algorithm>  /// for std::sort
#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/**
 * @namespace operations_on_datastructures
 * @brief Operations on Data Structures
 */
namespace operations_on_datastructures {

/**
 * @brief Prints the values of a vector sequentially, ending with a newline
 * character.
 * @param array Reference to the array to be printed
 * @returns void
 */
void print(const std::vector<int32_t> &array) {
    for (int32_t i : array) {
        std::cout << i << " ";  /// Print each value in the array
    }
    std::cout << "\n";  /// Print newline
}

/**
 * @brief Gets the union of two sorted arrays, and returns them in a
 * vector.
 * @details An algorithm is used that compares the elements of the two vectors,
 * appending the one that has a lower value, and incrementing the index for that
 * array. If one of the arrays reaches its end, all the elements of the other
 * are appended to the resultant vector.
 * @param first A std::vector of sorted integer values
 * @param second A std::vector of sorted integer values
 * @returns A std::vector of the union of the two arrays, in ascending order
 */
std::vector<int32_t> get_union(const std::vector<int32_t> &first,
                               const std::vector<int32_t> &second) {
    std::vector<int32_t> res;         ///< Vector to hold the union
    size_t f_index = 0;               ///< Index for the first array
    size_t s_index = 0;               ///< Index for the second array
    size_t f_length = first.size();   ///< Length of first array
    size_t s_length = second.size();  ///< Length of second array
    int32_t next = 0;  ///< Integer to store value of the next element

    while (f_index < f_length && s_index < s_length) {
        if (first[f_index] < second[s_index]) {
            next = first[f_index];  ///< Append from first array
            f_index++;              ///< Increment index of second array
        } else if (first[f_index] > second[s_index]) {
            next = second[s_index];  ///< Append from second array
            s_index++;               ///< Increment index of second array
        } else {
            next = first[f_index];  ///< Element is the same in both
            f_index++;              ///< Increment index of first array
            s_index++;              ///< Increment index of second array too
        }
        if ((res.size() == 0) || (next != res.back())) {
            res.push_back(next);  ///< Add the element if it is unique
        }
    }
    while (f_index < f_length) {
        next = first[f_index];  ///< Add remaining elements
        if ((res.size() == 0) || (next != res.back())) {
            res.push_back(next);  ///< Add the element if it is unique
        }
        f_index++;
    }
    while (s_index < s_length) {
        next = second[s_index];  ///< Add remaining elements
        if ((res.size() == 0) || (next != res.back())) {
            res.push_back(next);  ///< Add the element if it is unique
        }
        s_index++;
    }
    return res;
}

}  // namespace operations_on_datastructures

