/**
 * @file
 * @brief Finds the maximum sum of any contiguous run of elements in an array
 * (a.k.a. Kadane's algorithm).
 * @details
 * Given a fixed-size array, scan it once, keeping a running sum that resets
 * to zero whenever it goes negative, while tracking the best running sum
 * ever seen. If every element is negative, the result degenerates to the
 * largest (least negative) single element.
 */

#include <array>     /// for std::array
#include <cassert>   /// for assert
#include <climits>   /// for INT_MIN value
#include <cstdint>
#include <iostream>  /// for IO operations

/**
 * @brief Scans the array once and returns the best contiguous-sum found.
 * \param values fixed-size input array
 * \param count number of valid elements to consider
 * \returns the maximum contiguous subarray sum
 */
template <std::size_t CAP>
int64_t bestContiguousSum(std::array<int64_t, CAP> values, uint64_t count) {
    int64_t bestSoFar = INT_MIN;
    int64_t runningSum = 0;

    for (uint64_t idx = 0; idx < count; ++idx) {
        runningSum += values[idx];
        if (runningSum > bestSoFar) {
            bestSoFar = runningSum;
        }
        if (runningSum < 0) {
            runningSum = 0;
        }
    }
    return bestSoFar;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void runSelfTests() {
    std::array<int64_t, 4> allPositive = {1, 2, 3, 4};
    std::array<int64_t, 5> mixedValues = {-1, -2, -4, -6, 7};
    assert(bestContiguousSum(allPositive, 4) == 10);
    assert(bestContiguousSum(mixedValues, 5) == 7);
    std::cout << "All test cases have passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    // Interactive input is intentionally disabled below so the self-test
