}

/**
 * @file
 * @brief Conversion from [Kelvin to
 * Celsius](https://byjus.com/chemistry/kelvin-to-celsius/) degrees.
 * @details
 * The algorithm consists on converting a Kelvin degree value to a Celsius
 * value.
 * The formula to convert a Kelvin to a Celsius value is:
 * @f[ C = K - 273.15 @f] where:
 * - C is the Celsius temperature
 * - K is the Kelvin temperature
 *
 * Check out [Kelvin](https://en.wikipedia.org/wiki/Kelvin) and
 * [Celsius](https://en.wikipedia.org/wiki/Celsius) on Wikipedia for more
 * information about their story, how do they work, when and why they should be
 * used, etc..
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <cassert>   /// for assert
#include <cmath>     /// for std::abs
#include <iostream>  /// for IO operations

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {
/**
 * @brief Compare two floating point numbers with a certain tolerance.
 * This is needed as with some values, the result (e.g.: -196.15) might be a bit
 * lower (in this case, -196.499999...).
 * @param a the first number to compare
 * @param b the second number to compare
 * @param tolerance the tolerance to use when comparing the numbers
 * @returns true if the numbers ARE equal within the given tolerance
 * @returns false if the numbers are NOT equal within the given tolerance
 * otherwise
 */
bool are_almost_equal(double a, double b, double absolute_tolerance = 0.0001) {
    return std::abs(a - b) < absolute_tolerance;
}

/**
 * @brief Conversion from Kelvin to Celsius algorithm.
 * @param number the Celsius number that will be used to convert
 * @returns the Kelvin number converted to Celsius
 */
double kelvin_to_celsius(double temperature_in_k) {
    const double absolute_zero_in_c = -273.15;
    if (temperature_in_k < absolute_zero_in_c) {
        throw std::invalid_argument("input temperature below absolute zero");
    }
    return temperature_in_k + absolute_zero_in_c;
}
}  // namespace others

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    assert(others::are_almost_equal(others::kelvin_to_celsius(230), -43.15));
    assert(others::are_almost_equal(others::kelvin_to_celsius(512), 238.85));
    assert(others::are_almost_equal(others::kelvin_to_celsius(55), -218.15));
    assert(others::are_almost_equal(others::kelvin_to_celsius(77), -196.15));
    assert(others::are_almost_equal(others::kelvin_to_celsius(9.78), -263.37));
    assert(others::are_almost_equal(others::kelvin_to_celsius(15), -258.15));
    assert(others::are_almost_equal(others::kelvin_to_celsius(273.15), 0));

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Converts a temperature expressed in Kelvin into degrees Celsius.
 * @details
 * Conversion formula: C = K - 273.15
 */

#include <cassert>   /// for assert
#include <cmath>     /// for std::abs
#include <iostream>  /// for IO operations

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {
/**
 * @brief Checks whether two doubles are close enough to be considered equal,
 * to work around floating point rounding noise.
 * @param lhs first value
 * @param rhs second value
 * @param eps maximum allowed difference
 * @returns true if |lhs - rhs| is within eps
 */
bool nearly_equal(double lhs, double rhs, double eps = 0.0001) {
    return std::abs(lhs - rhs) < eps;
}

/**
 * @brief Converts a Kelvin temperature to Celsius.
 * @param kelvinValue temperature expressed in Kelvin
 * @returns the equivalent Celsius temperature
 * @throws std::invalid_argument if the value is below absolute zero
 */
double kelvin_to_celsius(double kelvinValue) {
    constexpr double kAbsoluteZeroCelsius = -273.15;
    if (kelvinValue < kAbsoluteZeroCelsius) {
        throw std::invalid_argument("input temperature below absolute zero");
    }
    return kelvinValue + kAbsoluteZeroCelsius;
}
}  // namespace others

/**
 * @brief Self-test implementations
 * @returns void
 */
static void runChecks() {
    assert(others::nearly_equal(others::kelvin_to_celsius(230), -43.15));
    assert(others::nearly_equal(others::kelvin_to_celsius(512), 238.85));
    assert(others::nearly_equal(others::kelvin_to_celsius(55), -218.15));
    assert(others::nearly_equal(others::kelvin_to_celsius(77), -196.15));
    assert(others::nearly_equal(others::kelvin_to_celsius(9.78), -263.37));
    assert(others::nearly_equal(others::kelvin_to_celsius(15), -258.15));
    assert(others::nearly_equal(others::kelvin_to_celsius(273.15), 0));

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation for [LFU Cache]
 * (https://en.wikipedia.org/wiki/Least_frequently_used)
 *
 * @details
 * LFU discards the least frequently used value. if there are multiple items
 * with the same minimum frequency then, the least recently used among them is
 * discarded. Data structures used - doubly linked list and unordered_map(hash
 * map).
 *
 * Hashmap maps the key to the address of the node of the linked list and its
 * current usage frequency. If the element is accessed the element is removed
 * from the linked list of the current frequency and added to the linked list of
 * incremented frequency.
 *
 * When the cache is full, the last element in the minimum frequency linked list
 * is popped.
 *
 * @author [Karan Sharma](https://github.com/deDSeC00720)
 */

#include <cassert>        // for assert
#include <iostream>       // for std::cout
#include <unordered_map>  // for std::unordered_map

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {

/**
 * @namespace
 * @brief Cache algorithm
 */
namespace Cache {

/**
 * @class
 * @brief Node for a doubly linked list with data, prev and next pointers
 * @tparam T type of the data of the node
 */
template <typename T>
class D_Node {
 public:
    T data;           ///< data of the node
    D_Node<T> *prev;  ///< previous node in the doubly linked list
    D_Node<T> *next;  ///< next node in the doubly linked list

    explicit D_Node(T data) : data(data), prev(nullptr), next(nullptr) {}
};

template <typename K, typename V>
using CacheNode = D_Node<std::pair<K, V>>;

/**
 * @class
 * @brief LFUCache
 * @tparam K type of key in the LFU
 * @tparam V type of value in the LFU
 */
template <typename K, typename V>
class LFUCache {
    std::unordered_map<K, std::pair<CacheNode<K, V> *, int>>
        node_map;  ///< maps the key to the node address and frequency
    std::unordered_map<int, std::pair<CacheNode<K, V> *, CacheNode<K, V> *>>
        freq_map;  ///< maps the frequency to doubly linked list

    int minFreq;    ///< minimum frequency in the cache
    int _capacity;  ///< maximum capacity of the cache

 public:
    /**
     * @brief Constructor, Initialize with minFreq and _capacity.
     * @param _capacity Total capacity of the cache.
     */
    explicit LFUCache(int _capacity) : minFreq(0), _capacity(_capacity) {}

 private:
    /**
     * @brief push the node at first position in the linked list of given
     * frequency
     * @param freq the frequency mapping to the linked list where node should be
     * pushed.
     * @param node node to be pushed to the linked list.
     */
    void push(int freq, CacheNode<K, V> *node) {
        // if freq is not present, then make a new list with node as the head as
        // well as tail.
        if (!freq_map.count(freq)) {
            freq_map[freq] = {node, node};
            return;
        }

        std::pair<CacheNode<K, V> *, CacheNode<K, V> *> &p = freq_map[freq];

        // insert the node at the beginning of the linked list and update the
        // head.
        p.first->prev = node;
        node->next = p.first;
        p.first = node;
    }

    /**
     * @brief increase the frequency of node and push it in the respective list.
     * @param p_node the node to be updated
     */
    void increase_frequency(std::pair<CacheNode<K, V> *, int> &p_node) {
        CacheNode<K, V> *node = p_node.first;
        int freq = p_node.second;

        std::pair<CacheNode<K, V> *, CacheNode<K, V> *> &p = freq_map[freq];

        // if the given node is the only node in the list,
        // then erase the frequency from map
        // and increase minFreq by 1.
        if (p.first == node && p.second == node) {
            freq_map.erase(freq);
            if (minFreq == freq) {
                minFreq = freq + 1;
            }
        } else {
            // remove the given node from current freq linked list
            CacheNode<K, V> *prev = node->prev;
            CacheNode<K, V> *next = node->next;
            node->prev = nullptr;
            node->next = nullptr;

            if (prev) {
                prev->next = next;
            } else {
                p.first = next;
            }

            if (next) {
                next->prev = prev;
            } else {
                p.second = prev;
            }
        }
        push(freq + 1, node);
        ++p_node.second;
    }

    /**
     * @brief pop the last node in the least frequently used linked list
     */
    void pop() {
        std::pair<CacheNode<K, V> *, CacheNode<K, V> *> &p = freq_map[minFreq];

        // if there is only one node
        // remove the node and erase
        // the frequency from freq_map
        if (p.first == p.second) {
            delete p.first;
            freq_map.erase(minFreq);
            return;
        }

        // remove the last node in the linked list
        CacheNode<K, V> *temp = p.second;
        p.second = temp->prev;
        p.second->next = nullptr;
        delete temp;
    }

 public:
    /**
     * @brief upsert a key-value pair
     * @param key key of the key-value pair
     * @param value value of the key-value pair
     */
    void put(K key, V value) {
        // update the value if key already exists
        if (node_map.count(key)) {
            node_map[key].first->data.second = value;
            increase_frequency(node_map[key]);
            return;
        }

        // if the cache is full
        // remove the least frequently used item
        if (node_map.size() == _capacity) {
            node_map.erase(freq_map[minFreq].second->data.first);
            pop();
        }

        // insert the new node and set minFreq to 1
        CacheNode<K, V> *node = new CacheNode<K, V>({key, value});
        node_map[key] = {node, 1};
        minFreq = 1;
        push(1, node);
    }

    /**
     * @brief get the value of the key-value pair if exists
     * @param key key of the key-value pair
     * @return the value mapped to the given key
     * @exception exception is thrown if the key is not present in the cache
     */
    V get(K key) {
        if (!node_map.count(key)) {
            throw std::runtime_error("key is not present in the cache");
        }

        // increase the frequency and return the value
        V value = node_map[key].first->data.second;
        increase_frequency(node_map[key]);
        return value;
    }

    /**
     * @brief Returns the number of items present in the cache.
     * @return number of items in the cache
     */
    int size() const { return node_map.size(); }

    /**
     * @brief Returns the total capacity of the cache
     * @return Total capacity of the cache
     */
    int capacity() const { return _capacity; }

    /**
     * @brief returns true if the cache is empty, false otherwise.
     * @return true if the cache is empty, false otherwise.
     */
    bool empty() const { return node_map.empty(); }

    /**
     * @brief destructs the cache, iterates on the map and deletes every node
     * present in the cache.
     */
    ~LFUCache() {
        auto it = node_map.begin();
        while (it != node_map.end()) {
            delete it->second.first;
            ++it;
        }
    }
};
}  // namespace Cache
}  // namespace others

/**
 * @brief self test implementation
 * @return void
 */
static void test() {
    others::Cache::LFUCache<int, int> cache(5);

    // test the initial state of the cache
    assert(cache.size() == 0);
    assert(cache.capacity() == 5);
    assert(cache.empty());

    // test insertion in the cache
    cache.put(1, 10);
    cache.put(-2, 20);

    // test the state of cache after inserting some items
    assert(cache.size() == 2);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    // test getting items from the cache
    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    cache.put(-3, -30);
    cache.put(4, 40);
    cache.put(5, -50);
    cache.put(6, 60);

    // test the state after inserting more items than the capacity
    assert(cache.size() == 5);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    // test retrieval of all items in the cache
    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    // fetching -3 throws runtime_error
    // as -3 was evicted being the least frequently used
    // when 6 was added
    // assert(cache.get(-3) == -30);

    assert(cache.get(4) == 40);
    assert(cache.get(5) == -50);
    assert(cache.get(6) == 60);

    std::cout << "test - passed\n";
}

/**
 * @brief main function
 * @return 0 on exit
 */
int main() {
    test();  // run the self test implementation
    return 0;
}

/**
 * @file
 * @brief Implementation of an [LFU Cache]
 * (https://en.wikipedia.org/wiki/Least_frequently_used)
 *
 * @details
 * A Least-Frequently-Used cache evicts whichever entry has been accessed the
 * fewest times; ties are broken by evicting the least recently used entry
 * among those tied for lowest frequency. This is implemented using a hash
 * map from key to (node, frequency), plus a second hash map from frequency
 * to a small doubly linked list of nodes sharing that frequency.
 *
 * Whenever an entry is touched (via get or an updating put), it is unlinked
 * from its current frequency bucket and relinked at the head of the next
 * frequency bucket up.
 *
 * Eviction removes the tail node of the lowest-frequency bucket.
 */

#include <cassert>
#include <iostream>
#include <unordered_map>

/**
 * @namespace
 * @brief Other algorithms
 */
namespace others {

/**
 * @namespace
 * @brief Cache algorithm
 */
namespace Cache {

/**
 * @class
 * @brief Doubly linked list node.
 * @tparam T type stored in the node
 */
template <typename T>
class ListNode {
 public:
    T payload;
    ListNode<T> *prevNode;
    ListNode<T> *nextNode;

    explicit ListNode(T payload)
        : payload(payload), prevNode(nullptr), nextNode(nullptr) {}
};

template <typename K, typename V>
using EntryNode = ListNode<std::pair<K, V>>;

/**
 * @class
 * @brief Least-Frequently-Used cache.
 * @tparam K key type
 * @tparam V value type
 */
template <typename K, typename V>
class LFUCache {
    std::unordered_map<K, std::pair<EntryNode<K, V> *, int>>
        keyIndex;  ///< key -> (node pointer, current frequency)
    std::unordered_map<int, std::pair<EntryNode<K, V> *, EntryNode<K, V> *>>
        freqBuckets;  ///< frequency -> (head, tail) of that bucket's list

    int lowestFreq;
    int maxCapacity;

 public:
    /**
     * @brief Builds an empty cache with a fixed maximum capacity.
     * @param capacity how many entries the cache may hold at once
     */
    explicit LFUCache(int capacity) : lowestFreq(0), maxCapacity(capacity) {}

 private:
    /**
     * @brief Inserts a node at the head of the given frequency bucket.
     */
    void insertAtHead(int freq, EntryNode<K, V> *node) {
        if (!freqBuckets.count(freq)) {
            freqBuckets[freq] = {node, node};
            return;
        }

        auto &bucket = freqBuckets[freq];
        bucket.first->prevNode = node;
        node->nextNode = bucket.first;
        bucket.first = node;
    }

    /**
     * @brief Moves a node from its current frequency bucket to the next one
     * up, bumping its recorded frequency by one.
     */
    void bumpFrequency(std::pair<EntryNode<K, V> *, int> &entry) {
        EntryNode<K, V> *node = entry.first;
        int freq = entry.second;

        auto &bucket = freqBuckets[freq];

        if (bucket.first == node && bucket.second == node) {
            freqBuckets.erase(freq);
            if (lowestFreq == freq) {
                lowestFreq = freq + 1;
            }
        } else {
            EntryNode<K, V> *before = node->prevNode;
            EntryNode<K, V> *after = node->nextNode;
            node->prevNode = nullptr;
            node->nextNode = nullptr;

            if (before) {
                before->nextNode = after;
            } else {
                bucket.first = after;
            }

            if (after) {
                after->prevNode = before;
            } else {
                bucket.second = before;
            }
        }
        insertAtHead(freq + 1, node);
        ++entry.second;
    }

    /**
     * @brief Removes the least recently used node from the lowest-frequency
     * bucket.
     */
    void evictOldest() {
        auto &bucket = freqBuckets[lowestFreq];

        if (bucket.first == bucket.second) {
            delete bucket.first;
            freqBuckets.erase(lowestFreq);
            return;
        }

        EntryNode<K, V> *victim = bucket.second;
        bucket.second = victim->prevNode;
        bucket.second->nextNode = nullptr;
        delete victim;
    }

 public:
    /**
     * @brief Inserts or updates a key-value pair.
     * @param key key to insert/update
     * @param value value to associate with the key
     */
    void put(K key, V value) {
        if (keyIndex.count(key)) {
            keyIndex[key].first->payload.second = value;
            bumpFrequency(keyIndex[key]);
            return;
        }

        if (static_cast<int>(keyIndex.size()) == maxCapacity) {
            keyIndex.erase(freqBuckets[lowestFreq].second->payload.first);
            evictOldest();
        }

        EntryNode<K, V> *node = new EntryNode<K, V>({key, value});
        keyIndex[key] = {node, 1};
        lowestFreq = 1;
        insertAtHead(1, node);
    }

    /**
     * @brief Retrieves the value for a key, bumping its usage frequency.
     * @param key key to look up
     * @return the stored value
     * @exception std::runtime_error if the key is absent
     */
    V get(K key) {
        if (!keyIndex.count(key)) {
            throw std::runtime_error("key is not present in the cache");
        }

        V value = keyIndex[key].first->payload.second;
        bumpFrequency(keyIndex[key]);
        return value;
    }

    /** @brief Number of entries currently stored. */
    int size() const { return static_cast<int>(keyIndex.size()); }

    /** @brief Maximum number of entries the cache can hold. */
    int capacity() const { return maxCapacity; }

    /** @brief True when the cache holds no entries. */
    bool empty() const { return keyIndex.empty(); }

    /** @brief Frees every node still owned by the cache. */
    ~LFUCache() {
        for (auto &entry : keyIndex) {
            delete entry.second.first;
        }
    }
};
}  // namespace Cache
}  // namespace others

/**
 * @brief self test implementation
 * @return void
 */
static void runSelfTest() {
    others::Cache::LFUCache<int, int> cache(5);

    assert(cache.size() == 0);
    assert(cache.capacity() == 5);
    assert(cache.empty());

    cache.put(1, 10);
    cache.put(-2, 20);

    assert(cache.size() == 2);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    cache.put(-3, -30);
    cache.put(4, 40);
    cache.put(5, -50);
    cache.put(6, 60);

    assert(cache.size() == 5);
    assert(cache.capacity() == 5);
    assert(!cache.empty());

    assert(cache.get(1) == 10);
    assert(cache.get(-2) == 20);

    // -3 was the least frequently used entry when 6 was inserted, so it was
    // evicted; fetching it now would throw.
    // assert(cache.get(-3) == -30);

    assert(cache.get(4) == 40);
    assert(cache.get(5) == -50);
    assert(cache.get(6) == 60);

    std::cout << "test - passed\n";
}

/**
 * @brief main function
 * @return 0 on exit
 */
int main() {
    runSelfTest();
    return 0;
}

/**
 * @file
 * @brief Solution for Longest Substring Without Repeating Characters problem.
 * @details
 * Problem link: https://leetcode.com/problems/longest-substring-without-repeating-characters/description/
 * 
 * Intuition:
 * 1) The intuition is straightforward and simple. We track the frequency of characters.
 * 2) Since we can't use a string to track the longest substring without repeating characters efficiently (as removing a character from the front of a string isn't O(1)), we optimize the solution using a deque approach.
 *
 * Approach:
 * 1) Initialize an unordered_map to track the frequency of characters.
 * 2) Use a deque for pushing characters, and update the result deque (`res`) with the current deque (`temp`) 
 *    whenever we find a longer substring.
 * 3) Use a while loop to reduce the frequency from the front, incrementing `i`, 
 *    and removing characters from the `temp` deque as we no longer need them.
 * 4) Return `res.size()` as we are interested in the length of the longest substring.
 * 
 * Time Complexity: O(N)
 * Space Complexity: O(N)
 * 
 * I hope this helps to understand.
 * Thank you!
 * @author [Ashish Kumar Sahoo](github.com/ashish5kmax)
 **/

#include <iostream>        // for IO Operations
#include <unordered_map>   // for std::unordered_map
#include <deque>           // for std::deque
#include <string>          // for string class/string datatype which is taken as input
#include <cassert>         // for assert

/**
 * @class Longest_Substring
 * @brief Class that solves the Longest Substring Without Repeating Characters problem.
 */
class Longest_Substring {
public:
    /**
     * @brief Function to find the length of the longest substring without repeating characters.
     * @param s Input string.
     * @return Length of the longest substring.
     */
    int lengthOfLongestSubstring(std::string s) {
        // If the size of string is 1, then it will be the answer.
        if (s.size() == 1) return 1;

        // Map used to store the character frequency.
        std::unordered_map<char, int> m;
        int n = s.length();

        // Deque to remove from back if repeating characters are present.
        std::deque<char> temp;
        std::deque<char> res;
        int i, j;

        // Sliding window approach using two pointers.
        for (i = 0, j = 0; i < n && j < n;) {
            m[s[j]]++;

            // If repeating character found, update result and remove from the front.
            if (m[s[j]] > 1) {
                if (temp.size() > res.size()) {
                    res = temp;
                }

                while (m[s[j]] > 1) {
                    temp.pop_front();
                    m[s[i]]--;
                    i++;
                }
            }

            // Add the current character to the deque.
            temp.push_back(s[j]);
            j++;
        }

        // Final check to update result.
        if (temp.size() > res.size()) {
            res = temp;
        }

        return res.size();  // Return the length of the longest substring.
    }
};

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    Longest_Substring soln;
    assert(soln.lengthOfLongestSubstring("abcabcbb") == 3);
    assert(soln.lengthOfLongestSubstring("bbbbb") == 1);
    assert(soln.lengthOfLongestSubstring("pwwkew") == 3);
    assert(soln.lengthOfLongestSubstring("") == 0); // Test case for empty string
    assert(soln.lengthOfLongestSubstring("abcdef") == 6); // Test case for all unique characters
    assert(soln.lengthOfLongestSubstring("a") == 1); // Single character
    std::cout << "All test cases passed!" << std::endl;
}

/**
 * @brief Main function.
 * @return 0 on successful execution.
 */
int main() {
    tests(); // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Solves the "Longest Substring Without Repeating Characters" problem.
 * @details
 * Problem link: https://leetcode.com/problems/longest-substring-without-repeating-characters/description/
 *
 * Idea:
 * 1) Track how often each character currently appears within the active
 *    window using a hash map.
 * 2) Maintain the current window's characters in a deque (a plain string
 *    isn't ideal since popping from the front repeatedly isn't O(1)).
 * 3) Whenever a duplicate shows up, shrink the window from the front until
 *    the duplicate is gone, saving the best window seen so far along the way.
 * 4) The final answer is the size of the best window found.
 *
 * Time Complexity: O(N)
 * Space Complexity: O(N)
 */

#include <iostream>
#include <unordered_map>
#include <deque>
#include <string>
#include <cassert>

/**
 * @class UniqueWindowFinder
 * @brief Encapsulates the sliding-window solution to the longest
 * no-repeat-substring problem.
 */
class UniqueWindowFinder {
public:
    /**
     * @brief Computes the length of the longest run of non-repeating
     * characters within the given string.
     * @param text Input string.
     * @return Length of the longest valid window.
     */
    int longestUniqueRun(std::string text) {
        if (text.size() == 1) return 1;

        std::unordered_map<char, int> occurrences;
        int len = static_cast<int>(text.length());

        std::deque<char> window;
        std::deque<char> bestWindow;
        int left = 0, right = 0;

        while (left < len && right < len) {
            occurrences[text[right]]++;

            if (occurrences[text[right]] > 1) {
                if (window.size() > bestWindow.size()) {
                    bestWindow = window;
                }

                while (occurrences[text[right]] > 1) {
                    window.pop_front();
                    occurrences[text[left]]--;
                    left++;
                }
            }

            window.push_back(text[right]);
            right++;
        }

        if (window.size() > bestWindow.size()) {
            bestWindow = window;
        }

        return static_cast<int>(bestWindow.size());
    }
};

/**
 * @brief Self-test implementations
 * @returns void
 */
static void runTests() {
    UniqueWindowFinder finder;
    assert(finder.longestUniqueRun("abcabcbb") == 3);
    assert(finder.longestUniqueRun("bbbbb") == 1);
    assert(finder.longestUniqueRun("pwwkew") == 3);
    assert(finder.longestUniqueRun("") == 0);
    assert(finder.longestUniqueRun("abcdef") == 6);
    assert(finder.longestUniqueRun("a") == 1);
    std::cout << "All test cases passed!" << std::endl;
}

/**
 * @brief Main function.
 * @return 0 on successful execution.
 */
int main() {
    runTests();
    return 0;
}

/**
 * @file
 * @brief An implementation of
 * [LRU
 * Cache](https://en.wikipedia.org/wiki/Cache_replacement_policies#Least_recently_used_(LRU)).
 * Lru is a part of cache algorithms (also frequently called cache replacement
 * algorithms or cache replacement policies).
 *
 * ### Logic
 *      * Discards the least recently used items first.
 *      * This algorithm requires keeping track of what was used when, which is
 * expensive if one wants to make sure the algorithm always discards the least
 * recently used item.
 *      * General implementations of this technique require keeping "age bits"
 * for cache-lines and track the "Least Recently Used" cache-line based on
 * age-bits.
 *      * In such an implementation, every time a cache-line is used, the age of
 * all other cache-lines changes
 *
 * ### Algorithm explanation
 *      For a cache of page frame x:
 *          * Check if the page is present in cache.
 *          * If not present, then check is the cache is full or not:
 *          * If the cache is full, REMOVE the last element from the cache.
 *          * If the element is present in cache, then shift that element to
 * first position in cache from its original position.
 *              * This way you can keep the least recently used elements in the
 * last and most recently used in front of the cache.
 *
 *  Every time a requested page is  not found in cache, that is a miss or page
 * fault, and if the page is present in cache, then its a hit.
 *
 * ## Data Structure used
 *  * In the algorithm below we used two different data structure, one is linked
 * list and other one is a hash map
 *  * The linked list is used to contain the pages and the hash map contains the
 * pages and their address.
 *  * Every time a new page is requested, we first check in the hash map if the
 * page is present or not.
 *  * If not present, and the cache is full, we simply delete the last entry in
 * the cache.
 *  * If present, we shift that page from its current location to beginning of
 * the cache and update the address in hash map for that page.
 *
 * @author [Nitin Sharma](https://github.com/foo290)
 * */

#include <cassert>        /// for assert
#include <cstdint>
#include <iostream>       /// for IO Operations
#include <list>           /// for std::list
#include <unordered_map>  /// for std::unordered_map

/**
 * @namespace others
 * @brief Other algorithms
 */
namespace others {
/**
 * @namespace lru_cache
 * @brief Implementation of the [LRU caching
 * algorithm](https://en.wikipedia.org/wiki/Cache_replacement_policies#Least_recently_used_(LRU))
 */
namespace lru_cache {
/**
 * @brief LRU cache class
 */
class LRUCache {
    uint64_t pageFrame;         ///< Page frame, or total size of the cache.
    std::list<uint64_t> cache;  ///< Cache linked list (using the STL)
    std::unordered_map<uint64_t, std::list<uint64_t>::iterator>
        pageMap;  ///< Hash map containing pages and their addresses

    uint64_t hits =
        0;  ///< Total number of hits, or total number of times a page
    ///< was found in cache.
    uint64_t pageFault = 0;  ///< Total number of miss/page fault, or total
                             ///< number of times a page was not found in cache

 public:
    /**
     * @brief Constructor, Initialize thee LRU class with page frame.
     * @param pf Page frame or total size of cache.
     * */
    explicit LRUCache(uint64_t pf) { pageFrame = pf; }

    /**
     * @brief Refer to a page, or request a page from memory.
     * @param page The page that you are referring to.
     * @returns void
     * */
    void refer(uint64_t page) {
        // If the page requested not in cache.
        if (pageMap.find(page) == pageMap.end()) {
            pageFault++;  ///< Increase the page fault by one.

            // Check if the cache is full
            if (cache.size() == pageFrame) {
                // delete the last page from cache
                uint64_t lastPage = cache.back();
                cache.pop_back();
                pageMap.erase(lastPage);
            }
        }
        // The requested page is in the cache
        else {
            hits++;
            // present in cache, erase from current position to bring in front
            cache.erase(pageMap[page]);
        }
        // Push it in the front of the cache and update the page reference in
        // page map.
        cache.push_front(page);
        pageMap[page] = cache.begin();
    }

    /**
     * @brief A function to display the current cache
     * @returns Void
     * */
    void display() {
        for (uint64_t &it : cache) {
            std::cout << it << " ";
        }
        std::cout << std::endl;
    }
    /**
     * @brief A function to get page hits
     * @returns int
     * */
    uint64_t getHits() const { return hits; }
    /**
     * @brief A function to get page fault
     * @returns int
     * */
    uint64_t getPageFault() const { return pageFault; }
};

}  // namespace lru_cache
}  // namespace others

namespace lru_tests {
