/**
 * @file
 * @brief An implementation of an
 * [LRU Cache](https://en.wikipedia.org/wiki/Cache_replacement_policies#Least_recently_used_(LRU)).
 *
 * ### Idea
 *      * Evicts whichever item has gone longest without being accessed.
 *      * Requires tracking recency of use for every entry, which can be
 *        costly if done naively.
 *      * A common trick is to keep the entries in a linked list ordered by
 *        recency, moving an entry to the front whenever it's touched, and
 *        dropping from the back when eviction is needed.
 *
 * ### Algorithm
 *      For a requested page x:
 *          * Look up x in the cache.
 *          * If absent and the cache is at capacity, drop the back-most
 *            (least recently used) entry first.
 *          * If present, move it to the front.
 *
 *  A lookup that already exists in the cache counts as a "hit"; one that
 *  doesn't counts as a "fault" / miss.
 *
 * ### Data structures
 *  * A doubly linked list (std::list) holds the pages in recency order.
 *  * A hash map from page -> list iterator gives O(1) lookups into the list.
 */

#include <cassert>
#include <cstdint>
#include <iostream>
#include <list>
#include <unordered_map>

/**
 * @namespace others
 * @brief Other algorithms
 */
namespace others {
/**
 * @namespace lru_cache
 * @brief Implementation of the LRU caching algorithm
 */
namespace lru_cache {
/**
 * @brief LRU cache class
 */
class LRUCache {
    uint64_t capacity;                  ///< maximum number of pages held
    std::list<uint64_t> recencyOrder;   ///< most-recent-first list of pages
    std::unordered_map<uint64_t, std::list<uint64_t>::iterator>
        location;  ///< page -> iterator into recencyOrder

    uint64_t hitCount = 0;    ///< number of lookups that were already cached
    uint64_t faultCount = 0;  ///< number of lookups that required insertion

 public:
    /**
     * @brief Builds a cache with the given maximum size.
     * @param cap Maximum number of pages the cache may hold.
     */
    explicit LRUCache(uint64_t cap) { capacity = cap; }

    /**
     * @brief Requests a page, updating hit/fault counters and recency order.
     * @param page The page being requested.
     * @returns void
     */
    void refer(uint64_t page) {
        if (location.find(page) == location.end()) {
            faultCount++;

            if (recencyOrder.size() == capacity) {
                uint64_t evicted = recencyOrder.back();
                recencyOrder.pop_back();
                location.erase(evicted);
            }
        } else {
            hitCount++;
            recencyOrder.erase(location[page]);
        }
        recencyOrder.push_front(page);
        location[page] = recencyOrder.begin();
    }

    /**
     * @brief Prints the current contents of the cache, most recent first.
     * @returns void
     */
    void display() {
        for (uint64_t &page : recencyOrder) {
            std::cout << page << " ";
        }
        std::cout << std::endl;
    }

    /** @brief Number of cache hits so far. */
    uint64_t getHits() const { return hitCount; }

    /** @brief Number of cache faults (misses) so far. */
    uint64_t getPageFault() const { return faultCount; }
};

}  // namespace lru_cache
}  // namespace others

