/**
 * @file
 * @brief Determine the centre and radius of the
 * [minimum enclosing circle](https://en.wikipedia.org/wiki/Smallest-circle_problem)
 * for a given set of 2D points.
 *
 * @see [reference implementation](https://www.nayuki.io/page/smallest-enclosing-circle)
 */
#include <cmath>
#include <iostream>
#include <vector>

/** A simple 2D coordinate. */
struct Vec2 {
    double x; /**< horizontal coordinate */
    double y; /**< vertical coordinate */

    /** Build a coordinate, defaulting to the origin.
     * \param [in] px x-coordinate (default 0.0)
     * \param [in] py y-coordinate (default 0.0)
     */
    explicit Vec2(double px = 0.0, double py = 0.0) : x(px), y(py) {}
};

/** Euclidean distance between two points, i.e.
 * \f[d=\sqrt{\left(x_1-x_2\right)^2+\left(y_1-y_2\right)^2}\f]
 * \param [in] p first point
 * \param [in] q second point
 * \return straight-line distance between p and q
 */
double distanceBetween(const Vec2 &p, const Vec2 &q) {
    double deltaX = q.x - p.x;
    double deltaY = q.y - p.y;
    return std::sqrt(deltaX * deltaX + deltaY * deltaY);
}

/**
 * Area of the triangle formed by three points, computed with [Heron's
 * formula](https://en.wikipedia.org/wiki/Heron%27s_formula):
 * given side lengths a, b, c and semi-perimeter s = (a+b+c)/2,
 * \f[A=\sqrt{s(s-a)(s-b)(s-c)}\f]
 * \param [in] p1 first vertex
 * \param [in] p2 second vertex
 * \param [in] p3 third vertex
 * \returns the triangle's area
 */
double triangleAreaOf(const Vec2 &p1, const Vec2 &p2, const Vec2 &p3) {
    double sideA = distanceBetween(p1, p2);
    double sideB = distanceBetween(p2, p3);
    double sideC = distanceBetween(p3, p1);
    double semiPerimeter = (sideA + sideB + sideC) / 2;
    return std::sqrt(semiPerimeter * (semiPerimeter - sideA) *
                      (semiPerimeter - sideB) * (semiPerimeter - sideC));
}

/**
 * Determine whether every point in a collection lies on or inside a
 * given circle (i.e. its distance to the centre never exceeds the radius).
 * \param [in] points points to test
 * \param [in] center centre of the candidate circle
 * \param [in] radius radius of the candidate circle
 * \returns true if all points are within the circle, false if any point
 * falls outside it
 */
bool allPointsWithin(const std::vector<Vec2> &points, const Vec2 &center,
                     double radius) {
    for (const auto &pt : points) {
        if (distanceBetween(pt, center) > radius) {
            return false;
        }
    }
    return true;
}

/**
 * Compute the smallest circle enclosing a set of points, printing its
 * centre to stdout and returning its radius.
 * \param [in] points the set of points to enclose
 * \returns radius of the minimal enclosing circle
 */
double minimalEnclosingCircle(const std::vector<Vec2> &points) {
    double bestRadius = INFINITY;
    Vec2 bestCenter;

    /* NOTE: this brute-force triple-point pass is known to be incomplete
     * (it can miss the true optimum in some configurations, see the
     * scenario below with four points where it doesn't converge). It's
     * kept here for parity with the original approach. */
    // try every combination of three distinct points as candidates
    for (std::size_t i = 0; i + 2 < points.size(); ++i) {
        for (std::size_t j = i + 1; j < points.size(); ++j) {
            for (std::size_t k = j + 1; k < points.size(); ++k) {
                const Vec2 &A = points[i];
                const Vec2 &B = points[j];
                const Vec2 &C = points[k];

                Vec2 candidateCenter;
                candidateCenter.x =
                    -0.5 *
                    ((A.y * (B.x * B.x + B.y * B.y - C.x * C.x - C.y * C.y) +
                      B.y * (C.x * C.x + C.y * C.y - A.x * A.x - A.y * A.y) +
                      C.y * (A.x * A.x + A.y * A.y - B.x * B.x - B.y * B.y)) /
                     (A.x * (B.y - C.y) + B.x * (C.y - A.y) +
                      C.x * (A.y - B.y)));
                candidateCenter.y =
                    0.5 *
                    ((A.x * (B.x * B.x + B.y * B.y - C.x * C.x - C.y * C.y) +
                      B.x * (C.x * C.x + C.y * C.y - A.x * A.x - A.y * A.y) +
                      C.x * (A.x * A.x + A.y * A.y - B.x * B.x - B.y * B.y)) /
                     (A.x * (B.y - C.y) + B.x * (C.y - A.y) +
                      C.x * (A.y - B.y)));

                double candidateRadius =
                    (distanceBetween(A, B) * distanceBetween(B, C) *
                     distanceBetween(C, A)) /
                    (4 * triangleAreaOf(A, B, C));

                if (!allPointsWithin(points, candidateCenter, candidateRadius)) {
                    continue;
                }
                if (candidateRadius <= bestRadius) {
                    bestRadius = candidateRadius;
                    bestCenter = candidateCenter;
                }
            }
        }
    }

    // also try circles whose diameter spans every pair of points
    for (std::size_t i = 0; i + 1 < points.size(); ++i) {
        for (std::size_t j = i + 1; j < points.size(); ++j) {
            Vec2 candidateCenter;
            candidateCenter.x = (points[i].x + points[j].x) / 2;
            candidateCenter.y = (points[i].y + points[j].y) / 2;
            double candidateRadius = distanceBetween(candidateCenter, points[i]);

            if (!allPointsWithin(points, candidateCenter, candidateRadius)) {
                continue;
            }
            if (candidateRadius <= bestRadius) {
                bestRadius = candidateRadius;
                bestCenter = candidateCenter;
            }
        }
    }

    std::cout << bestCenter.x << " " << bestCenter.y << std::endl;
    return bestRadius;
}

/** Demo: five scattered points.
 * Expected result: radius approx 3.318493136080724,
 * centre approx (3.0454545454545454, 1.3181818181818181)
 */
void demoFivePoints() {
    std::vector<Vec2> points;
    points.push_back(Vec2(0, 0));
    points.push_back(Vec2(5, 4));
    points.push_back(Vec2(1, 3));
    points.push_back(Vec2(4, 1));
    points.push_back(Vec2(3, -2));
    std::cout << minimalEnclosingCircle(points) << std::endl;
}

/** Demo: a perfect square.
 * Expected result: radius approx 1.4142135623730951,
 * centre approx (1.0, 1.0)
 */
void demoUnitSquare() {
    std::vector<Vec2> points;
    points.push_back(Vec2(0, 0));
    points.push_back(Vec2(0, 2));
    points.push_back(Vec2(2, 2));
    points.push_back(Vec2(2, 0));
    std::cout << minimalEnclosingCircle(points) << std::endl;
}

/** Demo: four points where the brute-force pass is known not to converge.
 * Expected result: radius approx 1.821078397711709,
 * centre approx (2.142857142857143, 1.7857142857142856)
