 */
void demoFourPointsEdgeCase() {
    std::vector<Vec2> points;
    points.push_back(Vec2(0.5, 1));
    points.push_back(Vec2(3.5, 3));
    points.push_back(Vec2(2.5, 0));
    points.push_back(Vec2(2, 1.5));
    std::cout << minimalEnclosingCircle(points) << std::endl;
}

/** Program entry point. */
int main() {
    demoFivePoints();
    std::cout << std::endl;
    demoUnitSquare();
    std::cout << std::endl;
    demoFourPointsEdgeCase();
    return 0;
}

/** @file
 * A sparse matrix is a matrix which has number of zeroes greater than
 * \f$\frac{m\times n}{2}\f$, where m and n are the dimensions of the matrix.
 */

#include <iostream>

/** main function */
int main() {
    int m, n;
    int counterZeros = 0;

    std::cout << "Enter dimensions of matrix (seperated with space): ";
    std::cin >> m;
    std::cin >> n;

    int **a = new int *[m];
    for (int i = 0; i < m; i++) a[i] = new int[n];

    std::cout << "Enter matrix elements:";
    std::cout << "\n";

    // reads the matrix from stdin
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << "element? ";
            std::cin >> a[i][j];
        }
    }

    // counts the zero's
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (a[i][j] == 0)
                counterZeros++;  // Counting number of zeroes
        }
    }

    // makes sure the matrix is a sparse matrix
    if (counterZeros > ((m * n) / 2))  // Checking for sparse matrix
        std::cout << "Sparse matrix";
    else
        std::cout << "Not a sparse matrix";

    for (int i = 0; i < m; i++) delete[] a[i];
    delete[] a;
    return 0;
}

/** @file
 * A matrix is considered sparse when more than half of its entries
 * (i.e. more than (rows * cols) / 2 of them) are zero.
 */

#include <iostream>

/** Program entry point: reads a matrix from stdin and reports whether it
 * qualifies as sparse. */
int main() {
    int rows = 0;
    int cols = 0;
    int zeroTally = 0;

    std::cout << "Enter matrix dimensions (rows then columns, space separated): ";
    std::cin >> rows;
    std::cin >> cols;

    // Allocate a jagged 2D array of the requested size.
    int **grid = new int *[rows];
    for (int r = 0; r < rows; ++r) {
        grid[r] = new int[cols];
    }

    std::cout << "Enter the matrix entries:";
    std::cout << "\n";

    // Populate the grid row by row from user input.
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            std::cout << "value? ";
            std::cin >> grid[r][c];
        }
    }

    // Tally up how many cells hold a zero.
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == 0) {
                ++zeroTally;
            }
        }
    }

    // A matrix qualifies as sparse once zeros outnumber half of all entries.
    if (zeroTally > (rows * cols) / 2) {
        std::cout << "Sparse matrix";
    } else {
        std::cout << "Not a sparse matrix";
    }

    for (int r = 0; r < rows; ++r) {
        delete[] grid[r];
    }
    delete[] grid;

    return 0;
}

/**
 * @file
 * @brief Print the elements of a matrix traversing it spirally
 */
#include <iostream>

/** Arrange sequence of numbers from '1' in a matrix form
 * \param [out] a matrix to fill
 * \param [in] r number of rows
 * \param [in] c number of columns
 */
void genArray(int **a, int r, int c) {
    int value = 1;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            a[i][j] = value;
            std::cout << a[i][j] << " ";
            value++;
        }
        std::cout << std::endl;
    }
}

/** Traverse the matrix spirally and print the sequence of elements
 * \param [in] a matrix to read from
 * \param [in] r number of rows
 * \param [in] c number of columns
 */
void spiralPrint(int **a, int r, int c) {
    int startRow = 0, endRow = r - 1;
    int startCol = 0, endCol = c - 1;
    int cnt = 0;

    while (startRow <= endRow && startCol <= endCol) {
        /// Print start row
        for (int i = startCol; i <= endCol; i++, cnt++) {
            std::cout << a[startRow][i] << " ";
        }
        startRow++;

        /// Print the end col
        for (int i = startRow; i <= endRow; i++, cnt++) {
            std::cout << a[i][endCol] << " ";
        }
        endCol--;

        /// Print the end row
        if (cnt == r * c) {
            break;
        }

        for (int i = endCol; i >= startCol; i--, cnt++) {
            std::cout << a[endRow][i] << " ";
        }
        endRow--;

        /// Print the start Col
        if (cnt == r * c) {
            break;
        }
        for (int i = endRow; i >= startRow; i--, cnt++) {
            std::cout << a[i][startCol] << " ";
        }
        startCol++;
    }
}

/** main function */
int main() {
    int r, c;
    std::cin >> r >> c;
    int **a = new int *[r];
    for (int i = 0; i < r; i++) a[i] = new int[c];

    genArray(a, r, c);
    spiralPrint(a, r, c);

    for (int i = 0; i < r; i++) delete[] a[i];
    delete[] a;
    return 0;
}

/**
 * @file
 * @brief Walk a 2D grid layer by layer (outer ring inward) and print its
 * contents in spiral order.
 */
#include <iostream>

/** Fill a rows x cols grid with increasing integers starting at 1, printing
 * each row as it is produced.
 * \param [out] grid the matrix to populate
 * \param [in] rows number of rows
 * \param [in] cols number of columns
 */
void fillSequential(int **grid, int rows, int cols) {
    int counter = 1;
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            grid[row][col] = counter;
            std::cout << grid[row][col] << " ";
            ++counter;
        }
        std::cout << std::endl;
    }
}

/** Walk the outer boundary of the current sub-grid, shrinking the boundary
 * after each side, until every cell has been visited once.
 * \param [in] grid matrix to traverse
 * \param [in] rows number of rows
 * \param [in] cols number of columns
 */
void printInSpiralOrder(int **grid, int rows, int cols) {
    int top = 0, bottom = rows - 1;
    int left = 0, right = cols - 1;
    int visited = 0;
    const int total = rows * cols;

    while (top <= bottom && left <= right) {
        // walk along the top edge, left to right
        for (int col = left; col <= right; ++col, ++visited) {
            std::cout << grid[top][col] << " ";
        }
        ++top;

        // walk down the right edge
        for (int row = top; row <= bottom; ++row, ++visited) {
            std::cout << grid[row][right] << " ";
        }
        --right;

        if (visited == total) {
            break;
        }

        // walk along the bottom edge, right to left
        for (int col = right; col >= left; --col, ++visited) {
            std::cout << grid[bottom][col] << " ";
        }
        --bottom;

        if (visited == total) {
            break;
        }

        // walk up the left edge
        for (int row = bottom; row >= top; --row, ++visited) {
            std::cout << grid[row][left] << " ";
        }
        ++left;
    }
}

/** Entry point: reads dimensions, builds a heap-allocated grid, fills it,
 * prints it spirally, then frees everything. */
int main() {
    int rows = 0, cols = 0;
    std::cin >> rows >> cols;

    int **grid = new int *[rows];
    for (int row = 0; row < rows; ++row) {
        grid[row] = new int[cols];
    }

    fillSequential(grid, rows, cols);
    printInSpiralOrder(grid, rows, cols);

    for (int row = 0; row < rows; ++row) {
        delete[] grid[row];
    }
    delete[] grid;

    return 0;
}

/**
 * @file
@brief This program is use to print the following pattern<pre>
   \*\*
   \*\*
  \*\*\*\*
  \*\*\*\*
 \*\*\*\*\*\*
 \*\*\*\*\*\*
\*\*\*\*\*\*\*\*
********</pre>
where number of pairs line is given by user
*/
#include <iostream>

/** main function */
int main() {
    int l, st = 2, x, r, z, n, sp;
    std::cout << "Enter number of pair - ";
    std::cin >> x;
    z = x;
    for (r = 1; r <= x; r++) {
        z = z - 1;
        for (n = 1; n <= 2; n++) {
            for (sp = 1; sp <= z; sp++) {
                std::cout << " ";
            }
            for (l = 1; l <= st; l++) {
                std::cout << "\\*";
            }
            std::cout << std::endl;
        }
        st = st + 2;
    }
}

/**
 * @file
 * @brief Draws a symmetric "double staircase" pattern made of pairs of rows,
 * each pair using two asterisks (escaped) per step, e.g. for 4 pairs:<pre>
 *    \*\*
 *    \*\*
 *   \*\*\*\*
 *   \*\*\*\*
 *  \*\*\*\*\*\*
 *  \*\*\*\*\*\*
 * \*\*\*\*\*\*\*\*
 * ********</pre>
 * The number of row-pairs is supplied by the user.
 */
#include <iostream>

/** Print one line of leading spaces followed by a run of escaped stars.
 * \param [in] leadingSpaces how many blank columns to print before the stars
 * \param [in] starPairs how many "\*" tokens to print on this line
 */
void printStepLine(int leadingSpaces, int starPairs) {
    for (int gap = 0; gap < leadingSpaces; ++gap) {
        std::cout << " ";
    }
    for (int star = 0; star < starPairs; ++star) {
        std::cout << "\\*";
    }
    std::cout << std::endl;
}

/** Entry point: reads the number of step-pairs and draws each step twice,
 * widening the star count and shrinking the indentation as it descends. */
int main() {
    int stepCount = 0;
    std::cout << "Enter number of pair - ";
    std::cin >> stepCount;

    int starsThisStep = 2;
    int indent = stepCount;

    for (int step = 1; step <= stepCount; ++step) {
        --indent;
        for (int repeat = 0; repeat < 2; ++repeat) {
            printStepLine(indent, starsThisStep);
        }
        starsThisStep += 2;
    }

    return 0;
}

/**
 * @file
 * @brief Solve the [Tower of
 * Hanoi](https://en.wikipedia.org/wiki/Tower_of_Hanoi) problem.
 */
#include <iostream>

/**
 * Define the state of tower
 */
struct tower {
    //! Values in the tower
    int values[10];
    //! top tower ID
    int top;
};

/** Display the towers */
void show(const struct tower *const F, const struct tower *const T,
          const struct tower *const U) {
    std::cout << "\n\n\tF : ";
    for (int i = 0; i < F->top; i++) {
        std::cout << F->values[i] << "\t";
    }
    std::cout << "\n\tU : ";
    for (int i = 0; i < U->top; i++) {
        std::cout << U->values[i] << "\t";
    }
    std::cout << "\n\tT : ";
    for (int i = 0; i < T->top; i++) {
        std::cout << T->values[i] << "\t";
    }
}

/** Move one disc from one tower to another
 * \param [in,out] From tower to move disk *from*
 * \param [in,out] To  tower to move disk *to*
 */
void mov(tower *From, tower *To) {
    --From->top;
    To->values[To->top] = From->values[From->top];
    ++To->top;
}

/**
 * Recursive algorithm to solve the puzzle
 * \param [in] n starting number of disks
 * \param [in,out] From  tower to move disks from
 * \param [in,out] Using temporary tower for the puzzle
 * \param [in,out] To  tower to move disk to
 */
void TH(int n, tower *From, tower *Using, tower *To) {
    if (n == 1) {
        mov(From, To);
        show(From, To, Using);
    } else {
        TH(n - 1, From, To, Using);
        mov(From, To);
        show(From, To, Using);
        TH(n - 1, Using, From, To);
    }
}

/** Main function */
int main() {
    struct tower F, U, T;

    F.top = 0;
    U.top = 0;
    T.top = 0;

    int no;

    std::cout << "\nEnter number of discs : ";
    std::cin >> no;

    for (int i = no; i > 0; i--) {
        F.values[F.top++] = i;
    }

    show(&F, &T, &U);
    TH(no, &F, &U, &T);

    return 0;
}

/**
 * @file
 * @brief Solve the classic [Tower of
 * Hanoi](https://en.wikipedia.org/wiki/Tower_of_Hanoi) puzzle recursively.
 */
#include <iostream>

/**
 * Represents a single peg holding a stack of discs.
 */
struct Peg {
    //! Disc sizes currently stacked on this peg
    int discs[10];
    //! Index just past the topmost disc (i.e., the stack size)
    int count;
};

/** Move the topmost disc from one peg onto another peg.
 * \param [in,out] source peg to take the disc from
 * \param [in,out] destination peg to place the disc onto
 */
void relocateTopDisc(Peg *source, Peg *destination) {
    --source->count;
    destination->discs[destination->count] = source->discs[source->count];
    ++destination->count;
}

/** Print the current arrangement of all three pegs. */
void printPegs(const Peg *const source, const Peg *const destination,
               const Peg *const spare) {
    std::cout << "\n\n\tF : ";
    for (int i = 0; i < source->count; i++) {
        std::cout << source->discs[i] << "\t";
    }
    std::cout << "\n\tU : ";
    for (int i = 0; i < spare->count; i++) {
        std::cout << spare->discs[i] << "\t";
    }
    std::cout << "\n\tT : ";
    for (int i = 0; i < destination->count; i++) {
        std::cout << destination->discs[i] << "\t";
    }
}

/**
 * Recursively move discCount discs from source to destination, using spare
 * as scratch space, printing the pegs after every move.
 * \param [in] discCount how many discs remain to be moved in this call
 * \param [in,out] source peg the discs currently sit on
 * \param [in,out] spare peg used as temporary storage
 * \param [in,out] destination peg the discs must end up on
 */
void solveHanoi(int discCount, Peg *source, Peg *spare, Peg *destination) {
    if (discCount == 1) {
        relocateTopDisc(source, destination);
        printPegs(source, destination, spare);
        return;
    }
    solveHanoi(discCount - 1, source, destination, spare);
    relocateTopDisc(source, destination);
    printPegs(source, destination, spare);
    solveHanoi(discCount - 1, spare, source, destination);
}

/** Entry point: builds the starting peg, reads how many discs to use, and
 * kicks off the recursive solver. */
int main() {
    Peg source, spare, destination;

    source.count = 0;
    spare.count = 0;
    destination.count = 0;

    int discCount = 0;
    std::cout << "\nEnter number of discs : ";
    std::cin >> discCount;

    for (int size = discCount; size > 0; size--) {
        source.discs[source.count++] = size;
    }

    printPegs(&source, &destination, &spare);
    solveHanoi(discCount, &source, &spare, &destination);

    return 0;
}

/**
 * @file
 * @brief A C++ program to demonstrate working of std::sort(), std::reverse()
 */
#include <algorithm>
#include <iostream>
#include <numeric>  // For accumulate operation
#include <vector>

/** Main function */
int main() {
    // Initializing vector with array values
    int arr[] = {10, 20, 5, 23, 42, 15};
    int n = sizeof(arr) / sizeof(arr[0]);
    std::vector<int> vect(arr, arr + n);

    std::cout << "Vector is: ";
    for (int i = 0; i < n; i++) std::cout << vect[i] << " ";

    // Sorting the Vector in Ascending order
    std::sort(vect.begin(), vect.end());

    std::cout << "\nVector after sorting is: ";
    for (int i = 0; i < n; i++) std::cout << vect[i] << " ";

    // Reversing the Vector
    std::reverse(vect.begin(), vect.end());

    std::cout << "\nVector after reversing is: ";
    for (int i = 0; i < 6; i++) std::cout << vect[i] << " ";

    std::cout << "\nMaximum element of vector is: ";
    std::cout << *max_element(vect.begin(), vect.end());

    std::cout << "\nMinimum element of vector is: ";
    std::cout << *min_element(vect.begin(), vect.end());

    // Starting the summation from 0
    std::cout << "\nThe summation of vector elements is: ";
    std::cout << accumulate(vect.begin(), vect.end(), 0);

    return 0;
}

/**
 * @file
 * @brief Demonstrates common std::vector operations: sorting, reversing,
 * locating extremes, and summing via std::accumulate.
 */
#include <algorithm>
#include <iostream>
#include <numeric>  // for std::accumulate
#include <string>
#include <vector>

/** Print every element of a vector on one line, preceded by a label. */
static void dumpVector(const std::string &label, const std::vector<int> &data) {
    std::cout << label;
    for (std::size_t idx = 0; idx < data.size(); ++idx) {
        std::cout << data[idx] << " ";
    }
}

/** Entry point demonstrating vector construction, sort, reverse, min/max,
 * and accumulation. */
int main() {
    // Seed data copied into a vector from a raw array
    int rawValues[] = {10, 20, 5, 23, 42, 15};
    std::size_t count = sizeof(rawValues) / sizeof(rawValues[0]);
    std::vector<int> numbers(rawValues, rawValues + count);

    dumpVector("Vector is: ", numbers);

    // Ascending sort in place
    std::sort(numbers.begin(), numbers.end());
    std::cout << "\n";
    dumpVector("Vector after sorting is: ", numbers);

    // Flip the order of all elements
    std::reverse(numbers.begin(), numbers.end());
    std::cout << "\n";
    dumpVector("Vector after reversing is: ", numbers);

    std::cout << "\nMaximum element of vector is: ";
    std::cout << *std::max_element(numbers.begin(), numbers.end());

    std::cout << "\nMinimum element of vector is: ";
    std::cout << *std::min_element(numbers.begin(), numbers.end());

    // Sum all elements starting the running total at 0
    std::cout << "\nThe summation of vector elements is: ";
    std::cout << std::accumulate(numbers.begin(), numbers.end(), 0);

    return 0;
}

/**
 * @file
 * @brief Ground to ground [projectile
 * motion](https://en.wikipedia.org/wiki/Projectile_motion) equation
 * implementations
 * @details Ground to ground projectile motion is when a projectile's trajectory
 * starts at the ground, reaches the apex, then falls back on the ground.
 *
 * @author [Focusucof](https://github.com/Focusucof)
 */

#include <cassert>   /// for assert()
#define _USE_MATH_DEFINES
#include <cmath>     /// for std::pow(), std::sin(), and std::cos()
#include <iostream>  /// for IO operations

/**
 * @namespace physics
 * @brief Physics algorithms
 */

// Define gravity as a constant within guidelines
constexpr double GRAVITY = 9.80665; ///< Standard gravity (m/s^2)


namespace physics {
/**
 * @namespace ground_to_ground_projectile_motion
 * @brief Functions for the Ground to ground [projectile
 * motion](https://en.wikipedia.org/wiki/Projectile_motion) equation
 */
namespace ground_to_ground_projectile_motion {
/**
 * @brief Convert radians to degrees
 * @param radian Angle in radians
 * @returns Angle in degrees
 */

double degrees_to_radians(double degrees){
    double radians = degrees * (M_PI / 180);
    return radians;
}

/**
 * @brief Calculate the time of flight
 * @param initial_velocity The starting velocity of the projectile
 * @param angle The angle that the projectile is launched at in degrees
 * @param gravity The value used for the gravity constant
 * @returns The time that the projectile is in the air for
 */
template <typename T>
T time_of_flight(T initial_velocity, T angle, double gravity = GRAVITY) {
    double Viy = initial_velocity * (std::sin(degrees_to_radians(angle))); // calculate y component of the initial velocity
    return 2.0 * Viy / gravity;
}

/**
 * @brief Calculate the horizontal distance that the projectile travels
 * @param initial_velocity The starting velocity of the projectile
 * @param time The time that the projectile is in the air
 * @returns Horizontal distance that the projectile travels
 */
template <typename T>
T horizontal_range(T initial_velocity, T angle, T time) {
    double Vix = initial_velocity * (std::cos(degrees_to_radians(angle))); // calculate x component of the initial velocity
    return Vix * time;
}

/**
 * @brief Calculate the max height of the projectile
 * @param initial_velocity The starting velocity of the projectile
 * @param angle The angle that the projectile is launched at in degrees
 * @param gravity The value used for the gravity constant
 * @returns The max height that the projectile reaches
 */
template <typename T>
T max_height(T initial_velocity, T angle, double gravity = GRAVITY) {
    double Viy = initial_velocity * (std::sin(degrees_to_radians(angle))); // calculate y component of the initial velocity
    return (std::pow(Viy, 2) / (2.0 * gravity));
}
}  // namespace ground_to_ground_projectile_motion
}  // namespace physics

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // initial input variables
    double initial_velocity = 5.0;  // double initial_velocity input
    double angle = 40.0;            // double angle input

    // 1st test
    double expected_time_of_flight = 0.655;  // expected time output
    double flight_time_output =
        std::round(physics::ground_to_ground_projectile_motion::time_of_flight(initial_velocity, angle) * 1000.0) /
        1000.0;  // round output to 3 decimal places

    std::cout << "Projectile Flight Time (double)" << std::endl;
    std::cout << "Input Initial Velocity: " << initial_velocity << std::endl;
    std::cout << "Input Angle: " << angle << std::endl;
    std::cout << "Expected Output: " << expected_time_of_flight << std::endl;
    std::cout << "Output: " << flight_time_output << std::endl;
    assert(flight_time_output == expected_time_of_flight);
    std::cout << "TEST PASSED" << std::endl << std::endl;

    // 2nd test
    double expected_horizontal_range = 2.51; // expected range output
    double horizontal_range_output =
        std::round(physics::ground_to_ground_projectile_motion::horizontal_range(initial_velocity, angle,
                                             flight_time_output) *
                   100.0) /
        100.0;  // round output to 2 decimal places

    std::cout << "Projectile Horizontal Range (double)" << std::endl;
    std::cout << "Input Initial Velocity: " << initial_velocity << std::endl;
    std::cout << "Input Angle: " << angle << std::endl;
    std::cout << "Input Time Of Flight: " << flight_time_output << std::endl;
    std::cout << "Expected Output: " << expected_horizontal_range << std::endl;
    std::cout << "Output: " << horizontal_range_output << std::endl;
    assert(horizontal_range_output == expected_horizontal_range);
    std::cout << "TEST PASSED" << std::endl << std::endl;

    // 3rd test
    double expected_max_height = 0.526; // expected height output
    double max_height_output =
        std::round(physics::ground_to_ground_projectile_motion::max_height(initial_velocity, angle) * 1000.0) /
        1000.0;  // round output to 3 decimal places

    std::cout << "Projectile Max Height (double)" << std::endl;
    std::cout << "Input Initial Velocity: " << initial_velocity << std::endl;
    std::cout << "Input Angle: " << angle << std::endl;
    std::cout << "Expected Output: " << expected_max_height << std::endl;
    std::cout << "Output: " << max_height_output << std::endl;
    assert(max_height_output == expected_max_height);
    std::cout << "TEST PASSED" << std::endl << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Ground-to-ground projectile motion formulas: time of flight,
 * horizontal range, and maximum height.
 * @details A ground-to-ground projectile launches from the ground, rises to
 * its peak, and lands back at ground level.
 */

#include <cassert>   /// for assert()
#define _USE_MATH_DEFINES
#include <cmath>     /// for std::pow(), std::sin(), and std::cos()
#include <iostream>  /// for IO operations

/**
 * @namespace physics
 * @brief Physics algorithms
 */

// Standard gravitational acceleration used by every formula below.
constexpr double STANDARD_GRAVITY = 9.80665;  ///< m/s^2

namespace physics {
/**
 * @namespace ground_to_ground_projectile_motion
 * @brief Ground-to-ground projectile motion formulas
 */
namespace ground_to_ground_projectile_motion {

/**
 * @brief Converts an angle from degrees to radians.
 * @param angleDegrees angle expressed in degrees
 * @returns the same angle expressed in radians
 */
double toRadians(double angleDegrees) {
    return angleDegrees * (M_PI / 180.0);
}

/**
 * @brief Computes how long the projectile stays airborne.
 * @param launchSpeed initial speed of the projectile
 * @param launchAngle launch angle in degrees
 * @param gravity gravitational acceleration to use
 * @returns total flight duration
 */
template <typename NumT>
NumT flightDuration(NumT launchSpeed, NumT launchAngle,
                     double gravity = STANDARD_GRAVITY) {
    double verticalSpeed = launchSpeed * std::sin(toRadians(launchAngle));
    return 2.0 * verticalSpeed / gravity;
}

/**
 * @brief Computes the horizontal distance covered during the flight.
 * @param launchSpeed initial speed of the projectile
 * @param launchAngle launch angle in degrees
 * @param duration total flight duration
 * @returns horizontal distance traveled
 */
template <typename NumT>
NumT rangeCovered(NumT launchSpeed, NumT launchAngle, NumT duration) {
    double horizontalSpeed = launchSpeed * std::cos(toRadians(launchAngle));
    return horizontalSpeed * duration;
}

/**
 * @brief Computes the peak height reached by the projectile.
 * @param launchSpeed initial speed of the projectile
 * @param launchAngle launch angle in degrees
 * @param gravity gravitational acceleration to use
 * @returns maximum height reached
 */
template <typename NumT>
NumT peakHeight(NumT launchSpeed, NumT launchAngle,
                double gravity = STANDARD_GRAVITY) {
    double verticalSpeed = launchSpeed * std::sin(toRadians(launchAngle));
    return std::pow(verticalSpeed, 2) / (2.0 * gravity);
}

}  // namespace ground_to_ground_projectile_motion
}  // namespace physics

/**
 * @brief Self-test implementations
 * @returns void
 */
static void runChecks() {
    double launchSpeed = 5.0;
    double launchAngle = 40.0;

    // Check 1: flight duration
    double expectedDuration = 0.655;
    double actualDuration =
        std::round(physics::ground_to_ground_projectile_motion::flightDuration(
                       launchSpeed, launchAngle) *
                   1000.0) /
        1000.0;

    std::cout << "Projectile Flight Time (double)" << std::endl;
    std::cout << "Input Initial Velocity: " << launchSpeed << std::endl;
    std::cout << "Input Angle: " << launchAngle << std::endl;
    std::cout << "Expected Output: " << expectedDuration << std::endl;
    std::cout << "Output: " << actualDuration << std::endl;
    assert(actualDuration == expectedDuration);
    std::cout << "TEST PASSED" << std::endl << std::endl;

    // Check 2: horizontal range
    double expectedRange = 2.51;
    double actualRange =
        std::round(physics::ground_to_ground_projectile_motion::rangeCovered(
                       launchSpeed, launchAngle, actualDuration) *
                   100.0) /
        100.0;

    std::cout << "Projectile Horizontal Range (double)" << std::endl;
    std::cout << "Input Initial Velocity: " << launchSpeed << std::endl;
    std::cout << "Input Angle: " << launchAngle << std::endl;
    std::cout << "Input Time Of Flight: " << actualDuration << std::endl;
    std::cout << "Expected Output: " << expectedRange << std::endl;
    std::cout << "Output: " << actualRange << std::endl;
    assert(actualRange == expectedRange);
    std::cout << "TEST PASSED" << std::endl << std::endl;

    // Check 3: max height
    double expectedPeak = 0.526;
    double actualPeak =
        std::round(physics::ground_to_ground_projectile_motion::peakHeight(
                       launchSpeed, launchAngle) *
                   1000.0) /
        1000.0;

    std::cout << "Projectile Max Height (double)" << std::endl;
    std::cout << "Input Initial Velocity: " << launchSpeed << std::endl;
    std::cout << "Input Angle: " << launchAngle << std::endl;
    std::cout << "Expected Output: " << expectedPeak << std::endl;
    std::cout << "Output: " << actualPeak << std::endl;
    assert(actualPeak == expectedPeak);
    std::cout << "TEST PASSED" << std::endl << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Addition rule of probabilities
 */
#include <iostream>

/**
 * calculates the probability of the independent events A or B for independent
 * events
 * \parama [in] A probability of event A
 * \parama [in] B probability of event B
 * \returns probability of A and B
 */
double addition_rule_independent(double A, double B) {
    return (A + B) - (A * B);
}

/** Calculates the probability of the events A or B for dependent events
 * note that if value of B_given_A is unknown, use chainrule to find it
 * \parama [in] A probability of event A
 * \parama [in] B probability of event B
 * \parama [in] B_given_A probability of event B condition A
 * \returns probability of A and B
 */
double addition_rule_dependent(double A, double B, double B_given_A) {
    return (A + B) - (A * B_given_A);
}

/** Main function */
int main() {
    double A = 0.5;
    double B = 0.25;
    double B_given_A = 0.05;

    std::cout << "independent P(A or B) = " << addition_rule_independent(A, B)
              << std::endl;

    std::cout << "dependent P(A or B) = "
              << addition_rule_dependent(A, B, B_given_A) << std::endl;

    return 0;
}

/**
 * @file
 * @brief Union probability helpers (the "addition rule")
 *
 * Small utility functions that answer "what is the chance that
 * at least one of two events happens", both for the case where the
 * events don't influence each other and the case where they do.
 */
#include <iostream>

/**
 * Union probability for two events that do not influence one another.
 * \param [in] probA chance that the first event happens
 * \param [in] probB chance that the second event happens
 * \returns chance that the first event, the second event, or both occur
 */
double unionProbabilityIndependent(double probA, double probB) {
    return (probA + probB) - (probA * probB);
}

/** Union probability for two events where one affects the likelihood of
 * the other.
 * If probBGivenA is not already known, derive it first via the chain rule.
 * \param [in] probA chance that the first event happens
 * \param [in] probB chance that the second event happens
 * \param [in] probBGivenA chance of the second event given the first already
 * occurred
 * \returns chance that the first event, the second event, or both occur
 */
double unionProbabilityDependent(double probA, double probB,
                                  double probBGivenA) {
    return (probA + probB) - (probA * probBGivenA);
}

/** Entry point demonstrating both union-probability variants */
int main() {
    const double eventOneChance = 0.5;
    const double eventTwoChance = 0.25;
    const double eventTwoGivenOneChance = 0.05;

    std::cout << "Union probability (independent events): "
              << unionProbabilityIndependent(eventOneChance, eventTwoChance)
              << std::endl;

    std::cout << "Union probability (dependent events): "
              << unionProbabilityDependent(eventOneChance, eventTwoChance,
                                            eventTwoGivenOneChance)
              << std::endl;

    return 0;
}

/**
 * @file
 * @brief [Bayes' theorem](https://en.wikipedia.org/wiki/Bayes%27_theorem)
 *
 * Bayes' theorem allows one to find \f$P(A|B)\f$ given \f$P(B|A)\f$ or
 * \f$P(B|A)\f$ given \f$P(A|B)\f$ and \f$P(A)\f$ and \f$P(B)\f$.\n
 * Note that \f$P(A|B)\f$ is read 'The probability of A given that the event B
 * has occured'.
 */
#include <iostream>

/** returns P(A|B)
 */
double bayes_AgivenB(double BgivenA, double A, double B) {
    return (BgivenA * A) / B;
}

/** returns P(B|A)
 */
double bayes_BgivenA(double AgivenB, double A, double B) {
    return (AgivenB * B) / A;
}

/** Main function
 */
int main() {
    double A = 0.01;
    double B = 0.1;
    double BgivenA = 0.9;
    double AgivenB = bayes_AgivenB(BgivenA, A, B);
    std::cout << "A given B = " << AgivenB << std::endl;
    std::cout << "B given A = " << bayes_BgivenA(AgivenB, A, B) << std::endl;
    return 0;
}

/**
 * @file
 * @brief [Bayes' theorem](https://en.wikipedia.org/wiki/Bayes%27_theorem)
 * helper routines
 *
 * Bayes' theorem lets you flip a conditional probability around: given
 * P(effect | cause) plus the marginal probabilities of cause and effect,
 * you can recover P(cause | effect), and vice versa. Reading "X given Y"
 * means "the probability of X once we already know Y happened".
 */
#include <iostream>

/** Recovers P(cause | effect) from P(effect | cause).
 */
double posteriorCauseGivenEffect(double effectGivenCause, double priorCause,
                                  double priorEffect) {
    return (effectGivenCause * priorCause) / priorEffect;
}

/** Recovers P(effect | cause) from P(cause | effect).
 */
double posteriorEffectGivenCause(double causeGivenEffect, double priorCause,
                                  double priorEffect) {
    return (causeGivenEffect * priorEffect) / priorCause;
}

/** Demo entry point */
int main() {
    const double priorCause = 0.01;
    const double priorEffect = 0.1;
    const double effectGivenCause = 0.9;

    const double causeGivenEffect =
        posteriorCauseGivenEffect(effectGivenCause, priorCause, priorEffect);
    std::cout << "cause given effect = " << causeGivenEffect << std::endl;

    std::cout << "effect given cause = "
              << posteriorEffectGivenCause(causeGivenEffect, priorCause,
                                            priorEffect)
              << std::endl;
    return 0;
}

/**
 * @file
 * @brief [Binomial
 * distribution](https://en.wikipedia.org/wiki/Binomial_distribution) example
 *
 * The binomial distribution models the number of
 * successes in a sequence of n independent events
 *
 * Summary of variables used:
 * * n : number of trials
 * * p : probability of success
 * * x : desired successes
 */
#include <cmath>
#include <iostream>

/** finds the expected value of a binomial distribution
 * \param [in] n
 * \param [in] p
 * \returns \f$\mu=np\f$
 */
double binomial_expected(double n, double p) { return n * p; }

/** finds the variance of the binomial distribution
 * \param [in] n
 * \param [in] p
 * \returns \f$\sigma^2 = n\cdot p\cdot (1-p)\f$
 */
double binomial_variance(double n, double p) { return n * p * (1 - p); }

/** finds the standard deviation of the binomial distribution
 * \param [in] n
 * \param [in] p
 * \returns \f$\sigma = \sqrt{\sigma^2} = \sqrt{n\cdot p\cdot (1-p)}\f$
 */
double binomial_standard_deviation(double n, double p) {
    return std::sqrt(binomial_variance(n, p));
}

/** Computes n choose r
 * \param [in] n
 * \param [in] r
 * \returns \f$\displaystyle {n\choose r} =
 * \frac{n!}{r!(n-r)!} = \frac{n\times(n-1)\times(n-2)\times\cdots(n-r)}{r!}
 * \f$
 */
double nCr(double n, double r) {
    double numerator = n;
    double denominator = r;

    for (int i = n - 1; i >= ((n - r) + 1); i--) {
        numerator *= i;
    }

    for (int i = 1; i < r; i++) {
        denominator *= i;
    }

    return numerator / denominator;
}

/** calculates the probability of exactly x successes
 * \returns \f$\displaystyle P(n,p,x) = {n\choose x} p^x (1-p)^{n-x}\f$
 */
double binomial_x_successes(double n, double p, double x) {
    return nCr(n, x) * std::pow(p, x) * std::pow(1 - p, n - x);
}

/** calculates the probability of a result within a range (inclusive, inclusive)
 * \returns \f$\displaystyle \left.P(n,p)\right|_{x_0}^{x_1} =
 * \sum_{i=x_0}^{x_1} P(i)
 * =\sum_{i=x_0}^{x_1} {n\choose i} p^i (1-p)^{n-i}\f$
 */
double binomial_range_successes(double n, double p, double lower_bound,
                                double upper_bound) {
    double probability = 0;
    for (int i = lower_bound; i <= upper_bound; i++) {
        probability += nCr(n, i) * std::pow(p, i) * std::pow(1 - p, n - i);
    }
    return probability;
}

/** main function */
int main() {
    std::cout << "expected value : " << binomial_expected(100, 0.5)
              << std::endl;

    std::cout << "variance : " << binomial_variance(100, 0.5) << std::endl;

    std::cout << "standard deviation : "
              << binomial_standard_deviation(100, 0.5) << std::endl;

    std::cout << "exactly 30 successes : " << binomial_x_successes(100, 0.5, 30)
              << std::endl;

    std::cout << "45 or more successes : "
              << binomial_range_successes(100, 0.5, 45, 100) << std::endl;

    return 0;
}

/**
 * @file
 * @brief [Binomial
 * distribution](https://en.wikipedia.org/wiki/Binomial_distribution) toolkit
 *
 * The binomial distribution describes how many successes show up across a
 * fixed number of independent, identical trials.
 *
 * Naming used below:
 * * trialCount : how many trials are run
 * * successChance : probability that a single trial succeeds
 * * targetSuccesses : the success count we care about
 */
#include <cmath>
#include <iostream>

/** Computes "n choose r".
 * \param [in] n total items
 * \param [in] r items chosen
 * \returns the binomial coefficient C(n, r)
 */
double combinations(double n, double r) {
    double top = n;
    double bottom = r;

    for (int i = static_cast<int>(n) - 1; i >= static_cast<int>(n - r) + 1;
         i--) {
        top *= i;
    }

    for (int i = 1; i < static_cast<int>(r); i++) {
        bottom *= i;
    }

    return top / bottom;
}

/** Mean of the binomial distribution.
 * \returns mu = trialCount * successChance
 */
double meanOfBinomial(double trialCount, double successChance) {
    return trialCount * successChance;
}

/** Variance of the binomial distribution.
 * \returns sigma^2 = trialCount * successChance * (1 - successChance)
 */
double varianceOfBinomial(double trialCount, double successChance) {
    return trialCount * successChance * (1 - successChance);
}

/** Standard deviation of the binomial distribution.
 * \returns sqrt(variance)
 */
double stdDevOfBinomial(double trialCount, double successChance) {
    return std::sqrt(varianceOfBinomial(trialCount, successChance));
}

/** Probability of landing on exactly one particular success count.
 * \returns C(trialCount, targetSuccesses) * p^k * (1-p)^(n-k)
 */
double probabilityOfExactSuccesses(double trialCount, double successChance,
                                    double targetSuccesses) {
    return combinations(trialCount, targetSuccesses) *
           std::pow(successChance, targetSuccesses) *
           std::pow(1 - successChance, trialCount - targetSuccesses);
}

/** Probability that the success count falls in an inclusive range.
 * \returns sum over the range of the exact-success probability
 */
double probabilityOfSuccessRange(double trialCount, double successChance,
                                  double minSuccesses, double maxSuccesses) {
    double total = 0;
    for (int successes = static_cast<int>(minSuccesses);
         successes <= static_cast<int>(maxSuccesses); successes++) {
        total += combinations(trialCount, successes) *
                 std::pow(successChance, successes) *
                 std::pow(1 - successChance, trialCount - successes);
    }
    return total;
}

/** Demo entry point */
int main() {
    const double trials = 100;
    const double chance = 0.5;

    std::cout << "mean : " << meanOfBinomial(trials, chance) << std::endl;

    std::cout << "variance : " << varianceOfBinomial(trials, chance)
              << std::endl;

    std::cout << "standard deviation : " << stdDevOfBinomial(trials, chance)
              << std::endl;

    std::cout << "probability of exactly 30 successes : "
              << probabilityOfExactSuccesses(trials, chance, 30) << std::endl;

    std::cout << "probability of 45 or more successes : "
              << probabilityOfSuccessRange(trials, chance, 45, 100)
              << std::endl;

    return 0;
}

/**
 * @file
 * @brief [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 *
 * The exponential distribution is used to model
 * events occuring between a Poisson process like radioactive decay.
 *
 * \f[P(x, \lambda) = \lambda e^{-\lambda x}\f]
 *
 * Summary of variables used:
 * \f$\lambda\f$ : rate parameter
 */

#include <cassert>    // For assert
#include <cmath>      // For std::pow
#include <iostream>   // For I/O operation
#include <stdexcept>  // For std::invalid_argument
#include <string>     // For std::string

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace exponential_dist
 * @brief Functions for the [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 * algorithm implementation
 */
namespace geometric_dist {
/**
 * @brief the expected value of the exponential distribution
 * @returns \f[\mu = \frac{1}{\lambda}\f]
 */
double exponential_expected(double lambda) {
    if (lambda <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
    return 1 / lambda;
}

/**
 * @brief the variance of the exponential distribution
 * @returns \f[\sigma^2 = \frac{1}{\lambda^2}\f]
 */
double exponential_var(double lambda) {
    if (lambda <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
    return 1 / pow(lambda, 2);
}

/**
 * @brief the standard deviation of the exponential distribution
 * @returns \f[\sigma = \frac{1}{\lambda}\f]
 */
double exponential_std(double lambda) {
    if (lambda <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
    return 1 / lambda;
}
}  // namespace geometric_dist
}  // namespace probability

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    double lambda_1 = 1;
    double expected_1 = 1;
    double var_1 = 1;
    double std_1 = 1;

    double lambda_2 = 2;
    double expected_2 = 0.5;
    double var_2 = 0.25;
    double std_2 = 0.5;

    double lambda_3 = 3;
    double expected_3 = 0.333333;
    double var_3 = 0.111111;
    double std_3 = 0.333333;

    double lambda_4 = 0;     // Test 0
    double lambda_5 = -2.3;  // Test negative value

    const float threshold = 1e-3f;

    std::cout << "Test for lambda = 1 \n";
    assert(
        std::abs(expected_1 - probability::geometric_dist::exponential_expected(
                                  lambda_1)) < threshold);
    assert(std::abs(var_1 - probability::geometric_dist::exponential_var(
                                lambda_1)) < threshold);
    assert(std::abs(std_1 - probability::geometric_dist::exponential_std(
                                lambda_1)) < threshold);
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = 2 \n";
    assert(
        std::abs(expected_2 - probability::geometric_dist::exponential_expected(
                                  lambda_2)) < threshold);
    assert(std::abs(var_2 - probability::geometric_dist::exponential_var(
                                lambda_2)) < threshold);
    assert(std::abs(std_2 - probability::geometric_dist::exponential_std(
                                lambda_2)) < threshold);
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = 3 \n";
    assert(
        std::abs(expected_3 - probability::geometric_dist::exponential_expected(
                                  lambda_3)) < threshold);
    assert(std::abs(var_3 - probability::geometric_dist::exponential_var(
                                lambda_3)) < threshold);
    assert(std::abs(std_3 - probability::geometric_dist::exponential_std(
                                lambda_3)) < threshold);
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = 0 \n";
    try {
        probability::geometric_dist::exponential_expected(lambda_4);
        probability::geometric_dist::exponential_var(lambda_4);
        probability::geometric_dist::exponential_std(lambda_4);
    } catch (std::invalid_argument& err) {
        assert(std::string(err.what()) == "lambda must be greater than 0");
    }
    std::cout << "ALL TEST PASSED\n\n";

    std::cout << "Test for lambda = -2.3 \n";
    try {
        probability::geometric_dist::exponential_expected(lambda_5);
        probability::geometric_dist::exponential_var(lambda_5);
        probability::geometric_dist::exponential_std(lambda_5);
    } catch (std::invalid_argument& err) {
        assert(std::string(err.what()) == "lambda must be greater than 0");
    }
    std::cout << "ALL TEST PASSED\n\n";
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    test();  // Self test implementation
    return 0;
}

/**
 * @file
 * @brief [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 * routines
 *
 * The exponential distribution models the waiting time between successive
 * events of a Poisson process, such as radioactive decay.
 *
 * \f[f(x, \lambda) = \lambda e^{-\lambda x}\f]
 *
 * Naming used below:
 * \f$\lambda\f$ (rate) : the rate parameter of the process
 */

#include <cassert>    // For assert
#include <cmath>      // For std::pow
#include <iostream>   // For I/O operation
#include <stdexcept>  // For std::invalid_argument
#include <string>     // For std::string

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace exponential_dist
 * @brief Functions for the [Exponential
 * Distribution](https://en.wikipedia.org/wiki/Exponential_distribution)
 * algorithm implementation
 */
namespace exponential_dist {
/**
 * @brief Validates that a rate parameter is usable, throwing otherwise.
 * @param rate the rate parameter to validate
 */
void ensurePositiveRate(double rate) {
    if (rate <= 0) {
        throw std::invalid_argument("lambda must be greater than 0");
    }
}

/**
 * @brief the mean of the exponential distribution
 * @returns \f[\mu = \frac{1}{\lambda}\f]
 */
double distributionMean(double rate) {
    ensurePositiveRate(rate);
    return 1 / rate;
}

/**
 * @brief the variance of the exponential distribution
 * @returns \f[\sigma^2 = \frac{1}{\lambda^2}\f]
 */
double distributionVariance(double rate) {
    ensurePositiveRate(rate);
    return 1 / pow(rate, 2);
}

/**
 * @brief the standard deviation of the exponential distribution
 * @returns \f[\sigma = \frac{1}{\lambda}\f]
 */
double distributionStdDev(double rate) {
    ensurePositiveRate(rate);
    return 1 / rate;
}
}  // namespace exponential_dist
}  // namespace probability

/**
 * @brief Runs a battery of checks for a single rate value, comparing the
 * computed mean/variance/std-dev against expected constants.
 * @returns void
 */
static void checkRate(double rate, double expectedMean, double expectedVar,
                       double expectedStd, float tolerance) {
    std::cout << "Checking lambda = " << rate << "\n";
    assert(std::abs(expectedMean -
                     probability::exponential_dist::distributionMean(rate)) <
           tolerance);
    assert(std::abs(expectedVar - probability::exponential_dist::
                                       distributionVariance(rate)) <
           tolerance);
    assert(std::abs(expectedStd -
                     probability::exponential_dist::distributionStdDev(
                         rate)) < tolerance);
    std::cout << "ALL TEST PASSED\n\n";
}

/**
 * @brief Confirms that invalid rate values raise the expected exception.
 * @returns void
 */
static void checkInvalidRate(double rate) {
    std::cout << "Checking lambda = " << rate << "\n";
    try {
        probability::exponential_dist::distributionMean(rate);
        probability::exponential_dist::distributionVariance(rate);
        probability::exponential_dist::distributionStdDev(rate);
    } catch (std::invalid_argument& err) {
        assert(std::string(err.what()) == "lambda must be greater than 0");
    }
    std::cout << "ALL TEST PASSED\n\n";
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    const float tolerance = 1e-3f;

    checkRate(1, 1, 1, 1, tolerance);
    checkRate(2, 0.5, 0.25, 0.5, tolerance);
    checkRate(3, 0.333333, 0.111111, 0.333333, tolerance);

    checkInvalidRate(0);      // boundary case
    checkInvalidRate(-2.3);   // negative rate
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    test();  // Self test implementation
    return 0;
}

/**
 * @file
 * @brief [Geometric
 * Distribution](https://en.wikipedia.org/wiki/Geometric_distribution)
 *
 * @details
 * The geometric distribution models the experiment of doing Bernoulli trials
 * until a sucess was observed. There are two formulations of the geometric
 * distribution: 1) The probability distribution of the number X of Bernoulli
 * trials needed to get one success, supported on the set { 1, 2, 3, ... } 2)
 * The probability distribution of the number Y = X − 1 of failures before the
 * first success, supported on the set { 0, 1, 2, 3, ... } Here, the first one
 * is implemented.
 *
 * Common variables used:
 * p - The success probability
 * k - The number of tries
 *
 * @author [Domenic Zingsheim](https://github.com/DerAndereDomenic)
 */

#include <cassert>   /// for assert
#include <cmath>     /// for math functions
#include <cstdint>   /// for fixed size data types
#include <ctime>     /// for time to initialize rng
#include <iostream>  /// for std::cout
#include <limits>    /// for std::numeric_limits
#include <random>    /// for random numbers
#include <vector>    /// for std::vector

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace geometric_dist
 * @brief Functions for the [Geometric
 * Distribution](https://en.wikipedia.org/wiki/Geometric_distribution) algorithm
 * implementation
 */
namespace geometric_dist {
/**
 * @brief Returns a random number between [0,1]
 * @returns A uniformly distributed random number between 0 (included) and 1
 * (included)
 */
float generate_uniform() {
    return static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
}

/**
 * @brief A class to model the geometric distribution
 */
class geometric_distribution {
 private:
    float p;  ///< The succes probability p

 public:
    /**
     * @brief Constructor for the geometric distribution
     * @param p The success probability
     */
    explicit geometric_distribution(const float& p) : p(p) {}

    /**
     * @brief The expected value of a geometrically distributed random variable
     * X
     * @returns E[X] = 1/p
     */
    float expected_value() const { return 1.0f / p; }

    /**
     * @brief The variance of a geometrically distributed random variable X
     * @returns V[X] = (1 - p) / p^2
     */
    float variance() const { return (1.0f - p) / (p * p); }

    /**
     * @brief The standard deviation of a geometrically distributed random
     * variable X
     * @returns \sigma = \sqrt{V[X]}
     */
    float standard_deviation() const { return std::sqrt(variance()); }

    /**
     * @brief The probability density function
     * @details As we use the first definition of the geometric series (1),
     * we are doing k - 1 failed trials and the k-th trial is a success.
     * @param k The number of trials to observe the first success in [1,\infty)
     * @returns A number between [0,1] according to p * (1-p)^{k-1}
     */
    float probability_density(const uint32_t& k) const {
        return std::pow((1.0f - p), static_cast<float>(k - 1)) * p;
    }

    /**
     * @brief The cumulative distribution function
     * @details The sum of all probabilities up to (and including) k trials.
     * Basically CDF(k) = P(x <= k)
     * @param k The number of trials in [1,\infty)
     * @returns The probability to have success within k trials
     */
    float cumulative_distribution(const uint32_t& k) const {
        return 1.0f - std::pow((1.0f - p), static_cast<float>(k));
    }

    /**
     * @brief The inverse cumulative distribution function
     * @details This functions answers the question: Up to how many trials are
     * needed to have success with a probability of cdf? The exact floating
     * point value is reported.
     * @param cdf The probability in [0,1]
     * @returns The number of (exact) trials.
     */
    float inverse_cumulative_distribution(const float& cdf) const {
        return std::log(1.0f - cdf) / std::log(1.0f - p);
    }

    /**
     * @brief Generates a (discrete) sample according to the geometrical
     * distribution
     * @returns A geometrically distributed number in [1,\infty)
     */
    uint32_t draw_sample() const {
        float uniform_sample = generate_uniform();
        return static_cast<uint32_t>(
                   inverse_cumulative_distribution(uniform_sample)) +
               1;
    }

    /**
     * @brief This function computes the probability to have success in a given
     * range of tries
     * @details Computes P(min_tries <= x <= max_tries).
     * Can be used to calculate P(x >= min_tries) by not passing a second
     * argument. Can be used to calculate P(x <= max_tries) by passing 1 as the
     * first argument
     * @param min_tries The minimum number of tries in [1,\infty) (inclusive)
     * @param max_tries The maximum number of tries in [min_tries, \infty)
     * (inclusive)
     * @returns The probability of having success within a range of tries
     * [min_tries, max_tries]
     */
    float range_tries(const uint32_t& min_tries = 1,
                      const uint32_t& max_tries =
                          std::numeric_limits<uint32_t>::max()) const {
        float cdf_lower = cumulative_distribution(min_tries - 1);
        float cdf_upper = max_tries == std::numeric_limits<uint32_t>::max()
                              ? 1.0f
                              : cumulative_distribution(max_tries);
        return cdf_upper - cdf_lower;
    }
};
}  // namespace geometric_dist
}  // namespace probability

/**
 * @brief Tests the sampling method of the geometric distribution
 * @details Draws 1000000 random samples and estimates mean and variance
 * These should be close to the expected value and variance of the given
 * distribution to pass.
 * @param dist The distribution to test
 */
void sample_test(
    const probability::geometric_dist::geometric_distribution& dist) {
    uint32_t n_tries = 1000000;
    std::vector<float> tries;
    tries.resize(n_tries);

    float mean = 0.0f;
    for (uint32_t i = 0; i < n_tries; ++i) {
        tries[i] = static_cast<float>(dist.draw_sample());
        mean += tries[i];
    }

    mean /= static_cast<float>(n_tries);

    float var = 0.0f;
    for (uint32_t i = 0; i < n_tries; ++i) {
        var += (tries[i] - mean) * (tries[i] - mean);
    }

    // Unbiased estimate of variance
    var /= static_cast<float>(n_tries - 1);

    std::cout << "This value should be near " << dist.expected_value() << ": "
              << mean << std::endl;
    std::cout << "This value should be near " << dist.variance() << ": " << var
              << std::endl;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    probability::geometric_dist::geometric_distribution dist(0.3);

    const float threshold = 1e-3f;

    std::cout << "Starting tests for p = 0.3..." << std::endl;
    assert(std::abs(dist.expected_value() - 3.33333333f) < threshold);
    assert(std::abs(dist.variance() - 7.77777777f) < threshold);
    assert(std::abs(dist.standard_deviation() - 2.788866755) < threshold);
    assert(std::abs(dist.probability_density(5) - 0.07203) < threshold);
    assert(std::abs(dist.cumulative_distribution(6) - 0.882351) < threshold);
    assert(std::abs(dist.inverse_cumulative_distribution(
                        dist.cumulative_distribution(8)) -
                    8) < threshold);
    assert(std::abs(dist.range_tries() - 1.0f) < threshold);
    assert(std::abs(dist.range_tries(3) - 0.49f) < threshold);
    assert(std::abs(dist.range_tries(5, 11) - 0.2203267f) < threshold);
    std::cout << "All tests passed" << std::endl;
    sample_test(dist);

    dist = probability::geometric_dist::geometric_distribution(0.5f);

    std::cout << "Starting tests for p = 0.5..." << std::endl;
    assert(std::abs(dist.expected_value() - 2.0f) < threshold);
    assert(std::abs(dist.variance() - 2.0f) < threshold);
    assert(std::abs(dist.standard_deviation() - 1.4142135f) < threshold);
    assert(std::abs(dist.probability_density(5) - 0.03125) < threshold);
    assert(std::abs(dist.cumulative_distribution(6) - 0.984375) < threshold);
    assert(std::abs(dist.inverse_cumulative_distribution(
                        dist.cumulative_distribution(8)) -
                    8) < threshold);
    assert(std::abs(dist.range_tries() - 1.0f) < threshold);
    assert(std::abs(dist.range_tries(3) - 0.25f) < threshold);
    assert(std::abs(dist.range_tries(5, 11) - 0.062011f) < threshold);
    std::cout << "All tests passed" << std::endl;
    sample_test(dist);

    dist = probability::geometric_dist::geometric_distribution(0.8f);

    std::cout << "Starting tests for p = 0.8..." << std::endl;
    assert(std::abs(dist.expected_value() - 1.25f) < threshold);
    assert(std::abs(dist.variance() - 0.3125f) < threshold);
    assert(std::abs(dist.standard_deviation() - 0.559016f) < threshold);
    assert(std::abs(dist.probability_density(5) - 0.00128) < threshold);
    assert(std::abs(dist.cumulative_distribution(6) - 0.999936) < threshold);
    assert(std::abs(dist.inverse_cumulative_distribution(
                        dist.cumulative_distribution(8)) -
                    8) < threshold);
    assert(std::abs(dist.range_tries() - 1.0f) < threshold);
    assert(std::abs(dist.range_tries(3) - 0.04f) < threshold);
    assert(std::abs(dist.range_tries(5, 11) - 0.00159997f) < threshold);
    std::cout << "All tests have successfully passed!" << std::endl;
    sample_test(dist);
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    srand(time(nullptr));
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief [Geometric
 * Distribution](https://en.wikipedia.org/wiki/Geometric_distribution)
 * implementation
 *
 * @details
 * The geometric distribution models repeating a Bernoulli trial until the
 * first success shows up. Two equivalent formulations exist:
 * 1) The count X of trials needed to see one success, over {1, 2, 3, ...}
 * 2) The count Y = X - 1 of failures preceding the first success, over
 *    {0, 1, 2, 3, ...}
 * This file implements the first formulation.
 *
 * Naming used below:
 * successChance - probability that a single trial succeeds
 * tries - number of trials performed
 *
 * @author Rewritten for classroom dataset purposes
 */

#include <cassert>   /// for assert
#include <cmath>     /// for math functions
#include <cstdint>   /// for fixed size data types
#include <ctime>     /// for time to initialize rng
#include <iostream>  /// for std::cout
#include <limits>    /// for std::numeric_limits
#include <random>    /// for random numbers
#include <vector>    /// for std::vector

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace geometric_dist
 * @brief Functions for the [Geometric
 * Distribution](https://en.wikipedia.org/wiki/Geometric_distribution)
 * algorithm implementation
 */
namespace geometric_dist {
/**
 * @brief Produces a uniform random draw
 * @returns A uniformly distributed value in the closed interval [0, 1]
 */
float drawUniformSample() {
    return static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
}

/**
 * @brief Models a geometric distribution with a fixed success probability
 */
class GeometricLaw {
 public:
    /**
     * @brief Builds a geometric law with the given success probability
     * @param successChance The probability that any single trial succeeds
     */
    explicit GeometricLaw(const float& successChance)
        : successChance_(successChance) {}

    /**
     * @brief The mean number of trials needed for a success
     * @returns E[X] = 1 / successChance
     */
    float mean() const { return 1.0f / successChance_; }

    /**
     * @brief The variance of the number of trials needed for a success
     * @returns V[X] = (1 - successChance) / successChance^2
     */
    float variance() const {
        return (1.0f - successChance_) / (successChance_ * successChance_);
    }

    /**
     * @brief The standard deviation of the number of trials needed
     * @returns sqrt(V[X])
     */
    float stdDeviation() const { return std::sqrt(variance()); }

    /**
     * @brief Probability mass function
     * @details Following the "trials until first success" formulation,
     * there are tries - 1 failures followed by one success.
     * @param tries The trial count at which the first success occurs, in
     * [1, infinity)
     * @returns successChance * (1 - successChance)^(tries - 1)
     */
    float pmf(const uint32_t& tries) const {
        return std::pow((1.0f - successChance_),
                         static_cast<float>(tries - 1)) *
               successChance_;
    }

    /**
     * @brief Cumulative distribution function
     * @details Sums the pmf across every trial count up to and including
     * tries. cdf(tries) = P(X <= tries)
     * @param tries The trial count cutoff, in [1, infinity)
     * @returns The probability of succeeding within the given trial count
     */
    float cdf(const uint32_t& tries) const {
        return 1.0f -
               std::pow((1.0f - successChance_), static_cast<float>(tries));
    }

    /**
     * @brief Inverse of the cumulative distribution function
     * @details Answers: how many trials are needed to reach a given
     * cumulative probability? Returns the unrounded floating point answer.
     * @param cumulativeProb The target cumulative probability, in [0, 1]
     * @returns The (fractional) number of trials
     */
    float inverseCdf(const float& cumulativeProb) const {
        return std::log(1.0f - cumulativeProb) /
               std::log(1.0f - successChance_);
    }

    /**
     * @brief Draws a single sample from this geometric law
     * @returns A geometrically distributed integer in [1, infinity)
     */
    uint32_t sample() const {
        float u = drawUniformSample();
        return static_cast<uint32_t>(inverseCdf(u)) + 1;
    }

    /**
     * @brief Probability of succeeding within an inclusive range of trials
     * @details Computes P(minTries <= X <= maxTries). Omit maxTries to get
     * P(X >= minTries). Pass 1 as minTries to get P(X <= maxTries).
     * @param minTries Lower bound of trials, inclusive, in [1, infinity)
     * @param maxTries Upper bound of trials, inclusive, at least minTries
     * @returns The probability mass contained in the given range
     */
    float rangeProbability(const uint32_t& minTries = 1,
                            const uint32_t& maxTries =
                                std::numeric_limits<uint32_t>::max()) const {
        float lowerCdf = cdf(minTries - 1);
        float upperCdf = maxTries == std::numeric_limits<uint32_t>::max()
                              ? 1.0f
                              : cdf(maxTries);
        return upperCdf - lowerCdf;
    }

 private:
    float successChance_;  ///< The probability that a single trial succeeds
};
}  // namespace geometric_dist
}  // namespace probability

/**
 * @brief Empirically validates the sampling routine of a geometric law
 * @details Draws a large batch of samples and checks that the sample mean
 * and sample variance land close to the theoretical values.
 * @param law The distribution instance under test
 */
void verifySampling(const probability::geometric_dist::GeometricLaw& law) {
    const uint32_t sampleCount = 1000000;
    std::vector<float> draws(sampleCount);

    float runningMean = 0.0f;
    for (uint32_t i = 0; i < sampleCount; ++i) {
        draws[i] = static_cast<float>(law.sample());
        runningMean += draws[i];
    }
    runningMean /= static_cast<float>(sampleCount);

    float runningVar = 0.0f;
    for (uint32_t i = 0; i < sampleCount; ++i) {
        runningVar += (draws[i] - runningMean) * (draws[i] - runningMean);
    }
    // unbiased sample variance
    runningVar /= static_cast<float>(sampleCount - 1);

    std::cout << "Expected mean near " << law.mean() << ": " << runningMean
              << std::endl;
    std::cout << "Expected variance near " << law.variance() << ": "
              << runningVar << std::endl;
}

/**
 * @brief Checks the closed-form formulas of a geometric law against known
 * constants, then runs the sampling verification.
 * @param law distribution under test
 * @param meanExpect expected mean
 * @param varExpect expected variance
 * @param stdExpect expected standard deviation
 * @param pmfAt5 expected pmf value at tries = 5
 * @param cdfAt6 expected cdf value at tries = 6
 * @param rangeAt3 expected rangeProbability(3)
 * @param rangeAt5to11 expected rangeProbability(5, 11)
 * @param tolerance allowed absolute error
 */
static void checkLaw(const probability::geometric_dist::GeometricLaw& law,
                      float meanExpect, float varExpect, float stdExpect,
                      float pmfAt5, float cdfAt6, float rangeAt3,
                      float rangeAt5to11, float tolerance) {
    assert(std::abs(law.mean() - meanExpect) < tolerance);
    assert(std::abs(law.variance() - varExpect) < tolerance);
    assert(std::abs(law.stdDeviation() - stdExpect) < tolerance);
    assert(std::abs(law.pmf(5) - pmfAt5) < tolerance);
    assert(std::abs(law.cdf(6) - cdfAt6) < tolerance);
    assert(std::abs(law.inverseCdf(law.cdf(8)) - 8) < tolerance);
    assert(std::abs(law.rangeProbability() - 1.0f) < tolerance);
    assert(std::abs(law.rangeProbability(3) - rangeAt3) < tolerance);
    assert(std::abs(law.rangeProbability(5, 11) - rangeAt5to11) < tolerance);
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    const float tolerance = 1e-3f;

    probability::geometric_dist::GeometricLaw law(0.3f);
    std::cout << "Running checks for successChance = 0.3..." << std::endl;
    checkLaw(law, 3.33333333f, 7.77777777f, 2.788866755f, 0.07203f, 0.882351f,
              0.49f, 0.2203267f, tolerance);
    std::cout << "All checks passed" << std::endl;
    verifySampling(law);

    law = probability::geometric_dist::GeometricLaw(0.5f);
    std::cout << "Running checks for successChance = 0.5..." << std::endl;
    checkLaw(law, 2.0f, 2.0f, 1.4142135f, 0.03125f, 0.984375f, 0.25f,
              0.062011f, tolerance);
    std::cout << "All checks passed" << std::endl;
    verifySampling(law);

    law = probability::geometric_dist::GeometricLaw(0.8f);
    std::cout << "Running checks for successChance = 0.8..." << std::endl;
    checkLaw(law, 1.25f, 0.3125f, 0.559016f, 0.00128f, 0.999936f, 0.04f,
              0.00159997f, tolerance);
    std::cout << "All checks have successfully passed!" << std::endl;
    verifySampling(law);
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    srand(time(nullptr));
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief [Poisson
 * statistics](https://en.wikipedia.org/wiki/Poisson_distribution)
 *
 * The Poisson distribution counts how many
 * events occur over a set time interval.
 */
#include <cmath>
#include <iostream>

/**
 * poisson rate:\n
 * calculate the events per unit time\n
 * e.g 5 dollars every 2 mins = 5 / 2 = 2.5
 */
double poisson_rate(double events, double timeframe) {
    return events / timeframe;
}

/**
 *  calculate the expected value over a time
 * e.g rate of 2.5 over 10 mins = 2.5 x 10 = 25
 */
double poisson_expected(double rate, double time) { return rate * time; }

/**
 * Compute factorial of a given number
 */
double fact(double x) {
    double x_fact = x;
    for (int i = x - 1; i > 0; i--) {
        x_fact *= i;
    }

    if (x_fact <= 0) {
        x_fact = 1;
    }
    return x_fact;
}

/**
 * Find the probability of x successes in a Poisson dist.
 * \f[p(\mu,x) = \frac{\mu^x e^{-\mu}}{x!}\f]
 */
double poisson_x_successes(double expected, double x) {
    return (std::pow(expected, x) * std::exp(-expected)) / fact(x);
}

/**
 * probability of a success in range for Poisson dist (inclusive, inclusive)
 * \f[P = \sum_i p(\mu,i)\f]
 */
double poisson_range_successes(double expected, double lower, double upper) {
    double probability = 0;
    for (int i = lower; i <= upper; i++) {
        probability += poisson_x_successes(expected, i);
    }
    return probability;
}

/**
 * main function
 */
int main() {
    double rate, expected;
    rate = poisson_rate(3, 1);
    std::cout << "Poisson rate : " << rate << std::endl;

    expected = poisson_expected(rate, 2);
    std::cout << "Poisson expected : " << expected << std::endl;

    std::cout << "Poisson 0 successes : " << poisson_x_successes(expected, 0)
              << std::endl;
    std::cout << "Poisson 0-8 successes : "
              << poisson_range_successes(expected, 0, 8) << std::endl;

    return 0;
}

/**
 * @file
 * @brief Working with the [Poisson
 * distribution](https://en.wikipedia.org/wiki/Poisson_distribution)
 *
 * This distribution models the count of independent events
 * happening within a fixed span of time or space, given a
 * known average rate.
 */
#include <cmath>
#include <iostream>

/**
 * Derive the average occurrence rate per unit of time.
 * example: 6 hits over 3 seconds -> 6 / 3 = 2.0 hits/sec
 */
double occurrence_rate(double total_events, double duration) {
    return total_events / duration;
}

/**
 * Scale a rate up across a given span to get the expected count (mu).
 * example: a rate of 2.0 across 5 seconds -> 2.0 * 5 = 10.0
 */
double expected_count(double rate_per_unit, double span) {
    return rate_per_unit * span;
}

/**
 * Iteratively compute n! without recursion.
 * Falls back to 1 for degenerate (non-positive) inputs.
 */
double factorial_of(double n) {
    long long rounded = static_cast<long long>(n);
    double product = 1.0;
    for (long long k = 2; k <= rounded; ++k) {
        product *= static_cast<double>(k);
    }
    return (product <= 0) ? 1.0 : product;
}

/**
 * Probability mass function for the Poisson distribution: chance of
 * observing exactly `k` events given expected value `mu`.
 * \f[p(\mu,k) = \frac{\mu^k e^{-\mu}}{k!}\f]
 */
double poisson_pmf(double mu, double k) {
    double numerator = std::pow(mu, k) * std::exp(-mu);
    return numerator / factorial_of(k);
}

/**
 * Cumulative probability of seeing between `from` and `to` events
 * (both bounds included) under the Poisson distribution.
 * \f[P = \sum_i p(\mu,i)\f]
 */
double poisson_cumulative(double mu, double from, double to) {
    double total_probability = 0.0;
    for (int k = static_cast<int>(from); k <= static_cast<int>(to); ++k) {
        total_probability += poisson_pmf(mu, k);
    }
    return total_probability;
}

/**
 * demo / entry point
 */
int main() {
    double lambda = occurrence_rate(9, 3);
    std::cout << "Computed rate : " << lambda << std::endl;

    double mu = expected_count(lambda, 4);
    std::cout << "Expected count over interval : " << mu << std::endl;

    std::cout << "P(exactly 0 events) : " << poisson_pmf(mu, 0) << std::endl;

    std::cout << "P(0 to 10 events) : " << poisson_cumulative(mu, 0, 10)
              << std::endl;

    return 0;
}

/**
 * @file
 * @brief An implementation of a median calculation of a sliding window along a
 * data stream
 *
 * @details
 * Given a stream of integers, the algorithm calculates the median of a fixed
 * size window at the back of the stream. The leading time complexity of this
 * algorithm is O(log(N), and it is inspired by the known algorithm to [find
 * median from (infinite) data
 * stream](https://www.tutorialcup.com/interview/algorithm/find-median-from-data-stream.htm),
 * with the proper modifications to account for the finite window size for which
 * the median is requested
 *
 * ### Algorithm
 * The sliding window is managed by a list, which guarantees O(1) for both
 * pushing and popping. Each new value is pushed to the window back, while a
 * value from the front of the window is popped. In addition, the algorithm
 * manages a multi-value binary search tree (BST), implemented by std::multiset.
 * For each new value that is inserted into the window, it is also inserted to
 * the BST. When a value is popped from the window, it is also erased from the
 * BST. Both insertion and erasion to/from the BST are O(logN) in time, with N
 * the size of the window. Finally, the algorithm keeps a pointer to the root of
 * the BST, and updates its position whenever values are inserted or erased
 * to/from BST. The root of the tree is the median! Hence, median retrieval is
 * always O(1)
 *
 * Time complexity: O(logN). Space complexity: O(N). N - size of window
 * @author [Yaniv Hollander](https://github.com/YanivHollander)
 */
#include <cassert>  /// for assert
#include <cstdlib>  /// for std::rand - needed in testing
#include <ctime>    /// for std::time - needed in testing
#include <list>     /// for std::list - used to manage sliding window
#include <set>  /// for std::multiset - used to manage multi-value sorted sliding window values
#include <vector>  /// for std::vector - needed in testing

/**
 * @namespace probability
 * @brief Probability algorithms
 */
namespace probability {
/**
 * @namespace windowed_median
 * @brief Functions for the Windowed Median algorithm implementation
 */
namespace windowed_median {
using Window = std::list<int>;
using size_type = Window::size_type;

/**
 * @class WindowedMedian
 * @brief A class to calculate the median of a leading sliding window at the
 * back of a stream of integer values.
 */
class WindowedMedian {
    const size_type _windowSize;  ///< sliding window size
    Window _window;  ///< a sliding window of values along the stream
    std::multiset<int> _sortedValues;  ///< a DS to represent a balanced
                                       /// multi-value binary search tree (BST)
    std::multiset<int>::const_iterator
        _itMedian;  ///< an iterator that points to the root of the multi-value
                    /// BST

    /**
     * @brief Inserts a value to a sorted multi-value BST
     * @param value Value to insert
     */
    void insertToSorted(int value) {
        _sortedValues.insert(value);  /// Insert value to BST - O(logN)
        const auto sz = _sortedValues.size();
        if (sz == 1) {  /// For the first value, set median iterator to BST root
            _itMedian = _sortedValues.begin();
            return;
        }

        /// If new value goes to left tree branch, and number of elements is
        /// even, the new median in the balanced tree is the left child of the
        /// median before the insertion
        if (value < *_itMedian && sz % 2 == 0) {
            --_itMedian;  // O(1) - traversing one step to the left child
        }

        /// However, if the new value goes to the right branch, the previous
        /// median's right child is the new median in the balanced tree
        else if (value >= *_itMedian && sz % 2 != 0) {
            ++_itMedian;  /// O(1) - traversing one step to the right child
        }
    }

    /**
     * @brief Erases a value from a sorted multi-value BST
     * @param value Value to insert
     */
    void eraseFromSorted(int value) {
        const auto sz = _sortedValues.size();

        /// If the erased value is on the left branch or the median itself and
        /// the number of elements is even, the new median will be the right
        /// child of the current one
        if (value <= *_itMedian && sz % 2 == 0) {
            ++_itMedian;  /// O(1) - traversing one step to the right child
        }

        /// However, if the erased value is on the right branch or the median
        /// itself, and the number of elements is odd, the new median will be
        /// the left child of the current one
        else if (value >= *_itMedian && sz % 2 != 0) {
            --_itMedian;  // O(1) - traversing one step to the left child
        }

        /// Find the (first) position of the value we want to erase, and erase
        /// it
        const auto it = _sortedValues.find(value);  // O(logN)
        _sortedValues.erase(it);                    // O(logN)
    }

 public:
    /**
     * @brief Constructs a WindowedMedian object
     * @param windowSize Sliding window size
     */
    explicit WindowedMedian(size_type windowSize) : _windowSize(windowSize){};

    /**
     * @brief Insert a new value to the stream
     * @param value New value to insert
     */
    void insert(int value) {
        /// Push new value to the back of the sliding window - O(1)
        _window.push_back(value);
        insertToSorted(value);  // Insert value to the multi-value BST - O(logN)
        if (_window.size() > _windowSize) {  /// If exceeding size of window,
                                             /// pop from its left side
            eraseFromSorted(
                _window.front());  /// Erase from the multi-value BST
                                   /// the window left side value
            _window.pop_front();   /// Pop the left side value from the window -
                                   /// O(1)
        }
    }

    /**
     * @brief Gets the median of the values in the sliding window
     * @return Median of sliding window. For even window size return the average
     * between the two values in the middle
     */
    float getMedian() const {
        if (_sortedValues.size() % 2 != 0) {
            return *_itMedian;  // O(1)
        }
        return 0.5f * *_itMedian + 0.5f * *next(_itMedian);  /// O(1)
    }

    /**
     * @brief A naive and inefficient method to obtain the median of the sliding
     * window. Used for testing!
     * @return Median of sliding window. For even window size return the average
     * between the two values in the middle
     */
    float getMedianNaive() const {
        auto window = _window;
        window.sort();  /// Sort window - O(NlogN)
        auto median =
            *next(window.begin(),
                  window.size() / 2);  /// Find value in the middle - O(N)
        if (window.size() % 2 != 0) {
            return median;
        }
        return 0.5f * median +
               0.5f * *next(window.begin(), window.size() / 2 - 1);  /// O(N)
    }
};
}  // namespace windowed_median
}  // namespace probability

/**
 * @brief Self-test implementations
 * @param vals Stream of values
 * @param windowSize Size of sliding window
 */
static void test(const std::vector<int> &vals, int windowSize) {
    probability::windowed_median::WindowedMedian windowedMedian(windowSize);
    for (const auto val : vals) {
        windowedMedian.insert(val);

        /// Comparing medians: efficient function vs. Naive one
        assert(windowedMedian.getMedian() == windowedMedian.getMedianNaive());
    }
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    /// A few fixed test cases
    test({1, 2, 3, 4, 5, 6, 7, 8, 9},
         3);  /// Array of sorted values; odd window size
    test({9, 8, 7, 6, 5, 4, 3, 2, 1},
         3);  /// Array of sorted values - decreasing; odd window size
    test({9, 8, 7, 6, 5, 4, 5, 6}, 4);     /// Even window size
    test({3, 3, 3, 3, 3, 3, 3, 3, 3}, 3);  /// Array with repeating values
    test({3, 3, 3, 3, 7, 3, 3, 3, 3}, 3);  /// Array with same values except one
    test({4, 3, 3, -5, -5, 1, 3, 4, 5},
         5);  /// Array that includes repeating values including negatives

    /// Array with large values - sum of few pairs exceeds MAX_INT. Window size
    /// is even - testing calculation of average median between two middle
    /// values
    test({470211272, 101027544, 1457850878, 1458777923, 2007237709, 823564440,
          1115438165, 1784484492, 74243042, 114807987},
         6);

    /// Random test cases
    std::srand(static_cast<unsigned int>(std::time(nullptr)));
    std::vector<int> vals;
    for (int i = 8; i < 100; i++) {
        const auto n =
            1 + std::rand() /
                    ((RAND_MAX + 5u) / 20);  /// Array size in the range [5, 20]
        auto windowSize =
            1 + std::rand() / ((RAND_MAX + 3u) /
                               10);  /// Window size in the range [3, 10]
        vals.clear();
        vals.reserve(n);
        for (int i = 0; i < n; i++) {
            vals.push_back(
                rand() - RAND_MAX);  /// Random array values (positive/negative)
        }
        test(vals, windowSize);  /// Testing randomized test
    }
    return 0;
}

/**
 * @file
 * @brief Streaming median over a fixed-size trailing window
 *
 * @details
 * Given a stream of integers, this maintains the median of the most
 * recent `k` values seen so far (the trailing window). It runs in
 * O(log k) per inserted element, building on the classic "median of
 * an infinite data stream" trick, adapted to forget old values once
 * the window fills up.
 *
 * ### Approach
 * A doubly linked list acts as the window itself, giving O(1)
 * push-back and pop-front. Alongside it, a std::multiset acts as a
 * balanced multi-value search tree holding the same elements in
 * sorted order; every insertion into the window is mirrored into the
 * multiset (O(log k)), and every eviction from the window front is
 * mirrored as an erase from the multiset (also O(log k)). A cached
 * iterator tracks the tree's "center" element(s) and is nudged left
 * or right by one step whenever the tree changes, so that reading
 * the median stays O(1) instead of re-walking the tree each time.
 *
 * Time complexity: O(log k) per update. Space: O(k), k = window size.
 * @author rewritten for classroom dataset purposes
 */
#include <cassert>  /// assert() for self-checks
#include <cstdlib>  /// std::rand for generating test streams
#include <ctime>    /// std::time to seed the RNG
#include <list>     /// backing store for the trailing window
#include <set>      /// std::multiset acting as our sorted tree
#include <vector>   /// scratch storage for randomized test input

/**
 * @namespace probability
 * @brief Probability-related algorithms
 */
namespace probability {
/**
 * @namespace windowed_median
 * @brief Trailing-window median tracker
 */
namespace windowed_median {

using Stream = std::list<int>;
using count_t = Stream::size_type;

/**
 * @class RollingMedian
 * @brief Tracks the median across only the last `capacity` elements
 * pushed into an otherwise unbounded stream.
 */
class RollingMedian {
 public:
    /**
     * @brief Build a tracker bound to a fixed trailing window length.
     * @param capacity number of most-recent elements to consider
     */
    explicit RollingMedian(count_t capacity) : capacity_(capacity) {}

    /**
     * @brief Feed one more value from the stream into the tracker.
     * @param value newest observed value
     */
    void push(int value) {
        window_.push_back(value);           /// O(1) append to window
        addToTree(value);                   /// mirror into sorted tree, O(log k)
        if (window_.size() > capacity_) {   /// window overflowed - drop oldest
            removeFromTree(window_.front());
            window_.pop_front();
        }
    }

    /**
     * @brief Current median across the trailing window.
     * @return the middle value, or the average of the two central
     * values when the window holds an even count of elements
     */
    float median() const {
        if (sorted_.size() % 2 != 0) {
            return *centerIt_;
        }
        auto rightNeighbor = centerIt_;
        ++rightNeighbor;
        return 0.5f * (*centerIt_) + 0.5f * (*rightNeighbor);
    }

    /**
     * @brief Brute-force reference median, used only to cross-check
     * the fast implementation during testing.
     */
    float medianBruteForce() const {
        Stream copy = window_;
        copy.sort();  /// O(k log k) - deliberately unoptimized
        auto mid = copy.begin();
        std::advance(mid, copy.size() / 2);
        if (copy.size() % 2 != 0) {
            return *mid;
        }
        auto prevIt = mid;
        --prevIt;
        return 0.5f * (*mid) + 0.5f * (*prevIt);
    }

 private:
    /**
     * @brief Insert a value into the sorted multiset and reposition
     * the cached "center" iterator so it still points at the median.
     */
    void addToTree(int value) {
        sorted_.insert(value);
        const auto n = sorted_.size();
        if (n == 1) {
            centerIt_ = sorted_.begin();
            return;
        }
        if (value < *centerIt_ && n % 2 == 0) {
            --centerIt_;
        } else if (value >= *centerIt_ && n % 2 != 0) {
            ++centerIt_;
        }
    }

    /**
     * @brief Remove a value from the sorted multiset, first adjusting
     * the cached "center" iterator so the median stays correct.
     */
    void removeFromTree(int value) {
        const auto n = sorted_.size();
        if (value <= *centerIt_ && n % 2 == 0) {
            ++centerIt_;
        } else if (value >= *centerIt_ && n % 2 != 0) {
            --centerIt_;
        }
        auto hit = sorted_.find(value);
        sorted_.erase(hit);
    }

    const count_t capacity_;                          ///< max window length
    Stream window_;                                   ///< raw trailing values
    std::multiset<int> sorted_;                       ///< same values, sorted
    std::multiset<int>::const_iterator centerIt_;      ///< points at median
};

}  // namespace windowed_median
}  // namespace probability

/**
 * @brief Drives one scenario through both the fast and brute-force
 * median computations and asserts they agree at every step.
 */
static void checkScenario(const std::vector<int> &stream, int windowLen) {
    probability::windowed_median::RollingMedian tracker(windowLen);
    for (int v : stream) {
        tracker.push(v);
        assert(tracker.median() == tracker.medianBruteForce());
    }
}

/**
 * @brief Entry point running fixed scenarios plus randomized fuzzing.
 */
int main() {
    /// Hand-picked scenarios covering edge cases
    checkScenario({1, 2, 3, 4, 5, 6, 7, 8, 9}, 3);       /// ascending, odd window
    checkScenario({9, 8, 7, 6, 5, 4, 3, 2, 1}, 3);       /// descending, odd window
    checkScenario({9, 8, 7, 6, 5, 4, 5, 6}, 4);          /// even window
    checkScenario({3, 3, 3, 3, 3, 3, 3, 3, 3}, 3);       /// all duplicates
    checkScenario({3, 3, 3, 3, 7, 3, 3, 3, 3}, 3);       /// single outlier
    checkScenario({4, 3, 3, -5, -5, 1, 3, 4, 5}, 5);     /// duplicates + negatives

    /// Large magnitudes where naive pairwise sums could overflow int;
    /// also exercises the even-window "average of two centers" branch
    checkScenario({470211272, 101027544, 1457850878, 1458777923, 2007237709,
                   823564440, 1115438165, 1784484492, 74243042, 114807987},
                  6);

    /// Fuzz with randomized streams and window sizes
    std::srand(static_cast<unsigned int>(std::time(nullptr)));
    std::vector<int> stream;
    for (int trial = 8; trial < 100; ++trial) {
        const int streamLen =
            1 + std::rand() / ((RAND_MAX + 5u) / 20);  /// length in [5, 20]
        const int windowLen =
            1 + std::rand() / ((RAND_MAX + 3u) / 10);  /// window in [3, 10]
        stream.clear();
        stream.reserve(streamLen);
        for (int i = 0; i < streamLen; ++i) {
            stream.push_back(std::rand() - RAND_MAX);  /// mix of signs
        }
        checkScenario(stream, windowLen);
    }
    return 0;
}

/**
 * @file
 * @brief [Fenwick Tree](https://en.wikipedia.org/wiki/Fenwick_tree) algorithm
 * implementation
 * @details
 * _From Wikipedia, the free encyclopedia._
 *
 * A Fenwick tree or binary indexed tree (BIT) is a clever implementation of a
 * datastructure called bionomal tree. It can update values and solve range
 * queries with operations that is; commulative, associative and has an
 * inverse for this type of element. It can also solve immutable range queries
 * (min/max), when operations only are associative over this type of element.
 * Some of these restrictions can be removed, by storing redunant information;
 * like in max/min range queries.
 *
 * @author [Mateusz Grzegorzek](https://github.com/mateusz-grzegorzek)
 * @author [David Leal](https://github.com/Panquesito7)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace
 * @brief Range Queries
 */
namespace range_queries {
/**
 * @brief The class that initializes the Fenwick Tree.
 */
class fenwick_tree {
    size_t n = 0;            ///< No. of elements present in input array
    std::vector<int> bit{};  ///< Array that represents Binary Indexed Tree.

    /**
     * @brief Returns the highest power of two which is not more than `x`.
     * @param x Index of element in original array.
     * @return Offset of index.
     */
    inline int offset(int x) { return (x & (-x)); }
 public:
    /**
     * @brief Class Constructor
     * @tparam T the type of the array
     * @param[in] arr Input array for which prefix sum is evaluated.
     * @return void
     */
    template <typename T>
    explicit fenwick_tree(const std::vector<T>& arr) : n(arr.size()) {
        bit.assign(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            update(i, arr[i]);
        }
    }

    /**
     * @brief Class Constructor
     * @tparam T the type of the variable
     * @param[in] x Size of array that represents Binary Indexed Tree.
     * @return void
     */
    template <typename T>
    explicit fenwick_tree(T x) : n(x) { bit.assign(n + 1, 0); }

    /**
     * @brief Updates the value of an element in original array and
     * accordingly updates the values in BIT array.
     * @tparam T the type of the variables
     * @param id Index of element in original array.
     * @param val Value with which element's value is updated.
     * @return void
     */
    template <typename T>
    void update(T id, T val) {
        id++;
        while (id <= n) {
            bit[id] += val;
            id += offset(id);
        }
    }

    /**
     * @brief Returns the sum of elements in range from 0 to ID.
     * @tparam T the type of the variables
     * @param id Index in original array up to which sum is evaluated.
     * @return Sum of elements in range from 0 to id.
     */
    template <typename T>
    int sum(T id) {
        id++;
        T res = 0;
        while (id > 0) {
            res += bit[id];
            id -= offset(id);
        }
        return res;
    }

    /**
     * @brief Returns the prefix sum in range from L to R.
     * @param l Left index of range.
     * @param r Right index of range.
     * @return Sum of elements in range from L to R.
     */
    int sum_range(int l, int r) { return sum(r) - sum(l - 1); }
};
}  // namespace range_queries

/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    std::vector<int> arr = {1, 2, 3, 4, 5};
    range_queries::fenwick_tree fenwick_tree(arr);

    assert(fenwick_tree.sum_range(0, 0) == 1);
    assert(fenwick_tree.sum_range(0, 1) == 3);
    assert(fenwick_tree.sum_range(0, 2) == 6);
    assert(fenwick_tree.sum_range(0, 3) == 10);
    assert(fenwick_tree.sum_range(0, 4) == 15);

    fenwick_tree.update(0, 6);
    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Binary Indexed Tree (a.k.a. Fenwick Tree) for prefix-sum queries
 * @details
 * A binary indexed tree stores partial sums arranged so that both point
 * updates and prefix-sum queries run in O(log n). Internally it exploits the
 * lowest set bit of an index to decide which partial-sum "bucket" an index
 * is responsible for. This trick works for any operation that is
 * associative, commutative, and invertible (like addition); for operations
 * without an inverse (min/max) extra bookkeeping would be required.
 *
 * Rewritten variant for educational dataset generation.
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout
#include <vector>    /// for std::vector

/**
 * @namespace
 * @brief Range Queries
 */
namespace range_queries {

/**
 * @brief A Binary Indexed Tree supporting point updates and prefix sums.
 */
class BinaryIndexedTree {
 public:
    /**
     * @brief Build the tree from an existing array of values.
     * @tparam ValueT element type of the source array
     * @param source values to load into the tree
     */
    template <typename ValueT>
    explicit BinaryIndexedTree(const std::vector<ValueT>& source)
        : elementCount(source.size()) {
        tree.assign(elementCount + 1, 0);
        for (std::size_t idx = 0; idx < elementCount; ++idx) {
            add(static_cast<int>(idx), source[idx]);
        }
    }

    /**
     * @brief Build an empty tree capable of holding `capacity` elements.
     * @tparam SizeT integral type describing the capacity
     * @param capacity number of slots to allocate
     */
    template <typename SizeT>
    explicit BinaryIndexedTree(SizeT capacity) : elementCount(capacity) {
        tree.assign(elementCount + 1, 0);
    }

    /**
     * @brief Add `delta` to the element stored at position `position`.
     * @tparam T numeric type used for the position/delta pair
     * @param position zero-based index within the logical array
     * @param delta amount to add to that position
     */
    template <typename T>
    void add(T position, T delta) {
        int cursor = static_cast<int>(position) + 1;
        while (cursor <= static_cast<int>(elementCount)) {
            tree[cursor] += delta;
            cursor += lowestSetBit(cursor);
        }
    }

    /**
     * @brief Compute the prefix sum of elements in [0, position].
     * @tparam T numeric type describing the position
     * @param position last index (inclusive) to sum up to
     * @return running total of elements 0..position
     */
    template <typename T>
    int prefixSum(T position) {
        int cursor = static_cast<int>(position) + 1;
        int total = 0;
        while (cursor > 0) {
            total += tree[cursor];
            cursor -= lowestSetBit(cursor);
        }
        return total;
    }

    /**
     * @brief Compute the sum of elements between two indices, inclusive.
     * @param from left bound of the range
     * @param to right bound of the range
     * @return sum of elements in [from, to]
     */
    int rangeSum(int from, int to) { return prefixSum(to) - prefixSum(from - 1); }

 private:
    std::size_t elementCount = 0;  ///< logical number of elements tracked
    std::vector<int> tree{};       ///< internal BIT storage (1-indexed)

    /// Isolates the lowest set bit of x, i.e. x & (-x).
    static inline int lowestSetBit(int x) { return x & (-x); }
};

}  // namespace range_queries

/**
 * @brief Runs a handful of sanity checks against BinaryIndexedTree.
 */
static void runSanityChecks() {
    std::vector<int> sample = {1, 2, 3, 4, 5};
    range_queries::BinaryIndexedTree bit(sample);

    assert(bit.rangeSum(0, 0) == 1);
    assert(bit.rangeSum(0, 1) == 3);
    assert(bit.rangeSum(0, 2) == 6);
    assert(bit.rangeSum(0, 3) == 10);
    assert(bit.rangeSum(0, 4) == 15);

    bit.add(0, 6);
    std::cout << "Sanity checks completed without any failed assertion.\n";
}

/**
 * @brief Program entry point.
 * @return 0 on successful completion
 */
int main() {
    runSanityChecks();
    return 0;
}

/**
 * @file
 * @brief [Heavy Light
 * Decomposition](https://en.wikipedia.org/wiki/Heavy_path_decomposition)
 * implementation
 * @author [Aniruthan R](https://github.com/aneee004)
 *
 * @details
 * Heavy-Light Decomposition is a technique on trees, that supports the
 * following:
 * 1. Update node s, with a value v
 * 2. Return the (sum) of all node values on the simple path from a to b
 * (sum) can also be replced with XOR, OR, AND, min, or max
 *
 * The update is done in O(log n) time, and
 * the query is done in O(log^2 n) time with HLD
 * where, n is the number of nodes
 *
 * The template type is the data type of the value stored in the nodes.
 * If a non-primitive data-type is used as a template,
 * the coressponding operators must be overloaded.
 *
 * An HLD object can only be created with a constant number of nodes, and
 * it cannot be changed later. Creaty an empty instance is not supported.
 *
 * To start answering updates and queries,
 * 1. Create an instance of HLD<X> object (obj), with the required data type.
 * 2. Read in the edge/parent information and update it with obj.add_edge().
 * Note: The edges addes must be 0 indexed.
 * 3. Create a vector with initial node values, and call set_node_val() with it.
 * 4. Call obj.init() to populate the required information for supporting
 * operations.
 * 5. Call obj.update(node, new_val), to update the value at index 'node' to the
 * new value. Note: node must be 0 indexed
 * 6. Call obj.query(a, b) to get the (sum) of node values in the simple path
 * from a to b. Note: a and b, must be 0 indexed.
 *
 * Sample I/O at the bottom.
 * @todo Support edge weight queries, by storing the edge weight value in it's
 * child algorithm verified by testing in CSES path queries:
 * https://cses.fi/problemset/task/1138
 */

#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstring>
#include <iostream>
#include <list>
#include <numeric>
#include <string>
#include <vector>

/**
 * @namespace range_queries
 * @brief Algorithms and Data Structures that support range queries and updates.
 */
namespace range_queries {
/**
 * @namespace heavy_light_decomposition
 * @brief Heavy light decomposition algorithm
 */
namespace heavy_light_decomposition {
/**
 * @brief A Basic Tree, which supports binary lifting
 * @tparam the data type of the values stored in the tree nodes
 * @details Deleting the default constructor
 * An instance can only be created with the number of nodes
 * Defaults:
 * t_node indexing are zero based
 * t_root is 0
 * depth of root_node is 0
 * Supports:
 * lift :- lift a node k units up the tree
 * kth_ancestor :- returns the kth ancestor
 * lca :- returns the least common ancestor
 */
template <typename X>
class Tree {
    //

 private:
    std::vector<std::list<int>>
        t_adj;          ///< an adjacency list to stores the tree edges
    const int t_nodes,  ///< number of nodes
        t_maxlift;      ///< maximum possible height of the tree
    std::vector<std::vector<int>>
        t_par;                 ///< a matrix to store every node's 2^kth parent
    std::vector<int> t_depth,  ///< a vector to store the depth of a node,
        t_size;  ///< a vector to store the subtree size rooted at node

    int t_root;            ///< the root of the tree
    std::vector<X> t_val;  ///< values of nodes
    template <typename T>
    friend class HLD;

    /**
     * @brief Utility function to compute sub-tree sizes
     * @param u current dfs node
     * @param p the parent of node @param u
     * @returns void
     */
    void dfs_size(int u, int p = -1) {
        for (const int &v : t_adj[u]) {
            if (v ^ p) {
                dfs_size(v, u);
                t_size[u] += t_size[v];
            }
        }
    }

    /**
     * @brief Utility function to populate the t_par vector
     * @param u current dfs node
     * @param p the parent of node u
     * @returns void
     */
    void dfs_lca(int u, int p = -1) {
        t_par[u][0] = p;
        if (p != -1) {
            t_depth[u] = 1 + t_depth[p];
        }
        for (int k = 1; k < t_maxlift; k++) {
            if (t_par[u][k - 1] != -1) {
                t_par[u][k] = t_par[t_par[u][k - 1]][k - 1];
            }
        }

        for (const int &v : t_adj[u]) {
            if (v ^ p) {
                dfs_lca(v, u);
            }
        }
    }

 public:
    /**
     * @brief Class parameterized constructor, resizes the and initializes the
     * data members
     * @param nodes the total number of nodes in the tree
     */
    explicit Tree(int nodes)
        : t_nodes(nodes), t_maxlift(static_cast<int>(floor(log2(nodes))) + 1) {
        /* Initialize and resize all the vectors */
        t_root = 0; /* Default */
        t_adj.resize(t_nodes);
        t_par.assign(t_nodes, std::vector<int>(t_maxlift, -1));
        t_depth.assign(t_nodes, 0);
        t_size.assign(t_nodes, 1);
        t_val.resize(t_nodes);
    }

    /**
     * @brief Adds an undirected edge from node u to node v in the tree
     * @param u the node where the edge is from
     * @param v the node where the edge is to
     * @returns void
     */
    void add_edge(const int u, const int v) {
        t_adj[u].push_back(v);
        t_adj[v].push_back(u);
    }

    /**
     * @brief Set the root for the tree
     * @param new_root the new root
     * @returns void
     */
    void change_root(int new_root) { t_root = new_root; }

    /**
     * @brief Set the values for all the nodes
     * @param node_val a vector of size n, with all the node values where, n is
     * the number of nodes
     * @returns void
     */
    void set_node_val(const std::vector<X> &node_val) {
        assert(static_cast<int>(node_val.size()) == t_nodes);
        t_val = node_val;
    }

    /**
     * @brief This function must be called after the tree adjacency list and
     * node values are populated The function initializes the required
     * parameters, and populates the segment tree
     * @returns void
     */
    void init() {
        assert(t_nodes > 0);
        dfs_size(t_root);
        dfs_lca(t_root);
    }

    /**
     * @brief The function lifts a node, k units up the tree.
     * The lifting is done in place, and the result is stored in the address
     * pointed by p.
     * @param p a pointer to the variable that stores the node id
     * @param dist the distance to move up the tree
     * @returns void
     */
    void lift(int *const p, int dist) {
        for (int k = 0; k < t_maxlift; k++) {
            if (*p == -1) {
                return;
            }
            if (dist & 1) {
                *p = t_par[*p][k];
            }
            dist >>= 1;
        }
    }

    /**
     * @brief The function returns the kth ancestor of a node
     * @param p the node id whose kth ancestor is to be found
     * @param dist the distance to move up the tree
     * @returns the kth ancestor of node
     */
    int kth_ancestor(int p, const int &dist) {
        lift(&p, dist);
        return p;
    }

    /**
     * @brief The function returns the least common ancestor of two nodes
     * @param a node id_1
     * @param b node id_2
     * @returns the least common ancestor of node a, and node b
     */
    int lca(int a, int b) {
        assert(a >= 0 and b >= 0 and a < t_nodes and b < t_nodes);
        if (t_depth[a] > t_depth[b]) {
            lift(&a, t_depth[a] - t_depth[b]);
        }
        if (t_depth[b] > t_depth[a]) {
            lift(&b, t_depth[b] - t_depth[a]);
        }
        if (a == b) {
            return a;
        }
        for (int k = t_maxlift - 1; k >= 0; k--) {
            if (t_par[a][k] != t_par[b][k]) {
                a = t_par[a][k];
                b = t_par[b][k];
            }
        }
        return t_par[a][0];
    }
};

/**
 * @brief Segment Tree, to store heavy chains
 * @tparam the data type of the values stored in the tree nodes
 */
template <typename X>
class SG {
 private:
    /**
     * @brief Everything here is private,
     * and can only be accessed through the methods,
     * in the derived class (HLD)
     */

    std::vector<X> s_tree;  ///< the segment tree, stored as a vector
    int s_size;             ///< number of leaves in the segment tree
    X sret_init = 0;        ///< inital query return value
    template <typename T>
    friend class HLD;

    /**
     * @brief Function that specifies the type of operation involved when
     * segments are combined
     * @param lhs the left segment
     * @param rhs the right segment
     * @returns the combined result
     */
    X combine(X lhs, X rhs) { return lhs + rhs; }

    /**
     * @brief Class parameterized constructor. Resizes the and initilizes the
     * data members.
     * @param nodes the total number of nodes in the tree
     * @returns void
     */
    explicit SG(int size) {
        s_size = size;
        s_tree.assign(2 * s_size, 0ll);
    }

    /**
     * @brief Update the value at a node
     * @param p the node to be udpated
     * @param v the update value
     * @returns void
     */
    void update(int p, X v) {
        for (p += s_size; p > 0; p >>= 1) {
            s_tree[p] += v;
        }
    }

    /**
     * @brief Make a range query from node label l to node label r
     * @param l node label where the path starts
     * @param r node label where the path ends
     * @returns void
     */
    X query(int l, int r) {
        X lhs = sret_init, rhs = sret_init;
        for (l += s_size, r += s_size + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                lhs = combine(lhs, s_tree[l++]);
            }
            if (r & 1) {
                rhs = combine(s_tree[--r], rhs);
            }
        }
        return combine(lhs, rhs);
    }

    /**
     * @brief Set the initialization for the query data type, based on
     * requirement
     *
     * @details
     * Change the sret_init, based on requirement:
     * * Sum Query: 0 (Default)
     * * XOR Query: 0 (Default)
     * * Min Query: Infinity
     * * Max Query: -Infinity
     * @param new_sret_init the new init
     */
    void set_sret_init(X new_sret_init) { sret_init = new_sret_init; }
};

/**
 * @brief The Heavy-Light Decomposition class
 * @tparam the data type of the values stored in the tree nodes
 */
template <typename X>
class HLD : public Tree<X>, public SG<X> {
 private:
    int label;  ///< utility member to assign labels in dfs_labels()
    std::vector<int> h_label,  ///< stores the label of a node
        h_heavychlid,          ///< stores the heavy child of a node
        h_parent;  ///< stores the top of the heavy chain from a node

    /**
     * @brief Utility function to assign heavy child to each node (-1 for a leaf
     * node)
     * @param u current dfs node
     * @param p the parent of node u
     * @returns void
     */
    void dfs_hc(int u, int p = -1) {
        int hc_size = -1, hc_id = -1;
        for (const int &v : Tree<X>::t_adj[u]) {
            if (v ^ p) {
                dfs_hc(v, u);
                if (Tree<X>::t_size[v] > hc_size) {
                    hc_size = Tree<X>::t_size[v];
                    hc_id = v;
                }
            }
        }
        h_heavychlid[u] = hc_id;
    }

    /**
     * @brief Utility function to assign highest parent that can be reached
     * though heavy chains
     * @param u current dfs node
     * @param p the parent of node u
     * @returns void
     */
    void dfs_par(int u, int p = -1) {
        if (h_heavychlid[u] != -1) {
            h_parent[h_heavychlid[u]] = h_parent[u];
            dfs_par(h_heavychlid[u], u);
        }
        for (const int &v : Tree<X>::t_adj[u]) {
            if (v ^ p and v ^ h_heavychlid[u]) {
                dfs_par(v, u);
            }
        }
    }

    /**
     * @brief Utility function to lable the nodes so that heavy chains have a
     * contigous lable
     * @param u current dfs node
     * @param p the parent of node u
     * @returns void
     */
    void dfs_labels(int u, int p = -1) {
        h_label[u] = label++;
        if (h_heavychlid[u] != -1) {
            dfs_labels(h_heavychlid[u], u);
        }
        for (const int &v : Tree<X>::t_adj[u]) {
            if (v ^ p and v ^ h_heavychlid[u]) {
                dfs_labels(v, u);
            }
        }
    }

    /**
     * @brief Utility function to break down a path query into two chain queries
     * @param a node where the path starts
     * @param b node where the path ends
     * a and b must belong to a single root to leaf chain
     * @returns the sum of ndoe values in the simple path from a to b
     */
    X chain_query(int a, int b) {
        X ret = SG<X>::sret_init;
        if (Tree<X>::t_depth[a] < Tree<X>::t_depth[b]) {
            std::swap(a, b);
        }
        while (Tree<X>::t_depth[a] >= Tree<X>::t_depth[b]) {
            int l = h_label[h_parent[a]];
            int r = h_label[a];
            if (Tree<X>::t_depth[h_parent[a]] < Tree<X>::t_depth[b]) {
                l += Tree<X>::t_depth[b] - Tree<X>::t_depth[h_parent[a]];
            }
            ret = SG<X>::combine(ret, SG<X>::query(l, r));
            a = Tree<X>::t_par[h_parent[a]][0];
            if (a == -1) {
                break;
            }
        }
        return ret;
    }

 public:
    /**
     * @brief Class parameterized constructor. Resizes the and initilizes the
     * data members.
     * @param nodes the total number of nodes in the tree
     */
    explicit HLD(int nodes) : Tree<X>(nodes), SG<X>(nodes) {
        /* Initialization and resize vectors */
        label = 0;
        h_label.assign(Tree<X>::t_nodes, -1);
        h_heavychlid.assign(Tree<X>::t_nodes, -1);
        h_parent.resize(Tree<X>::t_nodes);
        iota(h_parent.begin(), h_parent.end(), 0);
    }

    /**
     * @brief This function must be called after the tree adjacency list and
     * node values are populated The function initializes the required
     * parametes, and populates the segment tree
     * @returns void
     */
    void init() {
        Tree<X>::init();

        // Fill the heavy child, greatest parent, and labels
        label = 0;
        dfs_hc(Tree<X>::t_root);
        dfs_par(Tree<X>::t_root);
        dfs_labels(Tree<X>::t_root);

        // Segment Tree Initialization
        for (int i = 0; i < Tree<X>::t_nodes; i++) {
            SG<X>::s_tree[h_label[i] + Tree<X>::t_nodes] = Tree<X>::t_val[i];
        }
        for (int i = Tree<X>::t_nodes - 1; i > 0; i--) {
            SG<X>::s_tree[i] = SG<X>::combine(SG<X>::s_tree[i << 1],
                                              SG<X>::s_tree[i << 1 | 1]);
        }
    }

    /**
     * @brief This function updates the value at node with val
     * @param node the node where the update is done
     * @param val the value that is being updated
     * @returns void
     */
    void update(int node, X val) {
        X diff = val - Tree<X>::t_val[node];
        SG<X>::update(h_label[node], diff);
        Tree<X>::t_val[node] = val;
    }

    /**
     * @brief This function returns the sum of node values in the simple path
     * from from node_1 to node_2
     * @param a the node where the simple path starts
     * @param b the node where the simple path ends
     * (parameters are interchangeable, i.e., the function is commutative)
     * @returns the sum of node values in the simple path from a to b
     */
    X query(int a, int b) {
        int lc = Tree<X>::lca(a, b);
        X ret = SG<X>::sret_init;
        assert(lc != -1);
        ret += chain_query(a, lc);
        ret += chain_query(b, lc);
        return ret - Tree<X>::t_val[lc];
    }
};
}  // namespace heavy_light_decomposition
}  // namespace range_queries

/**
 * Test implementations
 * @returns none
 */
static void test_1() {
    std::cout << "Test 1:\n";

    // Test details
    int n = 5;
    std::vector<int64_t> node_values = {4, 2, 5, 2, 1};
    std::vector<std::vector<int>> edges = {{1, 2}, {1, 3}, {3, 4}, {3, 5}};
    std::vector<std::vector<int>> queries = {
        {2, 1, 4},
        {1, 3, 2},
        {2, 1, 4},
    };
    std::vector<int> expected_result = {11, 8};
    std::vector<int> code_result;

    range_queries::heavy_light_decomposition::HLD<int64_t> hld(n);
    hld.set_node_val(node_values);
    for (int i = 0; i < n - 1; i++) {
        int u = edges[i][0], v = edges[i][1];
        hld.add_edge(u - 1, v - 1);
    }
    hld.init();
    for (const auto &q : queries) {
        int type = q[0];
        if (type == 1) {
            int p = q[1], x = q[2];
            hld.update(p - 1, x);
        } else if (type == 2) {
            int a = q[1], b = q[2];
            code_result.push_back(hld.query(a - 1, b - 1));
        } else {
            continue;
        }
    }
    for (int i = 0; i < static_cast<int>(expected_result.size()); i++) {
        assert(expected_result[i] == code_result[i]);
    }
    std::cout << "\nTest 1 passed!\n";
}

