/**
 * @file
 * @brief Heavy-Light Decomposition over a tree, supporting path sum queries
 * @details
 * Heavy-Light Decomposition (HLD) breaks a tree into chains so that any
 * root-to-node path touches O(log n) chains. Combined with a segment tree
 * over the chain labels, this lets us:
 *   1. Update the value stored at a single node in O(log n).
 *   2. Combine (sum, in this rewrite) the values along the simple path
 *      between any two nodes in O(log^2 n).
 *
 * Usage pattern:
 *   1. Construct a PathDecomposition<T> with the node count.
 *   2. Register edges via linkNodes() (0-indexed).
 *   3. Load initial node values with loadValues().
 *   4. Call build() once everything above is set.
 *   5. Use setValue(node, v) / pathAggregate(a, b) afterwards.
 *
 * Rewritten variant for educational dataset generation; behavior mirrors the
 * original implementation exactly, only naming/structure differ.
 */

#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstring>
#include <iostream>
#include <list>
#include <numeric>
#include <string>
#include <vector>

/**
 * @namespace range_queries
 * @brief Algorithms and data structures answering range queries/updates.
 */
namespace range_queries {

/**
 * @namespace heavy_light_decomposition
 * @brief Heavy-light decomposition based path queries.
 */
namespace heavy_light_decomposition {

/**
 * @brief A tree structure augmented with binary lifting for ancestor/LCA
 * queries.
 * @tparam ValueT type of value stored at each node
 */
template <typename ValueT>
class LiftableTree {
 protected:
    std::vector<std::list<int>> adjacency;  ///< adjacency list of the tree
    const int nodeCount;                    ///< total number of nodes
    const int liftLevels;                   ///< ceil(log2(nodeCount)) + 1
    std::vector<std::vector<int>> ancestorTable;  ///< binary-lifting table
    std::vector<int> depthOf;   ///< depth of each node from the root
    std::vector<int> subtreeSz; ///< subtree size rooted at each node

    int rootNode;               ///< current root of the tree
    std::vector<ValueT> nodeValue;  ///< value stored at each node

    template <typename U>
    friend class ChainDecomposition;

    /// Post-order pass computing subtree sizes.
    void computeSubtreeSizes(int u, int parent = -1) {
        for (const int &v : adjacency[u]) {
            if (v != parent) {
                computeSubtreeSizes(v, u);
                subtreeSz[u] += subtreeSz[v];
            }
        }
    }

    /// Fills in depth and the binary-lifting ancestor table.
    void computeAncestors(int u, int parent = -1) {
        ancestorTable[u][0] = parent;
        if (parent != -1) {
            depthOf[u] = 1 + depthOf[parent];
        }
        for (int k = 1; k < liftLevels; k++) {
            if (ancestorTable[u][k - 1] != -1) {
                ancestorTable[u][k] = ancestorTable[ancestorTable[u][k - 1]][k - 1];
            }
        }
        for (const int &v : adjacency[u]) {
            if (v != parent) {
                computeAncestors(v, u);
            }
        }
    }

 public:
    /**
     * @brief Allocates internal storage for a tree with `count` nodes.
     * @param count total number of nodes
     */
    explicit LiftableTree(int count)
        : nodeCount(count),
          liftLevels(static_cast<int>(std::floor(std::log2(count))) + 1) {
        rootNode = 0;
        adjacency.resize(nodeCount);
        ancestorTable.assign(nodeCount, std::vector<int>(liftLevels, -1));
        depthOf.assign(nodeCount, 0);
        subtreeSz.assign(nodeCount, 1);
        nodeValue.resize(nodeCount);
    }

    /// Adds an undirected edge between u and v.
    void linkNodes(int u, int v) {
        adjacency[u].push_back(v);
        adjacency[v].push_back(u);
    }

    /// Overrides which node acts as the root.
    void setRoot(int newRoot) { rootNode = newRoot; }

    /// Loads the full set of node values (must match nodeCount).
    void loadValues(const std::vector<ValueT> &values) {
        assert(static_cast<int>(values.size()) == nodeCount);
        nodeValue = values;
    }

    /// Must run after edges/values are populated; fills lifting tables.
    void build() {
        assert(nodeCount > 0);
        computeSubtreeSizes(rootNode);
        computeAncestors(rootNode);
    }

    /// Moves node *p up the tree by `steps`, mutating *p in place.
    void climb(int *p, int steps) {
        for (int k = 0; k < liftLevels; k++) {
            if (*p == -1) {
                return;
            }
            if (steps & 1) {
                *p = ancestorTable[*p][k];
            }
            steps >>= 1;
        }
    }

    /// Returns the ancestor of `node` located `steps` levels above it.
    int ancestorAt(int node, const int &steps) {
        climb(&node, steps);
        return node;
    }

    /// Returns the lowest common ancestor of nodes a and b.
    int lowestCommonAncestor(int a, int b) {
        assert(a >= 0 && b >= 0 && a < nodeCount && b < nodeCount);
        if (depthOf[a] > depthOf[b]) {
            climb(&a, depthOf[a] - depthOf[b]);
        }
        if (depthOf[b] > depthOf[a]) {
            climb(&b, depthOf[b] - depthOf[a]);
        }
        if (a == b) {
            return a;
        }
        for (int k = liftLevels - 1; k >= 0; k--) {
            if (ancestorTable[a][k] != ancestorTable[b][k]) {
                a = ancestorTable[a][k];
                b = ancestorTable[b][k];
            }
        }
        return ancestorTable[a][0];
    }
};

/**
 * @brief A flat array-based segment tree used to store chain values.
 * @tparam ValueT type of value stored in each leaf
 */
template <typename ValueT>
class FlatSegmentTree {
 private:
    std::vector<ValueT> nodes;  ///< underlying array-backed segment tree
    int leafCount;              ///< number of leaves
    ValueT neutralElement = 0;  ///< identity element for combine()

    template <typename U>
    friend class ChainDecomposition;

    /// Defines how two adjacent segments are merged (sum, in this rewrite).
    ValueT combine(ValueT lhs, ValueT rhs) { return lhs + rhs; }

    explicit FlatSegmentTree(int leaves) {
        leafCount = leaves;
        nodes.assign(2 * leafCount, 0ll);
    }

    /// Adds `delta` to the leaf at position p and propagates upward.
    void applyDelta(int p, ValueT delta) {
        for (p += leafCount; p > 0; p >>= 1) {
            nodes[p] += delta;
        }
    }

    /// Combines all leaves within [l, r].
    ValueT rangeCombine(int l, int r) {
        ValueT left = neutralElement, right = neutralElement;
        for (l += leafCount, r += leafCount + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                left = combine(left, nodes[l++]);
            }
            if (r & 1) {
                right = combine(nodes[--r], right);
            }
        }
        return combine(left, right);
    }

    /// Overrides the neutral/identity element (0 for sum/xor, +inf for min...).
    void setNeutralElement(ValueT value) { neutralElement = value; }
};

/**
 * @brief Ties together LiftableTree and FlatSegmentTree to answer path
 * aggregate queries via heavy-light decomposition.
 * @tparam ValueT type of value stored at each node
 */
template <typename ValueT>
class ChainDecomposition : public LiftableTree<ValueT>, public FlatSegmentTree<ValueT> {
 private:
    int nextLabel;  ///< counter used while assigning chain labels
    std::vector<int> chainLabel;   ///< label assigned to each node
    std::vector<int> heavyChild;   ///< heavy child of each node (-1 if leaf)
    std::vector<int> chainTop;     ///< topmost node of the chain a node belongs to

    /// Determines the heavy child (largest subtree) of each node.
    void markHeavyChildren(int u, int parent = -1) {
        int bestSize = -1, bestChild = -1;
        for (const int &v : LiftableTree<ValueT>::adjacency[u]) {
            if (v != parent) {
                markHeavyChildren(v, u);
                if (LiftableTree<ValueT>::subtreeSz[v] > bestSize) {
                    bestSize = LiftableTree<ValueT>::subtreeSz[v];
                    bestChild = v;
                }
            }
        }
        heavyChild[u] = bestChild;
    }

    /// Propagates the top-of-chain node along heavy edges.
    void markChainTops(int u, int parent = -1) {
        if (heavyChild[u] != -1) {
            chainTop[heavyChild[u]] = chainTop[u];
            markChainTops(heavyChild[u], u);
        }
        for (const int &v : LiftableTree<ValueT>::adjacency[u]) {
            if (v != parent && v != heavyChild[u]) {
                markChainTops(v, u);
            }
        }
    }

    /// Assigns contiguous labels so each heavy chain occupies a range.
    void assignLabels(int u, int parent = -1) {
        chainLabel[u] = nextLabel++;
        if (heavyChild[u] != -1) {
            assignLabels(heavyChild[u], u);
        }
        for (const int &v : LiftableTree<ValueT>::adjacency[u]) {
            if (v != parent && v != heavyChild[u]) {
                assignLabels(v, u);
            }
        }
    }

    /// Aggregates a path that lies within a single root-to-leaf chain walk.
    ValueT walkChains(int a, int b) {
        ValueT acc = FlatSegmentTree<ValueT>::neutralElement;
        if (LiftableTree<ValueT>::depthOf[a] < LiftableTree<ValueT>::depthOf[b]) {
            std::swap(a, b);
        }
        while (LiftableTree<ValueT>::depthOf[a] >= LiftableTree<ValueT>::depthOf[b]) {
            int l = chainLabel[chainTop[a]];
            int r = chainLabel[a];
            if (LiftableTree<ValueT>::depthOf[chainTop[a]] < LiftableTree<ValueT>::depthOf[b]) {
                l += LiftableTree<ValueT>::depthOf[b] - LiftableTree<ValueT>::depthOf[chainTop[a]];
            }
            acc = FlatSegmentTree<ValueT>::combine(acc, FlatSegmentTree<ValueT>::rangeCombine(l, r));
            a = LiftableTree<ValueT>::ancestorTable[chainTop[a]][0];
            if (a == -1) {
                break;
            }
        }
        return acc;
    }

 public:
    /**
     * @brief Allocates a decomposition capable of holding `count` nodes.
     * @param count total number of nodes
     */
    explicit ChainDecomposition(int count)
        : LiftableTree<ValueT>(count), FlatSegmentTree<ValueT>(count) {
        nextLabel = 0;
        chainLabel.assign(LiftableTree<ValueT>::nodeCount, -1);
        heavyChild.assign(LiftableTree<ValueT>::nodeCount, -1);
        chainTop.resize(LiftableTree<ValueT>::nodeCount);
        std::iota(chainTop.begin(), chainTop.end(), 0);
    }

    /// Must run after edges/values are populated; builds the full structure.
    void build() {
        LiftableTree<ValueT>::build();

        nextLabel = 0;
        markHeavyChildren(LiftableTree<ValueT>::rootNode);
        markChainTops(LiftableTree<ValueT>::rootNode);
        assignLabels(LiftableTree<ValueT>::rootNode);

        for (int i = 0; i < LiftableTree<ValueT>::nodeCount; i++) {
            FlatSegmentTree<ValueT>::nodes[chainLabel[i] + LiftableTree<ValueT>::nodeCount] =
                LiftableTree<ValueT>::nodeValue[i];
        }
        for (int i = LiftableTree<ValueT>::nodeCount - 1; i > 0; i--) {
            FlatSegmentTree<ValueT>::nodes[i] = FlatSegmentTree<ValueT>::combine(
                FlatSegmentTree<ValueT>::nodes[i << 1], FlatSegmentTree<ValueT>::nodes[i << 1 | 1]);
        }
    }

    /// Sets the value stored at `node` to `newValue`.
    void setValue(int node, ValueT newValue) {
        ValueT delta = newValue - LiftableTree<ValueT>::nodeValue[node];
        FlatSegmentTree<ValueT>::applyDelta(chainLabel[node], delta);
        LiftableTree<ValueT>::nodeValue[node] = newValue;
    }

    /// Returns the aggregate of node values on the simple path from a to b.
    ValueT pathAggregate(int a, int b) {
        int lca = LiftableTree<ValueT>::lowestCommonAncestor(a, b);
        assert(lca != -1);
        ValueT acc = FlatSegmentTree<ValueT>::neutralElement;
        acc += walkChains(a, lca);
        acc += walkChains(b, lca);
        return acc - LiftableTree<ValueT>::nodeValue[lca];
    }
};

}  // namespace heavy_light_decomposition
}  // namespace range_queries

/**
 * Reworded regression check #1.
 */
static void checkScenarioOne() {
    std::cout << "Scenario 1:\n";

    int n = 5;
    std::vector<int64_t> initialValues = {4, 2, 5, 2, 1};
    std::vector<std::vector<int>> edgeList = {{1, 2}, {1, 3}, {3, 4}, {3, 5}};
    std::vector<std::vector<int>> ops = {
        {2, 1, 4},
        {1, 3, 2},
        {2, 1, 4},
    };
    std::vector<int> expected = {11, 8};
    std::vector<int> actual;

    range_queries::heavy_light_decomposition::ChainDecomposition<int64_t> tree(n);
    tree.loadValues(initialValues);
    for (int i = 0; i < n - 1; i++) {
        int u = edgeList[i][0], v = edgeList[i][1];
        tree.linkNodes(u - 1, v - 1);
    }
    tree.build();
    for (const auto &op : ops) {
        int kind = op[0];
        if (kind == 1) {
            tree.setValue(op[1] - 1, op[2]);
        } else if (kind == 2) {
            actual.push_back(tree.pathAggregate(op[1] - 1, op[2] - 1));
        }
    }
    for (int i = 0; i < static_cast<int>(expected.size()); i++) {
        assert(expected[i] == actual[i]);
    }
    std::cout << "\nScenario 1 passed!\n";
}

