#include <algorithm>
#include <cmath>
#include <iostream>

using namespace std;
const int N = 1e6 + 5;
int a[N], bucket[N], cnt[N];
int bucket_size;
struct query {
    int l, r, i;
} q[N];
int ans = 0;

void add(int index) {
    cnt[a[index]]++;
    if (cnt[a[index]] == 1)
        ans++;
}
void remove(int index) {
    cnt[a[index]]--;
    if (cnt[a[index]] == 0)
        ans--;
}

bool mycmp(query x, query y) {
    if (x.l / bucket_size != y.l / bucket_size)
        return x.l / bucket_size < y.l / bucket_size;
    return x.r < y.r;
}

int main() {
    int n, t, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    bucket_size = ceil(sqrt(n));
    scanf("%d", &t);
    for (i = 0; i < t; i++) {
        scanf("%d %d", &q[i].l, &q[i].r);
        q[i].l--;
        q[i].r--;
        q[i].i = i;
    }
    sort(q, q + t, mycmp);
    int left = 0, right = 0;
    for (i = 0; i < t; i++) {
        int L = q[i].l, R = q[i].r;
        while (left < L) {
            remove(left);
            left++;
        }
        while (left > L) {
            add(left - 1);
            left--;
        }
        while (right <= R) {
            add(right);
            right++;
        }
        while (right > R + 1) {
            remove(right - 1);
            right--;
        }
        bucket[q[i].i] = ans;
    }
    for (i = 0; i < t; i++) printf("%d\n", bucket[i]);
    return 0;
}

// Offline range-query answering using Mo's square-root decomposition trick.
// Instead of answering each [l, r] query independently, we reorder the
// queries so that consecutive ones share most of their range, then slide
// a two-pointer window across the array, paying only for the incremental
// difference between queries.
#include <algorithm>
#include <cmath>
#include <iostream>

using namespace std;

const int MAXN = 1e6 + 5;

int values[MAXN];         // the input sequence
int distinctCountAt[MAXN]; // frequency table over value domain
int resultFor[MAXN];       // answer per original query index
int blockWidth;

struct Range {
    int from, to, originalIndex;
};

Range ranges[MAXN];
int distinctInWindow = 0;

// Including position p into the active window.
void includePos(int p) {
    distinctCountAt[values[p]]++;
    if (distinctCountAt[values[p]] == 1) {
        distinctInWindow++;
    }
}

// Excluding position p from the active window.
void excludePos(int p) {
    distinctCountAt[values[p]]--;
    if (distinctCountAt[values[p]] == 0) {
        distinctInWindow--;
    }
}

// Comparator implementing Mo's ordering: bucket by block, then by right end.
bool moOrder(const Range &a, const Range &b) {
    int blockA = a.from / blockWidth;
    int blockB = b.from / blockWidth;
    if (blockA != blockB) {
        return blockA < blockB;
    }
    return a.to < b.to;
}

int main() {
    int n, queryCount;
    scanf("%d", &n);
    for (int idx = 0; idx < n; idx++) {
        scanf("%d", &values[idx]);
    }

    blockWidth = static_cast<int>(ceil(sqrt(static_cast<double>(n))));

    scanf("%d", &queryCount);
    for (int idx = 0; idx < queryCount; idx++) {
        scanf("%d %d", &ranges[idx].from, &ranges[idx].to);
        ranges[idx].from--;
        ranges[idx].to--;
        ranges[idx].originalIndex = idx;
    }

    sort(ranges, ranges + queryCount, moOrder);

    int windowLeft = 0, windowRight = 0;
    for (int idx = 0; idx < queryCount; idx++) {
        int targetLeft = ranges[idx].from;
        int targetRight = ranges[idx].to;

        while (windowLeft < targetLeft) {
            excludePos(windowLeft);
            windowLeft++;
        }
        while (windowLeft > targetLeft) {
            includePos(windowLeft - 1);
            windowLeft--;
        }
        while (windowRight <= targetRight) {
            includePos(windowRight);
            windowRight++;
        }
        while (windowRight > targetRight + 1) {
            excludePos(windowRight - 1);
            windowRight--;
        }

        resultFor[ranges[idx].originalIndex] = distinctInWindow;
    }

    for (int idx = 0; idx < queryCount; idx++) {
        printf("%d\n", resultFor[idx]);
    }
    return 0;
}

/**
 * @file
 * @brief [Persistent segment tree with range updates (lazy
 * propagation)](https://en.wikipedia.org/wiki/Persistent_data_structure)
 *
 * @details
 * A normal segment tree facilitates making point updates and range queries in
 * logarithmic time. Lazy propagation preserves the logarithmic time with range
 * updates. So, a segment tree with lazy propagation enables doing range updates
 * and range queries in logarithmic time, but it doesn't save any information
 * about itself before the last update. A persistent data structure always
 * preserves the previous version of itself when it is modified. That is, a new
 * version of the segment tree is generated after every update. It saves all
 * previous versions of itself (before every update) to facilitate doing range
 * queries in any version. More memory is used ,but the logarithmic time is
 * preserved because the new version points to the same nodes, that the previous
 * version points to, that are not affected by the update. That is, only the
 * nodes that are affected by the update and their ancestors are copied. The
 * rest is copied using lazy propagation in the next queries. Thus preserving
 * the logarithmic time because the number of nodes copied after any update is
 * logarithmic.
 *
 * @author [Magdy Sedra](https://github.com/MSedra)
 */
#include <cstdint>   /// for std::uint32_t
#include <iostream>  /// for IO operations
#include <memory>    /// to manage dynamic memory
#include <vector>    /// for std::vector

/**
 * @namespace range_queries
 * @brief Range queries algorithms
 */
namespace range_queries {

/**
 * @brief Range query here is range sum, but the code can be modified to make
 * different queries like range max or min.
 */
class perSegTree {
 private:
    class Node {
     public:
        std::shared_ptr<Node> left = nullptr;   /// pointer to the left node
        std::shared_ptr<Node> right = nullptr;  /// pointer to the right node
        int64_t val = 0,
                prop = 0;  /// val is the value of the node (here equals to the
                           /// sum of the leaf nodes children of that node),
                           /// prop is the value to be propagated/added to all
                           /// the leaf nodes children of that node
    };

    uint32_t n = 0;  /// number of elements/leaf nodes in the segment tree
    std::vector<std::shared_ptr<Node>>
        ptrs{};  /// ptrs[i] holds a root pointer to the segment tree after the
                 /// ith update. ptrs[0] holds a root pointer to the segment
                 /// tree before any updates
    std::vector<int64_t> vec{};  /// values of the leaf nodes that the segment
                                 /// tree will be constructed with

    /**
     * @brief Creating a new node with the same values of curr node
     * @param curr node that would be copied
     * @returns the new node
     */
    std::shared_ptr<Node> newKid(std::shared_ptr<Node> const &curr) {
        auto newNode = std::make_shared<Node>(Node());
        newNode->left = curr->left;
        newNode->right = curr->right;
        newNode->prop = curr->prop;
        newNode->val = curr->val;
        return newNode;
    }

    /**
     * @brief If there is some value to be propagated to the passed node, value
     * is added to the node and the children of the node, if exist, are copied
     * and the propagated value is also added to them
     * @param i the left index of the range that the passed node holds its sum
     * @param j the right index of the range that the passed node holds its sum
     * @param curr pointer to the node to be propagated
     * @returns void
     */
    void lazy(const uint32_t &i, const uint32_t &j,
              std::shared_ptr<Node> const &curr) {
        if (!curr->prop) {
            return;
        }
        curr->val += (j - i + 1) * curr->prop;
        if (i != j) {
            curr->left = newKid(curr->left);
            curr->right = newKid(curr->right);
            curr->left->prop += curr->prop;
            curr->right->prop += curr->prop;
        }
        curr->prop = 0;
    }

    /**
     * @brief Constructing the segment tree with the early passed vector. Every
     * call creates a node to hold the sum of the given range, set its pointers
     * to the children, and set its value to the sum of the children's values
     * @param i the left index of the range that the created node holds its sum
     * @param j the right index of the range that the created node holds its sum
     * @returns pointer to the newly created node
     */
    std::shared_ptr<Node> construct(const uint32_t &i, const uint32_t &j) {
        auto newNode = std::make_shared<Node>(Node());
        if (i == j) {
            newNode->val = vec[i];
        } else {
            uint32_t mid = i + (j - i) / 2;
            auto leftt = construct(i, mid);
            auto right = construct(mid + 1, j);
            newNode->val = leftt->val + right->val;
            newNode->left = leftt;
            newNode->right = right;
        }
        return newNode;
    }

    /**
     * @brief Doing range update, checking at every node if it has some value to
     * be propagated. All nodes affected by the update are copied and
     * propagation value is added to the leaf of them
     * @param i the left index of the range that the passed node holds its sum
     * @param j the right index of the range that the passed node holds its sum
     * @param l the left index of the range to be updated
     * @param r the right index of the range to be updated
     * @param value the value to be added to every element whose index x
     * satisfies l<=x<=r
     * @param curr pointer to the current node, which has value = the sum of
     * elements whose index x satisfies i<=x<=j
     * @returns pointer to the current newly created node
     */
    std::shared_ptr<Node> update(const uint32_t &i, const uint32_t &j,
                                 const uint32_t &l, const uint32_t &r,
                                 const int64_t &value,
                                 std::shared_ptr<Node> const &curr) {
        lazy(i, j, curr);
        if (i >= l && j <= r) {
            std::shared_ptr<Node> newNode = newKid(curr);
            newNode->prop += value;
            lazy(i, j, newNode);
            return newNode;
        }
        if (i > r || j < l) {
            return curr;
        }
        auto newNode = std::make_shared<Node>(Node());
        uint32_t mid = i + (j - i) / 2;
        newNode->left = update(i, mid, l, r, value, curr->left);
        newNode->right = update(mid + 1, j, l, r, value, curr->right);
        newNode->val = newNode->left->val + newNode->right->val;
        return newNode;
    }

    /**
     * @brief Querying the range from index l to index r, checking at every node
     * if it has some value to be propagated. Current node's value is returned
     * if its range is completely inside the wanted range, else 0 is returned
     * @param i the left index of the range that the passed node holds its sum
     * @param j the right index of the range that the passed node holds its sum
     * @param l the left index of the range whose sum should be returned as a
     * result
     * @param r the right index of the range whose sum should be returned as a
     * result
     * @param curr pointer to the current node, which has value = the sum of
     * elements whose index x satisfies i<=x<=j
     * @returns sum of elements whose index x satisfies l<=x<=r
     */
    int64_t query(const uint32_t &i, const uint32_t &j, const uint32_t &l,
                  const uint32_t &r, std::shared_ptr<Node> const &curr) {
        lazy(i, j, curr);
        if (j < l || r < i) {
            return 0;
        }
        if (i >= l && j <= r) {
            return curr->val;
        }
        uint32_t mid = i + (j - i) / 2;
        return query(i, mid, l, r, curr->left) +
               query(mid + 1, j, l, r, curr->right);
    }

    /**
     * public methods that can be used directly from outside the class. They
     * call the private functions that do all the work
     */
 public:
    /**
     * @brief Constructing the segment tree with the values in the passed
     * vector. Returned root pointer is pushed in the pointers vector to have
     * access to the original version if the segment tree is updated
     * @param vec vector whose values will be used to build the segment tree
     * @returns void
     */
    void construct(const std::vector<int64_t>
                       &vec)  // the segment tree will be built from the values
                              // in "vec", "vec" is 0 indexed
    {
        if (vec.empty()) {
            return;
        }
        n = vec.size();
        this->vec = vec;
        auto root = construct(0, n - 1);
        ptrs.push_back(root);
    }

    /**
     * @brief Doing range update by passing the left and right indexes of the
     * range as well as the value to be added.
     * @param l the left index of the range to be updated
     * @param r the right index of the range to be updated
     * @param value the value to be added to every element whose index x
     * satisfies l<=x<=r
     * @returns void
     */
    void update(const uint32_t &l, const uint32_t &r,
                const int64_t
                    &value)  // all elements from index "l" to index "r" would
                             // by updated by "value", "l" and "r" are 0 indexed
    {
        ptrs.push_back(update(
            0, n - 1, l, r, value,
            ptrs[ptrs.size() -
                 1]));  // saving the root pointer to the new segment tree
    }

    /**
     * @brief Querying the range from index l to index r, getting the sum of the
     * elements whose index x satisfies l<=x<=r
     * @param l the left index of the range whose sum should be returned as a
     * result
     * @param r the right index of the range whose sum should be returned as a
     * result
     * @param version the version to query on. If equals to 0, the original
     * segment tree will be queried
     * @returns sum of elements whose index x satisfies l<=x<=r
     */
    int64_t query(
        const uint32_t &l, const uint32_t &r,
        const uint32_t
            &version)  // querying the range from "l" to "r" in a segment tree
                       // after "version" updates, "l" and "r" are 0 indexed
    {
        return query(0, n - 1, l, r, ptrs[version]);
    }

    /**
     * @brief Getting the number of versions after updates so far which is equal
     * to the size of the pointers vector
     * @returns the number of versions
     */
    uint32_t size()  // returns the number of segment trees (versions) , the
                     // number of updates done so far = returned value - 1
                     // ,because one of the trees is the original segment tree
    {
        return ptrs.size();
    }
};
}  // namespace range_queries

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    std::vector<int64_t> arr = {-5, 2, 3, 11, -2, 7, 0, 1};
    range_queries::perSegTree tree;
    std::cout << "Elements before any updates are {";
    for (uint32_t i = 0; i < arr.size(); ++i) {
        std::cout << arr[i];
        if (i != arr.size() - 1) {
            std::cout << ",";
        }
    }
    std::cout << "}\n";
    tree.construct(
        arr);  // constructing the original segment tree (version = 0)
    std::cout << "Querying range sum on version 0 from index 2 to 4 = 3+11-2 = "
              << tree.query(2, 4, 0) << '\n';
    std::cout
        << "Subtract 7 from all elements from index 1 to index 5 inclusive\n";
    tree.update(1, 5, -7);  // subtracting 7 from index 1 to index 5
    std::cout << "Elements of the segment tree whose version = 1 (after 1 "
                 "update) are {";
    for (uint32_t i = 0; i < arr.size(); ++i) {
        std::cout << tree.query(i, i, 1);
        if (i != arr.size() - 1) {
            std::cout << ",";
        }
    }
    std::cout << "}\n";
    std::cout << "Add 10 to all elements from index 0 to index 7 inclusive\n";
    tree.update(0, 7, 10);  // adding 10 to all elements
    std::cout << "Elements of the segment tree whose version = 2 (after 2 "
                 "updates) are {";
    for (uint32_t i = 0; i < arr.size(); ++i) {
        std::cout << tree.query(i, i, 2);
        if (i != arr.size() - 1) {
            std::cout << ",";
        }
    }
    std::cout << "}\n";
    std::cout << "Number of segment trees (versions) now = " << tree.size()
              << '\n';
    std::cout << "Querying range sum on version 0 from index 3 to 5 = 11-2+7 = "
              << tree.query(3, 5, 0) << '\n';
    std::cout << "Querying range sum on version 1 from index 3 to 5 = 4-9+0 = "
              << tree.query(3, 5, 1) << '\n';
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Persistent segment tree that supports range-add updates through
 * lazy propagation while keeping every historical version reachable.
 *
 * @details
 * A plain segment tree with lazy propagation lets you do range updates and
 * range queries in O(log n), but every update overwrites the tree in place,
 * so older states are lost. Making the structure persistent means each
 * update produces a brand-new "version" of the tree without discarding the
 * old ones: unaffected subtrees are shared between versions (their pointers
 * are simply reused), and only the O(log n) nodes on the path to the
 * updated range are freshly allocated. That keeps both memory and time
 * logarithmic per update while letting callers query any past version.
 *
 * @author Rewritten variant for classroom dataset purposes
 */
#include <cstdint>   /// fixed width integers
#include <iostream>  /// console IO
#include <memory>    /// shared_ptr based node management
#include <vector>    /// vector container

/**
 * @namespace range_queries
 * @brief Range query utilities
 */
namespace range_queries {

/**
 * @brief Persistent range-sum tree with lazy range-add support. The query
 * performed here is sum, though the same skeleton generalizes to min/max.
 */
class VersionedRangeSum {
 private:
    struct TreeNode {
        std::shared_ptr<TreeNode> leftChild = nullptr;
        std::shared_ptr<TreeNode> rightChild = nullptr;
        int64_t total = 0;    // aggregate value stored at this node
        int64_t pending = 0;  // lazily-deferred addition for this subtree
    };

    uint32_t elementCount = 0;
    std::vector<std::shared_ptr<TreeNode>> versionRoots{};
    std::vector<int64_t> sourceValues{};

    // Shallow-clones a node so we can mutate the copy without disturbing
    // any earlier version that still points at the original.
    std::shared_ptr<TreeNode> cloneNode(std::shared_ptr<TreeNode> const &src) {
        auto copy = std::make_shared<TreeNode>(TreeNode());
        copy->leftChild = src->leftChild;
        copy->rightChild = src->rightChild;
        copy->pending = src->pending;
        copy->total = src->total;
        return copy;
    }

    // Applies any deferred addition stored at a node, pushing it down to
    // freshly-cloned children when the node isn't a leaf.
    void settle(const uint32_t &lo, const uint32_t &hi,
                std::shared_ptr<TreeNode> const &node) {
        if (!node->pending) {
            return;
        }
        node->total += (hi - lo + 1) * node->pending;
        if (lo != hi) {
            node->leftChild = cloneNode(node->leftChild);
            node->rightChild = cloneNode(node->rightChild);
            node->leftChild->pending += node->pending;
            node->rightChild->pending += node->pending;
        }
        node->pending = 0;
    }

    // Recursively builds the initial (version 0) tree from sourceValues.
    std::shared_ptr<TreeNode> build(const uint32_t &lo, const uint32_t &hi) {
        auto node = std::make_shared<TreeNode>(TreeNode());
        if (lo == hi) {
            node->total = sourceValues[lo];
        } else {
            uint32_t mid = lo + (hi - lo) / 2;
            auto leftHalf = build(lo, mid);
            auto rightHalf = build(mid + 1, hi);
            node->total = leftHalf->total + rightHalf->total;
            node->leftChild = leftHalf;
            node->rightChild = rightHalf;
        }
        return node;
    }

    // Produces a new tree (sharing untouched branches) reflecting adding
    // `delta` to every element in [ql, qr].
    std::shared_ptr<TreeNode> applyAdd(const uint32_t &lo, const uint32_t &hi,
                                        const uint32_t &ql, const uint32_t &qr,
                                        const int64_t &delta,
                                        std::shared_ptr<TreeNode> const &node) {
        settle(lo, hi, node);
        if (lo >= ql && hi <= qr) {
            auto copy = cloneNode(node);
            copy->pending += delta;
            settle(lo, hi, copy);
            return copy;
        }
        if (lo > qr || hi < ql) {
            return node;
        }
        auto copy = std::make_shared<TreeNode>(TreeNode());
        uint32_t mid = lo + (hi - lo) / 2;
        copy->leftChild = applyAdd(lo, mid, ql, qr, delta, node->leftChild);
        copy->rightChild = applyAdd(mid + 1, hi, ql, qr, delta, node->rightChild);
        copy->total = copy->leftChild->total + copy->rightChild->total;
        return copy;
    }

    // Sums the values covered by [ql, qr] within the given node's range.
    int64_t sumRange(const uint32_t &lo, const uint32_t &hi,
                      const uint32_t &ql, const uint32_t &qr,
                      std::shared_ptr<TreeNode> const &node) {
        settle(lo, hi, node);
        if (hi < ql || qr < lo) {
            return 0;
        }
        if (lo >= ql && hi <= qr) {
            return node->total;
        }
        uint32_t mid = lo + (hi - lo) / 2;
        return sumRange(lo, mid, ql, qr, node->leftChild) +
               sumRange(mid + 1, hi, ql, qr, node->rightChild);
    }

 public:
    // Builds version 0 from the supplied values (0-indexed).
    void build(const std::vector<int64_t> &initial) {
        if (initial.empty()) {
            return;
        }
        elementCount = initial.size();
        sourceValues = initial;
        auto root = build(0, elementCount - 1);
        versionRoots.push_back(root);
    }

    // Adds `delta` to every element with index in [lo, hi], creating and
    // storing a brand-new version derived from the latest one.
    void addRange(const uint32_t &lo, const uint32_t &hi, const int64_t &delta) {
        versionRoots.push_back(
            applyAdd(0, elementCount - 1, lo, hi, delta,
                     versionRoots[versionRoots.size() - 1]));
    }

    // Returns sum of elements in [lo, hi] as seen in the given version.
    int64_t rangeSum(const uint32_t &lo, const uint32_t &hi,
                      const uint32_t &version) {
        return sumRange(0, elementCount - 1, lo, hi, versionRoots[version]);
    }

    // Number of stored versions (original + one per update).
    uint32_t versionCount() { return versionRoots.size(); }
};
}  // namespace range_queries

/**
 * @brief Demo run showing versions before/after two range updates
 */
static void demo() {
    std::vector<int64_t> data = {-5, 2, 3, 11, -2, 7, 0, 1};
    range_queries::VersionedRangeSum tree;

    std::cout << "Starting array: {";
    for (uint32_t i = 0; i < data.size(); ++i) {
        std::cout << data[i];
        if (i != data.size() - 1) {
            std::cout << ",";
        }
    }
    std::cout << "}\n";

    tree.build(data);  // version 0
    std::cout << "Sum over [2,4] in version 0 (expect 3+11-2=12): "
              << tree.rangeSum(2, 4, 0) << '\n';

    std::cout << "Applying -7 to indices [1,5]\n";
    tree.addRange(1, 5, -7);
    std::cout << "Version 1 elements: {";
    for (uint32_t i = 0; i < data.size(); ++i) {
        std::cout << tree.rangeSum(i, i, 1);
        if (i != data.size() - 1) {
            std::cout << ",";
        }
    }
    std::cout << "}\n";

    std::cout << "Applying +10 to indices [0,7]\n";
    tree.addRange(0, 7, 10);
    std::cout << "Version 2 elements: {";
    for (uint32_t i = 0; i < data.size(); ++i) {
        std::cout << tree.rangeSum(i, i, 2);
        if (i != data.size() - 1) {
            std::cout << ",";
        }
    }
    std::cout << "}\n";

    std::cout << "Total number of stored versions: " << tree.versionCount()
              << '\n';
    std::cout << "Sum over [3,5] in version 0 (expect 11-2+7=16): "
              << tree.rangeSum(3, 5, 0) << '\n';
    std::cout << "Sum over [3,5] in version 1 (expect 4-9+0=-5): "
              << tree.rangeSum(3, 5, 1) << '\n';
}

int main() {
    demo();
    return 0;
}

/**
 * @file
 * @brief
 * [Prefix Sum
 * Array](https://en.wikipedia.org/wiki/Prefix_sum) data structure
 * implementation.
 *
 * @details
 * Prefix Sum Array is a data structure, that allows answering sum in some range
 * queries. It can answer most sum range queries in O(1), with a build time
 * complexity of O(N). But it hasn't an update querie.
 *
 * * Running Time Complexity \n
 * * Build : O(N) \n
 * * Range Query : O(1) \n
 * @author [Paulo Vitor Lima Borges](https://github.com/PauloVLB)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace range_queries
 * @brief Range Queries algorithms
 */
namespace range_queries {
/**
 * @namespace prefix_sum_array
 * @brief Range sum queries using prefix-sum-array
 */
namespace prefix_sum_array {

std::vector<int64_t> PSA{};

/**
 * @brief function that builds the PSA
 * @param original_array original array of values
 * @returns void
 */
void build(const std::vector<int64_t>& original_array) {
    PSA.clear();
    PSA.push_back(0);
    for (std::size_t i = 1; i < original_array.size(); ++i) {
        PSA.push_back(PSA.back() + original_array[i]);
    }
}
/**
 * @brief query function
 * @param beg begin of the interval to sum
 * @param end end of the interval to sum
 * @returns sum of the range [beg, end]
 */
int64_t query(int64_t beg, int64_t end) { return PSA[end] - PSA[beg - 1]; }

}  // namespace prefix_sum_array
}  // namespace range_queries

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    std::vector<int64_t> values{0,  123, 0,  2,  -2, 5,
                                24, 0,   23, -1, -1};  // original array

    range_queries::prefix_sum_array::build(values);
    // queries are of the type: sum of the range [a, b] = psa[b] - psa[a-1]

    assert(range_queries::prefix_sum_array::query(1, 10) ==
           173);  // sum of the entire array
    assert(range_queries::prefix_sum_array::query(4, 6) ==
           27);  // the sum of the interval [4, 6]
    assert(range_queries::prefix_sum_array::query(5, 9) ==
           51);  // the sum of the interval [5, 9]
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Cumulative-sum array (a.k.a. prefix sums) letting range-sum
 * queries run in constant time after a linear-time precomputation pass.
 *
 * @details
 * By precomputing running totals of the input sequence we can answer
 * "what is the sum between index a and b" queries in O(1) each, at the
 * cost of O(n) preprocessing and O(n) extra storage. The tradeoff is that
 * there is no efficient way to update individual elements afterward
 * without rebuilding (or using a Fenwick/segment tree instead).
 *
 * * Preprocessing: O(n)
 * * Each range query: O(1)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace range_queries
 * @brief Range query algorithms
 */
namespace range_queries {
/**
 * @namespace prefix_sum_array
 * @brief Constant-time range sums via a running-total array
 */
namespace prefix_sum_array {

std::vector<int64_t> runningTotals{};

/**
 * @brief Builds the running-total table from the raw input sequence.
 * @param sourceData the sequence to precompute sums over
 */
void buildTable(const std::vector<int64_t>& sourceData) {
    runningTotals.clear();
    runningTotals.push_back(0);
    for (std::size_t pos = 1; pos < sourceData.size(); ++pos) {
        runningTotals.push_back(runningTotals.back() + sourceData[pos]);
    }
}

/**
 * @brief Returns the sum of elements over the inclusive range [from, to].
 * @param from start of the range (1-indexed style, matching original array)
 * @param to end of the range
 * @returns sum across [from, to]
 */
int64_t rangeSum(int64_t from, int64_t to) {
    return runningTotals[to] - runningTotals[from - 1];
}

}  // namespace prefix_sum_array
}  // namespace range_queries

/**
 * @brief Sanity checks exercising a handful of ranges
 */
static void runChecks() {
    std::vector<int64_t> sample{0,  123, 0,  2,  -2, 5,
                                24, 0,   23, -1, -1};

    range_queries::prefix_sum_array::buildTable(sample);

    assert(range_queries::prefix_sum_array::rangeSum(1, 10) == 173);
    assert(range_queries::prefix_sum_array::rangeSum(4, 6) == 27);
    assert(range_queries::prefix_sum_array::rangeSum(5, 9) == 51);
}

int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief   Implementation of [Segment Tree]
 *          (https://en.wikipedia.org/wiki/Segment_tree) data structure
 *
 * @details
 * A segment tree, also known as a statistic tree, is a tree data structure used
 * for storing information about intervals, or segments. Its classical version
 * allows querying which of the stored segments contain a given point, but our
 * modification allows us to perform (query) any binary operation on any range
 * in the array in O(logN) time. Here, we have used addition (+).
 * For range updates, we have used lazy propagation.
 *
 * * Space Complexity : O(NlogN) \n
 * * Build Time Complexity : O(NlogN) \n
 * * Query Time Complexity : O(logN) \n
 *
 * @author  [Madhav Gaba](https://github.com/madhavgaba)
 * @author  [Soham Roy](https://github.com/sohamroy19)
 */

#include <cassert>   /// for assert
#include <cmath>     /// for log2
#include <cstdint>   /// for std::uint64_t
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @brief   Constructs the initial segment tree
 *
 * @param   arr input to construct the tree out of
 * @param   segtree the segment tree
 * @param   low inclusive lowest index of arr to begin at
 * @param   high inclusive highest index of arr to end at
 * @param   pos index of segtree to fill (eg. root node)
 * @returns void
 */
void ConsTree(const std::vector<int64_t> &arr, std::vector<int64_t> *segtree,
              uint64_t low, uint64_t high, uint64_t pos) {
    if (low == high) {
        (*segtree)[pos] = arr[low];
        return;
    }

    uint64_t mid = (low + high) / 2;
    ConsTree(arr, segtree, low, mid, 2 * pos + 1);
    ConsTree(arr, segtree, mid + 1, high, 2 * pos + 2);
    (*segtree)[pos] = (*segtree)[2 * pos + 1] + (*segtree)[2 * pos + 2];
}

/**
 * @brief   Returns the sum of all elements in a range
 *
 * @param   segtree the segment tree
 * @param   lazy for lazy propagation
 * @param   qlow lower index of the required query
 * @param   qhigh higher index of the required query
 * @param   low lower index of query for this function call
 * @param   high higher index of query for this function call
 * @param   pos index of segtree to consider (eg. root node)
 * @return  result of the range query for this function call
 */
int64_t query(std::vector<int64_t> *segtree, std::vector<int64_t> *lazy,
              uint64_t qlow, uint64_t qhigh, uint64_t low, uint64_t high,
              uint64_t pos) {
    if (low > high || qlow > high || low > qhigh) {
        return 0;
    }

    if ((*lazy)[pos] != 0) {
        (*segtree)[pos] += (*lazy)[pos] * (high - low + 1);

        if (low != high) {
            (*lazy)[2 * pos + 1] += (*lazy)[pos];
            (*lazy)[2 * pos + 2] += (*lazy)[pos];
        }
        (*lazy)[pos] = 0;
    }

    if (qlow <= low && qhigh >= high) {
        return (*segtree)[pos];
    }

    uint64_t mid = (low + high) / 2;

    return query(segtree, lazy, qlow, qhigh, low, mid, 2 * pos + 1) +
           query(segtree, lazy, qlow, qhigh, mid + 1, high, 2 * pos + 2);
}

/**
 * @brief   Updates a range of the segment tree
 *
 * @param   segtree the segment tree
 * @param   lazy for lazy propagation
 * @param   start lower index of the required query
 * @param   end higher index of the required query
 * @param   delta integer to add to each element of the range
 * @param   low lower index of query for this function call
 * @param   high higher index of query for this function call
 * @param   pos index of segtree to consider (eg. root node)
 * @returns void
 */
void update(std::vector<int64_t> *segtree, std::vector<int64_t> *lazy,
            int64_t start, int64_t end, int64_t delta, uint64_t low,
            uint64_t high, uint64_t pos) {
    if (low > high) {
        return;
    }

    if ((*lazy)[pos] != 0) {
        (*segtree)[pos] += (*lazy)[pos] * (high - low + 1);

        if (low != high) {
            (*lazy)[2 * pos + 1] += (*lazy)[pos];
            (*lazy)[2 * pos + 2] += (*lazy)[pos];
        }
        (*lazy)[pos] = 0;
    }

    if (start > high || end < low) {
        return;
    }

    if (start <= low && end >= high) {
        (*segtree)[pos] += delta * (high - low + 1);

        if (low != high) {
            (*lazy)[2 * pos + 1] += delta;
            (*lazy)[2 * pos + 2] += delta;
        }

        return;
    }

    uint64_t mid = (low + high) / 2;

    update(segtree, lazy, start, end, delta, low, mid, 2 * pos + 1);
    update(segtree, lazy, start, end, delta, mid + 1, high, 2 * pos + 2);
    (*segtree)[pos] = (*segtree)[2 * pos + 1] + (*segtree)[2 * pos + 2];
}

/**
 * @brief   Self-test implementation
 *
 * @returns void
 */
static void test() {
    auto max = static_cast<int64_t>(2 * pow(2, ceil(log2(7))) - 1);
    assert(max == 15);

    std::vector<int64_t> arr{1, 2, 3, 4, 5, 6, 7}, lazy(max), segtree(max);
    ConsTree(arr, &segtree, 0, 7 - 1, 0);

    assert(query(&segtree, &lazy, 1, 5, 0, 7 - 1, 0) == 2 + 3 + 4 + 5 + 6);

    update(&segtree, &lazy, 2, 4, 1, 0, 7 - 1, 0);
    assert(query(&segtree, &lazy, 1, 5, 0, 7 - 1, 0) == 2 + 4 + 5 + 6 + 6);

    update(&segtree, &lazy, 0, 6, -2, 0, 7 - 1, 0);
    assert(query(&segtree, &lazy, 0, 4, 0, 7 - 1, 0) == -1 + 0 + 2 + 3 + 4);
}

/**
 * @brief   Main function
 *
 * @return  0 on exit
 */
int main() {
    test();  // run self-test implementations

    std::cout << "Enter number of elements: ";

    uint64_t n = 0;
    std::cin >> n;

    auto max = static_cast<uint64_t>(2 * pow(2, ceil(log2(n))) - 1);
    std::vector<int64_t> arr(n), lazy(max), segtree(max);

    int choice = 0;
    std::cout << "\nDo you wish to enter each number?:\n"
                 "1: Yes\n"
                 "0: No (default initialize them to 0)\n";

    std::cin >> choice;
    if (choice == 1) {
        std::cout << "Enter " << n << " numbers:\n";
        for (int i = 1; i <= n; i++) {
            std::cout << i << ": ";
            std::cin >> arr[i];
        }
    }

    ConsTree(arr, &segtree, 0, n - 1, 0);

    do {
        std::cout << "\nMake your choice:\n"
                     "1: Range update (input)\n"
                     "2: Range query (output)\n"
                     "0: Exit\n";
        std::cin >> choice;

        if (choice == 1) {
            std::cout << "Enter 1-indexed lower bound, upper bound & value:\n";

            uint64_t p = 1, q = 1, v = 0;
            std::cin >> p >> q >> v;
            update(&segtree, &lazy, p - 1, q - 1, v, 0, n - 1, 0);
        } else if (choice == 2) {
            std::cout << "Enter 1-indexed lower bound & upper bound:\n";

            uint64_t p = 1, q = 1;
            std::cin >> p >> q;
            std::cout << query(&segtree, &lazy, p - 1, q - 1, 0, n - 1, 0);
            std::cout << "\n";
        }
    } while (choice > 0);

    return 0;
}

/**
 * @file
 * @brief Iterative-friendly recursive segment tree supporting range-sum
 * queries alongside range-add updates via lazy propagation.
 *
 * @details
 * A segment tree stores partial aggregates over an implicit binary
 * partition of the array, letting range operations run in O(log n) instead
 * of O(n). Ordinarily updating an entire range would still require
 * touching each covered leaf, but lazy propagation defers those updates:
 * whenever we descend into a subtree during another query, we first flush
 * anything pending on the current node before continuing.
 *
 * * Space: O(n log n)
 * * Build: O(n log n)
 * * Query: O(log n)
 */

#include <cassert>   /// for assert
#include <cmath>     /// for log2
#include <cstdint>   /// for uint64_t
#include <iostream>  /// for IO
#include <vector>    /// for vector

/**
 * @brief Recursively fills in the segment tree array from raw values.
 *
 * @param source values to build the tree from
 * @param tree output tree storage
 * @param lo inclusive lower bound of the segment covered by this call
 * @param hi inclusive upper bound of the segment covered by this call
 * @param node index in `tree` currently being filled
 */
void buildTree(const std::vector<int64_t> &source, std::vector<int64_t> *tree,
               uint64_t lo, uint64_t hi, uint64_t node) {
    if (lo == hi) {
        (*tree)[node] = source[lo];
        return;
    }

    uint64_t mid = (lo + hi) / 2;
    buildTree(source, tree, lo, mid, 2 * node + 1);
    buildTree(source, tree, mid + 1, hi, 2 * node + 2);
    (*tree)[node] = (*tree)[2 * node + 1] + (*tree)[2 * node + 2];
}

/**
 * @brief Answers a range-sum query, flushing pending lazy updates as needed.
 *
 * @param tree the segment tree array
 * @param pending the lazy-propagation array
 * @param wantLo lower bound of the requested query range
 * @param wantHi upper bound of the requested query range
 * @param lo lower bound covered by the current recursive call
 * @param hi upper bound covered by the current recursive call
 * @param node index of the node under consideration
 * @return partial (or full) sum contributed by this call
 */
int64_t querySum(std::vector<int64_t> *tree, std::vector<int64_t> *pending,
                  uint64_t wantLo, uint64_t wantHi, uint64_t lo, uint64_t hi,
                  uint64_t node) {
    if (lo > hi || wantLo > hi || lo > wantHi) {
        return 0;
    }

    if ((*pending)[node] != 0) {
        (*tree)[node] += (*pending)[node] * (hi - lo + 1);

        if (lo != hi) {
            (*pending)[2 * node + 1] += (*pending)[node];
            (*pending)[2 * node + 2] += (*pending)[node];
        }
        (*pending)[node] = 0;
    }

    if (wantLo <= lo && wantHi >= hi) {
        return (*tree)[node];
    }

    uint64_t mid = (lo + hi) / 2;

    return querySum(tree, pending, wantLo, wantHi, lo, mid, 2 * node + 1) +
           querySum(tree, pending, wantLo, wantHi, mid + 1, hi, 2 * node + 2);
}

/**
 * @brief Adds `delta` to every element within [rangeLo, rangeHi].
 *
 * @param tree the segment tree array
 * @param pending the lazy-propagation array
 * @param rangeLo lower bound of the update
 * @param rangeHi upper bound of the update
 * @param delta amount to add to each covered element
 * @param lo lower bound covered by the current recursive call
 * @param hi upper bound covered by the current recursive call
 * @param node index of the node under consideration
 */
void addRange(std::vector<int64_t> *tree, std::vector<int64_t> *pending,
              int64_t rangeLo, int64_t rangeHi, int64_t delta, uint64_t lo,
              uint64_t hi, uint64_t node) {
    if (lo > hi) {
        return;
    }

    if ((*pending)[node] != 0) {
        (*tree)[node] += (*pending)[node] * (hi - lo + 1);

        if (lo != hi) {
            (*pending)[2 * node + 1] += (*pending)[node];
            (*pending)[2 * node + 2] += (*pending)[node];
        }
        (*pending)[node] = 0;
    }

    if (rangeLo > hi || rangeHi < lo) {
        return;
    }

    if (rangeLo <= lo && rangeHi >= hi) {
        (*tree)[node] += delta * (hi - lo + 1);

        if (lo != hi) {
            (*pending)[2 * node + 1] += delta;
            (*pending)[2 * node + 2] += delta;
        }

        return;
    }

    uint64_t mid = (lo + hi) / 2;

    addRange(tree, pending, rangeLo, rangeHi, delta, lo, mid, 2 * node + 1);
    addRange(tree, pending, rangeLo, rangeHi, delta, mid + 1, hi, 2 * node + 2);
    (*tree)[node] = (*tree)[2 * node + 1] + (*tree)[2 * node + 2];
}

/**
 * @brief Runs a small set of correctness checks against known results.
 */
static void selfCheck() {
    auto capacity = static_cast<int64_t>(2 * pow(2, ceil(log2(7))) - 1);
    assert(capacity == 15);

    std::vector<int64_t> input{1, 2, 3, 4, 5, 6, 7}, pending(capacity),
        tree(capacity);
    buildTree(input, &tree, 0, 7 - 1, 0);

    assert(querySum(&tree, &pending, 1, 5, 0, 7 - 1, 0) == 2 + 3 + 4 + 5 + 6);

    addRange(&tree, &pending, 2, 4, 1, 0, 7 - 1, 0);
    assert(querySum(&tree, &pending, 1, 5, 0, 7 - 1, 0) == 2 + 4 + 5 + 6 + 6);

    addRange(&tree, &pending, 0, 6, -2, 0, 7 - 1, 0);
    assert(querySum(&tree, &pending, 0, 4, 0, 7 - 1, 0) == -1 + 0 + 2 + 3 + 4);
}

int main() {
    selfCheck();

    std::cout << "Enter number of elements: ";

    uint64_t count = 0;
    std::cin >> count;

    auto capacity = static_cast<uint64_t>(2 * pow(2, ceil(log2(count))) - 1);
    std::vector<int64_t> input(count), pending(capacity), tree(capacity);

    int choice = 0;
    std::cout << "\nDo you wish to enter each number?:\n"
                 "1: Yes\n"
                 "0: No (default initialize them to 0)\n";

    std::cin >> choice;
    if (choice == 1) {
        std::cout << "Enter " << count << " numbers:\n";
        for (int i = 1; i <= count; i++) {
            std::cout << i << ": ";
            std::cin >> input[i];
        }
    }

    buildTree(input, &tree, 0, count - 1, 0);

    do {
        std::cout << "\nMake your choice:\n"
                     "1: Range update (input)\n"
                     "2: Range query (output)\n"
                     "0: Exit\n";
        std::cin >> choice;

        if (choice == 1) {
            std::cout << "Enter 1-indexed lower bound, upper bound & value:\n";

            uint64_t from = 1, to = 1, value = 0;
            std::cin >> from >> to >> value;
            addRange(&tree, &pending, from - 1, to - 1, value, 0, count - 1, 0);
        } else if (choice == 2) {
            std::cout << "Enter 1-indexed lower bound & upper bound:\n";

            uint64_t from = 1, to = 1;
            std::cin >> from >> to;
            std::cout << querySum(&tree, &pending, from - 1, to - 1, 0,
                                   count - 1, 0);
            std::cout << "\n";
        }
    } while (choice > 0);

    return 0;
}

/**
 * @file sparse_table.cpp
 * @brief Implementation of [Sparse
 * Table](https://en.wikipedia.org/wiki/Range_minimum_query) data structure
 *
 * @details
 * Sparse Table is a data structure, that allows answering range queries.
 * It can answer most range queries in O(logn), but its true power is answering
 * range minimum queries or equivalent range maximum queries). For those queries
 * it can compute the answer in O(1) time.
 *
 * * Running Time Complexity \n
 * * Build : O(NlogN) \n
 * * Range Query : O(1) \n
 */

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace range_queries
 * @brief Range Queries algorithms
 */
namespace range_queries {
/**
 * @namespace sparse_table
 * @brief Range queries using sparse-tables
 */
namespace sparse_table {
/**
 * This function precomputes intial log table for further use.
 * @param n value of the size of the input array
 * @return corresponding vector of the log table
 */
template <typename T>
std::vector<T> computeLogs(const std::vector<T>& A) {
    int n = A.size();
    std::vector<T> logs(n);
    logs[1] = 0;
    for (int i = 2; i < n; i++) {
        logs[i] = logs[i / 2] + 1;
    }
    return logs;
}

/**
 * This functions builds the primary data structure sparse table
 * @param n value of the size of the input array
 * @param A array of the input integers
 * @param logs array of the log table
 * @return created sparse table data structure
 */
template <typename T>
std::vector<std::vector<T> > buildTable(const std::vector<T>& A,
                                        const std::vector<T>& logs) {
    int n = A.size();
    std::vector<std::vector<T> > table(20, std::vector<T>(n + 5, 0));
    int curLen = 0;
    for (int i = 0; i <= logs[n]; i++) {
        curLen = 1 << i;
        for (int j = 0; j + curLen < n; j++) {
            if (curLen == 1) {
                table[i][j] = A[j];
            } else {
                table[i][j] =
                    std::min(table[i - 1][j], table[i - 1][j + curLen / 2]);
            }
        }
    }
    return table;
}

/**
 * This function is the query function to get the range minimum value
 * @param beg beginning index of the query range
 * @param end ending index of the query range
 * @param logs array of the log table
 * @param table sparse table data structure for the input array
 * @return minimum value for the [beg, end] range for the input array
 */
template <typename T>
int getMinimum(int beg, int end, const std::vector<T>& logs,
               const std::vector<std::vector<T> >& table) {
    int p = logs[end - beg + 1];
    int pLen = 1 << p;
    return std::min(table[p][beg], table[p][end - pLen + 1]);
}
}  // namespace sparse_table
}  // namespace range_queries

/**
 * Main function
 */
int main() {
    std::vector<int> A{1, 2, 0, 3, 9};
    std::vector<int> logs = range_queries::sparse_table::computeLogs(A);
    std::vector<std::vector<int> > table =
        range_queries::sparse_table::buildTable(A, logs);
    assert(range_queries::sparse_table::getMinimum(0, 0, logs, table) == 1);
    assert(range_queries::sparse_table::getMinimum(0, 4, logs, table) == 0);
    assert(range_queries::sparse_table::getMinimum(2, 4, logs, table) == 0);
    return 0;
}

/**
 * @file sparse_table_range_queries.cpp
 * @brief Sparse table structure for O(1) range-minimum queries
 *
 * @details
 * A sparse table precomputes, for every power-of-two length, the minimum
 * over every window of that length. Because "minimum" is idempotent, two
 * overlapping precomputed windows can be combined to answer any range query
 * without recomputation.
 *
 * Complexity:
 *   Build:        O(n log n)
 *   Query:        O(1)
 */

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

/**
 * @namespace range_queries
 * @brief Range Queries algorithms
 */
namespace range_queries {

/**
 * @namespace sparse_table
 * @brief Range queries using sparse tables
 */
namespace sparse_table {

/**
 * @brief Builds a lookup table where entry i holds floor(log2(i)).
 * @param data the array we plan on querying (only its size matters here)
 * @return a vector such that result[i] == floor(log2(i))
 */
template <typename T>
std::vector<T> buildLogLookup(const std::vector<T>& data) {
    int count = data.size();
    std::vector<T> logLookup(count);
    logLookup[1] = 0;
    for (int i = 2; i < count; i++) {
        logLookup[i] = logLookup[i / 2] + 1;
    }
    return logLookup;
}

/**
 * @brief Constructs the sparse table itself.
 * @param data the source array
 * @param logLookup precomputed floor(log2(i)) values
 * @return a 2D table where table[k][i] holds the min over data[i..i+2^k-1]
 */
template <typename T>
std::vector<std::vector<T> > constructSparseTable(const std::vector<T>& data,
                                                    const std::vector<T>& logLookup) {
    int count = data.size();
    std::vector<std::vector<T> > table(20, std::vector<T>(count + 5, 0));
    int windowLen = 0;
    for (int level = 0; level <= logLookup[count]; level++) {
        windowLen = 1 << level;
        for (int start = 0; start + windowLen < count; start++) {
            if (windowLen == 1) {
                table[level][start] = data[start];
            } else {
                table[level][start] = std::min(table[level - 1][start],
                                                table[level - 1][start + windowLen / 2]);
            }
        }
    }
    return table;
}

/**
 * @brief Answers a range-minimum query using the prebuilt sparse table.
 * @param left inclusive left bound of the query
 * @param right inclusive right bound of the query
 * @param logLookup precomputed floor(log2(i)) values
 * @param table sparse table built by constructSparseTable
 * @return minimum element within data[left..right]
 */
template <typename T>
int queryMinimum(int left, int right, const std::vector<T>& logLookup,
                  const std::vector<std::vector<T> >& table) {
    int level = logLookup[right - left + 1];
    int windowLen = 1 << level;
    return std::min(table[level][left], table[level][right - windowLen + 1]);
}

}  // namespace sparse_table
}  // namespace range_queries

/**
 * Program entry point exercising the sparse table on a small example.
 */
int main() {
    std::vector<int> values{1, 2, 0, 3, 9};
    std::vector<int> logLookup = range_queries::sparse_table::buildLogLookup(values);
    std::vector<std::vector<int> > table =
        range_queries::sparse_table::constructSparseTable(values, logLookup);

    assert(range_queries::sparse_table::queryMinimum(0, 0, logLookup, table) == 1);
    assert(range_queries::sparse_table::queryMinimum(0, 4, logLookup, table) == 0);
    assert(range_queries::sparse_table::queryMinimum(2, 4, logLookup, table) == 0);
    return 0;
}

/******************************************************************************
 * @file
 * @brief [Binary search
 * algorithm](https://en.wikipedia.org/wiki/Binary_search_algorithm)
 * @details
 * Binary search is a search algorithm that finds the position of a target value
 * within a sorted array.Just like looking for a word in a dictionary, in binary search we compare the target value to the middle
 * element of the array. If they are not equal, then the half in which the target
 * cannot lie is eliminated and the search continues on the remaining half,
 * again taking the middle element to compare to the target value, and repeating
 * this until the target value is found. If the search ends with the remaining
 * half being empty, the target is not in the array.
 *
 * ### Implementation
 *
 * Binary search works on sorted arrays. It begins by comparing an
 * element in the middle of the array with the target value. If the target value
 * matches the element, its position in the array is returned. If the target
 * value is less than the element, the search continues in the lower half of
 * the array. If the target value is greater than the element, the search
 * continues in the upper half of the array. By doing this, the algorithm
 * eliminates the half in which the target value cannot lie in each iteration.
 *
 * ### Complexities
 *
 * //n is the number of element in the array.
 *
 * Worst-case time complexity	O(log n)
 * Best-case time complexity	O(1)
 * Average time complexity	    O(log n)
 * space complexity  0(1)
 * Worst-case space complexity  0(1)
 *
 * @author [Lajat Manekar](https://github.com/Lazeeez)
 * @author Unknown author
 *******************************************************************************/

#include <algorithm>  /// for std::sort function
#include <cassert>    /// for std::assert
#include <cstdint>
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector
/******************************************************************************
 * @namespace search
 * @brief Searching algorithms
 *******************************************************************************/
namespace search {

/******************************************************************************
 * @namespace binary_search
 * @brief Binary search searching algorihm
 *******************************************************************************/
namespace binary_search {

/******************************************************************************
 * @brief The main function which implements binary search
 * @param arr vector to be searched in
 * @param val value to be searched
 * @returns @param int index of val in vector arr
 *******************************************************************************/
uint64_t binarySearch(std::vector<uint64_t> arr, uint64_t val) {
    uint64_t low = 0;                // set the lowest point of the vector.
    uint64_t high = arr.size() - 1;  // set the highest point of the vector.

    while (low <= high) {
        uint64_t m = low + (high - low) / 2;  // set the pivot point

        if (val == arr[m]) {
            return m;
        } /****************************************************
           * if pivot point is the val, return it,
           * else check if val is greater or smaller than pivot value
           * and set the next pivot point accordingly.
           ****************************************************/
        else if (val < arr[m]) {
            high = m - 1;
        } else {
            low = m + 1;
        }
    }
    return -1;  // if val is not in the array, return -1.
}

}  // namespace binary_search

}  // namespace search

/*******************************************************************************
 * @brief Self-test implementation #1
 * @returns void
 *******************************************************************************/
static void test1() {
    // testcase #1
    // array = [1,3,5,7,9,8,6,4,2] , Value = 4
    // should return 3

    std::vector<uint64_t> arr = {{1, 3, 5, 7, 9, 8, 6, 4, 2}};
    std::sort(arr.begin(), arr.end());
    uint64_t expected_ans = 3;
    uint64_t derived_ans = search::binary_search::binarySearch(arr, 4);
    std::cout << "Test #1: ";
    assert(derived_ans == expected_ans);
    std::cout << "Passed!" << std::endl;
}

