/******************************************************************************
 * @file
 * @brief Classic binary search over a sorted vector
 * @details
 * Binary search locates a target inside a sorted collection by repeatedly
 * halving the region under consideration. At every step the middle element
 * is compared to the target: an exact match ends the search, a smaller
 * middle element discards the lower half, and a larger middle element
 * discards the upper half. When the region under consideration becomes
 * empty, the target does not exist in the collection.
 *
 * Complexity: O(log n) worst case, O(1) best case, O(1) extra space.
 *
 * Rewritten variant for educational dataset generation.
 ******************************************************************************/

#include <algorithm>  /// for std::sort
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>   /// for std::cout
#include <vector>     /// for std::vector

/******************************************************************************
 * @namespace search
 * @brief Searching algorithms
 ******************************************************************************/
namespace search {

/******************************************************************************
 * @namespace binary_search
 * @brief Binary search implementation
 ******************************************************************************/
namespace binary_search {

/******************************************************************************
 * @brief Locates `target` inside `sortedValues` using bisection.
 * @param sortedValues a vector already sorted in ascending order
 * @param target the value being searched for
 * @return the index of target if present, otherwise a sentinel of -1
 * (wrapped around due to the unsigned return type).
 ******************************************************************************/
uint64_t locate(std::vector<uint64_t> sortedValues, uint64_t target) {
    uint64_t lowBound = 0;
    uint64_t highBound = sortedValues.size() - 1;

    while (lowBound <= highBound) {
        uint64_t mid = lowBound + (highBound - lowBound) / 2;  // avoid overflow

        if (target == sortedValues[mid]) {
            return mid;
        } else if (target < sortedValues[mid]) {
            // target must live in the left half, discard the right half
            highBound = mid - 1;
        } else {
            // target must live in the right half, discard the left half
            lowBound = mid + 1;
        }
    }
    return -1;  // not present
}

}  // namespace binary_search

}  // namespace search

/*******************************************************************************
 * @brief First reworded regression check.
 *******************************************************************************/
static void verifyCaseOne() {
    // input: {1,3,5,7,9,8,6,4,2} sorted, looking for 4 -> expect index 3
    std::vector<uint64_t> values = {{1, 3, 5, 7, 9, 8, 6, 4, 2}};
    std::sort(values.begin(), values.end());
    uint64_t expected = 3;
    uint64_t got = search::binary_search::locate(values, 4);
    std::cout << "Check #1: ";
    assert(got == expected);
    std::cout << "Passed!" << std::endl;
}

/*******************************************************************************
 * @brief Second reworded regression check.
 *******************************************************************************/
void verifyCaseTwo() {
    // input: {1,23,25,4,2} sorted, looking for 25 -> expect index 4
    std::vector<uint64_t> values = {{1, 23, 25, 4, 2}};
    std::sort(values.begin(), values.end());
    uint64_t expected = 4;
    uint64_t got = search::binary_search::locate(values, 25);
    std::cout << "Check #2: ";
    assert(got == expected);
    std::cout << "Passed!" << std::endl;
}

/*******************************************************************************
 * @brief Third reworded regression check.
 *******************************************************************************/
void verifyCaseThree() {
    // sorted mix of duplicates and larger values, looking for 31 -> expect index 8
    std::vector<uint64_t> values = {{1, 31, 231, 12, 2, 5, 51, 21, 23, 12, 3}};
    std::sort(values.begin(), values.end());
    uint64_t expected = 8;
    uint64_t got = search::binary_search::locate(values, 31);
    std::cout << "Check #3: ";
    assert(got == expected);
    std::cout << "Passed!" << std::endl;
}

/*******************************************************************************
 * @brief Program entry point.
 * @returns 0 on exit
 *******************************************************************************/
int main() {
    verifyCaseOne();
    verifyCaseTwo();
    verifyCaseThree();

    return 0;
}

/**
 * \file
 * \brief [Exponential search
 * algorithm](https://en.wikipedia.org/wiki/Exponential_search)
 * \copyright 2020 Divide-et-impera-11
 *
 * The algorithm try to search the range where the key should be.
 * If it has been found we do a binary search there.
 * The range of the search grows by exponential every time.
 * If the key is larger than the last element of array, the start of
 * block(block_front) will be equal to the end of block(block_size) and the
 * algorithm return null ponter, every other cases the algoritm return fom the
 * loop.
 */
#include <cassert>
#include <cmath>
#include <cstdint>
#ifdef _MSC_VER
#include <string>  // use for MS Visual C++
#else
#include <cstring>  // for all other compilers
#endif

/** Binary Search Algorithm (used by ::struzik_search)\n
 * * Time Complexity O(log n) where 'n' is the number of elements
 * * Worst Time Complexity O(log n)
 * * Best Time Complexity Ω(1)
 * * Space Complexity O(1)
 * * Auxiliary Space Complexity O(1)
 * \returns pointer to value in the array
 * \returns `nullptr` if value not found
 */
template <class Type>
inline Type* binary_s(Type* array, size_t size, Type key) {
    int32_t lower_index(0), upper_index(size - 1), middle_index;

    while (lower_index <= upper_index) {
        middle_index = std::floor((lower_index + upper_index) / 2);

        if (*(array + middle_index) < key)
            lower_index = (middle_index + 1);
        else if (*(array + middle_index) > key)
            upper_index = (middle_index - 1);
        else
            return (array + middle_index);
    }

    return nullptr;
}

/** Struzik Search Algorithm(Exponential)
 * * Time Complexity O(log i) where i is the position of search key in the list
 * * Worst Time Complexity O(log i)
 * * Best Time Complexity Ω(1)
 * * Space Complexity O(1)
 * * Auxiliary Space Complexity O(1)
 */
template <class Type>
Type* struzik_search(Type* array, size_t size, Type key) {
    uint32_t block_front(0), block_size = size == 0 ? 0 : 1;
    while (block_front != block_size) {
        if (*(array + block_size - 1) < key) {
            block_front = block_size;
            (block_size * 2 - 1 < size) ? (block_size *= 2) : block_size = size;
            continue;
        }
        return binary_s<Type>(array + block_front, (block_size - block_front),
                              key);
    }
    return nullptr;
}

/** Main function */
int main() {
    // TEST CASES
    int* sorted_array = new int[7]{7, 10, 15, 23, 70, 105, 203};
    assert(struzik_search<int>(sorted_array, 7, 0) == nullptr);
    assert(struzik_search<int>(sorted_array, 7, 1000) == nullptr);
    assert(struzik_search<int>(sorted_array, 7, 50) == nullptr);
    assert(struzik_search<int>(sorted_array, 7, 7) == sorted_array);
    // TEST CASES
    delete[] sorted_array;
    return 0;
}

/**
 * \file
 * \brief Exponential search: locate a range via doubling, then bisect it
 *
 * The algorithm grows a candidate window exponentially (1, 2, 4, 8, ...)
 * until it either overshoots the key or reaches the end of the array. Once
 * the window is known to bracket the key (or the array is exhausted), an
 * ordinary binary search is run inside that window. This gives good
 * performance when the key tends to be near the front of the array.
 */
#include <cassert>
#include <cmath>
#include <cstdint>
#ifdef _MSC_VER
#include <string>  // MSVC needs this instead of cstring
#else
#include <cstring>  // every other compiler
#endif

/**
 * @brief Plain binary search over a raw pointer range, used as the final
 * step once exponential_probe() has located a bracketing window.
 * Time complexity: O(log n) worst case, O(1) best case.
 * @return pointer to the matching element, or nullptr if absent.
 */
template <class Elem>
inline Elem* bisect_range(Elem* data, size_t count, Elem key) {
    int32_t lo(0), hi(count - 1), mid;

    while (lo <= hi) {
        mid = std::floor((lo + hi) / 2);

        if (*(data + mid) < key)
            lo = mid + 1;
        else if (*(data + mid) > key)
            hi = mid - 1;
        else
            return (data + mid);
    }

    return nullptr;
}

/**
 * @brief Exponential (a.k.a. Struzik) search.
 * Grows the probe window geometrically, then delegates to bisect_range().
 * Time complexity: O(log i), where i is the position of the key.
 */
template <class Elem>
Elem* exponential_probe(Elem* data, size_t count, Elem key) {
    uint32_t windowStart(0), windowEnd = count == 0 ? 0 : 1;
    while (windowStart != windowEnd) {
        if (*(data + windowEnd - 1) < key) {
            windowStart = windowEnd;
            (windowEnd * 2 - 1 < count) ? (windowEnd *= 2) : windowEnd = count;
            continue;
        }
        return bisect_range<Elem>(data + windowStart, (windowEnd - windowStart), key);
    }
    return nullptr;
}

/** Program entry point running a few reworded checks. */
int main() {
    // sorted sample data + assorted lookups
    int* sample = new int[7]{7, 10, 15, 23, 70, 105, 203};
    assert(exponential_probe<int>(sample, 7, 0) == nullptr);
    assert(exponential_probe<int>(sample, 7, 1000) == nullptr);
    assert(exponential_probe<int>(sample, 7, 50) == nullptr);
    assert(exponential_probe<int>(sample, 7, 7) == sample);
    delete[] sample;
    return 0;
}

/**
 * @author sprintyaf
 * @file fibonacci_search.cpp
 * @brief [Fibonacci search
 * algorithm](https://en.wikipedia.org/wiki/Fibonacci_search_technique)
 */

#include <iostream>
#include <vector> // for std::vector class
#include <cassert> // for assert
#include <cstdlib> // for random numbers
#include <algorithm> // for sorting



/**
 * @brief using fibonacci search algorithm finds an index of a given element in a sorted array
 * 
 * @param arr sorted array
 * @param value value that we're looking for
 * @returns if the array contains the value, returns an index of the element. otherwise -1.
 */
int fibonacci_search(const std::vector<int> &arr, int value){
    // initialize last and current members of Fibonacci sequence 
    int last = 0, current = 1;
    int length = arr.size(); // array size
    // next member of Fibonacci sequence which is "last" + "current"
    int next = last + current; 

    // "next" will store the smallest Fibonacci number greater or equal to "length"
    while(next < length){
        last = current;
        current = next;
        next = last + current;
    }

    // "offset" is the end of eliminated range from front
    int offset = -1, index;
    // while loop until there are elements left to consider.
    // when "next" becomes 1, last is equal to 0, so search is done,
    // because arr[offset] will already be eliminated
    while(next > 1){
        // check if "last" is valid location
        index = std::min(offset + last, length-1);
        // if value is greater than the value at "index", eliminate the subarray from offset to index
        if(arr[index] < value){
            next = current;
            current = last;
            last = next - current;
            offset = index;
        // if value is less than the value at "index", eliminate the subarray after index+1
        } else if(arr[index] > value){
            next = last;
            current = current - last;
            last = next - current;
        // element is found
        } else {
            return index;
        }
    }
    // comparing the last element
    if(current && !arr.empty() && arr[offset+1] == value){
        return offset+1;
    }
    // value was not found, return -1
    return -1;
}

/**
 * @brief random tests for checking performance when an array doesn't contain an element
*/
bool no_occurence_tests(){
    bool passed = true;
    int rand_num, rand_value, index, num_tests = 1000;
    std::vector<int> arr;
    while(num_tests--){
        arr.clear();
        for(int i = 0; i < 100; i++){
            rand_num = std::rand() % 1000;
            arr.push_back(rand_num);
        }
        rand_value = std::rand() % 1000;
        while(std::find(arr.begin(), arr.end(), rand_value) != arr.end()){
            std::remove(arr.begin(), arr.end(), rand_value);
        }
        sort(arr.begin(), arr.end());
        index = fibonacci_search(arr, rand_value);
        passed = passed && (index == -1);
    }
    return passed;
}

/**
 * @brief random tests which cover cases when we have one, multiple or zero occurences of the value we're looking for
*/
bool random_tests(){
    bool passed = true;
    int rand_num, rand_value, index, real_value, num_tests = 10000;
    std::vector<int> arr;
    while(num_tests--){
        arr.clear();
        for(int i = 0; i < 100; i++){
            rand_num = std::rand() % 1000;
            arr.push_back(rand_num);
        }
        rand_value = std::rand() % 1000;
        std::sort(arr.begin(), arr.end());
        index = fibonacci_search(arr, rand_value);
        if(index != -1){
            real_value = arr[index];
            passed = passed && (real_value == rand_value);
        } else {
            passed = passed && (std::find(arr.begin(), arr.end(), rand_value) == arr.end());
        }
    }
    return passed;
}

/**
 * Main Function
 * testing the algorithm
 */
int main() {
    assert(no_occurence_tests());
    assert(random_tests());
    return 0;
}

/**
 * @file fibonacci_search.cpp
 * @brief Fibonacci search over a sorted array
 * @details
 * Instead of splitting the search interval in half like binary search,
 * Fibonacci search splits it according to consecutive Fibonacci numbers.
 * This can be handy on architectures where division is expensive since the
 * algorithm only needs addition and subtraction to advance.
 *
 * Rewritten variant for educational dataset generation.
 */

#include <iostream>
#include <vector>    // for std::vector
#include <cassert>   // for assert
#include <cstdlib>   // for random number generation
#include <algorithm> // for std::sort / std::find

/**
 * @brief Finds `target` in a sorted array using Fibonacci search.
 *
 * @param sortedArr array assumed to be sorted ascending
 * @param target value being searched for
 * @return index of target if present, otherwise -1
 */
int fibonacciLookup(const std::vector<int> &sortedArr, int target) {
    // fibPrev2/fibPrev1 track the two previous Fibonacci numbers,
    // fibCurrent is their sum (the smallest Fibonacci >= array length)
    int fibPrev2 = 0, fibPrev1 = 1;
    int n = sortedArr.size();
    int fibCurrent = fibPrev2 + fibPrev1;

    while (fibCurrent < n) {
        fibPrev2 = fibPrev1;
        fibPrev1 = fibCurrent;
        fibCurrent = fibPrev2 + fibPrev1;
    }

    // marks the boundary of the portion of the array already ruled out
    int excludedUpTo = -1;
    int probe;

    while (fibCurrent > 1) {
        probe = std::min(excludedUpTo + fibPrev2, n - 1);

        if (sortedArr[probe] < target) {
            // discard everything up to and including probe
            fibCurrent = fibPrev1;
            fibPrev1 = fibPrev2;
            fibPrev2 = fibCurrent - fibPrev1;
            excludedUpTo = probe;
        } else if (sortedArr[probe] > target) {
            // discard everything after probe
            fibCurrent = fibPrev2;
            fibPrev1 = fibPrev1 - fibPrev2;
            fibPrev2 = fibCurrent - fibPrev1;
        } else {
            return probe;
        }
    }

    // only one element may remain uncompared; check it explicitly
    if (fibPrev1 && !sortedArr.empty() && sortedArr[excludedUpTo + 1] == target) {
        return excludedUpTo + 1;
    }
    return -1;
}

/**
 * @brief Randomized regression: confirms -1 is returned for absent values.
 */
bool checkAbsentValues() {
    bool ok = true;
    int sample, missingValue, foundIdx, trials = 1000;
    std::vector<int> data;
    while (trials--) {
        data.clear();
        for (int i = 0; i < 100; i++) {
            sample = std::rand() % 1000;
            data.push_back(sample);
        }
        missingValue = std::rand() % 1000;
        while (std::find(data.begin(), data.end(), missingValue) != data.end()) {
            std::remove(data.begin(), data.end(), missingValue);
        }
        sort(data.begin(), data.end());
        foundIdx = fibonacciLookup(data, missingValue);
        ok = ok && (foundIdx == -1);
    }
    return ok;
}

/**
 * @brief Randomized regression covering present/absent/duplicate cases.
 */
bool checkGeneralCases() {
    bool ok = true;
    int sample, target, foundIdx, foundValue, trials = 10000;
    std::vector<int> data;
    while (trials--) {
        data.clear();
        for (int i = 0; i < 100; i++) {
            sample = std::rand() % 1000;
            data.push_back(sample);
        }
        target = std::rand() % 1000;
        std::sort(data.begin(), data.end());
        foundIdx = fibonacciLookup(data, target);
        if (foundIdx != -1) {
            foundValue = data[foundIdx];
            ok = ok && (foundValue == target);
        } else {
            ok = ok && (std::find(data.begin(), data.end(), target) == data.end());
        }
    }
    return ok;
}

/**
 * Program entry point running the reworded regression checks.
 */
int main() {
    assert(checkAbsentValues());
    assert(checkGeneralCases());
    return 0;
}

/**
 * @file
 * @brief Implementation of [Floyd's Cycle
 * Detection](https://en.wikipedia.org/wiki/Cycle_detection) algorithm
 * @details
 * Given an array of integers containing 'n + 1' integers, where each
 * integer is in the range [1, n] inclusive. If there is only one duplicate
 * number in the input array, this algorithm returns the duplicate number in
 * O(1) space and the time complexity is less than O(n^2) without modifying the
 * original array, otherwise, it returns -1.
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector
/**
 * @namespace search
 * @brief Search algorithms
 */
namespace search {
/**
 * @namespace cycle_detection
 * @brief Functions for the [Floyd's Cycle
 * Detection](https://en.wikipedia.org/wiki/Cycle_detection) algorithm
 */
namespace cycle_detection {
/**
 * @brief The main function implements search algorithm
 * @tparam T type of array
 * @param in_arr the input array
 * @param n size of array
 * @returns the duplicate number
 */
template <typename T>
int32_t duplicateNumber(const std::vector<T> &in_arr, const uint32_t &n) {
    if (n == 0 ||
        n == 1) {  // to find duplicate in an array its size should be atleast 2
        return -1;
    }
    uint32_t tortoise = in_arr[0];  // variable tortoise is used for the longer
                                    // jumps in the array
    uint32_t hare =
        in_arr[0];  // variable hare is used for shorter jumps in the array
    do {
        tortoise = in_arr[tortoise];
        hare = in_arr[in_arr[hare]];
    } while (tortoise != hare);
    tortoise = in_arr[0];
    while (tortoise != hare) {
        tortoise = in_arr[tortoise];
        hare = in_arr[hare];
    }
    return tortoise;
}
}  // namespace cycle_detection
}  // namespace search

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // 1st test
    // [3, 4, 8, 5, 9, 1, 2, 6, 7, 4] return 4
    std::vector<uint32_t> array1 = {3, 4, 8, 5, 9, 1, 2, 6, 7, 4};
    std::cout << "Test 1... ";
    assert(search::cycle_detection::duplicateNumber(array1, array1.size()) ==
           4);  // here the duplicate number is 4
    std::cout << "passed" << std::endl;

    // 2nd test
    // [1, 2, 3, 4, 2] return 2
    std::vector<uint32_t> array2 = {1, 2, 3, 4, 2};
    std::cout << "Test 2... ";
    assert(search::cycle_detection::duplicateNumber(array2, array2.size()) ==
           2);  // here the duplicate number is 2
    std::cout << "passed" << std::endl;

    // 3rd test
    // [] return -1
    std::vector<uint32_t> array3 = {};
    std::cout << "Test 3... ";
    assert(search::cycle_detection::duplicateNumber(array3, array3.size()) ==
           -1);  // since the input array is empty no duplicate number exists in
                 // this case
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Duplicate detection using Floyd's tortoise-and-hare cycle finding
 * @details
 * Given an array of n+1 integers where every value lies in [1, n], treating
 * the array as a "next pointer" function (index i points to in_arr[i])
 * necessarily creates a cycle, because at least one value repeats. Floyd's
 * algorithm finds the entry point of that cycle, which corresponds exactly
 * to the duplicated value, in O(n) time and O(1) extra space, without
 * mutating the input.
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for std::cout
#include <vector>    /// for std::vector

/**
 * @namespace search
 * @brief Search algorithms
 */
namespace search {

/**
 * @namespace cycle_detection
 * @brief Floyd's tortoise-and-hare cycle detection
 */
namespace cycle_detection {

/**
 * @brief Finds the single duplicated value in `values` (if one exists).
 * @tparam T element type of the input array
 * @param values the input array, values in [1, n], length n+1
 * @param count number of elements in `values`
 * @return the duplicate value, or -1 if there are fewer than 2 elements
 */
template <typename T>
int32_t findRepeatedValue(const std::vector<T> &values, const uint32_t &count) {
    if (count == 0 || count == 1) {
        // need at least two elements for a duplicate to even be possible
        return -1;
    }

    uint32_t slow = values[0];  // advances one hop per iteration
    uint32_t fast = values[0];  // advances two hops per iteration

    do {
        slow = values[slow];
        fast = values[values[fast]];
    } while (slow != fast);

    // second phase: find the entry point of the cycle
    slow = values[0];
    while (slow != fast) {
        slow = values[slow];
        fast = values[fast];
    }
    return slow;
}

}  // namespace cycle_detection
}  // namespace search

/**
 * @brief Reworded self-test suite.
 */
static void runChecks() {
    // duplicate is 4
    std::vector<uint32_t> caseA = {3, 4, 8, 5, 9, 1, 2, 6, 7, 4};
    std::cout << "Check 1... ";
    assert(search::cycle_detection::findRepeatedValue(caseA, caseA.size()) == 4);
    std::cout << "passed" << std::endl;

    // duplicate is 2
    std::vector<uint32_t> caseB = {1, 2, 3, 4, 2};
    std::cout << "Check 2... ";
    assert(search::cycle_detection::findRepeatedValue(caseB, caseB.size()) == 2);
    std::cout << "passed" << std::endl;

    // empty array -> no duplicate possible
    std::vector<uint32_t> caseC = {};
    std::cout << "Check 3... ";
    assert(search::cycle_detection::findRepeatedValue(caseC, caseC.size()) == -1);
    std::cout << "passed" << std::endl;
}

/**
 * @brief Program entry point.
 * @return 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * \file
 * \brief Hash Search Algorithm - Best Time Complexity Ω(1)
 *
 * \copyright 2020 Arctic2333
 *
 * In this algorithm, we use the method of division and reservation remainder to
 * construct the hash function, and use the method of chain address to solve the
 * conflict, that is, we link a chain list after the data, and store all the
 * records whose keywords are synonyms in the same linear chain list.
 *
 * @warning This program is only for educational purposes. It has serious flaws
 * in implementation with regards to memory management resulting in large
 * amounts of memory leaks.
 * @todo fix the program for memory leaks and better structure in C++ and not C
 * fashion
 */
#include <cstdlib>
#include <iostream>

#define MAX 6      ///< Determines how much data
#define HASHMAX 5  ///< Determines the length of the hash table

int data[MAX] = {1, 10, 15, 5, 8, 7};  //!< test data

/**
 * a one-way linked list
 */
typedef struct list {
    int key;            //!< key value for node
    struct list* next;  //!< pointer to next link in the chain
} node,                 /**< define node as one item list */
    *link;              ///< pointer to nodes

node hashtab[HASHMAX];  ///< array of nodes

// int counter = 1;

/**
 * Mode of hash detection :
 * Division method
 * \param [in] key to hash
 * \returns hash value for `key`
 */
int h(int key) { return key % HASHMAX; }

/**
 * The same after the remainder will be added after the same hash header
 * To avoid conflict, zipper method is used
 * Insert elements into the linked list in the header
 * \param [in] key key to add to list
 * \warning dynamic memory allocated to `n` never gets freed.
 * \todo fix memory leak
 */
void create_list(int key) {  // Construct hash table
    link p, n;
    int index;
    n = (link)malloc(sizeof(node));
    n->key = key;
    n->next = NULL;
    index = h(key);
    p = hashtab[index].next;
    if (p != NULL) {
        n->next = p;
        hashtab[index].next = n;
    } else {
        hashtab[index].next = n;
    }
}

/**
 * Input the key to be searched, and get the hash header position through the H
 * (int key) function, then one-dimensional linear search. If found @return
 * element depth and number of searches If not found @return -1
 */
int hash_search(int key, int* counter) {  // Hash lookup function
    link pointer;
    int index;

    *counter = 0;
    index = h(key);
    pointer = hashtab[index].next;

    std::cout << "data[" << index << "]:";

    while (pointer != NULL) {
        counter[0]++;
        std::cout << "data[" << pointer->key << "]:";
        if (pointer->key == key)
            return 1;
        else
            pointer = pointer->next;
    }

    return 0;
}

/** main function */
int main() {
    link p;
    int key = 0, index, i, counter;  // Key is the value to be found
    index = 0;

    // You can write the input mode here
    while (index < MAX) {  // Construct hash table
        create_list(data[index]);
        index++;
    }

    for (i = 0; i < HASHMAX; i++) {  // Output hash table
        std::cout << "hashtab [" << i << "]\n";

        p = hashtab[i].next;

        while (p != NULL) {
