}

/**
 * \file
 * \brief Hash table search using separate chaining
 *
 * \copyright rewritten educational variant
 *
 * This demonstrates a simple hash table built with the division method
 * (key % table size) for hashing, resolving collisions via separate
 * chaining: each bucket is the head of a singly linked list of entries that
 * hashed to the same slot.
 *
 * @warning Educational example only; the linked list nodes allocated with
 * malloc() are intentionally never freed, mirroring the original sample's
 * simplistic memory handling.
 */
#include <cstdlib>
#include <iostream>

#define ITEM_COUNT 6    ///< number of records to insert
#define BUCKET_COUNT 5  ///< number of buckets in the hash table

int sampleRecords[ITEM_COUNT] = {1, 10, 15, 5, 8, 7};  //!< records to insert

/**
 * A single node in a bucket's chain.
 */
typedef struct entry {
    int key;             //!< the stored key
    struct entry* next;  //!< next node in the same bucket's chain
} entry_t, *entry_ptr;

entry_t buckets[BUCKET_COUNT];  ///< array of bucket head sentinels

/**
 * Computes the bucket index for a key via the division method.
 * \param key value being hashed
 * \returns bucket index in [0, BUCKET_COUNT)
 */
int bucketIndexOf(int key) { return key % BUCKET_COUNT; }

/**
 * Inserts `key` at the front of its bucket's chain.
 * \param key the key to insert
 * \warning the allocated node is never released (deliberately, for
 * simplicity of this educational example).
 */
void insertKey(int key) {
    entry_ptr newNode;
    int idx;

    newNode = (entry_ptr)malloc(sizeof(entry_t));
    newNode->key = key;
    newNode->next = NULL;

    idx = bucketIndexOf(key);
    entry_ptr existingHead = buckets[idx].next;
    newNode->next = existingHead;
    buckets[idx].next = newNode;
}

/**
 * Searches for `key`, walking the chain in its bucket.
 * Reports the number of comparisons made through `steps`.
 * \returns 1 if found, 0 otherwise
 */
int lookupKey(int key, int* steps) {
    entry_ptr cursor;
    int idx;

    *steps = 0;
    idx = bucketIndexOf(key);
    cursor = buckets[idx].next;

    std::cout << "data[" << idx << "]:";

    while (cursor != NULL) {
        steps[0]++;
        std::cout << "data[" << cursor->key << "]:";
        if (cursor->key == key) {
            return 1;
        }
        cursor = cursor->next;
    }

    return 0;
}

/** Program entry point demonstrating build + lookup. */
int main() {
    entry_ptr cursor;
    int key = 0, idx, i, steps;

    idx = 0;
    while (idx < ITEM_COUNT) {
        insertKey(sampleRecords[idx]);
        idx++;
    }

    for (i = 0; i < BUCKET_COUNT; i++) {
        std::cout << "hashtab [" << i << "]\n";

        cursor = buckets[i].next;
        while (cursor != NULL) {
            std::cout << "please int key:";
            if (cursor->key > 0) {
                std::cout << "[" << cursor->key << "]";
            }
            cursor = cursor->next;
        }
        std::cout << std::endl;
    }

    while (key != -1) {
        key = 10;  // fixed demo lookup value
        if (lookupKey(key, &steps)) {
            std::cout << "search time = " << steps << std::endl;
        } else {
            std::cout << "no found!\n";
        }
        key = -1;  // stop after one demo lookup
    }

    return 0;
}

/******************************************************************************
 * @file
 * @brief [Interpolation search
 * algorithm](https://en.wikipedia.org/wiki/interpolation_search)
 *
 * @details
 * interpolation search resembles the method by which people search a telephone
 * directory for a name (the key value by which the book's entries are ordered):
 * in each step the algorithm calculates where in the remaining search space
 * the sought item might be, based on the key values at the bounds of the search
 * space and the value of the sought key, usually via a linear interpolation.
 * The key value actually found at this estimated position is then compared to
 * the key value being sought. If it is not equal, then depending on the
 * comparison, the remaining search space is reduced to the part before or
 * after the estimated position. This method will only work if calculations
 * on the size of differences between key values are sensible.

 * ### Complexities
 *
 * //n is the number of element in the array.
 *
 * Worst-case time complexity	O(n)                (when items are distributed
 exponentially)
 * Average time complexity	    O(log2(log2 n))
 * space complexity  0(1)
 *
 * @author [Lajat Manekar](https://github.com/Lazeeez)
 * @author Unknown author
 *******************************************************************************/

#include <algorithm>  /// for std::sort function
#include <cassert>    /// for std::assert
#include <cstdint>
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/******************************************************************************
 * @namespace search
 * @brief Searching algorithms
 *******************************************************************************/
namespace search {

/******************************************************************************
 * @namespace interpolation_search
 * @brief Functions for the [Interpolation
 *Search](https://en.wikipedia.org/wiki/interpolation_search) algorithm
 *implementation
 *******************************************************************************/
namespace interpolation_search {

/******************************************************************************
 * @brief The main function which implements interpolation search
 * @param arr vector to be searched in
 * @param number value to be searched
 * @returns integer index of `number` in vector `arr`
 *******************************************************************************/
uint64_t interpolationSearch(const std::vector<uint64_t> &arr,
                             uint64_t number) {
    uint64_t size = arr.size();
    uint64_t low = 0, high = (size - 1);

    // Since vector is sorted, an element present in array must be in range
    // defined by corner
    while (low <= high && number >= arr[low] && number <= arr[high]) {
        if (low == high) {
            if (arr[low] == number) {
                return low;
            }
            return -1;
        }
        // Probing the position with keeping uniform distribution in mind.
        uint64_t pos =
            low +
            ((static_cast<uint64_t>(high - low) / (arr[high] - arr[low])) *
             (number - arr[low]));

        if (arr[pos] == number) {
            return pos;  // Condition of target found
        }

        if (arr[pos] < number) {
            low = pos + 1;  // If x is larger, x is in upper part
        }

        else {
            high = pos - 1;  // If x is smaller, x is in the lower part
        }
    }
    return -1;
}

}  // namespace interpolation_search

}  // namespace search

