/**
 * \file
 * \brief Straightforward linear (sequential) search
 *
 * Checks every element in order until a match is found or the array is
 * exhausted. No assumption about ordering is required, unlike binary or
 * interpolation search, at the cost of O(n) worst-case time.
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout / std::cin

/**
 * \brief Scans `data` from front to back looking for `needle`.
 * \param [in] data pointer to the array to scan
 * \param [in] length number of elements in the array
 * \param [in] needle value being searched for
 * \returns index of the first matching element
 * \returns -1 if no element matches
 */
int sequentialScan(int *data, int length, int needle) {
    for (int i = 0; i < length; ++i) {
        if (data[i] == needle) {
            return i;
        }
    }

    // fell through the whole array without a match
    return -1;
}

/**
 * @brief Reworded self-test suite.
 * @returns void
 */
static void runSelfTests() {
    int len = 4;
    int *nums = new int[len];
    for (int i = 0; i < len; i++) {
        nums[i] = i;
    }

    assert(sequentialScan(nums, len, 0) == 0);
    assert(sequentialScan(nums, len, 1) == 1);
    assert(sequentialScan(nums, len, 2) == 2);

    delete[] nums;

    len = 6;
    nums = new int[len];
    for (int i = 0; i < len; i++) {
        nums[i] = i;
    }

    assert(sequentialScan(nums, len, 3) == 3);
    assert(sequentialScan(nums, len, 1) == 1);
    assert(sequentialScan(nums, len, 5) == 5);

    std::cout << "All self-tests passed without issue!\n";
    delete[] nums;
}

