/**
 * @file
 * @brief find the length of the Longest Increasing Subsequence (LIS)
 * using [Binary Search](https://en.wikipedia.org/wiki/Longest_increasing_subsequence)
 * @details
 * Given an integer array nums, return the length of the longest strictly
 * increasing subsequence.
 * The longest increasing subsequence is described as a subsequence of an array
 * where: All elements of the subsequence are in increasing order. This subsequence
 * itself is of the longest length possible.

 * For solving this problem we have Three Approaches :-

 * Approach 1 :- Using Brute Force
 * The first approach that came to your mind is the Brute Force approach where we
 * generate all subsequences and then manually filter the subsequences whose
 * elements come in increasing order and then return the longest such subsequence.
 * Time Complexity :- O(2^n)
 * It's time complexity is exponential. Therefore we will try some other
 * approaches.

 * Approach 2 :- Using Dynamic Programming
 * To generate all subsequences we will use recursion and in the recursive logic we
 * will figure out a way to solve this problem. Recursive Logic to solve this
 * problem:-
 * 1. We only consider the element in the subsequence if the element is grater then
 * the last element present in the subsequence
 * 2. When we consider the element we will increase the length of subsequence by 1
 * Time Complexity: O(N*N)
 * Space Complexity: O(N*N) + O(N)

 * This approach is better then the previous Brute Force approach so, we can
 * consider this approach.

 * But when the Constraints for the problem is very larger then this approach fails

 * Approach 3 :- Using Binary Search
 * Other approaches use additional space to create a new subsequence Array.
 * Instead, this solution uses the existing nums Array to build the subsequence
 * array. We can do this because the length of the subsequence array will never be
 * longer than the current index.

 * Time complexity: O(n∗log(n))
 * Space complexity: O(1)

 * This approach consider Most optimal Approach for solving this problem

 * @author [Naman Jain](https://github.com/namanmodi65)
 */

#include <cassert>   /// for std::assert
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector
#include <algorithm> /// for std::lower_bound
#include <cstdint>   /// for std::uint32_t

/**
 * @brief Function to find the length of the Longest Increasing Subsequence (LIS)
 * using Binary Search
 * @tparam T The type of the elements in the input vector
 * @param nums The input vector of elements of type T
 * @return The length of the longest increasing subsequence
 */
template <typename T>
std::uint32_t longest_increasing_subsequence_using_binary_search(std::vector<T>& nums) {
    if (nums.empty()) return 0;

    std::vector<T> ans;
    ans.push_back(nums[0]);
    for (std::size_t i = 1; i < nums.size(); i++) {
        if (nums[i] > ans.back()) {
            ans.push_back(nums[i]);
        } else {
            auto idx = std::lower_bound(ans.begin(), ans.end(), nums[i]) - ans.begin();
            ans[idx] = nums[i];
        }
    }
    return static_cast<std::uint32_t>(ans.size());
}

/**
 * @brief Test cases for Longest Increasing Subsequence function
 * @returns void
 */
static void tests() {
    std::vector<int> arr = {10, 9, 2, 5, 3, 7, 101, 18};
    assert(longest_increasing_subsequence_using_binary_search(arr) == 4);

    std::vector<int> arr2 = {0, 1, 0, 3, 2, 3};
    assert(longest_increasing_subsequence_using_binary_search(arr2) == 4);

    std::vector<int> arr3 = {7, 7, 7, 7, 7, 7, 7};
    assert(longest_increasing_subsequence_using_binary_search(arr3) == 1);

    std::vector<int> arr4 = {-10, -1, -5, 0, 5, 1, 2};
    assert(longest_increasing_subsequence_using_binary_search(arr4) == 5);

    std::vector<double> arr5 = {3.5, 1.2, 2.8, 3.1, 4.0};
    assert(longest_increasing_subsequence_using_binary_search(arr5) == 4);

    std::vector<char> arr6 = {'a', 'b', 'c', 'a', 'd'};
    assert(longest_increasing_subsequence_using_binary_search(arr6) == 4);

    std::vector<int> arr7 = {};
    assert(longest_increasing_subsequence_using_binary_search(arr7) == 0);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function to run tests
 * @returns 0 on exit
 */
int main() {
    tests();  // run self test implementation
    return 0;
}

/**
 * @file
 * @brief Length of the Longest Increasing Subsequence (LIS) via patience
 * sorting / binary search
 * @details
 * Given a sequence, the LIS is the longest subsequence (not necessarily
 * contiguous) whose elements are strictly increasing.
 *
 * Three well-known strategies exist:
 *   1. Brute force: enumerate every subsequence - O(2^n), impractical.
 *   2. Dynamic programming: O(n^2) time, tracking the best subsequence
 *      ending at each index.
 *   3. Patience-sorting with binary search: maintain a "tails" array where
 *      tails[k] is the smallest possible tail value of an increasing
 *      subsequence of length k+1. Each new element either extends the tails
 *      array or replaces the first tail that is >= it (found via binary
 *      search). The final size of tails is the LIS length.
 *      Time: O(n log n), Space: O(n) for the tails array.
 *
 * This file implements approach 3.
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout
#include <vector>    /// for std::vector
#include <algorithm> /// for std::lower_bound
#include <cstdint>   /// for std::uint32_t

/**
 * @brief Computes the length of the longest strictly increasing subsequence.
 * @tparam T element type stored in the sequence
 * @param sequence input values (unmodified logically, only scanned)
 * @return length of the longest increasing subsequence
 */
template <typename T>
std::uint32_t lisLengthViaBisection(std::vector<T>& sequence) {
    if (sequence.empty()) return 0;

    std::vector<T> tails;
    tails.push_back(sequence[0]);
    for (std::size_t i = 1; i < sequence.size(); i++) {
        if (sequence[i] > tails.back()) {
            tails.push_back(sequence[i]);
        } else {
            auto pos = std::lower_bound(tails.begin(), tails.end(), sequence[i]) - tails.begin();
            tails[pos] = sequence[i];
        }
    }
    return static_cast<std::uint32_t>(tails.size());
}

/**
 * @brief Reworded regression suite covering several data types/edge cases.
 * @returns void
 */
static void runChecks() {
    std::vector<int> caseA = {10, 9, 2, 5, 3, 7, 101, 18};
    assert(lisLengthViaBisection(caseA) == 4);

    std::vector<int> caseB = {0, 1, 0, 3, 2, 3};
    assert(lisLengthViaBisection(caseB) == 4);

    std::vector<int> caseC = {7, 7, 7, 7, 7, 7, 7};
    assert(lisLengthViaBisection(caseC) == 1);

    std::vector<int> caseD = {-10, -1, -5, 0, 5, 1, 2};
    assert(lisLengthViaBisection(caseD) == 5);

    std::vector<double> caseE = {3.5, 1.2, 2.8, 3.1, 4.0};
    assert(lisLengthViaBisection(caseE) == 4);

    std::vector<char> caseF = {'a', 'b', 'c', 'a', 'd'};
    assert(lisLengthViaBisection(caseF) == 4);

    std::vector<int> caseG = {};
    assert(lisLengthViaBisection(caseG) == 0);

    std::cout << "All checks completed successfully!\n";
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file median_search.cpp
 * @brief Implementation of [Median search](https://en.wikipedia.org/wiki/Median_of_medians) algorithm.
 * @cases from [here](https://brilliant.org/wiki/median-finding-algorithm/)
 *
 * @details
 * Given an array A[1,...,n] of n numbers and an index i, where 1 ≤ i ≤ n, find the i-th smallest element of A.
 * median_of_medians(A, i):
 *  #divide A into sublists of len 5
 *  sublists = [A[j:j+5] for j in range(0, len(A), 5)]
 *  medians = [sorted(sublist)[len(sublist)/2] for sublist in sublists]
 *  if len(medians) <= 5:
 *	pivot = sorted(medians)[len(medians)/2]
 *  else:
 *      #the pivot is the median of the medians
 *      pivot = median_of_medians(medians, len(medians)/2)
 *  #partitioning step
 *  low = [j for j in A if j < pivot]
 *  high = [j for j in A if j > pivot]
 *  k = len(low)
 *   if i < k:
 *      return median_of_medians(low,i)
 *   elif i > k:
 *      return median_of_medians(high,i-k-1)
 *  else: #pivot = k
 *       return pivot
 *
 * \note this algorithm implements median search for only arrays which have distinct elements
 *
 * Here are some example lists you can use to see how the algorithm works
 * A = [1,2,3,4,5,1000,8,9,99] (Contain Unique Elements)
 * B = [1,2,3,4,5,6] (Contains Unique Elements)
 * print median_of_medians(A, 0) #should be 1
 * print median_of_medians(A,7) #should be 99
 * print median_of_medians(B,4) #should be 5
 *
 * @author Unknown author
 * @author [Sushil Kumar](https://github.com/Rp-sushil)
 */

#include <iostream>
#include <algorithm>
#include <vector>
#include <cassert>

/**
 * @namespace search
 * @brief Search algorithms
 */
namespace search {
/**
 * @namespace median_search
 * @brief Functions for [Median search](https://en.wikipedia.org/wiki/Median_search) algorithm
 */
namespace median_search {
/**
* This function search the element in an array for the given index.
* @param A array where numbers are saved
* @param idx current index in array
* @returns corresponding element which we want to search.
*/  
int median_of_medians(const std::vector<int>& A,  const int& idx) {
	int pivot = 0;					// initialized with zero
	std::vector<int> a(A.begin(), A.end());
	std::vector<int> m;
	int r = a.size();
	for(int i = 0; i < r; i += 5){
		std::sort(a.begin() + i, a.begin() + std::min(r, i + 5));
		int mid = (i + std::min(r, i + 5)) / 2;
		m.push_back(a[mid]);
	}
	int sz = int(m.size());
	if(sz <= 5){
		std::sort(m.begin(), m.end());
		pivot = m[(sz- 1) / 2];
	}
	else{
		pivot = median_of_medians(m, idx);
	}
	std::vector<int> low;
	std::vector<int> high;
	for(int i = 0; i < r; i++){
		if(a[i] < pivot){
			low.push_back(a[i]);
		}
		else if(a[i] > pivot){
			high.push_back(a[i]);
		}
	}
	int k = int(low.size());
	if(idx < k){
		return median_of_medians(low, idx);
	}
	else if(idx > k){
		return median_of_medians(high, idx-k-1);
	}
	else{
		return pivot;
	}
}
}  // namespace median_search
}  // namespace search

/**
 * Function to test above algorithm
 */
void test(){
	std::vector<int> A{25,21,98,100,76,22,43,60,89,87};
	int i = 3;
	assert(A[6] == search::median_search::median_of_medians(A, i));		// A[6]  = 43, is the fourth smallest element.
	std::cout << "test case:1 passed\n";

	std::vector<int> B{1,2,3,4,5,6};
	int j = 4;
	assert(B[4] == search::median_search::median_of_medians(B, j));		// B[4] = 5, is the fifth smallest element.
	std::cout << "test case:2 passed\n";

	std::vector<int> C{1,2,3,4,5,1000,8,9,99};
	int k = 3;
	assert(C[3] == search::median_search::median_of_medians(C, k)); 	// C[3] = 4, is the fourth smallest element.
	std::cout << "test case:3 passed\n";
	std::cout << "--All tests passed--\n";
}

/**
 * Main function
 */
int main()
{
	test();
	int n = 0;
	std::cout << "Enter Size of Array: ";
	std::cin >> n;
	std::vector<int> a(n);
	std::cout << "Enter Array: ";
	for(int i = 0; i < n; i++){
		std::cin >> a[i];
	}
	std::cout << "Median: ";			// Median defination: https://en.wikipedia.org/wiki/Median
	int x = search::median_search::median_of_medians(a,  (n - 1) / 2);
	if(n % 2 == 0){
		int y = search::median_search::median_of_medians(a, n / 2);
		std::cout << (float(x) + float(y))/2.0;
	}
	else{
		std::cout << x;
	}
	std::cout << "\nTo find i-th smallest element ";
       	std::cout << "\nEnter i: ";
	int idx = 0;
	std::cin >> idx;
	idx--;
	std::cout << idx + 1<< "-th smallest element: " << search::median_search::median_of_medians(a, idx) << '\n';
	return 0;
}

/**
 * @file median_search.cpp
 * @brief Median-of-medians selection algorithm (find the i-th smallest
 * element deterministically in linear time)
 *
 * @details
 * Given an array of n distinct numbers and an index i, this returns the
 * i-th smallest element (0-indexed) without fully sorting the array.
 *
 * Outline:
 *   select(A, i):
 *     split A into groups of 5
 *     compute the median of each group
 *     pivot = the median of those group-medians (recursively, if there are
 *             more than 5 of them)
 *     partition A around pivot into `low` (< pivot) and `high` (> pivot)
 *     let k = size of `low`
 *       if i < k:  recurse into low with the same index
 *       if i > k:  recurse into high with index (i - k - 1)
 *       if i == k: pivot is the answer
 *
 * \note This implementation assumes all elements are distinct.
 *
 * Example: A = [1,2,3,4,5,1000,8,9,99]
 *   select(A, 0) -> 1
 *   select(A, 7) -> 99
 *   B = [1,2,3,4,5,6]; select(B, 4) -> 5
 */

#include <iostream>
#include <algorithm>
#include <vector>
#include <cassert>

/**
 * @namespace search
 * @brief Search algorithms
 */
namespace search {

/**
 * @namespace median_search
 * @brief Median-of-medians (deterministic selection) algorithm
 */
namespace median_search {

/**
 * @brief Returns the element that would occupy position `targetIdx` if
 * `values` were fully sorted, without sorting the whole array.
 * @param values the array to select from
 * @param targetIdx the (0-based) rank being requested
 * @returns the value at that rank
 */
int selectNth(const std::vector<int>& values, const int& targetIdx) {
    int pivot = 0;
    std::vector<int> working(values.begin(), values.end());
    std::vector<int> groupMedians;
    int total = working.size();

    for (int start = 0; start < total; start += 5) {
        int end = std::min(total, start + 5);
        std::sort(working.begin() + start, working.begin() + end);
        int midIdx = (start + end) / 2;
        groupMedians.push_back(working[midIdx]);
    }

    int medianCount = static_cast<int>(groupMedians.size());
    if (medianCount <= 5) {
        std::sort(groupMedians.begin(), groupMedians.end());
        pivot = groupMedians[(medianCount - 1) / 2];
    } else {
        pivot = selectNth(groupMedians, targetIdx);
    }

    std::vector<int> below;
    std::vector<int> above;
    for (int i = 0; i < total; i++) {
        if (working[i] < pivot) {
            below.push_back(working[i]);
        } else if (working[i] > pivot) {
            above.push_back(working[i]);
        }
    }

    int belowCount = static_cast<int>(below.size());
    if (targetIdx < belowCount) {
        return selectNth(below, targetIdx);
    } else if (targetIdx > belowCount) {
        return selectNth(above, targetIdx - belowCount - 1);
    } else {
        return pivot;
    }
}

}  // namespace median_search
}  // namespace search

/**
 * @brief Reworded regression checks for selectNth().
 */
void runChecks() {
    std::vector<int> setA{25, 21, 98, 100, 76, 22, 43, 60, 89, 87};
    int idxA = 3;
    assert(setA[6] == search::median_search::selectNth(setA, idxA));  // 43 is the 4th smallest
    std::cout << "check 1 passed\n";

    std::vector<int> setB{1, 2, 3, 4, 5, 6};
    int idxB = 4;
    assert(setB[4] == search::median_search::selectNth(setB, idxB));  // 5 is the 5th smallest
    std::cout << "check 2 passed\n";

    std::vector<int> setC{1, 2, 3, 4, 5, 1000, 8, 9, 99};
    int idxC = 3;
    assert(setC[3] == search::median_search::selectNth(setC, idxC));  // 4 is the 4th smallest
    std::cout << "check 3 passed\n";
    std::cout << "--all checks passed--\n";
}

/**
 * Program entry point: runs regression checks, then an interactive demo
 * that reports the median and lets the user query an arbitrary rank.
 */
int main() {
    runChecks();
    int n = 0;
    std::cout << "Enter Size of Array: ";
    std::cin >> n;
    std::vector<int> values(n);
    std::cout << "Enter Array: ";
    for (int i = 0; i < n; i++) {
        std::cin >> values[i];
    }
    std::cout << "Median: ";  // https://en.wikipedia.org/wiki/Median
    int lower = search::median_search::selectNth(values, (n - 1) / 2);
    if (n % 2 == 0) {
        int upper = search::median_search::selectNth(values, n / 2);
        std::cout << (float(lower) + float(upper)) / 2.0;
    } else {
        std::cout << lower;
    }
    std::cout << "\nTo find i-th smallest element ";
    std::cout << "\nEnter i: ";
    int rank = 0;
    std::cin >> rank;
    rank--;
    std::cout << rank + 1 << "-th smallest element: "
              << search::median_search::selectNth(values, rank) << '\n';
    return 0;
}

/**
 * @file
 * @brief Given a linked list L[0,....,n] of n numbers, find the middle node.
 *
 * @details The technique utilized in this implementation is the ["Floyd's
 * tortoise and
 * hare"](https://en.wikipedia.org/wiki/Cycle_detection#Floyd's_tortoise_and_hare)
 * approach. This technique uses two pointers that iterate through the list at
 * different 'speeds' in order to solve problems. In this implementation, for
 * every iteration the slow pointer advances one node while the fast pointer
 * advances two nodes. The result of this is that since the fast pointer moves
 * twice as fast as the slow pointer, when the fast pointer reaches the end of
 * the list the slow pointer will be pointing to the middle node of the list.
 *
 * Here are some example lists you can use to see how the algorithm works
 * A = [1,2,3,4,5]
 * B = [1,2,3,4,5,6]
 * print median(A) #should be 39
 * print median(B) #should be 4
 *
 * @author [Benjamin Weiss](https://github.com/weiss-ben)
 * @see median_search.cpp
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations

/**
 * Definition for singly-linked list.
 */
struct ListNode {
    int val{0};               ///< the value stored in the node
    ListNode* next{nullptr};  ///< pointer to the next node
    ListNode() = default;     ///< default constructor
    explicit ListNode(int x)
        : val(x) {}  ///< constructor with value for node->val provided
    ListNode(int x, ListNode* next)
        : val(x),
          next(next) {
    }  ///< constructor with values provided for node->val and node->next
};

/**
 * @namespace search
 * @brief Search algorithms
 */
namespace search {
/**
 * @namespace median_search
 * @brief Functions for the Median Search algorithm implementation. Wkipedia
 * link to algorithm: https://en.wikipedia.org/wiki/Median_search
 */
namespace median_search2 {
/**
 * This function searches for the median of a linked list.
 * @param head The head of the linked list.
 * @returns Median node of the linked list.
 */
ListNode* middleNode(ListNode* head) {
    if (!head) {
        return nullptr;
    }

    // Fast and slow pointers
    ListNode* fastptr = nullptr;
    ListNode* slowptr = fastptr = head;

    // fast jumps 2 while slow jumps 1
    while (fastptr->next && fastptr->next->next) {
        slowptr = slowptr->next;
        fastptr = fastptr->next->next;
    }

    return (fastptr->next) ? slowptr->next : slowptr;
}

void deleteAll(const ListNode* const head) {
    if (head) {
        deleteAll(head->next);
        delete head;
    }
}
}  // namespace median_search2
}  // namespace search

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    auto* head1 = new ListNode;
    head1->val = 1;

    ListNode* temp = head1;
    for (int i = 2; i < 6; ++i) {
        // Allocate next
        auto* temp1 = new ListNode;
        temp1->val = i;

        // Advance
        temp->next = temp1;
        temp = temp1;
    }
    temp->next = nullptr;

    const ListNode* const median = search::median_search2::middleNode(head1);
    assert(3 == median->val);  // 3 is the value of the median node.
    search::median_search2::deleteAll(head1);
    std::cout << "test case:1 passed\n";

    // Test case # 2
    auto* head2 = new ListNode;
    head2->val = 1;

    ListNode* temp2 = head2;
    for (int i = 2; i < 7; ++i) {
        // Allocate next
        auto* temp3 = new ListNode;
        temp3->val = i;

        // Advance
        temp2->next = temp3;
        temp2 = temp3;
    }
    temp2->next = nullptr;

    const ListNode* const median1 = search::median_search2::middleNode(head2);
    assert(4 == median1->val);  // 4 is the value of the median node.
    search::median_search2::deleteAll(head2);
    std::cout << "test case:2 passed\n";

    std::cout << "--All tests passed--\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

/**
 * @file
 * @brief Find the middle node of a singly linked list of n nodes.
 *
 * @details Uses the "tortoise and hare" two-pointer technique: one pointer
 * advances one node per step while the other advances two nodes per step.
 * Because the fast pointer covers ground twice as quickly, by the time it
 * reaches the tail the slow pointer sits exactly at the middle node.
 *
 * Example lists:
 *   A = [1,2,3,4,5]   -> middle value 3
 *   B = [1,2,3,4,5,6] -> middle value 4
 *
 * @see median_search.cpp
 */

#include <cassert>   /// for assert
#include <iostream>  /// for std::cout

/**
 * A node in a singly linked list.
 */
struct Node {
    int val{0};          ///< value stored at this node
    Node* next{nullptr};  ///< pointer to the following node
    Node() = default;
    explicit Node(int x) : val(x) {}
    Node(int x, Node* nextNode) : val(x), next(nextNode) {}
};

/**
 * @namespace search
 * @brief Search algorithms
 */
namespace search {

/**
 * @namespace median_search2
 * @brief Middle-of-linked-list search via the tortoise/hare technique
 */
namespace median_search2 {

/**
 * @brief Locates the middle node of a linked list.
 * @param head first node of the list
 * @returns pointer to the middle node (upper middle for even-length lists)
 */
Node* findMiddle(Node* head) {
    if (!head) {
        return nullptr;
    }

    Node* fast = head;
    Node* slow = head;

    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }

    return (fast->next) ? slow->next : slow;
}

/// Recursively frees every node starting from `head`.
void releaseList(const Node* const head) {
    if (head) {
        releaseList(head->next);
        delete head;
    }
}

}  // namespace median_search2
}  // namespace search

/**
 * @brief Reworded regression checks.
 * @returns void
 */
static void runChecks() {
    auto* listA = new Node;
    listA->val = 1;

    Node* cursor = listA;
    for (int i = 2; i < 6; ++i) {
        auto* fresh = new Node;
        fresh->val = i;
        cursor->next = fresh;
        cursor = fresh;
    }
    cursor->next = nullptr;

    const Node* const midA = search::median_search2::findMiddle(listA);
    assert(3 == midA->val);
    search::median_search2::releaseList(listA);
    std::cout << "check 1 passed\n";

    auto* listB = new Node;
    listB->val = 1;

    Node* cursorB = listB;
    for (int i = 2; i < 7; ++i) {
        auto* fresh = new Node;
        fresh->val = i;
        cursorB->next = fresh;
        cursorB = fresh;
    }
    cursorB->next = nullptr;

    const Node* const midB = search::median_search2::findMiddle(listB);
    assert(4 == midB->val);
    search::median_search2::releaseList(listB);
    std::cout << "check 2 passed\n";

    std::cout << "--all checks passed--\n";
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Saddleback
 * Algorithm](https://www.geeksforgeeks.org/saddleback-search-algorithm-in-a-2d-array)
 * for 2D arrays.
 *
 * @details
 * Saddleback Algorithm is an algorithm that searches 2D array in linear time,
 * i.e, O(m + n), where m is number of rows and n is number of columns of 2D
 * array. Also, each row and column of the matrix should be sorted beforehand
 * for this algorithm to work.
 *
 * @author [Hashir Niazi](https://github.com/HashirGJ8842)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for io operations, and std::pair
#include <vector>    /// for std::vector

/** \namespace search
 * \brief Algorithms for searching
 */
namespace search {
/** \namespace saddleback
 * \brief Function for implementing [Saddleback
 * Algorithm](https://www.geeksforgeeks.org/saddleback-search-algorithm-in-a-2d-array).
 */
namespace saddleback {
/**
 * This function implements [Saddleback
 * Algorithm](https://www.geeksforgeeks.org/saddleback-search-algorithm-in-a-2d-array),
 * on a sorted 2D array, and finds the location of the element needed to search
 * @param matrix 2D matrix which is sorted on the basis of rows and columns
 * @param element element to be searched
 * @return An std::pair of with row and column populated within it, if the
 * element is present.
 * @return An std::pair with (0, 0), if the element is not present.
 */
std::pair<uint32_t, uint32_t> saddleback(
    std::vector<std::vector<int32_t>> matrix, int32_t element) {
    uint32_t left_index = 0;
    uint32_t right_index = matrix[0].size() - 1;  // Start from top right corner
    while (left_index <
           matrix.size()) {  // Exit once the value of indexes get out of range.
        if (element ==
            matrix[left_index]
                  [right_index]) {  // If value on this position of matrix is
                                    // equal to element, return (row, column).
            return std::make_pair(left_index + 1, right_index + 1);
        } else if (element >
                   matrix[left_index]
                         [right_index]) {  // Else if value on this position of
                                           // matrix is less than the element,
                                           // move left.
            ++left_index;
        } else if (element <
                   matrix[left_index]
                         [right_index]) {  // Else if value on this position of
                                           // matrix is greater than the
                                           // element, move down.
            if (!right_index)
                break;
            else
                --right_index;
        }
    }
    return std::make_pair(
        0, 0);  // If the program reaches here, that means one of the index
                // went out of index, hence no element present.
}
}  // namespace saddleback
}  // namespace search

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    std::vector<std::vector<int32_t>> matrix = {{1, 10, 100, 1000, 10000},
                                                {2, 20, 200, 2000, 20000},
                                                {3, 30, 300, 3000, 30000},
                                                {4, 40, 400, 4000, 40000},
                                                {5, 50, 500, 5000, 50000}};

    std::pair<uint32_t, uint32_t> not_found = std::make_pair(0, 0);
    std::pair<uint32_t, uint32_t> test_answer;
    // Test 1
    std::pair<uint32_t, uint32_t> answer1 =
        search::saddleback::saddleback(matrix, 123);
    assert(not_found == answer1);
    // Test 2
    answer1 = search::saddleback::saddleback(matrix, 0);
    assert(not_found == answer1);
    // Test 3
    answer1 = search::saddleback::saddleback(matrix, 1);
    test_answer = std::make_pair(1, 1);
    assert(test_answer == answer1);
    // Test 4
    answer1 = search::saddleback::saddleback(matrix, 50000);
    test_answer = std::make_pair(5, 5);
    assert(test_answer == answer1);
    // Test 5
    answer1 = search::saddleback::saddleback(matrix, 300);
    test_answer = std::make_pair(3, 3);
    assert(test_answer == answer1);
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // execute the tests
    return 0;
}

/**
 * @file
 * @brief Saddleback search over a row/column sorted 2D matrix
 *
 * @details
 * Given a matrix where every row and every column is individually sorted in
 * ascending order, the saddleback algorithm locates a target value in
 * O(rows + cols) time by starting at the top-right corner and eliminating
 * either a row or a column on every comparison:
 *   - if the current cell equals the target, we're done
 *   - if the current cell is smaller than the target, the whole column can't
 *     contain it (move down a row)
 *   - if the current cell is larger than the target, the whole row can't
 *     contain it (move left a column)
 */
#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO and std::pair
#include <vector>    /// for std::vector

/** \namespace search
 * \brief Searching algorithms
 */
namespace search {

/** \namespace saddleback
 * \brief Saddleback search implementation
 */
namespace saddleback {

/**
 * @brief Searches a row/column sorted matrix for `target`.
 * @param grid the sorted matrix to search
 * @param target the value being searched for
 * @return 1-indexed (row, column) pair if found
 * @return (0, 0) if the value is not present
 */
std::pair<uint32_t, uint32_t> locate(std::vector<std::vector<int32_t>> grid,
                                      int32_t target) {
    uint32_t row = 0;
    uint32_t col = grid[0].size() - 1;  // begin at the top-right corner

    while (row < grid.size()) {
        int32_t current = grid[row][col];
        if (target == current) {
            return std::make_pair(row + 1, col + 1);
        } else if (target > current) {
            // everything in this column above is even smaller; drop the row
            ++row;
        } else {  // target < current
            // everything in this row to the right is even bigger; drop the column
            if (!col) {
                break;
            }
            --col;
        }
    }
    return std::make_pair(0, 0);  // ran out of bounds: not present
}

}  // namespace saddleback
}  // namespace search

/**
 * @brief Reworded regression checks.
 * @returns void
 */
static void runChecks() {
    std::vector<std::vector<int32_t>> grid = {{1, 10, 100, 1000, 10000},
                                               {2, 20, 200, 2000, 20000},
                                               {3, 30, 300, 3000, 30000},
                                               {4, 40, 400, 4000, 40000},
                                               {5, 50, 500, 5000, 50000}};

    std::pair<uint32_t, uint32_t> missing = std::make_pair(0, 0);
    std::pair<uint32_t, uint32_t> result;

    result = search::saddleback::locate(grid, 123);
    assert(missing == result);

    result = search::saddleback::locate(grid, 0);
    assert(missing == result);

    result = search::saddleback::locate(grid, 1);
    assert(std::make_pair<uint32_t, uint32_t>(1, 1) == result);

    result = search::saddleback::locate(grid, 50000);
    assert(std::make_pair<uint32_t, uint32_t>(5, 5) == result);

    result = search::saddleback::locate(grid, 300);
    assert(std::make_pair<uint32_t, uint32_t>(3, 3) == result);
}

/**
 * @brief Program entry point.
 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Sublist Search
 * Algorithm](https://www.geeksforgeeks.org/sublist-search-search-a-linked-list-in-another-list)
 * @details
 *
 * ### Algorithm
 *
 *  * Sublist search is used to detect a presence of one list in another list.
 *  * Suppose we have a single-node list (let's say the first list), and we
 *  want to ensure that the list is present in another list (let's say the
 * second list), then we can perform the sublist search to find it.
 *
 *  * For instance, the first list contains these elements: 23 -> 30 -> 41,
 *  and the second list contains these elements: 10 -> 15 -> 23 -> 30 -> 41
 *  -> 49. At a glance, we see that the first list presents in the second list.
 *
 * ### Working
 *
 *  * The sublist search algorithm works by comparing the first element
 *  of the first list with the first element of the second list.
 *  * If the two values don't match, it goes to the next element of the
 *  second list. It does this until the two values match.
 *
 * @author [Nitin Sharma](https://github.com/foo290)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace search
 * @brief Searching algorithms
 */
namespace search {
/**
 * @namespace sublist_search
 * @brief Functions for the [Sublist
 * Search](https://www.geeksforgeeks.org/sublist-search-search-a-linked-list-in-another-list)
 * implementation
 */
namespace sublist_search {
/**
 * @brief A Node structure representing a single link Node in a linked list
 */
struct Node {
    uint32_t data = 0;  ///< the key/value of the node
    Node *next{};       ///< pointer to the next node
};

/**
 * @brief A simple function to print the linked list
 * @param start The head of the linked list
 * @returns void
 */
void printLinkedList(Node *start) {
    while (start != nullptr) {
        std::cout << "->" << start->data;
        start = start->next;
    }
    std::cout << std::endl;
}

/**
 * @brief Give a vector of data,
 * it adds each element of vector in the linked list and return the address of
 * head pointer.
 * @param data A vector of "int" containing the data that is supposed to be
 * stored in nodes of linked list.
 * @returns Node* A head pointer to the linked list.
 */
Node *makeLinkedList(const std::vector<uint64_t> &data) {
    /// This is used in test cases for rapidly creating linked list with 100+
    /// elements, instead of hard-coding 100 elements in test cases.
    Node *head = nullptr;
    Node *tail = nullptr;
    for (int i : data) {
        Node *node = new Node;
        node->data = i;
        node->next = nullptr;
        if (head == nullptr) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            tail = tail->next;
        }
    }
    return head;
}

/*
 * @brief This function dealocates memory related to the given list
 * It recursively deletes all of the nodes of the input list.
 * @param room the root/head of the input list
 * @warning Plese note that the memory for each node has to be alocated using
 * new.
 */
void deleteList(Node *const root) {
    if (root != NULL) {
        deleteList(root->next);
        delete root;
    }
}

/**
 * @brief Main searching function
 * @param sublist A linked list which is supposed to be searched in mainList.
 * @param mainList A linked list in which sublist will be searched.
 * @returns true if the sublist is found
 * @returns false if the sublist is NOT found
 */
bool sublistSearch(Node *sublist, Node *mainList) {
    if (sublist == nullptr || mainList == nullptr) {
        return false;
    }

    /// Initialize target pointer to the head node of sublist.
    Node *target_ptr = sublist;

    while (mainList != nullptr) {
        /// Initialize main pointer to the current node of main list.
        Node *main_ptr = mainList;

        while (target_ptr != nullptr) {
            if (main_ptr == nullptr) {
                return false;

            } else if (main_ptr->data == target_ptr->data) {
                /// If the data of target node and main node is equal then move
                /// to the next node of both lists.
                target_ptr = target_ptr->next;
                main_ptr = main_ptr->next;

            } else {
                break;
            }
        }

        if (target_ptr == nullptr) {
            /// Is target pointer becomes null that means the target list is
            /// been traversed without returning false. Which means the sublist
            /// has been found and return ture.
            return true;
        }

        /// set the target pointer again to stating point of target list.
        target_ptr = sublist;

        /// set the main pointer to the next element of the main list and repeat
        /// the algo.
        mainList = mainList->next;
    }

    /// If the main list is exhausted, means sublist does not found, return
    /// false
    return false;
}

}  // namespace sublist_search
}  // namespace search

/**
 * @brief class encapsulating the necessary test cases
 */
class TestCases {
 private:
    /**
     * @brief A function to print given message on console.
     * @tparam T Type of the given message.
     * @returns void
     * */
    template <typename T>
    void log(T msg) {
        // It's just to avoid writing cout and endl
        std::cout << "[TESTS] : ---> " << msg << std::endl;
