}

// C++ program to sort an array using bucket sort
#include <algorithm>
#include <iostream>
#include <vector>

// Function to sort arr[] of size n using bucket sort
void bucketSort(float arr[], int n) {
    // 1) Create n empty buckets
    std::vector<float> *b = new std::vector<float>[n];

    // 2) Put array elements in different buckets
    for (int i = 0; i < n; i++) {
        int bi = n * arr[i];  // Index in bucket
        b[bi].push_back(arr[i]);
    }

    // 3) Sort individual buckets
    for (int i = 0; i < n; i++) std::sort(b[i].begin(), b[i].end());

    // 4) Concatenate all buckets into arr[]
    int index = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < b[i].size(); j++) arr[index++] = b[i][j];
    delete[] b;
}

/* Driver program to test above funtion */
int main() {
    float arr[] = {0.897, 0.565, 0.656, 0.1234, 0.665, 0.3434};
    int n = sizeof(arr) / sizeof(arr[0]);
    bucketSort(arr, n);

    std::cout << "Sorted array is \n";
    for (int i = 0; i < n; i++) std::cout << arr[i] << " ";
    return 0;
}

// Alternate implementation of bucket sort for floats in [0, 1).
#include <algorithm>
#include <iostream>
#include <vector>

// Distributes values of `values` (length `count`) into `count` buckets based
// on their magnitude, sorts each bucket, then stitches everything back
// together in place.
void sortByBuckets(float values[], int count) {
    // Step 1: allocate one bucket per element.
    std::vector<std::vector<float>> buckets(count);

    // Step 2: assign each value to a bucket according to its scaled position.
    for (int pos = 0; pos < count; ++pos) {
        int bucketIdx = static_cast<int>(count * values[pos]);
        buckets[bucketIdx].push_back(values[pos]);
    }

    // Step 3: sort the contents of every bucket individually.
    for (auto &bucket : buckets) {
        std::sort(bucket.begin(), bucket.end());
    }

    // Step 4: write the buckets back into the original array, in order.
    int writePos = 0;
    for (auto &bucket : buckets) {
        for (float v : bucket) {
            values[writePos] = v;
            ++writePos;
        }
    }
}

/* Demo/driver exercising sortByBuckets */
int main() {
    float samples[] = {0.897f, 0.565f, 0.656f, 0.1234f, 0.665f, 0.3434f};
    int total = sizeof(samples) / sizeof(samples[0]);

    sortByBuckets(samples, total);

    std::cout << "Result after bucket sort:\n";
    for (int i = 0; i < total; ++i) {
        std::cout << samples[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

// Returns Sorted elements after performing Cocktail Selection Sort
// It is a Sorting algorithm which chooses the minimum and maximum element in an
// array simultaneously, and swaps it with the lowest and highest available
// position iteratively or recursively

#include <algorithm>
#include <iostream>
#include <vector>

// Iterative Version

void CocktailSelectionSort(std::vector<int> *vec, int low, int high) {
    while (low <= high) {
        int minimum = (*vec)[low];
        int minimumindex = low;
        int maximum = (*vec)[high];
        int maximumindex = high;

        for (int i = low; i <= high; i++) {
            if ((*vec)[i] >= maximum) {
                maximum = (*vec)[i];
                maximumindex = i;
            }
            if ((*vec)[i] <= minimum) {
                minimum = (*vec)[i];
                minimumindex = i;
            }
        }
        if (low != maximumindex || high != minimumindex) {
            std::swap((*vec)[low], (*vec)[minimumindex]);
            std::swap((*vec)[high], (*vec)[maximumindex]);
        } else {
            std::swap((*vec)[low], (*vec)[high]);
        }

        low++;
        high--;
    }
}

// Recursive Version

void CocktailSelectionSort_v2(std::vector<int> *vec, int low, int high) {
    if (low >= high)
        return;

    int minimum = (*vec)[low];
    int minimumindex = low;
    int maximum = (*vec)[high];
    int maximumindex = high;

    for (int i = low; i <= high; i++) {
        if ((*vec)[i] >= maximum) {
            maximum = (*vec)[i];
            maximumindex = i;
        }
        if ((*vec)[i] <= minimum) {
            minimum = (*vec)[i];
            minimumindex = i;
        }
    }
    if (low != maximumindex || high != minimumindex) {
        std::swap((*vec)[low], (*vec)[minimumindex]);
        std::swap((*vec)[high], (*vec)[maximumindex]);
    } else {
        std::swap((*vec)[low], (*vec)[high]);
    }

    CocktailSelectionSort(vec, low + 1, high - 1);
}

// main function, select any one of iterative or recursive version

int main() {
    int n;
    std::cout << "Enter number of elements\n";
    std::cin >> n;
    std::vector<int> v(n);
    std::cout << "Enter all the elements\n";
    for (int i = 0; i < n; ++i) {
        std::cin >> v[i];
    }

    int method;
    std::cout << "Enter method: \n\t0: iterative\n\t1: recursive:\t";
    std::cin >> method;

    if (method == 0) {
        CocktailSelectionSort(&v, 0, n - 1);
    } else if (method == 1) {
        CocktailSelectionSort_v2(&v, 0, n - 1);
    } else {
        std::cerr << "Unknown method" << std::endl;
        return -1;
    }
    std::cout << "Sorted elements are\n";
    for (int i = 0; i < n; ++i) {
        std::cout << v[i] << " ";
    }

    return 0;
}

// Alternate take on Cocktail Selection Sort: each pass locates both the
// smallest and largest remaining element in one sweep, and places them at
// the two ends of the still-unsorted window simultaneously.

#include <algorithm>
#include <iostream>
#include <vector>

// Locates the index of the smallest and largest values within
// data[start..end] inclusive, returning them via the reference parameters.
void findExtremes(const std::vector<int> &data, int start, int end,
                   int &smallIdx, int &bigIdx) {
    smallIdx = start;
    bigIdx = end;
    int smallVal = data[start];
    int bigVal = data[end];

    for (int cursor = start; cursor <= end; ++cursor) {
        if (data[cursor] <= smallVal) {
            smallVal = data[cursor];
            smallIdx = cursor;
        }
        if (data[cursor] >= bigVal) {
            bigVal = data[cursor];
            bigIdx = cursor;
        }
    }
}

// Iterative version: shrink the [start, end] window from both sides,
// pulling the minimum to the front and the maximum to the back each round.
void dualEndedSelectionSort(std::vector<int> &data, int start, int end) {
    while (start <= end) {
        int smallIdx, bigIdx;
        findExtremes(data, start, end, smallIdx, bigIdx);

        if (smallIdx != end || bigIdx != start) {
            std::swap(data[start], data[smallIdx]);
            std::swap(data[end], data[bigIdx]);
        } else {
            std::swap(data[start], data[end]);
        }

        ++start;
        --end;
    }
}

// Recursive version: handle one window, then recurse into the interior.
void dualEndedSelectionSortRecursive(std::vector<int> &data, int start, int end) {
    if (start >= end) {
        return;
    }

    int smallIdx, bigIdx;
    findExtremes(data, start, end, smallIdx, bigIdx);

    if (smallIdx != end || bigIdx != start) {
        std::swap(data[start], data[smallIdx]);
        std::swap(data[end], data[bigIdx]);
    } else {
        std::swap(data[start], data[end]);
    }

    dualEndedSelectionSort(data, start + 1, end - 1);
}

// Reads element count and values, then runs whichever variant was chosen.
int main() {
    int count = 0;
    std::cout << "How many elements?\n";
    std::cin >> count;

    std::vector<int> values(count);
    std::cout << "Enter the elements:\n";
    for (int i = 0; i < count; ++i) {
        std::cin >> values[i];
    }

    int choice = 0;
    std::cout << "Choose a variant:\n\t0: iterative\n\t1: recursive\t";
    std::cin >> choice;

    switch (choice) {
        case 0:
            dualEndedSelectionSort(values, 0, count - 1);
            break;
        case 1:
            dualEndedSelectionSortRecursive(values, 0, count - 1);
            break;
        default:
            std::cerr << "Unrecognized variant" << std::endl;
            return -1;
    }

    std::cout << "Result:\n";
    for (int i = 0; i < count; ++i) {
        std::cout << values[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

/**
 *
 * \file
 * \brief [Comb Sort Algorithm
 * (Comb Sort)](https://en.wikipedia.org/wiki/Comb_sort)
 *
 * \author
 *
 * \details
 * - A better version of bubble sort algorithm
 * - Bubble sort compares adjacent values whereas comb sort uses gap larger
 *   than 1
 * - Best case Time complexity O(n)
 *   Worst case Time complexity O(n^2)
 *
 */

#include <algorithm>
#include <cassert>
#include <iostream>

/**
 *
 * Find the next gap by shrinking the current gap by shrink factor of 1.3
 * @param gap current gap
 * @return new gap
 *
 */
int FindNextGap(int gap) {
    gap = (gap * 10) / 13;

    return std::max(1, gap);
}

/** Function to sort array
 *
 * @param arr array to be sorted
 * @param l start index of array
 * @param r end index of array
 *
 */
void CombSort(int *arr, int l, int r) {
    /**
     *
     * initial gap will be maximum and the maximum possible value is
     * the size of the array that is n and which is equal to r in this
     * case so to avoid passing an extra parameter n that is the size of
     * the array we are using r to initialize the initial gap.
     *
     */
    int gap = r;

    /// Initialize swapped as true to make sure that loop runs
    bool swapped = true;

    /// Keep running until gap = 1 or none elements were swapped
    while (gap != 1 || swapped) {
        /// Find next gap
        gap = FindNextGap(gap);

        swapped = false;

        /// Compare all elements with current gap
        for (int i = l; i < r - gap; ++i) {
            if (arr[i] > arr[i + gap]) {
                std::swap(arr[i], arr[i + gap]);
                swapped = true;
            }
        }
    }
}

void tests() {
    /// Test 1
    int arr1[10] = {34, 56, 6, 23, 76, 34, 76, 343, 4, 76};
    CombSort(arr1, 0, 10);
    assert(std::is_sorted(arr1, arr1 + 10));
    std::cout << "Test 1 passed\n";

    /// Test 2
    int arr2[8] = {-6, 56, -45, 56, 0, -1, 8, 8};
    CombSort(arr2, 0, 8);
    assert(std::is_sorted(arr2, arr2 + 8));
    std::cout << "Test 2 Passed\n";
}

/** Main function */
int main() {
    /// Running predefined tests
    tests();

    /// For user interaction
    int n;
    std::cin >> n;
    int *arr = new int[n];
    for (int i = 0; i < n; ++i) std::cin >> arr[i];
    CombSort(arr, 0, n);
    for (int i = 0; i < n; ++i) std::cout << arr[i] << ' ';
    delete[] arr;
    return 0;
}

/**
 * \file
 * \brief Reworded implementation of [Comb Sort](https://en.wikipedia.org/wiki/Comb_sort)
 *
 * \details
 * Comb sort improves on plain bubble sort by comparing elements that are
 * further apart than just neighbors. The separation ("gap") starts large and
 * shrinks toward 1 as passes continue, which helps clear out "turtles" (small
 * values stuck near the end) much faster than bubble sort would.
 *
 * - Best case: O(n)
 * - Worst case: O(n^2)
 */

#include <algorithm>
#include <cassert>
#include <iostream>

/**
 * Shrinks the current gap by the standard comb-sort shrink factor (~1.3),
 * never letting it drop below 1.
 * @param currentGap the gap used in the pass just completed
 * @return the gap to use for the next pass
 */
int shrinkGap(int currentGap) {
    int candidate = (currentGap * 10) / 13;
    return candidate > 1 ? candidate : 1;
}

/**
 * Sorts the range [start, end) of an int array using comb sort.
 * @param data pointer to the array
 * @param start first index included in the sort
 * @param end one past the last index included in the sort
 */
void combSort(int *data, int start, int end) {
    // The initial gap is the width of the range being sorted.
    int gap = end;

    // Track whether the previous pass performed any exchange.
    bool exchangedSomething = true;

    // Keep combing through until the gap has collapsed to 1 AND a pass
    // produced no exchanges.
    while (gap != 1 || exchangedSomething) {
        gap = shrinkGap(gap);
        exchangedSomething = false;

        for (int i = start; i < end - gap; ++i) {
            if (data[i] > data[i + gap]) {
                std::swap(data[i], data[i + gap]);
                exchangedSomething = true;
            }
        }
    }
}

/**
 * Runs a couple of canned test cases against combSort.
 */
void runSampleChecks() {
    // Case 1
    int sample1[10] = {34, 56, 6, 23, 76, 34, 76, 343, 4, 76};
    combSort(sample1, 0, 10);
    assert(std::is_sorted(sample1, sample1 + 10));
    std::cout << "Sample check 1 OK\n";

    // Case 2
    int sample2[8] = {-6, 56, -45, 56, 0, -1, 8, 8};
    combSort(sample2, 0, 8);
    assert(std::is_sorted(sample2, sample2 + 8));
    std::cout << "Sample check 2 OK\n";
}

/** Program entry point */
int main() {
    // Run the built-in checks first.
    runSampleChecks();

    // Then allow interactive input from the user.
    int count = 0;
    std::cin >> count;
    int *values = new int[count];
    for (int i = 0; i < count; ++i) {
        std::cin >> values[i];
    }

    combSort(values, 0, count);

    for (int i = 0; i < count; ++i) {
        std::cout << values[i] << ' ';
    }

    delete[] values;
    return 0;
}

/**
 * @file
 * @brief Counting Inversions using [Merge
 Sort](https://en.wikipedia.org/wiki/Merge_sort)
 *
 * @details
 * Program to count the number of inversions in an array
 * using merge-sort.
 *
 * The count of inversions help to determine how close the array
 * is to be sorted in ASCENDING order.
 *
 * two elements a[i] and a[j] form an inversion if `a[i]` > `a[j]` and i < j
 *
 * Time Complexity --> `O(n.log n)`

 * Space Complexity --> `O(n)` ; additional array `temp[1..n]`
 * ### Algorithm

 *   1. The idea is similar to merge sort, divide the array into two equal or
 almost
 *      equal halves in each step until the base case is reached.
 *   2. Create a function merge that counts the number of inversions when two
 halves of
 *      the array are merged, create two indices i and j, i is the index for
 first half
 *      and j is an index of the second half. if `a[i]` is greater than `a[j]`,
 then there are (mid – i)
 *      inversions, Because left and right subarrays are sorted, so all the
 remaining elements
 *      in left-subarray (a[i+1], a[i+2] … a[mid]) will be greater than a[j].
 *   3. Create a recursive function to divide the array into halves and find the
 answer by summing
 *      the number of inversions is the first half, number of inversion in the
 second half and
 *      the number of inversions by merging the two.
 *   4. The base case of recursion is when there is only one element in the
 given half.
 *   5. Print the answer
 *
 * @author [Rakshit Raj](https://github.com/rakshitraj)
 */
#include <cassert>   /// for assert
#include <cstdint>   /// for typedef datatype uint64_t
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace inversion
 * @brief Functions for counting inversions using Merge Sort algorithm
 */
namespace inversion {

// Functions used --->
// int mergeSort(int* arr, int* temp, int left, int right);
// int merge(int* arr, int* temp, int left, int mid, int right);
// int countInversion(int* arr, const int size);
// void show(int* arr, const int size);

/**
 * @brief Function to merge two sub-arrays.
 *
 * @details
 * merge() function is called from mergeSort()
 * to merge the array after it split for sorting
 * by the mergeSort() funtion.
 *
 * In this case the merge fuction will also count and return
 * inversions detected when merging the sub arrays.
 *
 * @param arr    input array, data-menber of vector
 * @param temp   stores the resultant merged array
 * @param left   lower bound of `arr[]` and left-sub-array
 * @param mid    midpoint, upper bound of left sub-array,
 *               `(mid+1)` gives the lower bound of right-sub-array
 * @param right  upper bound of `arr[]` and right-sub-array
 * @returns number of inversions found in merge step
 */
template <typename T>
uint32_t merge(T* arr, T* temp, uint32_t left, uint32_t mid, uint32_t right) {
    uint32_t i = left;       /* i --> index of left sub-array */
    uint32_t j = mid + 1;    /* j --> index for right sub-array */
    uint32_t k = left;       /* k --> index for resultant array temp */
    uint32_t inv_count = 0;  // inversion count

    while ((i <= mid) && (j <= right)) {
        if (arr[i] <= arr[j]) {
            temp[k++] = arr[i++];
        } else {
            temp[k++] = arr[j++];
            inv_count +=
                (mid - i +
                 1);  // tricky; may vary depending on selection of sub-array
        }
    }
    // Add remaining elements from the larger subarray to the end of temp
    while (i <= mid) {
        temp[k++] = arr[i++];
    }
    while (j <= right) {
        temp[k++] = arr[j++];
    }
    // Copy temp[] to arr[]
    for (k = left; k <= right; k++) {
        arr[k] = temp[k];
    }
    return inv_count;
}

/**
 * @brief Implement merge Sort and count inverions while merging
 *
 * @details
 * The mergeSort() function implements Merge Sort, a
 * Divide and conquer algorithm, it divides the input
 * array into two halves and calls itself for each
 * sub-array and then calls the merge() function to
 * merge the two halves.
 *
 * @param arr   - array to be sorted
 * @param temp  - merged resultant array
 * @param left  - lower bound of array
 * @param right - upper bound of array
 * @returns number of inversions in array
 */
template <typename T>
uint32_t mergeSort(T* arr, T* temp, uint32_t left, uint32_t right) {
    uint32_t mid = 0, inv_count = 0;
    if (right > left) {
        // midpoint to split the array
        mid = (right + left) / 2;
        // Add inversions in left and right sub-arrays
        inv_count += mergeSort(arr, temp, left, mid);  // left sub-array
        inv_count += mergeSort(arr, temp, mid + 1, right);

        // inversions in the merge step
        inv_count += merge(arr, temp, left, mid, right);
    }
    return inv_count;
}

/**
 * @brief Function countInversion() returns the number of inversion
 * present in the input array. Inversions are an estimate of
 * how close or far off the array is to being sorted.
 *
 * @details
 * Number of inversions in a sorted array is 0.
 * Number of inversion in an array[1...n] sorted in
 * non-ascending order is n(n-1)/2, since each pair of elements
 * contitute an inversion.
 *
 * @param arr   - array, data member of std::vector<int>, input for counting
 * inversions
 * @param array_size    - number of elementa in the array
 * @returns number of inversions in input array, sorts the array
 */
template <class T>
uint32_t countInversion(T* arr, const uint32_t size) {
    std::vector<T> temp;
    temp.reserve(size);
    temp.assign(size, 0);
    return mergeSort(arr, temp.data(), 0, size - 1);
}

/**
 * @brief UTILITY function to print array.
 * @param arr[]   array to print
 * @param array_size    size of input array arr[]
 * @returns void
 *
 */
template <typename T>
void show(T* arr, const uint32_t array_size) {
    std::cout << "Printing array: \n";
    for (uint32_t i = 0; i < array_size; i++) {
        std::cout << " " << arr[i];
    }
    std::cout << "\n";
}

}  // namespace inversion
}  // namespace sorting

