/**
 * Counting inversions via merge sort.
 *
 * An inversion is a pair of positions (i, j) with i < j but arr[i] > arr[j].
 * The total inversion count is a handy proxy for "how far from sorted" an
 * array is: a sorted array has zero inversions, and a fully reverse-sorted
 * array has the maximum possible, n*(n-1)/2.
 *
 * Strategy: piggy-back on merge sort. Whenever the merge step takes an
 * element from the right half before the left half is exhausted, every
 * remaining element in the left half forms an inversion with it.
 *
 * Time complexity: O(n log n). Space complexity: O(n) for the scratch
 * buffer used during merging.
 */
#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

namespace sorting {
namespace inversion {

/**
 * Merges arr[left..mid] with arr[mid+1..right] (both already sorted),
 * tallying cross-inversions along the way, and returns that tally.
 */
template <typename T>
uint32_t mergeAndCount(T *arr, T *scratch, uint32_t left, uint32_t mid,
                       uint32_t right) {
    uint32_t leftCursor = left;
    uint32_t rightCursor = mid + 1;
    uint32_t writeCursor = left;
    uint32_t crossings = 0;

    while (leftCursor <= mid && rightCursor <= right) {
        if (arr[leftCursor] <= arr[rightCursor]) {
            scratch[writeCursor++] = arr[leftCursor++];
        } else {
            scratch[writeCursor++] = arr[rightCursor++];
            crossings += (mid - leftCursor + 1);
        }
    }
    while (leftCursor <= mid) scratch[writeCursor++] = arr[leftCursor++];
    while (rightCursor <= right) scratch[writeCursor++] = arr[rightCursor++];

    for (uint32_t k = left; k <= right; ++k) arr[k] = scratch[k];

    return crossings;
}

/**
 * Recursively sorts arr[left..right] and accumulates the inversion count
 * from both halves plus whatever is discovered during merging.
 */
template <typename T>
uint32_t sortAndCount(T *arr, T *scratch, uint32_t left, uint32_t right) {
    if (left >= right) return 0;

    uint32_t mid = left + (right - left) / 2;
    uint32_t total = 0;
    total += sortAndCount(arr, scratch, left, mid);
    total += sortAndCount(arr, scratch, mid + 1, right);
    total += mergeAndCount(arr, scratch, left, mid, right);
    return total;
}

/**
 * Public entry point: counts inversions in arr[0..size), sorting the array
 * as a side effect.
 */
template <class T>
uint32_t countInversion(T *arr, const uint32_t size) {
    std::vector<T> scratch(size);
    return sortAndCount(arr, scratch.data(), 0, size - 1);
}

/**
 * Simple debug helper that prints every element of an array.
 */
template <typename T>
void show(T *arr, const uint32_t size) {
    std::cout << "Array contents: \n";
    for (uint32_t i = 0; i < size; ++i) std::cout << " " << arr[i];
    std::cout << "\n";
}

}  // namespace inversion
}  // namespace sorting

