#include <iostream>
using namespace std;

int Max(int Arr[], int N) {
    int max = Arr[0];
    for (int i = 1; i < N; i++)
        if (Arr[i] > max)
            max = Arr[i];
    return max;
}

int Min(int Arr[], int N) {
    int min = Arr[0];
    for (int i = 1; i < N; i++)
        if (Arr[i] < min)
            min = Arr[i];
    return min;
}

void Print(int Arr[], int N) {
    for (int i = 0; i < N; i++) cout << Arr[i] << ", ";
}

int *Counting_Sort(int Arr[], int N) {
    int max = Max(Arr, N);
    int min = Min(Arr, N);
    int *Sorted_Arr = new int[N];

    int *Count = new int[max - min + 1];
    for (int i = 0; i < max - min + 1; ++i) {
        Count[i] = 0;
    }

    for (int i = 0; i < N; i++) Count[Arr[i] - min]++;

    for (int i = 1; i < (max - min + 1); i++) Count[i] += Count[i - 1];

    for (int i = N - 1; i >= 0; i--) {
        Sorted_Arr[Count[Arr[i] - min] - 1] = Arr[i];
        Count[Arr[i] - min]--;
    }

    delete[] Count;
    return Sorted_Arr;
}

int main() {
    int Arr[] = {47, 65, 20, 66, 25, 53, 64, 69, 72, 22,
                 74, 25, 53, 15, 42, 36, 4,  69, 86, 19},
        N = 20;
    int *Sorted_Arr;

    cout << "\n\tOrignal Array = ";
    Print(Arr, N);
    Sorted_Arr = Counting_Sort(Arr, N);
    cout << "\n\t Sorted Array = ";
    Print(Sorted_Arr, N);
    delete[] Sorted_Arr;
    cout << endl;

    return 0;
}

#include <iostream>
using namespace std;

// Scans the buffer and reports the largest value found.
int findLargest(int data[], int length) {
    int best = data[0];
    for (int idx = 1; idx < length; idx++) {
        if (data[idx] > best) {
            best = data[idx];
        }
    }
    return best;
}

// Scans the buffer and reports the smallest value found.
int findSmallest(int data[], int length) {
    int best = data[0];
    for (int idx = 1; idx < length; idx++) {
        if (data[idx] < best) {
            best = data[idx];
        }
    }
    return best;
}

// Dumps the contents of a buffer to stdout, comma separated.
void dumpBuffer(int data[], int length) {
    for (int idx = 0; idx < length; idx++) {
        cout << data[idx] << ", ";
    }
}

// Classic counting sort: builds a frequency table shifted by the
// minimum value, turns it into a prefix-sum table, then places
// each element into its final position by walking the input in reverse
// (reverse traversal keeps the sort stable).
int *countingSortBuffer(int data[], int length) {
    int hi = findLargest(data, length);
    int lo = findSmallest(data, length);
    int range = hi - lo + 1;

    int *result = new int[length];
    int *freq = new int[range];

    for (int idx = 0; idx < range; idx++) {
        freq[idx] = 0;
    }

    for (int idx = 0; idx < length; idx++) {
        freq[data[idx] - lo]++;
    }

    for (int idx = 1; idx < range; idx++) {
        freq[idx] += freq[idx - 1];
    }

    for (int idx = length - 1; idx >= 0; idx--) {
        int bucket = data[idx] - lo;
        result[freq[bucket] - 1] = data[idx];
        freq[bucket]--;
    }

    delete[] freq;
    return result;
}

int main() {
    int values[] = {47, 65, 20, 66, 25, 53, 64, 69, 72, 22,
                     74, 25, 53, 15, 42, 36, 4,  69, 86, 19};
    int total = 20;

    cout << "\n\tBefore sorting = ";
    dumpBuffer(values, total);

    int *sortedValues = countingSortBuffer(values, total);

    cout << "\n\tAfter sorting  = ";
    dumpBuffer(sortedValues, total);

    delete[] sortedValues;
    cout << endl;

    return 0;
}

// C++ Program for counting sort
#include <iostream>

using namespace std;

void countSort(string arr) {
    string output;

    int count[256], i;
    for (int i = 0; i < 256; i++) count[i] = 0;

    for (i = 0; arr[i]; ++i) ++count[arr[i]];

    for (i = 1; i < 256; ++i) count[i] += count[i - 1];

    for (i = 0; arr[i]; ++i) {
        output[count[arr[i]] - 1] = arr[i];
        --count[arr[i]];
    }

    for (i = 0; arr[i]; ++i) arr[i] = output[i];

    cout << "Sorted character array is " << arr;
}

int main() {
    string arr;
    cin >> arr;

    countSort(arr);

    return 0;
}

// Counting sort applied to the characters of a string.
#include <iostream>

using namespace std;

const int ALPHABET = 256;

// Rearranges the characters of `text` into ascending order using
// a frequency histogram over the byte range [0, 256).
void sortCharacters(string text) {
    string rearranged = text;

    int histogram[ALPHABET];
    for (int k = 0; k < ALPHABET; k++) {
        histogram[k] = 0;
    }

    int pos = 0;
    while (text[pos]) {
        histogram[(unsigned char)text[pos]]++;
        pos++;
    }

    for (int k = 1; k < ALPHABET; k++) {
        histogram[k] += histogram[k - 1];
    }

    pos = 0;
    while (text[pos]) {
        unsigned char ch = text[pos];
        rearranged[histogram[ch] - 1] = ch;
        histogram[ch]--;
        pos++;
    }

    pos = 0;
    while (text[pos]) {
        text[pos] = rearranged[pos];
        pos++;
    }

    cout << "Sorted character array is " << text;
}

int main() {
    string word;
    cin >> word;

    sortCharacters(word);

    return 0;
}

/**
 * @file
 * @brief Implementation of [Cycle
 * sort](https://en.wikipedia.org/wiki/Cycle_sort) algorithm
 * @details
 * Cycle Sort is a sorting algorithm that works in \f$O(n^2)\f$ time in the best
 * case and works in \f$O(n^2)\f$ in worst case. If a element is already at its
 * correct  position, do nothing. If a element is not at its correct position,
 * we then need to move it to its correct position by computing the correct
 * positions.Therefore, we should make sure the duplicate elements.
 * @author [TsungHan Ho](https://github.com/dalaoqi)
 */

#include <algorithm>  /// for std::is_sorted, std::swap
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>   /// for io operations
#include <vector>     /// for std::vector

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace cycle_sort
 * @brief Functions for [Cycle sort](https://en.wikipedia.org/wiki/Cycle_sort)
 * algorithm
 */
namespace cycle_sort {
/**
 * @brief The main function implements cycleSort
 * @tparam T type of array
 * @param in_arr array to be sorted
 * @returns void
 */
template <typename T>
std::vector<T> cycleSort(const std::vector<T> &in_arr) {
    std::vector<T> arr(in_arr);
    for (int cycle_start = 0; cycle_start <= arr.size() - 1; cycle_start++) {
        // initialize item
        T item = arr[cycle_start];

        // Count the number of elements smaller than item, this  number is the
        // correct index of item.
        int pos = cycle_start;
        for (int i = cycle_start + 1; i < arr.size(); i++) {
            if (arr[i] < item) {
                pos++;
            }
        }

        // item is already in correct position
        if (pos == cycle_start) {
            continue;
        }

        // duplicate  elements
        while (item == arr[pos]) pos += 1;
        if (pos == cycle_start) {
            continue;
        } else {
            std::swap(item, arr[pos]);
        }
        // Rest of the  elements
        while (pos != cycle_start) {
            pos = cycle_start;
            // Find position where we put the element
            for (size_t i = cycle_start + 1; i < arr.size(); i++) {
                if (arr[i] < item) {
                    pos += 1;
                }
            }
            // duplicate  elements
            while (item == arr[pos]) pos += 1;
            if (item == arr[pos]) {
                continue;
            } else {
                std::swap(item, arr[pos]);
            }
        }
    }
    return arr;
}
}  // namespace cycle_sort
}  // namespace sorting

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // Test 1
    // [4, 3, 2, 1] return [1, 2, 3, 4]
    std::vector<uint32_t> array1 = {4, 3, 2, 1};
    std::cout << "Test 1... ";
    std::vector<uint32_t> arr1 = sorting::cycle_sort::cycleSort(array1);
    assert(std::is_sorted(std::begin(arr1), std::end(arr1)));
    std::cout << "passed" << std::endl;

    // [4.3, -6.5, -7.4, 0, 2.7, 1.8] return [-7.4, -6.5, 0, 1.8, 2.7, 4.3]
    std::vector<double> array2 = {4.3, -6.5, -7.4, 0, 2.7, 1.8};
    std::cout << "Test 2... ";
    std::vector<double> arr2 = sorting::cycle_sort::cycleSort(array2);
    assert(std::is_sorted(std::begin(arr2), std::end(arr2)));
    std::cout << "passed" << std::endl;

    // Test 3
    // [3, 3, 3, 3] return [3, 3, 3, 3]
    std::vector<uint32_t> array3 = {3, 3, 3, 3};
    std::cout << "Test 3... ";
    std::vector<uint32_t> arr3 = sorting::cycle_sort::cycleSort(array3);
    assert(std::is_sorted(std::begin(arr3), std::end(arr3)));
    std::cout << "passed" << std::endl;

    // [9, 4, 6, 8, 14, 3] return [9, 4, 6, 8, 14, 3]
    std::vector<uint32_t> array4 = {3, 4, 6, 8, 9, 14};
    std::cout << "Test 4... ";
    std::vector<uint32_t> arr4 = sorting::cycle_sort::cycleSort(array4);
    assert(std::is_sorted(std::begin(arr4), std::end(arr4)));
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // execute the test
    return 0;
}

/**
 * @file
 * @brief Reimplementation of the [Cycle
 * sort](https://en.wikipedia.org/wiki/Cycle_sort) algorithm.
 * @details
 * Cycle sort minimizes the number of writes to the underlying array: every
 * element is moved directly to its final resting place, computed by counting
 * how many other elements are smaller than it. Its runtime is quadratic in
 * both the average and worst case, but it guarantees each value is written
 * at most once (aside from duplicates), which matters when writes are
 * expensive.
 */

#include <algorithm>  /// for std::is_sorted, std::swap
#include <cassert>    /// for assert
#include <cstdint>
#include <iostream>  /// for io operations
#include <vector>    /// for std::vector

namespace sorting {
namespace cyclic_placement {

/**
 * @brief Sorts a copy of the input vector using the cycle-sort strategy.
 * @tparam ValueT element type stored in the vector
 * @param source vector to be sorted (left untouched)
 * @returns a newly built, sorted vector
 */
template <typename ValueT>
std::vector<ValueT> sortByCycles(const std::vector<ValueT> &source) {
    std::vector<ValueT> data(source);
    const size_t total = data.size();

    for (size_t start = 0; start + 1 <= total && start < total; start++) {
        ValueT candidate = data[start];

        // Determine how many entries to the right are strictly smaller;
        // that count tells us candidate's correct slot.
        size_t target = start;
        for (size_t scan = start + 1; scan < total; scan++) {
            if (data[scan] < candidate) {
                target++;
            }
        }

        if (target == start) {
            // Already resting in the right spot.
            continue;
        }

        // Skip past any equal values to keep duplicates untouched.
        while (candidate == data[target]) {
            target++;
        }
        if (target == start) {
            continue;
        }
        std::swap(candidate, data[target]);

        // Keep cycling the displaced value into its own correct slot
        // until we loop back around to the starting index.
        while (target != start) {
            target = start;
            for (size_t scan = start + 1; scan < total; scan++) {
                if (data[scan] < candidate) {
                    target++;
                }
            }
            while (candidate == data[target]) {
                target++;
            }
            if (candidate == data[target]) {
                continue;
            }
            std::swap(candidate, data[target]);
        }
    }
    return data;
}

}  // namespace cyclic_placement
}  // namespace sorting

/**
 * @brief Runs a handful of sanity checks against sortByCycles.
 * @returns void
 */
static void runChecks() {
    std::cout << "Check A... ";
    std::vector<uint32_t> descending = {4, 3, 2, 1};
    auto resultA = sorting::cyclic_placement::sortByCycles(descending);
    assert(std::is_sorted(std::begin(resultA), std::end(resultA)));
    std::cout << "ok" << std::endl;

    std::cout << "Check B... ";
    std::vector<double> mixedDoubles = {4.3, -6.5, -7.4, 0, 2.7, 1.8};
    auto resultB = sorting::cyclic_placement::sortByCycles(mixedDoubles);
    assert(std::is_sorted(std::begin(resultB), std::end(resultB)));
    std::cout << "ok" << std::endl;

    std::cout << "Check C... ";
    std::vector<uint32_t> allSame = {3, 3, 3, 3};
    auto resultC = sorting::cyclic_placement::sortByCycles(allSame);
    assert(std::is_sorted(std::begin(resultC), std::end(resultC)));
    std::cout << "ok" << std::endl;

    std::cout << "Check D... ";
    std::vector<uint32_t> alreadySorted = {3, 4, 6, 8, 9, 14};
    auto resultD = sorting::cyclic_placement::sortByCycles(alreadySorted);
    assert(std::is_sorted(std::begin(resultD), std::end(resultD)));
    std::cout << "ok" << std::endl;
}

