 * @returns 0 on exit
 */
int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [gnome
 * sort](https://en.wikipedia.org/wiki/Gnome_sort) algorithm.
 * @author [beqakd](https://github.com/beqakd)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @details
 * Gnome sort algorithm is not the best one but it is widely used.
 * The algorithm iteratively checks the order of pairs in the array. If they are
 * on right order it moves to the next successive pair, otherwise it swaps
 * elements. This operation is repeated until no more swaps are made thus
 * indicating the values to be in ascending order.
 *
 * The time Complexity of the algorithm is \f$O(n^2)\f$ and in some cases it
 * can be \f$O(n)\f$.
 */

#include <algorithm>  // for std::swap
#include <array>      // for std::array
#include <cassert>    // for assertions
#include <iostream>   // for io operations

/**
 * @namespace sorting
 * Sorting algorithms
 */
namespace sorting {
/**
 * This implementation is for a C-style array input that gets modified in place.
 * @param [in,out] arr our array of elements.
 * @param size size of given array
 */
template <typename T>
void gnomeSort(T *arr, int size) {
    // few easy cases
    if (size <= 1) {
        return;
    }

    int index = 0;  // initialize some variables.
    while (index < size) {
        // check for swap
        if ((index == 0) || (arr[index] >= arr[index - 1])) {
            index++;
        } else {
            std::swap(arr[index], arr[index - 1]);  // swap
            index--;
        }
    }
}

/**
 * This implementation is for a C++-style array input. The function argument is
 * a pass-by-value and hence a copy of the array gets created which is then
 * modified by the function and returned.
 * @tparam T type of data variables in the array
 * @tparam size size of the array
 * @param [in] arr our array of elements.
 * @return array with elements sorted
 */
template <typename T, size_t size>
std::array<T, size> gnomeSort(std::array<T, size> arr) {
    // few easy cases
    if (size <= 1) {
        return arr;
    }

    int index = 0;  // initialize loop index
    while (index < size) {
        // check for swap
        if ((index == 0) || (arr[index] >= arr[index - 1])) {
            index++;
        } else {
            std::swap(arr[index], arr[index - 1]);  // swap
            index--;
        }
    }
    return arr;
}
}  // namespace sorting

/**
 * Test function
 */
static void test() {
    // Example 1. Creating array of int,
    std::cout << "Test 1 - as a C-array...";
    const int size = 6;
    std::array<int, size> arr = {-22, 100, 150, 35, -10, 99};
    sorting::gnomeSort(arr.data(),
                       size);  // pass array data as a C-style array pointer
    assert(std::is_sorted(std::begin(arr), std::end(arr)));
    std::cout << " Passed\n";
    for (int i = 0; i < size; i++) {
        std::cout << arr[i] << ", ";
    }
    std::cout << std::endl;

    // Example 2. Creating array of doubles.
    std::cout << "\nTest 2 - as a std::array...";
    std::array<double, size> double_arr = {-100.2, 10.2, 20.0, 9.0, 7.5, 7.2};
    std::array<double, size> sorted_arr = sorting::gnomeSort(double_arr);
    assert(std::is_sorted(std::begin(sorted_arr), std::end(sorted_arr)));
    std::cout << " Passed\n";
    for (int i = 0; i < size; i++) {
        std::cout << double_arr[i] << ", ";
    }
    std::cout << std::endl;

    // Example 3. Creating random array of float.
    std::cout << "\nTest 3 - 200 random numbers as a std::array...";
    const int size2 = 200;
    std::array<float, size2> rand_arr{};

    for (auto &a : rand_arr) {
        // generate random numbers between -5.0 and 4.99
        a = float(std::rand() % 1000 - 500) / 100.f;
    }

    std::array<float, size2> float_arr = sorting::gnomeSort(rand_arr);
    assert(std::is_sorted(std::begin(float_arr), std::end(float_arr)));
    std::cout << " Passed\n";
    // for (int i = 0; i < size; i++) std::cout << double_arr[i] << ", ";
    std::cout << std::endl;
}

/**
 * Our main function with example of sort method.
 */
int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief Reimplementation of [gnome
 * sort](https://en.wikipedia.org/wiki/Gnome_sort).
 * @details
 * Gnome sort behaves like a garden gnome sorting flower pots: it looks at
 * the pot next to it and the one before it. If they are in the right
 * order, it steps forward one pot. If not, it swaps them and steps
 * backward one pot. It keeps doing this until it reaches the end of the
 * row. It is simple to implement but not particularly fast, sitting at
 * O(n^2) in general with O(n) behavior on nearly-sorted input.
 */

#include <algorithm>  // for std::swap
#include <array>      // for std::array
#include <cassert>    // for assertions
#include <iostream>   // for io operations

namespace sorting {

/**
 * @brief In-place gnome sort over a raw pointer / C-style array.
 * @tparam ValueT element type
 * @param items pointer to first element of the array
 * @param count number of elements in the array
 */
template <typename ValueT>
void gnomeSortInPlace(ValueT *items, int count) {
    if (count <= 1) {
        return;
    }

    int cursor = 0;
    while (cursor < count) {
        bool atStartOrOrdered =
            (cursor == 0) || (items[cursor] >= items[cursor - 1]);
        if (atStartOrOrdered) {
            cursor++;
        } else {
            std::swap(items[cursor], items[cursor - 1]);
            cursor--;
        }
    }
}

/**
 * @brief Value-semantics gnome sort over a std::array; returns a sorted copy.
 * @tparam ValueT element type
 * @tparam count number of elements
 * @param items array to sort (received by value)
 * @return sorted array
 */
template <typename ValueT, size_t count>
std::array<ValueT, count> gnomeSortCopy(std::array<ValueT, count> items) {
    if (count <= 1) {
        return items;
    }

    int cursor = 0;
    while (cursor < static_cast<int>(count)) {
        bool atStartOrOrdered =
            (cursor == 0) || (items[cursor] >= items[cursor - 1]);
        if (atStartOrOrdered) {
            cursor++;
        } else {
            std::swap(items[cursor], items[cursor - 1]);
            cursor--;
        }
    }
    return items;
}

}  // namespace sorting

/**
 * @brief Runs demonstration/verification cases for both overloads.
 */
static void runChecks() {
    std::cout << "Scenario 1 - raw C-array of ints... ";
    const int width = 6;
    std::array<int, width> ints = {-22, 100, 150, 35, -10, 99};
    sorting::gnomeSortInPlace(ints.data(), width);
    assert(std::is_sorted(std::begin(ints), std::end(ints)));
    std::cout << "passed\n";
    for (int i = 0; i < width; i++) {
        std::cout << ints[i] << ", ";
    }
    std::cout << std::endl;

    std::cout << "\nScenario 2 - std::array of doubles... ";
    std::array<double, width> doubles = {-100.2, 10.2, 20.0, 9.0, 7.5, 7.2};
    std::array<double, width> sortedDoubles = sorting::gnomeSortCopy(doubles);
    assert(std::is_sorted(std::begin(sortedDoubles), std::end(sortedDoubles)));
    std::cout << "passed\n";
    for (int i = 0; i < width; i++) {
        std::cout << doubles[i] << ", ";
    }
    std::cout << std::endl;

    std::cout << "\nScenario 3 - 200 random floats... ";
    const int bigWidth = 200;
    std::array<float, bigWidth> randomFloats{};

    for (auto &value : randomFloats) {
        value = float(std::rand() % 1000 - 500) / 100.f;
    }

    std::array<float, bigWidth> sortedFloats =
        sorting::gnomeSortCopy(randomFloats);
    assert(std::is_sorted(std::begin(sortedFloats), std::end(sortedFloats)));
    std::cout << "passed\n";
    std::cout << std::endl;
}

/**
 * @brief Program entry point.
 */
int main() {
    runChecks();
    return 0;
}

/**
 * \file
 * \brief [Heap Sort Algorithm
 * (heap sort)](https://en.wikipedia.org/wiki/Heapsort) implementation
 *
 * \author [Ayaan Khan](http://github.com/ayaankhan98)
 *
 * \details
 *  Heap-sort is a comparison-based sorting algorithm.
 *  Heap-sort can be thought of as an improved selection sort:
 *  like selection sort, heap sort divides its input into a sorted
 *  and an unsorted region, and it iteratively shrinks the unsorted
 *  region by extracting the largest element from it and inserting
 *  it into the sorted region. Unlike selection sort,
 *  heap sort does not waste time with a linear-time scan of the
 *  unsorted region; rather, heap sort maintains the unsorted region
 *  in a heap data structure to more quickly find the largest element
 *  in each step.
 *
 *  Time Complexity - \f$O(n \log(n))\f$
 *
 */
#include <algorithm>
#include <cassert>
#include <iostream>

/**
 *
 * Utility function to print the array after
 * sorting.
 *
 * @param arr array to be printed
 * @param sz size of array
 *
 */
template <typename T>
void printArray(T *arr, int sz) {
    for (int i = 0; i < sz; i++) std::cout << arr[i] << "  ";
    std::cout << "\n";
}

/**
 *
 * \addtogroup sorting Sorting Algorithm
 * @{
 *
 * The heapify procedure can be thought of as building a heap from
 * the bottom up by successively sifting downward to establish the
 * heap property.
 *
 * @param arr array to be sorted
 * @param n size of array
 * @param i node position in Binary Tress or element position in
 *          Array to be compared with it's childern
 *
 */
template <typename T>
void heapify(T *arr, int n, int i) {
    int largest = i;
    int l = 2 * i + 1;
    int r = 2 * i + 2;

    if (l < n && arr[l] > arr[largest])
        largest = l;

    if (r < n && arr[r] > arr[largest])
        largest = r;

    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        heapify(arr, n, largest);
    }
}

/**
 * Utilizes heapify procedure to sort
 * the array
 *
 * @param arr array to be sorted
 * @param n size of array
 *
 */
template <typename T>
void heapSort(T *arr, int n) {
    for (int i = n - 1; i >= 0; i--) heapify(arr, n, i);

    for (int i = n - 1; i >= 0; i--) {
        std::swap(arr[0], arr[i]);
        heapify(arr, i, 0);
    }
}

/**
 *
 * @}
 * Test cases to test the program
 *
 */
void test() {
    std::cout << "Test 1\n";
    int arr[] = {-10, 78, -1, -6, 7, 4, 94, 5, 99, 0};
    int sz = sizeof(arr) / sizeof(arr[0]);  // sz - size of array
    printArray(arr, sz);  // displaying the array before sorting
    heapSort(arr, sz);    // calling heapsort to sort the array
    printArray(arr, sz);  // display array after sorting
    assert(std::is_sorted(arr, arr + sz));
    std::cout << "Test 1 Passed\n========================\n";

    std::cout << "Test 2\n";
    double arr2[] = {4.5, -3.6, 7.6, 0, 12.9};
    sz = sizeof(arr2) / sizeof(arr2[0]);
    printArray(arr2, sz);
    heapSort(arr2, sz);
    printArray(arr2, sz);
    assert(std::is_sorted(arr2, arr2 + sz));
    std::cout << "Test 2 passed\n";
}

/** Main function */
int main() {
    test();
    return 0;
}

/**
 * \file
 * \brief Reimplementation of the [heap
 * sort](https://en.wikipedia.org/wiki/Heapsort) algorithm.
 *
 * \details
 * Heap sort builds a binary max-heap out of the input array, then
 * repeatedly pulls the maximum element (the heap root) to the end of the
 * unsorted region and restores the heap property on the shrinking prefix.
 * Because the heap is stored implicitly inside the array itself, no extra
 * memory beyond the input buffer is required.
 *
 * Time complexity - O(n log n)
 */
#include <algorithm>
#include <cassert>
#include <iostream>

/**
 * Prints every element of the buffer separated by two spaces.
 *
 * @param buffer array to print
 * @param count number of elements
 */
template <typename ValueT>
void showBuffer(ValueT *buffer, int count) {
    for (int idx = 0; idx < count; idx++) {
        std::cout << buffer[idx] << "  ";
    }
    std::cout << "\n";
}

/**
 * Restores the max-heap property for the subtree rooted at `root`,
 * assuming the subtrees below it already satisfy the heap property.
 * Sifts the value at `root` downward until both children (if any) are
 * no greater than it.
 *
 * @param buffer array representing the heap
 * @param heapSize number of elements currently part of the heap
 * @param root index of the subtree root to fix
 */
template <typename ValueT>
void siftDown(ValueT *buffer, int heapSize, int root) {
    int biggest = root;
    int leftChild = 2 * root + 1;
    int rightChild = 2 * root + 2;

    if (leftChild < heapSize && buffer[leftChild] > buffer[biggest]) {
        biggest = leftChild;
    }

    if (rightChild < heapSize && buffer[rightChild] > buffer[biggest]) {
        biggest = rightChild;
    }

    if (biggest != root) {
        std::swap(buffer[root], buffer[biggest]);
        siftDown(buffer, heapSize, biggest);
    }
}

/**
 * Sorts the buffer in place: first builds a max-heap out of the whole
 * array (bottom-up), then repeatedly swaps the root with the last
 * unsorted element and re-heapifies the reduced heap.
 *
 * @param buffer array to sort
 * @param count number of elements
 */
template <typename ValueT>
void heapSort(ValueT *buffer, int count) {
    for (int root = count / 2 - 1; root >= 0; root--) {
        siftDown(buffer, count, root);
    }

    for (int boundary = count - 1; boundary > 0; boundary--) {
        std::swap(buffer[0], buffer[boundary]);
        siftDown(buffer, boundary, 0);
    }
}

/**
 * Exercises heapSort against an integer array and a floating-point array.
 */
void runChecks() {
    std::cout << "Scenario 1\n";
    int ints[] = {-10, 78, -1, -6, 7, 4, 94, 5, 99, 0};
    int intCount = sizeof(ints) / sizeof(ints[0]);
    showBuffer(ints, intCount);
    heapSort(ints, intCount);
    showBuffer(ints, intCount);
    assert(std::is_sorted(ints, ints + intCount));
    std::cout << "Scenario 1 passed\n========================\n";

    std::cout << "Scenario 2\n";
    double doubles[] = {4.5, -3.6, 7.6, 0, 12.9};
    int doubleCount = sizeof(doubles) / sizeof(doubles[0]);
    showBuffer(doubles, doubleCount);
    heapSort(doubles, doubleCount);
    showBuffer(doubles, doubleCount);
    assert(std::is_sorted(doubles, doubles + doubleCount));
    std::cout << "Scenario 2 passed\n";
}

