/**
 * @file
 * @brief Implementation of the classic insertion sort routine.
 *
 * @details
 * Insertion sort grows a sorted prefix of the container one item at a
 * time: it repeatedly takes the next unsorted value and slides it
 * backwards past every already-sorted entry that is bigger than it.
 *
 * Why bother with an O(n^2) algorithm at all?
 *   - the logic fits in a handful of lines
 *   - on short or nearly-sorted inputs it beats fancier O(n log n) sorts
 *   - unlike selection sort it does far fewer comparisons in the best case
 *   - it is stable: two equal keys keep their original relative order
 *   - it can operate "online", sorting values as they arrive
 *
 * Think of how a card player sorts a hand: cards already held are in
 * order, and each newly drawn card is slotted into the correct spot
 * amongst them.
 *
 * Walkthrough on {4, 3, 2, 5, 1}:
 *   pick 3 -> shift 4 right -> {3, 4, 2, 5, 1}
 *   pick 2 -> shift 4,3 right -> {2, 3, 4, 5, 1}
 *   pick 5 -> already in place -> {2, 3, 4, 5, 1}
 *   pick 1 -> shift everything right -> {1, 2, 3, 4, 5}
 */

#include <algorithm>  /// for std::is_sorted
#include <cassert>    /// for assert
#include <iostream>   /// for std::cout / std::cin
#include <vector>     /// for std::vector

/** \namespace sorting
 * \brief Collection of sorting algorithm implementations
 */
namespace sorting {

/**
 * \brief Sorts a raw array in place using insertion sort.
 *
 * @tparam ValueT element type stored in the array
 * @param data pointer to the first element of the array
 * @param length number of elements pointed to by data
 */
template <typename ValueT>
void insertion_sort(ValueT *data, int length) {
    int cursor = 1;
    while (cursor < length) {
        ValueT pending = data[cursor];
        int hole = cursor - 1;

        while (hole >= 0 && pending < data[hole]) {
            data[hole + 1] = data[hole];
            --hole;
        }
        data[hole + 1] = pending;
        ++cursor;
    }
}

/**
 * \brief Sorts a std::vector in place using insertion sort.
 *
 * @tparam ValueT element type stored in the vector
 * @param data pointer to the vector to sort
 */
template <typename ValueT>
void insertion_sort(std::vector<ValueT> *data) {
    const size_t length = data->size();

    for (size_t cursor = 1; cursor < length; ++cursor) {
        ValueT pending = (*data)[cursor];
        long hole = static_cast<long>(cursor) - 1;

        while (hole >= 0 && pending < (*data)[hole]) {
            (*data)[hole + 1] = (*data)[hole];
            --hole;
        }
        (*data)[hole + 1] = pending;
    }
}

}  // namespace sorting

/**
 * @brief Fills a pre-allocated array with pseudo-random values.
 *
 * @tparam ValueT element type of the array
 * @param data array to populate
 * @param count number of elements to generate
 */
template <typename ValueT>
static void fill_with_noise(ValueT *data, int count) {
    for (int i = 0; i < count; ++i) {
        double sample = (std::rand() % 10000 - 5000) / 100.f;
        data[i] = static_cast<ValueT>(sample);
    }
}

