/**
 * @file
 * @brief An alternate take on the Insertion Sort algorithm.
 * @author A. Contributor
 *
 * @details
 * Insertion sort maintains a growing sorted region at the front of the
 * collection. On every step the next element outside that region is
 * pulled out and walked backwards through the sorted region until it
 * lands in its rightful spot.
 *
 * Reasons this simple O(n^2) approach still earns its keep:
 * - trivial to reason about and implement correctly
 * - performs very well on small inputs
 * - beats selection/bubble sort in typical cases despite same big-O class
 * - stable — equal keys never swap relative order
 *
 * It mirrors how a person sorts a hand of playing cards: hold the sorted
 * ones, and slot each new card into place as it is drawn.
 *
 * Best case is O(n) when the input is already sorted; worst/average case
 * remains O(n^2).
 *
 * Trace on [4, 3, 2, 5, 1]:
 *   -> [3, 4, 2, 5, 1]
 *   -> [2, 3, 4, 5, 1]
 *   -> unchanged, 5 stays
 *   -> [1, 2, 3, 4, 5]
 */

#include <algorithm>  /// std::is_sorted for validation
#include <cassert>    /// assert() for the self tests
#include <iostream>   /// console output
#include <vector>     /// std::vector support

/**
 * @namespace sorting
 * @brief Houses the sorting algorithm implementations in this project
 */
namespace sorting {

/**
 * @brief Insertion sort over a raw pointer/array.
 *
 * @tparam Elem type of the elements being sorted
 * @param items pointer to the array to sort in place
 * @param count number of elements in the array
 */
template <typename Elem>
void insertion_sort(Elem *items, int count) {
    int idx = 1;
    while (idx < count) {
        Elem carried = items[idx];
        int slot = idx - 1;

        while (slot >= 0 && carried < items[slot]) {
            items[slot + 1] = items[slot];
            slot--;
        }
        items[slot + 1] = carried;
        idx++;
    }
}

/**
 * @brief Insertion sort specialized for std::vector, sorting in place.
 *
 * @tparam Elem element type stored in the vector
 * @param items pointer to the vector to sort
 */
template <typename Elem>
void insertion_sort(std::vector<Elem> *items) {
    const size_t total = items->size();

    size_t idx = 1;
    while (idx < total) {
        Elem carried = items->at(idx);
        long slot = static_cast<long>(idx) - 1;

        while (slot >= 0 && carried < items->at(slot)) {
            items->at(slot + 1) = items->at(slot);
            slot--;
        }
        items->at(slot + 1) = carried;
        idx++;
    }
}

}  // namespace sorting

/**
 * @brief Populates an array with pseudo-random values for stress testing.
 *
 * @tparam Elem element type
 * @param items pre-allocated buffer to fill
 * @param total how many entries to generate
 */
template <typename Elem>
static void populate_randomly(Elem *items, int total) {
    for (int i = 0; i < total; ++i) {
        double sample = (std::rand() % 10000 - 5000) / 100.f;
        items[i] = static_cast<Elem>(sample);
    }
}

