#include <algorithm>
#include <iostream>

void librarySort(int *index, int n) {
    int lib_size, index_pos,
        *gaps,        // gaps
        *library[2];  // libraries

    bool target_lib, *numbered;

    for (int i = 0; i < 2; i++) library[i] = new int[n];

    gaps = new int[n + 1];
    numbered = new bool[n + 1];

    lib_size = 1;
    index_pos = 1;
    target_lib = 0;
    library[target_lib][0] = index[0];

    while (index_pos < n) {
        // binary search
        int insert = std::distance(
            library[target_lib],
            std::lower_bound(library[target_lib],
                             library[target_lib] + lib_size, index[index_pos]));

        // if there is no gap to insert a new index ...

        if (numbered[insert] == true) {
            int prov_size = 0, next_target_lib = !target_lib;

            // update library and clear gaps

            for (int i = 0; i <= n; i++) {
                if (numbered[i] == true) {
                    library[next_target_lib][prov_size] = gaps[i];
                    prov_size++;
                    numbered[i] = false;
                }

                if (i <= lib_size) {
                    library[next_target_lib][prov_size] =
                        library[target_lib][i];
                    prov_size++;
                }
            }

            target_lib = next_target_lib;
            lib_size = prov_size - 1;
        } else {
            numbered[insert] = true;
            gaps[insert] = index[index_pos];
            index_pos++;
        }
    }

    int index_pos_for_output = 0;
    for (int i = 0; index_pos_for_output < n; i++) {
        if (numbered[i] == true) {
            // std::cout << gaps[i] << std::endl;
            index[index_pos_for_output] = gaps[i];
            index_pos_for_output++;
        }

        if (i < lib_size) {
            // std::cout << library[target_lib][i] << std::endl;
            index[index_pos_for_output] = library[target_lib][i];
            index_pos_for_output++;
        }
    }
    delete[] numbered;
    delete[] gaps;
    for (int i = 0; i < 2; ++i) {
        delete[] library[i];
    }
}

int main() {
    // ---example--
    int index_ex[] = {-6, 5, 9, 1, 9, 1, 0, 1, -8, 4, -12};
    int n_ex = sizeof(index_ex) / sizeof(index_ex[0]);

    librarySort(index_ex, n_ex);
    std::cout << "sorted array :" << std::endl;
    for (int i = 0; i < n_ex; i++) std::cout << index_ex[i] << " ";
    std::cout << std::endl;

    /* --output--
    sorted array :
    -12 -8 -6 0 1 1 1 4 5 9 9
    */
}

// Library sort (a.k.a. gapped insertion sort): keeps a sparse working
// buffer with empty "gaps" scattered through it so that inserting a new
// element rarely requires shifting the whole array, then periodically
// rebuilds the buffer to redistribute gaps evenly.

#include <algorithm>
#include <iostream>

/**
 * Rearranges values in place, from smallest to largest, using the
 * library-sort (gapped insertion) technique.
 *
 * @param values array of ints to reorder
 * @param length how many entries values contains
 */
void gappedInsertionSort(int *values, int length) {
    int filledCount, cursor;
    int *slack;          // records the value stashed in a rebuilt-in gap
    int *buffers[2];     // two alternating working buffers
    bool activeBuffer;   // which of buffers[] is currently in use
    bool *occupied;      // marks which gap slots hold a value

    for (int b = 0; b < 2; b++) {
        buffers[b] = new int[length];
    }

    slack = new int[length + 1];
    occupied = new bool[length + 1];
    for (int i = 0; i <= length; i++) {
        occupied[i] = false;
    }

    filledCount = 1;
    cursor = 1;
    activeBuffer = false;
    buffers[activeBuffer][0] = values[0];

    while (cursor < length) {
        // Locate where the next value belongs via binary search.
        int *begin = buffers[activeBuffer];
        int *end = buffers[activeBuffer] + filledCount;
        int position = std::distance(begin, std::lower_bound(begin, end, values[cursor]));

        if (occupied[position]) {
            // No free gap here — rebuild into the other buffer, spreading
            // gaps back out evenly.
            int rebuiltCount = 0;
            bool nextBuffer = !activeBuffer;

            for (int i = 0; i <= length; i++) {
                if (occupied[i]) {
                    buffers[nextBuffer][rebuiltCount] = slack[i];
                    rebuiltCount++;
                    occupied[i] = false;
                }

                if (i <= filledCount) {
                    buffers[nextBuffer][rebuiltCount] = buffers[activeBuffer][i];
                    rebuiltCount++;
                }
            }

            activeBuffer = nextBuffer;
            filledCount = rebuiltCount - 1;
        } else {
            occupied[position] = true;
            slack[position] = values[cursor];
            cursor++;
        }
    }

    // Flatten the gapped buffer back into a contiguous sorted sequence.
    int written = 0;
    for (int i = 0; written < length; i++) {
        if (occupied[i]) {
            values[written] = slack[i];
            written++;
        }

        if (i < filledCount) {
            values[written] = buffers[activeBuffer][i];
            written++;
        }
    }

    delete[] occupied;
    delete[] slack;
    for (int b = 0; b < 2; ++b) {
        delete[] buffers[b];
    }
}

int main() {
    // ---- demo ----
    int sample[] = {-6, 5, 9, 1, 9, 1, 0, 1, -8, 4, -12};
    int sampleLen = sizeof(sample) / sizeof(sample[0]);

    gappedInsertionSort(sample, sampleLen);

    std::cout << "sorted result:" << std::endl;
    for (int i = 0; i < sampleLen; i++) {
        std::cout << sample[i] << " ";
    }
    std::cout << std::endl;

    /* expected output:
    sorted result:
    -12 -8 -6 0 1 1 1 4 5 9 9
    */
    return 0;
}

/**
 * @file
 * @author [@sinkyoungdeok](https://github.com/sinkyoungdeok)
 * @author [Krishna Vedala](https://github.com/kvedala)
 * @brief Algorithm that combines insertion sort and merge sort. [Wiki
 * link](https://en.wikipedia.org/wiki/Merge-insertion_sort)
 *
 * @see Individual algorithms: insertion_sort.cpp and merge_sort.cpp
 */
#include <algorithm>
#include <array>
#include <cassert>
#include <ctime>
#include <iostream>
#include <memory>

/** \namespace sorting
 * \brief Sorting algorithms
 */
namespace sorting {
/** \namespace merge_insertion
 * \brief Combined Intersion-Merge sorting algorithm
 */
namespace merge_insertion {

/**
 * @brief Insertion merge algorithm
 * @see insertion_sort.cpp
 *
 * @tparam T array data type
 * @tparam N length of array
 * @param A pointer to array to sort
 * @param start start index of sorting window
 * @param end end index of sorting window
 */
template <typename T, size_t N>
static void InsertionSort(std::array<T, N> *A, size_t start, size_t end) {
    size_t i = 0, j = 0;
    T *ptr = A->data();

    for (i = start; i < end; i++) {
        T temp = ptr[i];
        j = i;
        while (j > start && temp < ptr[j - 1]) {
            ptr[j] = ptr[j - 1];
            j--;
        }
        //   for (j = i; j > start && temp < ptr[j - 1]; --j) {
        //       ptr[j] = ptr[j - 1];
        //   }

        ptr[j] = temp;
    }
}

/**
 * @brief Perform merge of data in a window
 *
 * @tparam T array data type
 * @tparam N length of array
 * @param A pointer to array to sort
 * @param min start index of window
 * @param max end index of window
 * @param mid mid-point of window
 */
template <typename T, size_t N>
static void merge(std::array<T, N> *array, size_t min, size_t max, size_t mid) {
    size_t firstIndex = min;
    size_t secondIndex = mid + 1;

    auto ptr = array->data();
    std::array<T, N + 1> tempArray{0};

    // While there are elements in the left or right runs
    for (size_t index = min; index <= max; index++) {
        // If left run head exists and is <= existing right run head.
        if (firstIndex <= mid &&
            (secondIndex > max || ptr[firstIndex] <= ptr[secondIndex])) {
            tempArray[index] = ptr[firstIndex];
            firstIndex++;
        } else {
            tempArray[index] = ptr[secondIndex];
            secondIndex++;
        }
    }

    // transfer to the initial array
    memcpy(ptr + min, tempArray.data() + min, (max - min) * sizeof(T));
    //  for (int index = min; index <= max; index++) ptr[index] =
    //  tempArray[index];
}

/**
 * @brief Final combined algorithm.
 * Algorithm utilizes ::sorting::merge_insertion::InsertionSort if window length
 * is less than threshold, else performs merge sort recursively using
 * ::sorting::merge_insertion::mergeSort
 *
 * @tparam T array data type
 * @tparam N length of array
 * @param A pointer to array to sort
 * @param min start index of sort window
 * @param max end index of sort window
 * @param threshold window length threshold
 */
template <typename T, size_t N>
void mergeSort(std::array<T, N> *array, size_t min, size_t max,
               size_t threshold) {
    // prerequisite
    if ((max - min) <= threshold) {
        InsertionSort(array, min, max);
    } else {
        // get the middle point
        size_t mid = (max + min) >> 1;

        // apply merge sort to both parts of this
        mergeSort(array, min, mid, threshold);
        mergeSort(array, mid, max, threshold);

        // and finally merge all that sorted stuff
        merge(array, min, max, mid);
    }
}

}  // namespace merge_insertion
}  // namespace sorting

/**
 * @brief Function to test code using random arrays
 * @returns none
 */
static void test() {
    constexpr size_t size = 30;
    std::array<int, size> array{0};
    // input
    for (int i = 0; i < size; i++) {
        array[i] = std::rand() % 100 - 50;
        std::cout << array[i] << " ";
    }
    std::cout << std::endl;

    sorting::merge_insertion::InsertionSort(&array, 0, size);
    //  sorting::merge_insertion::mergeSort(&array, 0, size, 10);

    // output
    for (int i = 0; i < size; ++i) {
        std::cout << array[i] << " ";
    }
    std::cout << std::endl;

    assert(std::is_sorted(std::begin(array), std::end(array)));
    std::cout << "Test passed\n";
}

/**
 * @brief Main function
 * @return 0 on exit
 */
int main() {
    std::srand(std::time(nullptr));
    test();
    return 0;
}

/**
 * Hybrid sort: plain insertion sort for small windows, merge sort for
 * larger ones. Small windows are cheap to insertion-sort and avoid the
 * overhead of recursive splitting/merging, while larger windows still
 * benefit from merge sort's O(n log n) behaviour.
 *
 * See also: insertion_sort.cpp and merge_sort.cpp for the standalone
 * versions of each half of this hybrid.
 */
#include <algorithm>
#include <array>
#include <cassert>
#include <cstring>
#include <ctime>
#include <iostream>
#include <memory>

namespace sorting {
namespace merge_insertion {

/**
 * Plain insertion sort restricted to the half-open window [start, end).
 */
template <typename T, size_t N>
static void windowedInsertionSort(std::array<T, N> *data, size_t start,
                                  size_t end) {
    T *raw = data->data();

    for (size_t i = start; i < end; ++i) {
        T current = raw[i];
        size_t j = i;
        while (j > start && current < raw[j - 1]) {
            raw[j] = raw[j - 1];
            --j;
        }
        raw[j] = current;
    }
}

/**
 * Merges the two sorted runs [min, mid] and (mid, max] back into one
 * sorted run occupying [min, max].
 */
template <typename T, size_t N>
static void combineRuns(std::array<T, N> *data, size_t min, size_t max,
                        size_t mid) {
    size_t left = min;
    size_t right = mid + 1;

    T *raw = data->data();
    std::array<T, N + 1> staging{0};

    for (size_t pos = min; pos <= max; ++pos) {
        if (left <= mid && (right > max || raw[left] <= raw[right])) {
            staging[pos] = raw[left++];
        } else {
            staging[pos] = raw[right++];
        }
    }

    memcpy(raw + min, staging.data() + min, (max - min) * sizeof(T));
}

/**
 * Recursively sorts window [min, max]. Windows at or below `threshold`
 * elements are handled with windowedInsertionSort; larger windows are
 * split, recursed into, and merged back together with combineRuns.
 */
template <typename T, size_t N>
void hybridSort(std::array<T, N> *data, size_t min, size_t max,
                size_t threshold) {
    if ((max - min) <= threshold) {
        windowedInsertionSort(data, min, max);
        return;
    }

    size_t mid = (max + min) >> 1;
    hybridSort(data, min, mid, threshold);
    hybridSort(data, mid, max, threshold);
    combineRuns(data, min, max, mid);
}

}  // namespace merge_insertion
}  // namespace sorting

/**
 * Generates random data, sorts it, and confirms the result is ordered.
 */
static void runChecks() {
    constexpr size_t length = 30;
    std::array<int, length> data{0};

    for (size_t i = 0; i < length; ++i) {
        data[i] = std::rand() % 100 - 50;
        std::cout << data[i] << " ";
    }
    std::cout << std::endl;

    sorting::merge_insertion::windowedInsertionSort(&data, 0, length);

    for (size_t i = 0; i < length; ++i) {
        std::cout << data[i] << " ";
    }
    std::cout << std::endl;

    assert(std::is_sorted(data.begin(), data.end()));
    std::cout << "All checks passed\n";
}

int main() {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));
    runChecks();
    return 0;
}

/**
 *  \addtogroup sorting Sorting Algorithms
 *  @{
 *  \file
 *  \brief [Merge Sort Algorithm
 *  (MERGE SORT)](https://en.wikipedia.org/wiki/Merge_sort) implementation
 *
 *  \author [Ayaan Khan](http://github.com/ayaankhan98)
 *
 *  \details
 *  Merge Sort is an efficient, general purpose, comparison
 *  based sorting algorithm.
 *  Merge Sort is a divide and conquer algorithm
 *  Time  Complexity: O(n log n) 
 *  It is  same for all best case, worst case or average case 
 *  Merge Sort is very efficient when for the small data. 
 *  In built-in sort function merge sort along with quick sort is used. 
 */
#include <iostream>
#include <vector>

/**
 *
 * The merge() function is used for merging two halves.
 * The merge(arr, l, m, r) is key process that assumes that
 * arr[l..m] and arr[m+1..r] are sorted and merges the two
 * sorted sub-arrays into one.
 *
 * @param arr - array with two halves arr[l...m] and arr[m+1...r]
 * @param l - left index or start index of first half array
 * @param m - right index or end index of first half array
 *
 * (The second array starts form m+1 and goes till r)
 *
 * @param r - end index or right index of second half array
 */
void merge(int *arr, int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;

    std::vector<int> L(n1), R(n2);

    for (int i = 0; i < n1; i++) L[i] = arr[l + i];
    for (int j = 0; j < n2; j++) R[j] = arr[m + 1 + j];

    int i = 0, j = 0, k = l;

    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        } else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

/**
 * Merge sort is a divide and conquer algorithm, it divides the
 * input array into two halves and calls itself for the two halves
 * and then calls merge() to merge the two halves
 *
 * @param arr - array to be sorted
 * @param l - left index or start index of array
 * @param r - right index or end index of array
 *
 */
void mergeSort(int *arr, int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

/**
 * Utility function used to print the array after
 * sorting
 */
void show(int *arr, int size) {
    for (int i = 0; i < size; i++) std::cout << arr[i] << " ";
    std::cout << "\n";
}

/** Main function */
int main() {
    int size;
    std::cout << "Enter the number of elements: ";
    std::cin >> size;

    if (size <= 0) {
        std::cout << "Invalid size.\n";
        return 1;
    }

    int *arr = new int[size];
    std::cout << "Enter the unsorted elements: ";
    for (int i = 0; i < size; ++i) {
        std::cin >> arr[i];
    }

    mergeSort(arr, 0, size - 1);
    std::cout << "Sorted array: ";
    show(arr, size);
    delete[] arr;
    return 0;
}
/** @} */

/**
 *  \addtogroup sorting Sorting Algorithms
 *  @{
 *  Merge sort, rewritten.
 *
 *  Merge sort is a comparison-based, divide-and-conquer sorting algorithm
 *  with guaranteed O(n log n) performance in every case (best, average, and
 *  worst), at the cost of needing auxiliary storage proportional to the
 *  input size. Many standard library sort implementations use a hybrid of
 *  merge sort and quicksort internally.
 */
#include <iostream>
#include <vector>

/**
 * Combines the two already-sorted runs arr[lo..mid] and arr[mid+1..hi]
 * into a single sorted run covering arr[lo..hi].
 *
 * @param arr backing array containing both runs
 * @param lo  start of the first run
 * @param mid end of the first run (second run starts at mid + 1)
 * @param hi  end of the second run
 */
void combineRuns(int *arr, int lo, int mid, int hi) {
    int leftLen = mid - lo + 1;
    int rightLen = hi - mid;

    std::vector<int> leftBuf(leftLen), rightBuf(rightLen);

    for (int i = 0; i < leftLen; ++i) leftBuf[i] = arr[lo + i];
    for (int j = 0; j < rightLen; ++j) rightBuf[j] = arr[mid + 1 + j];

    int i = 0, j = 0, writePos = lo;

    while (i < leftLen && j < rightLen) {
        if (leftBuf[i] <= rightBuf[j]) {
            arr[writePos++] = leftBuf[i++];
        } else {
            arr[writePos++] = rightBuf[j++];
        }
    }
    while (i < leftLen) arr[writePos++] = leftBuf[i++];
    while (j < rightLen) arr[writePos++] = rightBuf[j++];
}

/**
 * Recursively splits arr[lo..hi] into halves, sorts each half, then merges
 * them back together via combineRuns.
 */
void mergeSortRange(int *arr, int lo, int hi) {
    if (lo >= hi) return;

    int mid = lo + (hi - lo) / 2;
    mergeSortRange(arr, lo, mid);
    mergeSortRange(arr, mid + 1, hi);
    combineRuns(arr, lo, mid, hi);
}

/**
 * Prints every element of the array on one line.
 */
void printArray(const int *arr, int count) {
    for (int i = 0; i < count; ++i) std::cout << arr[i] << " ";
    std::cout << "\n";
}

int main() {
    int count;
    std::cout << "Enter the number of elements: ";
    std::cin >> count;

    if (count <= 0) {
        std::cout << "Invalid size.\n";
        return 1;
    }

    int *values = new int[count];
    std::cout << "Enter the unsorted elements: ";
    for (int i = 0; i < count; ++i) {
        std::cin >> values[i];
    }

    mergeSortRange(values, 0, count - 1);
    std::cout << "Sorted array: ";
    printArray(values, count);
    delete[] values;
    return 0;
}
/** @} */

/**
 * Copyright 2020 @author Albirair
 * @file
 *
 * A generic implementation of non-recursive merge sort.
 */
#include <cstddef>  // for size_t
#include <iostream>
#include <utility>  // for std::move & std::remove_reference_t

namespace sorting {
template <class Iterator>
void merge(Iterator, Iterator, const Iterator, char[]);
/// bottom-up merge sort which sorts elements in a non-decreasing order
/**
 * sorts elements non-recursively by breaking them into small segments,
 * merging adjacent segments into larger sorted segments, then increasing
 * the sizes of segments by factors of 2 and repeating the same process.
 * best-case = worst-case = O(n log(n))
 * @param first points to the first element
 * @param last points to 1-step past the last element
 * @param n the number of elements
 */
template <class Iterator>
void non_recursive_merge_sort(const Iterator first, const Iterator last,
                              const size_t n) {
    // create a buffer large enough to store all elements
    // dynamically allocated to comply with cpplint
    char* buffer = new char[n * sizeof(*first)];
    // buffer size can be optimized to largest power of 2 less than n
    // elements divide the container into equally-sized segments whose
    // length start at 1 and keeps increasing by factors of 2
    for (size_t length(1); length < n; length <<= 1) {
        // merge adjacent segments whose number is n / (length * 2)
        Iterator left(first);
        for (size_t counter(n / (length << 1)); counter; --counter) {
            Iterator right(left + length), end(right + length);
            merge(left, right, end, buffer);
            left = end;
        }
        // if the number of remaining elements (n * 2 % length) is longer
        // than a segment, merge the remaining elements
        if ((n & ((length << 1) - 1)) > length)
            merge(left, left + length, last, buffer);
    }
    delete[] buffer;
}
/// merges 2 sorted adjacent segments into a larger sorted segment
/**
 * best-case = worst-case = O(n)
 * @param l points to the left part
 * @param r points to the right part, end of left part
 * @param e points to end of right part
 * @param b points at the buffer
 */
template <class Iterator>
void merge(Iterator l, Iterator r, const Iterator e, char b[]) {
    // create 2 pointers to point at the buffer
    auto p(reinterpret_cast<std::remove_reference_t<decltype(*l)>*>(b)), c(p);
    // move the left part of the segment
    for (Iterator t(l); r != t; ++t) *p++ = std::move(*t);
    // while neither the buffer nor the right part has been exhausted
    // move the smallest element of the two back to the container
    while (e != r && c != p) *l++ = std::move(*r < *c ? *r++ : *c++);
    // notice only one of the two following loops will be executed
    // while the right part hasn't bee exhausted, move it back
    while (e != r) *l++ = std::move(*r++);
    // while the buffer hasn't bee exhausted, move it back
    while (c != p) *l++ = std::move(*c++);
}
/// bottom-up merge sort which sorts elements in a non-decreasing order
/**
 * @param first points to the first element
 * @param n the number of elements
 */
template <class Iterator>
void non_recursive_merge_sort(const Iterator first, const size_t n) {
    non_recursive_merge_sort(first, first + n, n);
}
/// bottom-up merge sort which sorts elements in a non-decreasing order
/**
 * @param first points to the first element
 * @param last points to 1-step past the last element
 */
template <class Iterator>
void non_recursive_merge_sort(const Iterator first, const Iterator last) {
    non_recursive_merge_sort(first, last, last - first);
}

}  // namespace sorting

using sorting::non_recursive_merge_sort;

int main() {
    int size;
    std::cout << "Enter the number of elements : ";
    std::cin >> size;
    int* arr = new int[size];
    for (int i = 0; i < size; ++i) {
        std::cout << "arr[" << i << "] = ";
        std::cin >> arr[i];
    }
    non_recursive_merge_sort(arr, size);
    std::cout << "Sorted array\n";
    for (int i = 0; i < size; ++i)
        std::cout << "arr[" << i << "] = " << arr[i] << '\n';
    delete[] arr;
    return 0;
}

/**
 * Bottom-up (iterative) merge sort.
 *
 * Instead of recursively splitting the input, this variant starts by
 * treating every single element as a sorted run of length 1, then
 * repeatedly merges adjacent runs into runs twice as long, doubling the
 * run length each pass until the whole range is one sorted run.
 * Best-case and worst-case complexity are both O(n log n).
 */
#include <cstddef>
#include <iostream>
#include <utility>

namespace sorting {

template <class Iterator>
void mergeRuns(Iterator, Iterator, const Iterator, char[]);

/**
 * Sorts elements in [first, last) into non-decreasing order using the
 * iterative bottom-up merge strategy.
 * @param first  points to the first element
 * @param last   points one past the last element
 * @param count  number of elements in the range
 */
template <class Iterator>
void bottomUpMergeSort(const Iterator first, const Iterator last,
                       const size_t count) {
    char *scratch = new char[count * sizeof(*first)];

    for (size_t runLen(1); runLen < count; runLen <<= 1) {
        Iterator windowStart(first);
        for (size_t pairsRemaining(count / (runLen << 1)); pairsRemaining;
             --pairsRemaining) {
            Iterator windowMid(windowStart + runLen), windowEnd(windowMid + runLen);
            mergeRuns(windowStart, windowMid, windowEnd, scratch);
            windowStart = windowEnd;
        }
        if ((count & ((runLen << 1) - 1)) > runLen) {
            mergeRuns(windowStart, windowStart + runLen, last, scratch);
        }
    }
    delete[] scratch;
}

/**
 * Merges two adjacent sorted runs [l, r) and [r, e) into one sorted run,
 * using `buffer` as scratch space for the left run.
 */
template <class Iterator>
void mergeRuns(Iterator l, Iterator r, const Iterator e, char buffer[]) {
    auto bufStart(reinterpret_cast<std::remove_reference_t<decltype(*l)> *>(buffer));
    auto bufCursor(bufStart);

    for (Iterator t(l); r != t; ++t) *bufCursor++ = std::move(*t);

    while (e != r && bufStart != bufCursor) {
        *l++ = std::move(*r < *bufStart ? *r++ : *bufStart++);
    }
    while (e != r) *l++ = std::move(*r++);
    while (bufStart != bufCursor) *l++ = std::move(*bufStart++);
}

/**
 * Convenience overload taking just a start iterator and element count.
 */
template <class Iterator>
void bottomUpMergeSort(const Iterator first, const size_t count) {
    bottomUpMergeSort(first, first + count, count);
}

/**
 * Convenience overload taking a [first, last) range with no explicit count.
 */
template <class Iterator>
void bottomUpMergeSort(const Iterator first, const Iterator last) {
    bottomUpMergeSort(first, last, last - first);
}

}  // namespace sorting

using sorting::bottomUpMergeSort;

int main() {
    int count;
    std::cout << "Enter the number of elements : ";
    std::cin >> count;
    int *values = new int[count];
    for (int i = 0; i < count; ++i) {
        std::cout << "values[" << i << "] = ";
        std::cin >> values[i];
    }
    bottomUpMergeSort(values, static_cast<size_t>(count));
    std::cout << "Sorted array\n";
    for (int i = 0; i < count; ++i) {
        std::cout << "values[" << i << "] = " << values[i] << '\n';
    }
    delete[] values;
    return 0;
}

// Using general algorithms to sort a collection of strings results in
// alphanumeric sort. If it is a numeric string, it leads to unnatural sorting

// eg, an array of strings 1,10,100,2,20,200,3,30,300
// would be sorted in that same order by using conventional sorting,
// even though we know the correct sorting order is 1,2,3,10,20,30,100,200,300

// This Programme uses a comparator to sort the array in Numerical order instead
// of Alphanumeric order

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

bool NumericSort(std::string a, std::string b) {
    while (a[0] == '0') {
        a.erase(a.begin());
    }
    while (b[0] == '0') {
        b.erase(b.begin());
    }
    int n = a.length();
    int m = b.length();
    if (n == m)
        return a < b;
    return n < m;
}

int main() {
    int n;
    std::cout << "Enter number of elements to be sorted Numerically\n";
    std::cin >> n;

    std::vector<std::string> v(n);
    std::cout << "Enter the string of Numbers\n";
    for (int i = 0; i < n; i++) {
        std::cin >> v[i];
    }

    sort(v.begin(), v.end());
    std::cout << "Elements sorted normally \n";
    for (int i = 0; i < n; i++) {
        std::cout << v[i] << " ";
    }
    std::cout << "\n";

    std::sort(v.begin(), v.end(), NumericSort);
    std::cout << "Elements sorted Numerically \n";
    for (int i = 0; i < n; i++) {
        std::cout << v[i] << " ";
    }

    return 0;
}

// Standard lexicographic sort on numeric strings produces an order that
// looks wrong to humans: "1", "10", "100", "2", "20" ... instead of the
// numerically expected "1", "2", "10", "20", "100".
//
// This little program demonstrates the difference by sorting the same
// input twice: once with the default (alphabetical) comparator, and once
// with a custom comparator that treats each token as an integer value.

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

namespace numeric_text_ordering {

// Strips any leading zero characters from a copy of the token so that
// comparisons aren't skewed by things like "007" vs "7".
std::string stripLeadingZeros(std::string token) {
    std::size_t pos = 0;
    while (pos < token.size() && token[pos] == '0') {
        ++pos;
    }
    return token.substr(pos);
}

// Comparator usable with std::sort: numbers are ordered first by digit
// count (a shorter numeric string is always smaller, assuming no leading
// zeros), and ties are broken with a plain lexicographic comparison,
// which is safe once both operands have equal length.
bool byNumericValue(const std::string &lhs, const std::string &rhs) {
    std::string cleanLhs = stripLeadingZeros(lhs);
    std::string cleanRhs = stripLeadingZeros(rhs);

    if (cleanLhs.size() != cleanRhs.size()) {
        return cleanLhs.size() < cleanRhs.size();
    }
    return cleanLhs < cleanRhs;
}

}  // namespace numeric_text_ordering

int main() {
    std::size_t count = 0;
    std::cout << "How many numeric strings would you like to sort?\n";
    std::cin >> count;

    std::vector<std::string> tokens(count);
    std::cout << "Type each number as text, separated by whitespace\n";
    for (std::size_t idx = 0; idx < count; ++idx) {
        std::cin >> tokens[idx];
    }

    std::vector<std::string> alphaOrder = tokens;
    std::sort(alphaOrder.begin(), alphaOrder.end());

    std::cout << "Default (lexicographic) ordering:\n";
    for (const auto &token : alphaOrder) {
        std::cout << token << " ";
    }
    std::cout << "\n";

    std::vector<std::string> numericOrder = tokens;
    std::sort(numericOrder.begin(), numericOrder.end(),
               numeric_text_ordering::byNumericValue);

    std::cout << "Numeric-aware ordering:\n";
    for (const auto &token : numericOrder) {
        std::cout << token << " ";
    }
    std::cout << "\n";

    return 0;
}

/* C++ implementation Odd Even Sort */
#include <iostream>
#include <vector>

using namespace std;

void oddEven(vector<int> &arr, int size) {
    bool sorted = false;
    while (!sorted) {
        sorted = true;
        for (int i = 1; i < size - 1; i += 2)  // Odd
        {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                sorted = false;
            }
        }

        for (int i = 0; i < size - 1; i += 2)  // Even
        {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                sorted = false;
            }
        }
    }
}

void show(vector<int> A, int size) {
    int i;
    for (i = 0; i < size; i++) cout << A[i] << "\n";
}

int main() {
    int size, temp;
    cout << "\nEnter the number of elements : ";
    cin >> size;

    vector<int> arr;

    cout << "\nEnter the unsorted elements : \n";

    for (int i = 0; i < size; ++i) {
        cin >> temp;
        arr.push_back(temp);
    }

    oddEven(arr, size);

    cout << "Sorted array\n";
    show(arr, size);
    return 0;
}

/* Brick sort (a.k.a. odd-even transposition sort), reimplemented with a
 * do-while driver loop and index-based helper functions instead of the
 * classic while(!sorted) shape. */
#include <iostream>
#include <vector>

namespace brick_sort_demo {

void swapEntries(std::vector<int> &data, std::size_t left, std::size_t right) {
    int tmp = data[left];
    data[left] = data[right];
    data[right] = tmp;
}

// Runs a single pass over odd-indexed neighbor pairs (1,2), (3,4), ...
// Returns true if any swap occurred during this pass.
bool oddPhase(std::vector<int> &data) {
    bool changed = false;
    for (std::size_t i = 1; i + 1 < data.size(); i += 2) {
        if (data[i] > data[i + 1]) {
            swapEntries(data, i, i + 1);
            changed = true;
        }
    }
    return changed;
}

// Runs a single pass over even-indexed neighbor pairs (0,1), (2,3), ...
// Returns true if any swap occurred during this pass.
bool evenPhase(std::vector<int> &data) {
    bool changed = false;
    for (std::size_t i = 0; i + 1 < data.size(); i += 2) {
        if (data[i] > data[i + 1]) {
            swapEntries(data, i, i + 1);
            changed = true;
        }
    }
    return changed;
}

void brickSort(std::vector<int> &data) {
    bool didSwap;
    do {
        bool a = oddPhase(data);
        bool b = evenPhase(data);
        didSwap = a || b;
    } while (didSwap);
}

void printAll(const std::vector<int> &data) {
    for (int value : data) {
        std::cout << value << "\n";
    }
}

}  // namespace brick_sort_demo

int main() {
    std::size_t count = 0;
    std::cout << "\nHow many values will you enter? ";
    std::cin >> count;

    std::vector<int> values;
    values.reserve(count);

    std::cout << "\nEnter the values, unsorted:\n";
    for (std::size_t i = 0; i < count; ++i) {
        int v;
        std::cin >> v;
        values.push_back(v);
    }

    brick_sort_demo::brickSort(values);

    std::cout << "Result after brick sort:\n";
    brick_sort_demo::printAll(values);
    return 0;
}

/**
 * @file
 * @brief pancake sort sorts a disordered stack of pancakes by flipping any
 * number of pancakes using a spatula using minimum number of flips.
 *
 * @details
 * Unlike a traditional sorting algorithm, which attempts to sort with the
 * fewest comparisons possible, the goal is to sort the sequence in as few
 * reversals as possible. Overall time complexity of pancake sort is O(n^2) For
 * example: example 1:- Disordered pancake sizes: {2,5,3,7,8} Sorted:
 * {2,3,5,7,8} For example: example 2:- Disordered pancake sizes:
 * {22,51,37,73,81} Sorted: {22,37,51,73,81}
 * @author [Divyansh Gupta](https://github.com/divyansh12323)
 * @see more on [Pancake sort](https://en.wikipedia.org/wiki/Pancake_sorting)
 * @see related problem at
 * [Leetcode](https://leetcode.com/problems/pancake-sorting/)
 */

#include <algorithm>  // for std::is_sorted
#include <cassert>    // for std::assert
#include <iostream>   // for io operations
#include <vector>     // for std::vector

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace pancake_sort
 * @brief Functions for [Pancake
 * sort](https://en.wikipedia.org/wiki/Pancake_sorting) algorithm
 */
namespace pancake_sort {
/**
 * @brief This implementation is for reversing elements in a a C-style array .
 * @param [start,end] arr our vector of elements.
 * @param start starting index of array
 * @param end ending index of array
 * @returns void
 */
template <typename T>
void reverse(std::vector<T> &arr, int start, int end) {
    T temp;  // Temporary variable
    while (start <= end) {
        temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}
/**
 * @brief This implementation is for a C-style array input that gets modified in
 * place.
 * @param [start,end] arr our vector of elements.
 * @param size size of given array
 * @returns 0 on exit
 */
template <typename T>
int pancakeSort(std::vector<T> &arr, int size) {
    for (int i = size; i > 1; --i) {
        int max_index = 0, j = 0;  // intialize some variables.
        T max_value = 0;
        for (j = 0; j < i; j++) {
            if (arr[j] >= max_value) {
                max_value = arr[j];
                max_index = j;
            }
        }
        if (max_index != i - 1)  // check for reversing
        {
            reverse(arr, 0, max_index);
            reverse(arr, 0, i - 1);
        }
    }
    return 0;
}
}  // namespace pancake_sort
}  // namespace sorting

/**
 * @brief Test implementations
 * @returns void
 */
static void test() {
    // example 1: vector of int
    const int size1 = 7;
    std::cout << "\nTest 1- as std::vector<int>...";
    std::vector<int> arr1 = {23, 10, 20, 11, 12, 6, 7};
    sorting::pancake_sort::pancakeSort(arr1, size1);
    assert(std::is_sorted(arr1.begin(), arr1.end()));
    std::cout << "Passed\n";
    for (int i = 0; i < size1; i++) {
        std::cout << arr1[i] << " ,";
    }
    std::cout << std::endl;

    // example 2: vector of double
    const int size2 = 8;
    std::cout << "\nTest 2- as std::vector<double>...";
    std::vector<double> arr2 = {23.56, 10.62, 200.78, 111.484,
                                3.9,   1.2,   61.77,  79.6};
    sorting::pancake_sort::pancakeSort(arr2, size2);
    assert(std::is_sorted(arr2.begin(), arr2.end()));
    std::cout << "Passed\n";
    for (int i = 0; i < size2; i++) {
        std::cout << arr2[i] << ", ";
    }
    std::cout << std::endl;

    // example 3:vector of float
    const int size3 = 7;
    std::cout << "\nTest 3- as std::vector<float>...";
    std::vector<float> arr3 = {6.56, 12.62, 200.78, 768.484, 19.27, 68.87, 9.6};
    sorting::pancake_sort::pancakeSort(arr3, size3);
    assert(std::is_sorted(arr3.begin(), arr3.end()));
    std::cout << "Passed\n";
    for (int i = 0; i < size3; i++) {
        std::cout << arr3[i] << ", ";
    }
    std::cout << std::endl;
}
/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();
    return 0;
}

/**
 * @file
 * @brief Alternate implementation of pancake sort: repeatedly find the
 * largest unplaced "pancake" and flip it to the top of the stack, then flip
 * the whole unsorted prefix so it lands at the end of its final region.
 *
 * @details
 * Pancake sort measures cost in flips (prefix reversals) rather than
 * comparisons or swaps. Each outer step performs at most two reversals, so
 * overall complexity stays O(n^2). This version renames the moving pieces
 * to "stack" terminology and drives the outer loop with decreasing stack
 * height via a while loop instead of a for loop.
 */

#include <algorithm>  // for std::is_sorted
#include <cassert>    // for assert
#include <iostream>   // for std::cout
#include <vector>     // for std::vector

namespace sorting {
namespace flip_stack_sort {

// Reverses the sub-range [lo, hi] of the stack in place -- this is the
// "spatula flip" operation.
template <typename T>
void flipRange(std::vector<T> &stack, int lo, int hi) {
    while (lo < hi) {
        T swapTmp = stack[lo];
        stack[lo] = stack[hi];
        stack[hi] = swapTmp;
        ++lo;
        --hi;
    }
}

// Finds the index of the biggest pancake within stack[0..limit].
template <typename T>
int indexOfLargest(const std::vector<T> &stack, int limit) {
    int best = 0;
    for (int k = 1; k <= limit; ++k) {
        if (stack[k] > stack[best]) {
            best = k;
        }
    }
    return best;
}

// Sorts `stack` (of the given `count` elements) using flip operations only.
template <typename T>
int stackSort(std::vector<T> &stack, int count) {
    int unsortedTop = count - 1;
    while (unsortedTop > 0) {
        int biggest = indexOfLargest(stack, unsortedTop);
        if (biggest != unsortedTop) {
            // Bring the largest remaining pancake to the front, then flip
            // it down to its resting place at unsortedTop.
            flipRange(stack, 0, biggest);
            flipRange(stack, 0, unsortedTop);
        }
        --unsortedTop;
    }
    return 0;
}

}  // namespace flip_stack_sort
}  // namespace sorting

// Reworded self-checks exercising int, double, and float stacks.
static void runChecks() {
    std::cout << "\nCheck 1 - std::vector<int> stack...";
    std::vector<int> intStack = {23, 10, 20, 11, 12, 6, 7};
    sorting::flip_stack_sort::stackSort(intStack, static_cast<int>(intStack.size()));
    assert(std::is_sorted(intStack.begin(), intStack.end()));
    std::cout << "OK\n";
    for (int v : intStack) std::cout << v << " ,";
    std::cout << std::endl;

    std::cout << "\nCheck 2 - std::vector<double> stack...";
    std::vector<double> dblStack = {23.56, 10.62, 200.78, 111.484,
                                     3.9,   1.2,   61.77,  79.6};
    sorting::flip_stack_sort::stackSort(dblStack, static_cast<int>(dblStack.size()));
    assert(std::is_sorted(dblStack.begin(), dblStack.end()));
    std::cout << "OK\n";
    for (double v : dblStack) std::cout << v << ", ";
    std::cout << std::endl;

    std::cout << "\nCheck 3 - std::vector<float> stack...";
    std::vector<float> fltStack = {6.56f, 12.62f, 200.78f, 768.484f,
                                    19.27f, 68.87f, 9.6f};
    sorting::flip_stack_sort::stackSort(fltStack, static_cast<int>(fltStack.size()));
    assert(std::is_sorted(fltStack.begin(), fltStack.end()));
    std::cout << "OK\n";
    for (float v : fltStack) std::cout << v << ", ";
    std::cout << std::endl;
}

int main() {
    runChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Pigeonhole Sort algorithm]
 * (https://en.wikipedia.org/wiki/Pigeonhole_sort)
 * @author [Lownish](https://github.com/Lownish)
 * @details
 * Pigeonhole sorting is a sorting algorithm that is suitable for sorting lists
 * of elements where the number of elements and the number of possible key
 * values are approximately the same. It requires O(n + Range) time where n is
 * number of elements in input array and ‘Range’ is number of possible values in
 * array.
 *
 * The time Complexity of the algorithm is \f$O(n+N)\f$.
 */

#include <algorithm>  //for std::is_sorted
#include <array>      //for std::array
#include <cassert>    //for assert
#include <iostream>   //for io operations

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {

/**
 * Pigeonhole sorting of array of size n
 * The function will sort the array through Pigeonhole algorithm and print
 * @param arr unsorted array of elements
 * @returns sorted array of elements
 */
template <std::size_t N>
std::array<int, N> pigeonSort(std::array<int, N> arr) {
    // Finding min and max*
    auto min = std::min_element(std::begin(arr), std::end(arr));
    auto max = std::max_element(std::begin(arr), std::end(arr));

    // Range refers to the number of holes required
    int range = *max - *min + 1;
    int *hole = new int[range]();

    // Copying all array values to pigeonhole
    for (int i = 0; i < N; i++) {
        hole[arr[i] - *min] = arr[i];
    }

    // Deleting elements from list and storing to original array
    int count = 0;
    for (int i = 0; i < range; i++) {
        while (hole[i] != '\0') {
            arr[count] = hole[i];
            hole[i] = {};
            count++;
        }
    }
    delete[] hole;

    return arr;
}
}  // namespace sorting

/**
 * Test function 1 with unsorted array
 * {8, 3, 2, 7, 4, 6, 8}
 * @returns none
 */
static void test_1() {
    const int n = 7;
    std::array<int, n> test_array = {8, 3, 2, 7, 4, 6, 8};

    test_array = sorting::pigeonSort<n>(test_array);

    assert(std::is_sorted(std::begin(test_array), std::end(test_array)));

    // Printing sorted array
    for (int i = 0; i < n; i++) {
        std::cout << test_array.at(i) << " ";
    }
    std::cout << "\nPassed\n";
}

