/**
 * @file
 * @brief Alternate [Quick sort](https://en.wikipedia.org/wiki/Quicksort)
 * implementation in C++, using Lomuto-style partitioning around the last
 * element.
 * @details
 * Quicksort is a divide-and-conquer algorithm: pick a pivot, rearrange the
 * array so smaller elements land to its left and larger ones to its right,
 * then recurse on each side. This file always picks the final element of
 * the current window as pivot (one of several valid pivot strategies).
 *
 * Time complexity: O(n log n) average/best, O(n^2) worst case (already
 * sorted or reverse-sorted input with this pivot choice).
 * Space complexity: O(log n) average, O(n) worst, from recursion depth.
 */

#include <algorithm>  /// for std::is_sorted
#include <cassert>    /// for assert
#include <cstdint>
#include <ctime>      /// for std::time
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

namespace sorting {
namespace lomuto_quick_sort {

/**
 * @brief Partitions `data[low..high]` around the pivot `data[high]`,
 * placing the pivot in its final sorted position.
 * @returns the final index of the pivot element
 */
template <typename T>
int splitAroundPivot(std::vector<T> *data, const int &low, const int &high) {
    T pivotValue = (*data)[high];
    int boundary = low - 1;  // last index known to hold a "small" element

    for (int scan = low; scan < high; ++scan) {
        if ((*data)[scan] <= pivotValue) {
            ++boundary;
            std::swap((*data)[boundary], (*data)[scan]);
        }
    }

    std::swap((*data)[boundary + 1], (*data)[high]);
    return boundary + 1;
}

/**
 * @brief Sorts `data[low..high]` in place, recursively, via pointer.
 */
template <typename T>
void sortInPlace(std::vector<T> *data, const int &low, const int &high) {
    if (low >= high) {
        return;
    }
    int pivotIdx = splitAroundPivot(data, low, high);
    sortInPlace(data, low, pivotIdx - 1);
    sortInPlace(data, pivotIdx + 1, high);
}

/**
 * @brief Value-semantics wrapper: copies `data`, sorts the copy, and
 * returns it, leaving the caller's original untouched.
 */
template <typename T>
std::vector<T> sortCopy(std::vector<T> data, const int &low, const int &high) {
    if (low < high) {
        int pivotIdx = splitAroundPivot(&data, low, high);
        sortInPlace(&data, low, pivotIdx - 1);
        sortInPlace(&data, pivotIdx + 1, high);
    }
    return data;
}

/** @brief Prints the first `count` elements of `data`, space separated. */
template <typename T>
void printFirstN(const std::vector<T> &data, const int &count) {
    for (int i = 0; i < count; ++i) std::cout << data[i] << " ";
    std::cout << "\n";
}

}  // namespace lomuto_quick_sort
}  // namespace sorting

