        }
        assert(std::is_sorted(std::begin(sorted), std::end(sorted)));
        std::cout << "\t Passed\n";
    }
}

/** Driver program for above functions */
int main() {
    std::srand(std::time(nullptr));
    test_int();
    test_double();
    return 0;
}

/**
 * @file
 * @brief Alternate implementation of three-way quicksort (Dutch National
 * Flag partitioning).
 * @details
 * Unlike classic two-way quicksort, this variant splits the working range
 * into three zones in a single pass: values less than the pivot, values
 * equal to the pivot, and values greater than the pivot. That makes it
 * considerably faster on inputs with many duplicate keys, since the
 * "equal" zone never needs to be revisited by the recursion.
 * (Rewritten variant based on the classic Dutch-flag 3-way quicksort.)
 */
#include <algorithm>
#include <cassert>
#include <ctime>
#include <iostream>
#include <vector>

namespace {

// Streams a vector's contents as a comma-separated list.
template <typename T>
std::ostream &operator<<(std::ostream &out, const std::vector<T> &data) {
    for (std::size_t k = 0; k < data.size(); ++k) {
        out << data[k];
        if (k + 1 < data.size()) {
            out << ", ";
        }
    }
    return out;
}

}  // namespace

namespace sorting {
namespace {  // partitioning helper stays hidden from callers

/**
 * Splits `data[low..high]` into three zones relative to the pivot value
 * `data[high]`:
 *   - values below the pivot end up at indices <= *belowEnd
 *   - values equal to the pivot occupy the middle
 *   - values above the pivot end up at indices >= *aboveStart
 */
template <typename T>
void threeWaySplit(std::vector<T> *data, int32_t low, int32_t high,
                    int32_t *belowEnd, int32_t *aboveStart) {
    if (high - low <= 1) {
        if ((*data)[high] < (*data)[low]) {
            std::swap((*data)[high], (*data)[low]);
        }
        *belowEnd = low;
        *aboveStart = high;
        return;
    }

    T pivotValue = (*data)[high];
    int32_t cursor = low;
    int32_t lowerBound = low;
    int32_t upperBound = high;

    while (cursor <= upperBound) {
        if ((*data)[cursor] < pivotValue) {
            std::swap((*data)[lowerBound], (*data)[cursor]);
            ++lowerBound;
            ++cursor;
        } else if ((*data)[cursor] > pivotValue) {
            std::swap((*data)[cursor], (*data)[upperBound]);
            --upperBound;
        } else {
            ++cursor;
        }
    }

    *belowEnd = lowerBound - 1;
    *aboveStart = cursor;
}

}  // namespace

/**
 * Sorts `data[low..high]` in place using three-way partitioning.
 */
template <typename T>
void quicksort3(std::vector<T> *data, int32_t low, int32_t high) {
    if (low >= high) {
        return;
    }

    int32_t belowEnd = 0;
    int32_t aboveStart = 0;
    threeWaySplit(data, low, high, &belowEnd, &aboveStart);

    quicksort3(data, low, belowEnd);
    quicksort3(data, aboveStart, high);
}

/**
 * Value-semantics overload: sorts and returns a copy, leaving the
 * caller's vector untouched.
 */
template <typename T>
std::vector<T> quicksort3(std::vector<T> data, int32_t low, int32_t high) {
    if (low >= high) {
        return data;
    }

    int32_t belowEnd = 0;
    int32_t aboveStart = 0;
    threeWaySplit(&data, low, high, &belowEnd, &aboveStart);

    quicksort3(&data, low, belowEnd);
    quicksort3(&data, aboveStart, high);

    return data;
}

}  // namespace sorting

/** Randomized check across integer vectors of varying sizes. */
static void verify_int_vectors() {
    std::cout << "\nVerifying integer vectors\n";

    for (int trial = 1; trial < 21; ++trial) {
        std::size_t len = std::rand() % 500;
        std::vector<int> data(len);
        for (auto &value : data) {
            value = std::rand() % 500 - 250;
        }

        std::cout << "Trial " << trial << "\t size:" << len << "\t ";
        std::vector<int> result = sorting::quicksort3(data, 0, static_cast<int32_t>(len) - 1);
        if (len < 20) {
            std::cout << "\t Result:\n\t" << result << "\n";
        }
        assert(std::is_sorted(result.begin(), result.end()));
        std::cout << "\t OK\n";
    }
}

/** Randomized check across double vectors of varying sizes. */
static void verify_double_vectors() {
    std::cout << "\nVerifying double vectors\n";
    for (int trial = 1; trial < 21; ++trial) {
        std::size_t len = std::rand() % 500;
        std::vector<double> data(len);
        for (auto &value : data) {
            value = static_cast<double>(std::rand() % 500) - 250.0;
            value /= 100.0;
        }

        std::cout << "Trial " << trial << "\t size:" << len << "\t ";
        std::vector<double> result = sorting::quicksort3(data, 0, static_cast<int32_t>(len) - 1);
        if (len < 20) {
            std::cout << "\t Result:\n\t" << result << "\n";
        }
        assert(std::is_sorted(result.begin(), result.end()));
        std::cout << "\t OK\n";
    }
}

int main() {
    std::srand(static_cast<unsigned>(std::time(nullptr)));
    verify_int_vectors();
    verify_double_vectors();
    return 0;
}

/**
 * @file
 * @brief Quick Sort without recursion. This method uses the stack instead.
 * Both recursive and iterative implementations have O(n log n) best case
 * and O(n^2) worst case.
 * @details
 * https://stackoverflow.com/questions/12553238/quicksort-iterative-or-recursive
 * https://en.wikipedia.org/wiki/Quicksort
 * https://www.geeksforgeeks.org/iterative-quick-sort/
 * @author [Sebe324](https://github.com/sebe324)
 */

#include <iostream> /// for std::cout
#include <vector> /// for std::vector
#include <stack> /// for std::stack
#include <algorithm> /// for std::is_sorted
#include <cassert> /// for assert


/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @brief The partition function sorts the array from
 * start to end and uses the last element as the pivot.
 * @param arr the array to be sorted
 * @param start starting index
 * @param end ending index
 * @return int next index of the pivot
 */
int partition(std::vector<int> &arr, int start, int end)
{
    int pivot = arr[end];
    int index = start - 1;

    for (int j = start; j < end; j++) {
        if (arr[j] <= pivot) {
            std::swap(arr[++index], arr[j]);
        }
    }

    std::swap(arr[index + 1], arr[end]);
    return index + 1;
}

/**
 * @brief The main sorting function
 * @details The iterative quick sort uses
 * the stack instead of recursion for saving
 * and restoring the environment between calls.
 * It does not need the end and start params, because
 * it is not recursive.
 * @param arr array to be sorted
 * @return void
 */
void iterativeQuickSort(std::vector<int> &arr)
{
    std::stack<int> stack;
    int start = 0;
    int end = arr.size()-1;
    stack.push(start);
    stack.push(end);

    while(!stack.empty())
    {
        end = stack.top();
        stack.pop();
        start = stack.top();
        stack.pop();

        int pivotIndex = partition(arr,start,end);

        if(pivotIndex -1 > start)
        {
            stack.push(start);
            stack.push(pivotIndex-1);
        }

        if(pivotIndex+1<end)
        {
            stack.push(pivotIndex+1);
            stack.push(end);
        }
    }
}

} // namespace sorting
/**
 * @brief Self-test implementations
 * @returns void
 */
