/**
 * @file
 * @brief A stack-driven (non-recursive) take on Quicksort.
 * @details
 * Recursion is replaced by an explicit std::stack that remembers which
 * sub-ranges still need partitioning. Complexity bounds stay the same as
 * classic quicksort: average O(n log n), worst case O(n^2) on adversarial
 * inputs.
 * Background reading:
 * https://en.wikipedia.org/wiki/Quicksort
 * https://www.geeksforgeeks.org/iterative-quick-sort/
 */

#include <iostream>
#include <vector>
#include <stack>
#include <algorithm>
#include <cassert>
#include <utility>

/**
 * @namespace sorting
 * @brief Collection of sorting algorithm implementations
 */
namespace sorting {

/**
 * @namespace quicksort_no_recursion
 * @brief Helpers for the stack-based quicksort variant
 */
namespace quicksort_no_recursion {

/**
 * @brief Rearranges a sub-range so that everything <= the chosen pivot
 * (the last element) ends up left of it.
 * @param values container being sorted in place
 * @param lo first index of the sub-range
 * @param hi last index of the sub-range (pivot lives here initially)
 * @return final resting index of the pivot
 */
inline int lomutoSplit(std::vector<int> &values, int lo, int hi)
{
    const int pivotValue = values[hi];
    int boundary = lo - 1;

    for (int scan = lo; scan < hi; ++scan) {
        if (values[scan] <= pivotValue) {
            ++boundary;
            std::swap(values[boundary], values[scan]);
        }
    }

    std::swap(values[boundary + 1], values[hi]);
    return boundary + 1;
}

/**
 * @brief Sorts a vector using quicksort logic without recursive calls.
 * @details A manual stack of (lo, hi) pairs stands in for the call stack;
 * each iteration pops one range, partitions it, then pushes the resulting
 * sub-ranges if they are non-trivial.
 * @param values the vector to sort in place
 */
inline void sortWithoutRecursion(std::vector<int> &values)
{
    if (values.empty()) {
        return;
    }

    std::stack<std::pair<int, int>> pendingRanges;
    pendingRanges.push({0, static_cast<int>(values.size()) - 1});

    while (!pendingRanges.empty()) {
        const auto [lo, hi] = pendingRanges.top();
        pendingRanges.pop();

        const int pivotAt = lomutoSplit(values, lo, hi);

        if (pivotAt - 1 > lo) {
            pendingRanges.push({lo, pivotAt - 1});
        }
        if (pivotAt + 1 < hi) {
            pendingRanges.push({pivotAt + 1, hi});
        }
    }
}

}  // namespace quicksort_no_recursion
}  // namespace sorting

/**
 * @brief Prints a vector's contents separated by commas.
 */
static void dumpVector(const std::vector<int> &values)
{
    for (const auto &v : values) {
        std::cout << v << ",";
    }
    std::cout << "\n";
}

