 * @brief Exercises the stack-based quicksort against a couple of scenarios.
 */
static void runSelfChecks()
{
    std::cout << "Scenario A - all positive values\n";
    std::vector<int> dataA = {100, 534, 1000000, 553, 10, 61, 2000, 238, 2756, 9, 12, 56, 30};
    std::cout << "Before: \n";
    dumpVector(dataA);
    sorting::quicksort_no_recursion::sortWithoutRecursion(dataA);
    assert(std::is_sorted(dataA.begin(), dataA.end()));
    std::cout << "Scenario A passed.\n";
    std::cout << "After: \n";
