/**
 * @file
 * @brief Another take on quicksort using a randomly chosen pivot per
 * partition step.
 * @details
 * Plain quicksort risks O(n^2) behaviour on already-sorted or adversarial
 * inputs when the pivot is always the first/last element. Picking the
 * pivot uniformly at random from the current sub-range makes that worst
 * case exceedingly unlikely in practice, while keeping the average O(n log n)
 * runtime.
 *
 * Partitioning still separates values <= pivot to the left and values >
 * pivot to the right; only the pivot-selection step differs from vanilla
 * quicksort.
 *
 * Steps:
 *  1. Draw a random index in [start, end] and swap it into the `end` slot.
 *  2. Run a standard Lomuto partition using that value as pivot.
 *  3. Recurse on the two resulting sub-ranges.
 */

#include <algorithm>
#include <array>
#include <cassert>
#include <ctime>
#include <iostream>
#include <tuple>

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {

/**
 * @namespace randomized_quicksort
 * @brief Quicksort variant that randomizes pivot selection
 */
namespace randomized_quicksort {

/**
 * @brief Prints array contents on one line, space separated.
 */
template <size_t N>
void printArray(std::array<int64_t, N> data) {
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << " ";
    }
    std::cout << std::endl;
}

/**
 * @brief Draws a pseudo-random index between lo and hi inclusive.
 * @param lo lower bound
 * @param hi upper bound
 * @return random index within [lo, hi]
 */
int64_t pickRandomIndex(int64_t lo, int64_t hi) {
    srand(static_cast<unsigned>(time(nullptr)));
    return lo + rand() % (hi - lo + 1);
}

/**
 * @brief Lomuto-style partition step around arr[hi] as pivot.
 * @param arr array copy to be partitioned
 * @param lo lower bound of range
 * @param hi upper bound of range (pivot location)
 * @return tuple of (final pivot index, rearranged array)
 */
template <size_t N>
std::tuple<int64_t, std::array<int64_t, N>> splitAroundPivot(
    std::array<int64_t, N> arr, int64_t lo, int64_t hi) {
    const int64_t pivotValue = arr[hi];
    int64_t wall = lo;

    for (int64_t cursor = lo; cursor < hi; ++cursor) {
        if (arr[cursor] <= pivotValue) {
            std::swap(arr[cursor], arr[wall]);
            ++wall;
        }
    }
    std::swap(arr[wall], arr[hi]);
    return std::make_tuple(wall, arr);
}

/**
 * @brief Recursively sorts arr[lo..hi] using a randomly-selected pivot at
 * each partitioning step.
 */
template <size_t N>
std::array<int64_t, N> quicksortRandomPivot(std::array<int64_t, N> arr,
                                             int64_t lo, int64_t hi) {
    if (lo < hi) {
        const int64_t chosen = pickRandomIndex(lo, hi);
        std::swap(arr[hi], arr[chosen]);

        int64_t splitAt = 0;
        std::tie(splitAt, arr) = splitAroundPivot(arr, lo, hi);

        std::array<int64_t, arr.size()> afterLeft =
            quicksortRandomPivot(arr, lo, splitAt - 1);
        std::array<int64_t, arr.size()> afterBoth =
            quicksortRandomPivot(afterLeft, splitAt + 1, hi);
        arr = afterBoth;
    }
    return arr;
}

/**
 * @brief Builds an array of random values within [lowBound, highBound].
 */
template <size_t N>
std::array<int64_t, N> makeRandomArray(int64_t lowBound, int64_t highBound) {
    srand(static_cast<unsigned>(time(nullptr)));
    std::array<int64_t, N> generated{};
    assert(lowBound < highBound);
    size_t filled = 0;
    while (filled < N) {
        const int64_t candidate = lowBound + rand() % (highBound - lowBound + 1);
        if (candidate) {
            generated[filled] = candidate;
            ++filled;
        }
    }
    return generated;
}

}  // namespace randomized_quicksort
}  // namespace sorting

