    runChecks();
    return 0;
}

#include <iostream>

int main() {
    int size = 10;
    int* array = new int[size];
    // Input
    std::cout << "\nHow many numbers do want to enter in unsorted array : ";
    std::cin >> size;
    std::cout << "\nEnter the numbers for unsorted array : ";
    for (int i = 0; i < size; i++) {
        std::cin >> array[i];
    }

    // Sorting
    for (int i = size / 2; i > 0; i = i / 2) {
        for (int j = i; j < size; j++) {
            for (int k = j - i; k >= 0; k = k - i) {
                if (array[k] < array[k + i]) {
                    break;
                } else {
                    int temp = array[k + i];
                    array[k + i] = array[k];
                    array[k] = temp;
                }
            }
        }
    }

    // Output
    std::cout << "\nSorted array : ";
    for (int i = 0; i < size; ++i) {
        std::cout << array[i] << "\t";
    }

    delete[] array;
    return 0;
}

// Interactive shell sort demo (fixed-gap-sequence variant: dividing the
// working gap by 2 each pass, stopping once the gap reaches zero).
#include <iostream>

int main() {
    int count = 10;
    std::cout << "\nHow many numbers are in your unsorted list? ";
    std::cin >> count;

    int *values = new int[count];
    std::cout << "\nEnter the values one at a time: ";
    for (int i = 0; i < count; ++i) {
        std::cin >> values[i];
    }

    // Shell sort: start with a wide gap and shrink it by half each round,
    // performing a gapped insertion sort at each gap size.
    for (int gap = count / 2; gap > 0; gap /= 2) {
        for (int outer = gap; outer < count; ++outer) {
            for (int inner = outer - gap; inner >= 0; inner -= gap) {
                if (values[inner] < values[inner + gap]) {
                    break;
                }
                int tmp = values[inner + gap];
                values[inner + gap] = values[inner];
                values[inner] = tmp;
            }
        }
    }

    std::cout << "\nSorted result: ";
    for (int i = 0; i < count; ++i) {
        std::cout << values[i] << "\t";
    }

    delete[] values;
    return 0;
}

/**
 * \file
 * \brief [Shell sort](https://en.wikipedia.org/wiki/Shell_sort) algorithm
 * \author [Krishna Vedala](https://github.com/kvedala)
 */
#include <cassert>
#include <cstdlib>
#include <ctime>
#include <iostream>
#include <utility>  // for std::swap
#include <vector>

/** pretty print array
 * \param[in] arr array to print
 * \param[in] LEN length of array to print
 */
template <class T>
void show_data(T *arr, size_t LEN) {
    size_t i;

    for (i = 0; i < LEN; i++) {
        std::cout << arr[i] << ", ";
    }
    std::cout << std::endl;
}

/** pretty print array
 * \param[in] arr array to print
 * \param[in] N length of array to print
 */
template <typename T, size_t N>
void show_data(T (&arr)[N]) {
    show_data(arr, N);
}

/** \namespace sorting
 * \brief Sorting algorithms
 */
namespace sorting {
/**
 * Optimized algorithm - takes half the time by utilizing
 * Mar
 **/
template <typename T>
void shell_sort(T *arr, size_t LEN) {
    const unsigned int gaps[] = {701, 301, 132, 57, 23, 10, 4, 1};
    const unsigned int gap_len = 8;
    size_t i, j, g;

    for (g = 0; g < gap_len; g++) {
        unsigned int gap = gaps[g];
        for (i = gap; i < LEN; i++) {
            T tmp = arr[i];

            for (j = i; j >= gap && (arr[j - gap] - tmp) > 0; j -= gap) {
                arr[j] = arr[j - gap];
            }

            arr[j] = tmp;
        }
    }
}

/** function overload - when input array is of a known length array type
 */
template <typename T, size_t N>
void shell_sort(T (&arr)[N]) {
    shell_sort(arr, N);
}

/** function overload - when input array is of type std::vector,
 * simply send the data content and the data length to the above function.
 */
template <typename T>
void shell_sort(std::vector<T> *arr) {
    shell_sort(arr->data(), arr->size());
}

}  // namespace sorting

using sorting::shell_sort;

/**
 * function to compare sorting using cstdlib's qsort
 **/
template <typename T>
int compare(const void *a, const void *b) {
    T arg1 = *static_cast<const T *>(a);
    T arg2 = *static_cast<const T *>(b);

    if (arg1 < arg2)
        return -1;
    if (arg1 > arg2)
        return 1;
    return 0;

    //  return (arg1 > arg2) - (arg1 < arg2); // possible shortcut
    //  return arg1 - arg2; // erroneous shortcut (fails if INT_MIN is present)
}

/**
 * Test implementation of shell_sort on integer arrays by comparing results
 * against std::qsort.
 */
void test_int(const int NUM_DATA) {
    // int array = new int[NUM_DATA];
    int *data = new int[NUM_DATA];
    int *data2 = new int[NUM_DATA];
    // int array2 = new int[NUM_DATA];
    int range = 1800;

    for (int i = 0; i < NUM_DATA; i++)
        data[i] = data2[i] = (std::rand() % range) - (range >> 1);

    /* sort using our implementation */
    std::clock_t start = std::clock();
    shell_sort(data, NUM_DATA);
    std::clock_t end = std::clock();
    double elapsed_time = static_cast<double>(end - start) / CLOCKS_PER_SEC;
    std::cout << "Time spent sorting using shell_sort2: " << elapsed_time
              << "s\n";

    /* sort using std::qsort */
    start = std::clock();
    std::qsort(data2, NUM_DATA, sizeof(data2[0]), compare<int>);
    end = std::clock();

    elapsed_time = static_cast<double>(end - start) / CLOCKS_PER_SEC;
    std::cout << "Time spent sorting using std::qsort: " << elapsed_time
              << "s\n";

    for (int i = 0; i < NUM_DATA; i++) {
        assert(data[i] == data2[i]);  // ensure that our sorting results match
                                      // the standard results
    }

    delete[] data;
    delete[] data2;
}

/**
 * Test implementation of shell_sort on float arrays by comparing results
 * against std::qsort.
 */
void test_f(const int NUM_DATA) {
    // int array = new int[NUM_DATA];
    float *data = new float[NUM_DATA];
    float *data2 = new float[NUM_DATA];
    // int array2 = new int[NUM_DATA];
    int range = 1000;

    for (int i = 0; i < NUM_DATA; i++) {
        data[i] = data2[i] = ((std::rand() % range) - (range >> 1)) / 100.;
    }

    /* sort using our implementation */
    std::clock_t start = std::clock();
    shell_sort(data, NUM_DATA);
    std::clock_t end = std::clock();
    double elapsed_time = static_cast<double>(end - start) / CLOCKS_PER_SEC;
    std::cout << "Time spent sorting using shell_sort2: " << elapsed_time
              << "s\n";

    /* sort using std::qsort */
    start = std::clock();
    std::qsort(data2, NUM_DATA, sizeof(data2[0]), compare<float>);
    end = std::clock();

    elapsed_time = static_cast<double>(end - start) / CLOCKS_PER_SEC;
    std::cout << "Time spent sorting using std::qsort: " << elapsed_time
              << "s\n";

    for (int i = 0; i < NUM_DATA; i++) {
        assert(data[i] == data2[i]);  // ensure that our sorting results match
                                      // the standard results
    }

    delete[] data;
    delete[] data2;
}

/** Main function */
int main(int argc, char *argv[]) {
    // initialize random number generator - once per program
    std::srand(std::time(NULL));

    test_int(100);  // test with sorting random array of 100 values
    std::cout << "Test 1 - 100 int values - passed. \n";
    test_int(1000);  // test with sorting random array of 1000 values
    std::cout << "Test 2 - 1000 int values - passed.\n";
    test_int(10000);  // test with sorting random array of 10000 values
    std::cout << "Test 3 - 10000 int values - passed.\n";

    test_f(100);  // test with sorting random array of 100 values
    std::cout << "Test 1 - 100 float values - passed. \n";
    test_f(1000);  // test with sorting random array of 1000 values
    std::cout << "Test 2 - 1000 float values - passed.\n";
    test_f(10000);  // test with sorting random array of 10000 values
    std::cout << "Test 3 - 10000 float values - passed.\n";

    int i, NUM_DATA;

    if (argc == 2)
        NUM_DATA = atoi(argv[1]);
    else
        NUM_DATA = 200;

    // int array = new int[NUM_DATA];
    int *data = new int[NUM_DATA];
    // int array2 = new int[NUM_DATA];
    int range = 1800;

    std::srand(time(NULL));
    for (i = 0; i < NUM_DATA; i++) {
        // allocate random numbers in the given range
        data[i] = (std::rand() % range) - (range >> 1);
    }

    std::cout << "Unsorted original data: " << std::endl;
    show_data(data, NUM_DATA);
    std::clock_t start = std::clock();
    shell_sort(data, NUM_DATA);  // perform sorting
    std::clock_t end = std::clock();

    std::cout << std::endl
              << "Data Sorted using custom implementation: " << std::endl;
    show_data(data, NUM_DATA);

    double elapsed_time = (end - start) * 1.f / CLOCKS_PER_SEC;
    std::cout << "Time spent sorting: " << elapsed_time << "s\n" << std::endl;

    delete[] data;
    return 0;
}

/**
 * Shell sort using the Marcin Ciura gap sequence, benchmarked against
 * std::qsort for correctness and speed.
 */
#include <cassert>
#include <cstdlib>
#include <ctime>
#include <iostream>
#include <utility>
#include <vector>

/** Prints `length` elements of `data`, comma separated. */
template <class T>
void dumpArray(T *data, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        std::cout << data[i] << ", ";
    }
    std::cout << std::endl;
}

/** Overload for fixed-size C arrays. */
template <typename T, size_t N>
void dumpArray(T (&data)[N]) {
    dumpArray(data, N);
}

namespace sorting {

/**
 * Gap-sequence insertion sort (a.k.a. shell sort) using Ciura's empirically
 * tuned gaps, falling back to a gap of 1 (plain insertion sort) at the end.
 */
template <typename T>
void gapInsertionSort(T *data, size_t length) {
    static const unsigned int ciuraGaps[] = {701, 301, 132, 57, 23, 10, 4, 1};
    static const unsigned int gapCount = 8;

    for (unsigned int g = 0; g < gapCount; ++g) {
        unsigned int gap = ciuraGaps[g];
        for (size_t i = gap; i < length; ++i) {
            T pending = data[i];
            size_t j = i;
            while (j >= gap && (data[j - gap] - pending) > 0) {
                data[j] = data[j - gap];
                j -= gap;
            }
            data[j] = pending;
        }
    }
}

/** Overload for fixed-size C arrays. */
template <typename T, size_t N>
void gapInsertionSort(T (&data)[N]) {
    gapInsertionSort(data, N);
}

/** Overload for std::vector. */
template <typename T>
void gapInsertionSort(std::vector<T> *data) {
    gapInsertionSort(data->data(), data->size());
}

}  // namespace sorting

using sorting::gapInsertionSort;

/** Three-way comparator compatible with std::qsort. */
template <typename T>
int qsortCompare(const void *a, const void *b) {
    T x = *static_cast<const T *>(a);
    T y = *static_cast<const T *>(b);
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/** Compares our shell sort against std::qsort on random int data. */
void benchmarkInts(const int sampleSize) {
    int *ours = new int[sampleSize];
    int *reference = new int[sampleSize];
    int range = 1800;

    for (int i = 0; i < sampleSize; ++i) {
        ours[i] = reference[i] = (std::rand() % range) - (range >> 1);
    }

    std::clock_t t0 = std::clock();
    gapInsertionSort(ours, sampleSize);
    std::clock_t t1 = std::clock();
    std::cout << "Time spent sorting using gapInsertionSort: "
              << static_cast<double>(t1 - t0) / CLOCKS_PER_SEC << "s\n";

    t0 = std::clock();
    std::qsort(reference, sampleSize, sizeof(reference[0]), qsortCompare<int>);
    t1 = std::clock();
    std::cout << "Time spent sorting using std::qsort: "
              << static_cast<double>(t1 - t0) / CLOCKS_PER_SEC << "s\n";

    for (int i = 0; i < sampleSize; ++i) {
        assert(ours[i] == reference[i]);
    }

    delete[] ours;
    delete[] reference;
}

/** Compares our shell sort against std::qsort on random float data. */
void benchmarkFloats(const int sampleSize) {
    float *ours = new float[sampleSize];
    float *reference = new float[sampleSize];
    int range = 1000;

    for (int i = 0; i < sampleSize; ++i) {
        ours[i] = reference[i] = ((std::rand() % range) - (range >> 1)) / 100.f;
    }

    std::clock_t t0 = std::clock();
    gapInsertionSort(ours, sampleSize);
    std::clock_t t1 = std::clock();
    std::cout << "Time spent sorting using gapInsertionSort: "
              << static_cast<double>(t1 - t0) / CLOCKS_PER_SEC << "s\n";

    t0 = std::clock();
    std::qsort(reference, sampleSize, sizeof(reference[0]), qsortCompare<float>);
    t1 = std::clock();
    std::cout << "Time spent sorting using std::qsort: "
              << static_cast<double>(t1 - t0) / CLOCKS_PER_SEC << "s\n";

    for (int i = 0; i < sampleSize; ++i) {
        assert(ours[i] == reference[i]);
    }

    delete[] ours;
    delete[] reference;
}

int main(int argc, char *argv[]) {
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    benchmarkInts(100);
    std::cout << "Check 1 - 100 int values - passed.\n";
    benchmarkInts(1000);
    std::cout << "Check 2 - 1000 int values - passed.\n";
    benchmarkInts(10000);
    std::cout << "Check 3 - 10000 int values - passed.\n";

    benchmarkFloats(100);
    std::cout << "Check 1 - 100 float values - passed.\n";
    benchmarkFloats(1000);
    std::cout << "Check 2 - 1000 float values - passed.\n";
    benchmarkFloats(10000);
    std::cout << "Check 3 - 10000 float values - passed.\n";

    int sampleSize = (argc == 2) ? std::atoi(argv[1]) : 200;

    int *values = new int[sampleSize];
    int range = 1800;
    for (int i = 0; i < sampleSize; ++i) {
        values[i] = (std::rand() % range) - (range >> 1);
    }

    std::cout << "Unsorted original data: " << std::endl;
    dumpArray(values, sampleSize);

    std::clock_t t0 = std::clock();
    gapInsertionSort(values, sampleSize);
    std::clock_t t1 = std::clock();

    std::cout << std::endl
              << "Data sorted using custom implementation: " << std::endl;
    dumpArray(values, sampleSize);

    double elapsed = (t1 - t0) * 1.f / CLOCKS_PER_SEC;
    std::cout << "Time spent sorting: " << elapsed << "s\n" << std::endl;

    delete[] values;
    return 0;
}

// Returns the sorted vector after performing SlowSort
// It is a sorting algorithm that is of humorous nature and not useful.
// It's based on the principle of multiply and surrender, a tongue-in-cheek joke
// of divide and conquer. It was published in 1986 by Andrei Broder and Jorge
// Stolfi in their paper Pessimal Algorithms and Simplexity Analysis. This
// algorithm multiplies a single problem into multiple subproblems It is
// interesting because it is provably the least efficient sorting algorithm that
// can be built asymptotically, and with the restriction that such an algorithm,
// while being slow, must still all the time be working towards a result.

#include <iostream>

void SlowSort(int a[], int i, int j) {
    if (i >= j)
        return;
    int m = i + (j - i) / 2;  // midpoint, implemented this way to avoid
                              // overflow
    int temp;
    SlowSort(a, i, m);
    SlowSort(a, m + 1, j);
    if (a[j] < a[m]) {
        temp = a[j];  // swapping a[j] & a[m]
        a[j] = a[m];
        a[m] = temp;
    }
    SlowSort(a, i, j - 1);
}

// Sample Main function

int main() {
    int size;
    std::cout << "\nEnter the number of elements : ";

    std::cin >> size;

    int *arr = new int[size];

    std::cout << "\nEnter the unsorted elements : ";

    for (int i = 0; i < size; ++i) {
        std::cout << "\n";
        std::cin >> arr[i];
    }

    SlowSort(arr, 0, size);

    std::cout << "Sorted array\n";

    for (int i = 0; i < size; ++i) {
        std::cout << arr[i] << " ";
    }

    delete[] arr;
    return 0;
}

// Slow sort — a deliberately, provably inefficient sorting algorithm built
// on the "multiply and surrender" principle (a parody of divide and
// conquer). Originally described by Andrei Broder and Jorge Stolfi in their
// 1986 paper "Pessimal Algorithms and Simplexity Analysis." Despite being
// asymptotically about as bad as a sorting algorithm can get while still
// making steady progress, it is a fun illustration of recursion.

#include <iostream>

// Sorts arr[lo..hi] (inclusive) in place using the slow-sort strategy:
// recursively sort the first and second halves, ensure the maximum of the
// whole range ends up last, then recurse on everything except that last
// element.
void slowSort(int arr[], int lo, int hi) {
    if (lo >= hi) {
        return;
    }

    int mid = lo + (hi - lo) / 2;

    slowSort(arr, lo, mid);
    slowSort(arr, mid + 1, hi);

    if (arr[hi] < arr[mid]) {
        int swapTmp = arr[hi];
        arr[hi] = arr[mid];
        arr[mid] = swapTmp;
    }

    slowSort(arr, lo, hi - 1);
}

int main() {
    int count;
    std::cout << "\nHow many elements? ";
    std::cin >> count;

    int *values = new int[count];

    std::cout << "\nEnter the elements, unsorted: ";
    for (int i = 0; i < count; ++i) {
        std::cout << "\n";
        std::cin >> values[i];
    }

    slowSort(values, 0, count);

    std::cout << "Sorted result:\n";
    for (int i = 0; i < count; ++i) {
        std::cout << values[i] << " ";
    }

    delete[] values;
    return 0;
}

/**
 * @file
 * @brief [Stooge sort implementation](https://en.wikipedia.org/wiki/Stooge_sort)
 * in C++
 * @details
 * Stooge sort is a recursive sorting algorithm.
 * It divides the array into 3 parts and proceeds to:
 *	- sort first two thirds of the array
 *	- sort last two thirds of the array
 *  - sort first two thirds of the array
 * It's time complexity is O(n^(log3/log1.5)), which is about O(n^2.7),
 * which makes it to be not the most efficient sorting algorithm
 * on the street on average. Space complexity is O(1).
 */

#include <vector> /// for vector
#include <cassert> /// for assert
#include <algorithm>  /// for std::is_sorted
#include <iostream>   /// for IO operations

 /**
  * @brief The stoogeSort() function is used for sorting the array.
  * @param L - vector of values (int) to be sorted in in place (ascending order)
  * @param i - the first index of the array (0)
  * @param j - the last index of the array (L.size() - 1)
  * @returns void
  */
void stoogeSort(std::vector<int>* L, size_t i, size_t j) {
    if (i >= j) {
        return;
    }
    if ((*L)[i] > (*L)[j]) {
        std::swap((*L)[i], (*L)[j]);
    }
    if (j - i > 1) {
        size_t third = (j - i + 1) / 3;
        stoogeSort(L, i, j - third);
        stoogeSort(L, i + third, j);
        stoogeSort(L, i, j - third);
    }
}

/**
 * @brief Function to test sorting algorithm
 * @returns void
 */
void test1() {
	std::vector<int> L = { 8, 9, 10, 4, 3, 5, 1 };
	stoogeSort(&L, 0, L.size() - 1);
	assert(std::is_sorted(std::begin(L), std::end(L)));
}

/**
 * @brief Function to test sorting algorithm, one element
 * @returns void
 */
void test2() {
	std::vector<int> L = { -1 };
	stoogeSort(&L, 0, L.size() - 1);
	assert(std::is_sorted(std::begin(L), std::end(L)));
}

/**
 * @brief Function to test sorting algorithm, repeating elements
 * @returns void
 */
void test3() {
	std::vector<int> L = { 1, 2, 5, 4, 1, 5 };
	stoogeSort(&L, 0, L.size() - 1);
	assert(std::is_sorted(std::begin(L), std::end(L)));
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
	test1();
	test2();
	test3();

    std::cout << "All tests have successfully passed!\n";
	return 0;
}

// Stooge sort demonstration.
//
// This is a notoriously inefficient recursive sorting technique. Given a
// contiguous slice of an array, it swaps the endpoints if needed, then
// recursively sorts the first two-thirds, the last two-thirds, and the
// first two-thirds again. Runtime is roughly O(n^2.7) and no extra memory
// is used beyond the recursion stack.

#include <vector>
#include <cassert>
#include <algorithm>
#include <iostream>

// Recursively applies stooge sort to arr[lo..hi] (inclusive).
static void stoogeRecurse(std::vector<int>& arr, size_t lo, size_t hi) {
    if (lo >= hi) {
        return;
    }

    if (arr[lo] > arr[hi]) {
        std::swap(arr[lo], arr[hi]);
    }

    size_t span = hi - lo + 1;
    if (span > 2) {
        size_t chunk = span / 3;
        stoogeRecurse(arr, lo, hi - chunk);
        stoogeRecurse(arr, lo + chunk, hi);
        stoogeRecurse(arr, lo, hi - chunk);
    }
}

// Public entry point mirroring the classic stooge sort signature.
void stoogeSort(std::vector<int>* data, size_t lo, size_t hi) {
    stoogeRecurse(*data, lo, hi);
}

namespace stooge_checks {

void basicUnsortedCase() {
    std::vector<int> values{8, 9, 10, 4, 3, 5, 1};
    stoogeSort(&values, 0, values.size() - 1);
    assert(std::is_sorted(values.begin(), values.end()));
}

void singleElementCase() {
    std::vector<int> values{-1};
    stoogeSort(&values, 0, values.size() - 1);
    assert(std::is_sorted(values.begin(), values.end()));
}

void duplicateValuesCase() {
    std::vector<int> values{1, 2, 5, 4, 1, 5};
    stoogeSort(&values, 0, values.size() - 1);
    assert(std::is_sorted(values.begin(), values.end()));
}

}  // namespace stooge_checks

int main() {
    stooge_checks::basicUnsortedCase();
    stooge_checks::singleElementCase();
    stooge_checks::duplicateValuesCase();

    std::cout << "stooge sort: every check passed\n";
    return 0;
}

/**
 * @file strand_sort.cpp
 * @brief Implementation of [Strand Sort](https://en.wikipedia.org/wiki/Strand_sort) algorithm.
 *
 * @details
 * Strand Sort is a sorting algorithm that works in \f$O(n)\f$ time if list is already sorted and works in \f$O(n^2)\f$ in worst case.
 * 
 * It is passed over the array to be sorted once and the ascending (sequential) numbers are taken.
 * After the first iteration, the sequential sub-array is put on the empty sorted array.
 * The main sequence is passed over again and a new sub-sequence is created in order.
 * Now that the sorted array is not empty, the newly extracted substring is merged with the sorted array.
 * Repeat types 3 and 4 until the sub-sequence and main sequence are empty.
 * 
 * @author [Mertcan Davulcu](https://github.com/mertcandav)
 */
#include <iostream>
#include <list>

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
    /**
    * @namespace strand
    * @brief Functions for [Strand Sort](https://en.wikipedia.org/wiki/Strand_sort) algorithm
    */
    namespace strand {
        /**
        * @brief Apply sorting
        * @tparam element type of list
        * @param lst List to be sorted
        * @returns Sorted list<T> instance
        */
        template <typename T>
        std::list<T> strand_sort(std::list<T> lst) {
            if (lst.size() < 2) { // Returns list if empty or contains only one element
                return lst; // Returns list
            }
            std::list<T> result; // Define new "result" named list instance.
            std::list<T> sorted; // Define new "sorted" named list instance.
            while(!lst.empty()) /* if lst is not empty */ {
                sorted.push_back(lst.front()); // Adds the first element of "lst" list to the bottom of the "sorted" list.
                lst.pop_front(); // Remove first element of "lst" list.
                for (auto it = lst.begin(); it != lst.end(); ) { // Return the loop as long as the current iterator is not equal to the last literator of the "lst" list.
                    if (sorted.back() <= *it) { // If the last reference of the "sorted" list is less than or equal to the current iterator reference.
                        sorted.push_back(*it); // Adds the iterator retrieved in the loop under the "sorted" list.
                        it = lst.erase(it); // Deletes the element with the current iterator and assigns the deleted element to the iterator.
                    } else {
                        it++; // Next iterator.
                    }
                }
                result.merge(sorted); // Merge "result" list with "sorted" list.
            }
            return result; // Returns sorted list
        }
    }  // namespace strand
}  // namespace sorting

/**
 * @brief Function for testing
 * @return N/A
 */
static void test() {
    std::list<int> lst = { -333, 525, 1, 0, 94, 52, 33 };

    std::cout << "Before: ";
    for(auto item: lst) {
        std::cout << item << " ";
    }

    lst = sorting::strand::strand_sort(lst); // Sort list.

    std::cout << "\nAfter: ";
    for(auto item: lst) {
        std::cout << item << " ";
    }
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();
    return 0;
}

// Strand sort reimplementation.
//
// The idea: repeatedly pull an already-ascending "strand" out of the input
// list and merge it into an accumulating output list. When the source list
// runs dry, the accumulator holds the fully sorted sequence. Best case is
// linear time (already-sorted input); worst case degrades to quadratic.

#include <iostream>
#include <list>

namespace ordering {
namespace strands {

// Extracts sorted runs from `pending` one at a time and merges them into
// the returned list until nothing remains.
template <typename Item>
std::list<Item> sortByStrands(std::list<Item> pending) {
    if (pending.size() < 2) {
        return pending;
    }

    std::list<Item> accumulated;

    while (!pending.empty()) {
        std::list<Item> run;
        run.push_back(pending.front());
        pending.pop_front();

        for (auto cursor = pending.begin(); cursor != pending.end();) {
            if (run.back() <= *cursor) {
                run.push_back(*cursor);
                cursor = pending.erase(cursor);
            } else {
                ++cursor;
            }
        }

        accumulated.merge(run);
    }

    return accumulated;
}

}  // namespace strands
}  // namespace ordering

static void runDemo() {
    std::list<int> numbers{-333, 525, 1, 0, 94, 52, 33};

    std::cout << "input sequence: ";
    for (int n : numbers) {
        std::cout << n << " ";
    }

    numbers = ordering::strands::sortByStrands(numbers);

    std::cout << "\nsorted sequence: ";
    for (int n : numbers) {
        std::cout << n << " ";
    }
    std::cout << "\n";
}

int main() {
    runDemo();
    return 0;
}

// C++ program to find minimum number of swaps required to sort an array
#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

// Function returns the minimum number of swaps
// required to sort the array
int minSwaps(int arr[], int n) {
    // Create an array of pairs where first
    // element is array element and second element
    // is position of first element
    std::pair<int, int> *arrPos = new std::pair<int, int>[n];
    for (int i = 0; i < n; i++) {
        arrPos[i].first = arr[i];
        arrPos[i].second = i;
    }

    // Sort the array by array element values to
    // get right position of every element as second
    // element of pair.
    std::sort(arrPos, arrPos + n);

    // To keep track of visited elements. Initialize
    // all elements as not visited or false.
    std::vector<bool> vis(n, false);

    // Initialize result
    int ans = 0;

    // Traverse array elements
    for (int i = 0; i < n; i++) {
        // already swapped and corrected or
        // already present at correct pos
        if (vis[i] || arrPos[i].second == i)
            continue;

        // find out the number of node in
        // this cycle and add in ans
        int cycle_size = 0;
        int j = i;
        while (!vis[j]) {
            vis[j] = 1;

            // move to next node
            j = arrPos[j].second;
            cycle_size++;
        }

        // Update answer by adding current cycle.
        if (cycle_size > 0) {
            ans += (cycle_size - 1);
        }
    }

    delete[] arrPos;

    // Return result
    return ans;
}

// program to test
int main() {
    int arr[] = {6, 7, 8, 1, 2, 3, 9, 12};
    int n = (sizeof(arr) / sizeof(int));
    std::cout << minSwaps(arr, n);
    return 0;
}

// Computes the minimum number of element swaps needed to fully sort an
// array. Rather than actually sorting, this treats the array as a
// permutation graph: each element points to the slot it should occupy, and
// following those pointers traces out disjoint cycles. A cycle of length k
// needs exactly (k - 1) swaps to resolve, so summing that over all cycles
// gives the answer.

#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

int minimumSwapsToSort(const std::vector<int>& values) {
    const int count = static_cast<int>(values.size());

    // Pair each value with its original slot, then sort by value so that
    // `second` tells us where each element belongs once ordered.
    std::vector<std::pair<int, int>> withOrigin(count);
    for (int idx = 0; idx < count; ++idx) {
        withOrigin[idx] = {values[idx], idx};
    }
    std::sort(withOrigin.begin(), withOrigin.end());

    std::vector<bool> settled(count, false);
    int totalSwaps = 0;

    for (int start = 0; start < count; ++start) {
        if (settled[start] || withOrigin[start].second == start) {
            continue;
        }

        int cycleLength = 0;
        int cursor = start;
        while (!settled[cursor]) {
            settled[cursor] = true;
            cursor = withOrigin[cursor].second;
            ++cycleLength;
        }

        if (cycleLength > 0) {
            totalSwaps += cycleLength - 1;
        }
    }

    return totalSwaps;
}

int main() {
    std::vector<int> sample{6, 7, 8, 1, 2, 3, 9, 12};
    std::cout << minimumSwapsToSort(sample);
    return 0;
}

// C++ program to perform TimSort.
#include <algorithm>
#include <cassert>
#include <iostream>
#include <numeric>

const int RUN = 32;

// this function sorts array from left index to to right index which is of size
// atmost RUN
void insertionSort(int arr[], int left, int right) {
    for (int i = left + 1; i <= right; i++) {
        const int temp = arr[i];
        int j = i - 1;
        while (j >= left && arr[j] > temp) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = temp;
    }
}

// merge function merges the sorted runs
void merge(int arr[], int l, int m, int r) {
    // original array is broken in two parts, left and right array
    const int len1 = m - l + 1, len2 = r - m;
    int *left = new int[len1], *right = new int[len2];
    for (int i = 0; i < len1; i++) left[i] = arr[l + i];
    for (int i = 0; i < len2; i++) right[i] = arr[m + 1 + i];

    int i = 0;
    int j = 0;
    int k = l;

    // after comparing, we merge those two array in larger sub array
    while (i < len1 && j < len2) {
        if (left[i] <= right[j]) {
            arr[k] = left[i];
            i++;
        } else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    // copy remaining elements of left, if any
    while (i < len1) {
        arr[k] = left[i];
        k++;
        i++;
    }

    // copy remaining element of right, if any
    while (j < len2) {
        arr[k] = right[j];
        k++;
        j++;
    }
    delete[] left;
    delete[] right;
}

// iterative Timsort function to sort the array[0...n-1] (similar to merge sort)
void timSort(int arr[], int n) {
    // Sort individual subarrays of size RUN
    for (int i = 0; i < n; i += RUN)
        insertionSort(arr, i, std::min((i + 31), (n - 1)));

    // start merging from size RUN (or 32). It will merge to form size 64, then
    // 128, 256 and so on ....
    for (int size = RUN; size < n; size = 2 * size) {
        // pick starting point of left sub array. We are going to merge
        // arr[left..left+size-1] and arr[left+size, left+2*size-1] After every
        // merge, we increase left by 2*size
        for (int left = 0; left < n; left += 2 * size) {
            // find ending point of left sub array
            // mid+1 is starting point of right sub array
            const int mid = std::min((left + size - 1), (n - 1));
            const int right = std::min((left + 2 * size - 1), (n - 1));

            // merge sub array arr[left.....mid] & arr[mid+1....right]
            merge(arr, left, mid, right);
        }
    }
}

// utility function to print the Array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) printf("%d  ", arr[i]);
    std::cout << std::endl;
}

/**
 * @brief self-test implementation
 * @returns void
 */
void tests() {
    // Case: array of length 65
    constexpr int N = 65;
    int arr[N];

    std::iota(arr, arr + N, 0);
    std::reverse(arr, arr + N);
    assert(!std::is_sorted(arr, arr + N));

    timSort(arr, N);
    assert(std::is_sorted(arr, arr + N));
}

// Driver program to test above function
int main() {
    tests();  // run self test implementations

    int arr[] = {5, 21, 7, 23, 19};
    const int n = sizeof(arr) / sizeof(arr[0]);
    printf("Given Array is\n");
    printArray(arr, n);

    timSort(arr, n);

    printf("After Sorting Array is\n");
    printArray(arr, n);
    return 0;
}

// A from-scratch TimSort walkthrough: break the array into fixed-size runs,
// sort each run with insertion sort (cheap for small slices), then
// repeatedly merge neighboring runs — doubling the merge width each pass —
// until the whole array is one sorted run.

#include <algorithm>
#include <cassert>
#include <cstdio>
#include <iostream>
#include <numeric>

constexpr int RUN_WIDTH = 32;

// Sorts arr[from..to] in place using plain insertion sort.
void insertionSortRange(int arr[], int from, int to) {
    for (int cur = from + 1; cur <= to; ++cur) {
        const int key = arr[cur];
        int back = cur - 1;
        while (back >= from && arr[back] > key) {
            arr[back + 1] = arr[back];
            --back;
        }
        arr[back + 1] = key;
    }
}

// Merges two adjacent sorted slices arr[lo..mid] and arr[mid+1..hi] into a
// single sorted slice using temporary buffers.
void mergeRuns(int arr[], int lo, int mid, int hi) {
    const int leftLen = mid - lo + 1;
    const int rightLen = hi - mid;

    int* leftBuf = new int[leftLen];
    int* rightBuf = new int[rightLen];
    for (int i = 0; i < leftLen; ++i) leftBuf[i] = arr[lo + i];
    for (int i = 0; i < rightLen; ++i) rightBuf[i] = arr[mid + 1 + i];

    int li = 0, ri = 0, out = lo;
    while (li < leftLen && ri < rightLen) {
        if (leftBuf[li] <= rightBuf[ri]) {
            arr[out++] = leftBuf[li++];
        } else {
            arr[out++] = rightBuf[ri++];
        }
    }
    while (li < leftLen) arr[out++] = leftBuf[li++];
    while (ri < rightLen) arr[out++] = rightBuf[ri++];

    delete[] leftBuf;
    delete[] rightBuf;
}

// Full TimSort-style pass: sort fixed runs, then merge them bottom-up.
void timSort(int arr[], int length) {
    for (int start = 0; start < length; start += RUN_WIDTH) {
        insertionSortRange(arr, start, std::min(start + RUN_WIDTH - 1, length - 1));
    }

    for (int width = RUN_WIDTH; width < length; width *= 2) {
        for (int lo = 0; lo < length; lo += 2 * width) {
            const int mid = std::min(lo + width - 1, length - 1);
            const int hi = std::min(lo + 2 * width - 1, length - 1);
            mergeRuns(arr, lo, mid, hi);
        }
    }
}

void showArray(const int arr[], int length) {
    for (int i = 0; i < length; ++i) {
        printf("%d  ", arr[i]);
    }
    std::cout << std::endl;
}

void selfCheck() {
    constexpr int SIZE = 65;
    int data[SIZE];

    std::iota(data, data + SIZE, 0);
    std::reverse(data, data + SIZE);
    assert(!std::is_sorted(data, data + SIZE));

    timSort(data, SIZE);
    assert(std::is_sorted(data, data + SIZE));
}

int main() {
    selfCheck();

    int sample[] = {5, 21, 7, 23, 19};
    const int sampleLen = sizeof(sample) / sizeof(sample[0]);

    printf("Before sorting:\n");
    showArray(sample, sampleLen);

    timSort(sample, sampleLen);

    printf("After sorting:\n");
    showArray(sample, sampleLen);
    return 0;
}

/**
 * @file
 * @brief Implementation of the [Wave
 * sort](https://www.geeksforgeeks.org/sort-array-wave-form-2/) algorithm
 * @details
 * Wave Sort is a sorting algorithm that works in \f$O(nlogn)\f$ time assuming
 * the sort function used works in \f$O(nlogn)\f$ time.
 * @author [Swastika Gupta](https://github.com/Swastyy)
 */

#include <algorithm>  /// for std::is_sorted, std::swap
#include <cassert>    /// for assert
#include <iostream>   /// for IO operations
#include <vector>     /// for std::vector

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace wave_sort
 * @brief Functions for the [Wave
 * sort](https://www.geeksforgeeks.org/sort-array-wave-form-2/) implementation
 */
namespace wave_sort {
/**
 * @brief The main function implements that implements the Wave Sort algorithm
 * @tparam T type of array
 * @param in_arr array to be sorted
 * @returns arr the wave sorted array
 */
template <typename T>
std::vector<T> waveSort(const std::vector<T> &in_arr, int64_t n) {
    std::vector<T> arr(in_arr);

    for (int64_t i = 0; i < n; i++) {
        arr[i] = in_arr[i];
    }
    std::sort(arr.begin(), arr.end());
    for (int64_t i = 0; i < n - 1; i += 2) {  // swap all the adjacent elements
        std::swap(arr[i], arr[i + 1]);
    }
    return arr;
}
}  // namespace wave_sort
}  // namespace sorting

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // [10, 90, 49, 2, 1, 5, 23] return [2, 1, 10, 5, 49, 23, 90]
    std::vector<int64_t> array1 = {10, 90, 49, 2, 1, 5, 23};
    std::cout << "Test 1... ";
    std::vector<int64_t> arr1 = sorting::wave_sort::waveSort(array1, 7);
    const std::vector<int64_t> o1 = {2, 1, 10, 5, 49, 23, 90};
    assert(arr1 == o1);
    std::cout << "passed" << std::endl;

    // [1, 3, 4, 2, 7, 8] return [2, 1, 4, 3, 8, 7]
    std::vector<int64_t> array2 = {1, 3, 4, 2, 7, 8};
    std::cout << "Test 2... ";
    std::vector<int64_t> arr2 = sorting::wave_sort::waveSort(array2, 6);
    const std::vector<int64_t> o2 = {2, 1, 4, 3, 8, 7};
    assert(arr2 == o2);
    std::cout << "passed" << std::endl;

    // [3, 3, 3, 3] return [3, 3, 3, 3]
    std::vector<int64_t> array3 = {3, 3, 3, 3};
    std::cout << "Test 3... ";
    std::vector<int64_t> arr3 = sorting::wave_sort::waveSort(array3, 4);
    const std::vector<int64_t> o3 = {3, 3, 3, 3};
    assert(arr3 == o3);
    std::cout << "passed" << std::endl;

    // [9, 4, 6, 8, 14, 3] return [4, 3, 8, 6, 14, 9]
    std::vector<int64_t> array4 = {9, 4, 6, 8, 14, 3};
    std::cout << "Test 4... ";
    std::vector<int64_t> arr4 = sorting::wave_sort::waveSort(array4, 6);
    const std::vector<int64_t> o4 = {4, 3, 8, 6, 14, 9};
    assert(arr4 == o4);
    std::cout << "passed" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

// Wave sort: arrange a sequence so it zig-zags — every even-indexed slot is
// greater than or equal to its neighbors. This particular approach cheats
// by fully sorting the data first (O(n log n)) and then swapping each
// adjacent pair, which is sufficient to produce a valid wave pattern.

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

namespace ordering {
namespace wave {

// Returns a new vector containing the first `count` elements of `source`
// rearranged into wave form.
template <typename T>
std::vector<T> arrangeAsWave(const std::vector<T>& source, int64_t count) {
    std::vector<T> result(source.begin(), source.begin() + count);

    std::sort(result.begin(), result.end());

    for (int64_t idx = 0; idx + 1 < count; idx += 2) {
        std::swap(result[idx], result[idx + 1]);
    }

    return result;
}

}  // namespace wave
}  // namespace ordering

static void checkCase(const std::vector<int64_t>& input,
                       const std::vector<int64_t>& expected,
                       const char* label) {
    std::cout << label << "... ";
    std::vector<int64_t> actual =
        ordering::wave::arrangeAsWave(input, static_cast<int64_t>(input.size()));
    assert(actual == expected);
    std::cout << "ok" << std::endl;
}

static void runAllChecks() {
    checkCase({10, 90, 49, 2, 1, 5, 23}, {2, 1, 10, 5, 49, 23, 90}, "case A");
    checkCase({1, 3, 4, 2, 7, 8}, {2, 1, 4, 3, 8, 7}, "case B");
    checkCase({3, 3, 3, 3}, {3, 3, 3, 3}, "case C (duplicates)");
    checkCase({9, 4, 6, 8, 14, 3}, {4, 3, 8, 6, 14, 9}, "case D");
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * \addtogroup sorting Sorting Algorithms
 * @{
 * \file
 * \brief [Wiggle Sort Algorithm]
 * (https://leetcode.com/problems/wiggle-sort-ii/) Implementation
 *
 * \author [Roshan Kanwar](http://github.com/roshan0708)
 *
 * \details
 * Wiggle Sort sorts the array into a wave like array.
 * An array ‘arr[0..n-1]’ is sorted in wave form,
 * if arr[0] >= arr[1] <= arr[2] >= arr[3] <= arr[4] >= …..
 *
 * \example
 * arr = [1,1,5,6,1,4], after wiggle sort arr will become equal to [1,1,6,1,5,4]
 * arr = [2,8,9,1,7], after wiggle sort arr will become equal to [8,2,9,1,7]
 */

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <ctime>
#include <iostream>  /// for io operations
#include <vector>

/**
 * @namespace sorting
 * @brief Sorting algorithms
 */
namespace sorting {
/**
 * @namespace wiggle_sort
 * @brief Functions for [Wiggle
 * Sort](https://leetcode.com/problems/wiggle-sort-ii/) algorithm
 */
namespace wiggle_sort {

/**
 *
 * @brief Function used for sorting the elements in wave form.
 * @details
 * Checking whether the even indexed elements are greater than
 * their adjacent odd elements.
 * Traversing all even indexed elements of the input arr.
 * If current element is smaller than the previous odd element, swap them.
 * If current element is smaller than the next odd element, swap them.
 *
 * @param arr input array (unsorted elements)
 *
 */
template <typename T>  // this allows to have vectors of ints, double, float,
                       // etc
std::vector<T> wiggleSort(const std::vector<T> &arr) {
    uint32_t size = arr.size();

    std::vector<T> out(
        arr);  // create a copy of input vector. this way, the original input
               // vector does not get modified. a sorted array is is returned.

    for (int i = 0; i < size; i += 2) {
        if (i > 0 && out[i - 1] > out[i]) {
            std::swap(out[i], out[i - 1]);  // swapping the two values
        }

        if (i < size - 1 && out[i] < out[i + 1]) {
            std::swap(out[i], out[i + 1]);  // swapping the two values
        }
    }

    return out;  // returns the sorted vector
}
}  // namespace wiggle_sort
}  // namespace sorting

/**
 *
 * @brief Utility function used for printing the elements.
 * Prints elements of the array after they're sorted using wiggle sort
 * algorithm.
 *
 * @param arr array containing the sorted elements
 *
 */
template <typename T>
static void displayElements(const std::vector<T> &arr) {
    uint32_t size = arr.size();

    std::cout << "Sorted elements are as follows: ";

    std::cout << "[";

    for (int i = 0; i < size; i++) {
        std::cout << arr[i];
        if (i != size - 1) {
            std::cout << ", ";
        }
    }

    std::cout << "]" << std::endl;
}

/**
 * Test function
 * @returns void
 */
static void test() {
    std::srand(std::time(nullptr));  // initialize random number generator

    std::vector<float> data1(100);
    for (auto &d : data1) {  // generate random numbers between -5.0 and 4.99
        d = float(std::rand() % 1000 - 500) / 100.f;
    }

    std::vector<float> sorted = sorting::wiggle_sort::wiggleSort<float>(data1);

    displayElements(sorted);

    for (uint32_t j = 0; j < data1.size(); j += 2) {
        assert(data1[j] <= data1[j + 1] &&
               data1[j + 1] >= data1[j + 2]);  // check the validation condition
    }

    std::cout << "Test 1 passed\n";
}

/** Driver Code */
int main() {
    test();
    return 0;
}

/** @} */

// Wiggle sort variant: rearranges elements so the pattern alternates
// peak/valley — arr[0] >= arr[1] <= arr[2] >= arr[3] <= ... This
// implementation walks the array two steps at a time, fixing local
// violations against both neighbors of each even position without doing a
// full sort first.

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <ctime>
#include <iostream>
#include <vector>

namespace ordering {
namespace zigzag {

// Produces a wiggle-ordered copy of `input`; the source is left untouched.
template <typename T>
std::vector<T> makeWiggle(const std::vector<T>& input) {
    std::vector<T> result(input);
    const size_t total = result.size();

    for (size_t pos = 0; pos < total; pos += 2) {
        if (pos > 0 && result[pos - 1] > result[pos]) {
            std::swap(result[pos], result[pos - 1]);
        }
        if (pos + 1 < total && result[pos] < result[pos + 1]) {
            std::swap(result[pos], result[pos + 1]);
        }
    }

    return result;
}

}  // namespace zigzag
}  // namespace ordering

template <typename T>
static void printSequence(const std::vector<T>& seq) {
    std::cout << "Wiggle-ordered output: [";
    for (size_t i = 0; i < seq.size(); ++i) {
        std::cout << seq[i];
        if (i + 1 != seq.size()) {
            std::cout << ", ";
        }
    }
    std::cout << "]" << std::endl;
}

static void runDemo() {
    std::srand(static_cast<unsigned>(std::time(nullptr)));

    std::vector<float> raw(100);
    for (auto& value : raw) {
        value = static_cast<float>(std::rand() % 1000 - 500) / 100.f;
    }

    std::vector<float> wiggled = ordering::zigzag::makeWiggle<float>(raw);
    printSequence(wiggled);

    for (size_t i = 0; i + 2 < raw.size(); i += 2) {
        assert(raw[i] <= raw[i + 1] && raw[i + 1] >= raw[i + 2]);
    }

    std::cout << "Demo check passed\n";
}

int main() {
    runDemo();
    return 0;
}

/**
 * @file
 * @brief
 * The
 * [Boyer–Moore](https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore_string-search_algorithm)
 * algorithm searches for occurrences of pattern P in text T by performing
 * explicit character comparisons at different alignments. Instead of a
 * brute-force search of all alignments (of which there are n - m + 1),
 * Boyer–Moore uses information gained by preprocessing P to skip as many
 * alignments as possible.
 *
 * @details
 * The key insight in this algorithm is that if the end of the pattern is
 * compared to the text, then jumps along the text can be made rather than
 * checking every character of the text. The reason that this works is that in
 * lining up the pattern against the text, the last character of the pattern is
 * compared to the character in the text.
 *
 * If the characters do not match, there is no need to continue searching
 * backwards along the text. This leaves us with two cases.
 *
 * Case 1:
 * If the character in the text does not match any of the characters in the
 * pattern, then the next character in the text to check is located m characters
 * farther along the text, where m is the length of the pattern.
 *
 * Case 2:
 * If the character in the text is in the pattern, then a partial shift of the
 * pattern along the text is done to line up along the matching character and
 * the process is repeated.
 *
 * There are two shift rules:
 *
 * [The bad character rule]
 * (https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore_string-search_algorithm#The_bad_character_rule)
 *
 * [The good suffix rule]
 * (https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore_string-search_algorithm#The_good_suffix_rule)
 *
 * The shift rules are implemented as constant-time table lookups, using tables
 * generated during the preprocessing of P.
 * @author [Stoycho Kyosev](https://github.com/stoychoX)
 */

#include <cassert>   /// for assert
#include <climits>   /// for CHAR_MAX macro
#include <cstring>   /// for strlen
#include <iostream>  /// for IO operations
#include <string>    /// for std::string
#include <vector>    /// for std::vector

#define APLHABET_SIZE CHAR_MAX  ///< number of symbols in the alphabet we use

/**
 * @namespace
 * @brief String algorithms
 */
namespace strings {
/**
 * @namespace
 * @brief Functions for the [Boyer
 * Moore](https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore_string-search_algorithm)
 * algorithm implementation
 */
namespace boyer_moore {
/**
 * @brief A structure representing all the data we need to search the
 * preprocessed pattern in text.
 */
struct pattern {
    std::string pat;

    std::vector<size_t>
        bad_char;  ///< bad char table used in [Bad Character
                   ///< Heuristic](https://www.geeksforgeeks.org/boyer-moore-algorithm-for-pattern-searching/)

    std::vector<size_t>
        good_suffix;  ///< good suffix table used for [Good Suffix
                      ///< heuristic](https://www.geeksforgeeks.org/boyer-moore-algorithm-good-suffix-heuristic/?ref=rp)
};

/**
 * @brief A function that preprocess the good suffix thable
 *
 * @param str The string being preprocessed
 * @param arg The good suffix table
 * @returns void
 */
void init_good_suffix(const std::string& str, std::vector<size_t>& arg) {
    arg.resize(str.size() + 1, 0);

    // border_pos[i] - the index of the longest proper suffix of str[i..] which
    // is also a proper prefix.
    std::vector<size_t> border_pos(str.size() + 1, 0);

    size_t current_char = str.length();

    size_t border_index = str.length() + 1;

    border_pos[current_char] = border_index;

    while (current_char > 0) {
        while (border_index <= str.length() &&
               str[current_char - 1] != str[border_index - 1]) {
            if (arg[border_index] == 0) {
                arg[border_index] = border_index - current_char;
            }

            border_index = border_pos[border_index];
        }

        current_char--;
        border_index--;
        border_pos[current_char] = border_index;
    }

    size_t largest_border_index = border_pos[0];

    for (size_t i = 0; i < str.size(); i++) {
        if (arg[i] == 0) {
            arg[i] = largest_border_index;
        }

        // If we go pass the largest border we find the next one as we iterate
        if (i == largest_border_index) {
            largest_border_index = border_pos[largest_border_index];
        }
    }
}

/**
 * @brief A function that preprocess the bad char table
 *
 * @param str The string being preprocessed
 * @param arg The bad char table
 * @returns void
 */
void init_bad_char(const std::string& str, std::vector<size_t>& arg) {
    arg.resize(APLHABET_SIZE, str.length());

    for (size_t i = 0; i < str.length(); i++) {
        arg[str[i]] = str.length() - i - 1;
    }
}

/**
 * @brief A function that initializes pattern
 *
 * @param str Text used for initialization
 * @param arg Initialized structure
 * @returns void
 */
void init_pattern(const std::string& str, pattern& arg) {
    arg.pat = str;
    init_bad_char(str, arg.bad_char);
    init_good_suffix(str, arg.good_suffix);
}
/**
 * @brief A function that implements Boyer-Moore's algorithm.
 *
 * @param str Text we are seatching in.
 * @param arg pattern structure containing the preprocessed pattern
 * @return Vector of indexes of the occurrences of pattern in text
 */
std::vector<size_t> search(const std::string& str, const pattern& arg) {
    size_t index_position = arg.pat.size() - 1;
    std::vector<size_t> index_storage;

    while (index_position < str.length()) {
        size_t index_string = index_position;
        int index_pattern = static_cast<int>(arg.pat.size()) - 1;

        while (index_pattern >= 0 &&
               str[index_string] == arg.pat[index_pattern]) {
            --index_pattern;
            --index_string;
        }

        if (index_pattern < 0) {
            index_storage.push_back(index_position - arg.pat.length() + 1);
            index_position += arg.good_suffix[0];
        } else {
            index_position += std::max(arg.bad_char[str[index_string]],
                                       arg.good_suffix[index_pattern + 1]);
        }
    }

    return index_storage;
}

/**
 * @brief Check if pat is prefix of str.
 *
 * @param str pointer to some part of the input text.
 * @param pat the searched pattern.
 * @param len length of the searched pattern
 * @returns `true` if pat IS prefix of str.
 * @returns `false` if pat is NOT a prefix of str.
 */
bool is_prefix(const char* str, const char* pat, size_t len) {
    if (strlen(str) < len) {
        return false;
    }

    for (size_t i = 0; i < len; i++) {
        if (str[i] != pat[i]) {
            return false;
        }
    }

    return true;
}
}  // namespace boyer_moore
}  // namespace strings
/**
 * @brief A test case in which we search for every appearance of the word 'and'
 * @param text The text in which we search for appearance of the word 'and'
 * @returns void
 */
void and_test(const char* text) {
    strings::boyer_moore::pattern ands;
    strings::boyer_moore::init_pattern("and", ands);
    std::vector<size_t> indexes = strings::boyer_moore::search(text, ands);

    assert(indexes.size() == 2);
    assert(strings::boyer_moore::is_prefix(text + indexes[0], "and", 3));
    assert(strings::boyer_moore::is_prefix(text + indexes[1], "and", 3));
}

/**
 * @brief  A test case in which we search for every appearance of the word 'pat'
 * @param text The text in which we search for appearance of the word 'pat'
 * @returns void
 */
void pat_test(const char* text) {
    strings::boyer_moore::pattern pat;
    strings::boyer_moore::init_pattern("pat", pat);
    std::vector<size_t> indexes = strings::boyer_moore::search(text, pat);

    assert(indexes.size() == 6);

    for (const auto& currentIndex : indexes) {
        assert(strings::boyer_moore::is_prefix(text + currentIndex, "pat", 3));
    }
}
/**
 * @brief Self-test implementations
 * @returns void
 */
static void tests() {
    const char* text =
        "When pat Mr. and Mrs. pat Dursley woke up on the dull, gray  \
                            Tuesday our story starts, \
                there was nothing about pat the cloudy sky outside to pat suggest that\
                        strange and \
                    mysterious things would pat soon be happening all pat over the \
                        country.";

    and_test(text);
    pat_test(text);

    std::cout << "All tests have successfully passed!\n";
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();  // run self-test implementations
    return 0;
}

// Boyer-Moore substring search, rebuilt with the same two-heuristic design:
// the pattern is matched right-to-left against the text, and on a mismatch
// we skip forward using whichever of the bad-character rule or good-suffix
// rule advances us further. Preprocessing both tables up front keeps the
// scan itself close to sub-linear on average.

#include <cassert>
#include <climits>
#include <cstring>
#include <iostream>
#include <string>
#include <vector>

#define ALPHABET_SPAN CHAR_MAX

namespace text_search {
namespace boyer_moore_impl {

// Bundles a pattern together with its precomputed shift tables.
struct CompiledPattern {
    std::string needle;
    std::vector<size_t> badCharShift;
    std::vector<size_t> goodSuffixShift;
};

// Builds the good-suffix shift table for `needle` into `outShift`.
void buildGoodSuffixTable(const std::string& needle, std::vector<size_t>& outShift) {
    outShift.assign(needle.size() + 1, 0);

    std::vector<size_t> borderAt(needle.size() + 1, 0);

    size_t pos = needle.length();
    size_t border = needle.length() + 1;
    borderAt[pos] = border;

    while (pos > 0) {
        while (border <= needle.length() && needle[pos - 1] != needle[border - 1]) {
            if (outShift[border] == 0) {
                outShift[border] = border - pos;
            }
            border = borderAt[border];
        }
        --pos;
        --border;
        borderAt[pos] = border;
    }

    size_t widestBorder = borderAt[0];
    for (size_t i = 0; i < needle.size(); ++i) {
        if (outShift[i] == 0) {
            outShift[i] = widestBorder;
        }
        if (i == widestBorder) {
            widestBorder = borderAt[widestBorder];
        }
    }
}

// Builds the bad-character shift table for `needle` into `outShift`.
void buildBadCharTable(const std::string& needle, std::vector<size_t>& outShift) {
    outShift.assign(ALPHABET_SPAN, needle.length());
    for (size_t i = 0; i < needle.length(); ++i) {
        outShift[static_cast<unsigned char>(needle[i])] = needle.length() - i - 1;
    }
}

// Compiles a raw pattern string into a CompiledPattern with both tables.
void compile(const std::string& needle, CompiledPattern& out) {
    out.needle = needle;
    buildBadCharTable(needle, out.badCharShift);
    buildGoodSuffixTable(needle, out.goodSuffixShift);
}

// Scans `haystack` for every occurrence of the compiled pattern, returning
// the starting index of each match.
std::vector<size_t> locateAll(const std::string& haystack, const CompiledPattern& compiled) {
    size_t align = compiled.needle.size() - 1;
    std::vector<size_t> hits;

    while (align < haystack.length()) {
        size_t textCursor = align;
        int patCursor = static_cast<int>(compiled.needle.size()) - 1;

        while (patCursor >= 0 && haystack[textCursor] == compiled.needle[patCursor]) {
            --patCursor;
            --textCursor;
        }

        if (patCursor < 0) {
            hits.push_back(align - compiled.needle.length() + 1);
            align += compiled.goodSuffixShift[0];
        } else {
            align += std::max(compiled.badCharShift[static_cast<unsigned char>(haystack[textCursor])],
                               compiled.goodSuffixShift[patCursor + 1]);
        }
    }

    return hits;
}

// Checks whether `needle` (of length `len`) prefixes the C-string `text`.
bool startsWithPattern(const char* text, const char* needle, size_t len) {
    if (strlen(text) < len) {
        return false;
    }
    for (size_t i = 0; i < len; ++i) {
        if (text[i] != needle[i]) {
            return false;
        }
    }
    return true;
}

}  // namespace boyer_moore_impl
}  // namespace text_search

static void verifyWordOccurrences(const char* corpus) {
    text_search::boyer_moore_impl::CompiledPattern compiledAnd;
    text_search::boyer_moore_impl::compile("and", compiledAnd);
    std::vector<size_t> hits = text_search::boyer_moore_impl::locateAll(corpus, compiledAnd);

    assert(hits.size() == 2);
    assert(text_search::boyer_moore_impl::startsWithPattern(corpus + hits[0], "and", 3));
    assert(text_search::boyer_moore_impl::startsWithPattern(corpus + hits[1], "and", 3));
}

static void verifyPatOccurrences(const char* corpus) {
    text_search::boyer_moore_impl::CompiledPattern compiledPat;
    text_search::boyer_moore_impl::compile("pat", compiledPat);
    std::vector<size_t> hits = text_search::boyer_moore_impl::locateAll(corpus, compiledPat);

    assert(hits.size() == 6);
    for (size_t hit : hits) {
        assert(text_search::boyer_moore_impl::startsWithPattern(corpus + hit, "pat", 3));
    }
}

static void runAllChecks() {
    const char* corpus =
        "When pat Mr. and Mrs. pat Dursley woke up on the dull, gray  \
                            Tuesday our story starts, \
                there was nothing about pat the cloudy sky outside to pat suggest that\
                        strange and \
                    mysterious things would pat soon be happening all pat over the \
                        country.";

    verifyWordOccurrences(corpus);
    verifyPatOccurrences(corpus);

    std::cout << "Boyer-Moore checks all passed!\n";
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * @file
 * @brief          String pattern search - brute force
 */
#include <iostream>
#ifdef _MSC_VER
#include <string>  // use this for MS Visual C++
#else
#include <cstring>
#endif
#include <vector>

namespace string_search {
/**
 * Find a pattern in a string by comparing the pattern to every substring.
 * @param text     Any string that might contain the pattern.
 * @param pattern  String that we are searching for.
 * @return         Index where the pattern starts in the text
 * @return         -1 if the pattern was not found.
 */
int brute_force(const std::string &text, const std::string &pattern) {
    size_t pat_l = pattern.length();
    size_t txt_l = text.length();
    int index = -1;
    if (pat_l <= txt_l) {
        for (size_t i = 0; i < txt_l - pat_l + 1; i++) {
            std::string s = text.substr(i, pat_l);
            if (s == pattern) {
                index = i;
                break;
            }
        }
    }
    return index;
}
}  // namespace string_search

using string_search::brute_force;

/** set of test cases */
const std::vector<std::vector<std::string>> test_set = {
    // {text, pattern, expected output}
    {"a", "aa", "-1"},  {"a", "a", "0"},    {"ba", "b", "0"},
    {"bba", "bb", "0"}, {"bbca", "c", "2"}, {"ab", "b", "1"}};

/** Main function */
int main() {
    for (const auto &i : test_set) {
        int output = brute_force(i[0], i[1]);

        if (std::to_string(output) == i[2]) {
            std::cout << "success\n";
        } else {
            std::cout << "failure\n";
        }
    }
    return 0;
}

// Naive substring search: slide a window of the pattern's length across the
// text and directly compare each window's contents against the pattern.
// No preprocessing, O((n-m+1) * m) worst case, but trivially correct.

#include <iostream>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif
#include <vector>

namespace naive_search {

// Returns the index of the first occurrence of `needle` inside `haystack`,
// or -1 if `needle` never appears.
int locate(const std::string& haystack, const std::string& needle) {
    const size_t needleLen = needle.length();
    const size_t haystackLen = haystack.length();

    if (needleLen > haystackLen) {
        return -1;
    }

    for (size_t offset = 0; offset < haystackLen - needleLen + 1; ++offset) {
        if (haystack.substr(offset, needleLen) == needle) {
            return static_cast<int>(offset);
        }
    }

    return -1;
}

}  // namespace naive_search

using naive_search::locate;

// Each entry: {haystack, needle, expected index as string}.
const std::vector<std::vector<std::string>> checks = {
    {"a", "aa", "-1"},  {"a", "a", "0"},    {"ba", "b", "0"},
    {"bba", "bb", "0"}, {"bbca", "c", "2"}, {"ab", "b", "1"}};

int main() {
    for (const auto& entry : checks) {
        int result = locate(entry[0], entry[1]);

        if (std::to_string(result) == entry[2]) {
            std::cout << "pass\n";
        } else {
            std::cout << "fail\n";
        }
    }
    return 0;
}

/**
 * @file duval.cpp
 * @brief Implementation of [Duval's algorithm](https://en.wikipedia.org/wiki/Lyndon_word).
 *
 * @details
 * Duval's algorithm is an algorithm to find the lexicographically smallest
 * rotation of a string. It is based on the concept of Lyndon words.
 * Lyndon words are defined as the lexicographically smallest string in a
 * rotation equivalence class. A rotation equivalence class is a set of strings
 * that can be obtained by rotating a string. For example, the rotation
 * equivalence class of "abc" is {"abc", "bca", "cab"}. The lexicographically
 * smallest string in this class is "abc".
 *
 * Duval's algorithm works by iterating over the string and finding the
 * smallest rotation of the string that is a Lyndon word. This is done by
 * comparing the string with its suffixes and finding the smallest suffix that
 * is lexicographically smaller than the string. This suffix is then added to
 * the result and the process is repeated with the remaining string.
 * The algorithm has a time complexity of O(n) where n is the length of the
 * string.
 *
 * @note While Lyndon words are described in the context of strings,
 * Duval's algorithm can be used to find the lexicographically smallest cyclic
 * shift of any sequence of comparable elements.
 *
 * @author [Amine Ghoussaini](https://github.com/aminegh20)
*/

#include <array>    /// for std::array
#include <cassert>  /// for assert
#include <cstddef>  /// for std::size_t
#include <deque>    /// for std::deque
#include <iostream> /// for std::cout and std::endl
#include <string>   /// for std::string
#include <vector>   /// for std::vector

/**
 * @brief string manipulation algorithms
 * @namespace
 */
namespace string {
/**
 * @brief Find the lexicographically smallest cyclic shift of a sequence.
 * @tparam T type of the sequence
 * @param s the sequence
 * @returns the 0-indexed position of the least cyclic shift of the sequence
 */
template <typename T>
size_t duval(const T& s) {
    size_t n = s.size();
    size_t i = 0, ans = 0;
    while (i < n) {
        ans = i;
        size_t j = i + 1, k = i;
        while (j < (n + n) && s[j % n] >= s[k % n]) {
            if (s[k % n] < s[j % n]) {
                k = i;
            } else {
                k++;
            }
            j++;
        }
        while (i <= k) {
            i += j - k;
        }
    }
    return ans;
    // returns 0-indexed position of the least cyclic shift
}

}  // namespace string

/**
 * @brief self test implementation
 * returns void
 */
static void test() {
    using namespace string;

    // Test 1
    std::string s1 = "abcab";
    assert(duval(s1) == 3);

    // Test 2
    std::string s2 = "011100";
    assert(duval(s2) == 4);

    // Test 3
    std::vector<int> v = {5, 2, 1, 3, 4};
    assert(duval(v) == 2);

    // Test 4
    std::array<int, 5> a = {1, 2, 3, 4, 5};
    assert(duval(a) == 0);

    // Test 5
    std::deque<char> d = {'a', 'z', 'c', 'a', 'b'};
    assert(duval(d) == 3);

    // Test 6
    std::string s3;
    assert(duval(s3) == 0);

    // Test 7
    std::vector<int> v2 = {5, 2, 1, 3, -4};
    assert(duval(v2) == 4);

    std::cout << "All tests passed!" << std::endl;
}

/**
 * @brief main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self test implementations
    return 0;
}

// Duval's algorithm locates the starting index of the lexicographically
// smallest rotation of a sequence, leaning on the theory of Lyndon words.
// It scans the (conceptually doubled) sequence once, tracking a candidate
// start, a comparison cursor, and a "last known smaller" marker, and runs
// in linear time regardless of the element type as long as it's orderable.

#include <array>
#include <cassert>
#include <cstddef>
#include <deque>
#include <iostream>
#include <string>
#include <vector>

namespace text_rotation {

// Finds the 0-indexed offset of the smallest cyclic rotation of `seq`.
template <typename Sequence>
size_t smallestRotationOffset(const Sequence& seq) {
    const size_t length = seq.size();
    size_t bestStart = 0;
    size_t scan = 0;

    while (scan < length) {
        bestStart = scan;
        size_t ahead = scan + 1;
        size_t matched = scan;

        while (ahead < 2 * length && seq[ahead % length] >= seq[matched % length]) {
            if (seq[matched % length] < seq[ahead % length]) {
                matched = scan;
            } else {
                ++matched;
            }
            ++ahead;
        }

        while (scan <= matched) {
            scan += ahead - matched;
        }
    }

    return bestStart;
}

}  // namespace text_rotation

static void runAllChecks() {
    using text_rotation::smallestRotationOffset;

    std::string caseA = "abcab";
    assert(smallestRotationOffset(caseA) == 3);

    std::string caseB = "011100";
    assert(smallestRotationOffset(caseB) == 4);

    std::vector<int> caseC = {5, 2, 1, 3, 4};
    assert(smallestRotationOffset(caseC) == 2);

    std::array<int, 5> caseD = {1, 2, 3, 4, 5};
    assert(smallestRotationOffset(caseD) == 0);

    std::deque<char> caseE = {'a', 'z', 'c', 'a', 'b'};
    assert(smallestRotationOffset(caseE) == 3);

    std::string caseF;
    assert(smallestRotationOffset(caseF) == 0);

    std::vector<int> caseG = {5, 2, 1, 3, -4};
    assert(smallestRotationOffset(caseG) == 4);

    std::cout << "All Duval checks passed!" << std::endl;
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * @file
 * @brief Horspool's algorithm that finds if a string contains a substring (https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore%E2%80%93Horspool_algorithm)
 * @author [Harry Kontakis](https://github.com/ckontakis)
 */

#include <iostream>
#include <unordered_map>
#include <cassert>

/**
 * @namespace strings
 * @brief Algorithms with strings
 */
namespace strings {
/**
 * @namespace horspool
 * @brief Functions for [Horspool's](https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore%E2%80%93Horspool_algorithm) algorithm
 */
namespace horspool {
/**
 * A function that finds the shift table of the given prototype string that we need in Horpool's algorithm.
 * @param prototype is the substring that we use to find shift table
 * @return Shift Table of Horspool's algorithm
 */
std::unordered_map<char, int> findShiftTable(const std::string &prototype) {
    std::unordered_map<char, int>
        shiftTable;  // A HashMap for shift table that has characters for keys and integers for values

    for (int i = 0; i < prototype.size();
         i++) {  // Checking all characters of prototype string
        if (shiftTable.find(prototype[i]) ==
            shiftTable.end()) {  // If character does not exist in HashMap
            if (i != prototype.size() - 1) {
                shiftTable.insert(std::make_pair(
                    prototype[i], prototype.size() - i -
                                      1));  // Insert the character as key and the size of prototype string - index of character - 1 as value
            } else {
                shiftTable.insert(std::make_pair(
                    prototype[i],
                    prototype.size()));  // Insert the character as key and the size of prototype string as value
            }
        } else {
            if (i != prototype.size() - 1) {
                shiftTable[prototype[i]] = prototype.size() - i - 1;
            }
        }
    }
    return shiftTable;
}

/**
 * A function that implements Horspool's algorithm.
 * @param text is the string that we are searching if there is a substring
 * @param prototype is the substring that we are searching in text
 * @returns true if text string contains prototype string
 * @returns false if text string does not contain prototype string
 */
bool horspool(const std::string &text, const std::string &prototype) {
    std::unordered_map<char, int> shiftTable = findShiftTable(
        prototype);  // Initialise shift table calling findShiftTable function

    int i = static_cast<int>(
        prototype.size() -
        1);  // Index that we shift in text to find the substring
    while (i < text.size()) {
        int j = i, k = 0;
        bool flag = true;

        for (int z = static_cast<int>(prototype.size() - 1); z >= 0 && flag;
             z--) {  // Checking if all characters of substring are equal with all characters of string
            if (text[j] == prototype[z]) {
                k++;
                j--;
            } else {
                flag = false;  // If two characters are not equal set flag to false and break from loop
            }
        }

        if (k ==
            prototype.size()) {  // If all characters match then return true
            return true;
        } else {
            if (shiftTable.find(text[i]) != shiftTable.end()) {
                i += shiftTable[text[i]];  // If shift table contains the character then shift index as many steps as value
            } else {
                i += prototype.size();  // If character does not exist in shift table then shift index as many steps as size of prototype string
            }
        }
    }
    return false;
}
} // namespace horspool
} // namespace strings

/**
 * @brief Function with test cases for Horspool's algorithm
 * @returns void
 */
static void test(){
    assert(strings::horspool::horspool("Hello World","World") == true);
    assert(strings::horspool::horspool("Hello World"," World") == true);
    assert(strings::horspool::horspool("Hello World","ello") == true);
    assert(strings::horspool::horspool("Hello World","rld") == true);
    assert(strings::horspool::horspool("Hello","Helo") == false);
    assert(strings::horspool::horspool("c++_algorithms","c++_algorithms") == true);
    assert(strings::horspool::horspool("c++_algorithms","c++_") == true);
    assert(strings::horspool::horspool("Hello","Hello World") == false);
    assert(strings::horspool::horspool("c++_algorithms","") == false);
    assert(strings::horspool::horspool("c++","c") == true);
    assert(strings::horspool::horspool("3458934793","4793") == true);
    assert(strings::horspool::horspool("3458934793","123") == false);
}

/**
 * @brief Main Function that calls test function
 * @returns 0 on exit
 */
int main(){
    test();
    return 0;
}

// Horspool's algorithm: a simplified relative of Boyer-Moore that only
// uses a bad-character shift table, keyed on the character that aligns
// with the *last* position of the current window. Comparisons still
// proceed from the end of the pattern backward, but the skip logic is
// cheaper to precompute than full Boyer-Moore.

#include <iostream>
#include <unordered_map>
#include <cassert>

namespace strings {
namespace horspool {

// Builds the shift table for `needle`: for each character (excluding the
// final one), records how far we can jump when that character is seen at
// the alignment's rightmost slot.
std::unordered_map<char, int> buildShiftTable(const std::string& needle) {
    std::unordered_map<char, int> shifts;

    for (size_t i = 0; i < needle.size(); ++i) {
        const bool isLast = (i == needle.size() - 1);
        const int shiftValue = isLast ? static_cast<int>(needle.size())
                                       : static_cast<int>(needle.size() - i - 1);

        if (isLast) {
            if (shifts.find(needle[i]) == shifts.end()) {
                shifts.insert({needle[i], shiftValue});
            }
        } else {
            shifts[needle[i]] = shiftValue;
        }
    }

    return shifts;
}

// Reports whether `needle` occurs anywhere inside `haystack`.
bool contains(const std::string& haystack, const std::string& needle) {
    std::unordered_map<char, int> shifts = buildShiftTable(needle);

    int windowEnd = static_cast<int>(needle.size() - 1);

    while (windowEnd < static_cast<int>(haystack.size())) {
        int hCursor = windowEnd;
        int matched = 0;
        bool stillMatching = true;

        for (int nCursor = static_cast<int>(needle.size() - 1); nCursor >= 0 && stillMatching; --nCursor) {
            if (haystack[hCursor] == needle[nCursor]) {
                ++matched;
                --hCursor;
            } else {
                stillMatching = false;
            }
        }

        if (static_cast<size_t>(matched) == needle.size()) {
            return true;
        }

        auto found = shifts.find(haystack[windowEnd]);
        if (found != shifts.end()) {
            windowEnd += found->second;
        } else {
            windowEnd += static_cast<int>(needle.size());
        }
    }

    return false;
}

}  // namespace horspool
}  // namespace strings

static void runAllChecks() {
    assert(strings::horspool::contains("Hello World", "World") == true);
    assert(strings::horspool::contains("Hello World", " World") == true);
    assert(strings::horspool::contains("Hello World", "ello") == true);
    assert(strings::horspool::contains("Hello World", "rld") == true);
    assert(strings::horspool::contains("Hello", "Helo") == false);
    assert(strings::horspool::contains("c++_algorithms", "c++_algorithms") == true);
    assert(strings::horspool::contains("c++_algorithms", "c++_") == true);
    assert(strings::horspool::contains("Hello", "Hello World") == false);
    assert(strings::horspool::contains("c++_algorithms", "") == false);
    assert(strings::horspool::contains("c++", "c") == true);
    assert(strings::horspool::contains("3458934793", "4793") == true);
    assert(strings::horspool::contains("3458934793", "123") == false);
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * @file
 * @brief The [Knuth-Morris-Pratt
 * Algorithm](https://en.wikipedia.org/wiki/Knuth–Morris–Pratt_algorithm) for
 * finding a pattern within a piece of text with complexity O(n + m)
 * @details
 * 1. Preprocess pattern to identify any suffixes that are identical to
 * prefixes. This tells us where to continue from if we get a mismatch between a
 * character in our pattern and the text.
 * 2. Step through the text one character at a time and compare it to a
 * character in the pattern updating our location within the pattern if
 * necessary
 * @author [Yancey](https://github.com/Yancey2023)
 */

#include <cassert>   /// for assert
#include <iostream>  /// for IO operations
#include <string>    /// for std::string
#include <vector>    /// for std::vector

/**
 * @namespace string_search
 * @brief String search algorithms
 */
namespace string_search {
/**
 * @brief Generate the partial match table aka failure function for a pattern to
 * search.
 * @param pattern text for which to create the partial match table
 * @returns the partial match table as a vector array
 */
std::vector<size_t> getFailureArray(const std::string &pattern) {
    size_t pattern_length = pattern.size();
    std::vector<size_t> failure(pattern_length + 1);
    failure[0] = std::string::npos;
    size_t j = std::string::npos;
    for (int i = 0; i < pattern_length; i++) {
        while (j != std::string::npos && pattern[j] != pattern[i]) {
            j = failure[j];
        }
        failure[i + 1] = ++j;
    }
    return failure;
}

/**
 * @brief KMP algorithm to find a pattern in a text
 * @param pattern string pattern to search
 * @param text text in which to search
 * @returns the starting index of the pattern if found
 * @returns `std::string::npos` if not found
 */
size_t kmp(const std::string &pattern, const std::string &text) {
    if (pattern.empty()) {
        return 0;
    }
    std::vector<size_t> failure = getFailureArray(pattern);
    size_t text_length = text.size();
    size_t pattern_length = pattern.size();
    size_t k = 0;
    for (size_t j = 0; j < text_length; j++) {
        while (k != std::string::npos && pattern[k] != text[j]) {
            k = failure[k];
        }
        if (++k == pattern_length) {
            return j - k + 1;
        }
    }
    return std::string::npos;
}
}  // namespace string_search

using string_search::kmp;

/**
 * @brief self-test implementations
 * @returns void
 */
static void tests() {
    assert(kmp("abc1abc12l", "alskfjaldsabc1abc1abc12k2") == std::string::npos);
    assert(kmp("bca", "abcabc") == 1);
    assert(kmp("World", "helloWorld") == 5);
    assert(kmp("c++", "his_is_c++") == 7);
    assert(kmp("happy", "happy_coding") == 0);
    assert(kmp("", "pattern is empty") == 0);

    // this lets the user know that the tests have passed
    std::cout << "All KMP algorithm tests have successfully passed!\n";
}

/*
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    tests();
    return 0;
}

// KMP substring search reimplemented: first build a failure/prefix-function
// table that says, for each prefix of the pattern, how long its longest
// proper prefix-that-is-also-a-suffix is. Then scan the text once, using
// that table to avoid ever re-examining a text character after a mismatch.
// Overall O(n + m).

#include <cassert>
#include <iostream>
#include <string>
#include <vector>

namespace pattern_matching {

// Computes the KMP failure table for `needle`. failure[i] tells us where
// to resume matching within the pattern after a mismatch at position i.
std::vector<size_t> buildFailureTable(const std::string& needle) {
    const size_t m = needle.size();
    std::vector<size_t> failure(m + 1);
    failure[0] = std::string::npos;

    size_t candidate = std::string::npos;
    for (size_t i = 0; i < m; ++i) {
        while (candidate != std::string::npos && needle[candidate] != needle[i]) {
            candidate = failure[candidate];
        }
        failure[i + 1] = ++candidate;
    }
    return failure;
}

// Finds the first occurrence of `needle` in `haystack`.
// Returns the starting index, or std::string::npos if absent.
size_t findFirst(const std::string& needle, const std::string& haystack) {
    if (needle.empty()) {
        return 0;
    }

    std::vector<size_t> failure = buildFailureTable(needle);
    const size_t n = haystack.size();
    const size_t m = needle.size();

    size_t matchLen = 0;
    for (size_t i = 0; i < n; ++i) {
        while (matchLen != std::string::npos && needle[matchLen] != haystack[i]) {
            matchLen = failure[matchLen];
        }
        if (++matchLen == m) {
            return i - matchLen + 1;
        }
    }
    return std::string::npos;
}

}  // namespace pattern_matching

using pattern_matching::findFirst;

static void runAllChecks() {
    assert(findFirst("abc1abc12l", "alskfjaldsabc1abc1abc12k2") == std::string::npos);
    assert(findFirst("bca", "abcabc") == 1);
    assert(findFirst("World", "helloWorld") == 5);
    assert(findFirst("c++", "his_is_c++") == 7);
    assert(findFirst("happy", "happy_coding") == 0);
    assert(findFirst("", "pattern is empty") == 0);

    std::cout << "All KMP checks have completed successfully!\n";
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * @file
 * @brief Implementation of [Manacher's
 * Algorithm](https://en.wikipedia.org/wiki/Longest_palindromic_substring)
 * @details
 * Manacher's Algorithm is used to find the longest palindromic substring within
 * a string in O(n) time. It exploits the property of a palindrome that its
 * first half is symmetric to the last half, and thus if the first half is a
 * palindrome, then last half is also a palindrome.
 * @author [Riti Kumari](https://github.com/riti2409)
 */

#include <cassert>   /// for assert
#include <cstdint>
#include <iostream>  /// for IO operations
#include <vector>    /// for std::vector STL
#ifdef _MSC_VER
#include <string>  /// for string (required for MS Visual C++)
#else
#include <cstring>  /// for string
#endif

/**
 * @namespace strings
 * @brief Algorithms with strings
 */
namespace strings {
/**
 * @namespace manacher
 * @brief Functions for [Manacher's
 * Algorithm](https://en.wikipedia.org/wiki/Longest_palindromic_substring)
 * implementation
 */
namespace manacher {
/**
 * @brief A function that implements Manacher's algorithm
 * @param prototype is the string where algorithm finds a palindromic substring.
 * This string can contain any character except `@` `#` `&`
 * @returns the largest palindromic substring
 */
std::string manacher(const std::string &prototype) {
    if (prototype.size() > 0) {
        // stuffing characters between the input string to handle cases with
        // even length palindrome
        std::string stuffed_string = "";
        for (auto str : prototype) {
            stuffed_string += str;
            stuffed_string += "#";
        }
        stuffed_string = "@#" + stuffed_string + "&";

        std::vector<uint64_t> palindrome_max_half_length(
            stuffed_string.size(),
            0);  // this array will consist of largest possible half length of
                 // palindrome centered at index (say i with respect to the
                 // stuffed string). This value will be lower bound of half
                 // length since single character is a palindrome in itself.

        uint64_t bigger_center =
            0;  // this is the index of the center of palindromic
                // substring which would be considered as the larger
                // palindrome, having symmetric halves

        uint64_t right = 0;  // this is the maximum length of the palindrome
                             // from 'bigger_center' to the rightmost end

        // i is considered as center lying within one half of the palindrone
        // which is centered at 'bigger_center'
        for (uint64_t i = 1; i < stuffed_string.size() - 1; i++) {
            if (i < right) {  // when i is before right end, considering
                              // 'bigger_center' as center of palindrome
                uint64_t opposite_to_i =
                    2 * bigger_center -
                    i;  // this is the opposite end of string, if
                        // centered at center, and having one end as i

                // finding the minimum possible half length among
                // the palindrome on having center at opposite end,
                // and the string between i and right end,
                // considering 'bigger_center' as center of palindrome
                palindrome_max_half_length[i] = std::min(
                    palindrome_max_half_length[opposite_to_i], right - i);
            }

            // expanding the palindrome across the maximum stored length in the
            // array, centered at i
            while (stuffed_string[i + (palindrome_max_half_length[i] + 1)] ==
                   stuffed_string[i - (palindrome_max_half_length[i] + 1)]) {
                palindrome_max_half_length[i]++;
            }

            // if palindrome centered at i exceeds the rightmost end of
            // palindrome centered at 'bigger_center', then i will be made the
            // 'bigger_center' and right value will also be updated with respect
            // to center i
            if (i + palindrome_max_half_length[i] > right) {
                bigger_center = i;
                right = i + palindrome_max_half_length[i];
            }
        }

        // now extracting the first largest palindrome
        uint64_t half_length = 0;   // half length of the largest palindrome
        uint64_t center_index = 0;  // index of center of the largest palindrome

        for (uint64_t i = 1; i < stuffed_string.size() - 1; i++) {
            if (palindrome_max_half_length[i] > half_length) {
                half_length = palindrome_max_half_length[i];
                center_index = i;
            }
        }

        std::string palindromic_substring =
            "";  // contains the resulting largest palindrome

        if (half_length > 0) {
            // extra information: when '#' is the center, then palindromic
            // substring will have even length, else palindromic substring will
            // have odd length

            uint64_t start =
                center_index - half_length +
                1;  // index of first character of palindromic substring
            uint64_t end =
                center_index + half_length -
                1;  // index of last character of palindromic substring
            for (uint64_t index = start; index <= end; index += 2) {
                palindromic_substring += stuffed_string[index];
            }
        } else {
            // if length = 0, then there does not exist any palindrome of length
            // > 1 so we can assign any character of length 1 from string as the
            // palindromic substring
            palindromic_substring = prototype[0];
        }
        return palindromic_substring;

    } else {
        // handling case when string is empty
        return "";
    }
}

}  // namespace manacher
}  // namespace strings

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    assert(strings::manacher::manacher("") == "");
    assert(strings::manacher::manacher("abababc") == "ababa");
    assert(strings::manacher::manacher("cbaabd") == "baab");
    assert(strings::manacher::manacher("DedzefDeD") == "DeD");
    assert(strings::manacher::manacher("XZYYXXYZXX") == "YXXY");
    assert(strings::manacher::manacher("1sm222m10abc") == "m222m");
    assert(strings::manacher::manacher("798989591") == "98989");
    assert(strings::manacher::manacher("xacdedcax") == "xacdedcax");
    assert(strings::manacher::manacher("xaccax") == "xaccax");
    assert(strings::manacher::manacher("a") == "a");
    assert(strings::manacher::manacher("xy") == "x");
    assert(strings::manacher::manacher("abced") == "a");

    std::cout << "All tests have passed!" << std::endl;
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

// Manacher's algorithm finds the longest palindromic substring in linear
// time. The trick: insert separator characters between (and around) every
// original character so odd/even-length palindromes are handled uniformly,
// then expand palindrome radii while reusing previously computed radii via
// mirroring around the current rightmost-reaching palindrome's center.

#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif

namespace strings {
namespace manacher {

// Returns the longest palindromic substring of `source`.
std::string longestPalindrome(const std::string& source) {
    if (source.empty()) {
        return "";
    }

    // Build a transformed string with separators so every palindrome,
    // odd or even length, has a well-defined single center.
    std::string transformed = "";
    for (char c : source) {
        transformed += c;
        transformed += '#';
    }
    transformed = "@#" + transformed + "&";

    std::vector<uint64_t> radius(transformed.size(), 0);
    uint64_t axis = 0;
    uint64_t frontier = 0;

    for (uint64_t i = 1; i < transformed.size() - 1; ++i) {
        if (i < frontier) {
            uint64_t mirrored = 2 * axis - i;
            radius[i] = std::min(radius[mirrored], frontier - i);
        }

        while (transformed[i + (radius[i] + 1)] == transformed[i - (radius[i] + 1)]) {
            ++radius[i];
        }

        if (i + radius[i] > frontier) {
            axis = i;
            frontier = i + radius[i];
        }
    }

    uint64_t bestRadius = 0;
    uint64_t bestCenter = 0;
    for (uint64_t i = 1; i < transformed.size() - 1; ++i) {
        if (radius[i] > bestRadius) {
            bestRadius = radius[i];
            bestCenter = i;
        }
    }

    if (bestRadius == 0) {
        return std::string(1, source[0]);
    }

    std::string best = "";
    uint64_t from = bestCenter - bestRadius + 1;
    uint64_t to = bestCenter + bestRadius - 1;
    for (uint64_t idx = from; idx <= to; idx += 2) {
        best += transformed[idx];
    }
    return best;
}

}  // namespace manacher
}  // namespace strings

static void runAllChecks() {
    assert(strings::manacher::longestPalindrome("") == "");
    assert(strings::manacher::longestPalindrome("abababc") == "ababa");
    assert(strings::manacher::longestPalindrome("cbaabd") == "baab");
    assert(strings::manacher::longestPalindrome("DedzefDeD") == "DeD");
    assert(strings::manacher::longestPalindrome("XZYYXXYZXX") == "YXXY");
    assert(strings::manacher::longestPalindrome("1sm222m10abc") == "m222m");
    assert(strings::manacher::longestPalindrome("798989591") == "98989");
    assert(strings::manacher::longestPalindrome("xacdedcax") == "xacdedcax");
    assert(strings::manacher::longestPalindrome("xaccax") == "xaccax");
    assert(strings::manacher::longestPalindrome("a") == "a");
    assert(strings::manacher::longestPalindrome("xy") == "x");
    assert(strings::manacher::longestPalindrome("abced") == "a");

    std::cout << "All Manacher checks passed!" << std::endl;
}

int main() {
    runAllChecks();
    return 0;
}

/**
 * \file
 * \brief The [Rabin-Karp
 * Algorithm](https://en.wikipedia.org/wiki/Rabin–Karp_algorithm) for finding a
 * pattern within a piece of text with complexity O(n + m)
 */
#include <cassert>
#include <cmath>
#include <iostream>
#ifdef _MSC_VER
#include <string>  // use this for MS Visucal C++
#else
#include <cstring>
#endif

#define PRIME 5  ///< Prime modulus for hash functions

namespace string_search {
/**
 * convert a string to an intger - called as hashing function
 * \param[in] s source of string to hash
 * \param[in] n length of substring to hash
 * \returns hash integer
 */
int64_t create_hash(const std::string& s, int n) {
    int64_t result = 0;
    for (int i = 0; i < n; ++i) {
        result += (int64_t)(s[i] * (int64_t)pow(PRIME, i));
    }
    return result;
}

/**
 * re-hash a string using known existing hash
 * \param[in] s source of string to hash
 * \param[in] old_index previous index of string
 * \param[in] new_index new index of string
 * \param[in] old_hash previous hash of substring
 * \param[in] patLength length of substring to hash
 * \returns new hash integer
 */
int64_t recalculate_hash(const std::string& s, int old_index, int new_index,
                         int64_t old_hash, int patLength) {
    int64_t new_hash = old_hash - s[old_index];
    new_hash /= PRIME;
    new_hash += (int64_t)(s[new_index] * (int64_t)pow(PRIME, patLength - 1));
    return new_hash;
}

/**
 * compare if two sub-strings are equal
 * \param[in] str1 string pattern to search
 * \param[in] str2 text in which to search
 * \param[in] start1,end1 start and end indices for substring in str1
 * \param[in] start2,end2 start and end indices for substring in str2
 * \returns `true` if pattern was found
 * \returns `false` if pattern was not found
 * @note can this be replaced by std::string::compare?
 */
bool check_if_equal(const std::string& str1, const std::string& str2,
                    int start1, int end1, int start2, int end2) {
    if (end1 - start1 != end2 - start2) {
        return false;
    }
    while (start1 <= end1 && start2 <= end2) {
        if (str1[start1] != str2[start2]) {
            return false;
        }
        start1++;
        start2++;
    }
    return true;
}

/**
 *  Perform string pattern search using Rabin-Karp algorithm
 *  @param[in] str string to search in
 *  @param[in] pat pattern to search for
 *  @return index of first occurrence of pattern
 *  @return -1 if pattern not found
 */

int rabin_karp(const std::string& str, const std::string& pat) {
    int64_t pat_hash = create_hash(pat, pat.size());
    int64_t str_hash = create_hash(str, pat.size());
    for (int i = 0; i <= str.size() - pat.size(); ++i) {
        if (pat_hash == str_hash &&
            check_if_equal(str, pat, i, i + pat.size() - 1, 0,
                           pat.size() - 1)) {
            return i;
        }
        if (i < str.size() - pat.size()) {
            str_hash =
                recalculate_hash(str, i, i + pat.size(), str_hash, pat.size());
        }
    }
    return -1;  // return -1 if given pattern not found
}

}  // namespace string_search

using string_search::rabin_karp;

/** Main function */
int main(void) {
    assert(rabin_karp("helloWorld", "world") == -1);
    assert(rabin_karp("helloWorld", "World") == 5);
    assert(rabin_karp("this_is_c++", "c++") == 8);
    assert(rabin_karp("happy_coding", "happy") == 0);
    return 0;
}

// Rabin-Karp substring search: hash the pattern and each equal-length
// window of the text, only doing a character-by-character check when the
// hashes agree. Hashes are recomputed incrementally (rolling hash) so each
// shift of the window costs O(1) amortized.

#include <cassert>
#include <cmath>
#include <iostream>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif

#define HASH_BASE 5

namespace pattern_matching {

// Computes a polynomial hash of the first `len` characters of `text`.
int64_t hashPrefix(const std::string& text, int len) {
    int64_t total = 0;
    for (int i = 0; i < len; ++i) {
        total += static_cast<int64_t>(text[i]) * static_cast<int64_t>(pow(HASH_BASE, i));
    }
    return total;
}

// Rolls the hash forward: drops the character leaving the window at
// `leftOut`, and adds the character entering at `rightIn`.
int64_t rollHash(const std::string& text, int leftOut, int rightIn,
                  int64_t previousHash, int windowLen) {
    int64_t updated = previousHash - text[leftOut];
    updated /= HASH_BASE;
    updated += static_cast<int64_t>(text[rightIn]) * static_cast<int64_t>(pow(HASH_BASE, windowLen - 1));
    return updated;
}

// Compares two equal-length substrings character by character.
bool rangesMatch(const std::string& a, const std::string& b,
                  int aStart, int aEnd, int bStart, int bEnd) {
    if (aEnd - aStart != bEnd - bStart) {
        return false;
    }
    while (aStart <= aEnd && bStart <= bEnd) {
        if (a[aStart] != b[bStart]) {
            return false;
        }
        ++aStart;
        ++bStart;
    }
    return true;
}

// Searches for `needle` in `haystack` using rolling hashes.
// Returns the index of the first match, or -1 if not found.
int search(const std::string& haystack, const std::string& needle) {
    int64_t needleHash = hashPrefix(needle, needle.size());
    int64_t windowHash = hashPrefix(haystack, needle.size());

    for (int start = 0; start <= static_cast<int>(haystack.size() - needle.size()); ++start) {
        if (needleHash == windowHash &&
            rangesMatch(haystack, needle, start, start + needle.size() - 1, 0, needle.size() - 1)) {
            return start;
        }
        if (start < static_cast<int>(haystack.size() - needle.size())) {
            windowHash = rollHash(haystack, start, start + needle.size(), windowHash, needle.size());
        }
    }
    return -1;
}

}  // namespace pattern_matching

using pattern_matching::search;

int main(void) {
    assert(search("helloWorld", "world") == -1);
    assert(search("helloWorld", "World") == 5);
    assert(search("this_is_c++", "c++") == 8);
    assert(search("happy_coding", "happy") == 0);
    return 0;
}

/**
 * @file
 * @brief The [Z function](https://cp-algorithms.com/string/z-function.html) for
 * finding occurences of a pattern within a piece of text with time and space
 * complexity O(n + m)
 * @details
 * 1. The Z-function for a string is an array of length n where the
 * i-th element is equal to the greatest number of characters starting
 * from the position i that coincide with the first characters of s.
 * 2. E.g.: string: ababb then z[2]=2 as s[2]=s[0] and s[3]=s[1] and s[4]!=s[2]
 * @author [Ritika Gupta](https://github.com/RitikaGupta8734)
 */

#include <cstdint>
#include <iostream>  /// for IO operations
#ifdef _MSC_VER
#include <string>  /// for string (use this for MS Visual C++)
#else
#include <cstring>  /// for string
#endif
#include <cassert>  /// for assert
#include <vector>   /// for std::vector

/**
 * @brief Generate the Z-function for the inputted string.
 * \param[in] pattern text on which to apply the Z-function
 * \returns the Z-function output as a vector array
 */
std::vector<uint64_t> Z_function(const std::string &pattern) {
    uint64_t pattern_length = pattern.size();
    std::vector<uint64_t> z(pattern_length, 0);

    for (uint64_t i = 1, l = 0, r = 0; i < pattern_length; i++) {
        if (i <= r) {
            z[i] = std::min(r - i + 1, z[i - l]);
        }
        while (i + z[i] < pattern_length &&
               pattern[z[i]] == pattern[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] - 1 > r) {
            r = i + z[i] - 1;
        }
    }
    return z;
}

/**
 * @brief Using Z_function to find a pattern in a text
 * \param[in] pattern string pattern to search
 * \param[in] text text in which to search
 * \returns a vector of starting indexes where pattern is found in the text
 */
std::vector<uint64_t> find_pat_in_text(const std::string &pattern,
                                       const std::string &text) {
    uint64_t text_length = text.size(), pattern_length = pattern.size();
    std::vector<uint64_t> z = Z_function(pattern + '#' + text);
    std::vector<uint64_t> matching_indexes;

    for (uint64_t i = 0; i < text_length; i++) {
        if (z[i + pattern_length + 1] == pattern_length) {
            matching_indexes.push_back(i);
        }
    }
    return matching_indexes;
}

/**
 * @brief Self-test implementations
 * @returns void
 */
static void test() {
    // usual case
    std::string text1 = "alskfjaldsabc1abc1abcbksbcdnsdabcabc";
    std::string pattern1 = "abc";

    // matching_indexes1 gets the indexes where pattern1 exists in text1
    std::vector<uint64_t> matching_indexes1 = find_pat_in_text(pattern1, text1);
    assert((matching_indexes1 == std::vector<uint64_t>{10, 14, 18, 30, 33}));

    // corner case
    std::string text2 = "greengrass";
    std::string pattern2 = "abc";

    // matching_indexes2 gets the indexes where pattern2 exists in text2
    std::vector<uint64_t> matching_indexes2 = find_pat_in_text(pattern2, text2);
    assert((matching_indexes2 == std::vector<uint64_t>{}));

    // corner case - empty text
    std::string text3 = "";
    std::string pattern3 = "abc";

    // matching_indexes3 gets the indexes where pattern3 exists in text3
    std::vector<uint64_t> matching_indexes3 = find_pat_in_text(pattern3, text3);
    assert((matching_indexes3 == std::vector<uint64_t>{}));

    // corner case - empty pattern
    std::string text4 = "redsand";
    std::string pattern4 = "";

    // matching_indexes4 gets the indexes where pattern4 exists in text4
    std::vector<uint64_t> matching_indexes4 = find_pat_in_text(pattern4, text4);
    assert((matching_indexes4 == std::vector<uint64_t>{0, 1, 2, 3, 4, 5, 6}));
}

/**
 * @brief Main function
 * @returns 0 on exit
 */
int main() {
    test();  // run self-test implementations
    return 0;
}

// Z-function based pattern search. z[i] is defined as the length of the
// longest common prefix between the whole string and the suffix starting
// at i. Computing it in O(n) lets us find every occurrence of a pattern in
// a text by evaluating the Z-function of pattern + separator + text and
// looking for positions where z equals the pattern's length.

#include <cstdint>
#include <iostream>
#ifdef _MSC_VER
#include <string>
#else
#include <cstring>
#endif
#include <cassert>
#include <vector>

namespace zfunc {

// Builds the Z-array for `s`: zArr[i] = length of the longest prefix of s
// that also matches the substring starting at index i.
std::vector<uint64_t> compute(const std::string& s) {
    const uint64_t n = s.size();
    std::vector<uint64_t> zArr(n, 0);

    uint64_t segStart = 0, segEnd = 0;
    for (uint64_t i = 1; i < n; ++i) {
        if (i <= segEnd) {
            zArr[i] = std::min(segEnd - i + 1, zArr[i - segStart]);
        }
        while (i + zArr[i] < n && s[zArr[i]] == s[i + zArr[i]]) {
            ++zArr[i];
        }
        if (i + zArr[i] - 1 > segEnd) {
            segStart = i;
            segEnd = i + zArr[i] - 1;
        }
    }
    return zArr;
}

// Locates every starting index in `text` where `needle` occurs, using the
// Z-function of the concatenation needle + '#' + text.
std::vector<uint64_t> locateAll(const std::string& needle, const std::string& text) {
    const uint64_t textLen = text.size();
    const uint64_t needleLen = needle.size();
    std::vector<uint64_t> combinedZ = compute(needle + '#' + text);

    std::vector<uint64_t> hits;
    for (uint64_t i = 0; i < textLen; ++i) {
        if (combinedZ[i + needleLen + 1] == needleLen) {
            hits.push_back(i);
        }
    }
    return hits;
}

}  // namespace zfunc

static void runAllChecks() {
    // typical scenario with several matches
    std::string textA = "alskfjaldsabc1abc1abcbksbcdnsdabcabc";
    std::string needleA = "abc";
    std::vector<uint64_t> hitsA = zfunc::locateAll(needleA, textA);
    assert((hitsA == std::vector<uint64_t>{10, 14, 18, 30, 33}));

    // no matches at all
    std::string textB = "greengrass";
    std::string needleB = "abc";
    std::vector<uint64_t> hitsB = zfunc::locateAll(needleB, textB);
    assert((hitsB == std::vector<uint64_t>{}));

    // empty text
    std::string textC = "";
    std::string needleC = "abc";
    std::vector<uint64_t> hitsC = zfunc::locateAll(needleC, textC);
    assert((hitsC == std::vector<uint64_t>{}));

    // empty pattern matches everywhere
    std::string textD = "redsand";
    std::string needleD = "";
    std::vector<uint64_t> hitsD = zfunc::locateAll(needleD, textD);
    assert((hitsD == std::vector<uint64_t>{0, 1, 2, 3, 4, 5, 6}));
}

int main() {
    runAllChecks();
    return 0;
}
